export function hasTypesafeCredentials(env = process.env) {
  return typeof env?.TYPESAFE_API_KEY === "string" && env.TYPESAFE_API_KEY.trim().length > 0;
}

export function createTypesafeEngine({ policy }) {
  const engine = {
    id: DECISION_ENGINE_ID,
    model: PINNED_JEV_MODEL,
    async evaluate(request) {
      if (!hasTypesafeCredentials()) throw decisionError(DECISION_ERROR_CODES.AUTH_REQUIRED, "TYPESAFE_API_KEY is required for a semantic decision.");
      const started = Date.now();
      try {
        const client = createTypesafeClient(policy);
        const raw = await client.systemOne({ state: request.state, questions: sdkQuestions(request.questionSet), model: PINNED_JEV_MODEL }, { timeout: policy.requestTimeoutMs, retry: { maxRetries: policy.maxRetries } });
        return { ...normalizeTypesafeResult(raw, request.questionSet), latencyMs: Date.now() - started };
      } catch (error) {
        throw safeDecisionError(error);
      }
    },
    async health() {
      if (!hasTypesafeCredentials()) return { status: "missing", engine: DECISION_ENGINE_ID, model: PINNED_JEV_MODEL };
      const started = Date.now();
      try {
        const client = createTypesafeClient(policy);
        const raw = await client.systemOne({ state: { healthCheck: true }, questions: { healthy: noul("Is this bounded health-check request well-formed?", { yes: "The request is well-formed", no: "The request is not well-formed" }) }, model: PINNED_JEV_MODEL }, { timeout: policy.requestTimeoutMs, retry: { maxRetries: 0 } });
        if (raw.model !== PINNED_JEV_MODEL) throw decisionError(DECISION_ERROR_CODES.MODEL_UNSUPPORTED, "The semantic decision service returned an unsupported model.");
        return { status: "healthy", engine: DECISION_ENGINE_ID, model: PINNED_JEV_MODEL, latencyMs: Date.now() - started, usage: raw.usage ?? null };
      } catch (error) {
        const normalized = safeDecisionError(error);
        return {
          status: normalized.code === DECISION_ERROR_CODES.RATE_LIMITED ? "rate-limited"
            : normalized.code === DECISION_ERROR_CODES.AUTH_INVALID ? "invalid"
              : "unreachable",
          engine: DECISION_ENGINE_ID,
          model: PINNED_JEV_MODEL,
          errorCode: normalized.code,
          ...safeFailureFields(normalized),
        };
      }
    },
  };
  return Object.freeze(engine);
}

function baselineError(code, message) {
  const err = new Error(message);
  err.code = code;
  return err;
}

function resultFor(taskId, state, repository, event = null, transaction = null, alreadyFresh = false) {
  return {
    taskId,
    revalidated: !alreadyFresh,
    alreadyFresh,
    phase: state.phase,
    previousRevision: event ? event.details.previousStateRevision : state.revision,
    revalidatedRevision: event ? event.details.revalidatedStateRevision : state.revision,
    previousRepositoryFingerprint: event?.details.previousRepositoryFingerprint ?? repository,
    repositoryFingerprint: event?.details.repositoryFingerprint ?? repository,
    eventSeq: event?.seq ?? null,
    transactionCommitSeq: transaction?.seq ?? null,
  };
}

function revalidationError(message, details = {}) {
  const error = new Error(message);
  error.code = "E_CHECKPOINT_REVALIDATION_UNSAFE";
  Object.assign(error, details);
  return error;
}

function sameRepositoryFingerprint(left, right) {
  return left?.branch === right?.branch && left?.head === right?.head;
}

export async function runContextPlan({ target, packageRoot, taskId, decisionId, profile = "balanced", candidates = [], mandatoryIds = [], provider = null, readOnly = false } = {}) {
  if (readOnly) return compileContext({ profile, candidates, mandatoryIds });
  if (target && taskId) {
    const normalized = normalizeContextCandidates(candidates);
    const candidateSetFingerprint = canonicalFingerprint(normalized.map((candidate) => ({
      id: candidate.id, sourceRef: candidate.sourceRef, summary: candidate.summary,
      required: candidate.required, mandatory: candidate.mandatory,
    })));
    const questionSet = buildContextQuestionSet(normalized);
    const decision = await ensureSemanticDecision({
      target, packageRoot, taskId, decisionId, provider, allowNetwork: !readOnly,
      request: {
        decisionKind: "CONTEXT_PLAN", questionSetId: questionSet.id, questionSet,
        state: { candidates: normalized.map(({ id, sourceRef, kind, summary, required, mandatory, risk, trust }) => ({ id, sourceRef, kind, summary, required, mandatory, risk, trust })) },
        candidateIds: normalized.map((candidate) => candidate.id), candidateSetFingerprint,
      },
    });
    return compileContext({ profile, candidates, mandatoryIds, semanticRanker: () => ({ rankedIds: decision.artifact.decision?.rankedIds ?? [], excludedIds: decision.artifact.decision?.excludedIds ?? [] }) });
  }
  return compileContext({ profile, candidates, mandatoryIds });
}

export async function runContinuity({ target, packageRoot, taskId, task } = {}) {
  return withResolvedTask(target, { taskId: taskId ?? task, packageRoot }, async (ctx) => {
    return reconcileContinuity({ target, packageRoot, taskId: ctx?.taskId ?? null });
  });
}

async function assertPreRevisionRouteIdentity({ target, packageRoot, taskId, state, contract }) {
  if (state.phase === "CONTRACT_READY") return;
  try {
    const route = await readPersistedRoute(target, packageRoot, { taskId });
    assertStateIdentity({ contract, route, state });
  } catch (error) {
    throw revisionError(
      `Contract revision requires a valid current route: ${error.message}`,
      error.artifacts ?? [],
    );
  }
}

function revisionError(message, artifacts = []) {
  const error = new Error(message);
  error.code = "E_CONTRACT_REVISION_UNSAFE";
  if (artifacts.length > 0) error.artifacts = artifacts;
  return error;
}

function revisionStateProjection(state, contractFingerprintValue, phase) {
  const next = {
    ...state,
    contractFingerprint: contractFingerprintValue,
    phase,
    requiredGates: [],
    satisfiedGates: [],
    requiredArtifacts: [],
    checks: [],
    failures: [],
    blockers: [],
    verificationEvidence: [],
    completedSteps: phase === "CONTRACT_READY" ? ["contract"] : ["contract", "route"],
    pendingSteps: phase === "CONTRACT_READY"
      ? ["route", "planning", "implementation", "verification"]
      : ["planning", "implementation", "verification"],
  };
  delete next.evidenceCoverage;
  delete next.lastCompletionAttempt;
  delete next.diagnosedHypothesis;
  // The revision event carries the explicit PLANNED -> ROUTED rewind proof.
  // Do not feed the old lifecycle transition marker back into createWorkState:
  // the global transition table must remain forward-only.
  delete next.previousPhase;
  return next;
}

async function adoptAdapters({ target, manifest, adoptPaths, findings }) {
  if (!manifest || adoptPaths.length === 0) return manifest;

  const nextManifest = structuredClone(manifest);
  let changed = false;

  for (const relativePath of adoptPaths) {
    if (!ADAPTER_PATHS.has(relativePath)) {
      findings.push(
        finding(
          "adopt-invalid-path",
          "error",
          relativePath,
          "Only supported adapter paths can be adopted.",
        ),
      );
      continue;
    }

    const destination = ensureWithin(target, relativePath);
    try {
      await assertSafePath(target, relativePath);
    } catch (error) {
      findings.push(finding("unsafe-path", "error", relativePath, error.message));
      continue;
    }
    if (!(await fileExists(destination))) {
      findings.push(finding("adopt-file-missing", "error", relativePath, "Adapter file is missing."));
      continue;
    }

    nextManifest.files[relativePath] = {
      sha256: sha256(await readBytes(destination)),
      preserve: true,
    };
    findings.push(
      finding(
        "file-adopted",
        "info",
        relativePath,
        "Existing adapter is now recorded as preserved by ForgeLoop.",
      ),
    );
    changed = true;
  }

  if (changed) await writeManifest(target, nextManifest);
  return nextManifest;
}

function finding(code, severity, relativePath, message, remediation = null, evidence = null) {
  const evidenceRecord = evidence && typeof evidence === "object"
    ? evidence
    : createEvidence({
      kind: "OBSERVED",
      source: `ForgeLoop doctor:${relativePath}`,
      result: evidence ?? message,
    });
  return {
    code,
    severity,
    path: relativePath,
    message,
    remediation: remediation ?? (severity === "info" ? "No action required." : "Review the target path and apply the suggested correction."),
    evidence: evidenceRecord,
  };
}

async function inspectManagedNativeAdapter({ target, relativePath, bytes, record, findings }) {
  const initialInspection = inspectNativeAdapter(relativePath, bytes);
  const appearsForgeLoopManaged = initialInspection.hasForgeLoopMarker
    || initialInspection.legacyReferences.length > 0
    || initialInspection.text.includes(".forgeloop/kit/");
  if (record.preserve && !appearsForgeLoopManaged) return;

  const validation = await validateNativeAdapterTargets({ target, relativePath, bytes });
  if (validation.stale) {
    findings.push(finding(
      "E_NATIVE_ADAPTER_STALE",
      "error",
      relativePath,
      "Managed native adapter does not resolve its ForgeLoop references to the hidden kit.",
      "Run forgeloop update or merge the hidden-kit references into this adapter.",
    ));
  }
  for (const missingTarget of validation.missingTargets) {
    findings.push(finding(
      "E_NATIVE_ADAPTER_TARGET_MISSING",
      "error",
      relativePath,
      `Managed native adapter target is missing: ${missingTarget}.`,
      "Restore the hidden canonical target and rerun doctor.",
    ));
  }
}

async function inspectRepositoryIndexForDoctor({ target, packageRoot, repositoryIndex, repositoryIndexOptions, findings }) {
  const persistentTransport = await getPersistentTransportStatus({ homeDirectory: repositoryIndexOptions?.homeDirectory });
  if (!repositoryIndex) return { status: "DISABLED", required: false, persistentTransport };
  if (!(await isRepositoryCandidate(target))) {
    return { status: "DEFERRED", required: true, reason: "target is not a Git repository", persistentTransport };
  }

  const status = await getRepositoryIndexStatus(target, { packageRoot, ...repositoryIndexOptions, includeLocalPaths: true });
  const publicStatus = sanitizeRepositoryIndexStatus(status);
  const result = {
    status: publicStatus.health,
    required: true,
    engine: publicStatus.engine,
    engineVersion: publicStatus.engineVersion,
    indexPath: ".forgeloop/repository-index/tgrep",
    server: publicStatus.server,
    diagnostics: publicStatus.diagnostics,
    persistentTransport,
  };
  if (status.health === "READY") {
    try {
      const smoke = await searchRepository(target, {
        ...repositoryIndexOptions,
        packageRoot,
        pattern: "__FORGELOOP_DOCTOR_INDEX_SMOKE__",
        fixedStrings: true,
        maxCount: 1,
      });
      result.smokeSearch = {
        status: "OK",
        matchCount: smoke.matches.length,
        nativeExitCode: smoke.metrics.exitCode,
      };
    } catch (error) {
      result.smokeSearch = {
        status: "ERROR",
        code: error.code ?? "E_REPOSITORY_INDEX_SEARCH_FAILED",
        message: error.message,
      };
      findings.push(finding(
        error.code ?? "E_REPOSITORY_INDEX_SEARCH_FAILED",
        "error",
        ".forgeloop/repository-index",
        `Repository Index smoke search failed: ${error.message}`,
        "Run forgeloop index-status --json, then index-rebuild if the managed search service is unhealthy.",
        error.message,
      ));
    }
  }
  if (status.health !== "READY") {
    findings.push(finding(
      publicStatus.diagnostics?.[0]?.code ?? "E_REPOSITORY_INDEX_SERVER_UNHEALTHY",
      "error",
      ".forgeloop/repository-index",
      `Repository Index is ${status.health}; ${publicStatus.diagnostics?.[0]?.message ?? "native index health is not ready"}`,
      "Run forgeloop index-setup or forgeloop index-rebuild with an approved managed tgrep asset.",
      publicStatus,
    ));
  }
  return result;
}

function readProfileMode(bytes) {
  const text = bytes.toString("utf8");
  return text.match(/^profile-mode:\s*([^\s]+)\s*$/m)?.[1] ?? null;
}

export async function runDoctor({ target, packageRoot, adoptPaths = [], strict = false, fix = false, repositoryIndex, repositoryIndexOptions }) {
  const findings = [];
  let incompleteTransactions = await findIncompleteTransactions(target);
  if (fix && incompleteTransactions.some((transaction) => transaction.status === "COMMITTING")) {
    const recovered = await recoverIncompleteTransactions(target);
    for (const transaction of recovered) {
      findings.push(finding(
        transaction.status === "ROLLED_BACK" ? "TRANSACTION_RECOVERED" : "E_TRANSACTION_RECOVERY_FAILED",
        transaction.status === "ROLLED_BACK" ? "info" : "error",
        `.forgeloop/.txn/${transaction.transactionId}`,
        `Transaction recovery result: ${transaction.status}.`,
      ));
    }
    incompleteTransactions = await findIncompleteTransactions(target);
  }
  for (const transaction of incompleteTransactions) {
    findings.push(finding(
      "E_TRANSACTION_INCOMPLETE",
      "error",
      `.forgeloop/.txn/${transaction.transactionId}`,
      `Transaction ${transaction.transactionId} is ${transaction.status} and requires inspection or deterministic recovery.`,
      "Run forgeloop doctor --fix only after ensuring no active process owns the task lock.",
    ));
  }
  let manifest = null;
  let manifestChanged = false;
  try {
    manifest = await readManifest(target);
    if (!manifest) {
      findings.push(finding("manifest-missing", "error", ".forgeloop/manifest.json", "Run forgeloop init first."));
    }
  } catch (error) {
    findings.push(finding("manifest-invalid", "error", ".forgeloop/manifest.json", error.message));
  }

  manifest = await adoptAdapters({ target, manifest, adoptPaths, findings });
  const entries = await readTemplateEntries(packageRoot);
  const layoutVersion = manifest?.layoutVersion ?? 1;
  if (manifest && layoutVersion < LAYOUT_VERSION) {
    findings.push(finding(
      "legacy-layout",
      "info",
      ".forgeloop/manifest.json",
      "Target uses the legacy root template layout; run forgeloop update to migrate the canonical kit under .forgeloop/kit.",
    ));
  }
  for (const entry of entries) {
    const managedPath = layoutVersion >= LAYOUT_VERSION ? entry.relativePath : entry.legacyRelativePath;
    const destination = ensureWithin(target, managedPath);
    try {
      await assertSafePath(target, managedPath);
    } catch (error) {
      findings.push(finding("unsafe-path", "error", managedPath, error.message));
      continue;
    }
    const hasLegacyAlternative = layoutVersion >= LAYOUT_VERSION
      && entry.legacyRelativePath !== entry.relativePath;
    if (layoutVersion < LAYOUT_VERSION && entry.legacyRelativePath !== entry.relativePath) {
      const hiddenDestination = ensureWithin(target, entry.relativePath);
      try {
        await assertSafePath(target, entry.relativePath);
        if (await fileExists(hiddenDestination)) {
          findings.push(finding(
            "E_MIGRATION_INCOMPLETE",
            "error",
            entry.relativePath,
            "A hidden migration destination exists while the legacy manifest is still authoritative; rerun forgeloop update to recover the transaction.",
            "Run forgeloop update and inspect the result before changing either copy.",
          ));
        }
      } catch (error) {
        findings.push(finding("unsafe-path", "error", entry.relativePath, error.message));
      }
    }
    if (hasLegacyAlternative) {
      try {
        await assertSafePath(target, entry.legacyRelativePath);
      } catch (error) {
        findings.push(finding("unsafe-path", "error", entry.legacyRelativePath, error.message));
        continue;
      }
    }
    if (!(await fileExists(destination))) {
      const legacyDestination = hasLegacyAlternative
        ? ensureWithin(target, entry.legacyRelativePath)
        : null;
      if (legacyDestination && await fileExists(legacyDestination)) {
        findings.push(finding(
          "E_MIGRATION_INCOMPLETE",
          "error",
          entry.legacyRelativePath,
          "Canonical file remains in the legacy root layout; migration is incomplete and the legacy copy was preserved.",
          "Run forgeloop update; it removes the root copy only when the recorded ownership hash still matches.",
        ));
        continue;
      }
      if (fix && manifest && (layoutVersion >= LAYOUT_VERSION || managedPath.startsWith(".forgeloop/"))) {
        await writeFileAtomic(destination, entry.bytes);
        manifest.files[managedPath] = {
          sha256: sha256(entry.bytes),
          preserve: entry.sourcePath === "PROJECT_PROFILE.md",
        };
        manifestChanged = true;
        findings.push(finding("file-restored", "info", managedPath, "Restored missing managed template file.", "No action required."));
        continue;
      }
      findings.push(finding("file-missing", "error", managedPath, "Managed file is missing."));
      continue;
    }

    const destinationBytes = await readBytes(destination);
    if (entry.sourcePath === "PROJECT_PROFILE.md") {
      const mode = readProfileMode(destinationBytes);
      if (mode === "template") {
        findings.push(finding("profile-template", "info", managedPath, "Initialize profile-mode as project after confirming real project facts."));
      }
    }

    const legacyPath = hasLegacyAlternative
      ? ensureWithin(target, entry.legacyRelativePath)
      : null;
    if (entry.sourcePath === "PROJECT_PROFILE.md" && legacyPath && await fileExists(legacyPath)) {
      findings.push(finding(
        "E_DUPLICATE_PROFILE_SOURCE",
        "error",
        entry.legacyRelativePath,
        "Both legacy root and hidden-kit project profiles exist; keep only the hidden profile as canonical.",
        "Remove the legacy root profile after verifying its bytes are represented in .forgeloop/kit/PROJECT_PROFILE.md.",
      ));
    }

    const record = manifest?.files?.[managedPath];
    if (!record) {
      if (ADAPTER_PATHS.has(managedPath)) {
        findings.push(
          finding(
            "unmanaged-file",
            "error",
            managedPath,
            "Existing adapter is not managed by ForgeLoop; merge the loop reference and rerun doctor.",
          ),
        );
      }
      continue;
    }
    const actualHash = sha256(destinationBytes);
    if (actualHash !== record.sha256 && !record.preserve) {
      findings.push(finding("file-drift", "warning", managedPath, "File differs from the last managed version; update will preserve it."));
    }
    if (hasLegacyAlternative) {
      if (await fileExists(legacyPath)) {
        if (entry.sourcePath !== "PROJECT_PROFILE.md") {
          findings.push(finding(
            "E_MIGRATION_INCOMPLETE",
            "error",
            entry.legacyRelativePath,
            record.legacySha256
              ? "A legacy root copy remains after the manifest authority switch; cleanup is incomplete."
              : "A legacy root copy remains without an ownership proof; it was preserved.",
            "Run forgeloop update; modified or unowned legacy files require manual review and are never deleted silently.",
          ));
        }
        if (entry.sourcePath === "PROJECT_PROFILE.md") {
          findings.push(finding(
            "E_MIGRATION_INCOMPLETE",
            "error",
            entry.legacyRelativePath,
            record.legacySha256
              ? "The legacy project profile remains after the manifest authority switch; cleanup is incomplete."
              : "A legacy project profile remains alongside the hidden canonical profile.",
            "Run forgeloop update, then remove the root profile only after verifying ownership and preserved bytes.",
          ));
        }
      }
    }
    if (layoutVersion >= LAYOUT_VERSION && ADAPTER_PATHS.has(managedPath)) {
      await inspectManagedNativeAdapter({
        target,
        relativePath: managedPath,
        bytes: destinationBytes,
        record,
        findings,
      });
    }
  }

  const shippedPaths = new Set(entries.map((entry) => layoutVersion >= LAYOUT_VERSION ? entry.relativePath : entry.legacyRelativePath));
  for (const relativePath of Object.keys(manifest?.files ?? {})) {
    if (!shippedPaths.has(relativePath)) {
      findings.push(
        finding(
          "manifest-orphan",
          "warning",
          relativePath,
          "Manifest entry no longer corresponds to a shipped template.",
        ),
      );
    }
  }

  if (manifestChanged && manifest) {
    await writeManifest(target, manifest);
  }

  const repositoryIndexResult = await inspectRepositoryIndexForDoctor({
    target,
    packageRoot,
    repositoryIndex,
    repositoryIndexOptions,
    findings,
  });

  findings.push(semanticDecisionPlaneFinding());

  const ok = findings.every((item) => item.severity !== "error")
    && (!strict || findings.every((item) => item.severity !== "warning"));
  return {
    ok,
    findings,
    repositoryIndex: repositoryIndexResult,
    evidence: [createEvidence({
      kind: "OBSERVED",
      source: "ForgeLoop doctor",
      result: `${findings.length} findings; ${ok ? "healthy" : "needs attention"}`,
    })],
  };
}

function semanticDecisionPlaneFinding() {
  const credentialState = hasTypesafeCredentials() ? "credentials configured" : "credentials missing";
  return finding(
    "semantic-decision-plane",
    "info",
    ".forgeloop/config.json",
    `Semantic decision plane: ${credentialState}; pinned model ${PINNED_JEV_MODEL}.`,
    "Set TYPESAFE_API_KEY in the host environment before invoking a new semantic decision; recovery and inspection remain local.",
  );
}

function gateError(message, options = {}) {
  const error = new Error(message);
  error.code = options.code ?? "E_GATE_INVALID";
  if (options.cause !== undefined) error.cause = options.cause;
  if (options.artifacts !== undefined) error.artifacts = options.artifacts;
  return error;
}

function revalidationError(message, code = "E_GATE_REVALIDATION_UNSAFE", artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function runModelRoute({ target, packageRoot, taskId, decisionId, workType, surfaces, risks, platforms, behaviorChange, executableChange, generationRequired, architectureChange, ambiguity, semanticRecommendation, contract } = {}) {
  if (target && taskId) {
    const bindings = await readCurrentDecisionBindings(target, packageRoot, taskId);
    const decision = await resolveRequiredSemanticDecision({
      target, packageRoot, taskId, decisionId, decisionKind: "MODEL_ROUTE", currentBindings: bindings,
    });
    semanticRecommendation = decision.decision;
  }
  return projectModelRoute({
    input: {
      workType,
      surfaces,
      risks,
      platforms,
      behaviorChange,
      executableChange,
      generationRequired,
      architectureChange,
      ambiguity,
      contract,
    },
    semanticRecommendation,
  });
}

export async function runNext({ target, packageRoot, taskId, task, authorityContext, runtimeContext, compact = false, explain = false }) {
  return withResolvedTask(target, { taskId: taskId ?? task, packageRoot }, async (ctx) => {
    const result = await getNextAction({
      target,
      packageRoot,
      taskId: ctx?.taskId ?? null,
      authorityContext,
      runtimeContext,
    });
    const explained = explain ? { ...result, explanation: explainNextAction(result) } : result;
    if (!compact) return explained;
    const compactTaskId = ctx?.taskId ?? (result.taskId && result.taskId !== "unknown" ? result.taskId : null);
    let profile = null;
    try {
      const route = await readPersistedRoute(target, packageRoot, { taskId: compactTaskId });
      profile = projectExecutionProfile(route.value);
    } catch {
      // Legacy and incomplete tasks remain readable without a profile.
    }
    return {
      taskId: compactTaskId ?? result.taskId,
      phase: explained.currentPhase,
      profile,
      nextAction: explained.nextAction,
      command: explained.commandSpecs?.[0]?.argv ?? [],
      terminal: explained.terminal,
      errors: explained.reasonCodes ?? explained.reasons?.map((reason) => reason.code) ?? [],
      ...(explained.explanation ? { explanation: explained.explanation } : {}),
    };
  });
}

export async function runProtocolInfo({ packageVersion = null } = {}) {
  return protocolInfo({ packageVersion });
}

export async function runReport(options = {}) {
  const target = options.target;
  const packageRoot = options.packageRoot;
  const taskId = options.taskId ?? options.task ?? null;
  return withResolvedTask(target, { taskId, packageRoot }, async (ctx) => {
    return evaluateReport({ ...options, taskId: ctx?.taskId ?? null });
  });
}

function canAppendCanonicalRouteWitness({ stateBefore, previousPersistedRouteFingerprint, persistedRoute }) {
  return stateBefore?.phase === "ROUTED"
    && previousPersistedRouteFingerprint !== null
    && persistedRoute.fingerprint !== previousPersistedRouteFingerprint
    && stateBefore.contractFingerprint === persistedRoute.value.contractFingerprint;
}

function canAppendRepairedRouteWitness({ stateBefore, marker, previousPersistedRouteFingerprint, persistedRoute }) {
  if (previousPersistedRouteFingerprint === null) {
    return stateBefore.phase === "CONTRACT_READY"
      && marker.details.reconstructedPhase === "CONTRACT_READY"
      && marker.details.routeFingerprint === null;
  }
  return persistedRoute.fingerprint !== previousPersistedRouteFingerprint
    && persistedRoute.value.contractFingerprint === marker.details.contractFingerprint;
}

export async function runStatus({ target, packageRoot, contractFile = null, taskId, task } = {}) {
  return withResolvedTask(target, { taskId: taskId ?? task, packageRoot }, async (ctx) => {
    const effectiveTaskId = ctx?.taskId ?? null;
    const state = await readAndClassifyWorkState({ target, packageRoot, contractFile, taskId: effectiveTaskId });
    const [protocol, continuity] = await Promise.all([
      inspectSchemaHealth(target),
      reconcileContinuity({ target, packageRoot, taskId: effectiveTaskId }),
    ]);
    const taskInfo = effectiveTaskId ? await findTaskById(target, effectiveTaskId, packageRoot) : null;
    return {
      ...state,
      taskId: effectiveTaskId,
      taskKey: ctx?.taskKey ?? null,
      recovery: taskInfo?.recovery ?? null,
      claimState: taskInfo?.claimState ?? null,
      historicalWriteClaims: taskInfo?.historicalWriteClaims ?? [],
      effectiveWriteClaims: taskInfo?.effectiveWriteClaims ?? [],
      mutationAllowed: taskInfo?.mutationAllowed ?? true,
      ownershipValid: taskInfo?.ownershipValid ?? true,
      ownershipErrors: taskInfo?.ownershipErrors ?? taskInfo?.errors ?? [],
      reasonCodes: taskInfo?.reasonCodes ?? [],
      protocol,
      continuity,
      evidence: [...(state.evidence ?? []), ...(protocol.evidence ?? [])],
    };
  });
}

export async function assertNoScopeConflictsWithInspection(claims, existingTasks, currentTaskId, { target, packageRoot } = {}) {
  try {
    assertNoScopeConflicts(claims, existingTasks, currentTaskId);
  } catch (error) {
    if (error.code !== "E_TASK_SCOPE_CONFLICT") throw error;
    const inspected = [];
    for (const conflict of error.conflicts ?? []) {
      let inspection = null;
      try {
        inspection = await inspectTaskConflictState(target, { taskId: conflict.taskId, packageRoot });
      } catch (inspectionError) {
        inspection = {
          taskId: conflict.taskId,
          classification: "INCONSISTENT",
          reasonCodes: [inspectionError.code ?? "E_TASK_NOT_FOUND"],
          recoverable: false,
        };
      }
      const guidance = recoveryGuidanceForClassification(inspection.classification, conflict.taskId);
      inspected.push({
        ...conflict,
        classification: inspection.classification,
        reasonCodes: inspection.reasonCodes,
        nextAction: guidance.nextAction,
        commandSpecs: guidance.commandSpecs,
        inspection,
      });
    }
    error.conflicts = inspected;
    error.message = `${error.message}; conflicting task classifications: ${inspected
      .map((item) => `${item.taskId}=${item.inspection.classification}`)
      .join(", ")}`;
    throw error;
  }
}

