async function validateReceiptFile(target, packageRoot, relativeFile) {
  await assertSafePath(target, relativeFile);
  const receiptPath = ensureWithin(target, relativeFile);
  let receipt;
  try {
    const bytes = await readBytes(receiptPath);
    assertJsonBytes(bytes, relativeFile);
    receipt = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(receipt, relativeFile);
  } catch (error) {
    throw new Error(`Unable to parse receipt ${relativeFile}: ${error.message}`);
  }
  try {
    return await validateReceipt(receipt, packageRoot);
  } catch (error) {
    throw new Error(`Invalid receipt ${relativeFile}: ${error.message}`);
  }
}

function hasCanonicalVerificationEvidence(details) {
  return Boolean(
    details
    && typeof details.evidenceRef === "string" && details.evidenceRef.length > 0 && details.evidenceRef.length <= 256
    && details.evidenceKind === "FORGELOOP_EXECUTION"
    && typeof details.verifiedAt === "string",
  );
}

function hasModernAuthorizationEvidence(details) {
  if (!details || typeof details !== "object") return false;
  if (!["ALLOW", "REQUIRE_AUTHORITY", "REQUIRE_APPROVAL"].includes(details.capabilityDecision)) return false;
  if (typeof details.capabilityPolicyFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.capabilityPolicyFingerprint)) return false;
  if (typeof details.policyLockDigest !== "string" || !details.policyLockDigest.startsWith("sha256:")) return false;
  if (typeof details.taskPolicyDigest !== "string" || !details.taskPolicyDigest.startsWith("sha256:")) return false;
  if (details.capabilityDecision === "ALLOW") return true;
  if (details.authorityKind !== "HOST_ATTESTED" || typeof details.authorityRef !== "string" || !details.authorityRef) return false;
  if (details.capabilityDecision === "REQUIRE_AUTHORITY") return true;
  if (details.capabilityDecision === "REQUIRE_APPROVAL") {
    return typeof details.approvalId === "string" && !!details.approvalId
      && typeof details.approvalFingerprint === "string" && /^[a-f0-9]{64}$/.test(details.approvalFingerprint);
  }
  return false;
}

function issue(code, message) {
  return { code, message };
}

function actionError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function actionRequiresIdempotency(effectClass) {
  return SIDE_EFFECTING_EFFECT_CLASSES.includes(effectClass);
}

export function assertActionAuthorizationDetails(details, { legacyAllowed = false } = {}) {
  const required = legacyAllowed
    ? []
    : [
      "capabilityDecision",
      "actionFingerprint",
      "capabilityPolicyFingerprint",
      "policyLockDigest",
      "taskPolicyDigest",
    ];
  for (const key of required) {
    assertBoundedEventText(details, key, 512);
  }
  if (details.capabilityDecision !== undefined) {
    if (!["ALLOW", "REQUIRE_AUTHORITY", "REQUIRE_APPROVAL"].includes(details.capabilityDecision)) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "capabilityDecision must be ALLOW, REQUIRE_AUTHORITY, or REQUIRE_APPROVAL",
      );
    }
    if (
      typeof details.capabilityPolicyFingerprint !== "string" ||
      !SHA256_HEX_REGEX.test(details.capabilityPolicyFingerprint)
    ) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "capabilityPolicyFingerprint must bind ACTION_AUTHORIZED to the exact project policy",
      );
    }
    if (typeof details.policyLockDigest !== "string" || !details.policyLockDigest.startsWith("sha256:")) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "policyLockDigest must bind ACTION_AUTHORIZED to the persisted policy lock",
      );
    }
    if (typeof details.taskPolicyDigest !== "string" || !details.taskPolicyDigest.startsWith("sha256:")) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "taskPolicyDigest must bind ACTION_AUTHORIZED to the task policy snapshot",
      );
    }
    if (details.capabilityDecision === "REQUIRE_AUTHORITY") {
      if (details.authorityKind !== "HOST_ATTESTED") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_AUTHORIZATION decisions require authorityKind=HOST_ATTESTED",
        );
      }
      assertBoundedEventText(details, "authorityRef", 256);
    }
    if (details.capabilityDecision === "REQUIRE_APPROVAL") {
      assertBoundedEventText(details, "approvalId", 256);
      if (typeof details.approvalFingerprint !== "string") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_APPROVAL authorizations require approvalFingerprint",
        );
      }
      if (details.authorityKind !== "HOST_ATTESTED") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_APPROVAL authorizations require authorityKind=HOST_ATTESTED",
        );
      }
      assertBoundedEventText(details, "authorityRef", 256);
    }
  }
  return true;
}

export function assertActionTransition(from, to) {
  const targets = ACTION_TRANSITIONS.get(from);
  if (!targets || !targets.includes(to)) {
    throw actionError(
      E_ACTION_STATE_MISMATCH,
      `Invalid durable action transition ${String(from)} -> ${String(to)}`,
    );
  }
  return to;
}

export function assertApprovalIdFormat(approvalId) {
  if (typeof approvalId !== "string" || !APPROVAL_ID_REGEX.test(approvalId)) {
    throw actionError(E_APPROVAL_INVALID, "approvalId must match approval-[A-Za-z0-9_-]+");
  }
  return approvalId;
}

function assertBoundedText(value, label, maxLength, { required = true } = {}) {
  if (value === undefined || value === null) {
    if (required) throw actionError(E_ACTION_INVALID, `${label} is required`);
    return;
  }
  if (typeof value !== "string" || value.length === 0) {
    throw actionError(E_ACTION_INVALID, `${label} must be a non-empty string`);
  }
  if (value.length > maxLength) {
    throw actionError(E_ACTION_INVALID, `${label} must not exceed ${maxLength} characters`);
  }
}

function assertEnum(value, allowed, label) {
  if (!allowed.includes(value)) {
    throw actionError(E_ACTION_INVALID, `${label} must be one of ${allowed.join(", ")}`);
  }
}

function assertTimestamp(value, label, { required = false } = {}) {
  if (value === undefined || value === null) {
    if (required) throw actionError(E_ACTION_INVALID, `${label} is required`);
    return;
  }
  if (typeof value !== "string" || Number.isNaN(Date.parse(value))) {
    throw actionError(E_ACTION_INVALID, `${label} must be an ISO timestamp string`);
  }
}

export function canonicalActionFingerprint(actionInput) {
  return canonicalFingerprint(canonicalActionIdentity(actionInput));
}

export function canonicalActionIdentity(actionInput) {
  return {
    taskId: actionInput.taskId,
    actionId: actionInput.actionId,
    effectClass: actionInput.effectClass,
    capability: actionInput.capability,
    target: actionInput.target ?? null,
    operation: actionInput.operation ?? null,
    idempotencyKey: actionInput.idempotencyKey ?? null,
    requiredForCompletion: Boolean(actionInput.requiredForCompletion),
    requirement: actionInput.requirement ?? null,
  };
}

export function validateActionArtifact(action) {
  if (!action || typeof action !== "object" || Array.isArray(action)) {
    throw actionError(E_ACTION_INVALID, "durable action artifact must be a JSON object");
  }

  for (const key of [
    "schemaVersion",
    "taskId",
    "actionId",
    "actionFingerprint",
    "effectClass",
    "capability",
    "operation",
    "target",
    "idempotencyKey",
    "requiredForCompletion",
    "requirement",
    "provenance",
    "state",
    "revision",
    "createdAt",
    "updatedAt",
  ]) {
    if (!Object.prototype.hasOwnProperty.call(action, key)) {
      throw actionError(E_ACTION_INVALID, `durable action artifact.${key} is required`);
    }
  }

  if (action.schemaVersion !== 1) {
    throw actionError(E_ACTION_INVALID, "durable action schemaVersion must be 1");
  }
  assertBoundedText(action.taskId, "taskId", 256);
  assertBoundedText(action.actionId, "actionId", 256);
  if (!ACTION_ID_REGEX.test(action.actionId)) {
    throw actionError(E_ACTION_INVALID, "actionId must match action-[A-Za-z0-9_-]+");
  }
  if (typeof action.actionFingerprint !== "string" || !SHA256_HEX_REGEX.test(action.actionFingerprint)) {
    throw actionError(E_ACTION_INVALID, "actionFingerprint must be a lowercase sha256 hex digest");
  }
  assertEnum(action.effectClass, ACTION_EFFECT_CLASSES, "effectClass");
  assertEnum(action.capability, ACTION_CAPABILITIES, "capability");
  assertBoundedText(action.operation, "operation", 512);
  assertBoundedText(action.target, "target", 512);

  if (actionRequiresIdempotency(action.effectClass)) {
    assertBoundedText(action.idempotencyKey, "idempotencyKey", 512);
  } else if (action.idempotencyKey !== null && action.idempotencyKey !== undefined) {
    assertBoundedText(action.idempotencyKey, "idempotencyKey", 512);
  }

  if (typeof action.requiredForCompletion !== "boolean") {
    throw actionError(E_ACTION_INVALID, "requiredForCompletion must be a boolean");
  }
  assertBoundedText(action.requirement, "requirement", 256, { required: false });
  assertEnum(action.provenance, ACTION_PROVENANCE, "provenance");
  assertEnum(action.state, ACTION_STATES, "state");

  if (action.state !== "PROPOSED" && !Number.isInteger(action.revision)) {
    throw actionError(E_ACTION_INVALID, "revision must be an integer");
  }

  assertTimestamp(action.createdAt, "createdAt", { required: true });
  assertTimestamp(action.updatedAt, "updatedAt", { required: true });

  if (action.lastEvidenceRef !== undefined && action.lastEvidenceRef !== null) {
    assertBoundedText(action.lastEvidenceRef, "lastEvidenceRef", 256);
  }

  if (action.lastReconciliationAt !== undefined && action.lastReconciliationAt !== null) {
    assertTimestamp(action.lastReconciliationAt, "lastReconciliationAt", { required: true });
  }

  if (action.commitResultCode !== undefined && action.commitResultCode !== null) {
    assertEnum(
      action.commitResultCode,
      COMMIT_UNKNOWN_RESULT_CODES,
      "commitResultCode",
    );
  }

  // VERIFIED is a trust claim: it must always carry canonical evidence.
  if (action.state === "VERIFIED" && !action.lastEvidenceRef) {
    throw actionError(
      E_ACTION_VERIFICATION_REQUIRED,
      "VERIFIED actions require a canonical verification evidence reference",
    );
  }

  const allowedKeys = new Set([
    "schemaVersion",
    "taskId",
    "actionId",
    "actionFingerprint",
    "effectClass",
    "capability",
    "operation",
    "target",
    "idempotencyKey",
    "requiredForCompletion",
    "requirement",
    "provenance",
    "state",
    "revision",
    "createdAt",
    "updatedAt",
    "lastEvidenceRef",
    "lastReconciliationAt",
    "commitResultCode",
  ]);
  for (const key of Object.keys(action)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_ACTION_INVALID, `durable action artifact.${key} is not an allowed property`);
    }
  }

  const recomputed = canonicalActionFingerprint(action);
  if (recomputed !== action.actionFingerprint) {
    throw actionError(
      E_ACTION_INVALID,
      "actionFingerprint does not match the immutable identity fields",
    );
  }

  return action;
}

export function validateApprovalArtifact(approval) {
  if (!approval || typeof approval !== "object" || Array.isArray(approval)) {
    throw actionError(E_APPROVAL_INVALID, "approval artifact must be a JSON object");
  }

  for (const key of [
    "schemaVersion",
    "taskId",
    "approvalId",
    "actionId",
    "actionFingerprint",
    "contractFingerprint",
    "taskRevision",
    "capability",
    "status",
    "requestedAt",
  ]) {
    if (!Object.prototype.hasOwnProperty.call(approval, key)) {
      throw actionError(E_APPROVAL_INVALID, `approval artifact.${key} is required`);
    }
  }

  if (approval.schemaVersion !== 1) {
    throw actionError(E_APPROVAL_INVALID, "approval schemaVersion must be 1");
  }
  assertBoundedText(approval.taskId, "taskId", 256);
  assertBoundedText(approval.approvalId, "approvalId", 256);
  if (!APPROVAL_ID_REGEX.test(approval.approvalId)) {
    throw actionError(E_APPROVAL_INVALID, "approvalId must match approval-[A-Za-z0-9_-]+");
  }
  assertBoundedText(approval.actionId, "actionId", 256);
  if (typeof approval.actionFingerprint !== "string" || !SHA256_HEX_REGEX.test(approval.actionFingerprint)) {
    throw actionError(E_APPROVAL_INVALID, "actionFingerprint must be a lowercase sha256 hex digest");
  }
  if (
    typeof approval.contractFingerprint !== "string" ||
    !SHA256_HEX_REGEX.test(approval.contractFingerprint)
  ) {
    throw actionError(E_APPROVAL_INVALID, "contractFingerprint must be a lowercase sha256 hex digest");
  }
  if (!Number.isInteger(approval.taskRevision) || approval.taskRevision < 0) {
    throw actionError(E_APPROVAL_INVALID, "taskRevision must be a non-negative integer");
  }
  assertEnum(approval.capability, ACTION_CAPABILITIES, "capability");
  assertEnum(approval.status, APPROVAL_STATUSES, "status");
  assertTimestamp(approval.requestedAt, "requestedAt", { required: true });

  if (approval.status !== "PENDING") {
    assertEnum(approval.decision, [approval.status], "decision");
    assertTimestamp(approval.resolvedAt, "resolvedAt", { required: true });
    assertEnum(approval.authorityKind, APPROVAL_AUTHORITY_KINDS, "authorityKind");
    if (approval.authorityKind === "HOST_ATTESTED" && !approval.hostGrantRef) {
      throw actionError(
        E_APPROVAL_INVALID,
        "HOST_ATTESTED approvals require a hostGrantRef supplied by the host boundary",
      );
    }
  }

  const allowedKeys = new Set([
    "schemaVersion",
    "taskId",
    "approvalId",
    "actionId",
    "actionFingerprint",
    "contractFingerprint",
    "taskRevision",
    "capability",
    "status",
    "requestedAt",
    "reason",
    "decision",
    "resolvedAt",
    "authorityKind",
    "hostGrantRef",
  ]);
  for (const key of Object.keys(approval)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_APPROVAL_INVALID, `approval artifact.${key} is not an allowed property`);
    }
  }
  assertBoundedText(approval.reason, "reason", 512, { required: false });

  return approval;
}

export function validateCapabilityPolicy(policy) {
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    throw actionError(E_POLICY_INVALID, "capability policy must be a JSON object");
  }
  if (policy.schemaVersion !== 1) {
    throw actionError(E_POLICY_INVALID, "capability policy schemaVersion must be 1");
  }
  if (!["ALLOW", "DENY"].includes(policy.defaultDecision)) {
    throw actionError(
      E_POLICY_INVALID,
      "defaultDecision must be ALLOW or DENY; REQUIRE_* defaults are not valid",
    );
  }
  if (!Array.isArray(policy.rules)) {
    throw actionError(E_POLICY_INVALID, "rules must be an array");
  }
  const seen = new Set();
  for (const rule of policy.rules) {
    if (!rule || typeof rule !== "object") {
      throw actionError(E_POLICY_INVALID, "each rule must be a JSON object");
    }
    assertEnum(rule.capability, ACTION_CAPABILITIES, "rule.capability");
    assertEnum(rule.decision, CAPABILITY_DECISIONS, "rule.decision");
    if (seen.has(rule.capability)) {
      throw actionError(
        E_POLICY_INVALID,
        `duplicate rule for capability ${rule.capability}`,
      );
    }
    seen.add(rule.capability);
  }
  const allowedKeys = new Set(["schemaVersion", "defaultDecision", "rules"]);
  for (const key of Object.keys(policy)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_POLICY_INVALID, `capability policy.${key} is not an allowed property`);
    }
  }
  return policy;
}

export async function evaluateActionReadiness({
  target,
  packageRoot,
  taskId,
  action,
}) {
  const resolved = action ?? await readAction(target, { packageRoot, taskId, actionId: action?.actionId });
  const ledger = await projectActionLedger({
    target,
    packageRoot,
    taskId,
    actionId: resolved.actionId,
    artifact: resolved,
  });

  if (!ledger.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "action ledger chronology is invalid or diverges from the artifact",
      ...ledger.errors.map((error) => error.message),
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // REQUIRE_APPROVAL authorizations bind the exact resolved approval content;
  // any post-authorization mutation of the approval artifact must be
  // readiness/audit-visible (INV-FINAL-APPROVAL-01).
  const authorizationDetails = ledger.authorization.details;
  if (authorizationDetails?.capabilityDecision === "REQUIRE_APPROVAL") {
    try {
      const { validateBoundApprovalFingerprint } = await import("./approvals.js");
      await validateBoundApprovalFingerprint(target, {
        packageRoot,
        taskId,
        approvalId: authorizationDetails.approvalId,
        expectedFingerprint: authorizationDetails.approvalFingerprint,
      });
    } catch (error) {
      return result(resolved.actionId, "UNTRUSTED", [
        `bound approval integrity failed: ${error.message}`,
      ], { authorization: ledger.authorization, verification: ledger.verification });
    }
  }

  if (resolved.state === "COMMIT_UNKNOWN") {
    return result(resolved.actionId, "AMBIGUOUS", [
      "external commit state is unknown; reconcile through a trusted boundary",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (resolved.state === "FAILED" || resolved.state === "CANCELLED") {
    return result(resolved.actionId, "FAILED", [
      `action is ${resolved.state}`,
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (resolved.state !== "VERIFIED") {
    return result(resolved.actionId, "PENDING", [
      `action is ${resolved.state}; verification requires canonical independent evidence`,
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // A required action without a requirement can never be strongly verified:
  // legacy artifacts stay readable but cannot become trusted-satisfied
  // (INV-FINAL-VERIFY-02).
  if (
    resolved.requiredForCompletion
    && (typeof resolved.requirement !== "string" || resolved.requirement.length === 0)
  ) {
    return result(resolved.actionId, "UNTRUSTED", [
      "required action has no canonical requirement binding",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // VERIFIED label present: trust requires modern authorization evidence.
  if (!ledger.authorization.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "authorization evidence is invalid or legacy pre-hardening",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (!ledger.verification.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "verification evidence is missing or not canonical",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  return result(resolved.actionId, "SATISFIED", [], {
    authorization: ledger.authorization,
    verification: ledger.verification,
  });
}

export async function evaluateRequiredActionReadiness({
  target,
  packageRoot,
  taskId,
}) {
  const actions = await listActions(target, { packageRoot, taskId });
  const required = actions.filter((action) => action.requiredForCompletion);
  const evaluated = [];
  for (const action of required) {
    evaluated.push(await evaluateActionReadiness({ target, packageRoot, taskId, action }));
  }
  return {
    total: required.length,
    satisfied: evaluated.filter((item) => item.status === "SATISFIED").length,
    unresolved: evaluated.filter((item) => item.status !== "SATISFIED").length,
    ambiguous: evaluated.filter((item) => item.status === "AMBIGUOUS").length,
    failed: evaluated.filter((item) => item.status === "FAILED").length,
    untrusted: evaluated.filter((item) => item.status === "UNTRUSTED").length,
    actions: evaluated,
  };
}

function result(actionId, status, reasons, extra = {}) {
  return {
    actionId,
    status,
    reasons,
    ...extra,
  };
}

function actionError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function assertProposeInput(input) {
  if (!input || typeof input !== "object") {
    throw actionError(E_ACTION_INVALID, "action input must be an object");
  }
  if (typeof input.actionId !== "string" || !/^action-[A-Za-z0-9_-]+$/.test(input.actionId)) {
    throw actionError(E_ACTION_INVALID, "actionId must match action-[A-Za-z0-9_-]+");
  }
  for (const key of ["effectClass", "capability", "operation", "target", "provenance"]) {
    if (typeof input[key] !== "string" || !input[key]) {
      throw actionError(E_ACTION_INVALID, `action input.${key} must be a non-empty string`);
    }
  }
  if (actionRequiresIdempotency(input.effectClass)) {
    if (typeof input.idempotencyKey !== "string" || !input.idempotencyKey) {
      throw actionError(
        E_ACTION_IDEMPOTENCY_REQUIRED,
        `effectClass ${input.effectClass} requires an idempotency key`,
      );
    }
  }
  // Completion-critical actions must declare what postcondition they satisfy;
  // without a requirement, strong verification binding is impossible
  // (INV-FINAL-VERIFY-02). Legacy artifacts remain readable but untrusted.
  if (
    input.requiredForCompletion === true
    && (typeof input.requirement !== "string" || input.requirement.trim() === "")
  ) {
    throw actionError(
      E_ACTION_INVALID,
      "required-for-completion actions require a non-empty requirement",
    );
  }
}

async function listActionFiles(target, packageRoot, taskId) {
  const relDir = taskActionsDirectory(taskId);
  await assertSafePath(target, relDir);
  const absoluteDir = ensureWithin(target, relDir);
  let entries;
  try {
    entries = await readdir(absoluteDir);
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
  const actions = [];
  for (const entry of entries) {
    if (!entry.endsWith(".json")) continue;
    const parsed = await readActionFile(target, packageRoot, taskId, entry.replace(/\.json$/, ""));
    if (parsed) actions.push(parsed);
  }
  actions.sort((left, right) => String(left.createdAt).localeCompare(String(right.createdAt)));
  return actions;
}

export async function listActions(target, { packageRoot, taskId }) {
  const actions = await listActionFiles(target, packageRoot, taskId);
  return actions.map((action) => validateActionArtifact(action));
}

export async function readAction(target, { packageRoot, taskId, actionId }) {
  const action = await readActionFile(target, packageRoot, taskId, actionId);
  if (!action) {
    throw actionError(E_ACTION_NOT_FOUND, `durable action ${actionId} does not exist for task ${taskId}`);
  }
  return validateActionArtifact(action);
}

async function readActionFile(target, packageRoot, taskId, actionId) {
  const relPath = taskActionPath(taskId, actionId);
  await assertSafePath(target, relPath);
  const absolute = ensureWithin(target, relPath);
  let text;
  try {
    text = await readFile(absolute, "utf8");
  } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
  try {
    return JSON.parse(text);
  } catch (error) {
    throw actionError(E_ACTION_INVALID, `durable action artifact is not valid JSON: ${relPath}`);
  }
}

export async function validateActionLedgerConsistency(target, { packageRoot, taskId }) {
  const actions = await listActionFiles(target, packageRoot, taskId);
  const { projectActionLedger } = await import("./action-ledger-projection.js");
  const issues = [];
  for (const action of actions) {
    const projection = await projectActionLedger({
      target,
      packageRoot,
      taskId,
      actionId: action.actionId,
      artifact: action,
    });
    if (!projection.valid) {
      for (const error of projection.errors) {
        issues.push({
          actionId: action.actionId,
          code: error.code ?? "E_ACTION_EVIDENCE_INVALID",
          message: error.message,
        });
      }
      continue;
    }
    // Artifact must correspond to a proposed identity in the ledger even when
    // the chronology itself is internally consistent.
    if (projection.state === null) {
      issues.push({ actionId: action.actionId, code: "E_ACTION_EVIDENCE_INVALID", message: `action ${action.actionId} has no matching ACTION_PROPOSED ledger event` });
    }
  }
  return issues;
}

function approvalBindingFields(approval) {
  return {
    taskId: approval.taskId,
    actionId: approval.actionId,
    actionFingerprint: approval.actionFingerprint,
    contractFingerprint: approval.contractFingerprint,
    taskRevision: approval.taskRevision,
    capability: approval.capability,
  };
}

function approvalError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function approvalFingerprint(approval) {
  return canonicalFingerprint(approvalFingerprintPayload(approval));
}

function approvalFingerprintPayload(approval) {
  return {
    ...approvalBindingFields(approval),
    status: approval.status,
    decision: approval.decision ?? null,
    resolvedAt: approval.resolvedAt ?? null,
    authorityKind: approval.authorityKind ?? null,
    hostGrantRef: approval.hostGrantRef ?? null,
  };
}

export function assertApprovalBinding(approval, expectedBinding) {
  if (!expectedBinding || typeof expectedBinding !== "object") {
    throw approvalError(E_APPROVAL_INVALID, "expected binding must be an object");
  }
  for (const [key, value] of Object.entries(approvalBindingFields(approval))) {
    if (expectedBinding[key] !== value) {
      throw approvalError(
        E_APPROVAL_STALE,
        `approval ${approval.approvalId} is stale: bound ${key} does not match the current task/action state`,
      );
    }
  }
  return true;
}

function assertRequestInput(input) {
  if (!input || typeof input !== "object") {
    throw approvalError(E_APPROVAL_INVALID, "approval input must be an object");
  }
  assertApprovalIdFormat(input.approvalId);
  for (const key of ["actionId", "actionFingerprint", "contractFingerprint"]) {
    if (typeof input[key] !== "string" || !input[key]) {
      throw approvalError(E_APPROVAL_INVALID, `approval input.${key} must be a non-empty string`);
    }
  }
  if (!/^[a-f0-9]{64}$/.test(input.actionFingerprint)) {
    throw approvalError(
      E_APPROVAL_INVALID,
      "approval input.actionFingerprint must be a lowercase sha256 hex digest",
    );
  }
  if (!/^[a-f0-9]{64}$/.test(input.contractFingerprint)) {
    throw approvalError(
      E_APPROVAL_INVALID,
      "approval input.contractFingerprint must be a lowercase sha256 hex digest",
    );
  }
  if (!Number.isInteger(input.taskRevision) || input.taskRevision < 0) {
    throw approvalError(E_APPROVAL_INVALID, "approval input.taskRevision must be a non-negative integer");
  }
  if (input.reason !== undefined && input.reason !== null && (typeof input.reason !== "string" || input.reason.length > 512)) {
    throw approvalError(E_APPROVAL_INVALID, "approval input.reason must be a string of at most 512 characters");
  }
}

export async function listApprovals(target, { packageRoot, taskId }) {
  const approvals = await listApprovalFiles(target, taskId);
  return approvals.map((approval) => validateApprovalArtifact(approval));
}

export async function readApproval(target, { packageRoot, taskId, approvalId }) {
  const approval = await readApprovalFile(target, taskId, approvalId);
  if (!approval) {
    throw approvalError(E_ACTION_NOT_FOUND, `approval ${approvalId} does not exist for task ${taskId}`);
  }
  return validateApprovalArtifact(approval);
}

async function readApprovalFile(target, taskId, approvalId) {
  const relPath = taskApprovalPath(taskId, approvalId);
  await assertSafePath(target, relPath);
  let text;
  try {
    text = await readFile(ensureWithin(target, relPath), "utf8");
  } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
  try {
    return JSON.parse(text);
  } catch {
    throw approvalError(E_APPROVAL_INVALID, `approval artifact is not valid JSON: ${relPath}`);
  }
}

export async function validateBoundApprovalFingerprint(target, {
  packageRoot,
  taskId,
  approvalId,
  expectedFingerprint,
}) {
  if (
    typeof expectedFingerprint !== "string"
    || !/^[a-f0-9]{64}$/.test(expectedFingerprint)
  ) {
    throw approvalError(
      E_APPROVAL_INVALID,
      "expected approval fingerprint must be a lowercase sha256 hex digest",
    );
  }

  const approval = await readApproval(target, {
    packageRoot,
    taskId,
    approvalId,
  });

  const actualFingerprint = approvalFingerprint(approval);

  if (actualFingerprint !== expectedFingerprint) {
    throw approvalError(
      E_APPROVAL_INVALID,
      `approval ${approvalId} no longer matches the fingerprint bound at action authorization`,
    );
  }

  return {
    approval,
    fingerprint: actualFingerprint,
  };
}

function changedPathNames(entry) {
  return [entry.path, entry.sourcePath].filter(Boolean);
}

export function assertAttestationStatementBindings(statement, manifest, taskId, manifestFingerprint = canonicalFingerprint(manifest)) {
  const predicate = statement.predicate;
  if (predicate.task.taskId !== taskId || predicate.task.verificationCycle !== manifest.verificationCycle) {
    throw verifierError("E_ATTESTATION_SCOPE_MISMATCH", "Attestation statement task or verification cycle does not match the manifest");
  }
  if (predicate.content.manifestFingerprint !== manifestFingerprint) {
    throw verifierError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement does not bind the current code manifest");
  }
  if (predicate.content.contentDigest !== manifest.contentDigest) {
    throw verifierError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject does not bind the manifest content digest");
  }
  const expectedPaths = [...new Set(manifest.entries.flatMap((entry) => [entry.path, entry.sourcePath].filter(Boolean)))].sort();
  const actualPaths = [...new Set(predicate.content.coveredPaths)].sort();
  if (JSON.stringify(expectedPaths) !== JSON.stringify(actualPaths)) {
    throw verifierError("E_ATTESTATION_SCOPE_MISMATCH", "Statement covered paths do not match the manifest");
  }
  const bindingPairs = [
    ["contractFingerprint", "E_ATTESTATION_CONTRACT_MISMATCH"],
    ["routeFingerprint", "E_ATTESTATION_ROUTE_MISMATCH"],
    ["stateFingerprint", "E_ATTESTATION_STATE_MISMATCH"],
    ["receiptFingerprint", "E_ATTESTATION_RECEIPT_MISMATCH"],
    ["ledgerSeq", "E_ATTESTATION_LEDGER_MISMATCH"],
    ["ledgerHash", "E_ATTESTATION_LEDGER_MISMATCH"],
  ];
  for (const [key, code] of bindingPairs) {
    if (predicate.evidence[key] !== manifest.bindings[key]) {
      throw verifierError(code, `Statement evidence does not match the manifest binding: ${key}`);
    }
  }
}

function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function verifierError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "AttestationVerificationError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function verifyAttestation({
  target,
  packageRoot = getPackageRoot(),
  taskId,
  revision = null,
  bundlePath = null,
  identity = null,
  issuer = null,
  revisionProvider = null,
  signingProvider = null,
  trustedRoot = null,
  requireSignature = false,
} = {}) {
  let effectiveRequireSignature = requireSignature === true;
  let effectiveSigningProvider = signingProvider;
  let effectiveBundlePath = bundlePath;
  let configuredPolicy = {};
  let configurationError = null;
  try {
    const { readConfig } = await import("./config.js");
    const config = await readConfig(target, packageRoot);
    const signing = config.attestation?.signing ?? {};
    effectiveRequireSignature ||= signing.required === true;
    effectiveSigningProvider ??= signing.provider;
    configuredPolicy = signing.policy ?? {};
  } catch (error) {
    if (error.code !== "ARTIFACT_MISSING") configurationError = error;
  }
  if (effectiveRequireSignature && !effectiveBundlePath) effectiveBundlePath = taskAttestationBundlePath(taskId);
  const result = {
    schemaVersion: 1,
    status: "INVALID",
    level: "PROCESSED",
    taskId,
    revisionProvider: typeof revisionProvider === "string" ? revisionProvider : "git",
    revision: revision ?? null,
    content: { status: "NOT_CHECKED", checkedPaths: 0 },
    receipt: "NOT_CHECKED",
    statement: "NOT_CHECKED",
    ledger: "NOT_CHECKED",
    signature: { required: effectiveRequireSignature, status: effectiveRequireSignature ? "UNAVAILABLE" : "NOT_CHECKED" },
    errors: [],
  };
  if (configurationError) {
    result.errors.push({ code: E_ATTESTATION_CONFIGURATION_INVALID, message: configurationError.message });
    return result;
  }
  try {
    const statementArtifact = await readAttestationStatement({ target, packageRoot, taskId });
    const manifestArtifact = await readCodeManifest({ target, packageRoot, taskId });
    await validateAttestationStatement(statementArtifact.value, packageRoot);
    result.statement = "VALID";
    result.ledger = "VALID";
    result.receipt = "VALID";
    assertAttestationStatementBindings(
      statementArtifact.value,
      manifestArtifact.value,
      taskId,
      manifestArtifact.fingerprint,
    );
    const provider = typeof revisionProvider === "string"
      ? await resolveRevisionProvider({ target, providerName: revisionProvider, registry: REVISION_PROVIDERS })
      : revisionProvider ?? await resolveRevisionProvider({ target, providerName: manifestArtifact.value.capture.revisionProvider, registry: REVISION_PROVIDERS });
    result.revisionProvider = provider.name ?? result.revisionProvider;
    await validateCodeManifestBindings({ target, packageRoot, taskId, manifest: manifestArtifact.value, revisionProvider: provider });
    const content = await verifyCodeManifestContent({ target, manifest: manifestArtifact.value, revisionProvider: provider, revision });
    result.revision = content.revision;
    result.content = { status: "VALID", checkedPaths: content.results.length };
    const signingPolicy = {
      ...configuredPolicy,
      identity,
      issuer,
      ...(trustedRoot ? { trustedRoot } : {}),
    };
    if (effectiveRequireSignature && !(await fileExists(ensureWithin(target, effectiveBundlePath)))) {
      throw verifierError("E_ATTESTATION_UNSIGNED", `Required attestation signature bundle is missing: ${effectiveBundlePath}`);
    }
    const signer = typeof effectiveSigningProvider === "object"
      ? assertSigningProvider(effectiveSigningProvider)
      : await resolveSigningProvider({
        providerName: effectiveSigningProvider ?? (effectiveBundlePath ? "sigstore" : "none"),
        registry: SIGNING_PROVIDERS,
      });
    const signature = await signer.verify({
      target,
      statementPath: taskAttestationStatementPath(taskId),
      bundlePath: effectiveBundlePath,
      policy: signingPolicy,
    });
    result.signature = {
      required: effectiveRequireSignature,
      status: signature.status,
      provider: signer.name,
      ...(identity ? { identity } : {}),
      ...(issuer ? { issuer } : {}),
    };
    if (effectiveRequireSignature && signature.status !== "VALID") {
      throw verifierError(signature.code ?? "E_ATTESTATION_SIGNATURE_INVALID", signature.message ?? "Required signature is not valid");
    }
    result.status = "VALID";
    result.level = signature.status === "VALID" ? "ATTESTED" : "VERIFIED";
    return result;
  } catch (error) {
    result.errors.push({ code: error.code ?? "E_ATTESTATION_STATEMENT_INVALID", message: error.message, ...(error.artifacts ? { artifacts: error.artifacts } : {}) });
    return result;
  }
}

export async function verifyCodeManifestContent({ target, manifest, revisionProvider, revision = null } = {}) {
  const provider = typeof revisionProvider === "string"
    ? await resolveRevisionProvider({ target, providerName: revisionProvider, registry: REVISION_PROVIDERS })
    : revisionProvider;
  assertRevisionProvider(provider);
  const targetRevision = revision ?? (manifest.capture.mode === "WORKTREE" ? "WORKTREE" : manifest.capture.observedRevision);
  const results = [];
  for (const entry of manifest.entries) {
    results.push({ path: entry.path, ...(await verifyEntryContent(provider, { target, revision: targetRevision }, entry)) });
  }
  return { valid: true, revision: targetRevision, results, provider };
}

async function verifyEntryContent(provider, { target, revision }, entry) {
  if (entry.kind === "DELETED" || entry.operation === "DELETED") {
    try {
      await provider.readContent({ target, revision, path: entry.path });
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Deleted path exists at revision ${revision}: ${entry.path}`);
    } catch (error) {
      if (error.code === "E_ATTESTATION_CONTENT_MISMATCH") throw error;
      if (error.notFound === true) return { valid: true };
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Unable to prove that deleted path is absent at revision ${revision}: ${entry.path}`, [entry.path]);
    }
  }
  if (entry.kind === "GITLINK") {
    let identity;
    try {
      identity = await provider.getContentIdentity({ target, revision, path: entry.path });
    } catch (error) {
      if (error.notFound === true) throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Gitlink is absent at revision ${revision}: ${entry.path}`, [entry.path]);
      throw error;
    }
    if (identity !== entry.providerContentId) {
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Gitlink identity differs from the attested snapshot: ${entry.path}`, [entry.path]);
    }
    return { valid: true, actualIdentity: identity };
  }
  let bytes;
  try {
    bytes = await provider.readContent({ target, revision, path: entry.path });
  } catch (error) {
    if (error.code?.startsWith("E_REVISION_") && error.notFound !== true) throw error;
    throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Attested path cannot be read at revision ${revision}: ${entry.path}`, [entry.path]);
  }
  const actualDigest = sha256(bytes);
  if (actualDigest !== entry.sha256) {
    throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Current source content differs from the attested snapshot: ${entry.path}`, [entry.path]);
  }
  if (entry.providerContentId) {
    let actualIdentity;
    try {
      actualIdentity = await provider.getContentIdentity({ target, revision, path: entry.path });
    } catch (error) {
      if (error.code?.startsWith("E_REVISION_") && error.notFound !== true) throw error;
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Attested provider identity cannot be read at revision ${revision}: ${entry.path}`, [entry.path]);
    }
    if (actualIdentity !== entry.providerContentId) {
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Provider content identity differs from the attested snapshot: ${entry.path}`, [entry.path]);
    }
  }
  return { valid: true, actualDigest };
}

function attestationError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "AttestationError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function resolveAttestationStatus({ target, packageRoot = getPackageRoot(), taskId, revisionProvider = null, bundlePath = null, requireSignature = false, signingProvider = null, signerPolicy = {} } = {}) {
  const result = {
    taskId,
    status: "MISSING",
    level: "PROCESSED",
    content: "NOT_CHECKED",
    receipt: "NOT_CHECKED",
    ledger: "NOT_CHECKED",
    signature: requireSignature ? "REQUIRED" : "NOT_CHECKED",
    signer: null,
    files: 0,
    subject: null,
    errors: [],
  };
  let effectiveRequireSignature = requireSignature === true;
  let effectiveSigningProvider = signingProvider;
  let effectiveSignerPolicy = { ...signerPolicy };
  let effectiveBundlePath = bundlePath;
  try {
    const { readConfig } = await import("./config.js");
    const config = await readConfig(target, packageRoot);
    const configuredSigning = config.attestation?.signing ?? {};
    effectiveRequireSignature ||= configuredSigning.required === true;
    effectiveSigningProvider ??= configuredSigning.provider;
    effectiveSignerPolicy = {
      ...(configuredSigning.policy ?? {}),
      ...signerPolicy,
    };
    if (effectiveRequireSignature && !effectiveBundlePath) effectiveBundlePath = taskAttestationBundlePath(taskId);
    result.signature = effectiveRequireSignature ? "REQUIRED" : "NOT_CHECKED";
    if ((config.attestation?.mode ?? "off") === "off" && !bundlePath && !effectiveRequireSignature) {
      result.status = "DISABLED";
      result.level = "PROCESSED";
      result.signature = "NOT_CHECKED";
      return result;
    }
  } catch (error) {
    if (error.code !== "ARTIFACT_MISSING") {
      result.status = "INVALID";
      result.errors.push({ code: E_ATTESTATION_CONFIGURATION_INVALID, message: error.message });
      return result;
    }
  }
  result.signature = effectiveRequireSignature ? "REQUIRED" : "NOT_CHECKED";
  if (effectiveRequireSignature && !effectiveBundlePath) effectiveBundlePath = taskAttestationBundlePath(taskId);
  try {
    const statement = await readAttestationStatement({ target, packageRoot, taskId });
    const manifest = await readCodeManifest({ target, packageRoot, taskId });
    const provider = revisionProvider ?? manifest.value.capture.revisionProvider;
    await validateCodeManifestBindings({ target, packageRoot, taskId, manifest: manifest.value, revisionProvider: provider });
    const { assertAttestationStatementBindings, verifyCodeManifestContent } = await import("./attestation-verifier.js");
    assertAttestationStatementBindings(statement.value, manifest.value, taskId, manifest.fingerprint);
    await verifyCodeManifestContent({
      target,
      manifest: manifest.value,
      revisionProvider: provider,
      revision: manifest.value.capture.mode === "WORKTREE" ? "WORKTREE" : manifest.value.capture.observedRevision,
    });
    result.status = "VALID";
    result.level = "VERIFIED";
    result.content = "VALID";
    result.receipt = "VALID";
    result.ledger = "VALID";
    result.files = statement.value.predicate.content.coveredPaths.length;
    result.subject = `sha256:${statement.value.subject[0].digest.sha256}`;
    if (effectiveRequireSignature && !(await fileExists(ensureWithin(target, effectiveBundlePath)))) {
      result.signature = "UNSIGNED";
      result.status = "INVALID";
      result.errors.push({ code: "E_ATTESTATION_UNSIGNED", message: `Required attestation signature bundle is missing: ${effectiveBundlePath}` });
      return result;
    }
    if (effectiveBundlePath) {
      const { assertSigningProvider, resolveSigningProvider } = await import("./signing/provider.js");
      const { SIGNING_PROVIDERS } = await import("./signing/registry.js");
      const signer = typeof effectiveSigningProvider === "object"
        ? assertSigningProvider(effectiveSigningProvider)
        : await resolveSigningProvider({ providerName: effectiveSigningProvider ?? effectiveSignerPolicy.provider ?? (effectiveBundlePath ? "sigstore" : "none"), registry: SIGNING_PROVIDERS });
      const verified = await signer.verify({ target, statementPath: taskAttestationStatementPath(taskId), bundlePath: effectiveBundlePath, policy: effectiveSignerPolicy });
      result.signature = verified.status;
      result.signer = verified.signer ?? null;
      if (verified.status === "VALID") result.level = "ATTESTED";
      else if (effectiveRequireSignature) {
        result.status = "INVALID";
        result.errors.push({ code: verified.code ?? (verified.status === "UNSIGNED" ? "E_ATTESTATION_UNSIGNED" : "E_ATTESTATION_SIGNATURE_INVALID"), message: verified.message ?? "Signature verification failed" });
      }
    }
  } catch (error) {
    if (["E_ATTESTATION_STATEMENT_MISSING", "E_ATTESTATION_MANIFEST_MISSING"].includes(error.code)) {
      result.status = "MISSING";
      result.level = "PROCESSED";
    } else {
      result.status = "INVALID";
    }
    result.errors.push({ code: error.code ?? "E_ATTESTATION_STATEMENT_INVALID", message: error.message });
  }
  return result;
}

export async function validateAttestationPredicate(predicate, packageRoot = getPackageRoot()) {
  try {
    assertSchema(predicate, await readSchema("code-attestation", packageRoot), "ForgeLoop attestation predicate");
    assertSecretFree(predicate);
    return predicate;
  } catch (error) {
    throw attestationError("E_ATTESTATION_STATEMENT_INVALID", error.message);
  }
}

export async function validateAttestationStatement(statement, packageRoot = getPackageRoot()) {
  try {
    assertSchema(statement, await readSchema("in-toto-statement", packageRoot), "in-toto statement");
    if (statement._type !== STATEMENT_TYPE || statement.predicateType !== PREDICATE_TYPE) {
      throw attestationError("E_ATTESTATION_STATEMENT_INVALID", "Statement type or predicate type is not the ForgeLoop v1 contract");
    }
    await validateAttestationPredicate(statement.predicate, packageRoot);
    const subject = statement.subject[0];
    if (subject.name !== `forgeloop-task:${statement.predicate.task.taskId}`) {
      throw attestationError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject does not match the attested task");
    }
    if (subject.digest.sha256 !== statement.predicate.content.contentDigest) {
      throw attestationError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject digest does not match the predicate content digest");
    }
    assertSecretFree(statement);
    return statement;
  } catch (error) {
    if (error.code?.startsWith("E_ATTESTATION_")) throw error;
    throw attestationError("E_ATTESTATION_STATEMENT_INVALID", error.message);
  }
}

function auditUxError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function buildProjection({ status, audit, report, history, trace, ownership, next, approvals, timeline }) {
  const integrityErrors = [
    ...projectErrors(audit.errors),
    ...projectErrors(trace.integrity.errors),
    ...projectErrors(history.integrity.errors),
    ...projectErrors(ownership.ownershipErrors),
  ];
  const checks = projectChecks(trace);
  const completion = projectCompletion(audit, ownership);
  const reasonCodes = projectReasonCodes(
    status.reasonCodes,
    audit.errors,
    trace.integrity.errors,
    ownership.reasonCodes,
    next.reasonCodes,
  );
  const auditStatus = safeIdentifier(audit.status) ?? "INVALID";
  const reportVerdict = safeIdentifier(report.verdict);
  const traceValid = trace.integrity.valid === true;
  const historyValid = history.integrity.valid === true;
  return {
    schemaVersion: AUDIT_UX_SCHEMA_VERSION,
    protocolVersion: trace.protocolVersion,
    taskId: trace.task.id,
    readOnly: true,
    authority: {
      readOnly: true,
      lifecycleAuthority: false,
      evidenceAuthority: false,
      completionAuthority: false,
      mutationAuthority: false,
      externalExecution: false,
    },
    health: {
      phase: safePhase(status.phase ?? trace.task.phase),
      protocolValid: status.protocol?.status === "VALID",
      auditStatus,
      reportVerdict,
      completionStatus: completion.valid ? "VALID" : "INCOMPLETE",
      ownershipValid: ownership.ownershipValid === true,
      claimState: safeIdentifier(ownership.claimState),
      mutationAllowed: ownership.mutationAllowed === true,
      recoveryStatus: safeIdentifier(ownership.recoveryStatus),
      currentNextAction: safeIdentifier(next.nextAction),
      historyQuality: safeIdentifier(history.historyQuality.level),
      traceIntegrity: traceValid,
      reasonCodes,
    },
    lifecycle: {
      phase: safePhase(trace.task.phase),
      status: safeIdentifier(trace.task.status),
      revision: Number.isInteger(trace.task.revision) ? trace.task.revision : null,
      verificationCycle: Number.isInteger(trace.task.verificationCycle) ? trace.task.verificationCycle : null,
      nextAction: safeIdentifier(next.nextAction),
      terminal: next.terminal === true,
    },
    timeline,
    verification: {
      checks,
      checkCount: trace.checks.length,
      totalAttempts: trace.checks.reduce((total, check) => total + check.attemptCount, 0),
      failedAttempts: trace.checks.reduce((total, check) => total + check.failedAttempts, 0),
      coverage: completion.coverage,
    },
    ownership: {
      claimState: safeIdentifier(ownership.claimState),
      ownershipValid: ownership.ownershipValid === true,
      mutationAllowed: ownership.mutationAllowed === true,
      recoveryStatus: safeIdentifier(ownership.recoveryStatus),
      historicalWriteClaims: ownership.historicalWriteClaims.slice(0, AUDIT_UX_LIMITS.maxActions).map(safeText).filter(Boolean),
      effectiveWriteClaims: ownership.effectiveWriteClaims.slice(0, AUDIT_UX_LIMITS.maxActions).map(safeText).filter(Boolean),
      reasonCodes: projectReasonCodes(ownership.reasonCodes, ownership.ownershipErrors),
    },
    diagnostics: projectDiagnostics(trace),
    completion,
    integrity: {
      valid: auditStatus === "VALID" && traceValid && historyValid,
      auditStatus,
      traceValid,
      historyValid,
      reasonCodes: projectReasonCodes(integrityErrors),
    },
    history: {
      quality: safeIdentifier(history.historyQuality.level),
      totalEventCount: history.summary.totalEventCount,
      returnedEventCount: timeline.items.length,
      truncated: timeline.truncated,
    },
    actions: {
      ...projectActions(trace.actions),
      bounded: trace.actions.total > AUDIT_UX_LIMITS.maxActions,
    },
    approvals: projectApprovals(approvals),
    recovery: {
      active: ownership.recoveryStatus === "RELEASED_BY_RECOVERY",
      status: safeIdentifier(ownership.recoveryStatus),
      events: trace.recovery.slice(0, AUDIT_UX_LIMITS.maxDiagnostics).map((event) => ({
        sequence: event.sequence,
        timestamp: typeof event.at === "string" ? event.at : null,
        kind: safeIdentifier(event.type),
      })),
    },
    links: {
      status: "task/status",
      ownership: "task/ownership",
      contract: "task/contract",
      auditView: "task/audit-view",
    },
  };
}

function normalizeOptions(options = {}) {
  const limit = options.limit === undefined ? 100 : options.limit;
  if (!Number.isInteger(limit) || limit < 1 || limit > AUDIT_UX_LIMITS.maxTimelineItems) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", `limit must be an integer between 1 and ${AUDIT_UX_LIMITS.maxTimelineItems}`);
  }
  for (const key of ["beforeSequence", "afterSequence"]) {
    if (options[key] !== undefined && (!Number.isInteger(options[key]) || options[key] < 0)) {
      throw auditUxError("E_AUDIT_UX_INPUT_INVALID", `${key} must be a non-negative integer`);
    }
  }
  if (options.beforeSequence !== undefined && options.afterSequence !== undefined) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "beforeSequence and afterSequence cannot be combined");
  }
  let categories = options.categories ?? [];
  if (typeof categories === "string") categories = categories.split(",").map((value) => value.trim()).filter(Boolean);
  if (!Array.isArray(categories) || categories.length > AUDIT_UX_CATEGORIES.length) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "categories must be a bounded array of category names");
  }
  const normalizedCategories = uniqueStrings(categories.map((value) => String(value).toUpperCase()));
  if (normalizedCategories.some((category) => !AUDIT_UX_CATEGORIES.includes(category))) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "categories contains an unknown audit timeline category");
  }
  return {
    limit,
    beforeSequence: options.beforeSequence,
    afterSequence: options.afterSequence,
    categories: normalizedCategories,
  };
}

function projectTimeline(events, options) {
  const filtered = events
    .filter((event) => options.beforeSequence === undefined || event.sequence < options.beforeSequence)
    .filter((event) => options.afterSequence === undefined || event.sequence > options.afterSequence)
    .filter((event) => options.categories.length === 0 || options.categories.includes(categoryForEvent(event)))
    .sort((left, right) => left.sequence - right.sequence);
  const hasMore = filtered.length > options.limit;
  const page = hasMore && options.afterSequence === undefined
    ? filtered.slice(-options.limit)
    : filtered.slice(0, options.limit);
  const items = page.map(timelineItem);
  return {
    items,
    totalAvailable: filtered.length,
    truncated: hasMore,
    cursor: {
      beforeSequence: options.beforeSequence ?? null,
      afterSequence: options.afterSequence ?? null,
      nextBeforeSequence: hasMore && options.afterSequence === undefined ? items[0]?.sequence ?? null : null,
      nextAfterSequence: hasMore && options.afterSequence !== undefined ? items.at(-1)?.sequence ?? null : null,
    },
  };
}

async function evaluateLocalAttestation({ target, packageRoot, taskId, completion }) {
  const configured = completion.attestation ?? { mode: "off" };
  const base = {
    mode: configured.mode ?? "off",
    manifest: configured.mode === "off" ? "NOT_CHECKED" : configured.status === "CAPTURED" ? "VALID" : configured.status ?? "MISSING",
    statement: "NOT_CHECKED",
    signature: "NOT_CHECKED",
    coverage: "NOT_CHECKED",
    errors: [],
  };
  if (configured.mode === "off") return { ...base, status: "DISABLED" };
  if (configured.status !== "CAPTURED") {
    return { ...base, status: configured.status === "UNAVAILABLE" ? "UNAVAILABLE" : "MISSING" };
  }

  let manifest;
  try {
    manifest = await readCodeManifest({ target, packageRoot, taskId });
    await verifyCodeManifestContent({
      target,
      manifest: manifest.value,
      revisionProvider: manifest.value.capture.revisionProvider,
      revision: manifest.value.capture.mode === "WORKTREE" ? "WORKTREE" : manifest.value.capture.observedRevision,
    });
    base.coverage = "VALID";
  } catch (error) {
    base.manifest = "INVALID";
    base.status = "INVALID";
    base.errors.push({ code: error.code ?? "E_ATTESTATION_CONTENT_MISMATCH", message: error.message });
    return base;
  }

  try {
    const statement = await readAttestationStatement({ target, packageRoot, taskId });
    await validateAttestationStatement(statement.value, packageRoot);
    assertAttestationStatementBindings(statement.value, manifest.value, taskId, manifest.fingerprint);
    base.statement = "VALID";
  } catch (error) {
    if (error.code === "E_ATTESTATION_STATEMENT_MISSING") {
      return { ...base, status: "VALID" };
    }
    base.statement = "INVALID";
    base.status = "INVALID";
    base.errors.push({ code: error.code ?? "E_ATTESTATION_STATEMENT_INVALID", message: error.message });
    return base;
  }
  return { ...base, status: "VALID" };
}

function sortErrors(errors) {
  return [...errors].sort((left, right) => left.code.localeCompare(right.code)
    || left.message.localeCompare(right.message));
}

function assertBundledCodeManifestBindings({ loaded, ledger, taskId }) {
  const manifest = loaded.codeManifest;
  if (!manifest) return;
  const comparisons = [
    ["taskId", manifest.taskId, taskId, "E_BUNDLE_TASK_MISMATCH"],
    ["contractFingerprint", manifest.bindings.contractFingerprint, loaded.contract ? canonicalFingerprint(loaded.contract) : null, "E_ATTESTATION_CONTRACT_MISMATCH"],
    ["routeFingerprint", manifest.bindings.routeFingerprint, loaded.route ? canonicalFingerprint(loaded.route) : null, "E_ATTESTATION_ROUTE_MISMATCH"],
    ["stateFingerprint", manifest.bindings.stateFingerprint, loaded.state ? canonicalFingerprint(loaded.state) : null, "E_ATTESTATION_STATE_MISMATCH"],
    ["receiptFingerprint", manifest.bindings.receiptFingerprint, loaded.receipt ? canonicalFingerprint(loaded.receipt) : null, "E_ATTESTATION_RECEIPT_MISMATCH"],
  ];
  for (const [name, expected, actual, code] of comparisons) {
    if (expected !== actual) throw bundleBindingError(code, `Bundled code manifest binding does not match ${name}`);
  }
  if (!ledger?.valid) {
    throw bundleBindingError("E_ATTESTATION_LEDGER_MISMATCH", "A valid bundled event ledger is required by the code manifest");
  }
  const completion = ledger.events.findLast((event) => event.taskId === taskId && event.event === "COMPLETION_VALIDATED");
  if (!completion || completion.seq !== manifest.bindings.ledgerSeq || completion.hash !== manifest.bindings.ledgerHash) {
    throw bundleBindingError("E_ATTESTATION_LEDGER_MISMATCH", "Bundled code manifest does not match the COMPLETION_VALIDATED ledger checkpoint");
  }
}

function assertStructuralQualityBundleEvidence({ loaded, manifest, taskId }) {
  const quality = loaded.structuralQuality;
  if (!quality) return;
  const baseline = quality.baseline;
  const evaluations = quality.evaluations ?? [];
  const qualityArtifacts = new Map();
  if (baseline) qualityArtifacts.set("structural-quality/baseline.json", baseline);
  for (const evaluation of evaluations) {
    const name = `structural-quality/evaluations/cycle-${evaluation.verificationCycle}-attempt-${evaluation.attempt}.json`;
    qualityArtifacts.set(name, evaluation);
  }
  for (const value of [baseline, ...evaluations].filter(Boolean)) {
    if (value.taskId !== taskId) throw bundleBindingError("E_BUNDLE_TASK_MISMATCH", "Structural-quality artifact taskId does not match its bundle task");
    const bindingErrors = validateStructuralQualityBindings(value);
    if (bindingErrors.length > 0) throw bundleBindingError(bindingErrors[0].code, bindingErrors[0].message);
  }
  const baselineFingerprint = baseline ? canonicalFingerprint(baseline) : null;
  const bundledConfig = loaded.config?.structuralQuality;
  let policy = null;
  if (bundledConfig) policy = normalizeStructuralQualityConfig(bundledConfig);
  const expectedContractFingerprint = loaded.contract ? canonicalFingerprint(loaded.contract) : null;
  const expectedRouteFingerprint = loaded.route ? canonicalFingerprint(loaded.route) : null;
  for (const value of [baseline, ...evaluations].filter(Boolean)) {
    if (baselineFingerprint && value.role === "EVALUATION" && value.bindings?.baselineFingerprint !== baselineFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality evaluation does not bind the bundled baseline");
    }
    if (policy && value.bindings?.policyFingerprint !== structuralQualityPolicyFingerprint(policy)) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality artifact policy binding does not match bundled configuration");
    }
    if (expectedContractFingerprint && value.bindings?.contractFingerprint !== expectedContractFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality contract binding does not match the bundled contract");
    }
    if (expectedRouteFingerprint && value.bindings?.routeFingerprint !== expectedRouteFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality route binding does not match the bundled route");
    }
  }
  const checks = [
    ...(loaded.state?.checks ?? []),
    ...(loaded.receipt?.checks ?? []),
  ].filter((check) => check?.kind === "structural-quality");
  for (const check of checks) {
    const bundleReference = bundleQualityReference(check.details?.artifactRef, taskId);
    const value = qualityArtifacts.get(bundleReference);
    if (!value) throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check references missing ${bundleReference}`);
    if (check.details?.artifactFingerprint !== canonicalFingerprint(value)) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check fingerprint does not match ${bundleReference}`);
    }
    const expected = structuralQualityCheckProjection(value);
    if (check.status !== expected.status || check.evidenceKind !== expected.evidenceKind) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check does not match ${bundleReference}`);
    }
  }
  for (const artifact of manifest.artifacts.filter((item) => item.startsWith("structural-quality/"))) {
    if (!qualityArtifacts.has(artifact)) throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality manifest entry was not loaded: ${artifact}`);
  }
}

function bundleBindingError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function bundleDirectory(taskId) {
  return `${BUNDLE_ROOT}/${safeTaskId(taskId)}`;
}

function bundleQualityReference(reference, taskId) {
  if (typeof reference !== "string" || reference.trim() === "") {
    throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", "Structural-quality check has no artifact reference");
  }
  const normalized = reference.replaceAll("\\", "/");
  const sourceRoot = taskStructuralQualityDirectory(taskId).replaceAll("\\", "/");
  const suffix = normalized.startsWith(`${sourceRoot}/`)
    ? normalized.slice(sourceRoot.length + 1)
    : normalized.startsWith("structural-quality/")
      ? normalized.slice("structural-quality/".length)
      : null;
  if (!suffix || !(suffix === "baseline.json" || /^evaluations\/cycle-\d+-attempt-\d+\.json$/u.test(suffix))) {
    throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", "Structural-quality artifact reference escapes its task quality directory");
  }
  return `structural-quality/${suffix}`;
}

async function copyOptionalJson(target, taskPath, legacyPath, destinationPath, schemaName, packageRoot, artifacts, relativeName) {
  const candidates = [taskPath, legacyPath].filter(Boolean);
  for (const sourcePath of candidates) {
    if (!(await fileExists(ensureWithin(target, sourcePath)))) continue;
    return copyJson(target, sourcePath, destinationPath, schemaName, packageRoot, artifacts, relativeName);
  }
  return null;
}

async function copyRawFile(target, sourcePath, destinationPath, artifacts, relativeName) {
  if (!(await fileExists(ensureWithin(target, sourcePath)))) return false;
  await assertSafePath(target, destinationPath);
  await writeFileAtomic(ensureWithin(target, destinationPath), await readBytes(ensureWithin(target, sourcePath)));
  artifacts.push(relativeName);
  return true;
}

function safeTaskId(taskId) {
  if (typeof taskId !== "string" || !/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(taskId)) {
    const error = new Error(`Invalid task ID for bundle: ${taskId}`);
    error.code = "E_BUNDLE_PATH_INVALID";
    throw error;
  }
  return taskId;
}

function structuralQualityBundleKind(artifact) {
  if (artifact === "structural-quality/baseline.json") return "baseline";
  if (/^structural-quality\/evaluations\/cycle-\d+-attempt-\d+\.json$/u.test(artifact)) return "evaluation";
  if (artifact.startsWith("structural-quality/")) {
    throw bundleBindingError("E_BUNDLE_PATH_INVALID", `Unknown structural-quality bundle artifact: ${artifact}`);
  }
  return null;
}

function structuralQualityCheckProjection(value) {
  if (value.status === "PASS") return { status: "passed", evidenceKind: "OBSERVED" };
  if (value.status === "FAIL") return { status: "failed", evidenceKind: "OBSERVED" };
  if (value.status === "BLOCKED") return { status: "blocked", evidenceKind: "BLOCKED" };
  return { status: "not-run", evidenceKind: "NOT_VERIFIED" };
}

export function isTrustedHostAuthorityContext(authorityContext) {
  // Only a genuine host-controlled trust boundary may satisfy
  // REQUIRE_AUTHORITY. A project-local file, environment-selected source,
  // CLI flag, or transport session can never promote itself to HOST_ATTESTED.
  if (!authorityContext || typeof authorityContext !== "object") return false;
  if (authorityContext.trustMode !== "HOST_ATTESTED") return false;
  const source = typeof authorityContext.source === "string" ? authorityContext.source : "";
  const forbiddenSources = ["project-local-file", "environment", "cli-flag", "transport-session"];
  if (forbiddenSources.includes(source)) return false;
  return authorityContext.hostSupplied === true && source === "host-boundary";
}

export async function loadCapabilityPolicy(target, packageRoot) {
  const relativePath = PROJECT_ARTIFACT_PATHS.capabilityPolicy;
  await assertSafePath(target, relativePath);
  const absolutePath = ensureWithin(target, relativePath);
  if (!(await fileExists(absolutePath))) {
    return null;
  }
  let parsed;
  try {
    const { readFile } = await import("node:fs/promises");
    parsed = JSON.parse(await readFile(absolutePath, "utf8"));
  } catch (error) {
    throw policyError(E_POLICY_INVALID, `capability policy is not valid JSON: ${error.message}`);
  }
  for (const key of Object.keys(parsed ?? {})) {
    if (!ALLOWED_POLICY_PROPERTIES.has(key)) {
      throw policyError(
        E_POLICY_INVALID,
        `capability policy.${key} is not an allowed property; project-local policy can never declare authority or trust metadata`,
      );
    }
  }
  validateCapabilityPolicy(parsed);
  return {
    policy: parsed,
    fingerprint: canonicalFingerprint(parsed),
    path: relativePath,
  };
}

function policyError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export async function readCapabilityPolicyIdentity(target, packageRoot) {
  const loaded = await loadCapabilityPolicy(target, packageRoot);
  if (!loaded) {
    return {
      policy: null,
      fingerprint: null,
      digest: null,
    };
  }
  return {
    policy: loaded.policy,
    fingerprint: loaded.fingerprint,
    digest: `sha256:${sha256(canonicalFingerprint(loaded.policy))}`,
  };
}

export function assertCheckpointRevalidatedDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)
    || Object.keys(details).length !== REVALIDATION_DETAIL_KEYS.length
    || REVALIDATION_DETAIL_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(details, key))) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} requires its exact state-transition detail set`);
  }
  if (!CHECKPOINT_REVALIDATION_PHASES.includes(details.phase)) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.phase is unsupported`);
  }
  assertRepositoryFingerprint(details.previousRepositoryFingerprint, `${CHECKPOINT_REVALIDATED_EVENT} details.previousRepositoryFingerprint`);
  assertRepositoryFingerprint(details.repositoryFingerprint, `${CHECKPOINT_REVALIDATED_EVENT} details.repositoryFingerprint`, { requireHead: true });
  if (JSON.stringify(details.previousRepositoryFingerprint) === JSON.stringify(details.repositoryFingerprint)) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} must record repository drift`);
  }
  for (const key of ["contractFingerprint", "routeFingerprint", "previousStateFingerprint", "revalidatedStateFingerprint"]) {
    if (!isFingerprint(details[key])) throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  for (const key of ["previousStateRevision", "revalidatedStateRevision"]) {
    if (!Number.isInteger(details[key]) || details[key] < 0) {
      throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.${key} must be a non-negative integer`);
    }
  }
  if (details.revalidatedStateRevision !== details.previousStateRevision + 1) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} state revisions must advance exactly once`);
  }
  return details;
}

export function assertRepositoryFingerprint(value, label = "repository fingerprint", { requireHead = false } = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || Object.keys(value).length !== REPOSITORY_FINGERPRINT_KEYS.length
    || REPOSITORY_FINGERPRINT_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(value, key))) {
    throw invalid(`${label} must contain exactly branch and head`);
  }
  for (const key of REPOSITORY_FINGERPRINT_KEYS) {
    if (value[key] !== null && (typeof value[key] !== "string" || !value[key].trim())) {
      throw invalid(`${label}.${key} must be a non-empty string or null`);
    }
  }
  if (requireHead && typeof value.head !== "string") {
    throw invalid(`${label}.head must be available`);
  }
  return value;
}

export function validateCheckpointRevalidationEventBindings(events = []) {
  const errors = [];
  const revalidations = events.filter((event) => event.event === CHECKPOINT_REVALIDATED_EVENT);
  for (let index = 0; index < revalidations.length; index += 1) {
    const event = revalidations[index];
    let details;
    try {
      details = assertCheckpointRevalidatedDetails(event.details);
    } catch (error) {
      errors.push(bindingError(`event ${event.seq}: ${error.message}`));
      continue;
    }
    if (!resolveCheckpointRevalidationBoundary(events, event)) {
      errors.push(bindingError(`event ${event.seq} must be immediately followed by its checkpoint-revalidate transaction commit`));
    }
    const previous = revalidations[index - 1]?.details;
    if (previous) {
      if (!sameRepositoryFingerprint(details.previousRepositoryFingerprint, previous.repositoryFingerprint)) {
        errors.push(bindingError(`event ${event.seq} is disconnected from the previous checkpoint revalidation repository`));
      }
      if (details.previousStateRevision < previous.revalidatedStateRevision) {
        errors.push(bindingError(`event ${event.seq} rolls back the previous checkpoint revalidation revision`));
      }
      if (details.previousStateRevision === previous.revalidatedStateRevision
        && details.previousStateFingerprint !== previous.revalidatedStateFingerprint) {
        errors.push(bindingError(`event ${event.seq} does not continue the previous checkpoint revalidation state fingerprint`));
      }
      const contractEvolved = details.contractFingerprint !== previous.contractFingerprint
        && resolveCanonicalContractEvolution(events, {
          taskId: event.taskId,
          sourceSeq: revalidations[index - 1].seq,
          sourceContractFingerprint: previous.contractFingerprint,
          targetContractFingerprint: details.contractFingerprint,
        });
      if (details.contractFingerprint !== previous.contractFingerprint && !contractEvolved) {
        errors.push(bindingError(`event ${event.seq} changes the checkpoint revalidation contract identity without canonical contract provenance`));
      }
      if (details.routeFingerprint !== previous.routeFingerprint) {
        const evolved = details.previousStateRevision > previous.revalidatedStateRevision
          && routeEvolutionAfter(
            events,
            revalidations[index - 1],
            previous.routeFingerprint,
            details.routeFingerprint,
            details.contractFingerprint,
          );
        if (!evolved) {
          errors.push(bindingError(`event ${event.seq} changes the checkpoint revalidation route identity without canonical route provenance`));
        }
      }
    } else {
      const anchor = resolveEffectiveContractBootstrapRepairAnchor(events);
      if (anchor?.details?.reconstructedStateRevision === details.previousStateRevision
        && anchor.details.reconstructedStateFingerprint !== details.previousStateFingerprint) {
        errors.push(bindingError(`event ${event.seq} does not bind the repaired checkpoint state fingerprint`));
      }
    }
  }
  return errors;
}

export function assertCheck(value, label = "check", options = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw checkError("E_CHECK_INVALID", `${label} must be an object`);
  }
  if (value.schemaVersion !== CHECK_SCHEMA_VERSION || value.protocolVersion !== PROTOCOL_VERSION) {
    throw checkError("E_CHECK_INVALID", `${label} has an unsupported protocol version`);
  }
  string(value.id, `${label}.id`);
  string(value.kind, `${label}.kind`);
  string(value.requirement, `${label}.requirement`);
  string(value.source, `${label}.source`);
  optionalString(value.executionRef, `${label}.executionRef`);
  if (value.provenance !== undefined && !CHECK_PROVENANCE.includes(value.provenance)) {
    throw checkError("E_CHECK_INVALID", `${label}.provenance must be one of ${CHECK_PROVENANCE.join(", ")}`);
  }
  if (options.requireCommandProvenance === true
    && value.kind === "command"
    && value.evidenceKind === "OBSERVED"
    && (value.executionRef === undefined || value.provenance !== "FORGELOOP_EXECUTED")) {
    throw checkError(
      "E_COMMAND_PROVENANCE_UNATTESTED",
      `${label} observed command evidence requires ForgeLoop execution provenance`,
    );
  }
  if (!CHECK_STATUSES.includes(value.status)) {
    throw checkError("E_CHECK_INVALID", `${label}.status must be one of ${CHECK_STATUSES.join(", ")}`);
  }
  if (!CHECK_EVIDENCE_KINDS.includes(value.evidenceKind)) {
    throw checkError("E_EVIDENCE_KIND_INVALID", `${label}.evidenceKind must be one of ${CHECK_EVIDENCE_KINDS.join(", ")}`);
  }
  if (value.exitCode !== undefined && (!Number.isInteger(value.exitCode) || value.exitCode < 0)) {
    throw checkError("E_CHECK_INVALID", `${label}.exitCode must be a non-negative integer`);
  }
  optionalString(value.timestamp, `${label}.timestamp`);
  if (value.status === "passed" && ["NOT_VERIFIED", "BLOCKED"].includes(value.evidenceKind)) {
    throw contradiction(`${label} passed cannot use ${value.evidenceKind} evidence`);
  }
  if (value.status === "passed" && value.exitCode !== undefined && value.exitCode !== 0) {
    throw contradiction(`${label} passed requires exitCode 0 when exitCode is recorded`);
  }
  if (value.status === "blocked" && value.evidenceKind !== "BLOCKED") {
    throw contradiction(`${label} blocked must use BLOCKED evidence`);
  }
  if (value.status === "not-run" && value.evidenceKind !== "NOT_VERIFIED") {
    throw contradiction(`${label} not-run must use NOT_VERIFIED evidence`);
  }
  if (value.status === "passed") {
    const auth = validateVerificationAuthority(value, options);
    if (!auth.valid) {
      throw checkError(auth.error.code, auth.error.message);
    }
  }
  assertCompoundStatus(value, label);
  return value;
}

function assertCompoundStatus(value, label) {
  const components = value.details?.components;
  if (!Array.isArray(components)) return;
  for (const [index, component] of components.entries()) {
    if (!component || typeof component !== "object" || Array.isArray(component)) {
      throw checkError("E_CHECK_INVALID", `${label}.details.components[${index}] must be an object`);
    }
    string(component.requirementId ?? component.requirement, `${label}.details.components[${index}].requirementId`);
    if (!CHECK_STATUSES.includes(component.status) || !CHECK_EVIDENCE_KINDS.includes(component.evidenceKind)) {
      throw checkError("E_CHECK_INVALID", `${label}.details.components[${index}] has invalid status or evidenceKind`);
    }
  }
  if (value.status === "passed" && components.some((component) => (
    component.status !== "passed" || component.evidenceKind !== "OBSERVED"
  ))) {
    throw contradiction(`${label} passed cannot contain an unverified, partial, blocked, or failed component`);
  }
}

function checkError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function contradiction(message) {
  return checkError("E_CHECK_STATUS_CONTRADICTION", message);
}

export function createCheck(input = {}, options = {}) {
  const check = {
    schemaVersion: CHECK_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    id: input.id,
    kind: input.kind,
    requirement: input.requirement,
    status: input.status ?? "not-run",
    evidenceKind: input.evidenceKind ?? "NOT_VERIFIED",
    source: input.source,
    ...(input.exitCode !== undefined ? { exitCode: input.exitCode } : {}),
    ...(input.timestamp !== undefined ? { timestamp: input.timestamp } : {}),
    ...(input.repositoryFingerprint !== undefined ? { repositoryFingerprint: input.repositoryFingerprint } : {}),
    ...(input.viewport !== undefined ? { viewport: structuredClone(input.viewport) } : {}),
    ...(input.executionRef !== undefined ? { executionRef: input.executionRef } : {}),
    ...(input.provenance !== undefined ? { provenance: input.provenance } : {}),
    ...(input.details !== undefined ? { details: structuredClone(input.details) } : {}),
  };
  return assertCheck(check, "check", options);
}

function optionalString(value, label) {
  if (value !== undefined) string(value, label);
}

function string(value, label) {
  if (typeof value !== "string" || value.trim() === "") {
    throw checkError("E_CHECK_INVALID", `${label} must be a non-empty string`);
  }
  return value;
}

function canonicalEntries(entries) {
  if (!Array.isArray(entries)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must be an array");
  const normalized = entries.map((entry, index) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Manifest entry ${index} must be an object`);
    const item = {
      path: normalizedPath(entry.path, `entries[${index}].path`),
      ...(entry.sourcePath !== undefined ? { sourcePath: normalizedPath(entry.sourcePath, `entries[${index}].sourcePath`) } : {}),
      operation: entry.operation,
      kind: entry.kind,
      ...(entry.sha256 !== undefined ? { sha256: entry.sha256 } : {}),
      ...(entry.providerContentId !== undefined ? { providerContentId: entry.providerContentId } : {}),
      ...(entry.providerMetadata !== undefined ? { providerMetadata: entry.providerMetadata } : {}),
    };
    if (!OPERATIONS.has(item.operation) || !KINDS.has(item.kind)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Manifest entry ${index} has an unsupported operation or kind`);
    if (item.operation === "DELETED" && item.kind !== "DELETED") throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} must use kind DELETED`);
    if (item.kind === "DELETED" && item.operation !== "DELETED") throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} must use operation DELETED`);
    if (item.kind === "DELETED" && item.sha256 !== undefined) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} cannot have sha256`);
    if (["FILE", "SYMLINK"].includes(item.kind) && !SHA256.test(item.sha256 ?? "")) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Entry ${item.path} requires a lowercase SHA-256 content digest`);
    if (item.kind === "GITLINK" && (typeof item.providerContentId !== "string" || !item.providerContentId)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Gitlink entry ${item.path} requires providerContentId`);
    if (item.providerMetadata !== undefined && (!item.providerMetadata || typeof item.providerMetadata !== "object" || Array.isArray(item.providerMetadata))) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Entry ${item.path} providerMetadata must be an object`);
    if (item.operation === "RENAMED" && !item.sourcePath) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Renamed entry ${item.path} requires sourcePath`);
    return item;
  });
  const paths = normalized.map((entry) => entry.path);
  if (new Set(paths).size !== paths.length) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must not contain duplicate paths");
  const sorted = [...normalized].sort((left, right) => left.path.localeCompare(right.path));
  if (JSON.stringify(sorted) !== JSON.stringify(normalized)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must be sorted by normalized path");
  return normalized;
}

export function codeManifestContentDigest(entries) {
  return canonicalFingerprint(entries.map((entry) => ({
    path: entry.path,
    sourcePath: entry.sourcePath ?? null,
    operation: entry.operation,
    kind: entry.kind,
    sha256: entry.sha256 ?? null,
    providerContentId: entry.providerContentId ?? null,
    providerMetadata: entry.providerMetadata ?? {},
  })));
}

async function completionCheckpoint(target, packageRoot, taskId, override = null) {
  if (override) {
    if (!Number.isInteger(override.seq) || override.seq < 1 || !SHA256.test(override.hash)) {
      throw manifestError("E_ATTESTATION_LEDGER_MISMATCH", "The candidate completion checkpoint is invalid");
    }
    return { seq: override.seq, hash: override.hash, ledger: null };
  }
  const ledger = await validateEventLedger(target, packageRoot, { taskId });
  const completion = ledger.events.findLast((event) => event.taskId === taskId && event.event === "COMPLETION_VALIDATED");
  if (!ledger.valid || !completion) throw manifestError("E_ATTESTATION_LEDGER_MISMATCH", "A valid COMPLETION_VALIDATED ledger checkpoint is required for a code manifest");
  return { seq: completion.seq, hash: completion.hash, ledger };
}

function digestBytes(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function manifestError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "CodeManifestError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function normalizedPath(value, label = "path") {
  if (typeof value !== "string" || !value || value.startsWith("/") || value === "." || value === ".." || value.startsWith("../")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must be a safe relative path`);
  }
  if (/[\u0000-\u001f\u007f]/u.test(value)) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} contains a control character`);
  }
  if (value.includes("\\")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must use forward slashes`);
  }
  const portable = value;
  const normalized = path.posix.normalize(portable).replace(/^\.\//u, "");
  if (!normalized || normalized === "." || normalized === ".." || normalized.startsWith("../") || normalized.startsWith(".forgeloop/")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} is unsafe or reserved: ${value}`);
  }
  if (normalized !== portable) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must use a normalized relative path: ${value}`);
  }
  return normalized;
}

export async function validateCodeManifest(manifest, packageRoot = getPackageRoot()) {
  try {
    assertSchema(manifest, await readSchema("code-manifest", packageRoot), "code manifest");
    const entries = canonicalEntries(manifest.entries);
    if (manifest.contentDigest !== codeManifestContentDigest(entries)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest contentDigest does not match its entries");
    assertSecretFree(manifest);
    return { ...manifest, entries };
  } catch (error) {
    if (error.code === "E_ATTESTATION_MANIFEST_INVALID") throw error;
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", error.message);
  }
}

export function classifyCommandResolution(commandInput) {
  if (Array.isArray(commandInput)) {
    if (commandInput.length === 0 || commandInput.some((item) => typeof item !== "string" || item.trim() === "")) {
      return { resolutionMode: "UNKNOWN", mayInstall: false, installer: null, tool: null };
    }
    const binary = normalizeExecutableName(commandInput[0]);
    if (["sh", "bash", "zsh", "dash", "ksh"].includes(binary)) {
      const shellFlagIndex = commandInput.findIndex((item, index) => index > 0 && /^-.*c/.test(item));
      const shellCommand = shellFlagIndex >= 0 ? commandInput[shellFlagIndex + 1] : null;
      if (shellCommand) return classifyCommandResolution(shellCommand);
    }
    if (binary === "cmd") {
      const shellFlagIndex = commandInput.findIndex((item, index) => index > 0 && /^\/c$/iu.test(item));
      const shellCommand = shellFlagIndex >= 0 ? commandInput.slice(shellFlagIndex + 1).join(" ") : null;
      if (shellCommand) return classifyCommandResolution(shellCommand);
    }
    return classifySingleCommand(commandInput);
  }

  if (typeof commandInput !== "string" || commandInput.trim() === "") {
    return { resolutionMode: "UNKNOWN", mayInstall: false, installer: null, tool: null };
  }

  const subcommands = splitCommandPipeline(commandInput);
  for (const subcommand of subcommands) {
    const result = classifySingleCommand(subcommand);
    if (result.mayInstall) return result;
  }
  return classifySingleCommand(subcommands[0] || commandInput);
}

async function readPackageJsonIfPresent(cwd) {
  if (!cwd || typeof cwd !== "string") return null;
  try {
    const raw = await fs.readFile(path.resolve(cwd, "package.json"), "utf8");
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export async function resolveExecutionResolution({ argv, cwd } = {}) {
  const direct = classifyCommandResolution(argv);
  if (direct.mayInstall && direct.resolutionMode !== "UNKNOWN") return direct;

  const npmInvocation = parseNpmInvocation(argv);
  const scriptName = getNpmScriptName(argv);
  if (scriptName && (npmInvocation.workspace || npmInvocation.workspaces)) {
    return {
      resolutionMode: "UNKNOWN",
      mayInstall: true,
      installer: "npm-workspace",
      tool: null,
      reason: "NPM_WORKSPACE_SCRIPT_UNRESOLVED",
      dispatch: { kind: "npm-workspace-script", scriptName },
    };
  }

  if (direct.mayInstall) return direct;
  if (!scriptName) return direct;

  const packageJson = await readPackageJsonIfPresent(cwd);
  if (!packageJson || typeof packageJson.scripts !== "object" || packageJson.scripts === null) return direct;

  const nestedRisk = await resolveNpmScriptRisk({ scriptName, packageJson });
  return nestedRisk?.mayInstall ? nestedRisk : direct;
}

async function resolveNpmScriptRisk({ scriptName, packageJson, visited = new Set(), depth = 0 } = {}) {
  if (depth > MAX_NPM_SCRIPT_DEPTH) {
    return { resolutionMode: "UNKNOWN", mayInstall: true, installer: "npm-script", tool: null, reason: "MAX_SCRIPT_DEPTH" };
  }
  if (visited.has(scriptName)) {
    return { resolutionMode: "UNKNOWN", mayInstall: true, installer: "npm-script", tool: null, reason: "SCRIPT_CYCLE" };
  }

  const nextVisited = new Set(visited);
  nextVisited.add(scriptName);
  const candidates = getNpmLifecycleCandidates({ scriptName, scripts: packageJson?.scripts ?? {} });
  for (const candidate of candidates) {
    const scriptBody = packageJson?.scripts?.[candidate];
    if (typeof scriptBody !== "string" || scriptBody.trim() === "") continue;

    const direct = classifyCommandResolution(scriptBody);
    if (direct.mayInstall) {
      return {
        resolutionMode: direct.resolutionMode,
        mayInstall: true,
        installer: direct.installer ?? "npm-script",
        tool: direct.tool,
        dispatch: { kind: "npm-script", scriptName: candidate },
      };
    }

    for (const subcommand of splitCommandPipeline(scriptBody)) {
      const nestedScriptName = getNpmScriptName(subcommand);
      if (!nestedScriptName) continue;
      const nested = await resolveNpmScriptRisk({
        scriptName: nestedScriptName,
        packageJson,
        visited: nextVisited,
        depth: depth + 1,
      });
      if (nested?.mayInstall) return nested;
    }
  }
  return null;
}

export function normalizeExecutableName(binaryToken) {
  const base = binaryToken.split(/[\\/]/u).pop() ?? binaryToken;
  return base.toLowerCase().replace(/\.(?:cmd|bat|exe)$/u, "");
}

export function splitCommandPipeline(commandString) {
  const parts = [];
  let current = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];
    const next = commandString[i + 1];

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      current += char;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      current += char;
    } else if (!inSingleQuote && !inDoubleQuote) {
      if ((char === "&" && next === "&") || (char === "|" && next === "|")) {
        if (current.trim().length > 0) parts.push(current.trim());
        current = "";
        i++;
      } else if (char === ";" || char === "|") {
        if (current.trim().length > 0) parts.push(current.trim());
        current = "";
      } else {
        current += char;
      }
    } else {
      current += char;
    }
  }

  if (current.trim().length > 0) parts.push(current.trim());
  return parts.length > 0 ? parts : [commandString];
}

export function tokenizeCommand(commandString) {
  const tokens = [];
  let current = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (/\s/.test(char) && !inSingleQuote && !inDoubleQuote) {
      if (current.length > 0) {
        tokens.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }

  if (current.length > 0) tokens.push(current);
  return tokens;
}

export function unwrapCommandArgv(argv) {
  if (!Array.isArray(argv) || argv.length === 0) return null;
  let i = 0;
  while (i < argv.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(argv[i])) i++;
  if (i >= argv.length) return null;
  const binary = normalizeExecutableName(argv[i]);
  if (["sh", "bash", "zsh", "dash", "ksh"].includes(binary)) {
    const shellFlagIndex = argv.findIndex((item, index) => index > i && /^-.*c/.test(item));
    const shellCommand = shellFlagIndex >= 0 ? argv[shellFlagIndex + 1] : null;
    if (shellCommand) return tokenizeCommand(shellCommand);
  }
  if (binary === "cmd") {
    const shellFlagIndex = argv.findIndex((item, index) => index > i && /^\/c$/iu.test(item));
    const shellCommand = shellFlagIndex >= 0 ? argv.slice(shellFlagIndex + 1).join(" ") : null;
    if (shellCommand) return tokenizeCommand(shellCommand);
  }
  if (binary === "call") return argv.slice(i + 1);
  return argv.slice(i);
}

async function actionReceiptSummary(target, packageRoot, taskId) {
  const actions = await listActions(target, { packageRoot, taskId });
  return {
    count: actions.length,
    required: actions.filter((action) => action.requiredForCompletion).length,
    verified: actions.filter((action) => action.state === "VERIFIED").length,
    failed: actions.filter((action) => action.state === "FAILED").length,
    ambiguous: actions.filter((action) => action.state === "COMMIT_UNKNOWN").length,
    pending: actions.filter((action) => !["VERIFIED", "FAILED", "CANCELLED"].includes(action.state)).length,
    actionRefs: actions.map((action) => action.actionId),
  };
}

function appendUniqueEvidence(evidence, nextEvidence) {
  const exists = evidence.some((item) => item.kind === nextEvidence.kind
    && item.source === nextEvidence.source
    && item.result === nextEvidence.result
    && JSON.stringify(item.details ?? null) === JSON.stringify(nextEvidence.details ?? null));
  return exists ? [...evidence] : [...evidence, nextEvidence];
}

function artifactError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function commandProvenanceError(message = "Observed command evidence requires a ForgeLoop execution artifact") {
  return artifactError("E_COMMAND_PROVENANCE_UNATTESTED", message, [ARTIFACT_PATHS.receipt]);
}

function formatArgv(argv) {
  return argv.map((argument) => /[\s"']/u.test(argument)
    ? JSON.stringify(argument)
    : argument).join(" ");
}

function mergeByCheckId(checks, nextCheck) {
  const next = [...checks];
  const index = next.findIndex((item) => item?.schemaVersion === 1 && item.id === nextCheck.id);
  if (index >= 0) next[index] = nextCheck;
  else next.push(nextCheck);
  return next;
}

export async function requiredEvidenceForTarget({
  target,
  contract,
  route,
  packageRoot,
  additionalEvidence = [],
}) {
  const config = await readOptionalConfig(target, packageRoot);
  const guideEvidence = await completionEvidenceForGuides(route.value.guides, packageRoot);
  return [...new Set([
    ...(contract.value.successCriteria ?? []),
    ...guideEvidence,
    ...(config.requiredEvidence ?? []),
    ...(config.structuralQuality?.mode === "gate" ? [STRUCTURAL_QUALITY_REQUIREMENT] : []),
    ...additionalEvidence,
  ])].sort();
}

function requiredString(value, label) {
  if (typeof value !== "string" || value.trim() === "") {
    throw artifactError("E_CHECK_INVALID", `${label} must be a non-empty string`);
  }
  return value;
}

export async function validateCheckExecutionProvenance(check, {
  target,
  packageRoot,
  taskId,
  executionArtifacts,
  allowForeignCwd = false,
} = {}) {
  if (check?.kind !== "command" || check.evidenceKind !== "OBSERVED") return null;
  if (check.provenance !== "FORGELOOP_EXECUTED" || !check.executionRef) {
    throw commandProvenanceError();
  }
  const artifact = executionArtifacts
    ? { value: executionArtifacts[check.executionRef] }
    : await readExecutionArtifact({
      target,
      executionRef: check.executionRef,
      packageRoot,
      taskId,
    });
  if (!artifact.value) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution reference does not resolve to an execution artifact in this bundle",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  const execution = validateExecutionBinding({
    execution: artifact.value,
    taskId,
    checkId: check.id,
    requirement: check.requirement,
    verificationCycle: check.details?.verificationCycle ?? 1,
  });
  const protocolProjectRoot = execution.protocolProjectRoot ?? execution.cwd;
  if (
    execution.executionKind !== undefined
    && execution.executionKind !== "VERIFICATION"
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A command check must reference a verification execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (
    execution.executionIsolation !== undefined
    && execution.isolation?.mode !== execution.executionIsolation
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution artifact isolation mode does not match its isolation metadata",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (
    execution.isolation?.mode !== undefined
    && execution.isolation.mode !== "NATIVE_PROJECT"
    && path.resolve(execution.cwd) === path.resolve(protocolProjectRoot)
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Isolated execution artifact cwd must be separate from the protocol project root",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (!allowForeignCwd && path.resolve(protocolProjectRoot) !== path.resolve(target)) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution artifact protocol project root does not match the current target",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.status === "passed" && (execution.status !== "passed" || execution.exitCode !== 0)) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A passed command check must reference a successful execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.status === "failed" && execution.status !== "failed") {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A failed command check must reference a failed execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.exitCode !== undefined && check.exitCode !== execution.exitCode) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Check exitCode does not match its execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  return execution;
}

export async function validateChecksExecutionProvenance(checks, options) {
  const executions = [];
  for (const check of checks ?? []) {
    if (check.kind === "command" && check.evidenceKind === "OBSERVED") {
      const execution = await validateCheckExecutionProvenance(check, options);
      if (execution) executions.push(execution);
    }
  }
  return executions;
}

export async function authorizeCompletionRecoveryOrRebind({
  target,
  packageRoot,
  taskId = null,
  statePath = null,
  receiptPath = null,
  eventsPath = null,
  authorityContext,
  runtimeContext,
} = {}) {
  const statePathResolved = resolveArtifactPath("state", taskId, statePath);
  const receiptPathResolved = resolveArtifactPath("receipt", taskId, receiptPath);
  const resolveArtifacts = async () => {
    const state = await readWorkState(target, { packageRoot, taskId, statePath: statePathResolved });
    let receipt = null;
    try {
      receipt = (await readJsonArtifact(target, receiptPathResolved, "execution-receipt", packageRoot))?.value ?? null;
    } catch {
      receipt = null;
    }
    const events = (await validateEventLedger(target, packageRoot, { taskId, eventsPath })).events;
    return { state, receipt, events };
  };

  const initial = await resolveArtifacts();
  const recoveryAuth = validateCompletionRecoveryAuthorization(initial);
  if (recoveryAuth.authorized || !isFingerprintOnlyRecoveryMismatch(recoveryAuth.errors)) {
    return { ...initial, recoveryAuth, rebound: false };
  }

  const reboundResult = await rebindCompletionRejectionSnapshot({
    target,
    packageRoot,
    taskId,
    statePath,
    receiptPath,
    eventsPath,
    authorityContext,
    runtimeContext,
  });
  if (!reboundResult.rebound) {
    return { ...initial, recoveryAuth, rebound: false };
  }

  const rebounded = await resolveArtifacts();
  const reboundAuth = validateCompletionRecoveryAuthorization(rebounded);
  return { ...rebounded, recoveryAuth: reboundAuth, rebound: reboundAuth.authorized };
}

function findMatchingRejectionEvent(events, attempt, cycle) {
  let latestReviewIndex = -1;
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index];
    if (event.event === "REVIEW_STARTED" && (event.details?.verificationCycle ?? 1) === cycle) {
      latestReviewIndex = index;
    }
  }
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (event.event !== "COMPLETION_REJECTED") continue;
    if ((event.details?.verificationCycle ?? 1) !== cycle) continue;
    if (index < latestReviewIndex) continue;
    return { event, index };
  }
  return null;
}

export function isFingerprintOnlyRecoveryMismatch(errors = []) {
  return Array.isArray(errors)
    && errors.length > 0
    && errors.every((error) => FINGERPRINT_MISMATCH_CODES.has(error?.code));
}

function sameSortedValues(left, right) {
  return JSON.stringify(sortedValues(left)) === JSON.stringify(sortedValues(right));
}

function sortedValues(values) {
  return [...new Set(values ?? [])].sort();
}

function addAssertion(errors, assertion, code, artifacts) {
  try {
    assertion();
  } catch (error) {
    errors.push(issue(code, error.message, artifacts));
  }
}

export function assertCompletionRelationships(input) {
  const errors = completionRelationshipErrors(input);
  if (errors.length === 0) return;
  const first = errors[0];
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  throw error;
}

export function assertStateIdentity(input) {
  const errors = stateIdentityErrors(input);
  if (errors.length === 0) return;
  const first = errors[0];
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  throw error;
}

export function completionRelationshipErrors({
  contract,
  route,
  state,
  receipt,
  requiredEvidence = [],
  requireReceiptStateFingerprint = true,
  requireRequiredChecks = true,
  target,
  taskId,
  authorities,
  authorityContext,
  runtimeContext,
} = {}) {
  const errors = stateIdentityErrors({ contract, route, state });
  const contractValue = contract?.value ?? contract;
  const contractFingerprint = contract?.fingerprint;
  const effectiveTaskId = taskId ?? contractValue?.taskId ?? state?.taskId ?? receipt?.taskId;
  const authOptions = {
    ...(target ? { target } : {}),
    ...(effectiveTaskId ? { taskId: effectiveTaskId } : {}),
    ...(authorities ? { authorities } : {}),
    ...(authorityContext ? { authorityContext } : {}),
    ...(runtimeContext ? { runtimeContext } : {}),
  };
  if (contractValue && receipt && contractValue.taskId !== receipt.taskId) {
    errors.push(issue("E_RECEIPT_TASK_MISMATCH", "Execution receipt does not belong to the current contract task", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.receipt]));
  }
  if (route && receipt && (receipt.routeFingerprint !== route.fingerprint || !sameValue(receipt.selectedGuides, route.value.guides))) {
    errors.push(issue("E_ROUTE_GUIDE_MISMATCH", "Execution receipt does not match the persisted route identity", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.receipt]));
  }
  if (contractFingerprint && receipt && receipt.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_RECEIPT_CONTRACT_MISMATCH", "Execution receipt does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.receipt]));
  }

  if (state) {
    addAssertion(errors, () => assertCheckList(state.checks, "work-state.checks", authOptions), "E_CHECK_INVALID", [ARTIFACT_PATHS.state]);
    addAssertion(errors, () => assertEvidenceList(state.verificationEvidence, "work-state.verificationEvidence"), "E_EVIDENCE_INVALID", [ARTIFACT_PATHS.state]);
    for (const check of state.checks ?? []) {
      if (check.status === "passed") {
        const auth = validateVerificationAuthority(check, authOptions);
        if (!auth.valid) {
          errors.push(issue(auth.error.code, auth.error.message, [ARTIFACT_PATHS.state]));
        }
      }
    }
  }
  if (receipt) {
    addAssertion(errors, () => assertCheckList(receipt.checks, "receipt.checks", authOptions), "E_CHECK_INVALID", [ARTIFACT_PATHS.receipt]);
    addAssertion(errors, () => assertEvidenceList(receipt.evidence ?? [], "receipt.evidence"), "E_EVIDENCE_INVALID", [ARTIFACT_PATHS.receipt]);
    for (const check of receipt.checks ?? []) {
      if (check.status === "passed") {
        const auth = validateVerificationAuthority(check, authOptions);
        if (!auth.valid) {
          errors.push(issue(auth.error.code, auth.error.message, [ARTIFACT_PATHS.receipt]));
        }
      }
    }
    if (requireRequiredChecks) {
      const readiness = evaluateRequiredEvidence({ requirements: requiredEvidence, checks: receipt.checks, options: authOptions });
      for (const requirement of readiness.missing) {
        errors.push(issue("E_EVIDENCE_REQUIRED", `Required check is missing: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
      for (const requirement of readiness.partial) {
        errors.push(issue("E_EVIDENCE_PARTIAL", `Required evidence is partial: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
      for (const requirement of readiness.invalid) {
        errors.push(issue(requirement.reasonCode ?? "E_EVIDENCE_INVALID", `Required evidence is invalid: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
    }
  }

  const expectedCoverage = state ? coverageForRequirements(requiredEvidence, state.checks, {
    target,
    taskId: effectiveTaskId,
    authorities,
    options: authOptions,
  }) : [];
  if (state?.evidenceCoverage !== undefined) {
    addAssertion(errors, () => assertCoverageList(state.evidenceCoverage, "work-state.evidenceCoverage"), "E_EVIDENCE_COVERAGE_INVALID", [ARTIFACT_PATHS.state]);
    if (!sameValue(state.evidenceCoverage, expectedCoverage)) {
      errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Work state evidence coverage does not match its checks", [ARTIFACT_PATHS.state]));
    }
  }
  if (receipt) {
    if (receipt.evidenceCoverage === undefined) {
      errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Execution receipt requires evidence coverage", [ARTIFACT_PATHS.receipt]));
    } else {
      addAssertion(errors, () => assertCoverageList(receipt.evidenceCoverage, "receipt.evidenceCoverage"), "E_EVIDENCE_COVERAGE_INVALID", [ARTIFACT_PATHS.receipt]);
      if (!sameValue(receipt.evidenceCoverage, expectedCoverage)) {
        errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Execution receipt evidence coverage does not match current checks", [ARTIFACT_PATHS.receipt]));
      }
    }
  }

  if (state && receipt) {
    if (state.verificationCycle !== undefined && receipt.verificationCycle !== undefined
      && state.verificationCycle !== receipt.verificationCycle) {
      errors.push(issue("E_RECEIPT_CYCLE_MISMATCH", "Work state and execution receipt verification cycles diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (requireReceiptStateFingerprint) {
      if (receipt.stateFingerprint === undefined) {
        errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Execution receipt requires the current work-state fingerprint", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
      } else if (receipt.stateFingerprint !== canonicalFingerprint(state)) {
        errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Execution receipt does not match the recorded work state", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
      }
    }
    if (!sameValue(state.checks, receipt.checks)) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt checks diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (!sameValue(state.verificationEvidence, receipt.evidence ?? [])) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt evidence diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (state.evidenceCoverage !== undefined && receipt.evidenceCoverage !== undefined
      && !sameValue(state.evidenceCoverage, receipt.evidenceCoverage)) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt coverage diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
  }
  return errors;
}

function issue(code, message, artifacts = [], details = {}) {
  return { code, message, artifacts, ...details };
}

function sameValue(left, right) {
  return canonicalFingerprint(left) === canonicalFingerprint(right);
}

export function stateIdentityErrors({
  contract,
  route,
  state,
} = {}) {
  const errors = [];
  const contractValue = contract?.value ?? contract;
  const contractFingerprint = contract?.fingerprint;
  if (contractValue && state && contractValue.taskId !== state.taskId) {
    errors.push(issue("E_STATE_TASK_MISMATCH", "Work state does not belong to the current contract task", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.state]));
  }
  if (contractFingerprint && state && state.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_CONTRACT_STALE", "Work state does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.state]));
  }
  if (contractFingerprint && route && route.value.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_ROUTE_STALE", "Routing result does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.route]));
  }
  if (route && state && route.value.contractFingerprint !== undefined
    && route.value.contractFingerprint !== state.contractFingerprint) {
    errors.push(issue("E_ROUTE_STALE", "Routing result does not match the work state contract", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.state]));
  }
  if (route && state && (state.routeFingerprint !== route.fingerprint || !sameValue(state.selectedGuides, route.value.guides))) {
    errors.push(issue("E_ROUTE_GUIDE_MISMATCH", "Work state does not match the persisted route identity", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.state]));
  }
  return errors;
}

async function actionReceiptSummary(target, packageRoot, taskId) {
  const actions = await listActions(target, { packageRoot, taskId });
  const { evaluateRequiredActionReadiness } = await import("./action-readiness.js");
  const readiness = await evaluateRequiredActionReadiness({ target, packageRoot, taskId });
  return {
    count: actions.length,
    required: readiness.total,
    verified: actions.filter((action) => action.state === "VERIFIED").length,
    // Raw state counts are observability only; trusted completion is below.
    trustedSatisfied: readiness.satisfied,
    unresolvedRequired: readiness.unresolved,
    failed: actions.filter((action) => action.state === "FAILED").length,
    ambiguous: actions.filter((action) => action.state === "COMMIT_UNKNOWN").length,
    pending: actions.filter((action) => !["VERIFIED", "FAILED", "CANCELLED"].includes(action.state)).length,
    actionRefs: actions.map((action) => action.actionId),
  };
}

async function attestationConfiguration(target, packageRoot, errors) {
  try {
    const config = await readConfig(target, packageRoot);
    return {
      mode: config.attestation?.mode ?? "off",
      revisionProvider: config.attestation?.revisionProvider ?? "git",
      requireCompleteCoverage: config.attestation?.requireCompleteCoverage === true,
      signing: config.attestation?.signing ?? { provider: "none", required: false, policy: {} },
    };
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return { mode: "off", revisionProvider: "git", requireCompleteCoverage: false, signing: { provider: "none", required: false, policy: {} } };
    errors.push(issue(error.code ?? "E_ATTESTATION_INVALID", `Attestation configuration is invalid: ${error.message}`, [PROJECT_ARTIFACT_PATHS.config]));
    return { mode: "off", revisionProvider: "git", requireCompleteCoverage: false, signing: { provider: "none", required: false, policy: {} } };
  }
}

export function completionIdentityErrors({ contract, state, receipt } = {}) {
  return completionRelationshipErrors({ contract, state, receipt })
    .filter((error) => ["E_STATE_TASK_MISMATCH", "E_RECEIPT_TASK_MISMATCH"].includes(error.code));
}

function issue(code, message, artifacts = [], details = {}) {
  return { code, message, artifacts, ...details };
}

async function loadRequired(readArtifact, errorCode, errorMessage, artifacts, errors) {
  try {
    return await readArtifact();
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") {
      errors.push(issue(errorCode, errorMessage, artifacts));
      return null;
    }
    errors.push(issue(error.code ?? errorCode, error.message ?? errorMessage, artifacts));
    return null;
  }
}

function publicationStatus(receipt) {
  if (receipt.publicationStatus) return receipt.publicationStatus;
  if (receipt.publication?.deployed) return "deployed";
  if (receipt.publication?.pushed) return "pushed";
  if (receipt.publication?.committed) return "committed";
  return receipt.changedPaths?.length > 0 ? "local-only" : "not-published";
}

function sortIssues(issues) {
  return issues
    .map(withRepairGuidance)
    .sort((a, b) => (a.code || "").localeCompare(b.code || "") || (a.message || "").localeCompare(b.message || ""));
}

export function contextBudget(profile = "balanced") {
  return CONTEXT_BUDGETS[profile] ?? CONTEXT_BUDGETS.balanced;
}

export function normalizeContextCandidate(input = {}) {
  const safe = buildDecisionState({
    id: input.id ?? null,
    sourceRef: input.sourceRef ?? null,
    kind: input.kind ?? "UNKNOWN",
    summary: input.summary ?? "",
    required: input.required === true,
    mandatory: input.mandatory === true,
    risk: input.risk ?? "NORMAL",
    trust: input.trust ?? "UNTRUSTED",
  });
  const summary = typeof safe.summary === "string" ? safe.summary : "";
  const id = typeof safe.id === "string" && safe.id ? safe.id : `candidate-${canonicalFingerprint(safe).slice(0, 16)}`;
  return {
    ...safe,
    id,
    summary,
    chars: summary.length,
    promptInjection: INJECTION_PATTERN.test(summary),
  };
}

export function normalizeContextCandidates(candidates = []) {
  const seen = new Set();
  const normalized = [];
  for (const candidate of candidates) {
    const value = normalizeContextCandidate(candidate);
    const identity = `${value.id}:${value.sourceRef ?? ""}`;
    if (seen.has(identity)) continue;
    seen.add(identity);
    normalized.push(value);
  }
  return normalized;
}

export function compileContext({ candidates = [], profile = "balanced", mandatoryIds = [], semanticRanker = null } = {}) {
  const policy = assertContextCompilerPolicy({ profile, mandatoryIds });
  const normalized = normalizeContextCandidates(candidates);
  const candidateSetFingerprint = canonicalFingerprint(normalized.map((candidate) => ({
    id: candidate.id,
    sourceRef: candidate.sourceRef,
    summary: candidate.summary,
    required: candidate.required,
    mandatory: candidate.mandatory,
  })));
  const mandatory = new Set(policy.mandatoryIds);
  const marked = normalized.map((candidate) => ({ ...candidate, mandatory: candidate.mandatory || mandatory.has(candidate.id) }));
  const semantic = typeof semanticRanker === "function" ? semanticRanker(marked.filter((item) => !item.promptInjection).map((item) => ({ id: item.id, summary: item.summary }))) : [];
  const rankedIds = Array.isArray(semantic) ? semantic : (semantic?.rankedIds ?? []);
  const excludedIds = new Set(Array.isArray(semantic) ? [] : (semantic?.excludedIds ?? []));
  const ordered = orderCandidates(marked, Array.isArray(rankedIds) ? rankedIds : []);
  const budget = contextBudget(profile);
  const selected = [];
  const omitted = [];
  let chars = 0;
  for (const candidate of ordered) {
    const mustKeep = candidate.mandatory || candidate.required;
    if (excludedIds.has(candidate.id) && !mustKeep) {
      omitted.push(candidate);
      continue;
    }
    const fits = selected.length < budget.maxItems && chars + candidate.chars <= budget.maxChars;
    if (fits || mustKeep) {
      selected.push(candidate);
      chars += candidate.chars;
    } else omitted.push(candidate);
  }
  const promptInjectionIds = marked.filter((item) => item.promptInjection).map((item) => item.id).sort();
  const result = contextPlanResult({
    profile,
    candidates: marked,
    selected,
    omitted,
    mandatoryIds: [...new Set([...policy.mandatoryIds, ...marked.filter((item) => item.mandatory).map((item) => item.id)])].sort(),
    promptInjectionIds,
    fingerprint: null,
    budget,
    candidateSetFingerprint,
  });
  result.decisionFingerprint = contextPlanFingerprint(result);
  return result;
}

function orderCandidates(candidates, rankedIds = []) {
  const ranks = new Map(rankedIds.map((id, index) => [id, rankedIds.length - index]));
  return [...candidates].sort((a, b) => (b.mandatory - a.mandatory)
    || (b.required - a.required)
    || ((ranks.get(b.id) ?? 0) - (ranks.get(a.id) ?? 0))
    || (candidatePriority(b) - candidatePriority(a))
    || a.id.localeCompare(b.id));
}

export function contextPlanFingerprint(plan) {
  return canonicalFingerprint({
    profile: plan.profile,
    selectedIds: plan.selected.map((item) => item.id),
    omittedIds: plan.omitted.map((item) => item.id),
    mandatoryIds: plan.mandatoryIds,
    promptInjectionIds: plan.promptInjectionIds,
  });
}

export function assertContextCompilerPolicy({ profile = "balanced", mandatoryIds = [] } = {}) {
  if (!["light", "balanced", "full"].includes(profile)) throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "Context compiler profile is invalid.");
  if (!Array.isArray(mandatoryIds) || mandatoryIds.some((id) => typeof id !== "string" || !id)) throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "Context compiler mandatory IDs are invalid.");
  return { profile, mandatoryIds: [...new Set(mandatoryIds)] };
}

function finding(code, severity, field, itemId = null) {
  return { code, severity, field, itemId };
}

function hasOperationalHints(continuity) {
  return Boolean(
    continuity.currentFocus
    || continuity.remainingWork?.length
    || continuity.knownIssues?.length
    || continuity.changedAreas?.length
    || continuity.inspectFirst?.length
    || (typeof continuity.resumeNote === "string" && continuity.resumeNote.trim() !== ""),
  );
}

export async function lintContinuity({ target, continuity, state } = {}) {
  const findings = [];
  if (!continuity || typeof continuity !== "object" || Array.isArray(continuity)) {
    return { status: "PASS", findings };
  }

  const completedSteps = new Set(
    Array.isArray(state?.completedSteps) ? state.completedSteps : [],
  );

  for (const [index, item] of (continuity.remainingWork ?? []).entries()) {
    if (!item?.id) continue;
    if (completedSteps.has(item.id)) {
      findings.push(finding(
        "CONTINUITY_REMAINING_ALREADY_COMPLETED",
        "WARN",
        `remainingWork[${index}]`,
        item.id,
      ));
    }
  }

  if (continuity.currentFocus?.id && completedSteps.has(continuity.currentFocus.id)) {
    findings.push(finding(
      "CONTINUITY_FOCUS_ALREADY_COMPLETED",
      "WARN",
      "currentFocus",
      continuity.currentFocus.id,
    ));
  }

  const knownIssueIds = new Set(
    (continuity.knownIssues ?? []).map((item) => item?.id).filter(Boolean),
  );
  for (const [index, item] of (continuity.remainingWork ?? []).entries()) {
    if (item?.id && knownIssueIds.has(item.id)) {
      findings.push(finding(
        "CONTINUITY_ITEM_ROLE_CONFLICT",
        "WARN",
        `remainingWork[${index}]`,
        item.id,
      ));
    }
  }

  if (typeof target === "string" && target.trim() !== "") {
    for (const [index, inspectPath] of (continuity.inspectFirst ?? []).entries()) {
      try {
        await assertSafePath(target, inspectPath);
        if (!(await fileExists(ensureWithin(target, inspectPath)))) {
          findings.push(finding(
            "CONTINUITY_INSPECT_PATH_MISSING",
            "WARN",
            `inspectFirst[${index}]`,
          ));
        }
      } catch {
        // Invalid or unsafe paths are rejected by continuity schema validation;
        // lint never resolves an unchecked path or turns it into authority.
      }
    }
  }

  if (!hasOperationalHints(continuity)) {
    findings.push(finding("CONTINUITY_EMPTY_HINT_SET", "INFO", "continuity"));
  }

  return {
    status: findings.some((item) => item.severity === "WARN") ? "WARN" : "PASS",
    findings,
  };
}

export function continuityFinding(result) {
  if (continuityIsHealthy(result)) return null;
  const classification = result?.classification ?? "INVALID";
  const severity = classification === "RECONCILIATION_REQUIRED" ? "warning" : "error";
  return {
    code: `continuity-${classification.toLowerCase().replaceAll("_", "-")}`,
    severity,
    path: result?.path ?? ".forgeloop/continuity.json",
    message: result?.reasons?.join(", ") || `Continuity is ${classification}`,
    remediation: classification === "RECONCILIATION_REQUIRED"
      ? "Run forgeloop reconcile-continuity, inspect the current checkout, then record corrected continuity before advancing verification."
      : "Repair or clear continuity after reviewing the current work state and checkout.",
  };
}

export function continuityIsHealthy(result) {
  return HEALTHY.has(result?.classification ?? "ABSENT");
}

function baseResult(classification, overrides = {}) {
  return {
    classification,
    taskMatches: overrides.taskMatches ?? null,
    workStateMatches: overrides.workStateMatches ?? null,
    contractMatches: overrides.contractMatches ?? null,
    phaseMatches: overrides.phaseMatches ?? null,
    repositoryComparison: overrides.repositoryComparison ?? "NOT_VERIFIED",
    changedPathComparison: overrides.changedPathComparison ?? "NOT_VERIFIED",
    reasonCodes: uniqueSorted(overrides.reasonCodes ?? []),
    reasons: uniqueSorted(overrides.reasons ?? []),
    authority: "OPERATIONAL_CONTEXT_ONLY",
    evidenceAuthority: "NONE",
  };
}

export function classifyContinuity({
  continuity,
  state,
  contractFingerprint,
  repositoryFingerprint,
  changedPaths,
} = {}) {
  if (!continuity) {
    return baseResult("ABSENT", { reasons: ["CONTINUITY_ABSENT"] });
  }

  let value;
  try {
    value = assertContinuitySemantics(continuity);
  } catch (error) {
    return baseResult("INVALID", {
      reasonCodes: [error.code ?? "E_CONTINUITY_INVALID"],
      reasons: [error.message],
    });
  }

  if (!state || typeof state !== "object") {
    return baseResult("INCONSISTENT", {
      reasonCodes: ["E_CONTINUITY_STATE_MISSING"],
      reasons: ["CONTINUITY_STATE_MISSING"],
    });
  }

  if (state.phase === "COMPLETE") {
    return baseResult("NOT_APPLICABLE", {
      taskMatches: value.taskId === state.taskId,
      phaseMatches: value.phase === state.phase,
      reasons: ["CONTINUITY_NOT_APPLICABLE_AFTER_COMPLETE"],
    });
  }

  const taskMatches = value.taskId === state.taskId;
  const workStateMatches = value.workStateFingerprint === canonicalFingerprint(state);
  const expectedContract = contractFingerprint ?? state.contractFingerprint ?? null;
  const contractMatches = value.contractFingerprint === state.contractFingerprint
    && (expectedContract === null || value.contractFingerprint === expectedContract);
  const phaseMatches = value.phase === state.phase;
  const repositoryComparison = compareRepository(value.repositoryFingerprint, repositoryFingerprint);
  const changedPathComparison = compareChangedPaths(changedPaths, value.changedAreas);

  const inconsistentCodes = [];
  const inconsistentReasons = [];
  if (!taskMatches) {
    inconsistentCodes.push("E_CONTINUITY_TASK_MISMATCH");
    inconsistentReasons.push("CONTINUITY_TASK_MISMATCH");
  }
  if (!contractMatches) {
    inconsistentCodes.push("E_CONTINUITY_CONTRACT_MISMATCH");
    inconsistentReasons.push("CONTINUITY_CONTRACT_MISMATCH");
  }
  if (!phaseMatches && !phaseReachable(value.phase, state.phase)) {
    inconsistentCodes.push("E_CONTINUITY_PHASE_MISMATCH");
    inconsistentReasons.push("CONTINUITY_PHASE_MISMATCH");
  }
  if (inconsistentCodes.length > 0) {
    return baseResult("INCONSISTENT", {
      taskMatches,
      workStateMatches,
      contractMatches,
      phaseMatches,
      repositoryComparison,
      changedPathComparison,
      reasonCodes: inconsistentCodes,
      reasons: inconsistentReasons,
    });
  }

  const reconciliationReasons = [];
  if (!workStateMatches) reconciliationReasons.push("CONTINUITY_WORK_STATE_CHANGED");
  if (!phaseMatches) reconciliationReasons.push("CONTINUITY_PHASE_CHANGED");
  if (repositoryComparison === "MISMATCH") reconciliationReasons.push("CONTINUITY_REPOSITORY_CHANGED");
  if (["PARTIAL", "MISMATCH"].includes(changedPathComparison)) {
    reconciliationReasons.push("CONTINUITY_CHANGED_PATHS_DIFFER");
  }

  if (reconciliationReasons.length > 0) {
    return baseResult("RECONCILIATION_REQUIRED", {
      taskMatches,
      workStateMatches,
      contractMatches,
      phaseMatches,
      repositoryComparison,
      changedPathComparison,
      reasonCodes: [RECONCILIATION_CODE],
      reasons: reconciliationReasons,
    });
  }

  return baseResult("FRESH", {
    taskMatches,
    workStateMatches,
    contractMatches,
    phaseMatches,
    repositoryComparison,
    changedPathComparison,
  });
}

async function resolveLatestHandoffSafe(target, { packageRoot, taskId } = {}) {
  if (!taskId) return null;
  try {
    const { resolveLatestHandoff } = await import("./handoff.js");
    return await resolveLatestHandoff(target, { packageRoot, taskId });
  } catch (error) {
    return {
      status: "INVALID",
      error: {
        code: error.code ?? "E_HANDOFF_INVALID",
        message: error.message,
      },
    };
  }
}

export function assertContinuitySemantics(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw continuityError("E_CONTINUITY_INVALID", "Continuity must be a JSON object");
  }
  const unknownField = Object.keys(input).find((key) => !CONTINUITY_FIELDS.has(key));
  if (unknownField) {
    throw continuityError("E_CONTINUITY_INVALID", `Continuity contains unsupported field: ${unknownField}`);
  }
  if (input.schemaVersion !== CONTINUITY_SCHEMA_VERSION || input.protocolVersion !== PROTOCOL_VERSION) {
    throw continuityError("E_CONTINUITY_SCHEMA_UNSUPPORTED", "Unsupported continuity schema or protocol version");
  }
  if (!WORK_PHASES.includes(input.phase)) {
    throw continuityError("E_CONTINUITY_INVALID", `Unknown continuity phase: ${input.phase}`);
  }
  if (input.verificationCycle !== undefined
    && (!Number.isInteger(input.verificationCycle) || input.verificationCycle < 1)) {
    throw continuityError("E_CONTINUITY_INVALID", "verificationCycle must be a positive integer");
  }
  const normalized = {
    schemaVersion: CONTINUITY_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    taskId: nonEmptyString(input.taskId, "taskId", LIMITS.taskId),
    workStateFingerprint: fingerprint(input.workStateFingerprint, "workStateFingerprint"),
    contractFingerprint: fingerprint(input.contractFingerprint, "contractFingerprint"),
    phase: input.phase,
    ...(input.verificationCycle !== undefined ? { verificationCycle: input.verificationCycle } : {}),
    repositoryFingerprint: normalizeRepositoryFingerprint(input.repositoryFingerprint),
    updatedAt: nonEmptyString(input.updatedAt, "updatedAt", 128),
    ...(input.currentFocus !== undefined ? { currentFocus: normalizeWorkItem(input.currentFocus, "currentFocus") } : {}),
    remainingWork: normalizeWorkItems(input.remainingWork, "remainingWork", LIMITS.remainingWork),
    knownIssues: normalizeWorkItems(input.knownIssues, "knownIssues", LIMITS.knownIssues),
    changedAreas: normalizePaths(input.changedAreas, "changedAreas", LIMITS.changedAreas),
    inspectFirst: normalizePaths(input.inspectFirst, "inspectFirst", LIMITS.inspectFirst),
    ...(input.resumeNote !== undefined
      ? { resumeNote: nonEmptyString(input.resumeNote, "resumeNote", LIMITS.resumeNote) }
      : {}),
  };
  try {
    assertPortableContextSafe(normalized);
  } catch (error) {
    throw continuityError("E_CONTINUITY_INVALID", error.message);
  }
  return normalized;
}

function continuityError(code, message, artifacts = [CONTINUITY_PATH]) {
  const error = new Error(message);
  error.name = "ContinuityError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function createContinuity(input) {
  return assertContinuitySemantics({
    schemaVersion: input.schemaVersion ?? CONTINUITY_SCHEMA_VERSION,
    protocolVersion: input.protocolVersion ?? PROTOCOL_VERSION,
    ...structuredClone(input),
  });
}

export function assertContractBootstrapRepairDetails(details) {
  return assertContractBootstrapRepairDetailsInternal(details);
}

function assertContractBootstrapRepairDetailsInternal(details, { legacy = false } = {}) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    throw invalid("contract bootstrap repair requires structured details");
  }
  assertRepairDetailKeys(details, legacy);
  for (const key of [
    "taskId", "repairId", "defect", "contractCreateTransactionId", "repairedAt", "authorityKind",
  ]) {
    if (typeof details[key] !== "string" || !details[key].trim()) {
      throw invalid(`contract bootstrap repair details.${key} must be a non-empty string`);
    }
  }
  if (details.repairVersion !== CONTRACT_BOOTSTRAP_REPAIR_VERSION) {
    throw invalid("contract bootstrap repair details.repairVersion is unsupported");
  }
  if (!REPAIR_ID.test(details.repairId)) throw invalid("contract bootstrap repair details.repairId is invalid");
  if (details.defect !== CONTRACT_BOOTSTRAP_REPAIR_DEFECT) throw invalid("contract bootstrap repair details.defect is invalid");
  if (details.authorityKind !== CONTRACT_BOOTSTRAP_REPAIR_AUTHORITY) throw invalid("contract bootstrap repair details.authorityKind is invalid");
  for (const key of [
    "canonicalContractEventHash", "duplicateContractEventHash", "contractCreateCommitHash",
    "contractFingerprint", "reconstructedStateFingerprint",
  ]) {
    if (!isFingerprint(details[key])) throw invalid(`contract bootstrap repair details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  for (const key of ["canonicalContractEventSeq", "duplicateContractEventSeq", "contractCreateCommitSeq"]) {
    if (!Number.isInteger(details[key]) || details[key] < 1) throw invalid(`contract bootstrap repair details.${key} must be a positive integer`);
  }
  assertRepairDetailRevision(details, legacy);
  assertRepairDetailPhase(details);
  if (details.routeFingerprint !== null && !isFingerprint(details.routeFingerprint)) {
    throw invalid("contract bootstrap repair details.routeFingerprint must be a fingerprint or null");
  }
  if (details.previousStateFingerprint !== null && !isFingerprint(details.previousStateFingerprint)) {
    throw invalid("contract bootstrap repair details.previousStateFingerprint must be a fingerprint or null");
  }
  if (!Number.isFinite(Date.parse(details.repairedAt))) throw invalid("contract bootstrap repair details.repairedAt must be an ISO timestamp");
  return details;
}

export function assertLegacyContractBootstrapRepairDetails(details) {
  return assertContractBootstrapRepairDetailsInternal(details, { legacy: true });
}

function assertRepairDetailKeys(details, legacy) {
  const allowedKeys = legacy ? LEGACY_REPAIR_DETAIL_KEYS : REPAIR_DETAIL_KEYS;
  const unexpected = Object.keys(details).find((key) => !allowedKeys.has(key));
  if (unexpected) throw invalid(`contract bootstrap repair details contains unknown property: ${unexpected}`);
}

function assertRepairDetailPhase(details) {
  if (!["CONTRACT_READY", "ROUTED"].includes(details.reconstructedPhase)) {
    throw invalid("contract bootstrap repair details.reconstructedPhase is invalid");
  }
  if (details.reconstructedPhase === "ROUTED" && details.routeFingerprint === null) {
    throw invalid("ROUTED contract bootstrap repair requires routeFingerprint");
  }
}

function assertRepairDetailRevision(details, legacy) {
  if (!legacy && (!Number.isInteger(details.reconstructedStateRevision) || details.reconstructedStateRevision < 0)) {
    throw invalid("contract bootstrap repair details.reconstructedStateRevision must be a non-negative integer");
  }
}

function canonicalGuideList(value) {
  if (!Array.isArray(value) || value.some((guide) => typeof guide !== "string" || !guide)) return null;
  const guides = [...value].sort();
  return new Set(guides).size === guides.length ? guides : null;
}

export function contractBootstrapRepairId(details) {
  const identity = {
    taskId: details.taskId,
    defect: details.defect,
    canonicalContractEventSeq: details.canonicalContractEventSeq,
    canonicalContractEventHash: details.canonicalContractEventHash,
    duplicateContractEventSeq: details.duplicateContractEventSeq,
    duplicateContractEventHash: details.duplicateContractEventHash,
    contractCreateCommitSeq: details.contractCreateCommitSeq,
    contractCreateCommitHash: details.contractCreateCommitHash,
    contractCreateTransactionId: details.contractCreateTransactionId,
    contractFingerprint: details.contractFingerprint,
    reconstructedPhase: details.reconstructedPhase,
    routeFingerprint: details.routeFingerprint,
    reconstructedStateRevision: details.reconstructedStateRevision,
  };
  return `repair-${canonicalFingerprint(identity)}`;
}

export function eventHash(event) {
  const { hash, ...body } = event;
  return canonicalFingerprint(body);
}

function invalid(message) {
  const error = new Error(message);
  error.code = "E_EVENT_INVALID";
  return error;
}

function isCommitFor(event, operation) {
  return event?.event === "TRANSACTION_COMMITTED"
    && event.details?.operation === operation
    && typeof event.details?.transactionId === "string"
    && event.details.transactionId.length > 0;
}

export function isContractBootstrapRepairCandidate(events, ledgerErrors = [], taskId = null) {
  if (!Array.isArray(events) || events.length < 4) return null;
  const effectiveTaskId = taskId ?? events[0]?.taskId;
  if (typeof effectiveTaskId !== "string" || !effectiveTaskId) return null;
  if (events.some((event) => event.taskId !== effectiveTaskId)) return null;
  if (events.some((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_EVENT)) return null;
  if (events[0]?.event !== "TASK_RECEIVED" || events[1]?.event !== "TRANSACTION_COMMITTED"
    || events[1]?.details?.operation !== "task-create") return null;
  if (!events.some((event) => event.event === "DISCOVERY_STARTED")) return null;
  const contractEvents = events.filter((event) => event.event === "CONTRACT_VALIDATED");
  if (contractEvents.length !== 2) return null;
  const [canonical, duplicate] = contractEvents;
  if (!isFingerprint(canonical.details?.contractFingerprint)
    || canonical.details.contractFingerprint !== duplicate.details?.contractFingerprint) return null;
  if (canonical.hash !== eventHash(canonical) || duplicate.hash !== eventHash(duplicate)) return null;
  const canonicalIndex = events.indexOf(canonical);
  const duplicateIndex = events.indexOf(duplicate);
  const canonicalCommit = events[canonicalIndex + 1];
  const duplicateCommit = events[duplicateIndex + 1];
  if (!isCommitFor(canonicalCommit, "contract-create") || !isCommitFor(duplicateCommit, "contract-create")) return null;
  if (duplicateIndex !== events.length - 2 || events.at(-1) !== duplicateCommit) return null;
  if (events.some((event) => HISTORICAL_EVENTS.has(event.event))) return null;
  if (!Array.isArray(ledgerErrors) || ledgerErrors.length < 1) return null;
  if (ledgerErrors.some((error) => !isExactDuplicateContractChronologyError(error))) return null;
  if (!ledgerErrors.some((error) => error.message === "lifecycle milestone must not repeat: CONTRACT_VALIDATED")) return null;
  return {
    taskId: effectiveTaskId,
    canonicalContractEvent: canonical,
    duplicateContractEvent: duplicate,
    canonicalContractCommit: canonicalCommit,
    duplicateContractCommit: duplicateCommit,
    contractFingerprint: canonical.details.contractFingerprint,
  };
}

export function isContractBootstrapRepairMarkerValid(events, marker) {
  try {
    if (!marker || marker.event !== CONTRACT_BOOTSTRAP_REPAIR_EVENT) return false;
    if (!resolveContractBootstrapRepairBoundary(events, marker)) return false;
    assertContractBootstrapRepairDetails(marker.details);
    if (marker.taskId !== marker.details.taskId || marker.hash !== eventHash(marker)) return false;
    if (marker.seq < 1 || events[marker.seq - 1] !== marker) return false;
    const prefix = events.slice(0, marker.seq - 1);
    const prefixErrors = [];
    const candidate = isContractBootstrapRepairCandidate(prefix, prefixErrors, marker.taskId);
    if (!candidate) {
      const duplicateErrors = [
        { code: "E_PHASE_CHRONOLOGY_INVALID", message: "lifecycle milestone must not repeat: CONTRACT_VALIDATED" },
        { code: "E_PHASE_CHRONOLOGY_INVALID", message: "CONTRACT_VALIDATED is out of lifecycle order" },
      ];
      const recognized = isContractBootstrapRepairCandidate(prefix, duplicateErrors, marker.taskId);
      if (!recognized) return false;
      return isMarkerBound(marker, recognized);
    }
    return isMarkerBound(marker, candidate);
  } catch {
    return false;
  }
}

function isFingerprint(value) {
  return typeof value === "string" && FINGERPRINT.test(value);
}

export function isLegacyContractBootstrapRepairMarkerShape(event) {
  try {
    if (!event || event.event !== CONTRACT_BOOTSTRAP_REPAIR_EVENT) return false;
    assertLegacyContractBootstrapRepairDetails(event.details);
    if (typeof event.taskId !== "string" || !event.taskId
      || event.taskId !== event.details.taskId
      || !Number.isInteger(event.seq) || event.seq < 1
      || !isFingerprint(event.hash)
      || event.hash !== eventHash(event)
      || event.details.repairId !== legacyContractBootstrapRepairId(event.details)) return false;
    return true;
  } catch {
    return false;
  }
}

export function isLegacyContractBootstrapRepairMigrationCandidate(events, taskId = null) {
  if (!Array.isArray(events)) return null;
  const markers = events.filter((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (markers.length !== 1) return null;
  const marker = markers[0];
  if (!isLegacyContractBootstrapRepairMarkerShape(marker)) return null;
  const effectiveTaskId = taskId ?? marker.taskId;
  if (marker.taskId !== effectiveTaskId || events.some((event) => event.taskId !== effectiveTaskId)) return null;
  if (events.some((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT)) return null;
  const boundary = resolveContractBootstrapRepairBoundary(events, marker);
  if (!boundary || boundary.postRepairEvents.length > 0) return null;
  return { taskId: effectiveTaskId, marker, repairCommit: boundary.repairCommit };
}

function isMarkerBound(marker, candidate) {
  const details = marker.details;
  const expected = {
    taskId: candidate.taskId,
    defect: CONTRACT_BOOTSTRAP_REPAIR_DEFECT,
    canonicalContractEventSeq: candidate.canonicalContractEvent.seq,
    canonicalContractEventHash: candidate.canonicalContractEvent.hash,
    duplicateContractEventSeq: candidate.duplicateContractEvent.seq,
    duplicateContractEventHash: candidate.duplicateContractEvent.hash,
    contractCreateCommitSeq: candidate.duplicateContractCommit.seq,
    contractCreateCommitHash: candidate.duplicateContractCommit.hash,
    contractCreateTransactionId: candidate.duplicateContractCommit.details.transactionId,
    contractFingerprint: candidate.contractFingerprint,
  };
  for (const [key, value] of Object.entries(expected)) if (details[key] !== value) return false;
  if (details.repairId !== contractBootstrapRepairId(details)) return false;
  return true;
}

function isRepairTransactionCommit(event, taskId) {
  if (!event || event.taskId !== taskId || event.event !== "TRANSACTION_COMMITTED") return false;
  const details = event.details;
  return details && typeof details === "object" && !Array.isArray(details)
    && Object.keys(details).length === 2
    && typeof details.transactionId === "string" && details.transactionId.length > 0
    && details.operation === "task-repair-contract-bootstrap"
    && event.hash === eventHash(event);
}

export function legacyContractBootstrapRepairId(details) {
  const identity = {
    taskId: details.taskId,
    defect: details.defect,
    canonicalContractEventSeq: details.canonicalContractEventSeq,
    canonicalContractEventHash: details.canonicalContractEventHash,
    duplicateContractEventSeq: details.duplicateContractEventSeq,
    duplicateContractEventHash: details.duplicateContractEventHash,
    contractCreateCommitSeq: details.contractCreateCommitSeq,
    contractCreateCommitHash: details.contractCreateCommitHash,
    contractCreateTransactionId: details.contractCreateTransactionId,
    contractFingerprint: details.contractFingerprint,
    reconstructedPhase: details.reconstructedPhase,
    routeFingerprint: details.routeFingerprint,
  };
  return `repair-${canonicalFingerprint(identity)}`;
}

function migrationCommitFor(event, taskId) {
  return event?.event === "TRANSACTION_COMMITTED"
    && event.taskId === taskId
    && event.details?.operation === "task-migrate-contract-bootstrap-repair"
    && typeof event.details?.transactionId === "string"
    && event.details.transactionId.length > 0
    && event.hash === eventHash(event);
}

function migrationMatchesLegacyRepairBoundary({ migration, marker, repairCommit }) {
  const { details } = migration;
  const bindings = [
    [migration.taskId, marker.taskId],
    [details.taskId, marker.taskId],
    [details.legacyMarkerSeq, marker.seq],
    [details.legacyMarkerHash, marker.hash],
    [details.legacyRepairId, marker.details.repairId],
    [details.legacyRepairCommitSeq, repairCommit.seq],
    [details.legacyRepairCommitHash, repairCommit.hash],
    [details.legacyRepairTransactionId, repairCommit.details.transactionId],
    [details.contractFingerprint, marker.details.contractFingerprint],
    [details.reconstructedPhase, marker.details.reconstructedPhase],
    [details.routeFingerprint, marker.details.routeFingerprint],
    [details.reconstructedStateFingerprint, marker.details.reconstructedStateFingerprint],
  ];
  return bindings.every(([actual, expected]) => actual === expected);
}

export function resolveCanonicalPostRepairCheckpointBinding(events, marker) {
  const boundary = resolveContractBootstrapRepairBoundary(events, marker);
  if (!boundary) return null;
  const checkpointEvents = boundary.postRepairEvents.filter((event) => event.event === ROUTE_CHECKPOINT_BOUND_EVENT);
  if (checkpointEvents.length !== 1) return null;
  const checkpointEvent = checkpointEvents[0];
  const checkpointIndex = boundary.postRepairEvents.indexOf(checkpointEvent);
  const phaseEvent = boundary.postRepairEvents[checkpointIndex + 1];
  const transactionCommit = boundary.postRepairEvents[checkpointIndex + 2];
  const details = checkpointEvent.details;
  if (checkpointEvent.taskId !== boundary.marker.taskId
    || checkpointEvent.hash !== eventHash(checkpointEvent)
    || details?.contractFingerprint !== boundary.marker.details.contractFingerprint
    || !isFingerprint(details?.routeFingerprint)
    || canonicalGuideList(details?.selectedGuides) === null
    || !CHECKPOINT_PHASE_EVENTS.has(phaseEvent?.event)
    || phaseEvent.taskId !== boundary.marker.taskId
    || phaseEvent.hash !== eventHash(phaseEvent)
    || !isCommitFor(transactionCommit, "advance")
    || transactionCommit.taskId !== boundary.marker.taskId
    || transactionCommit.hash !== eventHash(transactionCommit)) {
    return null;
  }
  return {
    valid: true,
    checkpointEvent,
    phaseEvent,
    transactionCommit,
    routeFingerprint: details.routeFingerprint,
    contractFingerprint: details.contractFingerprint,
    selectedGuides: [...details.selectedGuides],
  };
}

export function resolveCanonicalPostRepairRouteBinding(events, marker, currentRouteFingerprint) {
  const boundary = resolveContractBootstrapRepairBoundary(events, marker);
  if (!boundary || !isFingerprint(currentRouteFingerprint)) return null;
  const binding = resolveCanonicalRouteEvolution(boundary.postRepairEvents, {
    taskId: boundary.marker.taskId,
    sourceSeq: boundary.repairCommit.seq,
    sourceRouteFingerprint: boundary.marker.details.routeFingerprint,
    targetRouteFingerprint: currentRouteFingerprint,
    contractFingerprint: boundary.marker.details.contractFingerprint,
  });
  if (!binding?.reboundEvents?.length) return null;
  const last = binding.reboundEvents.at(-1);
  return {
    valid: true,
    reboundEvent: last.reboundEvent,
    routeCommit: last.routeCommit,
    reboundEvents: binding.reboundEvents,
  };
}

export function resolveCanonicalRouteEvolution(events, {
  taskId,
  sourceSeq = 0,
  sourceRouteFingerprint,
  targetRouteFingerprint,
  contractFingerprint,
} = {}) {
  if (!Array.isArray(events)
    || typeof taskId !== "string" || !taskId
    || !Number.isInteger(sourceSeq) || sourceSeq < 0
    || (sourceRouteFingerprint !== null && !isFingerprint(sourceRouteFingerprint))
    || !isFingerprint(targetRouteFingerprint)
    || !isFingerprint(contractFingerprint)) return null;
  let currentFingerprint = sourceRouteFingerprint;
  const reboundEvents = [];
  for (let index = 0; index < events.length - 1; index += 1) {
    const reboundEvent = events[index];
    if (reboundEvent?.seq <= sourceSeq || reboundEvent?.event !== "ROUTE_REBOUND") continue;
    const routeCommit = events[index + 1];
    if (!isCanonicalRouteReboundBoundary(reboundEvent, routeCommit, {
      taskId,
      contractFingerprint,
      previousRouteFingerprint: currentFingerprint,
    })) return null;
    reboundEvents.push({ reboundEvent, routeCommit, previousFingerprint: currentFingerprint });
    currentFingerprint = reboundEvent.details.routeFingerprint;
  }
  return currentFingerprint === targetRouteFingerprint
    ? { valid: true, reboundEvents, routeFingerprint: currentFingerprint }
    : null;
}

export function resolveContractBootstrapRepairBoundary(events, marker = null) {
  if (!Array.isArray(events)) return null;
  const markers = events.filter((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (markers.length !== 1) return null;
  const resolvedMarker = marker ?? markers[0];
  const markerIndex = events.indexOf(resolvedMarker);
  if (markerIndex < 0 || resolvedMarker.seq !== markerIndex + 1) return null;
  const repairCommit = events[markerIndex + 1];
  if (!isRepairTransactionCommit(repairCommit, resolvedMarker.taskId)
    || repairCommit.seq !== resolvedMarker.seq + 1) return null;
  return {
    marker: resolvedMarker,
    markerIndex,
    repairCommit,
    repairCommitIndex: markerIndex + 1,
    postRepairEvents: events.slice(markerIndex + 2),
  };
}

function resolveContractBootstrapRepairMigration(events, migration) {
  if (!Array.isArray(events) || !migration || migration.event !== CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT) return null;
  const marker = events.find((event) => event.seq === migration.details?.legacyMarkerSeq);
  const markerIndex = marker ? events.indexOf(marker) : -1;
  const migrationIndex = events.indexOf(migration);
  const commit = events[migrationIndex + 1];
  const boundary = marker ? resolveContractBootstrapRepairBoundary(events, marker) : null;
  if (!marker || !isLegacyContractBootstrapRepairMarkerShape(marker)
    || markerIndex < 0 || !boundary
    || migrationIndex < 0 || migration.seq !== migrationIndex + 1
    || migration.seq <= marker.seq
    || !migrationMatchesLegacyRepairBoundary({ migration, marker, repairCommit: boundary.repairCommit })
    || !migrationCommitFor(commit, migration.taskId)
    || commit.seq !== migration.seq + 1) return null;
  return { marker, migration, migrationCommit: commit };
}

export function resolveEffectiveContractBootstrapRepairAnchor(events) {
  if (!Array.isArray(events)) return null;
  const markers = events.filter((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (markers.length !== 1) return null;
  const sourceMarker = markers[0];
  if (isContractBootstrapRepairMarkerValid(events, sourceMarker)) {
    return { kind: "MODERN", sourceMarker, details: sourceMarker.details };
  }
  if (!isLegacyContractBootstrapRepairMarkerShape(sourceMarker)) return null;
  const migration = events
    .filter((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT)
    .find((event) => event.details?.legacyMarkerSeq === sourceMarker.seq);
  const binding = resolveContractBootstrapRepairMigration(events, migration);
  if (!binding) return null;
  return {
    kind: "MIGRATED_LEGACY",
    sourceMarker,
    migrationEvent: migration,
    details: {
      ...sourceMarker.details,
      reconstructedStateRevision: migration.details.reconstructedStateRevision,
    },
  };
}

export function sameCanonicalGuideList(left, right) {
  const a = canonicalGuideList(left);
  const b = canonicalGuideList(right);
  return a !== null && b !== null && a.length === b.length && a.every((guide, index) => guide === b[index]);
}

export function createPresetContract({ taskId, preset, claims = [] } = {}) {
  if (!Object.prototype.hasOwnProperty.call(PRESET_DEFINITIONS, preset)) {
    const error = new Error(`Unknown contract preset: ${preset}. Expected one of ${CONTRACT_PRESET_IDS.join(", ")}`);
    error.code = "E_CONTRACT_PRESET_UNKNOWN";
    throw error;
  }
  const definition = PRESET_DEFINITIONS[preset];
  const confirmedClaims = normalizedClaims(claims);
  const unresolvedDecisions = confirmedClaims.length > 0
    ? []
    : ["Confirm the concrete deliverables and affected behavior before implementation."];
  return createContract({
    taskId,
    objective: definition.objective,
    deliverables: confirmedClaims.length > 0 ? confirmedClaims : ["Deliverables confirmed by task scope."],
    constraints: definition.constraints,
    risks: definition.risks,
    verification: definition.verification,
    successCriteria: definition.successCriteria,
    stopConditions: definition.stopConditions,
    unresolvedDecisions,
    sourceRefs: [`contract-preset:${preset}`],
  });
}

export function assertContractRevisedDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)
    || Object.keys(details).length !== REVISION_DETAIL_KEYS.length
    || REVISION_DETAIL_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(details, key))) {
    throw invalid(`${CONTRACT_REVISED_EVENT} requires its exact contract-transition detail set`);
  }
  for (const key of ["previousContractFingerprint", "contractFingerprint", "previousStateFingerprint", "revisedStateFingerprint"]) {
    if (!isFingerprint(details[key])) throw invalid(`${CONTRACT_REVISED_EVENT} details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  if (details.previousContractFingerprint === details.contractFingerprint) {
    throw invalid(`${CONTRACT_REVISED_EVENT} must change the contract fingerprint`);
  }
  if (!REVISION_PHASES.has(details.previousPhase) || !REVISION_PHASES.has(details.phase)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} details phase is unsupported`);
  }
  const expectedPhase = details.previousPhase === "PLANNED" ? "ROUTED" : details.previousPhase;
  if (details.phase !== expectedPhase) {
    throw invalid(`${CONTRACT_REVISED_EVENT} phase transition is invalid: ${details.previousPhase} -> ${details.phase}`);
  }
  for (const key of ["previousStateRevision", "revisedStateRevision"]) {
    if (!Number.isInteger(details[key]) || details[key] < 0) {
      throw invalid(`${CONTRACT_REVISED_EVENT} details.${key} must be a non-negative integer`);
    }
  }
  if (details.revisedStateRevision !== details.previousStateRevision + 1) {
    throw invalid(`${CONTRACT_REVISED_EVENT} state revisions must advance exactly once`);
  }
  if (details.previousRouteFingerprint !== null && !isFingerprint(details.previousRouteFingerprint)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} details.previousRouteFingerprint must be a fingerprint or null`);
  }
  if (details.previousPhase === "CONTRACT_READY" && details.previousRouteFingerprint !== null) {
    throw invalid(`${CONTRACT_REVISED_EVENT} CONTRACT_READY revisions cannot have a route fingerprint`);
  }
  if (details.previousPhase !== "CONTRACT_READY" && !isFingerprint(details.previousRouteFingerprint)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} routed revisions require the previous route fingerprint`);
  }
  return details;
}

export function validateContractRevisionEventBindings(events = []) {
  const errors = [];
  const revisions = events.filter((event) => event.event === CONTRACT_REVISED_EVENT);
  let currentContractFingerprint = null;
  let currentStateRevision = null;
  for (const event of revisions) {
    let details;
    try {
      details = assertContractRevisedDetails(event.details);
    } catch (error) {
      errors.push({ code: error.code ?? "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq}: ${error.message}` });
      continue;
    }
    if (!resolveContractRevisionBoundary(events, event)) {
      errors.push({ code: "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq} must be immediately followed by its contract-revise transaction commit` });
    }
    if (events.some((candidate) => candidate.taskId === event.taskId
      && candidate.event === "EXECUTION_STARTED"
      && candidate.seq < event.seq)) {
      errors.push({ code: "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq} occurs after execution started` });
    }
    if (currentContractFingerprint === null) {
      const initial = events.find((candidate) => candidate.taskId === event.taskId
        && candidate.event === "CONTRACT_VALIDATED"
        && candidate.seq < event.seq);
      const initialFingerprint = initial?.fingerprint ?? initial?.details?.contractFingerprint;
      if (!initial || initialFingerprint !== details.previousContractFingerprint) {
        errors.push({ code: "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq} does not continue the initial contract identity` });
      }
    } else if (details.previousContractFingerprint !== currentContractFingerprint) {
      errors.push({ code: "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq} is disconnected from the previous contract revision` });
    }
    if (currentStateRevision !== null && details.previousStateRevision < currentStateRevision) {
      errors.push({ code: "E_CONTRACT_REVISION_UNSAFE", message: `event ${event.seq} rolls back the contract revision state` });
    }
    currentContractFingerprint = details.contractFingerprint;
    currentStateRevision = details.revisedStateRevision;
  }
  return errors;
}

export function assertAssumptions(value, label = "Contract assumptions") {
  if (!Array.isArray(value)) {
    throw new Error(`${label} must be an array`);
  }
  value.forEach((item, index) => {
    assertAssumptionObject(item, `${label}[${index}]`);
  });
  return value;
}

function assertRequirementArray(value, label, seenIds) {
  if (!Array.isArray(value)) {
    throw new Error(`${label} must be an array`);
  }
  value.forEach((item, index) => {
    assertRequirementItem(item, `${label}[${index}]`, seenIds);
  });
}

function assertStringArray(value, label) {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string" || item.trim() === "")) {
    throw new Error(`${label} must be an array of non-empty strings`);
  }
}

export function contractFingerprint(contract) {
  return canonicalFingerprint(contract);
}

export async function validateContract(contract, packageRoot) {
  assertSecretFree(contract);
  assertAssumptions(contract.assumptions ?? []);
  const seenIds = new Set();
  for (const field of CONTRACT_STRING_ARRAY_FIELDS) {
    assertStringArray(contract[field] ?? [], `Contract ${field}`);
  }
  for (const field of CONTRACT_REQUIREMENT_FIELDS) {
    assertRequirementArray(contract[field] ?? [], `Contract ${field}`, seenIds);
  }
  const schema = await readSchema("current-contract", packageRoot);
  assertSchema(contract, schema, "current contract");
  return contract;
}

export function assertCoverageList(value, label = "evidenceCoverage") {
  if (!Array.isArray(value)) throw coverageError("E_EVIDENCE_COVERAGE_INVALID", `${label} must be an array`);
  value.forEach((item, index) => assertCoverage(item, `${label}[${index}]`));
  return value;
}

function coverageError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function coverageForRequirements(requirements, checks, {
  blockedIds = [],
  target,
  taskId,
  authorities,
  options = {},
} = {}) {
  const normalizedRequirements = normalizeRequirements(requirements ?? []);
  const normalizedChecks = Array.isArray(checks) ? checks : [];
  const readiness = evaluateRequiredEvidence({
    requirements: normalizedRequirements,
    checks: normalizedChecks,
    target,
    taskId,
    authorities,
    options,
  });
  const covered = new Set(readiness.covered.map((item) => item.id));
  const partial = new Set(readiness.partial.map((item) => item.id));
  const invalid = new Set(readiness.invalid.map((item) => item.id));
  const blocked = new Set(blockedIds);
  return normalizedRequirements.filter((requirement) => !requirement.terminalOwned).map((requirement) => createCoverage({
    requirement: requirement.text,
    requiredEvidence: [requirement.text],
    observedEvidence: covered.has(requirement.id) ? [requirement.text] : [],
    blocked: blocked.has(requirement.text) || blocked.has(requirement.id),
    ...(partial.has(requirement.id) || invalid.has(requirement.id) ? {
      status: "PARTIAL",
      details: { requirementId: requirement.id, readinessStatus: "PARTIAL" },
    } : {}),
  }));
}

export function decisionArtifactFingerprint(artifact) {
  return canonicalFingerprint(artifact);
}

export function decisionError(code, message, artifacts = []) {
  return new DecisionError(code, message, artifacts);
}

export function decisionEventDetails(artifact) {
  return {
    decisionId: artifact.decisionId,
    decisionKind: artifact.decisionKind,
    artifactFingerprint: canonicalFingerprint(artifact),
    questionSetFingerprint: artifact.questionSetFingerprint,
    stateFingerprint: artifact.stateFingerprint,
    model: artifact.model,
    status: "RECORDED",
  };
}

export function decisionSupersededEventDetails(previousArtifact, supersededBy) {
  return {
    ...decisionEventDetails(previousArtifact),
    supersededBy,
  };
}

export async function validateSemanticDecisionArtifactBindings(target, packageRoot, events = []) {
  const errors = [];
  for (const event of events) {
    if (event.event !== SEMANTIC_DECISION_RECORDED_EVENT) continue;
    try {
      const artifact = (await readDecisionArtifact(target, event.taskId, event.details.decisionId, packageRoot)).value;
      if (artifact.taskId !== event.taskId
        || artifact.decisionId !== event.details.decisionId
        || canonicalFingerprint(artifact) !== event.details.artifactFingerprint
        || artifact.questionSetFingerprint !== event.details.questionSetFingerprint
        || artifact.stateFingerprint !== event.details.stateFingerprint
        || artifact.model !== event.details.model) {
        errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} does not match its immutable semantic decision artifact` });
      }
    } catch (error) {
      errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} semantic decision artifact is unavailable or invalid` });
    }
  }
  return errors;
}

export function validateSemanticDecisionEventBindings(events = []) {
  const errors = [];
  const recorded = new Map();
  for (const event of events) {
    if (![SEMANTIC_DECISION_RECORDED_EVENT, SEMANTIC_DECISION_SUPERSEDED_EVENT].includes(event.event)) continue;
    try { assertSemanticDecisionDetails(event.details, event.event); } catch (error) {
      errors.push({ code: error.code ?? DECISION_ERROR_CODES.RESULT_INVALID, message: `event ${event.seq} (${event.event}): ${error.message}` });
      continue;
    }
    if (event.event === SEMANTIC_DECISION_RECORDED_EVENT) {
      const key = `${event.taskId}:${event.details.decisionId}`;
      if (recorded.has(key)) {
        errors.push({ code: DECISION_ERROR_CODES.RESULT_INVALID, message: `event ${event.seq} records duplicate decision ID ${event.details.decisionId}` });
      }
      recorded.set(key, event);
    }
    if (event.event === SEMANTIC_DECISION_SUPERSEDED_EVENT) {
      const key = `${event.taskId}:${event.details.decisionId}`;
      if (!recorded.has(key)) errors.push({ code: DECISION_ERROR_CODES.RESULT_INVALID, message: `event ${event.seq} supersedes a decision that was not recorded` });
      if (!recorded.has(`${event.taskId}:${event.details.supersededBy}`)) {
        errors.push({ code: DECISION_ERROR_CODES.RESULT_INVALID, message: `event ${event.seq} points to a superseding decision that was not recorded` });
      }
      const next = events.find((candidate) => candidate.seq === event.seq + 1);
      if (next?.event !== "TRANSACTION_COMMITTED" || next.taskId !== event.taskId || next.details?.operation !== "semantic-decision") {
        errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} supersession is not closed by a semantic-decision transaction` });
      }
    }
    if (event.event === SEMANTIC_DECISION_RECORDED_EVENT) {
      const next = events.find((candidate) => candidate.seq === event.seq + 1);
      const closesDirectly = next?.event === "TRANSACTION_COMMITTED" && next.taskId === event.taskId && next.details?.operation === "semantic-decision";
      const continuesWithSupersession = next?.event === SEMANTIC_DECISION_SUPERSEDED_EVENT && next.taskId === event.taskId;
      if (!closesDirectly && !continuesWithSupersession) {
        errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} is not closed by the semantic-decision transaction boundary` });
      }
    }
  }
  return errors;
}

export function decisionPolicyFingerprint(policy) {
  return canonicalFingerprint(normalizeDecisionPolicy(policy));
}

export function normalizeDecisionPolicy(input = {}) {
  const policy = { ...DECISION_DEFAULT_POLICY, ...input };
  if (policy.required !== true || policy.provider !== DECISION_ENGINE_ID || policy.model !== PINNED_JEV_MODEL) {
    throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "ForgeLoop Jev policy must remain mandatory and pinned.");
  }
  if (!Number.isInteger(policy.policyVersion) || policy.policyVersion < 1 || !Number.isInteger(policy.requestTimeoutMs) || policy.requestTimeoutMs < 500 || policy.requestTimeoutMs > 60_000 || !Number.isInteger(policy.maxRetries) || policy.maxRetries < 0 || policy.maxRetries > 3 || typeof policy.cache !== "boolean") {
    throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "ForgeLoop Jev policy limits are invalid.");
  }
  return Object.freeze(policy);
}

export function buildContextQuestionSet(candidates = []) {
  const bounded = candidates.slice(0, 64);
  const questions = Object.fromEntries(bounded.map((candidate, index) => [
    `candidate_${index}_relevant`, {
      type: "noul",
      criteria: { yes: `Candidate ${candidate.id} is relevant to the bounded task context`, no: `Candidate ${candidate.id} is not relevant to the bounded task context` },
    },
  ]));
  return buildDynamicQuestionSet({
    id: "context-candidates-v1", decisionKind: "CONTEXT_PLAN", questions,
    candidateIds: bounded.map((candidate) => candidate.id),
    metadata: { candidateQuestionPrefix: "candidate_", relevanceSuffix: "_relevant" },
  });
}

export function buildDynamicQuestionSet({ id, version = 1, decisionKind, questions, candidateIds = [], metadata = {} } = {}) {
  if (typeof id !== "string" || !id || !Number.isInteger(version) || version < 1
    || typeof decisionKind !== "string" || !questions || typeof questions !== "object"
    || Array.isArray(questions)) {
    throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Dynamic semantic question set is invalid.");
  }
  const names = Object.keys(questions);
  if (names.length === 0 || names.length > 128 || names.some((name) => !/^[a-z][a-z0-9_]{0,95}$/.test(name))) {
    throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Dynamic semantic question set has invalid bounded questions.");
  }
  return freezeQuestionSet({ id, version, decisionKind, questions, candidateIds: [...candidateIds].slice(0, 64), metadata });
}

export function buildTestUtilityQuestionSet(tests = []) {
  const dimensions = ["unique_semantic_intent", "semantic_duplicate", "likely_obsolete", "likely_flaky_low_signal", "expensive_relative_to_signal", "documentation_value", "integration_value", "guards_regression_prone_behavior", "requires_system_two_review"];
  const bounded = tests.slice(0, 16);
  const questions = {};
  for (let index = 0; index < bounded.length; index += 1) {
    for (const dimension of dimensions) questions[`test_${index}_${dimension}`] = {
      type: "noul", criteria: { yes: `${dimension} applies to test ${bounded[index].testId}`, no: `${dimension} does not apply to test ${bounded[index].testId}` },
    };
  }
  return buildDynamicQuestionSet({
    id: "test-utility-candidates-v1", decisionKind: "TEST_UTILITY", questions,
    candidateIds: bounded.map((test) => test.testId),
    metadata: { dimensions, candidateQuestionPrefix: "test_", testCount: bounded.length },
  });
}

function freezeQuestionSet(definition) {
  return Object.freeze({
    ...definition,
    questions: Object.freeze({ ...definition.questions }),
    fingerprint: canonicalFingerprint(definition.questions),
  });
}

export function validateDecisionRequest(input = {}) {
  if (!input || typeof input !== "object" || Array.isArray(input)) throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Decision request must be an object.");
  if (typeof input.taskId !== "string" || !input.taskId) throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Decision request requires a taskId.");
  if (!DECISION_KINDS.includes(input.decisionKind)) throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Decision request has an unsupported decision kind.");
  if (typeof input.questionSetId !== "string" && !input.questionSet) throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Decision request requires a question set.");
  const questionSet = input.questionSet ?? getQuestionSet(input.questionSetId);
  if (typeof questionSet.id !== "string" || typeof questionSet.fingerprint !== "string") throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Decision request question set is not canonical.");
  if (questionSet.decisionKind !== input.decisionKind) throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Question set does not match decision kind.");
  if (input.model !== undefined && input.model !== PINNED_JEV_MODEL) throw decisionError(DECISION_ERROR_CODES.MODEL_UNSUPPORTED, "Only the pinned ForgeLoop Jev model is supported.");
  const state = input.state && typeof input.state === "object"
    && (Object.prototype.hasOwnProperty.call(input.state, "lifecycle")
      || Object.prototype.hasOwnProperty.call(input.state, "semantic"))
    ? buildCombinedDecisionState(input.state)
    : buildCombinedDecisionState({ semantic: input.state ?? {} });
  return {
    ...input,
    model: PINNED_JEV_MODEL,
    questionSet,
    state,
  };
}

export function assertRequiredFreshDecision({ artifact, currentBindings = {}, expectedDecisionKind, expectedTaskId, expectedQuestionSetId, ledger = [] } = {}) {
  assertCanonicalArtifact(artifact, { expectedDecisionKind, expectedTaskId, expectedQuestionSetId });
  if (!Array.isArray(ledger)) throw invalid("Semantic decision ledger is unavailable.", DECISION_ERROR_CODES.LEDGER_INVALID);
  const record = decisionRecordForArtifact(ledger, artifact);
  if (!record || record.details.artifactFingerprint !== canonicalFingerprint(artifact)) {
    throw invalid("Semantic decision has no matching canonical ledger record.", DECISION_ERROR_CODES.LEDGER_INVALID);
  }
  if (isSuperseded(ledger, artifact)) throw decisionError(DECISION_ERROR_CODES.STALE, "Semantic decision has been superseded.");
  assertDecisionFresh(artifact, {
    ...currentBindings,
    model: PINNED_JEV_MODEL,
    policyFingerprint: currentBindings.policyFingerprint ?? artifact.policyFingerprint,
  });
  return artifact;
}

function isSuperseded(events, artifact) {
  return events.some((event) => event.event === SEMANTIC_DECISION_SUPERSEDED_EVENT
    && event.taskId === artifact.taskId
    && event.details?.decisionId === artifact.decisionId);
}

export function normalizeDecisionResult(raw, { questionSet, input = {}, model = PINNED_JEV_MODEL } = {}) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw decisionError(DECISION_ERROR_CODES.RESULT_INVALID, "Semantic decision result must be an object.");
  if (raw.model !== model || raw.model !== PINNED_JEV_MODEL) throw decisionError(DECISION_ERROR_CODES.MODEL_UNSUPPORTED, "Semantic decision result used an unsupported model.");
  if (!raw.answers || typeof raw.answers !== "object" || Array.isArray(raw.answers)) throw decisionError(DECISION_ERROR_CODES.RESULT_INVALID, "Semantic decision result is missing answers.");
  const answers = normalizeAnswers(raw.answers, questionSet);
  const confidence = normalizeConfidence(raw.confidence, questionSet);
  const usage = normalizeUsage(raw.usage);
  return {
    model,
    questionSetId: questionSet?.id ?? null,
    answers,
    confidence: Object.fromEntries(Object.keys(questionSet.questions).map((key) => [key, confidence[key] ?? null])),
    decision: normalizeCanonicalDecision({ questionSet, answers, confidence, input }),
    usage,
  };
}

export async function ensureSemanticDecision({ target, packageRoot, taskId, decisionId, request, provider = null, allowNetwork = true } = {}) {
  const policy = await loadPolicy(target, packageRoot);
  const taskBindings = await readCurrentDecisionBindings(target, packageRoot, taskId);
  const validated = validateDecisionRequest({
    ...request,
    taskId,
    state: { lifecycle: taskBindings.state ?? {}, semantic: request?.state ?? {} },
  });
  const currentBindings = {
    ...taskBindings,
    stateFingerprint: canonicalFingerprint(validated.state),
    taskStateFingerprint: canonicalFingerprint(validated.state.lifecycle),
    semanticStateFingerprint: canonicalFingerprint(validated.state.semantic),
    questionSetFingerprint: validated.questionSet.fingerprint,
    policyFingerprint: decisionPolicyFingerprint(policy),
    model: PINNED_JEV_MODEL,
    ...(request?.candidateSetFingerprint !== undefined ? { candidateSetFingerprint: request.candidateSetFingerprint } : {}),
  };
  const cached = await getTaskTransaction(target) ? null : await readCachedDecision({
    target, packageRoot, taskId, decisionKind: validated.decisionKind,
    currentBindings,
  });
  if (cached) return { artifact: cached, artifactFingerprint: decisionArtifactFingerprint(cached), cached: true, policy };
  if (!allowNetwork && !provider) throw decisionError(DECISION_ERROR_CODES.REQUIRED, `A current ${validated.decisionKind} decision is required.`);
  return recordSemanticDecision({ target, packageRoot, taskId, decisionId, request: { ...request, questionSet: validated.questionSet }, provider });
}

async function loadPolicy(target, packageRoot) {
  try {
    const config = await readConfig(target, packageRoot);
    return normalizeDecisionPolicy(config.decisionEngine ?? DECISION_DEFAULT_POLICY);
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return normalizeDecisionPolicy(DECISION_DEFAULT_POLICY);
    throw error;
  }
}

async function readCachedDecision({ target, packageRoot, taskId, decisionKind, currentBindings }) {
  try {
    return await resolveRequiredSemanticDecision({ target, packageRoot, taskId, decisionKind, currentBindings });
  } catch (error) {
    if (["E_DECISION_REQUIRED", "E_DECISION_STALE", "E_DECISION_BINDING_INVALID"].includes(error.code)) return null;
    throw error;
  }
}

async function readCachedSemanticDecision({ policy, decisionId, target, taskId, packageRoot, validated, taskBindings, request }) {
  if (!policy.cache || decisionId || !target || !taskId || await getTaskTransaction(target)) return null;
  return readCachedDecision({
    target,
    packageRoot,
    taskId,
    decisionKind: validated.decisionKind,
    currentBindings: {
      ...taskBindings,
      stateFingerprint: canonicalFingerprint(validated.state),
      taskStateFingerprint: canonicalFingerprint(validated.state.lifecycle),
      semanticStateFingerprint: canonicalFingerprint(validated.state.semantic),
      questionSetFingerprint: validated.questionSet.fingerprint,
      policyFingerprint: decisionPolicyFingerprint(policy),
      model: PINNED_JEV_MODEL,
      ...(request?.candidateSetFingerprint !== undefined ? { candidateSetFingerprint: request.candidateSetFingerprint } : {}),
      ...(request?.policyFingerprint !== undefined ? { policyFingerprint: request.policyFingerprint } : {}),
    },
  });
}

function resolveProvider(provider) {
  return provider ?? getTestSemanticProvider();
}

export function buildDecisionState(value) {
  const counters = { bytes: 0 };
  const sanitized = sanitize(value, 0, counters);
  const bytes = Buffer.byteLength(JSON.stringify(sanitized));
  if (bytes > DECISION_LIMITS.maxStateBytes) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state exceeds the supported byte limit.");
  return sanitized;
}

function isHomePath(value) {
  return typeof value === "string" && (/^\/Users\/[^/]+\//.test(value) || /^\/home\/[^/]+\//.test(value));
}

function sanitize(value, depth, counters) {
  if (depth > DECISION_LIMITS.maxDepth) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state nesting exceeds the supported limit.");
  if (value === null || typeof value === "boolean" || typeof value === "number") return value;
  if (typeof value === "string") {
    if (/[^\x09\x0A\x0D\x20-\uD7FF\uE000-\uFFFD]/u.test(value)) throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains unsafe control characters.");
    if (SECRET_VALUE.test(value)) throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains a secret-like value.");
    if (isHomePath(value)) return "<redacted-user-path>";
    counters.bytes += Buffer.byteLength(value);
    if (value.length > DECISION_LIMITS.maxStringChars) return `${value.slice(0, DECISION_LIMITS.maxStringChars)}…<truncated>`;
    return value;
  }
  if (Array.isArray(value)) {
    if (value.length > DECISION_LIMITS.maxItems) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state contains too many items.");
    return value.map((item) => sanitize(item, depth + 1, counters));
  }
  if (typeof value === "object") {
    const entries = Object.entries(value);
    if (entries.length > DECISION_LIMITS.maxItems) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state contains too many fields.");
    const result = {};
    for (const [key, child] of entries) {
      if (SECRET_KEY.test(key) || key.toLowerCase() === "env" || key.toLowerCase() === "environment") continue;
      result[key] = sanitize(child, depth + 1, counters);
    }
    return result;
  }
  throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains an unsupported value.");
}

async function readOptionalArtifact(reader) {
  try {
    return await reader();
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return null;
    throw error;
  }
}

export function createDiagnosisDetails(input, previous = null) {
  if (typeof input?.verificationCycle !== "number" || !Number.isInteger(input.verificationCycle) || input.verificationCycle < 1) {
    const error = new Error("verificationCycle must be an integer >= 1");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  try {
    assertFailureClass(input.failureClass);
  } catch {
    const error = new Error(`Invalid failureClass: ${input.failureClass}`);
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (typeof input.hypothesis !== "string" || !input.hypothesis.trim()) {
    const error = new Error("hypothesis must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (!Array.isArray(input.evidenceRefs) || input.evidenceRefs.length === 0) {
    const error = new Error("evidenceRefs must be a non-empty array");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  const cleanRefs = input.evidenceRefs.map((r) => {
    if (typeof r !== "string" || !r.trim()) {
      const error = new Error("each evidenceRef must be a non-empty string");
      error.code = "E_DIAGNOSIS_INVALID";
      throw error;
    }
    return r.trim();
  });
  const uniqueRefs = [...new Set(cleanRefs)].sort();
  if (typeof input.settledBy !== "string" || !input.settledBy.trim()) {
    const error = new Error("settledBy must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (typeof input.nextSafeAction !== "string" || !input.nextSafeAction.trim()) {
    const error = new Error("nextSafeAction must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }

  const fingerprint = diagnosisFingerprint({
    failureClass: input.failureClass,
    hypothesis: input.hypothesis,
    evidenceRefs: uniqueRefs,
  });
  const infoGain = classifyDiagnosisInformationGain(
    { hypothesis: input.hypothesis, evidenceRefs: uniqueRefs },
    previous ? { hypothesis: previous.hypothesis, evidenceRefs: previous.evidenceRefs } : null,
  );

  return {
    verificationCycle: input.verificationCycle,
    failureClass: input.failureClass,
    hypothesis: input.hypothesis.trim(),
    evidenceRefs: uniqueRefs,
    settledBy: input.settledBy.trim(),
    nextSafeAction: input.nextSafeAction.trim(),
    diagnosisFingerprint: fingerprint,
    informationGain: infoGain,
    previousDiagnosisFingerprint: previous?.diagnosisFingerprint ?? null,
  };
}

export function currentCycleDiagnosis(events, taskId, verificationCycle) {
  const taskEvents = diagnosisEventsForTask(events, taskId);
  for (let i = taskEvents.length - 1; i >= 0; i--) {
    if (taskEvents[i].details?.verificationCycle === verificationCycle) {
      return taskEvents[i];
    }
  }
  return null;
}

export function diagnosisEventsForTask(events, taskId) {
  if (!Array.isArray(events)) return [];
  return events.filter((e) => e.event === "DIAGNOSIS_RECORDED" && (!taskId || e.taskId === taskId));
}

export function diagnosisFingerprint({ failureClass, hypothesis, evidenceRefs }) {
  assertFailureClass(failureClass);
  const normalizedHypothesis = normalizeDiagnosisText(hypothesis, "hypothesis");
  if (!Array.isArray(evidenceRefs) || evidenceRefs.length === 0) {
    const error = new Error("evidenceRefs must be a non-empty array of strings");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  const cleanRefs = evidenceRefs.map((ref) => {
    if (typeof ref !== "string" || !ref.trim()) {
      const error = new Error("evidenceRef must be a non-empty string");
      error.code = "E_DIAGNOSIS_INVALID";
      throw error;
    }
    return ref.trim();
  });
  const normalizedRefs = [...new Set(cleanRefs)].sort();
  return canonicalFingerprint({
    failureClass,
    hypothesis: normalizedHypothesis,
    evidenceRefs: normalizedRefs,
  });
}

export function assertDiagnosticCaseDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "Diagnostic case details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `diagnostic case schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_DIAGNOSTIC_CASE_CYCLE_MISMATCH", "verificationCycle must be an integer >= 1");
  }
  if (!Number.isInteger(details.diagnosticRevision) || details.diagnosticRevision < 1) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticRevision must be an integer >= 1");
  }
  try {
    assertFailureClass(details.failureClass);
  } catch {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `invalid failureClass: ${details.failureClass}`);
  }

  if (!Array.isArray(details.observations) || details.observations.length > LIMITS.observationsPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `observations must be an array of at most ${LIMITS.observationsPerCase}`);
  }
  details.observations.forEach((observation, index) => assertObservation(observation, `observations[${index}]`));

  if (!Array.isArray(details.contributors) || details.contributors.length > LIMITS.contributorsPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `contributors must be an array of at most ${LIMITS.contributorsPerCase}`);
  }
  details.contributors.forEach((contributor, index) => assertContributor(contributor, `contributors[${index}]`));

  if (!Array.isArray(details.hypotheses)
    || details.hypotheses.length < 1
    || details.hypotheses.length > LIMITS.hypothesesPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `hypotheses must contain between 1 and ${LIMITS.hypothesesPerCase} hypotheses`);
  }
  details.hypotheses.forEach((hypothesis, index) => assertHypothesis(hypothesis, `hypotheses[${index}]`));

  const ids = [
    ...details.observations.map((o) => o.id),
    ...details.contributors.map((c) => c.id),
    ...details.hypotheses.map((h) => h.id),
  ];
  if (new Set(ids).size !== ids.length) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "duplicate IDs within the same diagnostic case are not allowed");
  }
  const observationIds = new Set(details.observations.map((o) => o.id));
  const contributorIds = new Set(details.contributors.map((c) => c.id));
  for (const contributor of details.contributors) {
    for (const basis of contributor.basis ?? []) {
      if (!observationIds.has(basis)) invalid("E_CONTRIBUTOR_REFERENCE_INVALID", `contributor ${contributor.id} references unknown observation ${basis}`);
    }
  }
  for (const hypothesis of details.hypotheses) {
    for (const ref of hypothesis.contributorRefs ?? []) {
      if (!contributorIds.has(ref)) invalid("E_CONTRIBUTOR_REFERENCE_INVALID", `hypothesis ${hypothesis.id} references unknown contributor ${ref}`);
    }
  }

  if (!details.nextSafeAction || typeof details.nextSafeAction !== "object"
    || typeof details.nextSafeAction.statement !== "string" || !details.nextSafeAction.statement.trim()) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "nextSafeAction.statement must be a non-empty string");
  }
  if (details.nextSafeAction.statement.length > LIMITS.statementLength) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `nextSafeAction.statement exceeds ${LIMITS.statementLength} characters`);
  }

  if (typeof details.diagnosticFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.diagnosticFingerprint)) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticFingerprint must be a SHA-256 fingerprint");
  }
  const computed = diagnosticSemanticFingerprint({
    verificationCycle: details.verificationCycle,
    failureClass: details.failureClass,
    case_: details,
  });
  if (computed !== details.diagnosticFingerprint) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticFingerprint does not match computed semantic fingerprint");
  }
  if (details.previousDiagnosticFingerprint !== undefined && details.previousDiagnosticFingerprint !== null
    && (typeof details.previousDiagnosticFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.previousDiagnosticFingerprint))) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "previousDiagnosticFingerprint must be a SHA-256 fingerprint or null");
  }
  return details;
}

export function assertHypothesisDispositionDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", "Disposition event details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", `disposition schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", "disposition verificationCycle must be an integer >= 1");
  }
  assertDiagnosticId(details.hypothesisRef, "hypothesisRef");
  if (!HYPOTHESIS_STATUSES.includes(details.status)) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", `disposition status must be one of ${HYPOTHESIS_STATUSES.join(", ")}`);
  }
  assertStringRefArray(
    details.evidenceRefs ?? [],
    "evidenceRefs",
    LIMITS.evidenceRefsPerHypothesis,
    "E_HYPOTHESIS_DISPOSITION_EVIDENCE_INVALID",
  );
  if ((details.evidenceRefs ?? []).length === 0) {
    invalid("E_HYPOTHESIS_DISPOSITION_EVIDENCE_INVALID", "disposition requires at least one evidenceRef");
  }
  assertBoundedText(details.reason, "reason", LIMITS.reasonLength, "E_HYPOTHESIS_DISPOSITION_INVALID");
  return details;
}

export function assertInterventionDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_INTERVENTION_INVALID", "Intervention event details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_INTERVENTION_INVALID", `intervention schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_INTERVENTION_INVALID", "intervention verificationCycle must be an integer >= 1");
  }
  const intervention = details.intervention;
  if (!intervention || typeof intervention !== "object" || Array.isArray(intervention)) {
    invalid("E_INTERVENTION_INVALID", "intervention.intervention must be an object");
  }
  assertDiagnosticId(intervention.id, "intervention.id");
  if (!INTERVENTION_KINDS.includes(intervention.kind)) {
    invalid("E_INTERVENTION_INVALID", `intervention.kind must be one of ${INTERVENTION_KINDS.join(", ")}`);
  }
  assertBoundedText(intervention.statement, "intervention.statement", LIMITS.statementLength, "E_INTERVENTION_INVALID");
  assertStringRefArray(intervention.targets ?? [], "intervention.targets", 32);
  const hypothesisRefs = assertStringRefArray(
    intervention.hypothesisRefs ?? [],
    "intervention.hypothesisRefs",
    LIMITS.hypothesesPerCase,
    "E_INTERVENTION_REFERENCE_INVALID",
  );
  if (hypothesisRefs.length === 0) {
    invalid("E_INTERVENTION_HYPOTHESIS_MISSING", "intervention must bind to at least one hypothesis");
  }
  if (intervention.reversible !== undefined && typeof intervention.reversible !== "boolean") {
    invalid("E_INTERVENTION_INVALID", "intervention.reversible must be boolean");
  }
  return details;
}

export function diagnosticSemanticFingerprint({ verificationCycle, failureClass, case_ }) {
  return canonicalFingerprint({
    verificationCycle,
    failureClass,
    observations: [...case_.observations]
      .map(({ kind, evidenceRef, statement, provenance }) => canonicalizeDiagnosticValue({ kind, evidenceRef, statement, provenance }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    contributors: [...case_.contributors]
      .map(({ type, statement, basis, status }) => canonicalizeDiagnosticValue({ type, statement, basis, status }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    hypotheses: [...case_.hypotheses]
      .map(({ statement, contributorRefs, evidenceRefs, settledBy }) => canonicalizeDiagnosticValue({ statement, contributorRefs, evidenceRefs, settledBy }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    nextSafeAction: canonicalizeDiagnosticValue(case_.nextSafeAction?.statement ?? null),
  });
}

export function interventionSemanticFingerprint(details) {
  const intervention = details.intervention;
  return canonicalFingerprint({
    kind: intervention.kind,
    statement: normalizeDiagnosticText(intervention.statement),
    targets: [...new Set((intervention.targets ?? []).map((target) => target.trim()))].sort(),
    hypothesisRefs: [...new Set((intervention.hypothesisRefs ?? []).map((ref) => ref.trim()))].sort(),
  });
}

export function resolveCurrentCycleDiagnostic(events, taskId, verificationCycle) {
  const candidates = diagnosticEventsForTask(events, taskId)
    .filter((event) => {
      const cycle = event.details?.verificationCycle;
      return (verificationCycle === null || verificationCycle === undefined)
        || (cycle === null || cycle === undefined)
        || cycle === verificationCycle;
    })
    .sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));

  const structured = [...candidates].reverse().find((event) => event.event === "DIAGNOSTIC_CASE_RECORDED");
  if (structured) return structuredProjection(structured);

  const legacy = [...candidates].reverse().find((event) => event.event === "DIAGNOSIS_RECORDED");
  if (legacy) return legacyProjection(legacy);

  return null;
}

const findActiveCheck = (ref) => activeCycleChecks.find(
  (candidate) => candidate.id === ref || candidate.checkId === ref,
);

function canTransitionStatus(from, to) {
  if (from === to) return false;
  if (TERMINAL_STATUSES.includes(from)) return false;
  return (DISPOSITION_TRANSITIONS[from] ?? []).includes(to);
}

async function requireValidLedger(target, packageRoot, taskId) {
  const ledger = await validateEventLedger(target, packageRoot, { taskId: taskId ?? null });
  if (!ledger.valid) {
    throw stateError(ledger.errors[0].code ?? "E_EVENT_INVALID", ledger.errors[0].message);
  }
  return ledger;
}

function stateError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function buildProtocolEvent(input, { checkpoint } = {}) {
  if (!checkpoint || !Number.isInteger(checkpoint.seq) || checkpoint.seq < 0
    || (checkpoint.lastHash !== null && !/^[a-f0-9]{64}$/.test(checkpoint.lastHash))) {
    throw protocolError("E_EVENT_INVALID", "event checkpoint is invalid");
  }
  const event = {
    seq: checkpoint.seq + 1,
    schemaVersion: EVENT_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    taskId: input.taskId,
    event: input.event,
    at: input.at ?? new Date().toISOString(),
    ...(input.fingerprint ? { fingerprint: input.fingerprint } : {}),
    previousHash: checkpoint.lastHash,
    ...(input.details ? { details: structuredClone(input.details) } : {}),
  };
  validateKnownEventDetails(event);
  assertSecretFree(event);
  event.hash = eventHash(event);
  return event;
}

function checkpointFromEvents(events) {
  const last = events.at(-1) ?? null;
  return {
    schemaVersion: 1,
    seq: last?.seq ?? 0,
    lastHash: last?.hash ?? null,
  };
}

export function eventHash(event) {
  const { hash, ...body } = event;
  return canonicalFingerprint(body);
}

function eventIndexPath(eventsPath) {
  return `${eventsPath}.index.json`;
}

function parseEventIndex(text, relativePath) {
  if (typeof text !== "string") return null;
  try {
    const value = JSON.parse(text);
    if (!value || value.schemaVersion !== 1 || !Number.isInteger(value.seq) || value.seq < 0
      || (value.lastHash !== null && !/^[a-f0-9]{64}$/.test(value.lastHash))) return null;
    return value;
  } catch {
    return null;
  }
}

async function parseEventsText(text, relPath, packageRoot) {
  assertJsonBytes(text, relPath);
  const schema = await readSchema("event", packageRoot);
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== "");
  return lines.map((line, index) => {
    let event;
    try {
      event = JSON.parse(line);
      assertJsonLimits(event, `${relPath}[${index}]`);
      assertSchema(event, schema, `${relPath}[${index}]`);
      validateKnownEventDetails(event);
    } catch (error) {
      throw protocolError(error.code ?? "E_EVENT_INVALID", `${relPath} line ${index + 1}: ${error.message}`, [relPath]);
    }
    return event;
  });
}

function protocolError(code, message, artifacts = [ARTIFACT_PATHS.events]) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function validateCompletionRecoveryAuthorization({ state, receipt, events } = {}) {
  const errors = [];
  if (!state) {
    return {
      authorized: false,
      errors: [{ code: "E_STATE_MISSING", message: "Work-state is required for recovery validation" }],
    };
  }
  const attempt = state.lastCompletionAttempt;
  if (!attempt || attempt.status !== "REJECTED") {
    return {
      authorized: false,
      errors: [{ code: "E_COMPLETION_RECOVERY_UNAUTHORIZED", message: "Recovery requires a persisted REJECTED completion attempt" }],
    };
  }
  const hasRecoverableReason = Array.isArray(attempt.reasonCodes)
    && attempt.reasonCodes.length > 0
    && attempt.reasonCodes.every((code) => isRecoverableCompletionEvidenceCode(code));
  if (!hasRecoverableReason) {
    return {
      authorized: false,
      errors: [{ code: "E_COMPLETION_RECOVERY_UNAUTHORIZED", message: "Completion attempt contains no recoverable evidence reason codes" }],
    };
  }

  const taskEvents = (events ?? []).filter((event) => event.taskId === state.taskId);
  const targetCycle = state.verificationCycle ?? 1;

  if (attempt.verificationCycle !== targetCycle) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: `Work-state rejection verificationCycle ${attempt.verificationCycle} does not match state verificationCycle ${targetCycle}`,
    });
    return { authorized: false, errors };
  }

  const reviewEvents = taskEvents
    .map((event, index) => ({ event, index }))
    .filter(({ event }) => event.event === "REVIEW_STARTED" && (event.details?.verificationCycle ?? 1) === targetCycle);
  const latestReviewIndex = reviewEvents.at(-1)?.index ?? -1;

  const rejectionEvents = taskEvents
    .map((event, index) => ({ event, index }))
    .filter(({ event }) => event.event === "COMPLETION_REJECTED");

  if (rejectionEvents.length === 0) {
    errors.push({
      code: "E_COMPLETION_RECOVERY_UNAUTHORIZED",
      message: "No COMPLETION_REJECTED event found in protocol ledger",
    });
    return { authorized: false, errors };
  }

  const matchingEvent = rejectionEvents.findLast(({ event, index }) => {
    const eventCycle = event.details?.verificationCycle ?? 1;
    if (eventCycle !== targetCycle) return false;
    if (latestReviewIndex >= 0 && index < latestReviewIndex) return false;
    return true;
  });

  if (!matchingEvent) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: `No matching COMPLETION_REJECTED event found for verification cycle ${targetCycle}`,
    });
    return { authorized: false, errors };
  }

  const eventDetails = matchingEvent.event.details ?? {};
  const stateReasons = [...new Set(attempt.reasonCodes ?? [])].sort();
  const eventReasons = [...new Set(eventDetails.reasonCodes ?? [])].sort();
  if (stateReasons.join(",") !== eventReasons.join(",")) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: "Work-state rejection reasonCodes do not match ledger COMPLETION_REJECTED event",
    });
  }

  const stateMissing = [...new Set(attempt.missingRequirementIds ?? [])].sort();
  const eventMissing = [...new Set(eventDetails.missingRequirementIds ?? [])].sort();
  if (stateMissing.join(",") !== eventMissing.join(",")) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: "Work-state missingRequirementIds do not match ledger COMPLETION_REJECTED event",
    });
  }

  const currentStateFingerprint = canonicalFingerprint(state);
  if (eventDetails.stateFingerprint && eventDetails.stateFingerprint !== currentStateFingerprint) {
    errors.push({
      code: "E_COMPLETION_REJECTION_STATE_FINGERPRINT_MISMATCH",
      message: "Current work-state no longer matches the rejected completion snapshot",
    });
  }

  if (eventDetails.receiptFingerprint !== undefined) {
    const currentReceiptFingerprint = receipt ? canonicalFingerprint(receipt) : undefined;
    if (currentReceiptFingerprint !== eventDetails.receiptFingerprint) {
      errors.push({
        code: "E_COMPLETION_REJECTION_RECEIPT_FINGERPRINT_MISMATCH",
        message: "Current receipt no longer matches the rejected completion snapshot",
      });
    }
  }

  return {
    authorized: errors.length === 0,
    errors,
  };
}

function validateContractBootstrapRepairLedger(events, errors, options) {
  const allowUnmigrated = options?.allowUnmigratedLegacyContractBootstrapRepairMarkers === true;
  validateContractBootstrapRepairMigrations(events, errors, {
    allowUnmigratedLegacyContractBootstrapRepairMarkers: allowUnmigrated,
  });
  return repairMarkerErrors(events, errors, {
    allowUnmigratedLegacyContractBootstrapRepairMarkers: allowUnmigrated,
  });
}

function validateExecutionGateChronology(events, index, seen, errors) {
  if (!seen.has("ROUTE_VALIDATED")) errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "execution started before route validation" });
  if (!seen.has("CONTRACT_VALIDATED")) errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "execution started before contract validation" });
  if (!seen.has("PREFLIGHT_READY")) errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "execution started before preflight readiness" });
  const preflight = events.slice(0, index).findLast((candidate) => candidate.event === "PREFLIGHT_READY");
  const requiredGates = preflight?.details?.requiredGates ?? [];
  const latestContractRevisionSeq = events.slice(0, index).findLast((candidate) => candidate.event === CONTRACT_REVISED_EVENT)?.seq ?? 0;
  const beforeExecution = events.slice(0, index);
  for (const gate of requiredGates) {
    if (!hasCurrentGateEvidence(beforeExecution, events[index]?.taskId, gate, latestContractRevisionSeq)) {
      errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: `execution started before gate satisfaction: ${gate}` });
    }
  }
}

export function validateKnownEventDetails(event) {
  if (!event || typeof event !== "object") return;
  switch (event.event) {
    case "DIAGNOSIS_RECORDED":
      assertDiagnosisDetails(event.details);
      return;
    case "DIAGNOSTIC_CASE_RECORDED":
      assertDiagnosticCaseDetails(event.details);
      return;
    case "INTERVENTION_RECORDED":
      assertInterventionDetails(event.details);
      return;
    case "HYPOTHESIS_DISPOSITION_RECORDED":
      assertHypothesisDispositionDetails(event.details);
      return;
    case "DECISION_CRITERION_RECORDED":
      assertDecisionCriterionDetails(event.details);
      return;
    case "CHECKPOINT_RECONCILED":
      assertReconcileClosureDetails(event.details);
      return;
    case CHECKPOINT_REVALIDATED_EVENT:
      assertCheckpointRevalidatedDetails(event.details);
      return;
    case CONTRACT_REVISED_EVENT:
      assertContractRevisedDetails(event.details);
      return;
    case GATE_SATISFIED_EVENT:
      assertGateSatisfiedDetails(event.details);
      return;
    case GATE_REVALIDATED_EVENT:
      assertGateRevalidatedDetails(event.details);
      return;
    case SEMANTIC_DECISION_RECORDED_EVENT:
    case SEMANTIC_DECISION_SUPERSEDED_EVENT:
      assertSemanticDecisionDetails(event.details, event.event);
      return;
    case "TASK_RECOVERY_RECORDED":
      assertRecoveryRecordedDetails(event.details);
      return;
    case "OPERATOR_RECOVERY_RECORDED":
      // The exact known legacy defect signature is tolerated here so the
      // ledger can be parsed and classified. It only becomes valid through an
      // official migration event (enforced by validateEventLedger).
      if (!event.details?.recoveryId && isLegacyRecoveryDetailsShape(event.details)) return;
      assertRecoveryRecordedDetails(event.details);
      return;
    case "TASK_ABANDONED":
      assertTaskAbandonedDetails(event.details);
      return;
    case "LEGACY_RECOVERY_MIGRATION_RECORDED":
      assertLegacyMigrationDetails(event.details);
      return;
    case CONTRACT_BOOTSTRAP_REPAIR_EVENT:
    case "CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_RECORDED":
      validateKnownContractBootstrapEvent(event);
      return;
    case "ROUTE_REBOUND":
      assertRouteReboundDetails(event.details);
      return;
    case ROUTE_CHECKPOINT_BOUND_EVENT:
      assertRouteCheckpointBoundDetails(event.details);
      return;
    case "TASK_RECOVERY_RESUMED":
      assertRecoveryResumedDetails(event.details);
      return;
    case "TRAJECTORY_EVALUATED":
      assertTrajectoryEvaluatedDetails(event);
      return;
    case "WORKSPACE_BOUND":
      assertStructuredArtifactEvent(event, ["workspaceFingerprint"], "WORKSPACE_BOUND");
      return;
    case "HANDOFF_CREATED":
      if (!event.details || typeof event.details !== "object" || Array.isArray(event.details)
        || typeof event.details.handoffId !== "string" || !/^handoff-[A-Za-z0-9_-]+$/.test(event.details.handoffId)
        || typeof event.details.artifact !== "string" || !event.details.artifact
        || typeof event.details.digest !== "string") {
        throw protocolError("E_EVENT_INVALID", "HANDOFF_CREATED requires a handoff ID, artifact path, and digest");
      }
      assertFingerprint(event.details.digest, "HANDOFF_CREATED details.digest");
      return;
    case "HANDOFF_ACCEPTED":
      assertHandoffAcceptedDetails(event);
      return;
    case "RESPONSIBILITY_SET":
      assertStructuredArtifactEvent(event, ["responsibilityFingerprint"], "RESPONSIBILITY_SET");
      if (typeof event.details.label !== "string" || !event.details.label) {
        throw protocolError("E_EVENT_INVALID", "RESPONSIBILITY_SET details.label must be a non-empty string");
      }
      return;
    case "VERIFICATION_SCOPE_CAPTURED":
      assertStructuredArtifactEvent(event, ["scopeFingerprint"], "VERIFICATION_SCOPE_CAPTURED");
      if (!["AUTO", "CHANGED", "CLAIMED", "FULL"].includes(event.details.resolvedMode)
        || !Number.isInteger(event.details.verificationCycle) || event.details.verificationCycle < 1) {
        throw protocolError("E_EVENT_INVALID", "VERIFICATION_SCOPE_CAPTURED requires a valid mode and verification cycle");
      }
      return;
    case "CODE_MANIFEST_CAPTURED":
      assertStructuredArtifactEvent(event, ["manifestFingerprint"], "CODE_MANIFEST_CAPTURED");
      assertFingerprint(event.details.contentDigest, "CODE_MANIFEST_CAPTURED details.contentDigest");
      if (!Number.isInteger(event.details.coveredPaths) || event.details.coveredPaths < 0) {
        throw protocolError("E_EVENT_INVALID", "CODE_MANIFEST_CAPTURED details.coveredPaths must be a non-negative integer");
      }
      return;
    case "ATTESTATION_STATEMENT_CREATED":
      assertStructuredArtifactEvent(event, ["statementFingerprint"], "ATTESTATION_STATEMENT_CREATED");
      assertFingerprint(event.details.manifestFingerprint, "ATTESTATION_STATEMENT_CREATED details.manifestFingerprint");
      return;
    default:
      if (isActionEventName(event.event)) {
        assertActionEventDetails(event);
        return;
      }
      if (isApprovalEventName(event.event)) {
        assertApprovalEventDetails(event);
        return;
      }
      return;
  }
}

function validateLegacyRecoveryMigrations(events, errors, { allowUnmigratedLegacyRecoveryEvents = false } = {}) {
  const migrationBySeq = new Map();
  for (const event of events) {
    if (event.event !== LEGACY_RECOVERY_MIGRATION_EVENT) continue;
    try {
      assertLegacyMigrationDetails(event.details);
    } catch (err) {
      errors.push({ code: err.code ?? "E_EVENT_INVALID", message: `event ${event.seq} (${event.event}): ${err.message}` });
      continue;
    }
    if (migrationBySeq.has(event.details.legacyEventSeq)) {
      errors.push({
        code: "E_EVENT_INVALID",
        message: `event ${event.seq} (${event.event}): duplicate migration for legacy recovery event seq ${event.details.legacyEventSeq}`,
      });
      continue;
    }
    migrationBySeq.set(event.details.legacyEventSeq, event);
  }
  for (const event of events) {
    if (!isLegacyRecoveryEventShape(event)) continue;
    const migration = migrationBySeq.get(event.seq);
    if (!migration) {
      if (!allowUnmigratedLegacyRecoveryEvents) {
        errors.push({
          code: "E_EVENT_INVALID",
          message: `legacy recovery event ${event.seq} is not officially migrated (run forgeloop task-repair-legacy-recovery)`,
        });
      }
      continue;
    }
    migrationBySeq.delete(event.seq);
    const expectedRecoveryId = legacyRecoveryMigrationId({ taskId: event.taskId, seq: event.seq, hash: event.hash });
    // Tail-binding: the migration event is appended at the ledger tail and may
    // sit anywhere after its historical source. It binds by reference only.
    if (migration.seq <= event.seq) {
      errors.push({
        code: "E_EVENT_INVALID",
        message: `migration event ${migration.seq} must follow legacy recovery event ${event.seq}`,
      });
    }
    if (migration.taskId !== event.taskId
      || migration.details.legacyTaskId !== event.taskId
      || migration.details.recoveryId !== expectedRecoveryId
      || migration.details.legacyEventHash !== event.hash
      || migration.details.legacyEventAt !== event.at
      || migration.details.legacyEventType !== event.event) {
      errors.push({
        code: "E_LEDGER_HASH_INVALID",
        message: `migration event ${migration.seq} does not bind legacy recovery event ${event.seq}`,
      });
    }
  }
  for (const [legacySeq, migration] of migrationBySeq) {
    errors.push({
      code: "E_EVENT_INVALID",
      message: `migration event ${migration.seq} references unknown legacy recovery event seq ${legacySeq}`,
    });
  }
}

function validateMilestoneChronology(events, index, event, milestoneCounts, lastMilestone, errors) {
  const milestoneIndex = LIFECYCLE_MILESTONES.indexOf(event.event);
  if (milestoneIndex < 0) return lastMilestone;
  const count = (milestoneCounts.get(event.event) ?? 0) + 1;
  milestoneCounts.set(event.event, count);
  const revisionPlanRepeat = isRevisionEpochPlanRepeat(events, index, event);
  if (count > 1 && !REPEATABLE_MILESTONES.has(event.event) && !revisionPlanRepeat) {
    errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: `lifecycle milestone must not repeat: ${event.event}` });
  }
  if (milestoneIndex > lastMilestone + 1) {
    errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: `${event.event} is missing prerequisite milestone: ${LIFECYCLE_MILESTONES[lastMilestone + 1]}` });
  } else if (milestoneIndex < lastMilestone && event.event !== "VERIFICATION_STARTED" && event.event !== "PREFLIGHT_READY") {
    errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: `${event.event} is out of lifecycle order` });
  } else if (milestoneIndex === lastMilestone && !REPEATABLE_MILESTONES.has(event.event) && !revisionPlanRepeat) {
    errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: `lifecycle milestone must not repeat: ${event.event}` });
  }
  if (milestoneIndex > lastMilestone) return milestoneIndex;
  return lastMilestone;
}

export function validateStateLedgerCoherence(state, events) {
  const errors = [
    ...validateCheckpointRevalidationCurrentBinding(state, events),
    ...validateContractRevisionCurrentBinding(state, events),
  ];
  if (!Number.isInteger(state.verificationCycle)) return errors;
  const taskEvents = events.filter((event) => event.taskId === state.taskId);
  const observed = new Set(taskEvents.map((event) => event.event));
  const supportsReviewEvents = taskEvents.some((event) => event.event === "REVIEW_STARTED"
    || (event.event === "VERIFICATION_STARTED" && Number.isInteger(event.details?.verificationCycle)));
  const phaseRequirements = {
    EXECUTING: ["EXECUTION_STARTED"],
    VERIFYING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    DIAGNOSING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    CORRECTING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    REVIEWING: ["EXECUTION_STARTED", "VERIFICATION_STARTED", ...(supportsReviewEvents ? ["REVIEW_STARTED"] : [])],
    COMPLETE: ["EXECUTION_STARTED", "VERIFICATION_STARTED", ...(supportsReviewEvents ? ["REVIEW_STARTED"] : []), "COMPLETION_VALIDATED"],
  };
  for (const required of phaseRequirements[state.phase] ?? []) {
    if (!observed.has(required)) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: `Work-state phase ${state.phase} requires ledger event ${required}`,
      });
    }
  }
  if (Number.isInteger(state.verificationCycle)) {
    const verificationEvents = taskEvents
      .map((event, index) => ({ event, index }))
      .filter(({ event }) => event.event === "VERIFICATION_STARTED");
    const cycles = verificationEvents.map(({ event }) => event.details?.verificationCycle ?? 1);
    if (cycles.at(-1) !== state.verificationCycle) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state verification cycle does not match the lifecycle ledger",
      });
    }
    const latestVerification = verificationEvents.at(-1);
    const latestReview = taskEvents
      .map((event, index) => ({ event, index }))
      .filter(({ event }) => event.event === "REVIEW_STARTED")
      .at(-1);
    const latestReviewCycle = latestReview?.event.details?.verificationCycle;
    if (state.phase === "VERIFYING"
      && latestReviewCycle === state.verificationCycle
      && latestReview.index > (latestVerification?.index ?? -1)) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state returned to VERIFYING without a new verification cycle in the lifecycle ledger",
      });
    }
    if (["REVIEWING", "COMPLETE"].includes(state.phase)
      && supportsReviewEvents
      && (latestReviewCycle !== state.verificationCycle
        || latestReview.index < (latestVerification?.index ?? -1))) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state review phase does not match the current lifecycle ledger cycle",
      });
    }
  }
  return errors;
}

export function authoritativeChecksForRequirements({ requirements = [], checks = [] } = {}) {
  return normalizeRequirements(requirements).map((requirement) => {
    const candidates = checks.filter((check) => matchesRequirement(check, requirement));
    return {
      requirement,
      check: latestAuthoritativeCheck(candidates),
    };
  });
}

function componentStatus(check, requirement, allChecks = [], options = {}) {
  if (requirement.operator !== "ALL" || !requirement.requirements?.length) return null;
  const components = check?.details?.components;
  const statuses = requirement.requirements.map((child) => {
    if (Array.isArray(components)) {
      const matchingComp = components.filter((item) => (
        item?.requirementId === child.id || item?.requirement === child.text
      )).at(-1);
      if (matchingComp) {
        const provenance = validateCommandProvenance(matchingComp);
        if (!provenance.valid) return { ...matchingComp, status: "failed", reasonCode: provenance.error.code };
        const auth = validateVerificationAuthority(matchingComp, options);
        if (!auth.valid) return { ...matchingComp, status: "failed", reasonCode: auth.error.code };
        return matchingComp;
      }
    }
    const childCandidates = allChecks.filter((candidate) => matchesRequirement(candidate, child));
    const childCheck = latestAuthoritativeCheck(childCandidates);
    if (childCheck) {
      const provenance = validateCommandProvenance(childCheck);
      if (!provenance.valid) return { ...childCheck, status: "failed", reasonCode: provenance.error.code };
      const auth = validateVerificationAuthority(childCheck, options);
      if (!auth.valid) return { ...childCheck, status: "failed", reasonCode: auth.error.code };
    }
    return childCheck;
  });
  if (statuses.some((item) => !item)) return "MISSING";
  if (statuses.some((item) => item.status === "failed")) return "INVALID";
  if (statuses.some((item) => item.status !== "passed" || item.evidenceKind !== "OBSERVED")) return "PARTIAL";
  return "COVERED";
}

export function evaluateRequiredEvidence({
  requirements = [],
  checks = [],
  target,
  taskId,
  authorities,
  options = {},
} = {}) {
  const authOptions = {
    ...(target ? { target } : {}),
    ...(taskId ? { taskId } : {}),
    ...(authorities ? { authorities } : {}),
    ...options,
  };
  const normalized = normalizeRequirements(requirements);
  const result = {
    ready: true,
    required: normalized,
    covered: [],
    missing: [],
    partial: [],
    invalid: [],
    lifecyclePending: [],
    reasonCodes: [],
  };
  for (const requirement of normalized) {
    if (requirement.mixedTerminal) {
      result.invalid.push({
        ...requirement,
        reasonCode: "E_CIRCULAR_COMPLETION_REQUIREMENT",
      });
      continue;
    }
    if (requirement.terminalOwned || requirement.lifecycleOwned) {
      result.lifecyclePending.push(requirement);
      continue;
    }
    const candidates = checks.filter((check) => matchesRequirement(check, requirement));
    const check = latestAuthoritativeCheck(candidates);
    const provenance = check ? validateCommandProvenance(check) : { valid: true };
    const auth = provenance.valid
      ? (check ? validateVerificationAuthority(check, authOptions) : { valid: true })
      : provenance;
    const compound = componentStatus(check, requirement, checks, authOptions);
    if (!auth.valid) {
      result.invalid.push({ ...requirement, reasonCode: auth.error.code });
    } else if (compound === "INVALID" || check?.status === "failed") {
      result.invalid.push(requirement);
    } else if (compound === "PARTIAL") {
      result.partial.push(requirement);
    } else if (compound === "MISSING") {
      result.missing.push(requirement);
    } else if (
      (check?.status === "passed" || compound === "COVERED")
      && (requirement.requiredEvidenceKind !== "OBSERVED" || check?.evidenceKind === "OBSERVED" || compound === "COVERED")
      && (compound === null || compound === "COVERED")
    ) {
      result.covered.push(requirement);
    } else if (check?.status === "passed" && check.evidenceKind !== "OBSERVED") {
      result.invalid.push({ ...requirement, reasonCode: "E_EVIDENCE_KIND_INVALID" });
    } else if (check) {
      result.partial.push(requirement);
    } else {
      result.missing.push(requirement);
    }
  }
  result.ready = result.missing.length === 0 && result.partial.length === 0 && result.invalid.length === 0;
  if (result.invalid.length) {
    const specificCodes = result.invalid
      .map((item) => item.reasonCode)
      .filter(Boolean);
    if (specificCodes.length > 0) {
      result.reasonCodes.push(...new Set(specificCodes));
    } else {
      result.reasonCodes.push("E_EVIDENCE_INVALID");
    }
  }
  if (result.missing.length) result.reasonCodes.push("E_EVIDENCE_REQUIRED");
  if (result.partial.length) result.reasonCodes.push("E_EVIDENCE_PARTIAL");
  const leaves = ordinaryLeafRequirements(normalized);
  const authoritativeLeaves = authoritativeChecksForRequirements({ requirements: leaves, checks });
  result.authoritativeFailures = authoritativeLeaves.filter(({ check }) => check?.status === "failed");
  result.authoritativeBlocked = authoritativeLeaves.filter(({ check }) => check?.status === "blocked");
  return result;
}

export function evaluateTerminalRequirements({ requirements = [], receipt = null } = {}) {
  const normalized = normalizeRequirements(requirements);
  const terminal = terminalRequirements(normalized);
  const result = {
    covered: [],
    pending: [],
    invalid: [],
    errors: [],
  };
  const pubStatus = receipt ? (receipt.publicationStatus ?? "not-published") : "not-published";
  const prodStatus = receipt ? (receipt.productionReadiness ?? "not-verified") : "not-verified";
  const receiptEvidence = Array.isArray(receipt?.evidence) ? receipt.evidence : [];

  for (const req of terminal) {
    if (req.type === "LIFECYCLE") {
      result.covered.push(req);
    } else if (req.type === "PUBLICATION") {
      const requiredLevel = req.requiredPublicationStatus ?? "published";
      const matchingEvidence = receiptEvidence
        .filter((item) => item.kind === "OBSERVED")
        .filter((item) => item.details?.requirementId === req.id)
        .filter((item) => item.details?.terminalType === "PUBLICATION");
      const latestEvidence = latestAuthoritativeCheck(matchingEvidence);
      const evidenceStatus = latestEvidence?.details?.terminalStatus;
      const evidenceSatisfied = isPublicationStatusSatisfied(evidenceStatus, requiredLevel);
      const globalSatisfied = isPublicationStatusSatisfied(pubStatus, requiredLevel);

      if (globalSatisfied && evidenceSatisfied) {
        result.covered.push(req);
      } else {
        result.pending.push(req);
        result.errors.push({
          code: "E_PUBLICATION_REQUIREMENT_PENDING",
          message: `The contract explicitly requires publication status '${requiredLevel}', but publication evidence/status is insufficient for requirement: ${req.text}`,
          requirementId: req.id,
        });
      }
    } else if (req.type === "PRODUCTION_READINESS") {
      const matchingEvidence = receiptEvidence
        .filter((item) => item.kind === "OBSERVED")
        .filter((item) => item.details?.requirementId === req.id)
        .filter((item) => item.details?.terminalType === "PRODUCTION_READINESS");
      const latestEvidence = latestAuthoritativeCheck(matchingEvidence);
      const evidenceStatus = latestEvidence?.details?.terminalStatus;
      const evidenceSatisfied = evidenceStatus === "ready" || evidenceStatus === "verified";
      const globalSatisfied = prodStatus === "ready" || prodStatus === "verified";

      if (globalSatisfied && evidenceSatisfied) {
        result.covered.push(req);
      } else {
        result.pending.push(req);
        result.errors.push({
          code: "E_PRODUCTION_REQUIREMENT_PENDING",
          message: `The contract explicitly requires production readiness, but production readiness evidence/status is insufficient for requirement: ${req.text}`,
          requirementId: req.id,
        });
      }
    }
  }
  return result;
}

export function latestAuthoritativeCheck(candidates) {
  if (!candidates || candidates.length === 0) return null;
  return [...candidates].sort((a, b) => {
    const cycleA = a.details?.verificationCycle ?? a.verificationCycle ?? 1;
    const cycleB = b.details?.verificationCycle ?? b.verificationCycle ?? 1;
    if (cycleA !== cycleB) return cycleA - cycleB;
    const timeA = typeof a.timestamp === "string" ? a.timestamp : "";
    const timeB = typeof b.timestamp === "string" ? b.timestamp : "";
    if (timeA !== timeB) return timeA.localeCompare(timeB);
    return 0;
  }).at(-1);
}

export function normalizeRequirements(requirements = []) {
  const byId = new Map();
  for (const raw of requirements) {
    const requirement = classifyRequirement(raw);
    if (!byId.has(requirement.id)) byId.set(requirement.id, requirement);
  }
  return [...byId.values()].sort((left, right) => left.id.localeCompare(right.id));
}

export function ordinaryLeafRequirements(requirements = []) {
  const result = [];
  function visit(requirement) {
    if (requirement.terminalOwned) return;
    if (requirement.operator === "ALL" && Array.isArray(requirement.requirements) && requirement.requirements.length > 0) {
      for (const child of requirement.requirements) {
        visit(child);
      }
      return;
    }
    result.push(requirement);
  }
  for (const req of normalizeRequirements(requirements)) {
    visit(req);
  }
  return result;
}

export function terminalRequirementsForContract(contractValue = {}, { additionalEvidence = [] } = {}) {
  const pool = [
    ...(contractValue.verification ?? []),
    ...(contractValue.successCriteria ?? []),
    ...additionalEvidence,
  ];
  return terminalRequirements(pool);
}

export function validateCommandProvenance(check) {
  if (check?.kind !== "command" || check.evidenceKind !== "OBSERVED") {
    return { valid: true, error: null };
  }
  if (check.provenance !== "FORGELOOP_EXECUTED" || typeof check.executionRef !== "string" || check.executionRef.trim() === "") {
    return {
      valid: false,
      error: {
        code: E_COMMAND_PROVENANCE_UNATTESTED,
        message: "Observed command evidence requires a ForgeLoop execution artifact",
      },
    };
  }
  return { valid: true, error: null };
}

export function assertEvidenceList(value, label = "evidence") {
  if (!Array.isArray(value)) throw new EvidenceError(`${label} must be an array`);
  value.forEach((item, index) => assertEvidence(item, `${label}[${index}]`));
  return value;
}

export function createEvidence(input, source, result, details, cycle) {
  const value = typeof input === "string"
    ? {
        kind: input,
        source,
        result,
        ...(cycle !== undefined ? { verificationCycle: cycle } : {}),
        details: {
          ...(details === undefined ? {} : details),
          ...(cycle !== undefined ? { verificationCycle: cycle } : {}),
        },
      }
    : structuredClone(input);
  if (value.details && typeof value.details === "object" && value.verificationCycle !== undefined) {
    value.details.verificationCycle = value.verificationCycle;
  }
  assertEvidence(value);
  return value;
}

export function evidenceMatches(evidence, terms) {
  const normalizedTerms = (Array.isArray(terms) ? terms : [terms])
    .filter((term) => typeof term === "string" && term.length > 0)
    .map((term) => term.toLowerCase());
  return (evidence ?? []).some((item) => {
    const detailsText = item.details
      ? `${item.details.requirementText ?? ""} ${String(item.details.terminalType ?? "").replace(/_/g, " ")}`
      : "";
    const haystack = `${item.source} ${item.result} ${detailsText}`.toLowerCase();
    return normalizedTerms.some((term) => haystack.includes(term));
  });
}

export async function assertExecutionPrerequisites(input = {}) {
  const prerequisites = await evaluateStartExecutionPrerequisites(input);
  const error = prerequisiteError(prerequisites);
  if (error) throw error;
  return prerequisites;
}

function freshnessErrors(state, freshness) {
  if (freshness.status !== "REVALIDATION_REQUIRED") return [];
  return [issue(
    "E_STATE_REVALIDATION_REQUIRED",
    `EXECUTING requires a fresh work-state checkpoint: ${freshness.reasons.join(", ")}`,
    [
      ARTIFACT_PATHS.state,
      ARTIFACT_PATHS.contract,
      ...(state.requiredArtifacts?.map((artifact) => artifact.path) ?? []),
    ],
  )];
}

export function hasExecutionStarted(phase) {
  return POST_EXECUTION_PHASES.has(phase);
}

function issue(code, message, artifacts = []) {
  return { code, message, artifacts };
}

async function load(loadArtifact, code, message, artifacts, errors) {
  try {
    return await loadArtifact();
  } catch (error) {
    errors.push(issue(code, `${message}: ${error.message}`, artifacts));
    return null;
  }
}

export function prerequisiteError(prerequisites) {
  const first = prerequisites.errors[0];
  if (!first) return null;
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  return error;
}

function prerequisiteLedgerErrors(ledger, taskId, preflight, route) {
  const errors = (ledger.errors ?? []).map((error) => issue(
    error.code ?? "E_PHASE_CHRONOLOGY_INVALID",
    error.message,
    [ARTIFACT_PATHS.events],
  ));
  const events = ledger.events ?? [];
  if (events.some((event) => event.taskId !== taskId)) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      "EXECUTING requires protocol prerequisite events to belong to the current task",
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.state, ARTIFACT_PATHS.contract],
    ));
    return errors;
  }
  const currentEvents = events.filter((event) => event.taskId === taskId);
  for (const requiredEvent of START_EXECUTION_EVENTS) {
    if (!currentEvents.some((event) => event.event === requiredEvent)) {
      errors.push(issue(
        "E_PHASE_CHRONOLOGY_INVALID",
        `EXECUTING requires a ${requiredEvent} protocol event`,
        [ARTIFACT_PATHS.events],
      ));
    }
  }
  // Bind to the latest PREFLIGHT_READY: an append-only lifecycle may contain an
  // older READY event superseded by a BLOCKED outcome and a fresh READY with
  // current details (see preflight-reactivation recovery).
  const preflightEvent = currentEvents.findLast((event) => event.event === "PREFLIGHT_READY");
  if (preflightEvent && (!sameStringSet(preflightEvent.details?.requiredGates, preflight.requiredGates)
    || !sameStringSet(preflightEvent.details?.satisfiedGates, preflight.satisfiedGates))) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      "PREFLIGHT_READY event gate sets do not match the current READY preflight",
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight],
    ));
  }
  if (preflightEvent && preflightEvent.fingerprint !== preflight.fingerprints.contract) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      PREFLIGHT_CONTRACT_IDENTITY_ERROR_MESSAGE,
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight, ARTIFACT_PATHS.contract],
    ));
  }
  if (preflightEvent && (preflightEvent.details?.routingFingerprint !== preflight.fingerprints.routing
    || preflightEvent.details?.routingFingerprint !== route.fingerprint)) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      PREFLIGHT_ROUTE_IDENTITY_ERROR_MESSAGE,
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight, ARTIFACT_PATHS.route],
    ));
  }
  const latestContractRevisionSeq = currentEvents.findLast((event) => event.event === "CONTRACT_REVISED")?.seq ?? 0;
  const currentEpochSatisfiedGates = new Set(preflight.requiredGates.filter((gate) => (
    hasCurrentGateEvidence(currentEvents, taskId, gate, latestContractRevisionSeq)
  )));
  for (const gate of preflight.requiredGates) {
    if (!currentEpochSatisfiedGates.has(gate)) {
      errors.push(issue(
        "E_PHASE_CHRONOLOGY_INVALID",
        `execution started before current-contract gate satisfaction: ${gate}`,
        [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight],
      ));
    }
  }
  return errors;
}

function sameStringSet(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right)) return false;
  return left.length === new Set(left).size
    && right.length === new Set(right).size
    && left.length === right.length
    && left.every((value) => right.includes(value));
}

function contextError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function projectExecutionProfileContext({
  taskId,
  contract,
  route,
  state,
  nextAction,
  runtimeContext,
} = {}) {
  if (typeof taskId !== "string" || !taskId) throw contextError("E_TASK_REQUIRED", "taskId is required");
  if (!contract || typeof contract !== "object" || Array.isArray(contract)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "contract is required for profile-aware context");
  }
  if (!route || typeof route !== "object" || Array.isArray(route)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "route is required for profile-aware context");
  }
  if (!state || typeof state !== "object" || Array.isArray(state)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "work state is required for profile-aware context");
  }
  const profile = route.executionProfile ? assertExecutionProfile(route.executionProfile) : legacyExecutionProfile();
  const resolvedProfile = profile.resolved;
  const policy = getExecutionProfileContextPolicy(resolvedProfile);
  const available = [...OPTIONAL_CONTEXT_BY_PROFILE[resolvedProfile]];
  const advisoryProviders = runtimeContext?.advisoryContextProviders;
  const hasAdvisory = Boolean(
    advisoryProviders && (
      advisoryProviders instanceof Map
        ? advisoryProviders.size > 0
        : Object.keys(advisoryProviders).length > 0
    ),
  );
  if (hasAdvisory && !available.includes("advisory-context")) {
    available.push("advisory-context");
  }
  return {
    schemaVersion: 1,
    protocolVersion: 1,
    taskId,
    executionProfile: profile,
    phase: state.phase,
    nextAction: nextAction?.nextAction ?? null,
    objective: contract.objective ?? null,
    deliverables: [...(contract.deliverables ?? [])],
    constraints: [...(contract.constraints ?? [])],
    selectedGuideIds: [...(state.selectedGuides ?? [])],
    verificationRequirements: verificationRequirements(contract),
    contextPolicy: policy,
    optionalContext: {
      available,
      loaded: [],
    },
    invariants: { ...PROFILE_INVARIANTS },
  };
}

export function projectExecutionProfile(route) {
  if (!route || typeof route !== "object") return null;
  return route.executionProfile?.resolved ?? LEGACY_EXECUTION_PROFILE;
}

function executionError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function validateExecutionBinding({ execution, taskId, checkId, requirement, verificationCycle = 1 } = {}) {
  if (!execution || execution.kind !== "COMMAND_EXECUTION"
    || execution.taskId !== taskId
    || execution.checkId !== checkId
    || execution.requirement !== requirement
    || execution.verificationCycle !== undefined && execution.verificationCycle !== verificationCycle) {
    throw executionError("E_EXECUTION_REF_INVALID", "Execution artifact does not match the current check binding", [ARTIFACT_PATHS.executionDirectory]);
  }
  return execution;
}

export function projectFailureSignatures({ state = null, events = [] } = {}) {
  const byCycle = new Map();
  const record = (cycle, details) => {
    if (details.status !== "failed" && details.status !== "blocked") return;
    const requirement = details.requirement ?? details.id ?? details.checkId;
    if (!requirement) return;
    const signature = computeFailureSignature({
      requirement,
      status: details.status,
      exitCode: Number.isInteger(details.exitCode) ? details.exitCode : null,
      failureToken: failureTokenOf(details),
    });
    if (!byCycle.has(cycle)) byCycle.set(cycle, new Map());
    const cycleMap = byCycle.get(cycle);
    if (!cycleMap.has(signature)) cycleMap.set(signature, { signature, requirements: new Set(), cycles: new Set() });
    cycleMap.get(signature).requirements.add(requirement);
    cycleMap.get(signature).cycles.add(cycle);
  };

  for (const event of events) {
    if (event.event !== "VERIFICATION_RECORDED") continue;
    record(event.details?.verificationCycle ?? 1, event.details ?? {});
  }
  for (const check of state?.checks ?? []) {
    if (check.status !== "failed" && check.status !== "blocked") continue;
    record(check.details?.verificationCycle ?? state?.verificationCycle ?? 1, check);
  }

  const signaturesByIdentity = new Map();
  for (const [, cycleMap] of [...byCycle.entries()].sort(([a], [b]) => a - b)) {
    for (const [signature, entry] of cycleMap) {
      if (!signaturesByIdentity.has(signature)) signaturesByIdentity.set(signature, { signature, cycles: [], requirements: new Set() });
      const aggregated = signaturesByIdentity.get(signature);
      aggregated.cycles.push(...entry.cycles);
      for (const requirement of entry.requirements) aggregated.requirements.add(requirement);
    }
  }

  return [...signaturesByIdentity.values()]
    .map((entry) => ({ ...entry, cycles: [...new Set(entry.cycles)].sort((a, b) => a - b), requirements: [...entry.requirements].sort() }))
    .sort((a, b) => a.signature.localeCompare(b.signature));
}

export function projectFailureSurfaces({ state = null, events = [] } = {}) {
  const failedRequirementsByCycle = new Map();
  // Track every canonically verified cycle so a successful verification
  // appears explicitly as surface: [] instead of silently disappearing.
  const knownCycles = new Set();
  const record = (cycle, requirement) => {
    if (!Number.isInteger(cycle)) cycle = Number(cycle) || 1;
    knownCycles.add(cycle);
    if (!failedRequirementsByCycle.has(cycle)) failedRequirementsByCycle.set(cycle, new Set());
    if (!requirement) return;
    failedRequirementsByCycle.get(cycle).add(requirement);
  };
  const knowCycle = (cycle) => {
    if (Number.isInteger(cycle)) knownCycles.add(cycle);
  };

  for (const event of events) {
    if (event.event === "VERIFICATION_STARTED") {
      knowCycle(event.details?.verificationCycle);
    }
    if (event.event !== "VERIFICATION_RECORDED") continue;
    const d = event.details ?? {};
    if (d.status === "failed" || d.status === "blocked") {
      record(d.verificationCycle ?? 1, d.requirement ?? d.id ?? d.checkId);
    } else {
      knowCycle(d.verificationCycle);
    }
  }

  for (const check of state?.checks ?? []) {
    knowCycle(check.details?.verificationCycle ?? state?.verificationCycle ?? 1);
    if (check.status !== "failed" && check.status !== "blocked") continue;
    record(check.details?.verificationCycle ?? state?.verificationCycle ?? 1, check.requirement ?? check.id ?? check.checkId);
  }
  for (const cycle of knownCycles) {
    if (!failedRequirementsByCycle.has(cycle)) failedRequirementsByCycle.set(cycle, new Set());
  }

  return [...failedRequirementsByCycle.entries()]
    .sort(([a], [b]) => a - b)
    .map(([verificationCycle, requirements]) => ({
      verificationCycle,
      surface: [...requirements].sort(),
      size: requirements.size,
    }));
}

function gateName(value) {
  if (typeof value !== "string" || !/^[a-z0-9][a-z0-9-]*$/.test(value)) {
    const error = new Error(`Invalid gate name: ${value}`);
    error.code = "E_GATE_INVALID";
    throw error;
  }
  return value;
}

export function gatePath(gate, options = {}) {
  const name = gateName(gate);
  if (options?.taskId) {
    return taskGatePath(options.taskId, name);
  }
  return `${ARTIFACT_PATHS.gates ?? ".forgeloop/gates"}/${name}.json`;
}

export async function validateGateArtifacts(target, gateValue, packageRoot) {
  const schema = await readSchema("gate", packageRoot);
  assertSchema(gateValue, schema, "gate");
  const stale = [];
  for (const artifact of gateValue.artifacts ?? []) {
    await assertSafePath(target, artifact.path);
    const artifactPath = ensureWithin(target, artifact.path);
    if (!(await fileExists(artifactPath))) {
      stale.push({ path: artifact.path, status: "missing" });
      continue;
    }
    const digest = sha256(await readBytes(artifactPath));
    if (digest !== artifact.sha256) stale.push({ path: artifact.path, status: "changed" });
  }
  return stale;
}

export function hasCurrentGateEvidence(events, taskId, gate, latestContractRevisionSeq = 0) {
  return events.some((event) => [GATE_SATISFIED_EVENT, GATE_REVALIDATED_EVENT].includes(event.event)
    && event.taskId === taskId
    && event.details?.gate === gate
    && event.seq > latestContractRevisionSeq);
}

export function validateGateSatisfactionBindings(events = []) {
  const errors = [];
  for (const [index, event] of events.entries()) {
    if (![GATE_SATISFIED_EVENT, GATE_REVALIDATED_EVENT].includes(event.event)) continue;
    const revalidated = event.event === GATE_REVALIDATED_EVENT;
    try {
      if (revalidated) assertGateRevalidatedDetails(event.details);
      else assertGateSatisfiedDetails(event.details);
    } catch (error) {
      errors.push({ code: error.code ?? "E_EVENT_INVALID", message: `event ${event.seq} (${event.event}): ${error.message}` });
      continue;
    }
    const revisedBeforeGate = events.slice(0, index).findLast((candidate) => candidate.taskId === event.taskId
      && candidate.event === CONTRACT_REVISED_EVENT);
    const boundary = revalidated
      ? resolveGateRevalidationBoundary(events, event)
      : resolveGateRecordBoundary(events, event);
    if ((revalidated || revisedBeforeGate) && !boundary) {
      errors.push({
        code: revalidated ? "E_GATE_REVALIDATION_INVALID" : "E_EVENT_INVALID",
        message: revalidated
          ? `event ${event.seq} must be immediately followed by its gate-revalidate transaction commit`
          : `event ${event.seq} must be immediately followed by its gate-record transaction commit after contract revision`,
      });
    }
  }
  return errors;
}

export async function completionEvidenceForGuides(guides, packageRoot) {
  const metadata = await readGuideMetadata(packageRoot);
  return [...new Set(guides.flatMap((guide) => metadata[guide]?.completionEvidence ?? []))].sort();
}

function parseFrontmatter(text, relativePath) {
  const match = text.match(/^---\s*\n([\s\S]*?)\n---\s*\n/);
  if (!match) throw new Error(`${relativePath} is missing YAML frontmatter`);
  const frontmatter = match[1];
  const guideId = frontmatter.match(/^guide-id:\s*([^\s]+)\s*$/m)?.[1] ?? null;
  const lastReviewed = frontmatter.match(/^last-reviewed:\s*"?([^"\r\n]+)"?\s*$/m)?.[1] ?? null;
  const version = frontmatter.match(/^version:\s*"?([^"\r\n]+)"?\s*$/m)?.[1] ?? null;
  return {
    guideId,
    lastReviewed,
    version,
    requiresGates: parseList(frontmatter, "requires-gates"),
    completionEvidence: parseList(frontmatter, "completion-evidence"),
  };
}

function parseList(frontmatter, key) {
  const lines = frontmatter.split(/\r?\n/);
  const start = lines.findIndex((line) => line.trim() === `${key}:`);
  if (start < 0) return [];
  const values = [];
  for (const line of lines.slice(start + 1)) {
    if (!/^\s+-\s+/.test(line)) break;
    values.push(line.replace(/^\s+-\s+/, "").trim());
  }
  return values.filter(Boolean);
}

export async function readGuideMetadata(packageRoot) {
  const metadata = {};
  for (const [id, relativePath] of Object.entries(GUIDE_FILES)) {
    const text = await readFile(path.join(packageRoot, relativePath), "utf8");
    const parsed = parseFrontmatter(text, relativePath);
    metadata[id] = {
      guideId: parsed.guideId ?? id,
      lastReviewed: parsed.lastReviewed,
      version: parsed.version,
      requiresGates: [...parsed.requiresGates],
      completionEvidence: [...parsed.completionEvidence],
      path: relativePath,
    };
  }
  return metadata;
}

export async function requiredGatesForGuides(guides, packageRoot) {
  const metadata = await readGuideMetadata(packageRoot);
  return [...new Set(guides.flatMap((guide) => metadata[guide]?.requiresGates ?? []))].sort();
}

export async function readHandoffAcceptanceLedger(target, packageRoot = getPackageRoot(), { taskId } = {}) {
  try {
    return await validateEventLedger(target, packageRoot, { taskId });
  } catch (error) {
    return {
      valid: false,
      events: [],
      errors: [{
        code: error.code ?? "E_EVENT_INVALID",
        message: error.message,
      }],
    };
  }
}

export function compareRepositoryFingerprint(expected, current) {
  const expectedUnavailable = !expected || (expected.branch === null && expected.head === null);
  const currentUnavailable = !current || (current.branch === null && current.head === null);
  if (expectedUnavailable && currentUnavailable) return "NOT_VERIFIED";
  if (expectedUnavailable !== currentUnavailable) return "MISMATCH";
  return expected.branch === current.branch && expected.head === current.head
    ? "MATCH"
    : "MISMATCH";
}

function handoffError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "HandoffError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function handoffWithoutDigest(value) {
  const { artifactDigest: _artifactDigest, ...body } = value;
  return body;
}

export async function listCanonicalHandoffs(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  const directory = taskHandoffDirectory(taskId);
  if (!(await fileExists(ensureWithin(target, directory)))) return [];
  const entries = await readdir(ensureWithin(target, directory), { withFileTypes: true });
  const handoffs = [];
  for (const entry of entries) {
    if (!entry.isFile() || !/^handoff-[A-Za-z0-9_-]+\.json$/u.test(entry.name)) continue;
    const handoffId = entry.name.slice(0, -5);
    const artifact = await readCanonicalHandoff(target, { taskId, handoffId, packageRoot });
    handoffs.push(artifact.value);
  }
  return handoffs.sort((left, right) => left.createdAt.localeCompare(right.createdAt) || left.handoffId.localeCompare(right.handoffId));
}

function optionalText(value, label, maxLength = 2000) {
  if (value === undefined || value === null) return null;
  try {
    return normalizePortableText(value, { label, maxLength, optional: true });
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", `${label} must be a non-empty string when provided`);
  }
}

function pathList(value) {
  return [...new Set((value ?? []).map((item) => String(item).replaceAll("\\", "/")))].sort();
}

export async function resolveLatestHandoff(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  const handoffs = await listCanonicalHandoffs(target, { taskId, packageRoot });
  const latest = handoffs.at(-1);
  return latest
    ? { handoffId: latest.handoffId, createdAt: latest.createdAt, digest: latest.artifactDigest }
    : null;
}

export async function validateCanonicalHandoff(target, handoff, {
  taskId,
  packageRoot = getPackageRoot(),
} = {}) {
  const { readSchema, assertSchema } = await import("./schema-validation.js");
  try {
    assertSchema(handoff, await readSchema("handoff-envelope", packageRoot), "handoff envelope");
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", error.message);
  }
  if (taskId && handoff.taskId !== taskId) {
    throw handoffError("E_HANDOFF_INVALID", "Handoff taskId does not match the selected task");
  }
  return validateHandoffDigest(handoff);
}

export function validateHandoffDigest(handoff) {
  try {
    assertPortableContextSafe(handoff);
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", error.message);
  }
  if (typeof handoff?.artifactDigest !== "string"
    || handoff.artifactDigest !== canonicalFingerprint(handoffWithoutDigest(handoff))) {
    throw handoffError("E_HANDOFF_TAMPERED", "Handoff artifact digest does not match its canonical content");
  }
  return handoff;
}

export async function buildTaskHistory({
  target,
  packageRoot,
  taskId = null,
  filters = {},
} = {}) {
  const trace = await buildTaskTrace({ target, packageRoot, taskId });
  let events = [...trace.events];

  if (filters.type) {
    const types = String(filters.type).split(",").map((value) => value.trim()).filter(Boolean);
    if (types.length > 0) {
      events = events.filter((event) => types.includes(event.type) || types.includes(event.category));
    }
  }
  if (filters.phase) {
    const phases = String(filters.phase).split(",").map((value) => value.trim()).filter(Boolean);
    if (phases.length > 0) events = events.filter((event) => phases.includes(event.phase));
  }
  if (filters.failures) {
    events = events.filter((event) => event.category === "verification"
      && ["failed", "blocked"].includes(String(event.data?.status ?? "")));
  }
  if (filters.checks) {
    events = events.filter((event) => event.category === "verification");
  }
  if (filters.since) {
    const since = Date.parse(filters.since);
    if (!Number.isNaN(since)) events = events.filter((event) => event.timestamp && Date.parse(event.timestamp) >= since);
  }
  if (filters.until) {
    const until = Date.parse(filters.until);
    if (!Number.isNaN(until)) events = events.filter((event) => event.timestamp && Date.parse(event.timestamp) <= until);
  }

  let omittedEvents = 0;
  if (Number.isInteger(filters.limit) && filters.limit >= 0 && events.length > filters.limit) {
    omittedEvents = events.length - filters.limit;
    events = events.slice(-filters.limit);
  }

  const checkAttempts = trace.checks.reduce(
    (total, check) => total + check.attemptCount,
    0,
  );
  const failedAttempts = trace.checks.reduce(
    (total, check) => total + check.failedAttempts,
    0,
  );

  return {
    schemaVersion: 1,
    command: "history",
    task: trace.task,
    snapshot: trace.snapshot,
    summary: {
      eventCount: events.length,
      totalEventCount: trace.events.length,
      checkAttemptCount: checkAttempts,
      failedAttemptCount: failedAttempts,
      diagnosticCaseCount: trace.diagnostics.cases.length,
      interventionCount: trace.diagnostics.interventions.length,
    },
    historyQuality: trace.historyQuality,
    integrity: trace.integrity,
    events,
    ...(omittedEvents > 0 ? { truncated: true, truncation: { reason: "OUTPUT_LIMIT", omittedEvents } } : {}),
  };
}

export function getHypothesisState(projection, id) {
  return projection?.hypotheses.find((hypothesis) => hypothesis.id === id) ?? null;
}

export function projectHypothesisStates(events, { taskId = null } = {}) {
  const ordered = [...events].sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
  const byId = new Map();
  const invalidTransitions = [];

  const ensure = (id, seq, cycle) => {
    if (!byId.has(id)) {
      const state = blankState(id);
      state.sourceEventSeq = seq ?? null;
      state.sourceCycle = cycle ?? null;
      byId.set(id, state);
    }
    return byId.get(id);
  };

  for (const event of ordered) {
    if (taskId && event.taskId && event.taskId !== taskId) continue;
    const details = event.details ?? {};
    if (event.event === "DIAGNOSTIC_CASE_RECORDED") {
      for (const hypothesis of details.hypotheses ?? []) {
        if (!hypothesis?.id) continue;
        ensure(hypothesis.id, event.seq, details.verificationCycle);
      }
    } else if (event.event === "DIAGNOSIS_RECORDED") {
      ensure(HYPOTHESIS_LEGACY_ID, event.seq, details.verificationCycle);
    } else if (event.event === "HYPOTHESIS_DISPOSITION_RECORDED") {
      const ref = details.hypothesisRef;
      if (!ref || !details.status) continue;
      const state = ensure(ref, null, null);
      if (!canTransition(state.currentStatus, details.status)) {
        invalidTransitions.push({
          sequence: event.seq,
          hypothesisRef: ref,
          from: state.currentStatus,
          to: details.status,
        });
        continue;
      }
      state.currentStatus = details.status;
      state.dispositionHistory.push({
        sequence: event.seq,
        status: details.status,
        evidenceRefs: [...(details.evidenceRefs ?? [])],
        reason: details.reason ?? null,
      });
    }
  }

  const hypotheses = [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
  return {
    hypotheses,
    openHypotheses: hypotheses.filter((hypothesis) => hypothesis.currentStatus === "OPEN").map((hypothesis) => hypothesis.id),
    invalidTransitions,
  };
}

export function buildInformationGainProjection(events, taskId) {
  const taskEvents = (events ?? [])
    .filter((event) => !taskId || !event.taskId || event.taskId === taskId)
    .sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));

  const diagnosticEvents = diagnosticEventsForTask(taskEvents, taskId)
    .sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
  if (diagnosticEvents.length === 0) return [];

  const failure = failureStateByCycle(taskEvents);

  // Build final per-cycle entries first; effectiveGain is computed once at the
  // end from fully final dimensions (no post-mutation anywhere).
  const built = [];
  let previousDiagnostic = null;
  for (const diagnostic of diagnosticEvents) {
    const intervalStart = previousDiagnostic ? previousDiagnostic.seq : -Infinity;
    const interval = intervalEvents(taskEvents, intervalStart, diagnostic.seq);

    const hypothesisDispositionChanged =
      interval.some((event) => event.event === "HYPOTHESIS_DISPOSITION_RECORDED");

    // Intervention deltas recognize only genuinely NEW semantic interventions:
    // recorded after the previous diagnosis, attributed to the current
    // correction cycle, and never attempted before. Repeating an already-known
    // intervention — or merely having executed the previous cycle's corrective
    // action — is not new information.
    const knownUpToPrev = new Set(
      taskEvents
        .filter((event) => event.event === "INTERVENTION_RECORDED"
          && (previousDiagnostic ? (event.seq ?? 0) <= previousDiagnostic.seq : false))
        .map((event) => event.details?.interventionSemanticFingerprint
          ?? `${event.details?.intervention?.statement ?? ""}`.trim().toLowerCase())
        .filter(Boolean),
    );
    const novelInInterval = interval
      .filter((event) => event.event === "INTERVENTION_RECORDED")
      .map((event) => event.details?.interventionSemanticFingerprint
        ?? `${event.details?.intervention?.statement ?? ""}`.trim().toLowerCase())
      .filter((fingerprint) => fingerprint && !knownUpToPrev.has(fingerprint));
    // A genuinely new intervention counts as information only when the
    // diagnosis itself moves: an identical re-proposal of the previous
    // diagnosis after executing its already-known corrective action carries
    // no new semantic state.
    const sameSemanticsAsPrevious = Boolean(previousDiagnostic)
      && !snapshotHasContentDelta(previousDiagnostic.details ?? {}, diagnostic.details ?? {});
    const interventionChanged = Boolean(previousDiagnostic)
      && novelInInterval.length > 0
      && !sameSemanticsAsPrevious;

    const cycle = diagnostic.details?.verificationCycle ?? 1;
    const previousCycle = previousDiagnostic?.details?.verificationCycle ?? null;
    const surface = [...(failure.surfaces.get(cycle) ?? new Set())].sort();
    const signatures = [...(failure.signatures.get(cycle) ?? new Set())].sort();
    const previousSurface = previousCycle !== null && previousCycle !== undefined
      ? [...(failure.surfaces.get(previousCycle) ?? new Set())].sort()
      : null;
    const previousSignatures = previousCycle !== null && previousCycle !== undefined
      ? [...(failure.signatures.get(previousCycle) ?? new Set())].sort()
      : null;
    const hasPreviousFailureState = previousSurface !== null;
    const failureSurfaceChanged = hasPreviousFailureState
      ? !sameSortedSet(surface, previousSurface)
      : false;
    const failureSignatureChanged = hasPreviousFailureState
      ? !sameSortedSet(signatures, previousSignatures)
      : false;

    // Strategy compares the PROPOSED diagnostic approach: the case's own
    // semantic content on both sides (identical bases, so the delta is real).
    const strategyFingerprint = strategyFingerprintFor(diagnostic, []);
    const previousStrategyFingerprint = previousDiagnostic
      ? strategyFingerprintFor(previousDiagnostic, [])
      : null;
    const strategyChanged = Boolean(previousStrategyFingerprint
      && strategyFingerprint !== previousStrategyFingerprint);

    const snapshot = snapshotFor(diagnostic);

    built.push({
      verificationCycle: cycle,
      sequence: diagnostic.seq ?? null,
      diagnosticSequence: diagnostic.seq ?? null,
      sourceModel: diagnostic.event === "DIAGNOSTIC_CASE_RECORDED"
        ? "STRUCTURED_DIAGNOSTIC_CASE_V1"
        : "LEGACY_DIAGNOSIS_V1",
      snapshot,
      dimensionsInput: {
        hypothesisDispositionChanged,
        failureSignatureChanged,
        failureSurfaceChanged,
        interventionChanged,
        strategyChanged,
        hypothesisEliminated: false,
      },
      evidence: {
        semanticRefs: [...(snapshot.evidenceRefs ?? [])].sort(),
        surface, signatures, strategyFingerprint,
      },
    });

    previousDiagnostic = diagnostic;
  }

  // Hypothesis elimination: an id disappearing only counts as elimination when
  // no surviving hypothesis carries the same normalized statement — ID-only
  // churn is artificial novelty and must never create gain.
  for (let i = 1; i < built.length; i++) {
    if (built[i].sourceModel !== "STRUCTURED_DIAGNOSTIC_CASE_V1"
      || built[i - 1].sourceModel !== "STRUCTURED_DIAGNOSTIC_CASE_V1") continue;
    const previousHypotheses = diagnosticEvents[i - 1]?.details?.hypotheses ?? [];
    const currentHypotheses = diagnosticEvents[i]?.details?.hypotheses ?? [];
    const currentStatements = new Set(currentHypotheses.map(
      (hypothesis) => `${hypothesis.statement}`.trim().toLowerCase()));
    built[i].dimensionsInput.hypothesisEliminated = previousHypotheses.some((hypothesis) => {
      const survivedById = currentHypotheses.some((candidate) => candidate.id === hypothesis.id);
      return !survivedById
        && !currentStatements.has(`${hypothesis.statement}`.trim().toLowerCase());
    });
  }

  // Final classification + single-point effectiveGain computation.
  const entries = computeInformationGain(built.map((entry) => ({
    verificationCycle: entry.verificationCycle,
    sequence: entry.sequence,
    snapshot: entry.snapshot,
    context: entry.dimensionsInput,
  })));

  return built.map((entry, index) => {
    const { dimensions, classification, effectiveGain } = entries[index];
    return Object.freeze({
      verificationCycle: entry.verificationCycle,
      sequence: entry.sequence,
      diagnosticSequence: entry.diagnosticSequence,
      sourceModel: entry.sourceModel,
      evidence: Object.freeze({
        semanticRefs: Object.freeze(entry.evidence.semanticRefs),
        failureSurface: Object.freeze(entry.evidence.surface),
        failureSignatures: Object.freeze(entry.evidence.signatures),
        strategyFingerprint: entry.evidence.strategyFingerprint,
      }),
      dimensions: Object.freeze({ ...dimensions }),
      classification,
      effectiveGain,
    });
  });
}

export function evaluateStructuredDiagnosticStall(gainProjection, { verificationCycle = null } = {}) {
  const candidates = verificationCycle === null || verificationCycle === undefined
    ? (gainProjection ?? [])
    : (gainProjection ?? []).filter((entry) => entry.verificationCycle === verificationCycle);

  const latest = candidates.at(-1) ?? null;
  if (!latest) {
    return { stalled: false, latestGain: null, reason: null };
  }
  if (latest.classification === "FIRST_DIAGNOSIS") {
    return { stalled: false, latestGain: latest, reason: null };
  }
  const stalled = latest.effectiveGain === false;
  return {
    stalled,
    latestGain: latest,
    reason: stalled ? "NO_DIAGNOSTIC_INFORMATION_GAIN" : null,
  };
}

function profileMetadata(bytes) {
  const text = bytes.toString("utf8");
  return {
    mode: text.match(/^profile-mode:\s*([^\s]+)\s*$/m)?.[1] ?? null,
    status: text.match(/^profile-status:\s*([^\s]+)\s*$/m)?.[1] ?? null,
  };
}

function reasonCodesFor({ state, trace, progress }) {
  const codes = [];
  codes.push(trace.integrity.valid ? "LEDGER_VALID" : "LEDGER_INCONSISTENT");
  if (state?.status === "VALID" || state?.status === "FRESH") codes.push("REPOSITORY_FRESH");
  if (["STALE", "REVALIDATION_REQUIRED"].includes(state?.status)) codes.push("REPOSITORY_STALE");
  if (trace.task.phase === "COMPLETE") codes.push("COMPLETION_VALID");
  else codes.push("COMPLETION_INCOMPLETE");
  if (progress.status === "ADVANCING") codes.push("DIAGNOSTIC_PROGRESS_ADVANCING");
  if (progress.status === "STALLED") codes.push("DIAGNOSTIC_PROGRESS_STALLED");
  return codes;
}

function structuralQualityIssues(quality, taskId) {
  if (!quality || quality.mode !== "gate") return [];
  const qualityPath = quality.current?.artifactRef ?? taskStructuralQualityDirectory(taskId);
  if (quality.baseline?.status !== "OBSERVED") {
    return [{
      code: "E_STRUCTURAL_QUALITY_BASELINE_MISSING",
      message: "Structural-quality gate evidence has no valid immutable baseline.",
      path: taskStructuralQualityDirectory(taskId),
    }];
  }
  if (!quality.current?.artifactRef) {
    return [{
      code: "E_STRUCTURAL_QUALITY_EVIDENCE_STALE",
      message: "Structural-quality gate has no evaluation for the current verification cycle.",
      path: qualityPath,
    }];
  }
  if (quality.current.status === "FAIL") {
    return [{
      code: "E_STRUCTURAL_QUALITY_REGRESSION",
      message: "Structural-quality verification detected a regression.",
      path: qualityPath,
    }];
  }
  if (quality.current.status === "BLOCKED") {
    return [{
      code: "E_STRUCTURAL_QUALITY_EVALUATION_INCOMPARABLE",
      message: "Structural-quality verification is blocked or incomparable.",
      path: qualityPath,
    }];
  }
  return [];
}

export function getInstallationAuthorityRef(check) {
  return (
    check?.details?.installationAuthorityRef
    ?? check?.details?.authorityRef
    ?? check?.installationAuthorityRef
    ?? check?.authorityRef
    ?? null
  );
}

function normalizeToolName(toolName) {
  if (typeof toolName !== "string") return "";
  if (toolName.startsWith("@")) {
    const parts = toolName.slice(1).split("@");
    return `@${parts[0]}`;
  }
  return toolName.split("@")[0];
}

export function validateAuthorityGrant({ authority, taskId, type = "SOFTWARE_INSTALLATION", tool } = {}) {
  if (!authority || typeof authority !== "object") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: "Authority grant artifact is missing or invalid",
      },
    };
  }

  if (authority.schemaVersion !== 1 || authority.protocolVersion !== 1) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant schema version (${authority.schemaVersion}) or protocol version (${authority.protocolVersion}) is invalid`,
      },
    };
  }

  if (authority.type !== type) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant type '${authority.type}' does not match expected '${type}'`,
      },
    };
  }

  if (authority.status !== "AUTHORIZED") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant is not active (status: '${authority.status}')`,
      },
    };
  }

  if (authority.source === "agent-self") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: "Self-asserted authority grants with source 'agent-self' are not permitted",
      },
    };
  }

  if (!["operator", "host", "project-policy"].includes(authority.source)) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant source '${authority.source}' is not recognized`,
      },
    };
  }

  if (taskId && authority.taskId && authority.taskId !== taskId) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant taskId '${authority.taskId}' does not match current task '${taskId}'`,
      },
    };
  }

  if (tool && authority.scope?.tool && authority.scope.tool !== "*") {
    const requestedNorm = normalizeToolName(tool);
    const scopeNorm = normalizeToolName(authority.scope.tool);
    const exactMatch = authority.scope.tool === tool
      || tool.startsWith(`${authority.scope.tool}@`)
      || authority.scope.tool.startsWith(`${tool}@`)
      || requestedNorm === scopeNorm;

    if (!exactMatch) {
      return {
        valid: false,
        error: {
          code: E_AUTHORITY_SCOPE_MISMATCH,
          message: `Authority grant scope tool '${authority.scope.tool}' does not match requested verification tool '${tool}'`,
        },
      };
    }
  }

  return { valid: true, error: null };
}

export function validateVerificationAuthority(check, options = {}) {
  const canonicalResolution = check?.execution?.resolution ?? check?.details?.execution?.resolution;
  const command = check?.details?.command
    ?? (check?.kind === "command" && typeof check?.source === "string" && !check.source.startsWith("check:")
      ? check.source
      : null);

  if (!canonicalResolution && (!command || typeof command !== "string")) return { valid: true, error: null };

  const classification = canonicalResolution ?? classifyCommandResolution(command);
  if (!classification.mayInstall) return { valid: true, error: null };

  const authorityRef = getInstallationAuthorityRef(check);
  if (!authorityRef) {
    return {
      valid: false,
      error: {
        code: E_INSTALLATION_AUTHORITY_REQUIRED,
        message: `Verification command '${command}' uses installation-capable resolution (${classification.resolutionMode}) without recorded installation authority reference`,
      },
    };
  }

  const resolved = resolveTrustedAuthority({
    authorityRef,
    target: options.target,
    trustedAuthorityFile: options.trustedAuthorityFile,
    trustedAuthorityDir: options.trustedAuthorityDir,
    authorities: options.authorities,
    authority: options.authority,
    authorityContext: options.authorityContext,
    runtimeContext: options.runtimeContext,
  });
  if (!resolved.trusted) {
    if (resolved.error?.code === E_AUTHORITY_INVALID && resolved.sourceConfigured === false) {
      return {
        valid: false,
        error: {
          code: E_INSTALLATION_AUTHORITY_REQUIRED,
          message: "Installation-capable verification requires a host-attested authority context",
        },
      };
    }
    return { valid: false, error: resolved.error };
  }

  return validateAuthorityGrant({
    authority: resolved.authority,
    taskId: options.taskId,
    type: "SOFTWARE_INSTALLATION",
    tool: classification.tool,
  });
}

function ownershipProjection(projection) {
  return {
    taskId: projection.taskId,
    phase: projection.phase,
    claimState: projection.claimState,
    mutationAllowed: projection.mutationAllowed,
    ownershipValid: projection.ownershipValid,
    recoveryStatus: projection.recoveryStatus,
    historicalWriteClaims: [...projection.historicalWriteClaims],
    effectiveWriteClaims: [...projection.effectiveWriteClaims],
    reasonCodes: [...projection.reasonCodes],
  };
}

export async function readManifest(target) {
  await assertSafePath(target, MANIFEST_PATH);
  const manifestPath = ensureWithin(target, MANIFEST_PATH);
  if (!(await fileExists(manifestPath))) return null;
  let raw;
  try {
    const bytes = await readFile(manifestPath);
    assertJsonBytes(bytes, MANIFEST_PATH);
    raw = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(raw, MANIFEST_PATH);
  } catch (error) {
    throw new Error(`Unable to parse ${MANIFEST_PATH}: ${error.message}`);
  }
  return validateManifest(raw);
}

export function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function validateManifest(manifest) {
  if (!manifest || typeof manifest !== "object") {
    throw new Error("Manifest must contain a JSON object");
  }
  if (manifest.schemaVersion !== MANIFEST_SCHEMA_VERSION) {
    throw new Error(`Unsupported manifest schema: ${manifest.schemaVersion}`);
  }
  if (manifest.layoutVersion !== undefined
    && ![LEGACY_LAYOUT_VERSION, LAYOUT_VERSION].includes(manifest.layoutVersion)) {
    throw new Error(`Unsupported manifest layout: ${manifest.layoutVersion}`);
  }
  if (typeof manifest.packageVersion !== "string" || !manifest.packageVersion) {
    throw new Error("Manifest packageVersion is required");
  }
  if (!manifest.files || typeof manifest.files !== "object" || Array.isArray(manifest.files)) {
    throw new Error("Manifest files must be an object");
  }

  for (const [relativePath, record] of Object.entries(manifest.files)) {
    ensureWithin("/manifest-root", relativePath);
    if (!record || typeof record.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(record.sha256)) {
      throw new Error(`Invalid manifest hash for ${relativePath}`);
    }
    if (typeof record.preserve !== "boolean") {
      throw new Error(`Invalid manifest preserve flag for ${relativePath}`);
    }
    if (record.legacySha256 !== undefined
      && (typeof record.legacySha256 !== "string" || !/^[a-f0-9]{64}$/.test(record.legacySha256))) {
      throw new Error(`Invalid manifest legacy hash for ${relativePath}`);
    }
  }
  return manifest;
}

export async function writeManifest(target, manifest, { dryRun = false } = {}) {
  validateManifest(manifest);
  await assertSafePath(target, MANIFEST_PATH);
  const manifestPath = ensureWithin(target, MANIFEST_PATH);
  await writeFileAtomic(
    manifestPath,
    `${JSON.stringify(manifest, null, 2)}\n`,
    { dryRun },
  );
}

function array(value) {
  return Array.isArray(value) ? value.filter((item) => typeof item === "string") : [];
}

function contractText(contract) {
  if (!contract || typeof contract !== "object" || Array.isArray(contract)) return "";
  const values = [contract.objective, contract.summary, ...(contract.deliverables ?? []), ...(contract.successCriteria ?? []), ...(contract.risks ?? []), ...(contract.constraints ?? [])];
  return values.map((value) => value && typeof value === "object" ? value.text : value).filter((value) => typeof value === "string").join(" ").toLowerCase();
}

function deterministicFloor(input) {
  const normalized = normalizedInput(input);
  const reasons = [];
  const combined = `${contractText(normalized.contract)} ${normalized.workType} ${normalized.surfaces.join(" ")} ${normalized.risks.join(" ")}`;
  const generationRequired = normalized.generationRequired
    || normalized.behaviorChange
    || normalized.executableChange
    || GENERATION_WORK_TYPES.has(normalized.workType)
    || /\b(implement|fix|refactor|change|build|generate|write|modify|code)\b/.test(combined);
  const primary = normalized.architectureChange
    || normalized.ambiguity
    || PRIMARY_WORK_TYPES.has(normalized.workType)
    || normalized.risks.some((risk) => PRIMARY_RISKS.has(risk))
    || normalized.surfaces.some((surface) => PRIMARY_SURFACES.has(surface))
    || /\b(architecture|architectural|security boundary|migration|ambiguous|unknown requirements)\b/.test(combined);

  if (!generationRequired) {
    reasons.push("NO_GENERATION_REQUIRED");
    return { floor: "NONE", reasons };
  }
  reasons.push("GENERATION_REQUIRED");
  if (primary) {
    reasons.push("PRIMARY_COMPLEXITY_OR_RISK");
    return { floor: "PRIMARY", reasons };
  }
  reasons.push("STANDARD_GENERATION_FLOOR");
  return { floor: "STANDARD", reasons };
}

function normalizeRecommendation(recommendation) {
  if (recommendation === null || recommendation === undefined) return null;
  if (typeof recommendation === "string") {
    return MODEL_ROUTE_TIERS.includes(recommendation) ? { tier: recommendation, confidence: null, requiresEscalation: false } : null;
  }
  if (!recommendation || typeof recommendation !== "object" || Array.isArray(recommendation)) return null;
  const tier = typeof recommendation.tier === "string" && MODEL_ROUTE_TIERS.includes(recommendation.tier) ? recommendation.tier : null;
  if (!tier) return null;
  return {
    tier,
    confidence: typeof recommendation.confidence === "number" && Number.isFinite(recommendation.confidence) ? recommendation.confidence : null,
    requiresEscalation: recommendation.requiresEscalation === true,
  };
}

function normalizedInput(input = {}) {
  return {
    workType: text(input.workType),
    surfaces: array(input.surfaces).map(text),
    risks: array(input.risks).map(text),
    platforms: array(input.platforms).map(text),
    behaviorChange: input.behaviorChange === true,
    executableChange: input.executableChange === true,
    generationRequired: input.generationRequired === true,
    architectureChange: input.architectureChange === true,
    ambiguity: input.ambiguity === true,
    contract: input.contract,
  };
}

export function resolveModelRoute({ input = {}, semanticRecommendation = null } = {}) {
  const deterministic = deterministicFloor(input);
  const recommendation = normalizeRecommendation(semanticRecommendation);
  let resolved = deterministic.floor;
  const reasons = [...deterministic.reasons];
  if (recommendation?.requiresEscalation) {
    if (MODEL_ROUTE_RANK[resolved] < MODEL_ROUTE_RANK.PRIMARY) resolved = "PRIMARY";
    reasons.push("JEV_LOW_CONFIDENCE_ESCALATION");
  } else if (recommendation && MODEL_ROUTE_RANK[recommendation.tier] > MODEL_ROUTE_RANK[resolved]) {
    resolved = recommendation.tier;
    reasons.push("JEV_ESCALATION_ONLY");
  }
  return {
    floor: deterministic.floor,
    resolved,
    reasons: [...new Set(reasons)],
    semanticRecommendation: recommendation,
    generationRequired: deterministic.floor !== "NONE",
  };
}

function text(value) {
  return typeof value === "string" ? value.toLowerCase() : "";
}

export function projectModelRoute({ input = {}, semanticRecommendation = null } = {}) {
  const route = resolveModelRoute({ input, semanticRecommendation });
  if (!MODEL_ROUTE_TIERS.includes(route.floor) || !MODEL_ROUTE_TIERS.includes(route.resolved)
    || MODEL_ROUTE_RANK[route.resolved] < MODEL_ROUTE_RANK[route.floor]) {
    const error = new Error("Model route violates its deterministic safety floor.");
    error.code = "E_MODEL_ROUTE_SAFETY_FLOOR_INVALID";
    throw error;
  }
  return {
    schemaVersion: 1,
    policyVersion: MODEL_ROUTE_POLICY_VERSION,
    engine: "typesafe-jev",
    model: MODEL_ROUTE_JEV_MODEL,
    floor: route.floor,
    resolved: route.resolved,
    reasons: route.reasons,
    generationRequired: route.generationRequired,
    semanticRecommendation: route.semanticRecommendation,
    authority: MODEL_ROUTE_PROJECTION_AUTHORITY,
    evidenceAuthority: MODEL_ROUTE_PROJECTION_EVIDENCE_AUTHORITY,
    lifecycleAuthority: false,
    completionAuthority: false,
    ownershipAuthority: false,
    installationAuthority: false,
  };
}

export function inspectNativeAdapter(relativePath, bytes) {
  const text = Buffer.from(bytes).toString("utf8");
  const expected = nativeShimReferences(relativePath);
  const legacyReferences = text.match(LEGACY_REFERENCE_PATTERN) ?? [];
  const missingReferences = expected.filter((reference) => !text.includes(reference));
  const resolvedReferences = expected.map((reference) => ({
    reference,
    path: resolveNativeReference(relativePath, reference),
  }));

  return {
    text,
    expected,
    legacyReferences,
    missingReferences,
    resolvedReferences,
    hasForgeLoopMarker: /forgeloop/i.test(text),
    hasProtocolMarker: text.includes("FORGELOOP_PROJECT_PROTOCOL=REQUIRED"),
  };
}

export function nativeShimPrefix(relativePath) {
  if (relativePath.startsWith(".cursor/")) return "../../.forgeloop/kit";
  if (relativePath.startsWith(".github/")) return "../.forgeloop/kit";
  return ".forgeloop/kit";
}

export function nativeShimReferences(relativePath) {
  const prefix = nativeShimPrefix(relativePath);
  return [
    `${prefix}/LOOP_ENGINEERING.md`,
    `${prefix}/PROTOCOL_INTEGRATION.md`,
  ];
}

export async function validateNativeAdapterTargets({ target, relativePath, bytes }) {
  const inspection = inspectNativeAdapter(relativePath, bytes);
  const invalidReferences = inspection.resolvedReferences.filter(({ path: resolvedPath }) => !isKitPath(resolvedPath));
  const missingTargets = [];

  for (const { path: resolvedPath } of inspection.resolvedReferences) {
    if (!isKitPath(resolvedPath)) continue;
    try {
      await assertSafePath(target, resolvedPath);
      if (!(await fileExists(ensureWithin(target, resolvedPath)))) missingTargets.push(resolvedPath);
    } catch (error) {
      invalidReferences.push({ path: resolvedPath, error: error.message });
    }
  }

  return {
    ...inspection,
    invalidReferences,
    missingTargets,
    stale: inspection.legacyReferences.length > 0
      || inspection.missingReferences.length > 0
      || invalidReferences.length > 0,
  };
}

export function artifactError(code, message, artifacts = []) {
  return { code, message, artifacts };
}

export function checkListReasons(state) {
  try {
    assertCheckList(state.checks, "work-state.checks");
    return [];
  } catch (error) {
    return [artifactError(error.code ?? "E_CHECK_INVALID", error.message, [ARTIFACT_PATHS.state])];
  }
}

export function freshnessReasons(state, classification) {
  const requiredArtifactPaths = state.requiredArtifacts?.map((artifact) => artifact.path) ?? [];
  const reasons = [artifactError(
    "E_STATE_REVALIDATION_REQUIRED",
    `Work-state checkpoint requires revalidation: ${classification.reasons.join(", ")}`,
    [ARTIFACT_PATHS.state],
  )];
  for (const reason of classification.reasons) {
    const contractRelated = ["CONTRACT_CHANGED", "CONTRACT_INVALID", "CONTRACT_NOT_VERIFIED"].includes(reason);
    const artifactRelated = reason.startsWith("REQUIRED_ARTIFACT");
    reasons.push(artifactError(
      contractRelated ? "E_CONTRACT_STALE" : artifactRelated ? "E_REQUIRED_ARTIFACT_STALE" : "E_REPOSITORY_CHANGED",
      `Work-state freshness check failed: ${reason}`,
      uniqueSorted([
        ARTIFACT_PATHS.state,
        ...(contractRelated ? [ARTIFACT_PATHS.contract] : []),
        ...(artifactRelated ? requiredArtifactPaths : []),
      ]),
    ));
  }
  return reasons;
}

export async function loadArtifact(loader, fallback) {
  try {
    return { value: await loader(), error: null, missingArtifacts: [] };
  } catch (error) {
    return {
      value: null,
      error,
      missingArtifacts: error?.code === "ARTIFACT_MISSING"
        ? (error.artifacts?.length ? error.artifacts : [fallback])
        : [],
    };
  }
}

export async function requirementsAndCoverage({
  target,
  packageRoot,
  contract,
  route,
  checks,
  additionalEvidence = [],
  authorityContext,
  runtimeContext,
}) {
  const requirements = await requiredEvidenceForTarget({
    target,
    contract,
    route,
    packageRoot,
    additionalEvidence,
  });
  return {
    requirements,
    coverage: coverageForRequirements(requirements, checks, {
      target,
      taskId: contract?.value?.taskId,
      options: { authorityContext, runtimeContext },
    }),
  };
}

export function staleReasons(state, contract, route) {
  const reasons = [];
  if (state.contractFingerprint !== contract.fingerprint) {
    reasons.push(artifactError(
      "E_CONTRACT_STALE",
      "Work state references a different current contract",
      [ARTIFACT_PATHS.state, ARTIFACT_PATHS.contract],
    ));
  }
  if (route.value.contractFingerprint !== undefined && route.value.contractFingerprint !== contract.fingerprint) {
    reasons.push(artifactError(
      "E_ROUTE_STALE",
      "Routing result references a different current contract",
      [ARTIFACT_PATHS.route, ARTIFACT_PATHS.contract],
    ));
  }
  if (state.routeFingerprint !== route.fingerprint) {
    reasons.push(artifactError(
      "E_ROUTE_STALE",
      "Work state references a different routing result",
      [ARTIFACT_PATHS.state, ARTIFACT_PATHS.route],
    ));
  }
  if (JSON.stringify(state.selectedGuides) !== JSON.stringify(route.value.guides)) {
    reasons.push(artifactError(
      "E_ROUTE_STALE",
      "Work state guides do not match the persisted routing result",
      [ARTIFACT_PATHS.state, ARTIFACT_PATHS.route],
    ));
  }
  return reasons;
}

function uniqueSorted(values) {
  return [...new Set(values.filter(Boolean))].sort();
}

export async function evaluateContinuityNextAction({ target, packageRoot, context } = {}) {
  return nextActionForContinuity({
    context,
    continuity: await reconcileContinuity({ target, packageRoot }),
  });
}

export function nextActionForContinuity({ context, continuity } = {}) {
  if (!continuity || ["ABSENT", "NOT_APPLICABLE"].includes(continuity.classification)) return null;

  if (continuity.classification === "FRESH") {
    const remaining = continuity.continuity?.remainingWork ?? [];
    if (remaining.length === 0) return null;
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.CONTINUE_IMPLEMENTATION,
      reasons: [reason(
        "CONTINUITY_REMAINING_WORK",
        `Execution continuity records ${remaining.length} remaining implementation item${remaining.length === 1 ? "" : "s"}.`,
        [ARTIFACT_PATHS.continuity],
      )],
      requiredArtifacts: REQUIRED_ARTIFACTS,
    });
  }

  if (continuity.classification === "RECONCILIATION_REQUIRED") {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      commands: ["forgeloop reconcile-continuity"],
      reasons: [reason(
        "E_CONTINUITY_RECONCILIATION_REQUIRED",
        "Execution continuity no longer matches canonical state or the current checkout; reconcile it before advancing verification.",
      )],
      requiredArtifacts: REQUIRED_ARTIFACTS,
    });
  }

  if (["INVALID", "INCONSISTENT"].includes(continuity.classification)) {
    const codes = continuity.reasonCodes?.length > 0
      ? continuity.reasonCodes
      : [continuity.classification === "INVALID" ? "E_CONTINUITY_INVALID" : "E_CONTINUITY_INCONSISTENT"];
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: codes.map((code, index) => reason(
        code,
        continuity.reasons?.[index] ?? `Execution continuity is ${continuity.classification.toLowerCase()}.`,
      )),
      requiredArtifacts: REQUIRED_ARTIFACTS,
    });
  }

  return null;
}

function reason(code, message, artifacts = REQUIRED_ARTIFACTS) {
  return { code, message, artifacts };
}

export function contractBootstrapRepairGuidance(taskId, reason = null) {
  const command = `forgeloop task-repair-contract-bootstrap --task ${taskId} --acknowledge-repair --json`;
  return {
    nextAction: NEXT_ACTIONS.REPAIR_CONTRACT_BOOTSTRAP,
    commands: [command],
    commandSpecs: [directCommandSpec("task-repair-contract-bootstrap", taskId, [
      { name: "acknowledgeRepair", option: "--acknowledge-repair", description: "Explicit caller acknowledgement of the exact repair signature." },
    ])],
    reason: reason ?? { code: "E_CONTRACT_BOOTSTRAP_REPAIR_AVAILABLE", message: "The exact duplicate contract bootstrap defect is repairable through the official append-only command." },
  };
}

export function contractBootstrapRepairMigrationGuidance(taskId, reason = null) {
  const command = `forgeloop task-migrate-contract-bootstrap-repair --task ${taskId} --acknowledge-migration --json`;
  return {
    nextAction: NEXT_ACTIONS.MIGRATE_CONTRACT_BOOTSTRAP_REPAIR,
    commands: [command],
    commandSpecs: [directCommandSpec("task-migrate-contract-bootstrap-repair", taskId, [
      { name: "acknowledgeMigration", option: "--acknowledge-migration", description: "Fresh explicit caller acknowledgement of the exact legacy marker migration." },
    ])],
    reason: reason ?? { code: "E_CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_AVAILABLE", message: "The exact legacy contract bootstrap repair marker can be migrated through the official append-only command." },
  };
}

export function decision(input, action, reason, requiredArtifacts = [], missingArtifacts = [], optionalActions = undefined) {
  const command = commandFor(action);
  return result({
    ...input,
    nextAction: action,
    reasons: [reason],
    ...(command ? { commands: [command] } : {}),
    requiredArtifacts,
    missingArtifacts,
    optionalActions,
  });
}

export function directCommandSpec(commandId, taskId, requiredInputs = []) {
  return {
    commandId,
    executable: "forgeloop",
    subcommand: commandId,
    argv: [commandId, `--task=${taskId}`, "--json"],
    requiredInputs,
  };
}

