function canAppendCanonicalRouteWitness({ stateBefore, previousPersistedRouteFingerprint, persistedRoute }) {
  return stateBefore?.phase === "ROUTED"
    && previousPersistedRouteFingerprint !== null
    && persistedRoute.fingerprint !== previousPersistedRouteFingerprint
    && stateBefore.contractFingerprint === persistedRoute.value.contractFingerprint;
}

function canAppendRepairedRouteWitness({ stateBefore, marker, previousPersistedRouteFingerprint, persistedRoute }) {
  if (previousPersistedRouteFingerprint === null) {
    return stateBefore.phase === "CONTRACT_READY"
      && marker.details.reconstructedPhase === "CONTRACT_READY"
      && marker.details.routeFingerprint === null;
  }
  return persistedRoute.fingerprint !== previousPersistedRouteFingerprint
    && persistedRoute.value.contractFingerprint === marker.details.contractFingerprint;
}

async function projectSnapshotSemanticPlan({ target, packageRoot, taskId, decisionId, kind, input, semanticRecommendation }) {
  if (target && taskId) {
    const decisionKind = { failure: "FAILURE_TRIAGE", diagnosis: "DIAGNOSIS_PRIORITY", review: "REVIEW_PLAN" }[kind];
    const bindings = await readCurrentDecisionBindings(target, packageRoot, taskId);
    // Decision stateFingerprint includes semantic inputs; this reader proves the lifecycle via taskStateFingerprint.
    delete bindings.stateFingerprint;
    const decision = await resolveRequiredSemanticDecision({ target, packageRoot, taskId, decisionId, decisionKind, currentBindings: bindings });
    semanticRecommendation = projectionRecommendation(kind, decision.decision);
  }
  return projectPlan({ kind, input, semanticRecommendation });
}

function projectionRecommendation(kind, decision) {
  const values = PROJECTION_VALUES[kind];
  if (!values) return decision;
  const field = kind === "failure" ? "failureClass" : "priority";
  const value = decision[field];
  if (value === "unknown") return null;
  return { ...decision, [field]: Object.hasOwn(values, value) ? values[value] : value };
}

async function present(target, relativePath) {
  try { await lstat(await assertSafePath(target, relativePath)); return true; }
  catch (error) { if (error.code === "ENOENT") return false; throw error; }
}

export async function assertNoScopeConflictsWithInspection(claims, existingTasks, currentTaskId, { target, packageRoot } = {}) {
  try {
    assertNoScopeConflicts(claims, existingTasks, currentTaskId);
  } catch (error) {
    if (error.code !== "E_TASK_SCOPE_CONFLICT") throw error;
    const inspected = [];
    for (const conflict of error.conflicts ?? []) {
      let inspection = null;
      try {
        inspection = await inspectTaskConflictState(target, { taskId: conflict.taskId, packageRoot });
      } catch (inspectionError) {
        inspection = {
          taskId: conflict.taskId,
          classification: "INCONSISTENT",
          reasonCodes: [inspectionError.code ?? "E_TASK_NOT_FOUND"],
          recoverable: false,
        };
      }
      const guidance = recoveryGuidanceForClassification(inspection.classification, conflict.taskId);
      inspected.push({
        ...conflict,
        classification: inspection.classification,
        reasonCodes: inspection.reasonCodes,
        nextAction: guidance.nextAction,
        commandSpecs: guidance.commandSpecs,
        inspection,
      });
    }
    error.conflicts = inspected;
    error.message = `${error.message}; conflicting task classifications: ${inspected
      .map((item) => `${item.taskId}=${item.inspection.classification}`)
      .join(", ")}`;
    throw error;
  }
}

