function hasCanonicalVerificationEvidence(details) {
  return Boolean(
    details
    && typeof details.evidenceRef === "string" && details.evidenceRef.length > 0 && details.evidenceRef.length <= 256
    && details.evidenceKind === "FORGELOOP_EXECUTION"
    && typeof details.verifiedAt === "string",
  );
}

function hasModernAuthorizationEvidence(details) {
  if (!details || typeof details !== "object") return false;
  if (!["ALLOW", "REQUIRE_AUTHORITY", "REQUIRE_APPROVAL"].includes(details.capabilityDecision)) return false;
  if (typeof details.capabilityPolicyFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.capabilityPolicyFingerprint)) return false;
  if (typeof details.policyLockDigest !== "string" || !details.policyLockDigest.startsWith("sha256:")) return false;
  if (typeof details.taskPolicyDigest !== "string" || !details.taskPolicyDigest.startsWith("sha256:")) return false;
  if (details.capabilityDecision === "ALLOW") return true;
  if (details.authorityKind !== "HOST_ATTESTED" || typeof details.authorityRef !== "string" || !details.authorityRef) return false;
  if (details.capabilityDecision === "REQUIRE_AUTHORITY") return true;
  if (details.capabilityDecision === "REQUIRE_APPROVAL") {
    return typeof details.approvalId === "string" && !!details.approvalId
      && typeof details.approvalFingerprint === "string" && /^[a-f0-9]{64}$/.test(details.approvalFingerprint);
  }
  return false;
}

function issue(code, message) {
  return { code, message };
}

export async function projectActionLedger({
  target,
  packageRoot,
  taskId,
  actionId,
  artifact = null,
}) {
  const chronology = await readActionChronology(target, packageRoot, taskId, actionId);
  const errors = [];

  const proposed = chronology.find((event) => event.event === "ACTION_PROPOSED");
  if (!proposed) {
    return {
      actionId,
      valid: false,
      state: null,
      revision: null,
      actionFingerprint: artifact?.actionFingerprint ?? null,
      authorization: { valid: false, details: null },
      verification: { valid: false, evidenceRef: null },
      reconciliation: { count: 0, latestOutcome: null },
      errors: [issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId} has no matching ACTION_PROPOSED ledger event`)],
    };
  }

  const actionFingerprint = proposed.details.actionFingerprint;
  let state = "PROPOSED";
  let revision = 0;
  let authorization = { valid: false, details: null };
  let verification = { valid: false, evidenceRef: null };
  const reconciliation = { count: 0, latestOutcome: null };
  // A trusted COMMITTED reconciliation emits two events for one logical
  // transition: ACTION_RECONCILED(outcome=COMMITTED) owns the transition and
  // ACTION_COMMIT_RECORDED(reconciled=true) is a same-revision informational
  // mirror. Replay must apply exactly one transition (INV-FINAL-REPLAY-01).
  let pendingReconciledCommitMirror = null;

  for (const event of chronology) {
    const details = event.details ?? {};

    if (details.actionFingerprint !== actionFingerprint) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: event ${event.event} carries a different action fingerprint`));
      continue;
    }
    const isReconciledMirror = event.event === "ACTION_COMMIT_RECORDED" && details.reconciled === true;
    if (
      Number.isInteger(details.revision)
      && details.revision !== revision + 1
      && event.event !== "ACTION_RECONCILED"
      && !isReconciledMirror
    ) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: ${event.event} skipped revision (expected ${revision + 1}, got ${details.revision})`));
    }

    switch (event.event) {
      case "ACTION_PROPOSED":
        break;
      case "ACTION_AUTHORIZED": {
        try {
          assertActionTransition(state, "AUTHORIZED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> AUTHORIZED`));
          continue;
        }
        // Structural validation always applies; legacy events are readable
        // but never satisfy trusted authorization.
        const isModern = hasModernAuthorizationEvidence(details);
        try {
          assertActionAuthorizationDetails({ ...details }, { legacyAllowed: true });
        } catch (error) {
          errors.push(issue(error.code ?? E_ACTION_EVIDENCE_INVALID, `action ${actionId}: invalid ACTION_AUTHORIZED details: ${error.message}`));
          continue;
        }
        state = "AUTHORIZED";
        revision += 1;
        authorization = { valid: isModern, details: isModern ? details : null };
        break;
      }
      case "ACTION_STARTED": {
        try {
          assertActionTransition(state, "STARTED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: ACTION_STARTED without a legal predecessor state (${state})`));
          continue;
        }
        if (!authorization.valid) {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: ACTION_STARTED occurred without valid modern authorization evidence`));
        }
        state = "STARTED";
        revision += 1;
        break;
      }
      case "ACTION_COMMIT_RECORDED": {
        // Reconciled commit mirrors corroborate a preceding trusted COMMITTED
        // reconciliation; they never transition state again.
        if (details.reconciled === true) {
          const mirror = pendingReconciledCommitMirror;
          if (
            !mirror
            || details.revision !== mirror.revision
            || details.actionFingerprint !== mirror.actionFingerprint
            || details.fromState !== mirror.fromState
            || details.toState !== mirror.toState
          ) {
            errors.push(issue(
              E_ACTION_EVIDENCE_INVALID,
              `action ${actionId}: reconciled commit mirror does not match the preceding COMMITTED reconciliation`,
            ));
            break;
          }
          pendingReconciledCommitMirror = null;
          break;
        }
        try {
          assertActionTransition(state, "COMMITTED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> COMMITTED`));
          continue;
        }
        state = "COMMITTED";
        revision += 1;
        break;
      }
      case "ACTION_VERIFIED": {
        try {
          assertActionTransition(state, "VERIFIED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> VERIFIED`));
          continue;
        }
        if (!hasCanonicalVerificationEvidence(details)) {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: ACTION_VERIFIED lacks canonical evidence`));
          state = "VERIFIED";
          revision += 1;
          verification = { valid: false, evidenceRef: details.evidenceRef ?? null };
          continue;
        }
        state = "VERIFIED";
        revision += 1;
        verification = { valid: true, evidenceRef: details.evidenceRef };
        break;
      }
      case "ACTION_FAILED": {
        try {
          assertActionTransition(state, "FAILED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> FAILED`));
          continue;
        }
        state = "FAILED";
        revision += 1;
        break;
      }
      case "ACTION_CANCELLED": {
        try {
          assertActionTransition(state, "CANCELLED");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> CANCELLED`));
          continue;
        }
        state = "CANCELLED";
        revision += 1;
        break;
      }
      case "ACTION_COMMIT_UNKNOWN": {
        try {
          assertActionTransition(state, "COMMIT_UNKNOWN");
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: illegal transition ${state} -> COMMIT_UNKNOWN`));
          continue;
        }
        state = "COMMIT_UNKNOWN";
        revision += 1;
        break;
      }
      case "ACTION_RECONCILED": {
        reconciliation.count += 1;
        reconciliation.latestOutcome = details.outcome ?? null;
        if (state !== "COMMIT_UNKNOWN") {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: ACTION_RECONCILED recorded while state was ${state}, not COMMIT_UNKNOWN`));
          continue;
        }
        const outcome = details.outcome;
        if (outcome === "UNKNOWN") {
          revision += 1;
          continue;
        }
        const nextState = outcome === "COMMITTED" ? "COMMITTED" : outcome === "NOT_COMMITTED" ? "PROPOSED" : null;
        if (!nextState) {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: unknown reconciliation outcome ${String(outcome)}`));
          continue;
        }
        try {
          assertActionTransition("COMMIT_UNKNOWN", nextState);
        } catch {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: reconciliation outcome ${outcome} maps to an illegal transition`));
          continue;
        }
        if (
          typeof details.authorityKind !== "string"
          || details.authorityKind !== "HOST_ATTESTED"
          || typeof details.authorityRef !== "string"
        ) {
          errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: settling reconciliation lacks trusted authority binding`));
        }
        state = nextState;
        revision += 1;
        if (outcome === "COMMITTED") {
          pendingReconciledCommitMirror = {
            revision: details.revision,
            actionFingerprint,
            fromState: "COMMIT_UNKNOWN",
            toState: "COMMITTED",
          };
        }
        break;
      }
      default:
        break;
    }
  }

  if (artifact) {
    if (artifact.state !== state) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: artifact state ${artifact.state} differs from projected ledger state ${state}`));
    }
    if (artifact.revision !== revision) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: artifact revision ${artifact.revision} differs from projected revision ${revision}`));
    }
    if (artifact.actionFingerprint !== actionFingerprint) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: artifact fingerprint differs from the immutable proposal fingerprint`));
    }
    // The artifact's evidence pointer must match the canonical verification
    // event when both claim a verified postcondition.
    if (
      artifact.lastEvidenceRef !== undefined
      && artifact.lastEvidenceRef !== null
      && verification.valid
      && state === "VERIFIED"
      && artifact.lastEvidenceRef !== verification.evidenceRef
    ) {
      errors.push(issue(E_ACTION_EVIDENCE_INVALID, `action ${actionId}: artifact lastEvidenceRef does not match the ACTION_VERIFIED evidence reference`));
    }
  }

  return {
    actionId,
    valid: errors.length === 0,
    state,
    revision,
    actionFingerprint,
    authorization,
    verification,
    reconciliation,
    errors,
  };
}

function actionError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function assertActionAuthorizationDetails(details, { legacyAllowed = false } = {}) {
  const required = legacyAllowed
    ? []
    : [
      "capabilityDecision",
      "actionFingerprint",
      "capabilityPolicyFingerprint",
      "policyLockDigest",
      "taskPolicyDigest",
    ];
  for (const key of required) {
    assertBoundedEventText(details, key, 512);
  }
  if (details.capabilityDecision !== undefined) {
    if (!["ALLOW", "REQUIRE_AUTHORITY", "REQUIRE_APPROVAL"].includes(details.capabilityDecision)) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "capabilityDecision must be ALLOW, REQUIRE_AUTHORITY, or REQUIRE_APPROVAL",
      );
    }
    if (
      typeof details.capabilityPolicyFingerprint !== "string" ||
      !SHA256_HEX_REGEX.test(details.capabilityPolicyFingerprint)
    ) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "capabilityPolicyFingerprint must bind ACTION_AUTHORIZED to the exact project policy",
      );
    }
    if (typeof details.policyLockDigest !== "string" || !details.policyLockDigest.startsWith("sha256:")) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "policyLockDigest must bind ACTION_AUTHORIZED to the persisted policy lock",
      );
    }
    if (typeof details.taskPolicyDigest !== "string" || !details.taskPolicyDigest.startsWith("sha256:")) {
      throw actionError(
        E_ACTION_EVIDENCE_INVALID,
        "taskPolicyDigest must bind ACTION_AUTHORIZED to the task policy snapshot",
      );
    }
    if (details.capabilityDecision === "REQUIRE_AUTHORITY") {
      if (details.authorityKind !== "HOST_ATTESTED") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_AUTHORIZATION decisions require authorityKind=HOST_ATTESTED",
        );
      }
      assertBoundedEventText(details, "authorityRef", 256);
    }
    if (details.capabilityDecision === "REQUIRE_APPROVAL") {
      assertBoundedEventText(details, "approvalId", 256);
      if (typeof details.approvalFingerprint !== "string") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_APPROVAL authorizations require approvalFingerprint",
        );
      }
      if (details.authorityKind !== "HOST_ATTESTED") {
        throw actionError(
          E_ACTION_EVIDENCE_INVALID,
          "REQUIRE_APPROVAL authorizations require authorityKind=HOST_ATTESTED",
        );
      }
      assertBoundedEventText(details, "authorityRef", 256);
    }
  }
  return true;
}

export function assertActionTransition(from, to) {
  const targets = ACTION_TRANSITIONS.get(from);
  if (!targets || !targets.includes(to)) {
    throw actionError(
      E_ACTION_STATE_MISMATCH,
      `Invalid durable action transition ${String(from)} -> ${String(to)}`,
    );
  }
  return to;
}

export function assertApprovalIdFormat(approvalId) {
  if (typeof approvalId !== "string" || !APPROVAL_ID_REGEX.test(approvalId)) {
    throw actionError(E_APPROVAL_INVALID, "approvalId must match approval-[A-Za-z0-9_-]+");
  }
  return approvalId;
}

function assertBoundedEventText(details, key, maxLength, { required = true } = {}) {
  const value = details[key];
  if (value === undefined || value === null) {
    if (required) throw actionError(E_ACTION_EVIDENCE_INVALID, `event details.${key} is required`);
    return;
  }
  if (typeof value !== "string" || value.length === 0 || value.length > maxLength) {
    throw actionError(
      E_ACTION_EVIDENCE_INVALID,
      `event details.${key} must be a non-empty string of at most ${maxLength} characters`,
    );
  }
}

function assertBoundedText(value, label, maxLength, { required = true } = {}) {
  if (value === undefined || value === null) {
    if (required) throw actionError(E_ACTION_INVALID, `${label} is required`);
    return;
  }
  if (typeof value !== "string" || value.length === 0) {
    throw actionError(E_ACTION_INVALID, `${label} must be a non-empty string`);
  }
  if (value.length > maxLength) {
    throw actionError(E_ACTION_INVALID, `${label} must not exceed ${maxLength} characters`);
  }
}

function assertEnum(value, allowed, label) {
  if (!allowed.includes(value)) {
    throw actionError(E_ACTION_INVALID, `${label} must be one of ${allowed.join(", ")}`);
  }
}

function assertTimestamp(value, label, { required = false } = {}) {
  if (value === undefined || value === null) {
    if (required) throw actionError(E_ACTION_INVALID, `${label} is required`);
    return;
  }
  if (typeof value !== "string" || Number.isNaN(Date.parse(value))) {
    throw actionError(E_ACTION_INVALID, `${label} must be an ISO timestamp string`);
  }
}

export function validateActionArtifact(action) {
  if (!action || typeof action !== "object" || Array.isArray(action)) {
    throw actionError(E_ACTION_INVALID, "durable action artifact must be a JSON object");
  }

  for (const key of [
    "schemaVersion",
    "taskId",
    "actionId",
    "actionFingerprint",
    "effectClass",
    "capability",
    "operation",
    "target",
    "idempotencyKey",
    "requiredForCompletion",
    "requirement",
    "provenance",
    "state",
    "revision",
    "createdAt",
    "updatedAt",
  ]) {
    if (!Object.prototype.hasOwnProperty.call(action, key)) {
      throw actionError(E_ACTION_INVALID, `durable action artifact.${key} is required`);
    }
  }

  if (action.schemaVersion !== 1) {
    throw actionError(E_ACTION_INVALID, "durable action schemaVersion must be 1");
  }
  assertBoundedText(action.taskId, "taskId", 256);
  assertBoundedText(action.actionId, "actionId", 256);
  if (!ACTION_ID_REGEX.test(action.actionId)) {
    throw actionError(E_ACTION_INVALID, "actionId must match action-[A-Za-z0-9_-]+");
  }
  if (typeof action.actionFingerprint !== "string" || !SHA256_HEX_REGEX.test(action.actionFingerprint)) {
    throw actionError(E_ACTION_INVALID, "actionFingerprint must be a lowercase sha256 hex digest");
  }
  assertEnum(action.effectClass, ACTION_EFFECT_CLASSES, "effectClass");
  assertEnum(action.capability, ACTION_CAPABILITIES, "capability");
  assertBoundedText(action.operation, "operation", 512);
  assertBoundedText(action.target, "target", 512);

  if (actionRequiresIdempotency(action.effectClass)) {
    assertBoundedText(action.idempotencyKey, "idempotencyKey", 512);
  } else if (action.idempotencyKey !== null && action.idempotencyKey !== undefined) {
    assertBoundedText(action.idempotencyKey, "idempotencyKey", 512);
  }

  if (typeof action.requiredForCompletion !== "boolean") {
    throw actionError(E_ACTION_INVALID, "requiredForCompletion must be a boolean");
  }
  assertBoundedText(action.requirement, "requirement", 256, { required: false });
  assertEnum(action.provenance, ACTION_PROVENANCE, "provenance");
  assertEnum(action.state, ACTION_STATES, "state");

  if (action.state !== "PROPOSED" && !Number.isInteger(action.revision)) {
    throw actionError(E_ACTION_INVALID, "revision must be an integer");
  }

  assertTimestamp(action.createdAt, "createdAt", { required: true });
  assertTimestamp(action.updatedAt, "updatedAt", { required: true });

  if (action.lastEvidenceRef !== undefined && action.lastEvidenceRef !== null) {
    assertBoundedText(action.lastEvidenceRef, "lastEvidenceRef", 256);
  }

  if (action.lastReconciliationAt !== undefined && action.lastReconciliationAt !== null) {
    assertTimestamp(action.lastReconciliationAt, "lastReconciliationAt", { required: true });
  }

  if (action.commitResultCode !== undefined && action.commitResultCode !== null) {
    assertEnum(
      action.commitResultCode,
      COMMIT_UNKNOWN_RESULT_CODES,
      "commitResultCode",
    );
  }

  // VERIFIED is a trust claim: it must always carry canonical evidence.
  if (action.state === "VERIFIED" && !action.lastEvidenceRef) {
    throw actionError(
      E_ACTION_VERIFICATION_REQUIRED,
      "VERIFIED actions require a canonical verification evidence reference",
    );
  }

  const allowedKeys = new Set([
    "schemaVersion",
    "taskId",
    "actionId",
    "actionFingerprint",
    "effectClass",
    "capability",
    "operation",
    "target",
    "idempotencyKey",
    "requiredForCompletion",
    "requirement",
    "provenance",
    "state",
    "revision",
    "createdAt",
    "updatedAt",
    "lastEvidenceRef",
    "lastReconciliationAt",
    "commitResultCode",
  ]);
  for (const key of Object.keys(action)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_ACTION_INVALID, `durable action artifact.${key} is not an allowed property`);
    }
  }

  const recomputed = canonicalActionFingerprint(action);
  if (recomputed !== action.actionFingerprint) {
    throw actionError(
      E_ACTION_INVALID,
      "actionFingerprint does not match the immutable identity fields",
    );
  }

  return action;
}

export function validateApprovalArtifact(approval) {
  if (!approval || typeof approval !== "object" || Array.isArray(approval)) {
    throw actionError(E_APPROVAL_INVALID, "approval artifact must be a JSON object");
  }

  for (const key of [
    "schemaVersion",
    "taskId",
    "approvalId",
    "actionId",
    "actionFingerprint",
    "contractFingerprint",
    "taskRevision",
    "capability",
    "status",
    "requestedAt",
  ]) {
    if (!Object.prototype.hasOwnProperty.call(approval, key)) {
      throw actionError(E_APPROVAL_INVALID, `approval artifact.${key} is required`);
    }
  }

  if (approval.schemaVersion !== 1) {
    throw actionError(E_APPROVAL_INVALID, "approval schemaVersion must be 1");
  }
  assertBoundedText(approval.taskId, "taskId", 256);
  assertBoundedText(approval.approvalId, "approvalId", 256);
  if (!APPROVAL_ID_REGEX.test(approval.approvalId)) {
    throw actionError(E_APPROVAL_INVALID, "approvalId must match approval-[A-Za-z0-9_-]+");
  }
  assertBoundedText(approval.actionId, "actionId", 256);
  if (typeof approval.actionFingerprint !== "string" || !SHA256_HEX_REGEX.test(approval.actionFingerprint)) {
    throw actionError(E_APPROVAL_INVALID, "actionFingerprint must be a lowercase sha256 hex digest");
  }
  if (
    typeof approval.contractFingerprint !== "string" ||
    !SHA256_HEX_REGEX.test(approval.contractFingerprint)
  ) {
    throw actionError(E_APPROVAL_INVALID, "contractFingerprint must be a lowercase sha256 hex digest");
  }
  if (!Number.isInteger(approval.taskRevision) || approval.taskRevision < 0) {
    throw actionError(E_APPROVAL_INVALID, "taskRevision must be a non-negative integer");
  }
  assertEnum(approval.capability, ACTION_CAPABILITIES, "capability");
  assertEnum(approval.status, APPROVAL_STATUSES, "status");
  assertTimestamp(approval.requestedAt, "requestedAt", { required: true });

  if (approval.status !== "PENDING") {
    assertEnum(approval.decision, [approval.status], "decision");
    assertTimestamp(approval.resolvedAt, "resolvedAt", { required: true });
    assertEnum(approval.authorityKind, APPROVAL_AUTHORITY_KINDS, "authorityKind");
    if (approval.authorityKind === "HOST_ATTESTED" && !approval.hostGrantRef) {
      throw actionError(
        E_APPROVAL_INVALID,
        "HOST_ATTESTED approvals require a hostGrantRef supplied by the host boundary",
      );
    }
  }

  const allowedKeys = new Set([
    "schemaVersion",
    "taskId",
    "approvalId",
    "actionId",
    "actionFingerprint",
    "contractFingerprint",
    "taskRevision",
    "capability",
    "status",
    "requestedAt",
    "reason",
    "decision",
    "resolvedAt",
    "authorityKind",
    "hostGrantRef",
  ]);
  for (const key of Object.keys(approval)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_APPROVAL_INVALID, `approval artifact.${key} is not an allowed property`);
    }
  }
  assertBoundedText(approval.reason, "reason", 512, { required: false });

  return approval;
}

export function validateCapabilityPolicy(policy) {
  if (!policy || typeof policy !== "object" || Array.isArray(policy)) {
    throw actionError(E_POLICY_INVALID, "capability policy must be a JSON object");
  }
  if (policy.schemaVersion !== 1) {
    throw actionError(E_POLICY_INVALID, "capability policy schemaVersion must be 1");
  }
  if (!["ALLOW", "DENY"].includes(policy.defaultDecision)) {
    throw actionError(
      E_POLICY_INVALID,
      "defaultDecision must be ALLOW or DENY; REQUIRE_* defaults are not valid",
    );
  }
  if (!Array.isArray(policy.rules)) {
    throw actionError(E_POLICY_INVALID, "rules must be an array");
  }
  const seen = new Set();
  for (const rule of policy.rules) {
    if (!rule || typeof rule !== "object") {
      throw actionError(E_POLICY_INVALID, "each rule must be a JSON object");
    }
    assertEnum(rule.capability, ACTION_CAPABILITIES, "rule.capability");
    assertEnum(rule.decision, CAPABILITY_DECISIONS, "rule.decision");
    if (seen.has(rule.capability)) {
      throw actionError(
        E_POLICY_INVALID,
        `duplicate rule for capability ${rule.capability}`,
      );
    }
    seen.add(rule.capability);
  }
  const allowedKeys = new Set(["schemaVersion", "defaultDecision", "rules"]);
  for (const key of Object.keys(policy)) {
    if (!allowedKeys.has(key)) {
      throw actionError(E_POLICY_INVALID, `capability policy.${key} is not an allowed property`);
    }
  }
  return policy;
}

export async function evaluateActionReadiness({
  target,
  packageRoot,
  taskId,
  action,
}) {
  const resolved = action ?? await readAction(target, { packageRoot, taskId, actionId: action?.actionId });
  const ledger = await projectActionLedger({
    target,
    packageRoot,
    taskId,
    actionId: resolved.actionId,
    artifact: resolved,
  });

  if (!ledger.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "action ledger chronology is invalid or diverges from the artifact",
      ...ledger.errors.map((error) => error.message),
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // REQUIRE_APPROVAL authorizations bind the exact resolved approval content;
  // any post-authorization mutation of the approval artifact must be
  // readiness/audit-visible (INV-FINAL-APPROVAL-01).
  const authorizationDetails = ledger.authorization.details;
  if (authorizationDetails?.capabilityDecision === "REQUIRE_APPROVAL") {
    try {
      const { validateBoundApprovalFingerprint } = await import("./approvals.js");
      await validateBoundApprovalFingerprint(target, {
        packageRoot,
        taskId,
        approvalId: authorizationDetails.approvalId,
        expectedFingerprint: authorizationDetails.approvalFingerprint,
      });
    } catch (error) {
      return result(resolved.actionId, "UNTRUSTED", [
        `bound approval integrity failed: ${error.message}`,
      ], { authorization: ledger.authorization, verification: ledger.verification });
    }
  }

  if (resolved.state === "COMMIT_UNKNOWN") {
    return result(resolved.actionId, "AMBIGUOUS", [
      "external commit state is unknown; reconcile through a trusted boundary",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (resolved.state === "FAILED" || resolved.state === "CANCELLED") {
    return result(resolved.actionId, "FAILED", [
      `action is ${resolved.state}`,
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (resolved.state !== "VERIFIED") {
    return result(resolved.actionId, "PENDING", [
      `action is ${resolved.state}; verification requires canonical independent evidence`,
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // A required action without a requirement can never be strongly verified:
  // legacy artifacts stay readable but cannot become trusted-satisfied
  // (INV-FINAL-VERIFY-02).
  if (
    resolved.requiredForCompletion
    && (typeof resolved.requirement !== "string" || resolved.requirement.length === 0)
  ) {
    return result(resolved.actionId, "UNTRUSTED", [
      "required action has no canonical requirement binding",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  // VERIFIED label present: trust requires modern authorization evidence.
  if (!ledger.authorization.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "authorization evidence is invalid or legacy pre-hardening",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  if (!ledger.verification.valid) {
    return result(resolved.actionId, "UNTRUSTED", [
      "verification evidence is missing or not canonical",
    ], { authorization: ledger.authorization, verification: ledger.verification });
  }

  return result(resolved.actionId, "SATISFIED", [], {
    authorization: ledger.authorization,
    verification: ledger.verification,
  });
}

export async function evaluateRequiredActionReadiness({
  target,
  packageRoot,
  taskId,
}) {
  const actions = await listActions(target, { packageRoot, taskId });
  const required = actions.filter((action) => action.requiredForCompletion);
  const evaluated = [];
  for (const action of required) {
    evaluated.push(await evaluateActionReadiness({ target, packageRoot, taskId, action }));
  }
  return {
    total: required.length,
    satisfied: evaluated.filter((item) => item.status === "SATISFIED").length,
    unresolved: evaluated.filter((item) => item.status !== "SATISFIED").length,
    ambiguous: evaluated.filter((item) => item.status === "AMBIGUOUS").length,
    failed: evaluated.filter((item) => item.status === "FAILED").length,
    untrusted: evaluated.filter((item) => item.status === "UNTRUSTED").length,
    actions: evaluated,
  };
}

function result(actionId, status, reasons, extra = {}) {
  return {
    actionId,
    status,
    reasons,
    ...extra,
  };
}

function actionError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function assertProposeInput(input) {
  if (!input || typeof input !== "object") {
    throw actionError(E_ACTION_INVALID, "action input must be an object");
  }
  if (typeof input.actionId !== "string" || !/^action-[A-Za-z0-9_-]+$/.test(input.actionId)) {
    throw actionError(E_ACTION_INVALID, "actionId must match action-[A-Za-z0-9_-]+");
  }
  for (const key of ["effectClass", "capability", "operation", "target", "provenance"]) {
    if (typeof input[key] !== "string" || !input[key]) {
      throw actionError(E_ACTION_INVALID, `action input.${key} must be a non-empty string`);
    }
  }
  if (actionRequiresIdempotency(input.effectClass)) {
    if (typeof input.idempotencyKey !== "string" || !input.idempotencyKey) {
      throw actionError(
        E_ACTION_IDEMPOTENCY_REQUIRED,
        `effectClass ${input.effectClass} requires an idempotency key`,
      );
    }
  }
  // Completion-critical actions must declare what postcondition they satisfy;
  // without a requirement, strong verification binding is impossible
  // (INV-FINAL-VERIFY-02). Legacy artifacts remain readable but untrusted.
  if (
    input.requiredForCompletion === true
    && (typeof input.requirement !== "string" || input.requirement.trim() === "")
  ) {
    throw actionError(
      E_ACTION_INVALID,
      "required-for-completion actions require a non-empty requirement",
    );
  }
}

