export async function validateBoundApprovalFingerprint(target, {
  packageRoot,
  taskId,
  approvalId,
  expectedFingerprint,
}) {
  if (
    typeof expectedFingerprint !== "string"
    || !/^[a-f0-9]{64}$/.test(expectedFingerprint)
  ) {
    throw approvalError(
      E_APPROVAL_INVALID,
      "expected approval fingerprint must be a lowercase sha256 hex digest",
    );
  }

  const approval = await readApproval(target, {
    packageRoot,
    taskId,
    approvalId,
  });

  const actualFingerprint = approvalFingerprint(approval);

  if (actualFingerprint !== expectedFingerprint) {
    throw approvalError(
      E_APPROVAL_INVALID,
      `approval ${approvalId} no longer matches the fingerprint bound at action authorization`,
    );
  }

  return {
    approval,
    fingerprint: actualFingerprint,
  };
}

function changedPathNames(entry) {
  return [entry.path, entry.sourcePath].filter(Boolean);
}

export function assertAttestationStatementBindings(statement, manifest, taskId, manifestFingerprint = canonicalFingerprint(manifest)) {
  const predicate = statement.predicate;
  if (predicate.task.taskId !== taskId || predicate.task.verificationCycle !== manifest.verificationCycle) {
    throw verifierError("E_ATTESTATION_SCOPE_MISMATCH", "Attestation statement task or verification cycle does not match the manifest");
  }
  if (predicate.content.manifestFingerprint !== manifestFingerprint) {
    throw verifierError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement does not bind the current code manifest");
  }
  if (predicate.content.contentDigest !== manifest.contentDigest) {
    throw verifierError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject does not bind the manifest content digest");
  }
  const expectedPaths = [...new Set(manifest.entries.flatMap((entry) => [entry.path, entry.sourcePath].filter(Boolean)))].sort();
  const actualPaths = [...new Set(predicate.content.coveredPaths)].sort();
  if (JSON.stringify(expectedPaths) !== JSON.stringify(actualPaths)) {
    throw verifierError("E_ATTESTATION_SCOPE_MISMATCH", "Statement covered paths do not match the manifest");
  }
  const bindingPairs = [
    ["contractFingerprint", "E_ATTESTATION_CONTRACT_MISMATCH"],
    ["routeFingerprint", "E_ATTESTATION_ROUTE_MISMATCH"],
    ["stateFingerprint", "E_ATTESTATION_STATE_MISMATCH"],
    ["receiptFingerprint", "E_ATTESTATION_RECEIPT_MISMATCH"],
    ["ledgerSeq", "E_ATTESTATION_LEDGER_MISMATCH"],
    ["ledgerHash", "E_ATTESTATION_LEDGER_MISMATCH"],
  ];
  for (const [key, code] of bindingPairs) {
    if (predicate.evidence[key] !== manifest.bindings[key]) {
      throw verifierError(code, `Statement evidence does not match the manifest binding: ${key}`);
    }
  }
}

function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function verifierError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "AttestationVerificationError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function verifyCodeManifestContent({ target, manifest, revisionProvider, revision = null } = {}) {
  const provider = typeof revisionProvider === "string"
    ? await resolveRevisionProvider({ target, providerName: revisionProvider, registry: REVISION_PROVIDERS })
    : revisionProvider;
  assertRevisionProvider(provider);
  const targetRevision = revision ?? (manifest.capture.mode === "WORKTREE" ? "WORKTREE" : manifest.capture.observedRevision);
  const results = [];
  for (const entry of manifest.entries) {
    results.push({ path: entry.path, ...(await verifyEntryContent(provider, { target, revision: targetRevision }, entry)) });
  }
  return { valid: true, revision: targetRevision, results, provider };
}

async function verifyEntryContent(provider, { target, revision }, entry) {
  if (entry.kind === "DELETED" || entry.operation === "DELETED") {
    try {
      await provider.readContent({ target, revision, path: entry.path });
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Deleted path exists at revision ${revision}: ${entry.path}`);
    } catch (error) {
      if (error.code === "E_ATTESTATION_CONTENT_MISMATCH") throw error;
      if (error.notFound === true) return { valid: true };
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Unable to prove that deleted path is absent at revision ${revision}: ${entry.path}`, [entry.path]);
    }
  }
  if (entry.kind === "GITLINK") {
    let identity;
    try {
      identity = await provider.getContentIdentity({ target, revision, path: entry.path });
    } catch (error) {
      if (error.notFound === true) throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Gitlink is absent at revision ${revision}: ${entry.path}`, [entry.path]);
      throw error;
    }
    if (identity !== entry.providerContentId) {
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Gitlink identity differs from the attested snapshot: ${entry.path}`, [entry.path]);
    }
    return { valid: true, actualIdentity: identity };
  }
  let bytes;
  try {
    bytes = await provider.readContent({ target, revision, path: entry.path });
  } catch (error) {
    if (error.code?.startsWith("E_REVISION_") && error.notFound !== true) throw error;
    throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Attested path cannot be read at revision ${revision}: ${entry.path}`, [entry.path]);
  }
  const actualDigest = sha256(bytes);
  if (actualDigest !== entry.sha256) {
    throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Current source content differs from the attested snapshot: ${entry.path}`, [entry.path]);
  }
  if (entry.providerContentId) {
    let actualIdentity;
    try {
      actualIdentity = await provider.getContentIdentity({ target, revision, path: entry.path });
    } catch (error) {
      if (error.code?.startsWith("E_REVISION_") && error.notFound !== true) throw error;
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Attested provider identity cannot be read at revision ${revision}: ${entry.path}`, [entry.path]);
    }
    if (actualIdentity !== entry.providerContentId) {
      throw verifierError("E_ATTESTATION_CONTENT_MISMATCH", `Provider content identity differs from the attested snapshot: ${entry.path}`, [entry.path]);
    }
  }
  return { valid: true, actualDigest };
}

function attestationError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "AttestationError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function validateAttestationPredicate(predicate, packageRoot = getPackageRoot()) {
  try {
    assertSchema(predicate, await readSchema("code-attestation", packageRoot), "ForgeLoop attestation predicate");
    assertSecretFree(predicate);
    return predicate;
  } catch (error) {
    throw attestationError("E_ATTESTATION_STATEMENT_INVALID", error.message);
  }
}

export async function validateAttestationStatement(statement, packageRoot = getPackageRoot()) {
  try {
    assertSchema(statement, await readSchema("in-toto-statement", packageRoot), "in-toto statement");
    if (statement._type !== STATEMENT_TYPE || statement.predicateType !== PREDICATE_TYPE) {
      throw attestationError("E_ATTESTATION_STATEMENT_INVALID", "Statement type or predicate type is not the ForgeLoop v1 contract");
    }
    await validateAttestationPredicate(statement.predicate, packageRoot);
    const subject = statement.subject[0];
    if (subject.name !== `forgeloop-task:${statement.predicate.task.taskId}`) {
      throw attestationError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject does not match the attested task");
    }
    if (subject.digest.sha256 !== statement.predicate.content.contentDigest) {
      throw attestationError("E_ATTESTATION_SUBJECT_MISMATCH", "Statement subject digest does not match the predicate content digest");
    }
    assertSecretFree(statement);
    return statement;
  } catch (error) {
    if (error.code?.startsWith("E_ATTESTATION_")) throw error;
    throw attestationError("E_ATTESTATION_STATEMENT_INVALID", error.message);
  }
}

function auditUxError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function buildProjection({ status, audit, report, history, trace, ownership, next, approvals, timeline }) {
  const integrityErrors = [
    ...projectErrors(audit.errors),
    ...projectErrors(trace.integrity.errors),
    ...projectErrors(history.integrity.errors),
    ...projectErrors(ownership.ownershipErrors),
  ];
  const checks = projectChecks(trace);
  const completion = projectCompletion(audit, ownership);
  const reasonCodes = projectReasonCodes(
    status.reasonCodes,
    audit.errors,
    trace.integrity.errors,
    ownership.reasonCodes,
    next.reasonCodes,
  );
  const auditStatus = safeIdentifier(audit.status) ?? "INVALID";
  const reportVerdict = safeIdentifier(report.verdict);
  const traceValid = trace.integrity.valid === true;
  const historyValid = history.integrity.valid === true;
  return {
    schemaVersion: AUDIT_UX_SCHEMA_VERSION,
    protocolVersion: trace.protocolVersion,
    taskId: trace.task.id,
    readOnly: true,
    authority: {
      readOnly: true,
      lifecycleAuthority: false,
      evidenceAuthority: false,
      completionAuthority: false,
      mutationAuthority: false,
      externalExecution: false,
    },
    health: {
      phase: safePhase(status.phase ?? trace.task.phase),
      protocolValid: status.protocol?.status === "VALID",
      auditStatus,
      reportVerdict,
      completionStatus: completion.valid ? "VALID" : "INCOMPLETE",
      ownershipValid: ownership.ownershipValid === true,
      claimState: safeIdentifier(ownership.claimState),
      mutationAllowed: ownership.mutationAllowed === true,
      recoveryStatus: safeIdentifier(ownership.recoveryStatus),
      currentNextAction: safeIdentifier(next.nextAction),
      historyQuality: safeIdentifier(history.historyQuality.level),
      traceIntegrity: traceValid,
      reasonCodes,
    },
    lifecycle: {
      phase: safePhase(trace.task.phase),
      status: safeIdentifier(trace.task.status),
      revision: Number.isInteger(trace.task.revision) ? trace.task.revision : null,
      verificationCycle: Number.isInteger(trace.task.verificationCycle) ? trace.task.verificationCycle : null,
      nextAction: safeIdentifier(next.nextAction),
      terminal: next.terminal === true,
    },
    timeline,
    verification: {
      checks,
      checkCount: trace.checks.length,
      totalAttempts: trace.checks.reduce((total, check) => total + check.attemptCount, 0),
      failedAttempts: trace.checks.reduce((total, check) => total + check.failedAttempts, 0),
      coverage: completion.coverage,
    },
    ownership: {
      claimState: safeIdentifier(ownership.claimState),
      ownershipValid: ownership.ownershipValid === true,
      mutationAllowed: ownership.mutationAllowed === true,
      recoveryStatus: safeIdentifier(ownership.recoveryStatus),
      historicalWriteClaims: ownership.historicalWriteClaims.slice(0, AUDIT_UX_LIMITS.maxActions).map(safeText).filter(Boolean),
      effectiveWriteClaims: ownership.effectiveWriteClaims.slice(0, AUDIT_UX_LIMITS.maxActions).map(safeText).filter(Boolean),
      reasonCodes: projectReasonCodes(ownership.reasonCodes, ownership.ownershipErrors),
    },
    diagnostics: projectDiagnostics(trace),
    completion,
    integrity: {
      valid: auditStatus === "VALID" && traceValid && historyValid,
      auditStatus,
      traceValid,
      historyValid,
      reasonCodes: projectReasonCodes(integrityErrors),
    },
    history: {
      quality: safeIdentifier(history.historyQuality.level),
      totalEventCount: history.summary.totalEventCount,
      returnedEventCount: timeline.items.length,
      truncated: timeline.truncated,
    },
    actions: {
      ...projectActions(trace.actions),
      bounded: trace.actions.total > AUDIT_UX_LIMITS.maxActions,
    },
    approvals: projectApprovals(approvals),
    recovery: {
      active: ownership.recoveryStatus === "RELEASED_BY_RECOVERY",
      status: safeIdentifier(ownership.recoveryStatus),
      events: trace.recovery.slice(0, AUDIT_UX_LIMITS.maxDiagnostics).map((event) => ({
        sequence: event.sequence,
        timestamp: typeof event.at === "string" ? event.at : null,
        kind: safeIdentifier(event.type),
      })),
    },
    links: {
      status: "task/status",
      ownership: "task/ownership",
      contract: "task/contract",
      auditView: "task/audit-view",
    },
  };
}

function normalizeOptions(options = {}) {
  const limit = options.limit === undefined ? 100 : options.limit;
  if (!Number.isInteger(limit) || limit < 1 || limit > AUDIT_UX_LIMITS.maxTimelineItems) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", `limit must be an integer between 1 and ${AUDIT_UX_LIMITS.maxTimelineItems}`);
  }
  for (const key of ["beforeSequence", "afterSequence"]) {
    if (options[key] !== undefined && (!Number.isInteger(options[key]) || options[key] < 0)) {
      throw auditUxError("E_AUDIT_UX_INPUT_INVALID", `${key} must be a non-negative integer`);
    }
  }
  if (options.beforeSequence !== undefined && options.afterSequence !== undefined) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "beforeSequence and afterSequence cannot be combined");
  }
  let categories = options.categories ?? [];
  if (typeof categories === "string") categories = categories.split(",").map((value) => value.trim()).filter(Boolean);
  if (!Array.isArray(categories) || categories.length > AUDIT_UX_CATEGORIES.length) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "categories must be a bounded array of category names");
  }
  const normalizedCategories = uniqueStrings(categories.map((value) => String(value).toUpperCase()));
  if (normalizedCategories.some((category) => !AUDIT_UX_CATEGORIES.includes(category))) {
    throw auditUxError("E_AUDIT_UX_INPUT_INVALID", "categories contains an unknown audit timeline category");
  }
  return {
    limit,
    beforeSequence: options.beforeSequence,
    afterSequence: options.afterSequence,
    categories: normalizedCategories,
  };
}

function projectTimeline(events, options) {
  const filtered = events
    .filter((event) => options.beforeSequence === undefined || event.sequence < options.beforeSequence)
    .filter((event) => options.afterSequence === undefined || event.sequence > options.afterSequence)
    .filter((event) => options.categories.length === 0 || options.categories.includes(categoryForEvent(event)))
    .sort((left, right) => left.sequence - right.sequence);
  const hasMore = filtered.length > options.limit;
  const page = hasMore && options.afterSequence === undefined
    ? filtered.slice(-options.limit)
    : filtered.slice(0, options.limit);
  const items = page.map(timelineItem);
  return {
    items,
    totalAvailable: filtered.length,
    truncated: hasMore,
    cursor: {
      beforeSequence: options.beforeSequence ?? null,
      afterSequence: options.afterSequence ?? null,
      nextBeforeSequence: hasMore && options.afterSequence === undefined ? items[0]?.sequence ?? null : null,
      nextAfterSequence: hasMore && options.afterSequence !== undefined ? items.at(-1)?.sequence ?? null : null,
    },
  };
}

async function evaluateLocalAttestation({ target, packageRoot, taskId, completion }) {
  const configured = completion.attestation ?? { mode: "off" };
  const base = {
    mode: configured.mode ?? "off",
    manifest: configured.mode === "off" ? "NOT_CHECKED" : configured.status === "CAPTURED" ? "VALID" : configured.status ?? "MISSING",
    statement: "NOT_CHECKED",
    signature: "NOT_CHECKED",
    coverage: "NOT_CHECKED",
    errors: [],
  };
  if (configured.mode === "off") return { ...base, status: "DISABLED" };
  if (configured.status !== "CAPTURED") {
    return { ...base, status: configured.status === "UNAVAILABLE" ? "UNAVAILABLE" : "MISSING" };
  }

  let manifest;
  try {
    manifest = await readCodeManifest({ target, packageRoot, taskId });
    await verifyCodeManifestContent({
      target,
      manifest: manifest.value,
      revisionProvider: manifest.value.capture.revisionProvider,
      revision: manifest.value.capture.mode === "WORKTREE" ? "WORKTREE" : manifest.value.capture.observedRevision,
    });
    base.coverage = "VALID";
  } catch (error) {
    base.manifest = "INVALID";
    base.status = "INVALID";
    base.errors.push({ code: error.code ?? "E_ATTESTATION_CONTENT_MISMATCH", message: error.message });
    return base;
  }

  try {
    const statement = await readAttestationStatement({ target, packageRoot, taskId });
    await validateAttestationStatement(statement.value, packageRoot);
    assertAttestationStatementBindings(statement.value, manifest.value, taskId, manifest.fingerprint);
    base.statement = "VALID";
  } catch (error) {
    if (error.code === "E_ATTESTATION_STATEMENT_MISSING") {
      return { ...base, status: "VALID" };
    }
    base.statement = "INVALID";
    base.status = "INVALID";
    base.errors.push({ code: error.code ?? "E_ATTESTATION_STATEMENT_INVALID", message: error.message });
    return base;
  }
  return { ...base, status: "VALID" };
}

function sortErrors(errors) {
  return [...errors].sort((left, right) => left.code.localeCompare(right.code)
    || left.message.localeCompare(right.message));
}

function assertBundledCodeManifestBindings({ loaded, ledger, taskId }) {
  const manifest = loaded.codeManifest;
  if (!manifest) return;
  const comparisons = [
    ["taskId", manifest.taskId, taskId, "E_BUNDLE_TASK_MISMATCH"],
    ["contractFingerprint", manifest.bindings.contractFingerprint, loaded.contract ? canonicalFingerprint(loaded.contract) : null, "E_ATTESTATION_CONTRACT_MISMATCH"],
    ["routeFingerprint", manifest.bindings.routeFingerprint, loaded.route ? canonicalFingerprint(loaded.route) : null, "E_ATTESTATION_ROUTE_MISMATCH"],
    ["stateFingerprint", manifest.bindings.stateFingerprint, loaded.state ? canonicalFingerprint(loaded.state) : null, "E_ATTESTATION_STATE_MISMATCH"],
    ["receiptFingerprint", manifest.bindings.receiptFingerprint, loaded.receipt ? canonicalFingerprint(loaded.receipt) : null, "E_ATTESTATION_RECEIPT_MISMATCH"],
  ];
  for (const [name, expected, actual, code] of comparisons) {
    if (expected !== actual) throw bundleBindingError(code, `Bundled code manifest binding does not match ${name}`);
  }
  if (!ledger?.valid) {
    throw bundleBindingError("E_ATTESTATION_LEDGER_MISMATCH", "A valid bundled event ledger is required by the code manifest");
  }
  const completion = ledger.events.findLast((event) => event.taskId === taskId && event.event === "COMPLETION_VALIDATED");
  if (!completion || completion.seq !== manifest.bindings.ledgerSeq || completion.hash !== manifest.bindings.ledgerHash) {
    throw bundleBindingError("E_ATTESTATION_LEDGER_MISMATCH", "Bundled code manifest does not match the COMPLETION_VALIDATED ledger checkpoint");
  }
}

function assertStructuralQualityBundleEvidence({ loaded, manifest, taskId }) {
  const quality = loaded.structuralQuality;
  if (!quality) return;
  const baseline = quality.baseline;
  const evaluations = quality.evaluations ?? [];
  const qualityArtifacts = new Map();
  if (baseline) qualityArtifacts.set("structural-quality/baseline.json", baseline);
  for (const evaluation of evaluations) {
    const name = `structural-quality/evaluations/cycle-${evaluation.verificationCycle}-attempt-${evaluation.attempt}.json`;
    qualityArtifacts.set(name, evaluation);
  }
  for (const value of [baseline, ...evaluations].filter(Boolean)) {
    if (value.taskId !== taskId) throw bundleBindingError("E_BUNDLE_TASK_MISMATCH", "Structural-quality artifact taskId does not match its bundle task");
    const bindingErrors = validateStructuralQualityBindings(value);
    if (bindingErrors.length > 0) throw bundleBindingError(bindingErrors[0].code, bindingErrors[0].message);
  }
  const baselineFingerprint = baseline ? canonicalFingerprint(baseline) : null;
  const bundledConfig = loaded.config?.structuralQuality;
  let policy = null;
  if (bundledConfig) policy = normalizeStructuralQualityConfig(bundledConfig);
  const expectedContractFingerprint = loaded.contract ? canonicalFingerprint(loaded.contract) : null;
  const expectedRouteFingerprint = loaded.route ? canonicalFingerprint(loaded.route) : null;
  for (const value of [baseline, ...evaluations].filter(Boolean)) {
    if (baselineFingerprint && value.role === "EVALUATION" && value.bindings?.baselineFingerprint !== baselineFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality evaluation does not bind the bundled baseline");
    }
    if (policy && value.bindings?.policyFingerprint !== structuralQualityPolicyFingerprint(policy)) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality artifact policy binding does not match bundled configuration");
    }
    if (expectedContractFingerprint && value.bindings?.contractFingerprint !== expectedContractFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality contract binding does not match the bundled contract");
    }
    if (expectedRouteFingerprint && value.bindings?.routeFingerprint !== expectedRouteFingerprint) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH", "Structural-quality route binding does not match the bundled route");
    }
  }
  const checks = [
    ...(loaded.state?.checks ?? []),
    ...(loaded.receipt?.checks ?? []),
  ].filter((check) => check?.kind === "structural-quality");
  for (const check of checks) {
    const bundleReference = bundleQualityReference(check.details?.artifactRef, taskId);
    const value = qualityArtifacts.get(bundleReference);
    if (!value) throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check references missing ${bundleReference}`);
    if (check.details?.artifactFingerprint !== canonicalFingerprint(value)) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check fingerprint does not match ${bundleReference}`);
    }
    const expected = structuralQualityCheckProjection(value);
    if (check.status !== expected.status || check.evidenceKind !== expected.evidenceKind) {
      throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality check does not match ${bundleReference}`);
    }
  }
  for (const artifact of manifest.artifacts.filter((item) => item.startsWith("structural-quality/"))) {
    if (!qualityArtifacts.has(artifact)) throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", `Bundled structural-quality manifest entry was not loaded: ${artifact}`);
  }
}

function bundleBindingError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function bundleDirectory(taskId) {
  return `${BUNDLE_ROOT}/${safeTaskId(taskId)}`;
}

async function bundleFileBinding(target, relativePath, name) {
  if (typeof name !== "string" || name.includes("\\") || name.includes("\u0000") || name.split("/").some(part => !part || part === "." || part === "..")) throw Object.assign(new Error("Invalid portable bundle artifact path"), { code: "E_BUNDLE_PATH_INVALID" });
  const filename = await assertSafePath(target, relativePath);
  const hash = createHash("sha256");
  let size = 0;
  for await (const bytes of createReadStream(filename)) { hash.update(bytes); size += bytes.length; }
  return { path: name, size, sha256: hash.digest("hex") };
}

function bundleQualityReference(reference, taskId) {
  if (typeof reference !== "string" || reference.trim() === "") {
    throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", "Structural-quality check has no artifact reference");
  }
  const normalized = reference.replaceAll("\\", "/");
  const sourceRoot = taskStructuralQualityDirectory(taskId).replaceAll("\\", "/");
  const suffix = normalized.startsWith(`${sourceRoot}/`)
    ? normalized.slice(sourceRoot.length + 1)
    : normalized.startsWith("structural-quality/")
      ? normalized.slice("structural-quality/".length)
      : null;
  if (!suffix || !(suffix === "baseline.json" || /^evaluations\/cycle-\d+-attempt-\d+\.json$/u.test(suffix))) {
    throw bundleBindingError("E_STRUCTURAL_QUALITY_EVIDENCE_STALE", "Structural-quality artifact reference escapes its task quality directory");
  }
  return `structural-quality/${suffix}`;
}

async function copyJson(target, sourcePath, destinationPath, schemaName, packageRoot, artifacts, relativeName) {
  try {
    const value = await readBundleSourceJson(target, sourcePath, schemaName, packageRoot);
    await writePortableJsonArtifact(target, destinationPath, value.value, schemaName, packageRoot);
    artifacts.push(relativeName);
    return value;
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return null;
    throw error;
  }
}

function safeTaskId(taskId) {
  if (typeof taskId !== "string" || !/^[A-Za-z0-9][A-Za-z0-9_-]*$/.test(taskId)) {
    const error = new Error(`Invalid task ID for bundle: ${taskId}`);
    error.code = "E_BUNDLE_PATH_INVALID";
    throw error;
  }
  return taskId;
}

function structuralQualityBundleKind(artifact) {
  if (artifact === "structural-quality/baseline.json") return "baseline";
  if (/^structural-quality\/evaluations\/cycle-\d+-attempt-\d+\.json$/u.test(artifact)) return "evaluation";
  if (artifact.startsWith("structural-quality/")) {
    throw bundleBindingError("E_BUNDLE_PATH_INVALID", `Unknown structural-quality bundle artifact: ${artifact}`);
  }
  return null;
}

function structuralQualityCheckProjection(value) {
  if (value.status === "PASS") return { status: "passed", evidenceKind: "OBSERVED" };
  if (value.status === "FAIL") return { status: "failed", evidenceKind: "OBSERVED" };
  if (value.status === "BLOCKED") return { status: "blocked", evidenceKind: "BLOCKED" };
  return { status: "not-run", evidenceKind: "NOT_VERIFIED" };
}

async function verifyBundleFileBindings(target, directory, manifest) {
  if (manifest.value.schemaVersion === 2) {
    const listed = manifest.value.files.map(file => file.path);
    if (new Set(listed).size !== listed.length || canonicalFingerprint([...listed].sort()) !== canonicalFingerprint([...manifest.value.artifacts].sort())) {
      throw Object.assign(new Error("Bundle file bindings disagree with included artifacts"), { code: "E_BUNDLE_DIGEST_INVALID" });
    }
    for (const binding of manifest.value.files) {
      const actual = await bundleFileBinding(target, `${directory}/${binding.path}`, binding.path);
      if (actual.size !== binding.size || actual.sha256 !== binding.sha256) throw Object.assign(new Error(`Bundle bytes disagree with manifest: ${binding.path}`), { code: "E_BUNDLE_DIGEST_INVALID" });
    }
  }
}

export function isTrustedHostAuthorityContext(authorityContext) {
  // Only a genuine host-controlled trust boundary may satisfy
  // REQUIRE_AUTHORITY. A project-local file, environment-selected source,
  // CLI flag, or transport session can never promote itself to HOST_ATTESTED.
  if (!authorityContext || typeof authorityContext !== "object") return false;
  if (authorityContext.trustMode !== "HOST_ATTESTED") return false;
  const source = typeof authorityContext.source === "string" ? authorityContext.source : "";
  const forbiddenSources = ["project-local-file", "environment", "cli-flag", "transport-session"];
  if (forbiddenSources.includes(source)) return false;
  return authorityContext.hostSupplied === true && source === "host-boundary";
}

export async function loadCapabilityPolicy(target, packageRoot) {
  const relativePath = PROJECT_ARTIFACT_PATHS.capabilityPolicy;
  await assertSafePath(target, relativePath);
  const absolutePath = ensureWithin(target, relativePath);
  if (!(await fileExists(absolutePath))) {
    return null;
  }
  let parsed;
  try {
    const { readFile } = await import("node:fs/promises");
    parsed = JSON.parse(await readFile(absolutePath, "utf8"));
  } catch (error) {
    throw policyError(E_POLICY_INVALID, `capability policy is not valid JSON: ${error.message}`);
  }
  for (const key of Object.keys(parsed ?? {})) {
    if (!ALLOWED_POLICY_PROPERTIES.has(key)) {
      throw policyError(
        E_POLICY_INVALID,
        `capability policy.${key} is not an allowed property; project-local policy can never declare authority or trust metadata`,
      );
    }
  }
  validateCapabilityPolicy(parsed);
  return {
    policy: parsed,
    fingerprint: canonicalFingerprint(parsed),
    path: relativePath,
  };
}

function policyError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export async function readCapabilityPolicyIdentity(target, packageRoot) {
  const loaded = await loadCapabilityPolicy(target, packageRoot);
  if (!loaded) {
    return {
      policy: null,
      fingerprint: null,
      digest: null,
    };
  }
  return {
    policy: loaded.policy,
    fingerprint: loaded.fingerprint,
    digest: `sha256:${sha256(canonicalFingerprint(loaded.policy))}`,
  };
}

export function assertCheckpointRevalidatedDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)
    || Object.keys(details).length !== REVALIDATION_DETAIL_KEYS.length
    || REVALIDATION_DETAIL_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(details, key))) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} requires its exact state-transition detail set`);
  }
  if (!CHECKPOINT_REVALIDATION_PHASES.includes(details.phase)) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.phase is unsupported`);
  }
  assertRepositoryFingerprint(details.previousRepositoryFingerprint, `${CHECKPOINT_REVALIDATED_EVENT} details.previousRepositoryFingerprint`);
  assertRepositoryFingerprint(details.repositoryFingerprint, `${CHECKPOINT_REVALIDATED_EVENT} details.repositoryFingerprint`, { requireHead: true });
  if (JSON.stringify(details.previousRepositoryFingerprint) === JSON.stringify(details.repositoryFingerprint)) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} must record repository drift`);
  }
  for (const key of ["contractFingerprint", "routeFingerprint", "previousStateFingerprint", "revalidatedStateFingerprint"]) {
    if (!isFingerprint(details[key])) throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  for (const key of ["previousStateRevision", "revalidatedStateRevision"]) {
    if (!Number.isInteger(details[key]) || details[key] < 0) {
      throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} details.${key} must be a non-negative integer`);
    }
  }
  if (details.revalidatedStateRevision !== details.previousStateRevision + 1) {
    throw invalid(`${CHECKPOINT_REVALIDATED_EVENT} state revisions must advance exactly once`);
  }
  return details;
}

export function assertRepositoryFingerprint(value, label = "repository fingerprint", { requireHead = false } = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)
    || Object.keys(value).length !== REPOSITORY_FINGERPRINT_KEYS.length
    || REPOSITORY_FINGERPRINT_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(value, key))) {
    throw invalid(`${label} must contain exactly branch and head`);
  }
  for (const key of REPOSITORY_FINGERPRINT_KEYS) {
    if (value[key] !== null && (typeof value[key] !== "string" || !value[key].trim())) {
      throw invalid(`${label}.${key} must be a non-empty string or null`);
    }
  }
  if (requireHead && typeof value.head !== "string") {
    throw invalid(`${label}.head must be available`);
  }
  return value;
}

export function assertCheck(value, label = "check", options = {}) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw checkError("E_CHECK_INVALID", `${label} must be an object`);
  }
  if (value.schemaVersion !== CHECK_SCHEMA_VERSION || value.protocolVersion !== PROTOCOL_VERSION) {
    throw checkError("E_CHECK_INVALID", `${label} has an unsupported protocol version`);
  }
  string(value.id, `${label}.id`);
  string(value.kind, `${label}.kind`);
  string(value.requirement, `${label}.requirement`);
  string(value.source, `${label}.source`);
  optionalString(value.executionRef, `${label}.executionRef`);
  if (value.provenance !== undefined && !CHECK_PROVENANCE.includes(value.provenance)) {
    throw checkError("E_CHECK_INVALID", `${label}.provenance must be one of ${CHECK_PROVENANCE.join(", ")}`);
  }
  if (options.requireCommandProvenance === true
    && value.kind === "command"
    && value.evidenceKind === "OBSERVED"
    && (value.executionRef === undefined || value.provenance !== "FORGELOOP_EXECUTED")) {
    throw checkError(
      "E_COMMAND_PROVENANCE_UNATTESTED",
      `${label} observed command evidence requires ForgeLoop execution provenance`,
    );
  }
  if (!CHECK_STATUSES.includes(value.status)) {
    throw checkError("E_CHECK_INVALID", `${label}.status must be one of ${CHECK_STATUSES.join(", ")}`);
  }
  if (!CHECK_EVIDENCE_KINDS.includes(value.evidenceKind)) {
    throw checkError("E_EVIDENCE_KIND_INVALID", `${label}.evidenceKind must be one of ${CHECK_EVIDENCE_KINDS.join(", ")}`);
  }
  if (value.exitCode !== undefined && (!Number.isInteger(value.exitCode) || value.exitCode < 0)) {
    throw checkError("E_CHECK_INVALID", `${label}.exitCode must be a non-negative integer`);
  }
  optionalString(value.timestamp, `${label}.timestamp`);
  if (value.status === "passed" && ["NOT_VERIFIED", "BLOCKED"].includes(value.evidenceKind)) {
    throw contradiction(`${label} passed cannot use ${value.evidenceKind} evidence`);
  }
  if (value.status === "passed" && value.exitCode !== undefined && value.exitCode !== 0) {
    throw contradiction(`${label} passed requires exitCode 0 when exitCode is recorded`);
  }
  if (value.status === "blocked" && value.evidenceKind !== "BLOCKED") {
    throw contradiction(`${label} blocked must use BLOCKED evidence`);
  }
  if (value.status === "not-run" && value.evidenceKind !== "NOT_VERIFIED") {
    throw contradiction(`${label} not-run must use NOT_VERIFIED evidence`);
  }
  if (value.status === "passed") {
    const auth = validateVerificationAuthority(value, options);
    if (!auth.valid) {
      throw checkError(auth.error.code, auth.error.message);
    }
  }
  assertCompoundStatus(value, label);
  return value;
}

function assertCompoundStatus(value, label) {
  const components = value.details?.components;
  if (!Array.isArray(components)) return;
  for (const [index, component] of components.entries()) {
    if (!component || typeof component !== "object" || Array.isArray(component)) {
      throw checkError("E_CHECK_INVALID", `${label}.details.components[${index}] must be an object`);
    }
    string(component.requirementId ?? component.requirement, `${label}.details.components[${index}].requirementId`);
    if (!CHECK_STATUSES.includes(component.status) || !CHECK_EVIDENCE_KINDS.includes(component.evidenceKind)) {
      throw checkError("E_CHECK_INVALID", `${label}.details.components[${index}] has invalid status or evidenceKind`);
    }
  }
  if (value.status === "passed" && components.some((component) => (
    component.status !== "passed" || component.evidenceKind !== "OBSERVED"
  ))) {
    throw contradiction(`${label} passed cannot contain an unverified, partial, blocked, or failed component`);
  }
}

function checkError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function contradiction(message) {
  return checkError("E_CHECK_STATUS_CONTRADICTION", message);
}

export function createCheck(input = {}, options = {}) {
  const check = {
    schemaVersion: CHECK_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    id: input.id,
    kind: input.kind,
    requirement: input.requirement,
    status: input.status ?? "not-run",
    evidenceKind: input.evidenceKind ?? "NOT_VERIFIED",
    source: input.source,
    ...(input.exitCode !== undefined ? { exitCode: input.exitCode } : {}),
    ...(input.timestamp !== undefined ? { timestamp: input.timestamp } : {}),
    ...(input.repositoryFingerprint !== undefined ? { repositoryFingerprint: input.repositoryFingerprint } : {}),
    ...(input.viewport !== undefined ? { viewport: structuredClone(input.viewport) } : {}),
    ...(input.executionRef !== undefined ? { executionRef: input.executionRef } : {}),
    ...(input.provenance !== undefined ? { provenance: input.provenance } : {}),
    ...(input.details !== undefined ? { details: structuredClone(input.details) } : {}),
  };
  return assertCheck(check, "check", options);
}

function optionalString(value, label) {
  if (value !== undefined) string(value, label);
}

function string(value, label) {
  if (typeof value !== "string" || value.trim() === "") {
    throw checkError("E_CHECK_INVALID", `${label} must be a non-empty string`);
  }
  return value;
}

function canonicalEntries(entries) {
  if (!Array.isArray(entries)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must be an array");
  const normalized = entries.map((entry, index) => {
    if (!entry || typeof entry !== "object" || Array.isArray(entry)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Manifest entry ${index} must be an object`);
    const item = {
      path: normalizedPath(entry.path, `entries[${index}].path`),
      ...(entry.sourcePath !== undefined ? { sourcePath: normalizedPath(entry.sourcePath, `entries[${index}].sourcePath`) } : {}),
      operation: entry.operation,
      kind: entry.kind,
      ...(entry.sha256 !== undefined ? { sha256: entry.sha256 } : {}),
      ...(entry.providerContentId !== undefined ? { providerContentId: entry.providerContentId } : {}),
      ...(entry.providerMetadata !== undefined ? { providerMetadata: entry.providerMetadata } : {}),
    };
    if (!OPERATIONS.has(item.operation) || !KINDS.has(item.kind)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Manifest entry ${index} has an unsupported operation or kind`);
    if (item.operation === "DELETED" && item.kind !== "DELETED") throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} must use kind DELETED`);
    if (item.kind === "DELETED" && item.operation !== "DELETED") throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} must use operation DELETED`);
    if (item.kind === "DELETED" && item.sha256 !== undefined) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Deleted entry ${item.path} cannot have sha256`);
    if (["FILE", "SYMLINK"].includes(item.kind) && !SHA256.test(item.sha256 ?? "")) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Entry ${item.path} requires a lowercase SHA-256 content digest`);
    if (item.kind === "GITLINK" && (typeof item.providerContentId !== "string" || !item.providerContentId)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Gitlink entry ${item.path} requires providerContentId`);
    if (item.providerMetadata !== undefined && (!item.providerMetadata || typeof item.providerMetadata !== "object" || Array.isArray(item.providerMetadata))) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Entry ${item.path} providerMetadata must be an object`);
    if (item.operation === "RENAMED" && !item.sourcePath) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `Renamed entry ${item.path} requires sourcePath`);
    return item;
  });
  const paths = normalized.map((entry) => entry.path);
  if (new Set(paths).size !== paths.length) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must not contain duplicate paths");
  const sorted = [...normalized].sort((left, right) => left.path.localeCompare(right.path));
  if (JSON.stringify(sorted) !== JSON.stringify(normalized)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest entries must be sorted by normalized path");
  return normalized;
}

export function codeManifestContentDigest(entries) {
  return canonicalFingerprint(entries.map((entry) => ({
    path: entry.path,
    sourcePath: entry.sourcePath ?? null,
    operation: entry.operation,
    kind: entry.kind,
    sha256: entry.sha256 ?? null,
    providerContentId: entry.providerContentId ?? null,
    providerMetadata: entry.providerMetadata ?? {},
  })));
}

async function completionCheckpoint(target, packageRoot, taskId, override = null) {
  if (override) {
    if (!Number.isInteger(override.seq) || override.seq < 1 || !SHA256.test(override.hash)) {
      throw manifestError("E_ATTESTATION_LEDGER_MISMATCH", "The candidate completion checkpoint is invalid");
    }
    return { seq: override.seq, hash: override.hash, ledger: null };
  }
  const ledger = await validateEventLedger(target, packageRoot, { taskId });
  const completion = ledger.events.findLast((event) => event.taskId === taskId && event.event === "COMPLETION_VALIDATED");
  if (!ledger.valid || !completion) throw manifestError("E_ATTESTATION_LEDGER_MISMATCH", "A valid COMPLETION_VALIDATED ledger checkpoint is required for a code manifest");
  return { seq: completion.seq, hash: completion.hash, ledger };
}

function digestBytes(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function manifestError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "CodeManifestError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function normalizedPath(value, label = "path") {
  if (typeof value !== "string" || !value || value.startsWith("/") || value === "." || value === ".." || value.startsWith("../")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must be a safe relative path`);
  }
  if (/[\u0000-\u001f\u007f]/u.test(value)) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} contains a control character`);
  }
  if (value.includes("\\")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must use forward slashes`);
  }
  const portable = value;
  const normalized = path.posix.normalize(portable).replace(/^\.\//u, "");
  if (!normalized || normalized === "." || normalized === ".." || normalized.startsWith("../") || normalized.startsWith(".forgeloop/")) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} is unsafe or reserved: ${value}`);
  }
  if (normalized !== portable) {
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", `${label} must use a normalized relative path: ${value}`);
  }
  return normalized;
}

export async function validateCodeManifest(manifest, packageRoot = getPackageRoot()) {
  try {
    assertSchema(manifest, await readSchema("code-manifest", packageRoot), "code manifest");
    const entries = canonicalEntries(manifest.entries);
    if (manifest.contentDigest !== codeManifestContentDigest(entries)) throw manifestError("E_ATTESTATION_MANIFEST_INVALID", "Manifest contentDigest does not match its entries");
    assertSecretFree(manifest);
    return { ...manifest, entries };
  } catch (error) {
    if (error.code === "E_ATTESTATION_MANIFEST_INVALID") throw error;
    throw manifestError("E_ATTESTATION_MANIFEST_INVALID", error.message);
  }
}

export function classifyCommandResolution(commandInput) {
  if (Array.isArray(commandInput)) {
    if (commandInput.length === 0 || commandInput.some((item) => typeof item !== "string" || item.trim() === "")) {
      return { resolutionMode: "UNKNOWN", mayInstall: false, installer: null, tool: null };
    }
    const binary = normalizeExecutableName(commandInput[0]);
    if (["sh", "bash", "zsh", "dash", "ksh"].includes(binary)) {
      const shellFlagIndex = commandInput.findIndex((item, index) => index > 0 && /^-.*c/.test(item));
      const shellCommand = shellFlagIndex >= 0 ? commandInput[shellFlagIndex + 1] : null;
      if (shellCommand) return classifyCommandResolution(shellCommand);
    }
    if (binary === "cmd") {
      const shellFlagIndex = commandInput.findIndex((item, index) => index > 0 && /^\/c$/iu.test(item));
      const shellCommand = shellFlagIndex >= 0 ? commandInput.slice(shellFlagIndex + 1).join(" ") : null;
      if (shellCommand) return classifyCommandResolution(shellCommand);
    }
    return classifySingleCommand(commandInput);
  }

  if (typeof commandInput !== "string" || commandInput.trim() === "") {
    return { resolutionMode: "UNKNOWN", mayInstall: false, installer: null, tool: null };
  }

  const subcommands = splitCommandPipeline(commandInput);
  for (const subcommand of subcommands) {
    const result = classifySingleCommand(subcommand);
    if (result.mayInstall) return result;
  }
  return classifySingleCommand(subcommands[0] || commandInput);
}

async function readPackageJsonIfPresent(cwd) {
  if (!cwd || typeof cwd !== "string") return null;
  try {
    const raw = await fs.readFile(path.resolve(cwd, "package.json"), "utf8");
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

export async function resolveExecutionResolution({ argv, cwd } = {}) {
  const direct = classifyCommandResolution(argv);
  if (direct.mayInstall && direct.resolutionMode !== "UNKNOWN") return direct;

  const npmInvocation = parseNpmInvocation(argv);
  const scriptName = getNpmScriptName(argv);
  if (scriptName && (npmInvocation.workspace || npmInvocation.workspaces)) {
    return {
      resolutionMode: "UNKNOWN",
      mayInstall: true,
      installer: "npm-workspace",
      tool: null,
      reason: "NPM_WORKSPACE_SCRIPT_UNRESOLVED",
      dispatch: { kind: "npm-workspace-script", scriptName },
    };
  }

  if (direct.mayInstall) return direct;
  if (!scriptName) return direct;

  const packageJson = await readPackageJsonIfPresent(cwd);
  if (!packageJson || typeof packageJson.scripts !== "object" || packageJson.scripts === null) return direct;

  const nestedRisk = await resolveNpmScriptRisk({ scriptName, packageJson });
  return nestedRisk?.mayInstall ? nestedRisk : direct;
}

async function resolveNpmScriptRisk({ scriptName, packageJson, visited = new Set(), depth = 0 } = {}) {
  if (depth > MAX_NPM_SCRIPT_DEPTH) {
    return { resolutionMode: "UNKNOWN", mayInstall: true, installer: "npm-script", tool: null, reason: "MAX_SCRIPT_DEPTH" };
  }
  if (visited.has(scriptName)) {
    return { resolutionMode: "UNKNOWN", mayInstall: true, installer: "npm-script", tool: null, reason: "SCRIPT_CYCLE" };
  }

  const nextVisited = new Set(visited);
  nextVisited.add(scriptName);
  const candidates = getNpmLifecycleCandidates({ scriptName, scripts: packageJson?.scripts ?? {} });
  for (const candidate of candidates) {
    const scriptBody = packageJson?.scripts?.[candidate];
    if (typeof scriptBody !== "string" || scriptBody.trim() === "") continue;

    const direct = classifyCommandResolution(scriptBody);
    if (direct.mayInstall) {
      return {
        resolutionMode: direct.resolutionMode,
        mayInstall: true,
        installer: direct.installer ?? "npm-script",
        tool: direct.tool,
        dispatch: { kind: "npm-script", scriptName: candidate },
      };
    }

    for (const subcommand of splitCommandPipeline(scriptBody)) {
      const nestedScriptName = getNpmScriptName(subcommand);
      if (!nestedScriptName) continue;
      const nested = await resolveNpmScriptRisk({
        scriptName: nestedScriptName,
        packageJson,
        visited: nextVisited,
        depth: depth + 1,
      });
      if (nested?.mayInstall) return nested;
    }
  }
  return null;
}

export function normalizeExecutableName(binaryToken) {
  const base = binaryToken.split(/[\\/]/u).pop() ?? binaryToken;
  return base.toLowerCase().replace(/\.(?:cmd|bat|exe)$/u, "");
}

export function splitCommandPipeline(commandString) {
  const parts = [];
  let current = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];
    const next = commandString[i + 1];

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
      current += char;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
      current += char;
    } else if (!inSingleQuote && !inDoubleQuote) {
      if ((char === "&" && next === "&") || (char === "|" && next === "|")) {
        if (current.trim().length > 0) parts.push(current.trim());
        current = "";
        i++;
      } else if (char === ";" || char === "|") {
        if (current.trim().length > 0) parts.push(current.trim());
        current = "";
      } else {
        current += char;
      }
    } else {
      current += char;
    }
  }

  if (current.trim().length > 0) parts.push(current.trim());
  return parts.length > 0 ? parts : [commandString];
}

export function tokenizeCommand(commandString) {
  const tokens = [];
  let current = "";
  let inSingleQuote = false;
  let inDoubleQuote = false;

  for (let i = 0; i < commandString.length; i++) {
    const char = commandString[i];

    if (char === "'" && !inDoubleQuote) {
      inSingleQuote = !inSingleQuote;
    } else if (char === '"' && !inSingleQuote) {
      inDoubleQuote = !inDoubleQuote;
    } else if (/\s/.test(char) && !inSingleQuote && !inDoubleQuote) {
      if (current.length > 0) {
        tokens.push(current);
        current = "";
      }
    } else {
      current += char;
    }
  }

  if (current.length > 0) tokens.push(current);
  return tokens;
}

export function unwrapCommandArgv(argv) {
  if (!Array.isArray(argv) || argv.length === 0) return null;
  let i = 0;
  while (i < argv.length && /^[A-Za-z_][A-Za-z0-9_]*=/.test(argv[i])) i++;
  if (i >= argv.length) return null;
  const binary = normalizeExecutableName(argv[i]);
  if (["sh", "bash", "zsh", "dash", "ksh"].includes(binary)) {
    const shellFlagIndex = argv.findIndex((item, index) => index > i && /^-.*c/.test(item));
    const shellCommand = shellFlagIndex >= 0 ? argv[shellFlagIndex + 1] : null;
    if (shellCommand) return tokenizeCommand(shellCommand);
  }
  if (binary === "cmd") {
    const shellFlagIndex = argv.findIndex((item, index) => index > i && /^\/c$/iu.test(item));
    const shellCommand = shellFlagIndex >= 0 ? argv.slice(shellFlagIndex + 1).join(" ") : null;
    if (shellCommand) return tokenizeCommand(shellCommand);
  }
  if (binary === "call") return argv.slice(i + 1);
  return argv.slice(i);
}

async function actionReceiptSummary(target, packageRoot, taskId) {
  const actions = await listActions(target, { packageRoot, taskId });
  return {
    count: actions.length,
    required: actions.filter((action) => action.requiredForCompletion).length,
    verified: actions.filter((action) => action.state === "VERIFIED").length,
    failed: actions.filter((action) => action.state === "FAILED").length,
    ambiguous: actions.filter((action) => action.state === "COMMIT_UNKNOWN").length,
    pending: actions.filter((action) => !["VERIFIED", "FAILED", "CANCELLED"].includes(action.state)).length,
    actionRefs: actions.map((action) => action.actionId),
  };
}

function appendUniqueEvidence(evidence, nextEvidence) {
  const exists = evidence.some((item) => item.kind === nextEvidence.kind
    && item.source === nextEvidence.source
    && item.result === nextEvidence.result
    && JSON.stringify(item.details ?? null) === JSON.stringify(nextEvidence.details ?? null));
  return exists ? [...evidence] : [...evidence, nextEvidence];
}

function artifactError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function commandProvenanceError(message = "Observed command evidence requires a ForgeLoop execution artifact") {
  return artifactError("E_COMMAND_PROVENANCE_UNATTESTED", message, [ARTIFACT_PATHS.receipt]);
}

function formatArgv(argv) {
  return argv.map((argument) => /[\s"']/u.test(argument)
    ? JSON.stringify(argument)
    : argument).join(" ");
}

function mergeByCheckId(checks, nextCheck) {
  const next = [...checks];
  const index = next.findIndex((item) => item?.schemaVersion === 1 && item.id === nextCheck.id);
  if (index >= 0) next[index] = nextCheck;
  else next.push(nextCheck);
  return next;
}

export async function requiredEvidenceForTarget({
  target,
  contract,
  route,
  packageRoot,
  additionalEvidence = [],
}) {
  const config = await readOptionalConfig(target, packageRoot);
  const guideEvidence = await completionEvidenceForGuides(route.value.guides, packageRoot);
  return [...new Set([
    ...(contract.value.successCriteria ?? []),
    ...guideEvidence,
    ...(config.requiredEvidence ?? []),
    ...(config.structuralQuality?.mode === "gate" ? [STRUCTURAL_QUALITY_REQUIREMENT] : []),
    ...additionalEvidence,
  ])].sort();
}

export async function validateCheckExecutionProvenance(check, {
  target,
  packageRoot,
  taskId,
  executionArtifacts,
  allowForeignCwd = false,
} = {}) {
  if (check?.kind !== "command" || check.evidenceKind !== "OBSERVED") return null;
  if (check.provenance !== "FORGELOOP_EXECUTED" || !check.executionRef) {
    throw commandProvenanceError();
  }
  const artifact = executionArtifacts
    ? { value: executionArtifacts[check.executionRef] }
    : await readExecutionArtifact({
      target,
      executionRef: check.executionRef,
      packageRoot,
      taskId,
    });
  if (!artifact.value) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution reference does not resolve to an execution artifact in this bundle",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  const execution = validateExecutionBinding({
    execution: artifact.value,
    taskId,
    checkId: check.id,
    requirement: check.requirement,
    verificationCycle: check.details?.verificationCycle ?? 1,
  });
  const protocolProjectRoot = execution.protocolProjectRoot ?? execution.cwd;
  if (
    execution.executionKind !== undefined
    && execution.executionKind !== "VERIFICATION"
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A command check must reference a verification execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (
    execution.executionIsolation !== undefined
    && execution.isolation?.mode !== execution.executionIsolation
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution artifact isolation mode does not match its isolation metadata",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (
    execution.isolation?.mode !== undefined
    && execution.isolation.mode !== "NATIVE_PROJECT"
    && path.resolve(execution.cwd) === path.resolve(protocolProjectRoot)
  ) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Isolated execution artifact cwd must be separate from the protocol project root",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (!allowForeignCwd && path.resolve(protocolProjectRoot) !== path.resolve(target)) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Execution artifact protocol project root does not match the current target",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.status === "passed" && (execution.status !== "passed" || execution.exitCode !== 0)) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A passed command check must reference a successful execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.status === "failed" && execution.status !== "failed") {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "A failed command check must reference a failed execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  if (check.exitCode !== undefined && check.exitCode !== execution.exitCode) {
    throw artifactError(
      "E_EXECUTION_REF_INVALID",
      "Check exitCode does not match its execution artifact",
      [taskId ? taskExecutionPath(taskId, check.executionRef) : ARTIFACT_PATHS.executionDirectory],
    );
  }
  return execution;
}

export async function validateChecksExecutionProvenance(checks, options) {
  const executions = [];
  for (const check of checks ?? []) {
    if (check.kind === "command" && check.evidenceKind === "OBSERVED") {
      const execution = await validateCheckExecutionProvenance(check, options);
      if (execution) executions.push(execution);
    }
  }
  return executions;
}

function validateRecordCheckInput({ id, kind = "command", requirement, status, evidenceKind, command, result, details, executionRef, provenance }) {
  requiredString(id, "check id");
  requiredString(kind, "check kind");
  requiredString(requirement, "check requirement");
  requiredString(status, "check status");
  requiredString(evidenceKind, "evidence kind");
  if (command !== undefined && typeof command !== "string") {
    throw artifactError("E_CHECK_INVALID", "command must be a string when supplied");
  }
  if (result !== undefined && typeof result !== "string") {
    throw artifactError("E_CHECK_INVALID", "result must be a string when supplied");
  }
  if (details !== undefined && (!details || typeof details !== "object" || Array.isArray(details))) {
    throw artifactError("E_CHECK_INVALID", "check details must be a JSON object");
  }
  if (executionRef !== undefined && (typeof executionRef !== "string" || executionRef.trim() === "")) {
    throw artifactError("E_EXECUTION_REF_INVALID", "executionRef must be a non-empty string when supplied");
  }
  if (provenance !== undefined && !CHECK_PROVENANCE.includes(provenance)) {
    throw artifactError("E_CHECK_INVALID", `provenance must be one of ${CHECK_PROVENANCE.join(", ")}`);
  }
  if ((typeof command !== "string" || command.trim() === "")
    && (typeof result !== "string" || result.trim() === "")) {
    throw artifactError("E_CHECK_INVALID", "record-check requires --command or --result");
  }
}

export async function authorizeCompletionRecoveryOrRebind({
  target,
  packageRoot,
  taskId = null,
  statePath = null,
  receiptPath = null,
  eventsPath = null,
  authorityContext,
  runtimeContext,
} = {}) {
  const statePathResolved = resolveArtifactPath("state", taskId, statePath);
  const receiptPathResolved = resolveArtifactPath("receipt", taskId, receiptPath);
  const resolveArtifacts = async () => {
    const state = await readWorkState(target, { packageRoot, taskId, statePath: statePathResolved });
    let receipt = null;
    try {
      receipt = (await readJsonArtifact(target, receiptPathResolved, "execution-receipt", packageRoot))?.value ?? null;
    } catch {
      receipt = null;
    }
    const events = (await validateEventLedger(target, packageRoot, { taskId, eventsPath })).events;
    return { state, receipt, events };
  };

  const initial = await resolveArtifacts();
  const recoveryAuth = validateCompletionRecoveryAuthorization(initial);
  if (recoveryAuth.authorized || !isFingerprintOnlyRecoveryMismatch(recoveryAuth.errors)) {
    return { ...initial, recoveryAuth, rebound: false };
  }

  const reboundResult = await rebindCompletionRejectionSnapshot({
    target,
    packageRoot,
    taskId,
    statePath,
    receiptPath,
    eventsPath,
    authorityContext,
    runtimeContext,
  });
  if (!reboundResult.rebound) {
    return { ...initial, recoveryAuth, rebound: false };
  }

  const rebounded = await resolveArtifacts();
  const reboundAuth = validateCompletionRecoveryAuthorization(rebounded);
  return { ...rebounded, recoveryAuth: reboundAuth, rebound: reboundAuth.authorized };
}

function findMatchingRejectionEvent(events, attempt, cycle) {
  let latestReviewIndex = -1;
  for (let index = 0; index < events.length; index += 1) {
    const event = events[index];
    if (event.event === "REVIEW_STARTED" && (event.details?.verificationCycle ?? 1) === cycle) {
      latestReviewIndex = index;
    }
  }
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (event.event !== "COMPLETION_REJECTED") continue;
    if ((event.details?.verificationCycle ?? 1) !== cycle) continue;
    if (index < latestReviewIndex) continue;
    return { event, index };
  }
  return null;
}

export function isFingerprintOnlyRecoveryMismatch(errors = []) {
  return Array.isArray(errors)
    && errors.length > 0
    && errors.every((error) => FINGERPRINT_MISMATCH_CODES.has(error?.code));
}

function sameSortedValues(left, right) {
  return JSON.stringify(sortedValues(left)) === JSON.stringify(sortedValues(right));
}

function sortedValues(values) {
  return [...new Set(values ?? [])].sort();
}

function addAssertion(errors, assertion, code, artifacts) {
  try {
    assertion();
  } catch (error) {
    errors.push(issue(code, error.message, artifacts));
  }
}

export function assertCompletionRelationships(input) {
  const errors = completionRelationshipErrors(input);
  if (errors.length === 0) return;
  const first = errors[0];
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  throw error;
}

export function assertStateIdentity(input) {
  const errors = stateIdentityErrors(input);
  if (errors.length === 0) return;
  const first = errors[0];
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  throw error;
}

export function completionRelationshipErrors({
  contract,
  route,
  state,
  receipt,
  requiredEvidence = [],
  requireReceiptStateFingerprint = true,
  requireRequiredChecks = true,
  target,
  taskId,
  authorities,
  authorityContext,
  runtimeContext,
} = {}) {
  const errors = stateIdentityErrors({ contract, route, state });
  const contractValue = contract?.value ?? contract;
  const contractFingerprint = contract?.fingerprint;
  const effectiveTaskId = taskId ?? contractValue?.taskId ?? state?.taskId ?? receipt?.taskId;
  const authOptions = {
    ...(target ? { target } : {}),
    ...(effectiveTaskId ? { taskId: effectiveTaskId } : {}),
    ...(authorities ? { authorities } : {}),
    ...(authorityContext ? { authorityContext } : {}),
    ...(runtimeContext ? { runtimeContext } : {}),
  };
  if (contractValue && receipt && contractValue.taskId !== receipt.taskId) {
    errors.push(issue("E_RECEIPT_TASK_MISMATCH", "Execution receipt does not belong to the current contract task", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.receipt]));
  }
  if (route && receipt && (receipt.routeFingerprint !== route.fingerprint || !sameValue(receipt.selectedGuides, route.value.guides))) {
    errors.push(issue("E_ROUTE_GUIDE_MISMATCH", "Execution receipt does not match the persisted route identity", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.receipt]));
  }
  if (contractFingerprint && receipt && receipt.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_RECEIPT_CONTRACT_MISMATCH", "Execution receipt does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.receipt]));
  }

  if (state) {
    addAssertion(errors, () => assertCheckList(state.checks, "work-state.checks", authOptions), "E_CHECK_INVALID", [ARTIFACT_PATHS.state]);
    addAssertion(errors, () => assertEvidenceList(state.verificationEvidence, "work-state.verificationEvidence"), "E_EVIDENCE_INVALID", [ARTIFACT_PATHS.state]);
    for (const check of state.checks ?? []) {
      if (check.status === "passed") {
        const auth = validateVerificationAuthority(check, authOptions);
        if (!auth.valid) {
          errors.push(issue(auth.error.code, auth.error.message, [ARTIFACT_PATHS.state]));
        }
      }
    }
  }
  if (receipt) {
    addAssertion(errors, () => assertCheckList(receipt.checks, "receipt.checks", authOptions), "E_CHECK_INVALID", [ARTIFACT_PATHS.receipt]);
    addAssertion(errors, () => assertEvidenceList(receipt.evidence ?? [], "receipt.evidence"), "E_EVIDENCE_INVALID", [ARTIFACT_PATHS.receipt]);
    for (const check of receipt.checks ?? []) {
      if (check.status === "passed") {
        const auth = validateVerificationAuthority(check, authOptions);
        if (!auth.valid) {
          errors.push(issue(auth.error.code, auth.error.message, [ARTIFACT_PATHS.receipt]));
        }
      }
    }
    if (requireRequiredChecks) {
      const readiness = evaluateRequiredEvidence({ requirements: requiredEvidence, checks: receipt.checks, options: authOptions });
      for (const requirement of readiness.missing) {
        errors.push(issue("E_EVIDENCE_REQUIRED", `Required check is missing: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
      for (const requirement of readiness.partial) {
        errors.push(issue("E_EVIDENCE_PARTIAL", `Required evidence is partial: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
      for (const requirement of readiness.invalid) {
        errors.push(issue(requirement.reasonCode ?? "E_EVIDENCE_INVALID", `Required evidence is invalid: ${requirement.text}`, [ARTIFACT_PATHS.receipt], { requirementId: requirement.id }));
      }
    }
  }

  const expectedCoverage = state ? coverageForRequirements(requiredEvidence, state.checks, {
    target,
    taskId: effectiveTaskId,
    authorities,
    options: authOptions,
  }) : [];
  if (state?.evidenceCoverage !== undefined) {
    addAssertion(errors, () => assertCoverageList(state.evidenceCoverage, "work-state.evidenceCoverage"), "E_EVIDENCE_COVERAGE_INVALID", [ARTIFACT_PATHS.state]);
    if (!sameValue(state.evidenceCoverage, expectedCoverage)) {
      errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Work state evidence coverage does not match its checks", [ARTIFACT_PATHS.state]));
    }
  }
  if (receipt) {
    if (receipt.evidenceCoverage === undefined) {
      errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Execution receipt requires evidence coverage", [ARTIFACT_PATHS.receipt]));
    } else {
      addAssertion(errors, () => assertCoverageList(receipt.evidenceCoverage, "receipt.evidenceCoverage"), "E_EVIDENCE_COVERAGE_INVALID", [ARTIFACT_PATHS.receipt]);
      if (!sameValue(receipt.evidenceCoverage, expectedCoverage)) {
        errors.push(issue("E_EVIDENCE_COVERAGE_INVALID", "Execution receipt evidence coverage does not match current checks", [ARTIFACT_PATHS.receipt]));
      }
    }
  }

  if (state && receipt) {
    if (state.verificationCycle !== undefined && receipt.verificationCycle !== undefined
      && state.verificationCycle !== receipt.verificationCycle) {
      errors.push(issue("E_RECEIPT_CYCLE_MISMATCH", "Work state and execution receipt verification cycles diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (requireReceiptStateFingerprint) {
      if (receipt.stateFingerprint === undefined) {
        errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Execution receipt requires the current work-state fingerprint", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
      } else if (receipt.stateFingerprint !== canonicalFingerprint(state)) {
        errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Execution receipt does not match the recorded work state", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
      }
    }
    if (!sameValue(state.checks, receipt.checks)) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt checks diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (!sameValue(state.verificationEvidence, receipt.evidence ?? [])) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt evidence diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
    if (state.evidenceCoverage !== undefined && receipt.evidenceCoverage !== undefined
      && !sameValue(state.evidenceCoverage, receipt.evidenceCoverage)) {
      errors.push(issue("E_RECEIPT_STATE_MISMATCH", "Work state and execution receipt coverage diverge", [ARTIFACT_PATHS.state, ARTIFACT_PATHS.receipt]));
    }
  }
  return errors;
}

function issue(code, message, artifacts = [], details = {}) {
  return { code, message, artifacts, ...details };
}

function sameValue(left, right) {
  return canonicalFingerprint(left) === canonicalFingerprint(right);
}

export function stateIdentityErrors({
  contract,
  route,
  state,
} = {}) {
  const errors = [];
  const contractValue = contract?.value ?? contract;
  const contractFingerprint = contract?.fingerprint;
  if (contractValue && state && contractValue.taskId !== state.taskId) {
    errors.push(issue("E_STATE_TASK_MISMATCH", "Work state does not belong to the current contract task", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.state]));
  }
  if (contractFingerprint && state && state.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_CONTRACT_STALE", "Work state does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.state]));
  }
  if (contractFingerprint && route && route.value.contractFingerprint !== contractFingerprint) {
    errors.push(issue("E_ROUTE_STALE", "Routing result does not match the current contract", [ARTIFACT_PATHS.contract, ARTIFACT_PATHS.route]));
  }
  if (route && state && route.value.contractFingerprint !== undefined
    && route.value.contractFingerprint !== state.contractFingerprint) {
    errors.push(issue("E_ROUTE_STALE", "Routing result does not match the work state contract", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.state]));
  }
  if (route && state && (state.routeFingerprint !== route.fingerprint || !sameValue(state.selectedGuides, route.value.guides))) {
    errors.push(issue("E_ROUTE_GUIDE_MISMATCH", "Work state does not match the persisted route identity", [ARTIFACT_PATHS.route, ARTIFACT_PATHS.state]));
  }
  return errors;
}

async function actionReceiptSummary(target, packageRoot, taskId) {
  const actions = await listActions(target, { packageRoot, taskId });
  const { evaluateRequiredActionReadiness } = await import("./action-readiness.js");
  const readiness = await evaluateRequiredActionReadiness({ target, packageRoot, taskId });
  return {
    count: actions.length,
    required: readiness.total,
    verified: actions.filter((action) => action.state === "VERIFIED").length,
    // Raw state counts are observability only; trusted completion is below.
    trustedSatisfied: readiness.satisfied,
    unresolvedRequired: readiness.unresolved,
    failed: actions.filter((action) => action.state === "FAILED").length,
    ambiguous: actions.filter((action) => action.state === "COMMIT_UNKNOWN").length,
    pending: actions.filter((action) => !["VERIFIED", "FAILED", "CANCELLED"].includes(action.state)).length,
    actionRefs: actions.map((action) => action.actionId),
  };
}

async function attestationConfiguration(target, packageRoot, errors) {
  try {
    const config = await readConfig(target, packageRoot);
    return {
      mode: config.attestation?.mode ?? "off",
      revisionProvider: config.attestation?.revisionProvider ?? "git",
      requireCompleteCoverage: config.attestation?.requireCompleteCoverage === true,
      signing: config.attestation?.signing ?? { provider: "none", required: false, policy: {} },
    };
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return { mode: "off", revisionProvider: "git", requireCompleteCoverage: false, signing: { provider: "none", required: false, policy: {} } };
    errors.push(issue(error.code ?? "E_ATTESTATION_INVALID", `Attestation configuration is invalid: ${error.message}`, [PROJECT_ARTIFACT_PATHS.config]));
    return { mode: "off", revisionProvider: "git", requireCompleteCoverage: false, signing: { provider: "none", required: false, policy: {} } };
  }
}

export function completionIdentityErrors({ contract, state, receipt } = {}) {
  return completionRelationshipErrors({ contract, state, receipt })
    .filter((error) => ["E_STATE_TASK_MISMATCH", "E_RECEIPT_TASK_MISMATCH"].includes(error.code));
}

export async function evaluateCompletion({
  target,
  packageRoot,
  strict = false,
  authorityContext,
  runtimeContext,
  taskId = null,
  contractPath = null,
  routePath = null,
  statePath = null,
  receiptPath = null,
  eventsPath = null,
  preflightPath = null,
} = {}) {
  const options = { target, packageRoot, strict, authorityContext, runtimeContext, taskId, contractPath, routePath, statePath, receiptPath, eventsPath, preflightPath };
  return withNativeReadScope(target, async () => evaluateSelectedCompletion(await resolveCompletionTaskOptions(options)));
}

function issue(code, message, artifacts = [], details = {}) {
  return { code, message, artifacts, ...details };
}

async function loadRequired(readArtifact, errorCode, errorMessage, artifacts, errors) {
  try {
    return await readArtifact();
  } catch (error) {
    if (errorCode === "E_RECEIPT_MISSING" && error.taskIdentityMismatch) {
      errors.push(receiptReadFailure(error, artifacts[0]));
      return null;
    }
    if (error.code === "ARTIFACT_MISSING") {
      errors.push(issue(errorCode, errorMessage, artifacts));
      return null;
    }
    errors.push(issue(error.code ?? errorCode, error.message ?? errorMessage, artifacts));
    return null;
  }
}

function publicationStatus(receipt) {
  if (receipt.publicationStatus) return receipt.publicationStatus;
  if (receipt.publication?.deployed) return "deployed";
  if (receipt.publication?.pushed) return "pushed";
  if (receipt.publication?.committed) return "committed";
  return receipt.changedPaths?.length > 0 ? "local-only" : "not-published";
}

export function receiptReadFailure(error, relativePath) {
  return error.taskIdentityMismatch
    ? issue("E_RECEIPT_TASK_MISMATCH", "Execution receipt does not belong to the current contract task", [relativePath])
    : issue("E_RECEIPT_INVALID", `Repair or remove the invalid execution receipt before continuing: ${error.message}`, [relativePath]);
}

function sortIssues(issues) {
  return issues
    .map(withRepairGuidance)
    .sort((a, b) => (a.code || "").localeCompare(b.code || "") || (a.message || "").localeCompare(b.message || ""));
}

export function validateTaskArtifactSet({
  route = null,
  state = null,
  stateClassification = null,
  receipt = null,
  taskBriefs = [],
  delegatedResults = [],
  events = [],
  continuity = null,
  continuityContext = {},
} = {}) {
  const errors = [];
  const incomplete = [];
  const continuityResult = evaluateContinuityConformance({ continuity, state, ...continuityContext });
  errors.push(...continuityResult.errors);

  addVersionErrors(route, "route", errors);
  addVersionErrors(state, "state", errors);
  addVersionErrors(receipt, "receipt", errors);
  for (const brief of taskBriefs) addVersionErrors(brief, `taskBrief:${brief?.taskId ?? "unknown"}`, errors);
  for (const result of delegatedResults) addVersionErrors(result, `delegatedResult:${result?.taskId ?? "unknown"}`, errors);

  if (route && state && route.protocolVersion !== state.protocolVersion) {
    errors.push(error("ROUTE_STATE_PROTOCOL_MISMATCH", "routing-result and work-state protocol versions differ", ["route", "state"]));
  }
  if (state && receipt && state.contractFingerprint !== receipt.contractFingerprint) {
    errors.push(error("STATE_RECEIPT_CONTRACT_MISMATCH", "work-state and execution-receipt contract fingerprints differ", ["state", "receipt"]));
  }
  if (state && receipt && state.taskId !== receipt.taskId) {
    errors.push(error("STATE_RECEIPT_TASK_MISMATCH", "work-state and execution-receipt task IDs differ", ["state", "receipt"]));
  }
  if (route && state && JSON.stringify(route.guides) !== JSON.stringify(state.selectedGuides)) {
    errors.push(error("ROUTE_STATE_GUIDES_MISMATCH", "work-state.selectedGuides must equal routing-result.guides", ["route", "state"]));
  }
  if (route && state && state.routeFingerprint !== undefined && state.routeFingerprint !== canonicalFingerprint(route)) {
    errors.push(error("ROUTE_STATE_FINGERPRINT_MISMATCH", "work-state.routeFingerprint must match routing-result", ["route", "state"]));
  }
  if (route && receipt && receipt.routeFingerprint !== undefined && receipt.routeFingerprint !== canonicalFingerprint(route)) {
    errors.push(error("STATE_RECEIPT_ROUTE_MISMATCH", "execution-receipt.routeFingerprint must match routing-result", ["route", "receipt"]));
  }
  if (state && receipt && JSON.stringify(state.selectedGuides) !== JSON.stringify(receipt.selectedGuides)) {
    errors.push(error("STATE_RECEIPT_GUIDES_MISMATCH", "execution-receipt.selectedGuides must equal work-state.selectedGuides", ["state", "receipt"]));
  }

  const delegationActive = delegationIsInScope({ state, receipt, events, taskBriefs, delegatedResults });
  const briefIds = new Set();
  for (const brief of taskBriefs) {
    if (!brief?.taskId) continue;
    if (briefIds.has(brief.taskId)) {
      errors.push(error("DUPLICATE_TASK_ID", `task brief ID is duplicated: ${brief.taskId}`, [`taskBrief:${brief.taskId}`]));
    }
    briefIds.add(brief.taskId);
    if (state && brief.parentTaskId !== state.taskId) {
      errors.push(error("TASK_PARENT_MISMATCH", `task brief ${brief.taskId} does not belong to ${state.taskId}`, [`taskBrief:${brief.taskId}`, "state"]));
    }
  }

  const delegatedIds = new Set();
  for (const result of delegatedResults) {
    if (!result?.taskId) continue;
    if (delegatedIds.has(result.taskId)) {
      errors.push(error("DUPLICATE_DELEGATED_RESULT", `delegated result is duplicated: ${result.taskId}`, [`delegatedResult:${result.taskId}`]));
    }
    delegatedIds.add(result.taskId);
    if (!briefIds.has(result.taskId)) {
      errors.push(error("UNKNOWN_DELEGATED_TASK", `delegated result has no corresponding task brief: ${result.taskId}`, [`delegatedResult:${result.taskId}`]));
    }
  }

  if (delegationActive) {
    if (taskBriefs.length > 0) {
      for (const taskId of [...briefIds].sort()) {
        if (!delegatedIds.has(taskId)) incomplete.push(`missing delegated result: ${taskId}`);
      }
    } else if (delegatedResults.length > 0) {
      incomplete.push("task briefs are required when delegated results are supplied");
    } else {
      incomplete.push("task briefs and delegated results were not supplied for delegated task");
    }
  }

  if (!route || !state || !receipt) incomplete.push("route, state, and receipt are all required for a complete artifact set");

  const sortedErrors = sortErrors(errors);
  let status = "VALID";
  if (sortedErrors.some((item) => item.code === "UNSUPPORTED_PROTOCOL_VERSION") || continuityResult.status === "INVALID") {
    status = "INVALID";
  } else if (sortedErrors.length > 0) {
    status = "INCONSISTENT";
  } else if (stateClassification?.status === "REVALIDATION_REQUIRED" || continuityResult.status === "STALE") {
    status = "STALE";
  } else if (incomplete.length > 0) {
    status = "INCOMPLETE";
  }

  const stale = status === "STALE"
    ? {
      reasons: [...(stateClassification?.reasons ?? [])],
      warnings: [...(stateClassification?.warnings ?? [])],
      repositoryComparison: stateClassification?.repositoryComparison ?? "NOT_VERIFIED",
      contractComparison: stateClassification?.contractComparison ?? "NOT_VERIFIED",
      artifactComparison: stateClassification?.artifactComparison ?? "NOT_APPLICABLE",
    }
    : null;

  const delegation = delegationActive
    ? {
      status: sortedErrors.some((e) => e.code.includes("DELEGAT") || e.code.includes("TASK"))
        ? "INCONSISTENT"
        : incomplete.some((i) => i.includes("delegat") || i.includes("brief"))
          ? "INCOMPLETE"
          : "VALID",
      required: true,
      errors: sortedErrors.filter((e) => e.code.includes("DELEGAT") || e.code.includes("TASK")),
    }
    : {
      status: "NOT_APPLICABLE",
      required: false,
      errors: [],
    };

  const evidenceKind = status === "VALID"
    ? "OBSERVED"
    : status === "INCOMPLETE"
      ? "NOT_VERIFIED"
      : status === "STALE"
        ? "INFERRED"
        : status === "INVALID"
          ? "BLOCKED"
          : "OBSERVED";
  return {
    status,
    errors: sortedErrors,
    incomplete: [...new Set(incomplete)].sort(),
    stale,
    delegation,
    continuity: continuityResult,
    evidence: [createEvidence({
      kind: evidenceKind,
      source: "ForgeLoop protocol conformance",
      result: status,
    })],
  };
}

export function contextBudget(profile = "balanced") {
  return CONTEXT_BUDGETS[profile] ?? CONTEXT_BUDGETS.balanced;
}

export function normalizeContextCandidate(input = {}) {
  const safe = buildDecisionState({
    id: input.id ?? null,
    sourceRef: input.sourceRef ?? null,
    kind: input.kind ?? "UNKNOWN",
    summary: input.summary ?? "",
    required: input.required === true,
    mandatory: input.mandatory === true,
    risk: input.risk ?? "NORMAL",
    trust: input.trust ?? "UNTRUSTED",
  });
  const summary = typeof safe.summary === "string" ? safe.summary : "";
  const id = typeof safe.id === "string" && safe.id ? safe.id : `candidate-${canonicalFingerprint(safe).slice(0, 16)}`;
  return {
    ...safe,
    id,
    summary,
    chars: summary.length,
    promptInjection: INJECTION_PATTERN.test(summary),
  };
}

export function normalizeContextCandidates(candidates = []) {
  const seen = new Set();
  const normalized = [];
  for (const candidate of candidates) {
    const value = normalizeContextCandidate(candidate);
    const identity = `${value.id}:${value.sourceRef ?? ""}`;
    if (seen.has(identity)) continue;
    seen.add(identity);
    normalized.push(value);
  }
  return normalized;
}

export function compileContext({ candidates = [], profile = "balanced", mandatoryIds = [], semanticRanker = null } = {}) {
  const policy = assertContextCompilerPolicy({ profile, mandatoryIds });
  const normalized = normalizeContextCandidates(candidates);
  const candidateSetFingerprint = canonicalFingerprint(normalized.map((candidate) => ({
    id: candidate.id,
    sourceRef: candidate.sourceRef,
    summary: candidate.summary,
    required: candidate.required,
    mandatory: candidate.mandatory,
  })));
  const mandatory = new Set(policy.mandatoryIds);
  const marked = normalized.map((candidate) => ({ ...candidate, mandatory: candidate.mandatory || mandatory.has(candidate.id) }));
  const semantic = typeof semanticRanker === "function" ? semanticRanker(marked.filter((item) => !item.promptInjection).map((item) => ({ id: item.id, summary: item.summary }))) : [];
  const rankedIds = Array.isArray(semantic) ? semantic : (semantic?.rankedIds ?? []);
  const excludedIds = new Set(Array.isArray(semantic) ? [] : (semantic?.excludedIds ?? []));
  const ordered = orderCandidates(marked, Array.isArray(rankedIds) ? rankedIds : []);
  const budget = contextBudget(profile);
  const selected = [];
  const omitted = [];
  let chars = 0;
  for (const candidate of ordered) {
    const mustKeep = candidate.mandatory || candidate.required;
    if (excludedIds.has(candidate.id) && !mustKeep) {
      omitted.push(candidate);
      continue;
    }
    const fits = selected.length < budget.maxItems && chars + candidate.chars <= budget.maxChars;
    if (fits || mustKeep) {
      selected.push(candidate);
      chars += candidate.chars;
    } else omitted.push(candidate);
  }
  const promptInjectionIds = marked.filter((item) => item.promptInjection).map((item) => item.id).sort();
  const result = contextPlanResult({
    profile,
    candidates: marked,
    selected,
    omitted,
    mandatoryIds: [...new Set([...policy.mandatoryIds, ...marked.filter((item) => item.mandatory).map((item) => item.id)])].sort(),
    promptInjectionIds,
    fingerprint: null,
    budget,
    candidateSetFingerprint,
  });
  result.decisionFingerprint = contextPlanFingerprint(result);
  return result;
}

function orderCandidates(candidates, rankedIds = []) {
  const ranks = new Map(rankedIds.map((id, index) => [id, rankedIds.length - index]));
  return [...candidates].sort((a, b) => (b.mandatory - a.mandatory)
    || (b.required - a.required)
    || ((ranks.get(b.id) ?? 0) - (ranks.get(a.id) ?? 0))
    || (candidatePriority(b) - candidatePriority(a))
    || a.id.localeCompare(b.id));
}

export function contextPlanFingerprint(plan) {
  return canonicalFingerprint({
    profile: plan.profile,
    selectedIds: plan.selected.map((item) => item.id),
    omittedIds: plan.omitted.map((item) => item.id),
    mandatoryIds: plan.mandatoryIds,
    promptInjectionIds: plan.promptInjectionIds,
  });
}

export function assertContextCompilerPolicy({ profile = "balanced", mandatoryIds = [] } = {}) {
  if (!["light", "balanced", "full"].includes(profile)) throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "Context compiler profile is invalid.");
  if (!Array.isArray(mandatoryIds) || mandatoryIds.some((id) => typeof id !== "string" || !id)) throw decisionError(DECISION_ERROR_CODES.POLICY_INVALID, "Context compiler mandatory IDs are invalid.");
  return { profile, mandatoryIds: [...new Set(mandatoryIds)] };
}

function finding(code, severity, field, itemId = null) {
  return { code, severity, field, itemId };
}

function hasOperationalHints(continuity) {
  return Boolean(
    continuity.currentFocus
    || continuity.remainingWork?.length
    || continuity.knownIssues?.length
    || continuity.changedAreas?.length
    || continuity.inspectFirst?.length
    || (typeof continuity.resumeNote === "string" && continuity.resumeNote.trim() !== ""),
  );
}

async function lintSelectedContinuity({ target, continuity, state } = {}) {
  const findings = [];
  if (!continuity || typeof continuity !== "object" || Array.isArray(continuity)) {
    return { status: "PASS", findings };
  }

  const completedSteps = new Set(
    Array.isArray(state?.completedSteps) ? state.completedSteps : [],
  );

  for (const [index, item] of (continuity.remainingWork ?? []).entries()) {
    if (!item?.id) continue;
    if (completedSteps.has(item.id)) {
      findings.push(finding(
        "CONTINUITY_REMAINING_ALREADY_COMPLETED",
        "WARN",
        `remainingWork[${index}]`,
        item.id,
      ));
    }
  }

  if (continuity.currentFocus?.id && completedSteps.has(continuity.currentFocus.id)) {
    findings.push(finding(
      "CONTINUITY_FOCUS_ALREADY_COMPLETED",
      "WARN",
      "currentFocus",
      continuity.currentFocus.id,
    ));
  }

  const knownIssueIds = new Set(
    (continuity.knownIssues ?? []).map((item) => item?.id).filter(Boolean),
  );
  for (const [index, item] of (continuity.remainingWork ?? []).entries()) {
    if (item?.id && knownIssueIds.has(item.id)) {
      findings.push(finding(
        "CONTINUITY_ITEM_ROLE_CONFLICT",
        "WARN",
        `remainingWork[${index}]`,
        item.id,
      ));
    }
  }

  if (typeof target === "string" && target.trim() !== "") {
    for (const [index, inspectPath] of (continuity.inspectFirst ?? []).entries()) {
      try {
        await assertSafePath(target, inspectPath);
        if (!(await inspectPathExists(target, inspectPath))) {
          findings.push(finding(
            "CONTINUITY_INSPECT_PATH_MISSING",
            "WARN",
            `inspectFirst[${index}]`,
          ));
        }
      } catch {
        // Invalid or unsafe paths are rejected by continuity schema validation;
        // lint never resolves an unchecked path or turns it into authority.
      }
    }
  }

  if (!hasOperationalHints(continuity)) {
    findings.push(finding("CONTINUITY_EMPTY_HINT_SET", "INFO", "continuity"));
  }

  return {
    status: findings.some((item) => item.severity === "WARN") ? "WARN" : "PASS",
    findings,
  };
}

export function continuityFinding(result) {
  if (continuityIsHealthy(result)) return null;
  const classification = result?.classification ?? "INVALID";
  const severity = classification === "RECONCILIATION_REQUIRED" ? "warning" : "error";
  return {
    code: `continuity-${classification.toLowerCase().replaceAll("_", "-")}`,
    severity,
    path: result?.path ?? ".forgeloop/continuity.json",
    message: result?.reasons?.join(", ") || `Continuity is ${classification}`,
    remediation: classification === "RECONCILIATION_REQUIRED"
      ? "Run forgeloop reconcile-continuity, inspect the current checkout, then record corrected continuity before advancing verification."
      : "Repair or clear continuity after reviewing the current work state and checkout.",
  };
}

export function continuityIsHealthy(result) {
  return HEALTHY.has(result?.classification ?? "ABSENT");
}

function baseResult(classification, overrides = {}) {
  return {
    classification,
    taskMatches: overrides.taskMatches ?? null,
    workStateMatches: overrides.workStateMatches ?? null,
    contractMatches: overrides.contractMatches ?? null,
    phaseMatches: overrides.phaseMatches ?? null,
    repositoryComparison: overrides.repositoryComparison ?? "NOT_VERIFIED",
    changedPathComparison: overrides.changedPathComparison ?? "NOT_VERIFIED",
    reasonCodes: uniqueSorted(overrides.reasonCodes ?? []),
    reasons: uniqueSorted(overrides.reasons ?? []),
    authority: "OPERATIONAL_CONTEXT_ONLY",
    evidenceAuthority: "NONE",
  };
}

export function classifyContinuity({
  continuity,
  state,
  contractFingerprint,
  repositoryFingerprint,
  changedPaths,
} = {}) {
  if (!continuity) {
    return baseResult("ABSENT", { reasons: ["CONTINUITY_ABSENT"] });
  }

  let value;
  try {
    value = assertContinuitySemantics(continuity);
  } catch (error) {
    return baseResult("INVALID", {
      reasonCodes: [error.code ?? "E_CONTINUITY_INVALID"],
      reasons: [error.message],
    });
  }

  if (!state || typeof state !== "object") {
    return baseResult("INCONSISTENT", {
      reasonCodes: ["E_CONTINUITY_STATE_MISSING"],
      reasons: ["CONTINUITY_STATE_MISSING"],
    });
  }

  if (state.phase === "COMPLETE") {
    return baseResult("NOT_APPLICABLE", {
      taskMatches: value.taskId === state.taskId,
      phaseMatches: value.phase === state.phase,
      reasons: ["CONTINUITY_NOT_APPLICABLE_AFTER_COMPLETE"],
    });
  }

  const taskMatches = value.taskId === state.taskId;
  const workStateMatches = value.workStateFingerprint === canonicalFingerprint(state);
  const expectedContract = contractFingerprint ?? state.contractFingerprint ?? null;
  const contractMatches = value.contractFingerprint === state.contractFingerprint
    && (expectedContract === null || value.contractFingerprint === expectedContract);
  const phaseMatches = value.phase === state.phase;
  const repositoryComparison = compareRepository(value.repositoryFingerprint, repositoryFingerprint);
  const changedPathComparison = compareChangedPaths(changedPaths, value.changedAreas);

  const inconsistentCodes = [];
  const inconsistentReasons = [];
  if (!taskMatches) {
    inconsistentCodes.push("E_CONTINUITY_TASK_MISMATCH");
    inconsistentReasons.push("CONTINUITY_TASK_MISMATCH");
  }
  if (!contractMatches) {
    inconsistentCodes.push("E_CONTINUITY_CONTRACT_MISMATCH");
    inconsistentReasons.push("CONTINUITY_CONTRACT_MISMATCH");
  }
  if (!phaseMatches && !phaseReachable(value.phase, state.phase)) {
    inconsistentCodes.push("E_CONTINUITY_PHASE_MISMATCH");
    inconsistentReasons.push("CONTINUITY_PHASE_MISMATCH");
  }
  if (inconsistentCodes.length > 0) {
    return baseResult("INCONSISTENT", {
      taskMatches,
      workStateMatches,
      contractMatches,
      phaseMatches,
      repositoryComparison,
      changedPathComparison,
      reasonCodes: inconsistentCodes,
      reasons: inconsistentReasons,
    });
  }

  const reconciliationReasons = [];
  if (!workStateMatches) reconciliationReasons.push("CONTINUITY_WORK_STATE_CHANGED");
  if (!phaseMatches) reconciliationReasons.push("CONTINUITY_PHASE_CHANGED");
  if (repositoryComparison === "MISMATCH") reconciliationReasons.push("CONTINUITY_REPOSITORY_CHANGED");
  if (["PARTIAL", "MISMATCH"].includes(changedPathComparison)) {
    reconciliationReasons.push("CONTINUITY_CHANGED_PATHS_DIFFER");
  }

  if (reconciliationReasons.length > 0) {
    return baseResult("RECONCILIATION_REQUIRED", {
      taskMatches,
      workStateMatches,
      contractMatches,
      phaseMatches,
      repositoryComparison,
      changedPathComparison,
      reasonCodes: [RECONCILIATION_CODE],
      reasons: reconciliationReasons,
    });
  }

  return baseResult("FRESH", {
    taskMatches,
    workStateMatches,
    contractMatches,
    phaseMatches,
    repositoryComparison,
    changedPathComparison,
  });
}

async function deriveDiagnosticContextSafe({ target, packageRoot, state }) {
  try {
    const [{ withEventLedgerAudit }, { deriveDiagnosticContext }] = await Promise.all([
      import("./events.js"),
      import("./reflection.js"),
    ]);
    return await withEventLedgerAudit(target, packageRoot, { taskId: state?.taskId ?? null }, audit => {
      if (!audit.valid) return { present: false };
      return { present: true, ...deriveDiagnosticContext(audit.events, state) };
    });
  } catch {
    return { present: false };
  }
}

export async function reconcileContinuity({ target, packageRoot, taskId = null } = {}) {
  const read = () => reconcileLoadedContinuity({ target, packageRoot, taskId });
  return withNativeReadScope(target, () => {
    if (getOperationalStore(target) && taskId) return withEventLedgerAudit(target, packageRoot, { taskId }, read);
    return read();
  });
}

async function resolveLatestHandoffSafe(target, { packageRoot, taskId } = {}) {
  if (!taskId) return null;
  try {
    const { resolveLatestHandoff } = await import("./handoff.js");
    return await resolveLatestHandoff(target, { packageRoot, taskId });
  } catch (error) {
    return {
      status: "INVALID",
      error: {
        code: error.code ?? "E_HANDOFF_INVALID",
        message: error.message,
      },
    };
  }
}

export function assertContinuitySemantics(input) {
  if (!input || typeof input !== "object" || Array.isArray(input)) {
    throw continuityError("E_CONTINUITY_INVALID", "Continuity must be a JSON object");
  }
  const unknownField = Object.keys(input).find((key) => !CONTINUITY_FIELDS.has(key));
  if (unknownField) {
    throw continuityError("E_CONTINUITY_INVALID", `Continuity contains unsupported field: ${unknownField}`);
  }
  if (input.schemaVersion !== CONTINUITY_SCHEMA_VERSION || input.protocolVersion !== PROTOCOL_VERSION) {
    throw continuityError("E_CONTINUITY_SCHEMA_UNSUPPORTED", "Unsupported continuity schema or protocol version");
  }
  if (!WORK_PHASES.includes(input.phase)) {
    throw continuityError("E_CONTINUITY_INVALID", `Unknown continuity phase: ${input.phase}`);
  }
  if (input.verificationCycle !== undefined
    && (!Number.isInteger(input.verificationCycle) || input.verificationCycle < 1)) {
    throw continuityError("E_CONTINUITY_INVALID", "verificationCycle must be a positive integer");
  }
  const normalized = {
    schemaVersion: CONTINUITY_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    taskId: nonEmptyString(input.taskId, "taskId", LIMITS.taskId),
    workStateFingerprint: fingerprint(input.workStateFingerprint, "workStateFingerprint"),
    contractFingerprint: fingerprint(input.contractFingerprint, "contractFingerprint"),
    phase: input.phase,
    ...(input.verificationCycle !== undefined ? { verificationCycle: input.verificationCycle } : {}),
    repositoryFingerprint: normalizeRepositoryFingerprint(input.repositoryFingerprint),
    updatedAt: nonEmptyString(input.updatedAt, "updatedAt", 128),
    ...(input.currentFocus !== undefined ? { currentFocus: normalizeWorkItem(input.currentFocus, "currentFocus") } : {}),
    remainingWork: normalizeWorkItems(input.remainingWork, "remainingWork", LIMITS.remainingWork),
    knownIssues: normalizeWorkItems(input.knownIssues, "knownIssues", LIMITS.knownIssues),
    changedAreas: normalizePaths(input.changedAreas, "changedAreas", LIMITS.changedAreas),
    inspectFirst: normalizePaths(input.inspectFirst, "inspectFirst", LIMITS.inspectFirst),
    ...(input.resumeNote !== undefined
      ? { resumeNote: nonEmptyString(input.resumeNote, "resumeNote", LIMITS.resumeNote) }
      : {}),
  };
  try {
    assertPortableContextSafe(normalized);
  } catch (error) {
    throw continuityError("E_CONTINUITY_INVALID", error.message);
  }
  return normalized;
}

function continuityError(code, message, artifacts = [CONTINUITY_PATH]) {
  const error = new Error(message);
  error.name = "ContinuityError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function createContinuity(input) {
  return assertContinuitySemantics({
    schemaVersion: input.schemaVersion ?? CONTINUITY_SCHEMA_VERSION,
    protocolVersion: input.protocolVersion ?? PROTOCOL_VERSION,
    ...structuredClone(input),
  });
}

export function assertContractBootstrapRepairDetails(details) {
  return assertContractBootstrapRepairDetailsInternal(details);
}

function assertContractBootstrapRepairDetailsInternal(details, { legacy = false } = {}) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    throw invalid("contract bootstrap repair requires structured details");
  }
  assertRepairDetailKeys(details, legacy);
  for (const key of [
    "taskId", "repairId", "defect", "contractCreateTransactionId", "repairedAt", "authorityKind",
  ]) {
    if (typeof details[key] !== "string" || !details[key].trim()) {
      throw invalid(`contract bootstrap repair details.${key} must be a non-empty string`);
    }
  }
  if (details.repairVersion !== CONTRACT_BOOTSTRAP_REPAIR_VERSION) {
    throw invalid("contract bootstrap repair details.repairVersion is unsupported");
  }
  if (!REPAIR_ID.test(details.repairId)) throw invalid("contract bootstrap repair details.repairId is invalid");
  if (details.defect !== CONTRACT_BOOTSTRAP_REPAIR_DEFECT) throw invalid("contract bootstrap repair details.defect is invalid");
  if (details.authorityKind !== CONTRACT_BOOTSTRAP_REPAIR_AUTHORITY) throw invalid("contract bootstrap repair details.authorityKind is invalid");
  for (const key of [
    "canonicalContractEventHash", "duplicateContractEventHash", "contractCreateCommitHash",
    "contractFingerprint", "reconstructedStateFingerprint",
  ]) {
    if (!isFingerprint(details[key])) throw invalid(`contract bootstrap repair details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  for (const key of ["canonicalContractEventSeq", "duplicateContractEventSeq", "contractCreateCommitSeq"]) {
    if (!Number.isInteger(details[key]) || details[key] < 1) throw invalid(`contract bootstrap repair details.${key} must be a positive integer`);
  }
  assertRepairDetailRevision(details, legacy);
  assertRepairDetailPhase(details);
  if (details.routeFingerprint !== null && !isFingerprint(details.routeFingerprint)) {
    throw invalid("contract bootstrap repair details.routeFingerprint must be a fingerprint or null");
  }
  if (details.previousStateFingerprint !== null && !isFingerprint(details.previousStateFingerprint)) {
    throw invalid("contract bootstrap repair details.previousStateFingerprint must be a fingerprint or null");
  }
  if (!Number.isFinite(Date.parse(details.repairedAt))) throw invalid("contract bootstrap repair details.repairedAt must be an ISO timestamp");
  return details;
}

export function assertLegacyContractBootstrapRepairDetails(details) {
  return assertContractBootstrapRepairDetailsInternal(details, { legacy: true });
}

function assertRepairDetailKeys(details, legacy) {
  const allowedKeys = legacy ? LEGACY_REPAIR_DETAIL_KEYS : REPAIR_DETAIL_KEYS;
  const unexpected = Object.keys(details).find((key) => !allowedKeys.has(key));
  if (unexpected) throw invalid(`contract bootstrap repair details contains unknown property: ${unexpected}`);
}

function assertRepairDetailPhase(details) {
  if (!["CONTRACT_READY", "ROUTED"].includes(details.reconstructedPhase)) {
    throw invalid("contract bootstrap repair details.reconstructedPhase is invalid");
  }
  if (details.reconstructedPhase === "ROUTED" && details.routeFingerprint === null) {
    throw invalid("ROUTED contract bootstrap repair requires routeFingerprint");
  }
}

function assertRepairDetailRevision(details, legacy) {
  if (!legacy && (!Number.isInteger(details.reconstructedStateRevision) || details.reconstructedStateRevision < 0)) {
    throw invalid("contract bootstrap repair details.reconstructedStateRevision must be a non-negative integer");
  }
}

function canonicalGuideList(value) {
  if (!Array.isArray(value) || value.some((guide) => typeof guide !== "string" || !guide)) return null;
  const guides = [...value].sort();
  return new Set(guides).size === guides.length ? guides : null;
}

export function contractBootstrapRepairId(details) {
  const identity = {
    taskId: details.taskId,
    defect: details.defect,
    canonicalContractEventSeq: details.canonicalContractEventSeq,
    canonicalContractEventHash: details.canonicalContractEventHash,
    duplicateContractEventSeq: details.duplicateContractEventSeq,
    duplicateContractEventHash: details.duplicateContractEventHash,
    contractCreateCommitSeq: details.contractCreateCommitSeq,
    contractCreateCommitHash: details.contractCreateCommitHash,
    contractCreateTransactionId: details.contractCreateTransactionId,
    contractFingerprint: details.contractFingerprint,
    reconstructedPhase: details.reconstructedPhase,
    routeFingerprint: details.routeFingerprint,
    reconstructedStateRevision: details.reconstructedStateRevision,
  };
  return `repair-${canonicalFingerprint(identity)}`;
}

export function eventHash(event) {
  const { hash, ...body } = event;
  return canonicalFingerprint(body);
}

function invalid(message) {
  const error = new Error(message);
  error.code = "E_EVENT_INVALID";
  return error;
}

function isCommitFor(event, operation) {
  return event?.event === "TRANSACTION_COMMITTED"
    && event.details?.operation === operation
    && typeof event.details?.transactionId === "string"
    && event.details.transactionId.length > 0;
}

export function isContractBootstrapRepairCandidate(events, ledgerErrors = [], taskId = null) {
  if (!isLedgerEventCollection(events) || events.length < 4) return null;
  const effectiveTaskId = taskId ?? ledgerEventAt(events, 0)?.taskId;
  if (typeof effectiveTaskId !== "string" || !effectiveTaskId) return null;
  if (events.some((event) => event.taskId !== effectiveTaskId)) return null;
  if (ledgerTypeSummary(events, CONTRACT_BOOTSTRAP_REPAIR_EVENT).count) return null;
  if (ledgerEventAt(events, 0)?.event !== "TASK_RECEIVED" || ledgerEventAt(events, 1)?.event !== "TRANSACTION_COMMITTED"
    || ledgerEventAt(events, 1)?.details?.operation !== "task-create") return null;
  if (!events.some((event) => event.event === "DISCOVERY_STARTED")) return null;
  const { count: contractCount, first: canonical, latest: duplicate } = ledgerTypeSummary(events, "CONTRACT_VALIDATED");
  if (contractCount !== 2) return null;
  if (!isFingerprint(canonical.details?.contractFingerprint)
    || canonical.details.contractFingerprint !== duplicate.details?.contractFingerprint) return null;
  if (canonical.hash !== eventHash(canonical) || duplicate.hash !== eventHash(duplicate)) return null;
  const canonicalIndex = events.indexOf(canonical);
  const duplicateIndex = events.indexOf(duplicate);
  const canonicalCommit = ledgerEventAt(events, canonicalIndex + 1);
  const duplicateCommit = ledgerEventAt(events, duplicateIndex + 1);
  if (!isCommitFor(canonicalCommit, "contract-create") || !isCommitFor(duplicateCommit, "contract-create")) return null;
  if (duplicateIndex !== events.length - 2 || !ledgerEventAtIs(events, events.length - 1, duplicateCommit)) return null;
  if (events.some((event) => HISTORICAL_EVENTS.has(event.event))) return null;
  if (!Array.isArray(ledgerErrors) || ledgerErrors.length < 1) return null;
  if (ledgerErrors.some((error) => !isExactDuplicateContractChronologyError(error))) return null;
  if (!ledgerErrors.some((error) => error.message === "lifecycle milestone must not repeat: CONTRACT_VALIDATED")) return null;
  return {
    taskId: effectiveTaskId,
    canonicalContractEvent: canonical,
    duplicateContractEvent: duplicate,
    canonicalContractCommit: canonicalCommit,
    duplicateContractCommit: duplicateCommit,
    contractFingerprint: canonical.details.contractFingerprint,
  };
}

export function isContractBootstrapRepairMarkerValid(events, marker) {
  try {
    if (!marker || marker.event !== CONTRACT_BOOTSTRAP_REPAIR_EVENT) return false;
    if (!resolveContractBootstrapRepairBoundary(events, marker)) return false;
    assertContractBootstrapRepairDetails(marker.details);
    if (marker.taskId !== marker.details.taskId || marker.hash !== eventHash(marker)) return false;
    if (marker.seq < 1 || !ledgerEventAtIs(events, marker.seq - 1, marker)) return false;
    const prefix = events.slice(0, marker.seq - 1);
    const prefixErrors = [];
    const candidate = isContractBootstrapRepairCandidate(prefix, prefixErrors, marker.taskId);
    if (!candidate) {
      const duplicateErrors = [
        { code: "E_PHASE_CHRONOLOGY_INVALID", message: "lifecycle milestone must not repeat: CONTRACT_VALIDATED" },
        { code: "E_PHASE_CHRONOLOGY_INVALID", message: "CONTRACT_VALIDATED is out of lifecycle order" },
      ];
      const recognized = isContractBootstrapRepairCandidate(prefix, duplicateErrors, marker.taskId);
      if (!recognized) return false;
      return isMarkerBound(marker, recognized);
    }
    return isMarkerBound(marker, candidate);
  } catch {
    return false;
  }
}

function isFingerprint(value) {
  return typeof value === "string" && FINGERPRINT.test(value);
}

export function isLegacyContractBootstrapRepairMarkerShape(event) {
  try {
    if (!event || event.event !== CONTRACT_BOOTSTRAP_REPAIR_EVENT) return false;
    assertLegacyContractBootstrapRepairDetails(event.details);
    if (typeof event.taskId !== "string" || !event.taskId
      || event.taskId !== event.details.taskId
      || !Number.isInteger(event.seq) || event.seq < 1
      || !isFingerprint(event.hash)
      || event.hash !== eventHash(event)
      || event.details.repairId !== legacyContractBootstrapRepairId(event.details)) return false;
    return true;
  } catch {
    return false;
  }
}

export function isLegacyContractBootstrapRepairMigrationCandidate(events, taskId = null) {
  if (!isLedgerEventCollection(events)) return null;
  const { count, first: marker } = ledgerTypeSummary(events, CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (count !== 1) return null;
  if (!isLegacyContractBootstrapRepairMarkerShape(marker)) return null;
  const effectiveTaskId = taskId ?? marker.taskId;
  if (marker.taskId !== effectiveTaskId || events.some((event) => event.taskId !== effectiveTaskId)) return null;
  if (ledgerTypeSummary(events, CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT).count) return null;
  const boundary = resolveContractBootstrapRepairBoundary(events, marker);
  if (!boundary || boundary.postRepairEvents.length > 0) return null;
  return { taskId: effectiveTaskId, marker, repairCommit: boundary.repairCommit };
}

function isMarkerBound(marker, candidate) {
  const details = marker.details;
  const expected = {
    taskId: candidate.taskId,
    defect: CONTRACT_BOOTSTRAP_REPAIR_DEFECT,
    canonicalContractEventSeq: candidate.canonicalContractEvent.seq,
    canonicalContractEventHash: candidate.canonicalContractEvent.hash,
    duplicateContractEventSeq: candidate.duplicateContractEvent.seq,
    duplicateContractEventHash: candidate.duplicateContractEvent.hash,
    contractCreateCommitSeq: candidate.duplicateContractCommit.seq,
    contractCreateCommitHash: candidate.duplicateContractCommit.hash,
    contractCreateTransactionId: candidate.duplicateContractCommit.details.transactionId,
    contractFingerprint: candidate.contractFingerprint,
  };
  for (const [key, value] of Object.entries(expected)) if (details[key] !== value) return false;
  if (details.repairId !== contractBootstrapRepairId(details)) return false;
  return true;
}

function isRepairTransactionCommit(event, taskId) {
  if (!event || event.taskId !== taskId || event.event !== "TRANSACTION_COMMITTED") return false;
  const details = event.details;
  return details && typeof details === "object" && !Array.isArray(details)
    && Object.keys(details).length === 2
    && typeof details.transactionId === "string" && details.transactionId.length > 0
    && details.operation === "task-repair-contract-bootstrap"
    && event.hash === eventHash(event);
}

export function legacyContractBootstrapRepairId(details) {
  const identity = {
    taskId: details.taskId,
    defect: details.defect,
    canonicalContractEventSeq: details.canonicalContractEventSeq,
    canonicalContractEventHash: details.canonicalContractEventHash,
    duplicateContractEventSeq: details.duplicateContractEventSeq,
    duplicateContractEventHash: details.duplicateContractEventHash,
    contractCreateCommitSeq: details.contractCreateCommitSeq,
    contractCreateCommitHash: details.contractCreateCommitHash,
    contractCreateTransactionId: details.contractCreateTransactionId,
    contractFingerprint: details.contractFingerprint,
    reconstructedPhase: details.reconstructedPhase,
    routeFingerprint: details.routeFingerprint,
  };
  return `repair-${canonicalFingerprint(identity)}`;
}

function migrationCommitFor(event, taskId) {
  return event?.event === "TRANSACTION_COMMITTED"
    && event.taskId === taskId
    && event.details?.operation === "task-migrate-contract-bootstrap-repair"
    && typeof event.details?.transactionId === "string"
    && event.details.transactionId.length > 0
    && event.hash === eventHash(event);
}

function migrationMatchesLegacyRepairBoundary({ migration, marker, repairCommit }) {
  const { details } = migration;
  const bindings = [
    [migration.taskId, marker.taskId],
    [details.taskId, marker.taskId],
    [details.legacyMarkerSeq, marker.seq],
    [details.legacyMarkerHash, marker.hash],
    [details.legacyRepairId, marker.details.repairId],
    [details.legacyRepairCommitSeq, repairCommit.seq],
    [details.legacyRepairCommitHash, repairCommit.hash],
    [details.legacyRepairTransactionId, repairCommit.details.transactionId],
    [details.contractFingerprint, marker.details.contractFingerprint],
    [details.reconstructedPhase, marker.details.reconstructedPhase],
    [details.routeFingerprint, marker.details.routeFingerprint],
    [details.reconstructedStateFingerprint, marker.details.reconstructedStateFingerprint],
  ];
  return bindings.every(([actual, expected]) => actual === expected);
}

export function resolveCanonicalPostRepairCheckpointBinding(events, marker) {
  const boundary = resolveContractBootstrapRepairBoundary(events, marker);
  if (!boundary) return null;
  const checkpointEvents = boundary.postRepairEvents.filter((event) => event.event === ROUTE_CHECKPOINT_BOUND_EVENT);
  if (checkpointEvents.length !== 1) return null;
  const checkpointEvent = checkpointEvents[0];
  const checkpointIndex = boundary.postRepairEvents.indexOf(checkpointEvent);
  const phaseEvent = ledgerEventAt(boundary.postRepairEvents, checkpointIndex + 1);
  const transactionCommit = ledgerEventAt(boundary.postRepairEvents, checkpointIndex + 2);
  const details = checkpointEvent.details;
  if (checkpointEvent.taskId !== boundary.marker.taskId
    || checkpointEvent.hash !== eventHash(checkpointEvent)
    || details?.contractFingerprint !== boundary.marker.details.contractFingerprint
    || !isFingerprint(details?.routeFingerprint)
    || canonicalGuideList(details?.selectedGuides) === null
    || !CHECKPOINT_PHASE_EVENTS.has(phaseEvent?.event)
    || phaseEvent.taskId !== boundary.marker.taskId
    || phaseEvent.hash !== eventHash(phaseEvent)
    || !isCommitFor(transactionCommit, "advance")
    || transactionCommit.taskId !== boundary.marker.taskId
    || transactionCommit.hash !== eventHash(transactionCommit)) {
    return null;
  }
  return {
    valid: true,
    checkpointEvent,
    phaseEvent,
    transactionCommit,
    routeFingerprint: details.routeFingerprint,
    contractFingerprint: details.contractFingerprint,
    selectedGuides: [...details.selectedGuides],
  };
}

export function resolveContractBootstrapRepairBoundary(events, marker = null) {
  if (!isLedgerEventCollection(events)) return null;
  const { count, first } = ledgerTypeSummary(events, CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (count !== 1) return null;
  const resolvedMarker = marker ?? first;
  const markerIndex = events.indexOf(resolvedMarker);
  if (markerIndex < 0 || resolvedMarker.seq !== markerIndex + 1) return null;
  const repairCommit = ledgerEventAt(events, markerIndex + 1);
  if (!isRepairTransactionCommit(repairCommit, resolvedMarker.taskId)
    || repairCommit.seq !== resolvedMarker.seq + 1) return null;
  return {
    marker: resolvedMarker,
    markerIndex,
    repairCommit,
    repairCommitIndex: markerIndex + 1,
    postRepairEvents: events.slice(markerIndex + 2),
  };
}

function resolveContractBootstrapRepairMigration(events, migration) {
  if (!isLedgerEventCollection(events) || !migration || migration.event !== CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT) return null;
  const marker = events.find((event) => event.seq === migration.details?.legacyMarkerSeq);
  const markerIndex = marker ? events.indexOf(marker) : -1;
  const migrationIndex = events.indexOf(migration);
  const commit = ledgerEventAt(events, migrationIndex + 1);
  const boundary = marker ? resolveContractBootstrapRepairBoundary(events, marker) : null;
  if (!marker || !isLegacyContractBootstrapRepairMarkerShape(marker)
    || markerIndex < 0 || !boundary
    || migrationIndex < 0 || migration.seq !== migrationIndex + 1
    || migration.seq <= marker.seq
    || !migrationMatchesLegacyRepairBoundary({ migration, marker, repairCommit: boundary.repairCommit })
    || !migrationCommitFor(commit, migration.taskId)
    || commit.seq !== migration.seq + 1) return null;
  return { marker, migration, migrationCommit: commit };
}

export function resolveEffectiveContractBootstrapRepairAnchor(events) {
  if (!isLedgerEventCollection(events)) return null;
  const { count, first: sourceMarker } = ledgerTypeSummary(events, CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (count !== 1) return null;
  if (isContractBootstrapRepairMarkerValid(events, sourceMarker)) {
    return { kind: "MODERN", sourceMarker, details: sourceMarker.details };
  }
  if (!isLegacyContractBootstrapRepairMarkerShape(sourceMarker)) return null;
  const migration = events
    .filter((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_EVENT)
    .find((event) => event.details?.legacyMarkerSeq === sourceMarker.seq);
  const binding = resolveContractBootstrapRepairMigration(events, migration);
  if (!binding) return null;
  return {
    kind: "MIGRATED_LEGACY",
    sourceMarker,
    migrationEvent: migration,
    details: {
      ...sourceMarker.details,
      reconstructedStateRevision: migration.details.reconstructedStateRevision,
    },
  };
}

export function sameCanonicalGuideList(left, right) {
  const a = canonicalGuideList(left);
  const b = canonicalGuideList(right);
  return a !== null && b !== null && a.length === b.length && a.every((guide, index) => guide === b[index]);
}

export function createPresetContract({ taskId, preset, claims = [] } = {}) {
  if (!Object.prototype.hasOwnProperty.call(PRESET_DEFINITIONS, preset)) {
    const error = new Error(`Unknown contract preset: ${preset}. Expected one of ${CONTRACT_PRESET_IDS.join(", ")}`);
    error.code = "E_CONTRACT_PRESET_UNKNOWN";
    throw error;
  }
  const definition = PRESET_DEFINITIONS[preset];
  const confirmedClaims = normalizedClaims(claims);
  const unresolvedDecisions = confirmedClaims.length > 0
    ? []
    : ["Confirm the concrete deliverables and affected behavior before implementation."];
  return createContract({
    taskId,
    objective: definition.objective,
    deliverables: confirmedClaims.length > 0 ? confirmedClaims : ["Deliverables confirmed by task scope."],
    constraints: definition.constraints,
    risks: definition.risks,
    verification: definition.verification,
    successCriteria: definition.successCriteria,
    stopConditions: definition.stopConditions,
    unresolvedDecisions,
    sourceRefs: [`contract-preset:${preset}`],
  });
}

export function assertContractRevisedDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)
    || Object.keys(details).length !== REVISION_DETAIL_KEYS.length
    || REVISION_DETAIL_KEYS.some((key) => !Object.prototype.hasOwnProperty.call(details, key))) {
    throw invalid(`${CONTRACT_REVISED_EVENT} requires its exact contract-transition detail set`);
  }
  for (const key of ["previousContractFingerprint", "contractFingerprint", "previousStateFingerprint", "revisedStateFingerprint"]) {
    if (!isFingerprint(details[key])) throw invalid(`${CONTRACT_REVISED_EVENT} details.${key} must be a lowercase SHA-256 fingerprint`);
  }
  if (details.previousContractFingerprint === details.contractFingerprint) {
    throw invalid(`${CONTRACT_REVISED_EVENT} must change the contract fingerprint`);
  }
  if (!REVISION_PHASES.has(details.previousPhase) || !REVISION_PHASES.has(details.phase)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} details phase is unsupported`);
  }
  const expectedPhase = details.previousPhase === "PLANNED" ? "ROUTED" : details.previousPhase;
  if (details.phase !== expectedPhase) {
    throw invalid(`${CONTRACT_REVISED_EVENT} phase transition is invalid: ${details.previousPhase} -> ${details.phase}`);
  }
  for (const key of ["previousStateRevision", "revisedStateRevision"]) {
    if (!Number.isInteger(details[key]) || details[key] < 0) {
      throw invalid(`${CONTRACT_REVISED_EVENT} details.${key} must be a non-negative integer`);
    }
  }
  if (details.revisedStateRevision !== details.previousStateRevision + 1) {
    throw invalid(`${CONTRACT_REVISED_EVENT} state revisions must advance exactly once`);
  }
  if (details.previousRouteFingerprint !== null && !isFingerprint(details.previousRouteFingerprint)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} details.previousRouteFingerprint must be a fingerprint or null`);
  }
  if (details.previousPhase === "CONTRACT_READY" && details.previousRouteFingerprint !== null) {
    throw invalid(`${CONTRACT_REVISED_EVENT} CONTRACT_READY revisions cannot have a route fingerprint`);
  }
  if (details.previousPhase !== "CONTRACT_READY" && !isFingerprint(details.previousRouteFingerprint)) {
    throw invalid(`${CONTRACT_REVISED_EVENT} routed revisions require the previous route fingerprint`);
  }
  return details;
}

export function assertAssumptions(value, label = "Contract assumptions") {
  if (!Array.isArray(value)) {
    throw new Error(`${label} must be an array`);
  }
  value.forEach((item, index) => {
    assertAssumptionObject(item, `${label}[${index}]`);
  });
  return value;
}

function assertRequirementArray(value, label, seenIds) {
  if (!Array.isArray(value)) {
    throw new Error(`${label} must be an array`);
  }
  value.forEach((item, index) => {
    assertRequirementItem(item, `${label}[${index}]`, seenIds);
  });
}

function assertStringArray(value, label) {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string" || item.trim() === "")) {
    throw new Error(`${label} must be an array of non-empty strings`);
  }
}

export function contractFingerprint(contract) {
  return canonicalFingerprint(contract);
}

export async function validateContract(contract, packageRoot) {
  assertSecretFree(contract);
  assertAssumptions(contract.assumptions ?? []);
  const seenIds = new Set();
  for (const field of CONTRACT_STRING_ARRAY_FIELDS) {
    assertStringArray(contract[field] ?? [], `Contract ${field}`);
  }
  for (const field of CONTRACT_REQUIREMENT_FIELDS) {
    assertRequirementArray(contract[field] ?? [], `Contract ${field}`, seenIds);
  }
  const schema = await readSchema("current-contract", packageRoot);
  assertSchema(contract, schema, "current contract");
  return contract;
}

export function assertCoverageList(value, label = "evidenceCoverage") {
  if (!Array.isArray(value)) throw coverageError("E_EVIDENCE_COVERAGE_INVALID", `${label} must be an array`);
  value.forEach((item, index) => assertCoverage(item, `${label}[${index}]`));
  return value;
}

function coverageError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function coverageForRequirements(requirements, checks, {
  blockedIds = [],
  target,
  taskId,
  authorities,
  options = {},
} = {}) {
  const normalizedRequirements = normalizeRequirements(requirements ?? []);
  const normalizedChecks = Array.isArray(checks) ? checks : [];
  const readiness = evaluateRequiredEvidence({
    requirements: normalizedRequirements,
    checks: normalizedChecks,
    target,
    taskId,
    authorities,
    options,
  });
  const covered = new Set(readiness.covered.map((item) => item.id));
  const partial = new Set(readiness.partial.map((item) => item.id));
  const invalid = new Set(readiness.invalid.map((item) => item.id));
  const blocked = new Set(blockedIds);
  return normalizedRequirements.filter((requirement) => !requirement.terminalOwned).map((requirement) => createCoverage({
    requirement: requirement.text,
    requiredEvidence: [requirement.text],
    observedEvidence: covered.has(requirement.id) ? [requirement.text] : [],
    blocked: blocked.has(requirement.text) || blocked.has(requirement.id),
    ...(partial.has(requirement.id) || invalid.has(requirement.id) ? {
      status: "PARTIAL",
      details: { requirementId: requirement.id, readinessStatus: "PARTIAL" },
    } : {}),
  }));
}

export function decisionArtifactFingerprint(artifact) {
  return canonicalFingerprint(artifact);
}

export function decisionError(code, message, artifacts = []) {
  return new DecisionError(code, message, artifacts);
}

export function decisionEventDetails(artifact) {
  return {
    decisionId: artifact.decisionId,
    decisionKind: artifact.decisionKind,
    artifactFingerprint: canonicalFingerprint(artifact),
    questionSetFingerprint: artifact.questionSetFingerprint,
    stateFingerprint: artifact.stateFingerprint,
