export async function validateSemanticDecisionArtifactBindings(target, packageRoot, events = [], { reader = readDecisionArtifact } = {}) {
  const errors = [];
  for (const event of ledgerEventsOfTypes(events, [SEMANTIC_DECISION_RECORDED_EVENT])) {
    if (event.event !== SEMANTIC_DECISION_RECORDED_EVENT) continue;
    try {
      const artifact = (await reader(target, event.taskId, event.details.decisionId, packageRoot)).value;
      if (artifact.taskId !== event.taskId
        || artifact.decisionId !== event.details.decisionId
        || canonicalFingerprint(artifact) !== event.details.artifactFingerprint
        || artifact.questionSetFingerprint !== event.details.questionSetFingerprint
        || artifact.stateFingerprint !== event.details.stateFingerprint
        || artifact.model !== event.details.model) {
        errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} does not match its immutable semantic decision artifact` });
      }
    } catch (error) {
      if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
      errors.push({ code: DECISION_ERROR_CODES.LEDGER_INVALID, message: `event ${event.seq} semantic decision artifact is unavailable or invalid` });
    }
  }
  return errors;
}

export function buildContextQuestionSet(candidates = []) {
  const bounded = candidates.slice(0, 64);
  const questions = Object.fromEntries(bounded.map((candidate, index) => [
    `candidate_${index}_relevant`, {
      type: "noul",
      criteria: { yes: `Candidate ${candidate.id} is relevant to the bounded task context`, no: `Candidate ${candidate.id} is not relevant to the bounded task context` },
    },
  ]));
  return buildDynamicQuestionSet({
    id: "context-candidates-v1", decisionKind: "CONTEXT_PLAN", questions,
    candidateIds: bounded.map((candidate) => candidate.id),
    metadata: { candidateQuestionPrefix: "candidate_", relevanceSuffix: "_relevant" },
  });
}

export function buildDynamicQuestionSet({ id, version = 1, decisionKind, questions, candidateIds = [], metadata = {} } = {}) {
  if (typeof id !== "string" || !id || !Number.isInteger(version) || version < 1
    || typeof decisionKind !== "string" || !questions || typeof questions !== "object"
    || Array.isArray(questions)) {
    throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Dynamic semantic question set is invalid.");
  }
  const names = Object.keys(questions);
  if (names.length === 0 || names.length > 128 || names.some((name) => !/^[a-z][a-z0-9_]{0,95}$/.test(name))) {
    throw decisionError(DECISION_ERROR_CODES.REQUEST_INVALID, "Dynamic semantic question set has invalid bounded questions.");
  }
  return freezeQuestionSet({ id, version, decisionKind, questions, candidateIds: [...candidateIds].slice(0, 64), metadata });
}

export function buildTestUtilityQuestionSet(tests = []) {
  const dimensions = ["unique_semantic_intent", "semantic_duplicate", "likely_obsolete", "likely_flaky_low_signal", "expensive_relative_to_signal", "documentation_value", "integration_value", "guards_regression_prone_behavior", "requires_system_two_review"];
  const bounded = tests.slice(0, 16);
  const questions = {};
  for (let index = 0; index < bounded.length; index += 1) {
    for (const dimension of dimensions) questions[`test_${index}_${dimension}`] = {
      type: "noul", criteria: { yes: `${dimension} applies to test ${bounded[index].testId}`, no: `${dimension} does not apply to test ${bounded[index].testId}` },
    };
  }
  return buildDynamicQuestionSet({
    id: "test-utility-candidates-v1", decisionKind: "TEST_UTILITY", questions,
    candidateIds: bounded.map((test) => test.testId),
    metadata: { dimensions, candidateQuestionPrefix: "test_", testCount: bounded.length },
  });
}

function freezeQuestionSet(definition) {
  return Object.freeze({
    ...definition,
    questions: Object.freeze({ ...definition.questions }),
    fingerprint: canonicalFingerprint(definition.questions),
  });
}

export function assertRequiredFreshDecision({ artifact, currentBindings = {}, expectedDecisionKind, expectedTaskId, expectedQuestionSetId, ledger = [] } = {}) {
  assertCanonicalArtifact(artifact, { expectedDecisionKind, expectedTaskId, expectedQuestionSetId });
  if (!Array.isArray(ledger)) throw invalid("Semantic decision ledger is unavailable.", DECISION_ERROR_CODES.LEDGER_INVALID);
  const record = decisionRecordForArtifact(ledger, artifact);
  if (!record || record.details.artifactFingerprint !== canonicalFingerprint(artifact)) {
    throw invalid("Semantic decision has no matching canonical ledger record.", DECISION_ERROR_CODES.LEDGER_INVALID);
  }
  if (isSuperseded(ledger, artifact)) throw decisionError(DECISION_ERROR_CODES.STALE, "Semantic decision has been superseded.");
  assertDecisionFresh(artifact, {
    ...currentBindings,
    model: PINNED_JEV_MODEL,
    policyFingerprint: currentBindings.policyFingerprint ?? artifact.policyFingerprint,
  });
  return artifact;
}

function isSuperseded(events, artifact) {
  return events.some((event) => event.event === SEMANTIC_DECISION_SUPERSEDED_EVENT
    && event.taskId === artifact.taskId
    && event.details?.decisionId === artifact.decisionId);
}

export function normalizeDecisionResult(raw, { questionSet, input = {}, model = PINNED_JEV_MODEL } = {}) {
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw decisionError(DECISION_ERROR_CODES.RESULT_INVALID, "Semantic decision result must be an object.");
  if (raw.model !== model || raw.model !== PINNED_JEV_MODEL) throw decisionError(DECISION_ERROR_CODES.MODEL_UNSUPPORTED, "Semantic decision result used an unsupported model.");
  if (!raw.answers || typeof raw.answers !== "object" || Array.isArray(raw.answers)) throw decisionError(DECISION_ERROR_CODES.RESULT_INVALID, "Semantic decision result is missing answers.");
  const answers = normalizeAnswers(raw.answers, questionSet);
  const confidence = normalizeConfidence(raw.confidence, questionSet);
  const usage = normalizeUsage(raw.usage);
  return {
    model,
    questionSetId: questionSet?.id ?? null,
    answers,
    confidence: Object.fromEntries(Object.keys(questionSet.questions).map((key) => [key, confidence[key] ?? null])),
    decision: normalizeCanonicalDecision({ questionSet, answers, confidence, input }),
    usage,
  };
}

export async function ensureSemanticDecision(options = {}) {
  return withDecisionScope(options, ensureSelectedSemanticDecision);
}

export async function recordSemanticDecision(options = {}) {
  return withDecisionScope(options, recordSelectedSemanticDecision);
}

function resolveProvider(provider) {
  return provider ?? getTestSemanticProvider();
}

export function buildDecisionState(value) {
  const counters = { bytes: 0 };
  const sanitized = sanitize(value, 0, counters);
  const bytes = Buffer.byteLength(JSON.stringify(sanitized));
  if (bytes > DECISION_LIMITS.maxStateBytes) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state exceeds the supported byte limit.");
  return sanitized;
}

function isHomePath(value) {
  return typeof value === "string" && (/^\/Users\/[^/]+\//.test(value) || /^\/home\/[^/]+\//.test(value));
}

function sanitize(value, depth, counters) {
  if (depth > DECISION_LIMITS.maxDepth) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state nesting exceeds the supported limit.");
  if (value === null || typeof value === "boolean" || typeof value === "number") return value;
  if (typeof value === "string") {
    if (/[^\x09\x0A\x0D\x20-\uD7FF\uE000-\uFFFD]/u.test(value)) throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains unsafe control characters.");
    if (SECRET_VALUE.test(value)) throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains a secret-like value.");
    if (isHomePath(value)) return "<redacted-user-path>";
    counters.bytes += Buffer.byteLength(value);
    if (value.length > DECISION_LIMITS.maxStringChars) return `${value.slice(0, DECISION_LIMITS.maxStringChars)}…<truncated>`;
    return value;
  }
  if (Array.isArray(value)) {
    if (value.length > DECISION_LIMITS.maxItems) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state contains too many items.");
    return value.map((item) => sanitize(item, depth + 1, counters));
  }
  if (typeof value === "object") {
    const entries = Object.entries(value);
    if (entries.length > DECISION_LIMITS.maxItems) throw decisionError(DECISION_ERROR_CODES.STATE_LIMIT, "Decision state contains too many fields.");
    const result = {};
    for (const [key, child] of entries) {
      if (SECRET_KEY.test(key) || key.toLowerCase() === "env" || key.toLowerCase() === "environment") continue;
      result[key] = sanitize(child, depth + 1, counters);
    }
    return result;
  }
  throw decisionError(DECISION_ERROR_CODES.STATE_UNSAFE, "Decision state contains an unsupported value.");
}

async function readOptionalArtifact(reader) {
  try {
    return await reader();
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return null;
    throw error;
  }
}

export function createDiagnosisDetails(input, previous = null) {
  if (typeof input?.verificationCycle !== "number" || !Number.isInteger(input.verificationCycle) || input.verificationCycle < 1) {
    const error = new Error("verificationCycle must be an integer >= 1");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  try {
    assertFailureClass(input.failureClass);
  } catch {
    const error = new Error(`Invalid failureClass: ${input.failureClass}`);
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (typeof input.hypothesis !== "string" || !input.hypothesis.trim()) {
    const error = new Error("hypothesis must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (!Array.isArray(input.evidenceRefs) || input.evidenceRefs.length === 0) {
    const error = new Error("evidenceRefs must be a non-empty array");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  const cleanRefs = input.evidenceRefs.map((r) => {
    if (typeof r !== "string" || !r.trim()) {
      const error = new Error("each evidenceRef must be a non-empty string");
      error.code = "E_DIAGNOSIS_INVALID";
      throw error;
    }
    return r.trim();
  });
  const uniqueRefs = [...new Set(cleanRefs)].sort();
  if (typeof input.settledBy !== "string" || !input.settledBy.trim()) {
    const error = new Error("settledBy must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  if (typeof input.nextSafeAction !== "string" || !input.nextSafeAction.trim()) {
    const error = new Error("nextSafeAction must be a non-empty string");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }

  const fingerprint = diagnosisFingerprint({
    failureClass: input.failureClass,
    hypothesis: input.hypothesis,
    evidenceRefs: uniqueRefs,
  });
  const infoGain = classifyDiagnosisInformationGain(
    { hypothesis: input.hypothesis, evidenceRefs: uniqueRefs },
    previous ? { hypothesis: previous.hypothesis, evidenceRefs: previous.evidenceRefs } : null,
  );

  return {
    verificationCycle: input.verificationCycle,
    failureClass: input.failureClass,
    hypothesis: input.hypothesis.trim(),
    evidenceRefs: uniqueRefs,
    settledBy: input.settledBy.trim(),
    nextSafeAction: input.nextSafeAction.trim(),
    diagnosisFingerprint: fingerprint,
    informationGain: infoGain,
    previousDiagnosisFingerprint: previous?.diagnosisFingerprint ?? null,
  };
}

export function currentCycleDiagnosis(events, taskId, verificationCycle) {
  const taskEvents = diagnosisEventsForTask(events, taskId);
  for (let i = taskEvents.length - 1; i >= 0; i--) {
    if (taskEvents[i].details?.verificationCycle === verificationCycle) {
      return taskEvents[i];
    }
  }
  return null;
}

export function diagnosisEventsForTask(events, taskId) {
  if (!Array.isArray(events)) return [];
  return events.filter((e) => e.event === "DIAGNOSIS_RECORDED" && (!taskId || e.taskId === taskId));
}

export function diagnosisFingerprint({ failureClass, hypothesis, evidenceRefs }) {
  assertFailureClass(failureClass);
  const normalizedHypothesis = normalizeDiagnosisText(hypothesis, "hypothesis");
  if (!Array.isArray(evidenceRefs) || evidenceRefs.length === 0) {
    const error = new Error("evidenceRefs must be a non-empty array of strings");
    error.code = "E_DIAGNOSIS_INVALID";
    throw error;
  }
  const cleanRefs = evidenceRefs.map((ref) => {
    if (typeof ref !== "string" || !ref.trim()) {
      const error = new Error("evidenceRef must be a non-empty string");
      error.code = "E_DIAGNOSIS_INVALID";
      throw error;
    }
    return ref.trim();
  });
  const normalizedRefs = [...new Set(cleanRefs)].sort();
  return canonicalFingerprint({
    failureClass,
    hypothesis: normalizedHypothesis,
    evidenceRefs: normalizedRefs,
  });
}

export function assertDiagnosticCaseDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "Diagnostic case details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `diagnostic case schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_DIAGNOSTIC_CASE_CYCLE_MISMATCH", "verificationCycle must be an integer >= 1");
  }
  if (!Number.isInteger(details.diagnosticRevision) || details.diagnosticRevision < 1) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticRevision must be an integer >= 1");
  }
  try {
    assertFailureClass(details.failureClass);
  } catch {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `invalid failureClass: ${details.failureClass}`);
  }

  if (!Array.isArray(details.observations) || details.observations.length > LIMITS.observationsPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `observations must be an array of at most ${LIMITS.observationsPerCase}`);
  }
  details.observations.forEach((observation, index) => assertObservation(observation, `observations[${index}]`));

  if (!Array.isArray(details.contributors) || details.contributors.length > LIMITS.contributorsPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `contributors must be an array of at most ${LIMITS.contributorsPerCase}`);
  }
  details.contributors.forEach((contributor, index) => assertContributor(contributor, `contributors[${index}]`));

  if (!Array.isArray(details.hypotheses)
    || details.hypotheses.length < 1
    || details.hypotheses.length > LIMITS.hypothesesPerCase) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `hypotheses must contain between 1 and ${LIMITS.hypothesesPerCase} hypotheses`);
  }
  details.hypotheses.forEach((hypothesis, index) => assertHypothesis(hypothesis, `hypotheses[${index}]`));

  const ids = [
    ...details.observations.map((o) => o.id),
    ...details.contributors.map((c) => c.id),
    ...details.hypotheses.map((h) => h.id),
  ];
  if (new Set(ids).size !== ids.length) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "duplicate IDs within the same diagnostic case are not allowed");
  }
  const observationIds = new Set(details.observations.map((o) => o.id));
  const contributorIds = new Set(details.contributors.map((c) => c.id));
  for (const contributor of details.contributors) {
    for (const basis of contributor.basis ?? []) {
      if (!observationIds.has(basis)) invalid("E_CONTRIBUTOR_REFERENCE_INVALID", `contributor ${contributor.id} references unknown observation ${basis}`);
    }
  }
  for (const hypothesis of details.hypotheses) {
    for (const ref of hypothesis.contributorRefs ?? []) {
      if (!contributorIds.has(ref)) invalid("E_CONTRIBUTOR_REFERENCE_INVALID", `hypothesis ${hypothesis.id} references unknown contributor ${ref}`);
    }
  }

  if (!details.nextSafeAction || typeof details.nextSafeAction !== "object"
    || typeof details.nextSafeAction.statement !== "string" || !details.nextSafeAction.statement.trim()) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "nextSafeAction.statement must be a non-empty string");
  }
  if (details.nextSafeAction.statement.length > LIMITS.statementLength) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", `nextSafeAction.statement exceeds ${LIMITS.statementLength} characters`);
  }

  if (typeof details.diagnosticFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.diagnosticFingerprint)) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticFingerprint must be a SHA-256 fingerprint");
  }
  const computed = diagnosticSemanticFingerprint({
    verificationCycle: details.verificationCycle,
    failureClass: details.failureClass,
    case_: details,
  });
  if (computed !== details.diagnosticFingerprint) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "diagnosticFingerprint does not match computed semantic fingerprint");
  }
  if (details.previousDiagnosticFingerprint !== undefined && details.previousDiagnosticFingerprint !== null
    && (typeof details.previousDiagnosticFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.previousDiagnosticFingerprint))) {
    invalid("E_DIAGNOSTIC_CASE_INVALID", "previousDiagnosticFingerprint must be a SHA-256 fingerprint or null");
  }
  return details;
}

export function assertHypothesisDispositionDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", "Disposition event details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", `disposition schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", "disposition verificationCycle must be an integer >= 1");
  }
  assertDiagnosticId(details.hypothesisRef, "hypothesisRef");
  if (!HYPOTHESIS_STATUSES.includes(details.status)) {
    invalid("E_HYPOTHESIS_DISPOSITION_INVALID", `disposition status must be one of ${HYPOTHESIS_STATUSES.join(", ")}`);
  }
  assertStringRefArray(
    details.evidenceRefs ?? [],
    "evidenceRefs",
    LIMITS.evidenceRefsPerHypothesis,
    "E_HYPOTHESIS_DISPOSITION_EVIDENCE_INVALID",
  );
  if ((details.evidenceRefs ?? []).length === 0) {
    invalid("E_HYPOTHESIS_DISPOSITION_EVIDENCE_INVALID", "disposition requires at least one evidenceRef");
  }
  assertBoundedText(details.reason, "reason", LIMITS.reasonLength, "E_HYPOTHESIS_DISPOSITION_INVALID");
  return details;
}

export function assertInterventionDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    invalid("E_INTERVENTION_INVALID", "Intervention event details must be an object");
  }
  if (details.schemaVersion !== DIAGNOSTIC_SCHEMA_VERSION) {
    invalid("E_INTERVENTION_INVALID", `intervention schemaVersion must be ${DIAGNOSTIC_SCHEMA_VERSION}`);
  }
  if (!Number.isInteger(details.verificationCycle) || details.verificationCycle < 1) {
    invalid("E_INTERVENTION_INVALID", "intervention verificationCycle must be an integer >= 1");
  }
  const intervention = details.intervention;
  if (!intervention || typeof intervention !== "object" || Array.isArray(intervention)) {
    invalid("E_INTERVENTION_INVALID", "intervention.intervention must be an object");
  }
  assertDiagnosticId(intervention.id, "intervention.id");
  if (!INTERVENTION_KINDS.includes(intervention.kind)) {
    invalid("E_INTERVENTION_INVALID", `intervention.kind must be one of ${INTERVENTION_KINDS.join(", ")}`);
  }
  assertBoundedText(intervention.statement, "intervention.statement", LIMITS.statementLength, "E_INTERVENTION_INVALID");
  assertStringRefArray(intervention.targets ?? [], "intervention.targets", 32);
  const hypothesisRefs = assertStringRefArray(
    intervention.hypothesisRefs ?? [],
    "intervention.hypothesisRefs",
    LIMITS.hypothesesPerCase,
    "E_INTERVENTION_REFERENCE_INVALID",
  );
  if (hypothesisRefs.length === 0) {
    invalid("E_INTERVENTION_HYPOTHESIS_MISSING", "intervention must bind to at least one hypothesis");
  }
  if (intervention.reversible !== undefined && typeof intervention.reversible !== "boolean") {
    invalid("E_INTERVENTION_INVALID", "intervention.reversible must be boolean");
  }
  return details;
}

export function diagnosticSemanticFingerprint({ verificationCycle, failureClass, case_ }) {
  return canonicalFingerprint({
    verificationCycle,
    failureClass,
    observations: [...case_.observations]
      .map(({ kind, evidenceRef, statement, provenance }) => canonicalizeDiagnosticValue({ kind, evidenceRef, statement, provenance }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    contributors: [...case_.contributors]
      .map(({ type, statement, basis, status }) => canonicalizeDiagnosticValue({ type, statement, basis, status }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    hypotheses: [...case_.hypotheses]
      .map(({ statement, contributorRefs, evidenceRefs, settledBy }) => canonicalizeDiagnosticValue({ statement, contributorRefs, evidenceRefs, settledBy }))
      .sort((a, b) => JSON.stringify(a).localeCompare(JSON.stringify(b))),
    nextSafeAction: canonicalizeDiagnosticValue(case_.nextSafeAction?.statement ?? null),
  });
}

export function interventionSemanticFingerprint(details) {
  const intervention = details.intervention;
  return canonicalFingerprint({
    kind: intervention.kind,
    statement: normalizeDiagnosticText(intervention.statement),
    targets: [...new Set((intervention.targets ?? []).map((target) => target.trim()))].sort(),
    hypothesisRefs: [...new Set((intervention.hypothesisRefs ?? []).map((ref) => ref.trim()))].sort(),
  });
}

export function resolveCurrentCycleDiagnostic(events, taskId, verificationCycle) {
  if (Array.isArray(events)) return resolveArrayCurrentCycleDiagnostic(events, taskId, verificationCycle);
  let structured = null;
  let legacy = null;
  for (const event of iterateDiagnosticEvents(events, taskId)) {
    const cycle = event.details?.verificationCycle;
    if (verificationCycle !== null && verificationCycle !== undefined
      && cycle !== null && cycle !== undefined && cycle !== verificationCycle) continue;
    if (event.event === "DIAGNOSTIC_CASE_RECORDED") {
      if (!structured || (event.seq ?? 0) >= (structured.seq ?? 0)) structured = event;
    } else if (!legacy || (event.seq ?? 0) >= (legacy.seq ?? 0)) legacy = event;
  }
  if (structured) return structuredProjection(structured);
  if (legacy) return legacyProjection(legacy);

  return null;
}

const findActiveCheck = (ref) => activeCycleChecks.find(
  (candidate) => candidate.id === ref || candidate.checkId === ref,
);

function canTransitionStatus(from, to) {
  if (from === to) return false;
  if (TERMINAL_STATUSES.includes(from)) return false;
  return (DISPOSITION_TRANSITIONS[from] ?? []).includes(to);
}

async function requireValidLedger(target, packageRoot, taskId) {
  const ledger = await validateEventLedger(target, packageRoot, { taskId: taskId ?? null });
  if (!ledger.valid) {
    throw stateError(ledger.errors[0].code ?? "E_EVENT_INVALID", ledger.errors[0].message);
  }
  return ledger;
}

function stateError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function assertOwnedLedgerUnchanged(events) {
  const owned = ownedLedgerProofs.get(events);
  if (owned && (owned.versionStatement.get().data_version !== owned.version
    || ownedSnapshotFileIdentity(owned.filename) !== owned.fileIdentity)) {
    throw protocolError("E_STATE_REVISION_CONFLICT", "Owned ledger snapshot changed during its audit");
  }
  return owned;
}

export function buildProtocolEvent(input, { checkpoint } = {}) {
  if (!checkpoint || !Number.isInteger(checkpoint.seq) || checkpoint.seq < 0
    || (checkpoint.lastHash !== null && !/^[a-f0-9]{64}$/.test(checkpoint.lastHash))) {
    throw protocolError("E_EVENT_INVALID", "event checkpoint is invalid");
  }
  const event = {
    seq: checkpoint.seq + 1,
    schemaVersion: EVENT_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    taskId: input.taskId,
    event: input.event,
    at: input.at ?? new Date().toISOString(),
    ...(input.fingerprint ? { fingerprint: input.fingerprint } : {}),
    previousHash: checkpoint.lastHash,
    ...(input.details ? { details: structuredClone(input.details) } : {}),
  };
  validateKnownEventDetails(event);
  assertSecretFree(event);
  event.hash = eventHash(event);
  return event;
}

function checkpointFromEvents(events) {
  const last = events.at(-1) ?? null;
  return {
    schemaVersion: 1,
    seq: last?.seq ?? 0,
    lastHash: last?.hash ?? null,
  };
}

async function evaluateCallbackLedgerAudit(target, packageRoot, options, callback, events, relPath) {
  let result;
  try {
    result = validateOwnedLedgerEvents(events, options);
    const owned = assertOwnedLedgerUnchanged(events);
    const sameScope = owned && owned.store === getOperationalStore(target)
      && owned.db === owned.store.db && owned.packageRoot === packageRoot
      && owned.relPath === relPath && owned.taskId === options?.taskId;
    const bindingErrors = sameScope && owned.semanticValidated
      ? [] : await validateSemanticDecisionArtifactBindings(target, packageRoot, events);
    assertOwnedLedgerUnchanged(events);
    if (sameScope && result.valid && bindingErrors.length === 0) owned.semanticValidated = true;
    if (bindingErrors.length) result = { valid: false, events, errors: [...result.errors, ...bindingErrors] };
  } catch (error) {
    result = { valid: false, events: [], errors: [{ code: error.code ?? "E_EVENT_INVALID", message: error.message, artifacts: [relPath] }] };
  }
  const initiallyValid = result.valid;
  const callbackResult = await callback(result);
  // The caller may await other work or mutate its result object. Keep the
  // private snapshot proof valid for the entire successful observation.
  if (initiallyValid) assertOwnedLedgerUnchanged(events);
  return callbackResult;
}

export function eventHash(event) {
  const { hash, ...body } = event;
  return canonicalFingerprint(body);
}

function ownedSnapshotFileIdentity(filename) {
  // The WAL is durable database content that can change while a read cursor
  // pins the main file. The SHM sidecar only carries transient lock/index
  // state, so it is intentionally excluded from the byte identity.
  const paths = [filename, `${filename}-wal`];
  const files = paths.map(current => {
    try {
      const file = lstatSync(current, { bigint: true });
      if (!file.isFile()) throw protocolError("E_STATE_REVISION_CONFLICT", "Owned ledger snapshot file changed during its audit");
      return file;
    } catch (error) {
      if (error?.code === "ENOENT") return null;
      throw error;
    }
  });
  const identity = files.map(file => file
    ? [file.dev, file.ino, file.size, file.mtimeNs, file.ctimeNs].join(":")
    : "missing").join("|");
  if (process.platform !== "win32") return identity;
  // Windows may defer file timestamps until SQLite's open handle closes.
  // Hash readable bytes with bounded memory so raw writes cannot reuse a proof.
  const hash = createHash("sha256");
  const buffer = Buffer.allocUnsafe(64 * 1024);
  for (const [index, current] of paths.entries()) {
    hash.update(`${index}:`);
    if (!files[index]) continue;
    const fd = openSync(current, "r");
    try {
      let count;
      while ((count = readSync(fd, buffer, 0, buffer.length, null)) !== 0) hash.update(buffer.subarray(0, count));
    } finally { closeSync(fd); }
  }
  return `${identity}:${hash.digest("hex")}`;
}

async function parseEventsText(text, relPath, packageRoot) {
  assertJsonBytes(text, relPath);
  const schema = await readSchema("event", packageRoot);
  const lines = text.split(/\r?\n/).filter((line) => line.trim() !== "");
  return lines.map((line, index) => {
    let event;
    try {
      event = JSON.parse(line);
      assertJsonLimits(event, `${relPath}[${index}]`);
      assertSchema(event, schema, `${relPath}[${index}]`);
      validateKnownEventDetails(event);
    } catch (error) {
      throw protocolError(error.code ?? "E_EVENT_INVALID", `${relPath} line ${index + 1}: ${error.message}`, [relPath]);
    }
    return event;
  });
}

function protocolError(code, message, artifacts = [ARTIFACT_PATHS.events]) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

async function readEventCheckpoint(target, packageRoot, relPath, options, transaction) {
  if (!transaction.eventCheckpoints) transaction.eventCheckpoints = new Map();
  const cached = transaction.eventCheckpoints.get(relPath);
  if (cached) return cached;
  const checkpoint = checkpointFromEvents(await readEventTail(target, packageRoot, { ...options, eventsPath: relPath, limit: 1 }));
  transaction.eventCheckpoints.set(relPath, checkpoint);
  return checkpoint;
}

export function validateCompletionRecoveryAuthorization({ state, receipt, events } = {}) {
  const errors = [];
  if (!state) {
    return {
      authorized: false,
      errors: [{ code: "E_STATE_MISSING", message: "Work-state is required for recovery validation" }],
    };
  }
  const attempt = state.lastCompletionAttempt;
  if (!attempt || attempt.status !== "REJECTED") {
    return {
      authorized: false,
      errors: [{ code: "E_COMPLETION_RECOVERY_UNAUTHORIZED", message: "Recovery requires a persisted REJECTED completion attempt" }],
    };
  }
  const hasRecoverableReason = Array.isArray(attempt.reasonCodes)
    && attempt.reasonCodes.length > 0
    && attempt.reasonCodes.every((code) => isRecoverableCompletionEvidenceCode(code));
  if (!hasRecoverableReason) {
    return {
      authorized: false,
      errors: [{ code: "E_COMPLETION_RECOVERY_UNAUTHORIZED", message: "Completion attempt contains no recoverable evidence reason codes" }],
    };
  }

  const taskEvents = (events ?? []).filter((event) => event.taskId === state.taskId);
  const targetCycle = state.verificationCycle ?? 1;

  if (attempt.verificationCycle !== targetCycle) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: `Work-state rejection verificationCycle ${attempt.verificationCycle} does not match state verificationCycle ${targetCycle}`,
    });
    return { authorized: false, errors };
  }

  const reviewEvents = taskEvents
    .map((event, index) => ({ event, index }))
    .filter(({ event }) => event.event === "REVIEW_STARTED" && (event.details?.verificationCycle ?? 1) === targetCycle);
  const latestReviewIndex = reviewEvents.at(-1)?.index ?? -1;

  const rejectionEvents = taskEvents
    .map((event, index) => ({ event, index }))
    .filter(({ event }) => event.event === "COMPLETION_REJECTED");

  if (rejectionEvents.length === 0) {
    errors.push({
      code: "E_COMPLETION_RECOVERY_UNAUTHORIZED",
      message: "No COMPLETION_REJECTED event found in protocol ledger",
    });
    return { authorized: false, errors };
  }

  const matchingEvent = rejectionEvents.findLast(({ event, index }) => {
    const eventCycle = event.details?.verificationCycle ?? 1;
    if (eventCycle !== targetCycle) return false;
    if (latestReviewIndex >= 0 && index < latestReviewIndex) return false;
    return true;
  });

  if (!matchingEvent) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: `No matching COMPLETION_REJECTED event found for verification cycle ${targetCycle}`,
    });
    return { authorized: false, errors };
  }

  const eventDetails = matchingEvent.event.details ?? {};
  const stateReasons = [...new Set(attempt.reasonCodes ?? [])].sort();
  const eventReasons = [...new Set(eventDetails.reasonCodes ?? [])].sort();
  if (stateReasons.join(",") !== eventReasons.join(",")) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: "Work-state rejection reasonCodes do not match ledger COMPLETION_REJECTED event",
    });
  }

  const stateMissing = [...new Set(attempt.missingRequirementIds ?? [])].sort();
  const eventMissing = [...new Set(eventDetails.missingRequirementIds ?? [])].sort();
  if (stateMissing.join(",") !== eventMissing.join(",")) {
    errors.push({
      code: "E_COMPLETION_REJECTION_LEDGER_MISMATCH",
      message: "Work-state missingRequirementIds do not match ledger COMPLETION_REJECTED event",
    });
  }

  const currentStateFingerprint = canonicalFingerprint(state);
  if (eventDetails.stateFingerprint && eventDetails.stateFingerprint !== currentStateFingerprint) {
    errors.push({
      code: "E_COMPLETION_REJECTION_STATE_FINGERPRINT_MISMATCH",
      message: "Current work-state no longer matches the rejected completion snapshot",
    });
  }

  if (eventDetails.receiptFingerprint !== undefined) {
    const currentReceiptFingerprint = receipt ? canonicalFingerprint(receipt) : undefined;
    if (currentReceiptFingerprint !== eventDetails.receiptFingerprint) {
      errors.push({
        code: "E_COMPLETION_REJECTION_RECEIPT_FINGERPRINT_MISMATCH",
        message: "Current receipt no longer matches the rejected completion snapshot",
      });
    }
  }

  return {
    authorized: errors.length === 0,
    errors,
  };
}

export function validateKnownEventDetails(event) {
  if (!event || typeof event !== "object") return;
  switch (event.event) {
    case "DIAGNOSIS_RECORDED":
      assertDiagnosisDetails(event.details);
      return;
    case "DIAGNOSTIC_CASE_RECORDED":
      assertDiagnosticCaseDetails(event.details);
      return;
    case "INTERVENTION_RECORDED":
      assertInterventionDetails(event.details);
      return;
    case "HYPOTHESIS_DISPOSITION_RECORDED":
      assertHypothesisDispositionDetails(event.details);
      return;
    case "DECISION_CRITERION_RECORDED":
      assertDecisionCriterionDetails(event.details);
      return;
    case "CHECKPOINT_RECONCILED":
      assertReconcileClosureDetails(event.details);
      return;
    case CHECKPOINT_REVALIDATED_EVENT:
      assertCheckpointRevalidatedDetails(event.details);
      return;
    case CONTRACT_REVISED_EVENT:
      assertContractRevisedDetails(event.details);
      return;
    case GATE_SATISFIED_EVENT:
      assertGateSatisfiedDetails(event.details);
      return;
    case GATE_REVALIDATED_EVENT:
      assertGateRevalidatedDetails(event.details);
      return;
    case SEMANTIC_DECISION_RECORDED_EVENT:
    case SEMANTIC_DECISION_SUPERSEDED_EVENT:
      assertSemanticDecisionDetails(event.details, event.event);
      return;
    case "TASK_RECOVERY_RECORDED":
      assertRecoveryRecordedDetails(event.details);
      return;
    case "OPERATOR_RECOVERY_RECORDED":
      // The exact known legacy defect signature is tolerated here so the
      // ledger can be parsed and classified. It only becomes valid through an
      // official migration event (enforced by validateEventLedger).
      if (!event.details?.recoveryId && isLegacyRecoveryDetailsShape(event.details)) return;
      assertRecoveryRecordedDetails(event.details);
      return;
    case "TASK_ABANDONED":
      assertTaskAbandonedDetails(event.details);
      return;
    case "LEGACY_RECOVERY_MIGRATION_RECORDED":
      assertLegacyMigrationDetails(event.details);
      return;
    case CONTRACT_BOOTSTRAP_REPAIR_EVENT:
    case "CONTRACT_BOOTSTRAP_REPAIR_MIGRATION_RECORDED":
      validateKnownContractBootstrapEvent(event);
      return;
    case "ROUTE_REBOUND":
      assertRouteReboundDetails(event.details);
      return;
    case ROUTE_CHECKPOINT_BOUND_EVENT:
      assertRouteCheckpointBoundDetails(event.details);
      return;
    case "TASK_RECOVERY_RESUMED":
      assertRecoveryResumedDetails(event.details);
      return;
    case "TRAJECTORY_EVALUATED":
      assertTrajectoryEvaluatedDetails(event);
      return;
    case "WORKSPACE_BOUND":
      assertStructuredArtifactEvent(event, ["workspaceFingerprint"], "WORKSPACE_BOUND");
      return;
    case "HANDOFF_CREATED":
      if (!event.details || typeof event.details !== "object" || Array.isArray(event.details)
        || typeof event.details.handoffId !== "string" || !/^handoff-[A-Za-z0-9_-]+$/.test(event.details.handoffId)
        || typeof event.details.artifact !== "string" || !event.details.artifact
        || typeof event.details.digest !== "string") {
        throw protocolError("E_EVENT_INVALID", "HANDOFF_CREATED requires a handoff ID, artifact path, and digest");
      }
      assertFingerprint(event.details.digest, "HANDOFF_CREATED details.digest");
      return;
    case "HANDOFF_ACCEPTED":
      assertHandoffAcceptedDetails(event);
      return;
    case "RESPONSIBILITY_SET":
      assertStructuredArtifactEvent(event, ["responsibilityFingerprint"], "RESPONSIBILITY_SET");
      if (typeof event.details.label !== "string" || !event.details.label) {
        throw protocolError("E_EVENT_INVALID", "RESPONSIBILITY_SET details.label must be a non-empty string");
      }
      return;
    case "VERIFICATION_SCOPE_CAPTURED":
      assertStructuredArtifactEvent(event, ["scopeFingerprint"], "VERIFICATION_SCOPE_CAPTURED");
      if (!["AUTO", "CHANGED", "CLAIMED", "FULL"].includes(event.details.resolvedMode)
        || !Number.isInteger(event.details.verificationCycle) || event.details.verificationCycle < 1) {
        throw protocolError("E_EVENT_INVALID", "VERIFICATION_SCOPE_CAPTURED requires a valid mode and verification cycle");
      }
      return;
    case "CODE_MANIFEST_CAPTURED":
      assertStructuredArtifactEvent(event, ["manifestFingerprint"], "CODE_MANIFEST_CAPTURED");
      assertFingerprint(event.details.contentDigest, "CODE_MANIFEST_CAPTURED details.contentDigest");
      if (!Number.isInteger(event.details.coveredPaths) || event.details.coveredPaths < 0) {
        throw protocolError("E_EVENT_INVALID", "CODE_MANIFEST_CAPTURED details.coveredPaths must be a non-negative integer");
      }
      return;
    case "ATTESTATION_STATEMENT_CREATED":
      assertStructuredArtifactEvent(event, ["statementFingerprint"], "ATTESTATION_STATEMENT_CREATED");
      assertFingerprint(event.details.manifestFingerprint, "ATTESTATION_STATEMENT_CREATED details.manifestFingerprint");
      return;
    default:
      if (isActionEventName(event.event)) {
        assertActionEventDetails(event);
        return;
      }
      if (isApprovalEventName(event.event)) {
        assertApprovalEventDetails(event);
        return;
      }
      return;
  }
}

export function validateLedgerEvents(events, options = {}) {
  const errors = [];
  let taskId = null;
  let previousHash = null;
  const seen = new Set();
  let lastMilestone = -1;
  const milestoneCounts = new Map();
  const createdHandoffs = ledgerRelationMap();
  const acceptedHandoffs = ledgerRelationSet();
  for (const [index, event] of events.entries()) {
    if (event.seq !== index + 1) {
      errors.push({ code: "E_EVENT_INVALID", message: `event sequence must be ${index + 1}` });
    }
    if (taskId === null) taskId = event.taskId;
    if (event.taskId !== taskId) errors.push({ code: "E_EVENT_INVALID", message: "event task IDs must remain stable" });
    if (event.previousHash !== previousHash) {
      errors.push({ code: "E_LEDGER_HASH_INVALID", message: `event ${event.seq} previousHash does not match` });
    }
    previousHash = event.hash;
    if (event.hash !== eventHash(event)) {
      errors.push({ code: "E_LEDGER_HASH_INVALID", message: `event ${event.seq} hash does not match its content` });
    }
    try {
      validateKnownEventDetails(event);
    } catch (err) {
      errors.push({ code: err.code ?? "E_EVENT_INVALID", message: `event ${event.seq} (${event.event}): ${err.message}` });
    }
    lastMilestone = validateMilestoneChronology(events, index, event, milestoneCounts, lastMilestone, errors);
    seen.add(event.event);
    if (event.event === "EXECUTION_STARTED") {
      validateExecutionGateChronology(events, index, seen, errors);
    }
    if (event.event === "VERIFICATION_RECORDED" && !seen.has("VERIFICATION_STARTED")) {
      errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "verification evidence recorded before verification started" });
    }
    if (event.event === "COMPLETION_VALIDATED" && !seen.has("VERIFICATION_RECORDED")) {
      errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "completion validated before verification evidence" });
    }
    if (event.event === "COMPLETION_REJECTED" && !seen.has("VERIFICATION_STARTED")) {
      errors.push({ code: "E_PHASE_CHRONOLOGY_INVALID", message: "completion rejected before verification started" });
    }
    if (event.event === "HANDOFF_CREATED") {
      if (event.details?.handoffId) {
        createdHandoffs.set(event.details.handoffId, event.details.digest);
      }
    }
    if (event.event === "HANDOFF_ACCEPTED") {
      const hId = event.details?.handoffId;
      if (hId) {
        if (acceptedHandoffs.has(hId)) {
          errors.push({ code: "E_HANDOFF_ALREADY_ACCEPTED", message: `duplicate HANDOFF_ACCEPTED for handoffId ${hId}` });
        } else {
          acceptedHandoffs.add(hId);
          if (!createdHandoffs.has(hId)) {
            errors.push({ code: "E_HANDOFF_ACCEPTANCE_INCONSISTENT", message: `HANDOFF_ACCEPTED has no preceding HANDOFF_CREATED for handoffId ${hId}` });
          } else if (createdHandoffs.get(hId) !== event.details?.handoffDigest) {
            errors.push({ code: "E_HANDOFF_ACCEPTANCE_INCONSISTENT", message: `HANDOFF_ACCEPTED digest mismatch for handoffId ${hId}` });
          }
        }
      }
    }
  }
  validateLegacyRecoveryMigrations(events, errors, {
    allowUnmigratedLegacyRecoveryEvents: options?.allowUnmigratedLegacyRecoveryEvents === true,
  });
  errors.push(...validateCheckpointRevalidationEventBindings(events));
  errors.push(...validateContractRevisionEventBindings(events));
  errors.push(...validateGateSatisfactionBindings(events));
  errors.push(...validateSemanticDecisionEventBindings(events));
  const repairedErrors = validateContractBootstrapRepairLedger(events, errors, options);
  return { valid: repairedErrors.length === 0, events, errors: repairedErrors };
}

function validateOwnedLedgerEvents(events, options) {
  const owned = assertOwnedLedgerUnchanged(events);
  if (!owned) return validateLedgerEvents(events, options);
  const flags = {
    allowUnmigratedLegacyRecoveryEvents: options?.allowUnmigratedLegacyRecoveryEvents === true,
    allowUnmigratedLegacyContractBootstrapRepairMarkers: options?.allowUnmigratedLegacyContractBootstrapRepairMarkers === true,
  };
  const key = JSON.stringify(flags);
  if (owned.successes.has(key)) return { valid: true, events, errors: [] };
  const result = validateLedgerEvents(events, flags);
  assertOwnedLedgerUnchanged(events);
  if (result.valid) owned.successes.add(key);
  return result;
}

export async function validatePortableEventLedger(target, packageRoot, options = {}) {
  return validateReadLedger(target, packageRoot, options, readPortableEvents);
}

export function validateStateLedgerCoherence(state, events) {
  const errors = [
    ...validateCheckpointRevalidationCurrentBinding(state, events),
    ...validateContractRevisionCurrentBinding(state, events),
  ];
  if (!Number.isInteger(state.verificationCycle)) return errors;
  const { observed, supportsReviewEvents, latestVerification, latestReview } = summarizeStateEvents(state, events);
  const phaseRequirements = {
    EXECUTING: ["EXECUTION_STARTED"],
    VERIFYING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    DIAGNOSING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    CORRECTING: ["EXECUTION_STARTED", "VERIFICATION_STARTED"],
    REVIEWING: ["EXECUTION_STARTED", "VERIFICATION_STARTED", ...(supportsReviewEvents ? ["REVIEW_STARTED"] : [])],
    COMPLETE: ["EXECUTION_STARTED", "VERIFICATION_STARTED", ...(supportsReviewEvents ? ["REVIEW_STARTED"] : []), "COMPLETION_VALIDATED"],
  };
  for (const required of phaseRequirements[state.phase] ?? []) {
    if (!observed.has(required)) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: `Work-state phase ${state.phase} requires ledger event ${required}`,
      });
    }
  }
  if (Number.isInteger(state.verificationCycle)) {
    if ((latestVerification ? latestVerification.event.details?.verificationCycle ?? 1 : undefined) !== state.verificationCycle) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state verification cycle does not match the lifecycle ledger",
      });
    }
    const latestReviewCycle = latestReview?.event.details?.verificationCycle;
    if (state.phase === "VERIFYING"
      && latestReviewCycle === state.verificationCycle
      && latestReview.index > (latestVerification?.index ?? -1)) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state returned to VERIFYING without a new verification cycle in the lifecycle ledger",
      });
    }
    if (["REVIEWING", "COMPLETE"].includes(state.phase)
      && supportsReviewEvents
      && (latestReviewCycle !== state.verificationCycle
        || latestReview.index < (latestVerification?.index ?? -1))) {
      errors.push({
        code: "E_STATE_LEDGER_DIVERGENCE",
        message: "Work-state review phase does not match the current lifecycle ledger cycle",
      });
    }
  }
  return errors;
}

function validateStoredEvent(event, schema, label) {
  assertJsonBytes(JSON.stringify(event), label);
  assertJsonLimits(event, label);
  assertSchema(event, schema, label);
  validateKnownEventDetails(event);
}

async function validateStoredEvents(events, relativePath, packageRoot) {
  const schema = await readSchema("event", packageRoot);
  for (const [index, event] of events.entries()) {
    validateStoredEvent(event, schema, `${relativePath}[${index}]`);
  }
  return events;
}

export function authoritativeChecksForRequirements({ requirements = [], checks = [] } = {}) {
  return normalizeRequirements(requirements).map((requirement) => {
    const candidates = checks.filter((check) => matchesRequirement(check, requirement));
    return {
      requirement,
      check: latestAuthoritativeCheck(candidates),
    };
  });
}

function componentStatus(check, requirement, allChecks = [], options = {}) {
  if (requirement.operator !== "ALL" || !requirement.requirements?.length) return null;
  const components = check?.details?.components;
  const statuses = requirement.requirements.map((child) => {
    if (Array.isArray(components)) {
      const matchingComp = components.filter((item) => (
        item?.requirementId === child.id || item?.requirement === child.text
      )).at(-1);
      if (matchingComp) {
        const provenance = validateCommandProvenance(matchingComp);
        if (!provenance.valid) return { ...matchingComp, status: "failed", reasonCode: provenance.error.code };
        const auth = validateVerificationAuthority(matchingComp, options);
        if (!auth.valid) return { ...matchingComp, status: "failed", reasonCode: auth.error.code };
        return matchingComp;
      }
    }
    const childCandidates = allChecks.filter((candidate) => matchesRequirement(candidate, child));
    const childCheck = latestAuthoritativeCheck(childCandidates);
    if (childCheck) {
      const provenance = validateCommandProvenance(childCheck);
      if (!provenance.valid) return { ...childCheck, status: "failed", reasonCode: provenance.error.code };
      const auth = validateVerificationAuthority(childCheck, options);
      if (!auth.valid) return { ...childCheck, status: "failed", reasonCode: auth.error.code };
    }
    return childCheck;
  });
  if (statuses.some((item) => !item)) return "MISSING";
  if (statuses.some((item) => item.status === "failed")) return "INVALID";
  if (statuses.some((item) => item.status !== "passed" || item.evidenceKind !== "OBSERVED")) return "PARTIAL";
  return "COVERED";
}

export function evaluateRequiredEvidence({
  requirements = [],
  checks = [],
  target,
  taskId,
  authorities,
  options = {},
} = {}) {
  const authOptions = {
    ...(target ? { target } : {}),
    ...(taskId ? { taskId } : {}),
    ...(authorities ? { authorities } : {}),
    ...options,
  };
  const normalized = normalizeRequirements(requirements);
  const result = {
    ready: true,
    required: normalized,
    covered: [],
    missing: [],
    partial: [],
    invalid: [],
    lifecyclePending: [],
    reasonCodes: [],
  };
  for (const requirement of normalized) {
    if (requirement.mixedTerminal) {
      result.invalid.push({
        ...requirement,
        reasonCode: "E_CIRCULAR_COMPLETION_REQUIREMENT",
      });
      continue;
    }
    if (requirement.terminalOwned || requirement.lifecycleOwned) {
      result.lifecyclePending.push(requirement);
      continue;
    }
    const candidates = checks.filter((check) => matchesRequirement(check, requirement));
    const check = latestAuthoritativeCheck(candidates);
    const provenance = check ? validateCommandProvenance(check) : { valid: true };
    const auth = provenance.valid
      ? (check ? validateVerificationAuthority(check, authOptions) : { valid: true })
      : provenance;
    const compound = componentStatus(check, requirement, checks, authOptions);
    if (!auth.valid) {
      result.invalid.push({ ...requirement, reasonCode: auth.error.code });
    } else if (compound === "INVALID" || check?.status === "failed") {
      result.invalid.push(requirement);
    } else if (compound === "PARTIAL") {
      result.partial.push(requirement);
    } else if (compound === "MISSING") {
      result.missing.push(requirement);
    } else if (
      (check?.status === "passed" || compound === "COVERED")
      && (requirement.requiredEvidenceKind !== "OBSERVED" || check?.evidenceKind === "OBSERVED" || compound === "COVERED")
      && (compound === null || compound === "COVERED")
    ) {
      result.covered.push(requirement);
    } else if (check?.status === "passed" && check.evidenceKind !== "OBSERVED") {
      result.invalid.push({ ...requirement, reasonCode: "E_EVIDENCE_KIND_INVALID" });
    } else if (check) {
      result.partial.push(requirement);
    } else {
      result.missing.push(requirement);
    }
  }
  result.ready = result.missing.length === 0 && result.partial.length === 0 && result.invalid.length === 0;
  if (result.invalid.length) {
    const specificCodes = result.invalid
      .map((item) => item.reasonCode)
      .filter(Boolean);
    if (specificCodes.length > 0) {
      result.reasonCodes.push(...new Set(specificCodes));
    } else {
      result.reasonCodes.push("E_EVIDENCE_INVALID");
    }
  }
  if (result.missing.length) result.reasonCodes.push("E_EVIDENCE_REQUIRED");
  if (result.partial.length) result.reasonCodes.push("E_EVIDENCE_PARTIAL");
  const leaves = ordinaryLeafRequirements(normalized);
  const authoritativeLeaves = authoritativeChecksForRequirements({ requirements: leaves, checks });
  result.authoritativeFailures = authoritativeLeaves.filter(({ check }) => check?.status === "failed");
  result.authoritativeBlocked = authoritativeLeaves.filter(({ check }) => check?.status === "blocked");
  return result;
}

export function evaluateTerminalRequirements({ requirements = [], receipt = null } = {}) {
  const normalized = normalizeRequirements(requirements);
  const terminal = terminalRequirements(normalized);
  const result = {
    covered: [],
    pending: [],
    invalid: [],
    errors: [],
  };
  const pubStatus = receipt ? (receipt.publicationStatus ?? "not-published") : "not-published";
  const prodStatus = receipt ? (receipt.productionReadiness ?? "not-verified") : "not-verified";
  const receiptEvidence = Array.isArray(receipt?.evidence) ? receipt.evidence : [];

  for (const req of terminal) {
    if (req.type === "LIFECYCLE") {
      result.covered.push(req);
    } else if (req.type === "PUBLICATION") {
      const requiredLevel = req.requiredPublicationStatus ?? "published";
      const matchingEvidence = receiptEvidence
        .filter((item) => item.kind === "OBSERVED")
        .filter((item) => item.details?.requirementId === req.id)
        .filter((item) => item.details?.terminalType === "PUBLICATION");
      const latestEvidence = latestAuthoritativeCheck(matchingEvidence);
      const evidenceStatus = latestEvidence?.details?.terminalStatus;
      const evidenceSatisfied = isPublicationStatusSatisfied(evidenceStatus, requiredLevel);
      const globalSatisfied = isPublicationStatusSatisfied(pubStatus, requiredLevel);

      if (globalSatisfied && evidenceSatisfied) {
        result.covered.push(req);
      } else {
        result.pending.push(req);
        result.errors.push({
          code: "E_PUBLICATION_REQUIREMENT_PENDING",
          message: `The contract explicitly requires publication status '${requiredLevel}', but publication evidence/status is insufficient for requirement: ${req.text}`,
          requirementId: req.id,
        });
      }
    } else if (req.type === "PRODUCTION_READINESS") {
      const matchingEvidence = receiptEvidence
        .filter((item) => item.kind === "OBSERVED")
        .filter((item) => item.details?.requirementId === req.id)
        .filter((item) => item.details?.terminalType === "PRODUCTION_READINESS");
      const latestEvidence = latestAuthoritativeCheck(matchingEvidence);
      const evidenceStatus = latestEvidence?.details?.terminalStatus;
      const evidenceSatisfied = evidenceStatus === "ready" || evidenceStatus === "verified";
      const globalSatisfied = prodStatus === "ready" || prodStatus === "verified";

      if (globalSatisfied && evidenceSatisfied) {
        result.covered.push(req);
      } else {
        result.pending.push(req);
        result.errors.push({
          code: "E_PRODUCTION_REQUIREMENT_PENDING",
          message: `The contract explicitly requires production readiness, but production readiness evidence/status is insufficient for requirement: ${req.text}`,
          requirementId: req.id,
        });
      }
    }
  }
  return result;
}

export function latestAuthoritativeCheck(candidates) {
  if (!candidates || candidates.length === 0) return null;
  return [...candidates].sort((a, b) => {
    const cycleA = a.details?.verificationCycle ?? a.verificationCycle ?? 1;
    const cycleB = b.details?.verificationCycle ?? b.verificationCycle ?? 1;
    if (cycleA !== cycleB) return cycleA - cycleB;
    const timeA = typeof a.timestamp === "string" ? a.timestamp : "";
    const timeB = typeof b.timestamp === "string" ? b.timestamp : "";
    if (timeA !== timeB) return timeA.localeCompare(timeB);
    return 0;
  }).at(-1);
}

export function normalizeRequirements(requirements = []) {
  const byId = new Map();
  for (const raw of requirements) {
    const requirement = classifyRequirement(raw);
    if (!byId.has(requirement.id)) byId.set(requirement.id, requirement);
  }
  return [...byId.values()].sort((left, right) => left.id.localeCompare(right.id));
}

export function ordinaryLeafRequirements(requirements = []) {
  const result = [];
  function visit(requirement) {
    if (requirement.terminalOwned) return;
    if (requirement.operator === "ALL" && Array.isArray(requirement.requirements) && requirement.requirements.length > 0) {
      for (const child of requirement.requirements) {
        visit(child);
      }
      return;
    }
    result.push(requirement);
  }
  for (const req of normalizeRequirements(requirements)) {
    visit(req);
  }
  return result;
}

export function terminalRequirementsForContract(contractValue = {}, { additionalEvidence = [] } = {}) {
  const pool = [
    ...(contractValue.verification ?? []),
    ...(contractValue.successCriteria ?? []),
    ...additionalEvidence,
  ];
  return terminalRequirements(pool);
}

export function validateCommandProvenance(check) {
  if (check?.kind !== "command" || check.evidenceKind !== "OBSERVED") {
    return { valid: true, error: null };
  }
  if (check.provenance !== "FORGELOOP_EXECUTED" || typeof check.executionRef !== "string" || check.executionRef.trim() === "") {
    return {
      valid: false,
      error: {
        code: E_COMMAND_PROVENANCE_UNATTESTED,
        message: "Observed command evidence requires a ForgeLoop execution artifact",
      },
    };
  }
  return { valid: true, error: null };
}

export function assertEvidenceList(value, label = "evidence") {
  if (!Array.isArray(value)) throw new EvidenceError(`${label} must be an array`);
  value.forEach((item, index) => assertEvidence(item, `${label}[${index}]`));
  return value;
}

export function createEvidence(input, source, result, details, cycle) {
  const value = typeof input === "string"
    ? {
        kind: input,
        source,
        result,
        ...(cycle !== undefined ? { verificationCycle: cycle } : {}),
        details: {
          ...(details === undefined ? {} : details),
          ...(cycle !== undefined ? { verificationCycle: cycle } : {}),
        },
      }
    : structuredClone(input);
  if (value.details && typeof value.details === "object" && value.verificationCycle !== undefined) {
    value.details.verificationCycle = value.verificationCycle;
  }
  assertEvidence(value);
  return value;
}

export function evidenceMatches(evidence, terms) {
  const normalizedTerms = (Array.isArray(terms) ? terms : [terms])
    .filter((term) => typeof term === "string" && term.length > 0)
    .map((term) => term.toLowerCase());
  return (evidence ?? []).some((item) => {
    const detailsText = item.details
      ? `${item.details.requirementText ?? ""} ${String(item.details.terminalType ?? "").replace(/_/g, " ")}`
      : "";
    const haystack = `${item.source} ${item.result} ${detailsText}`.toLowerCase();
    return normalizedTerms.some((term) => haystack.includes(term));
  });
}

export async function assertExecutionPrerequisites(input = {}) {
  const prerequisites = await evaluateStartExecutionPrerequisites(input);
  const error = prerequisiteError(prerequisites);
  if (error) throw error;
  return prerequisites;
}

export async function evaluateStartExecutionPrerequisites({
  target,
  state,
  packageRoot,
  taskId = null,
  contractPath = null,
  routePath = null,
  statePath = null,
  preflightPath = null,
  eventsPath = null,
  readers = null,
} = {}) {
  const effectiveTaskId = taskId ?? null;
  const contractRel = prerequisiteArtifactPath(contractPath, effectiveTaskId, "contract");
  const routeRel = prerequisiteArtifactPath(routePath, effectiveTaskId, "route");
  const stateRel = prerequisiteArtifactPath(statePath, effectiveTaskId, "state");
  const preflightRel = prerequisiteArtifactPath(preflightPath, effectiveTaskId, "preflight");
  const eventsRel = prerequisiteArtifactPath(eventsPath, effectiveTaskId, "events");

  const errors = [];
  const requiredArtifacts = [
    stateRel,
    contractRel,
    routeRel,
    preflightRel,
    eventsRel,
  ];
  if (!state) {
    return {
      errors: [issue("E_PHASE_PREREQUISITE_MISSING", "EXECUTING requires a work state", [stateRel])],
      requiredArtifacts,
    };
  }

  const contract = await load(
    () => (readers?.readContract ?? readContract)(target, packageRoot, { taskId: effectiveTaskId, contractPath }),
    "E_PHASE_PREREQUISITE_MISSING",
    `EXECUTING requires ${contractRel}`,
    [contractRel],
    errors,
  );
  const route = await load(
    () => (readers?.readRoute ?? readPersistedRoute)(target, packageRoot, { taskId: effectiveTaskId, routePath }),
    "E_PHASE_PREREQUISITE_MISSING",
    `EXECUTING requires ${routeRel}`,
    [routeRel],
    errors,
  );
  if (!contract || !route) return { errors, requiredArtifacts, contract, route };

  if (state.routeFingerprint !== route.fingerprint) {
    errors.push(issue(
      "E_ROUTE_STALE",
      "EXECUTING requires work state and route to match the current contract",
      [stateRel, routeRel, contractRel],
    ));
  }
  errors.push(...stateIdentityErrors({ contract, route, state }));

  const freshness = await (readers?.classifyState ?? classifyLoadedWorkState)({
    target,
    state,
    contractFile: contractRel,
  });
  errors.push(...freshnessErrors(state, freshness));

  const preflight = await evaluatePreflight({ target, packageRoot, taskId: effectiveTaskId, contractPath, routePath, statePath, readers });
  let persistedPreflight = null;
  let persistedPreflightReadError = null;
  try {
    persistedPreflight = await (readers?.readPreflight ?? readJsonArtifact)(target, preflightRel, "preflight", packageRoot);
  } catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    persistedPreflightReadError = error;
    // validatePersistedPreflight reports the stable, actionable preflight reason.
  }
  const persistedPreflightErrors = validatePersistedPreflight(persistedPreflight?.value, preflight, persistedPreflightReadError);
  if (!sameStringSet(state.requiredGates, preflight.requiredGates)
    || !sameStringSet(state.satisfiedGates, preflight.satisfiedGates)) {
    errors.push(issue(
      "E_PREFLIGHT_GATES_STALE",
      "Work state gate sets do not match the current preflight evaluation",
      [stateRel, preflightRel, ARTIFACT_PATHS.gates],
    ));
  }

  const ledger = await (readers?.validateLedger ?? validateEventLedger)(target, packageRoot, { taskId: effectiveTaskId, eventsPath });
  errors.push(...prerequisiteLedgerErrors(ledger, contract.value.taskId, preflight, route));
  errors.push(...validateStateLedgerCoherence(state, ledger.events).map((error) => issue(
    error.code,
    error.message,
    [stateRel, eventsRel],
  )));
  errors.push(...persistedPreflightErrors);
  return { errors, requiredArtifacts, contract, route, preflight, persistedPreflight, ledger };
}

function freshnessErrors(state, freshness) {
  if (freshness.status !== "REVALIDATION_REQUIRED") return [];
  return [issue(
    "E_STATE_REVALIDATION_REQUIRED",
    `EXECUTING requires a fresh work-state checkpoint: ${freshness.reasons.join(", ")}`,
    [
      ARTIFACT_PATHS.state,
      ARTIFACT_PATHS.contract,
      ...(state.requiredArtifacts?.map((artifact) => artifact.path) ?? []),
    ],
  )];
}

export function hasExecutionStarted(phase) {
  return POST_EXECUTION_PHASES.has(phase);
}

function issue(code, message, artifacts = []) {
  return { code, message, artifacts };
}

async function load(loadArtifact, code, message, artifacts, errors) {
  try {
    return await loadArtifact();
  } catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    errors.push(issue(code, `${message}: ${error.message}`, artifacts));
    return null;
  }
}

export function prerequisiteError(prerequisites) {
  const first = prerequisites.errors[0];
  if (!first) return null;
  const error = new Error(first.message);
  error.code = first.code;
  error.artifacts = first.artifacts;
  return error;
}

function prerequisiteLedgerErrors(ledger, taskId, preflight, route) {
  const errors = (ledger.errors ?? []).map((error) => issue(
    error.code ?? "E_PHASE_CHRONOLOGY_INVALID",
    error.message,
    [ARTIFACT_PATHS.events],
  ));
  const events = ledger.events ?? [];
  if (events.some((event) => event.taskId !== taskId)) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      "EXECUTING requires protocol prerequisite events to belong to the current task",
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.state, ARTIFACT_PATHS.contract],
    ));
    return errors;
  }
  const currentEvents = events.filter((event) => event.taskId === taskId);
  for (const requiredEvent of START_EXECUTION_EVENTS) {
    if (!currentEvents.some((event) => event.event === requiredEvent)) {
      errors.push(issue(
        "E_PHASE_CHRONOLOGY_INVALID",
        `EXECUTING requires a ${requiredEvent} protocol event`,
        [ARTIFACT_PATHS.events],
      ));
    }
  }
  // Bind to the latest PREFLIGHT_READY: an append-only lifecycle may contain an
  // older READY event superseded by a BLOCKED outcome and a fresh READY with
  // current details (see preflight-reactivation recovery).
  const preflightEvent = currentEvents.findLast((event) => event.event === "PREFLIGHT_READY");
  if (preflightEvent && (!sameStringSet(preflightEvent.details?.requiredGates, preflight.requiredGates)
    || !sameStringSet(preflightEvent.details?.satisfiedGates, preflight.satisfiedGates))) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      "PREFLIGHT_READY event gate sets do not match the current READY preflight",
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight],
    ));
  }
  if (preflightEvent && preflightEvent.fingerprint !== preflight.fingerprints.contract) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      PREFLIGHT_CONTRACT_IDENTITY_ERROR_MESSAGE,
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight, ARTIFACT_PATHS.contract],
    ));
  }
  if (preflightEvent && (preflightEvent.details?.routingFingerprint !== preflight.fingerprints.routing
    || preflightEvent.details?.routingFingerprint !== route.fingerprint)) {
    errors.push(issue(
      "E_PHASE_CHRONOLOGY_INVALID",
      PREFLIGHT_ROUTE_IDENTITY_ERROR_MESSAGE,
      [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight, ARTIFACT_PATHS.route],
    ));
  }
  const latestContractRevisionSeq = currentEvents.findLast((event) => event.event === "CONTRACT_REVISED")?.seq ?? 0;
  const currentEpochSatisfiedGates = new Set(preflight.requiredGates.filter((gate) => (
    hasCurrentGateEvidence(currentEvents, taskId, gate, latestContractRevisionSeq)
  )));
  for (const gate of preflight.requiredGates) {
    if (!currentEpochSatisfiedGates.has(gate)) {
      errors.push(issue(
        "E_PHASE_CHRONOLOGY_INVALID",
        `execution started before current-contract gate satisfaction: ${gate}`,
        [ARTIFACT_PATHS.events, ARTIFACT_PATHS.preflight],
      ));
    }
  }
  return errors;
}

function sameStringSet(left, right) {
  if (!Array.isArray(left) || !Array.isArray(right)) return false;
  return left.length === new Set(left).size
    && right.length === new Set(right).size
    && left.length === right.length
    && left.every((value) => right.includes(value));
}

function contextError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

export function projectExecutionProfileContext({
  taskId,
  contract,
  route,
  state,
  nextAction,
  runtimeContext,
} = {}) {
  if (typeof taskId !== "string" || !taskId) throw contextError("E_TASK_REQUIRED", "taskId is required");
  if (!contract || typeof contract !== "object" || Array.isArray(contract)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "contract is required for profile-aware context");
  }
  if (!route || typeof route !== "object" || Array.isArray(route)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "route is required for profile-aware context");
  }
  if (!state || typeof state !== "object" || Array.isArray(state)) {
    throw contextError("E_EXECUTION_PROFILE_CONTEXT_INVALID", "work state is required for profile-aware context");
  }
  const profile = route.executionProfile ? assertExecutionProfile(route.executionProfile) : legacyExecutionProfile();
  const resolvedProfile = profile.resolved;
  const policy = getExecutionProfileContextPolicy(resolvedProfile);
  const available = [...OPTIONAL_CONTEXT_BY_PROFILE[resolvedProfile]];
  const advisoryProviders = runtimeContext?.advisoryContextProviders;
  const hasAdvisory = Boolean(
    advisoryProviders && (
      advisoryProviders instanceof Map
        ? advisoryProviders.size > 0
        : Object.keys(advisoryProviders).length > 0
    ),
  );
  if (hasAdvisory && !available.includes("advisory-context")) {
    available.push("advisory-context");
  }
  return {
    schemaVersion: 1,
    protocolVersion: 1,
    taskId,
    executionProfile: profile,
    phase: state.phase,
    nextAction: nextAction?.nextAction ?? null,
    objective: contract.objective ?? null,
    deliverables: [...(contract.deliverables ?? [])],
    constraints: [...(contract.constraints ?? [])],
    selectedGuideIds: [...(state.selectedGuides ?? [])],
    verificationRequirements: verificationRequirements(contract),
    contextPolicy: policy,
    optionalContext: {
      available,
      loaded: [],
    },
    invariants: { ...PROFILE_INVARIANTS },
  };
}

export function projectExecutionProfile(route) {
  if (!route || typeof route !== "object") return null;
  return route.executionProfile?.resolved ?? LEGACY_EXECUTION_PROFILE;
}

function executionError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function validateExecutionBinding({ execution, taskId, checkId, requirement, verificationCycle = 1 } = {}) {
  if (!execution || execution.kind !== "COMMAND_EXECUTION"
    || execution.taskId !== taskId
    || execution.checkId !== checkId
    || execution.requirement !== requirement
    || execution.verificationCycle !== undefined && execution.verificationCycle !== verificationCycle) {
    throw executionError("E_EXECUTION_REF_INVALID", "Execution artifact does not match the current check binding", [ARTIFACT_PATHS.executionDirectory]);
  }
  return execution;
}

export function projectFailureSignatures({ state = null, events = [] } = {}) {
  const byCycle = new Map();
  const record = (cycle, details) => {
    if (details.status !== "failed" && details.status !== "blocked") return;
    const requirement = details.requirement ?? details.id ?? details.checkId;
    if (!requirement) return;
    const signature = computeFailureSignature({
      requirement,
      status: details.status,
      exitCode: Number.isInteger(details.exitCode) ? details.exitCode : null,
      failureToken: failureTokenOf(details),
    });
    if (!byCycle.has(cycle)) byCycle.set(cycle, new Map());
    const cycleMap = byCycle.get(cycle);
    if (!cycleMap.has(signature)) cycleMap.set(signature, { signature, requirements: new Set(), cycles: new Set() });
    cycleMap.get(signature).requirements.add(requirement);
    cycleMap.get(signature).cycles.add(cycle);
  };

  for (const event of events) {
    if (event.event !== "VERIFICATION_RECORDED") continue;
    record(event.details?.verificationCycle ?? 1, event.details ?? {});
  }
  for (const check of state?.checks ?? []) {
    if (check.status !== "failed" && check.status !== "blocked") continue;
    record(check.details?.verificationCycle ?? state?.verificationCycle ?? 1, check);
  }

  const signaturesByIdentity = new Map();
  for (const [, cycleMap] of [...byCycle.entries()].sort(([a], [b]) => a - b)) {
    for (const [signature, entry] of cycleMap) {
      if (!signaturesByIdentity.has(signature)) signaturesByIdentity.set(signature, { signature, cycles: [], requirements: new Set() });
      const aggregated = signaturesByIdentity.get(signature);
      aggregated.cycles.push(...entry.cycles);
      for (const requirement of entry.requirements) aggregated.requirements.add(requirement);
    }
  }

  return [...signaturesByIdentity.values()]
    .map((entry) => ({ ...entry, cycles: [...new Set(entry.cycles)].sort((a, b) => a - b), requirements: [...entry.requirements].sort() }))
    .sort((a, b) => a.signature.localeCompare(b.signature));
}

export function projectFailureSurfaces({ state = null, events = [] } = {}) {
  const failedRequirementsByCycle = new Map();
  // Track every canonically verified cycle so a successful verification
  // appears explicitly as surface: [] instead of silently disappearing.
  const knownCycles = new Set();
  const record = (cycle, requirement) => {
    if (!Number.isInteger(cycle)) cycle = Number(cycle) || 1;
    knownCycles.add(cycle);
    if (!failedRequirementsByCycle.has(cycle)) failedRequirementsByCycle.set(cycle, new Set());
    if (!requirement) return;
    failedRequirementsByCycle.get(cycle).add(requirement);
  };
  const knowCycle = (cycle) => {
    if (Number.isInteger(cycle)) knownCycles.add(cycle);
  };

  for (const event of events) {
    if (event.event === "VERIFICATION_STARTED") {
      knowCycle(event.details?.verificationCycle);
    }
    if (event.event !== "VERIFICATION_RECORDED") continue;
    const d = event.details ?? {};
    if (d.status === "failed" || d.status === "blocked") {
      record(d.verificationCycle ?? 1, d.requirement ?? d.id ?? d.checkId);
    } else {
      knowCycle(d.verificationCycle);
    }
  }

  for (const check of state?.checks ?? []) {
    knowCycle(check.details?.verificationCycle ?? state?.verificationCycle ?? 1);
    if (check.status !== "failed" && check.status !== "blocked") continue;
    record(check.details?.verificationCycle ?? state?.verificationCycle ?? 1, check.requirement ?? check.id ?? check.checkId);
  }
  for (const cycle of knownCycles) {
    if (!failedRequirementsByCycle.has(cycle)) failedRequirementsByCycle.set(cycle, new Set());
  }

  return [...failedRequirementsByCycle.entries()]
    .sort(([a], [b]) => a - b)
    .map(([verificationCycle, requirements]) => ({
      verificationCycle,
      surface: [...requirements].sort(),
      size: requirements.size,
    }));
}

function gateName(value) {
  if (typeof value !== "string" || !/^[a-z0-9][a-z0-9-]*$/.test(value)) {
    const error = new Error(`Invalid gate name: ${value}`);
    error.code = "E_GATE_INVALID";
    throw error;
  }
  return value;
}

export function gatePath(gate, options = {}) {
  const name = gateName(gate);
  if (options?.taskId) {
    return taskGatePath(options.taskId, name);
  }
  return `${ARTIFACT_PATHS.gates ?? ".forgeloop/gates"}/${name}.json`;
}

export async function validateGateArtifacts(target, gateValue, packageRoot) {
  return withNativeReadScope(target, async () => {
    const schema = await readSchema("gate", packageRoot);
    assertSchema(gateValue, schema, "gate");
    const stale = [];
    for (const artifact of gateValue.artifacts ?? []) {
      await assertSafePath(target, artifact.path);
      const canonical = readCanonicalGateArtifactBinding(target, artifact.path);
      if (canonical) {
        if (canonical.sha256 === null) stale.push({ path: artifact.path, status: "missing" });
        else if (canonical.sha256 !== artifact.sha256) stale.push({ path: artifact.path, status: "changed" });
        continue;
      }
      const artifactPath = ensureWithin(target, artifact.path);
      if (!(await fileExists(artifactPath))) {
        stale.push({ path: artifact.path, status: "missing" });
        continue;
      }
      const binding = await hashGateFile(target, artifact.path);
      if (binding.sha256 !== artifact.sha256) stale.push({ path: artifact.path, status: "changed" });
    }
    return stale;
  });
}

export function hasCurrentGateEvidence(events, taskId, gate, latestContractRevisionSeq = 0) {
  return events.some((event) => [GATE_SATISFIED_EVENT, GATE_REVALIDATED_EVENT].includes(event.event)
    && event.taskId === taskId
    && event.details?.gate === gate
    && event.seq > latestContractRevisionSeq);
}

export async function completionEvidenceForGuides(guides, packageRoot) {
  const metadata = await readGuideMetadata(packageRoot);
  return [...new Set(guides.flatMap((guide) => metadata[guide]?.completionEvidence ?? []))].sort();
}

function parseFrontmatter(text, relativePath) {
  const match = text.match(/^---\s*\n([\s\S]*?)\n---\s*\n/);
  if (!match) throw new Error(`${relativePath} is missing YAML frontmatter`);
  const frontmatter = match[1];
  const guideId = frontmatter.match(/^guide-id:\s*([^\s]+)\s*$/m)?.[1] ?? null;
  const lastReviewed = frontmatter.match(/^last-reviewed:\s*"?([^"\r\n]+)"?\s*$/m)?.[1] ?? null;
  const version = frontmatter.match(/^version:\s*"?([^"\r\n]+)"?\s*$/m)?.[1] ?? null;
  return {
    guideId,
    lastReviewed,
    version,
    requiresGates: parseList(frontmatter, "requires-gates"),
    completionEvidence: parseList(frontmatter, "completion-evidence"),
  };
}

function parseList(frontmatter, key) {
  const lines = frontmatter.split(/\r?\n/);
  const start = lines.findIndex((line) => line.trim() === `${key}:`);
  if (start < 0) return [];
  const values = [];
  for (const line of lines.slice(start + 1)) {
    if (!/^\s+-\s+/.test(line)) break;
    values.push(line.replace(/^\s+-\s+/, "").trim());
  }
  return values.filter(Boolean);
}

export async function readGuideMetadata(packageRoot) {
  const metadata = {};
  for (const [id, relativePath] of Object.entries(GUIDE_FILES)) {
    const text = await readFile(path.join(packageRoot, relativePath), "utf8");
    const parsed = parseFrontmatter(text, relativePath);
    metadata[id] = {
      guideId: parsed.guideId ?? id,
      lastReviewed: parsed.lastReviewed,
      version: parsed.version,
      requiresGates: [...parsed.requiresGates],
      completionEvidence: [...parsed.completionEvidence],
      path: relativePath,
    };
  }
  return metadata;
}

export async function requiredGatesForGuides(guides, packageRoot) {
  const metadata = await readGuideMetadata(packageRoot);
  return [...new Set(guides.flatMap((guide) => metadata[guide]?.requiresGates ?? []))].sort();
}

export function compareRepositoryFingerprint(expected, current) {
  const expectedUnavailable = !expected || (expected.branch === null && expected.head === null);
  const currentUnavailable = !current || (current.branch === null && current.head === null);
  if (expectedUnavailable && currentUnavailable) return "NOT_VERIFIED";
  if (expectedUnavailable !== currentUnavailable) return "MISMATCH";
  return expected.branch === current.branch && expected.head === current.head
    ? "MATCH"
    : "MISMATCH";
}

function handoffError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "HandoffError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function handoffWithoutDigest(value) {
  const { artifactDigest: _artifactDigest, ...body } = value;
  return body;
}

function optionalText(value, label, maxLength = 2000) {
  if (value === undefined || value === null) return null;
  try {
    return normalizePortableText(value, { label, maxLength, optional: true });
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", `${label} must be a non-empty string when provided`);
  }
}

function pathList(value) {
  return [...new Set((value ?? []).map((item) => String(item).replaceAll("\\", "/")))].sort();
}

export async function resolveLatestHandoff(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  const handoffs = await listCanonicalHandoffs(target, { taskId, packageRoot });
  const latest = handoffs.at(-1);
  return latest
    ? { handoffId: latest.handoffId, createdAt: latest.createdAt, digest: latest.artifactDigest }
    : null;
}

export async function validateCanonicalHandoff(target, handoff, {
  taskId,
  packageRoot = getPackageRoot(),
} = {}) {
  const { readSchema, assertSchema } = await import("./schema-validation.js");
  try {
    assertSchema(handoff, await readSchema("handoff-envelope", packageRoot), "handoff envelope");
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", error.message);
  }
  if (taskId && handoff.taskId !== taskId) {
    throw handoffError("E_HANDOFF_INVALID", "Handoff taskId does not match the selected task");
  }
  return validateHandoffDigest(handoff);
}

export function validateHandoffDigest(handoff) {
  try {
    assertPortableContextSafe(handoff);
  } catch (error) {
    throw handoffError("E_HANDOFF_INVALID", error.message);
  }
  if (typeof handoff?.artifactDigest !== "string"
    || handoff.artifactDigest !== canonicalFingerprint(handoffWithoutDigest(handoff))) {
    throw handoffError("E_HANDOFF_TAMPERED", "Handoff artifact digest does not match its canonical content");
  }
  return handoff;
}

export async function buildTaskHistory({
  target,
  packageRoot,
  taskId = null,
  filters = {},
} = {}) {
  const projection = historyEventProjection(filters);
  const trace = await buildTaskTrace({ target, packageRoot, taskId }, projection);
  const events = trace.events;
  const omittedEvents = projection.omittedEvents;

  const checkAttempts = trace.checks.reduce(
    (total, check) => total + check.attemptCount,
    0,
  );
  const failedAttempts = trace.checks.reduce(
    (total, check) => total + check.failedAttempts,
    0,
  );

  return {
    schemaVersion: 1,
    command: "history",
    task: trace.task,
    snapshot: trace.snapshot,
    summary: {
      eventCount: events.length,
      totalEventCount: trace.totalEventCount,
      checkAttemptCount: checkAttempts,
      failedAttemptCount: failedAttempts,
      diagnosticCaseCount: trace.diagnostics.cases.length,
      interventionCount: trace.diagnostics.interventions.length,
    },
    historyQuality: trace.historyQuality,
    integrity: trace.integrity,
    events,
    ...(omittedEvents > 0 ? { truncated: true, truncation: { reason: "OUTPUT_LIMIT", omittedEvents } } : {}),
  };
}

function historyEventProjection(filters) {
  const predicates = [];
  for (const key of ["type", "phase"]) {
    if (!filters[key]) continue;
    const values = String(filters[key]).split(",").map(value => value.trim()).filter(Boolean);
    if (values.length) predicates.push(event => values.includes(event[key])
      || (key === "type" && values.includes(event.category)));
  }
  if (filters.failures) predicates.push(event => event.category === "verification"
    && ["failed", "blocked"].includes(String(event.data?.status ?? "")));
  if (filters.checks) predicates.push(event => event.category === "verification");
  for (const key of ["since", "until"]) {
    if (!filters[key]) continue;
    const bound = Date.parse(filters[key]);
    if (!Number.isNaN(bound)) predicates.push(event => event.timestamp
      && (key === "since" ? Date.parse(event.timestamp) >= bound : Date.parse(event.timestamp) <= bound));
  }
  const limit = Number.isInteger(filters.limit) && filters.limit >= 0 ? filters.limit : null;
  const events = [];
  let matched = 0;
  let cursor = 0;
  return {
    add(event) {
      if (!predicates.every(predicate => predicate(event))) return;
      matched += 1;
      if (limit === 0) return;
      if (limit === null || events.length < limit) events.push(event);
      else { events[cursor] = event; cursor = (cursor + 1) % limit; }
    },
    result: () => cursor === 0 ? events : events.slice(cursor).concat(events.slice(0, cursor)),
    get omittedEvents() { return matched - events.length; },
  };
}

export function getHypothesisState(projection, id) {
  return projection?.hypotheses.find((hypothesis) => hypothesis.id === id) ?? null;
}

export function projectHypothesisStates(events, { taskId = null } = {}) {
  const ordered = [...events].sort((a, b) => (a.seq ?? 0) - (b.seq ?? 0));
  const byId = new Map();
  const invalidTransitions = [];

  const ensure = (id, seq, cycle) => {
    if (!byId.has(id)) {
      const state = blankState(id);
      state.sourceEventSeq = seq ?? null;
      state.sourceCycle = cycle ?? null;
      byId.set(id, state);
    }
    return byId.get(id);
  };

  for (const event of ordered) {
    if (taskId && event.taskId && event.taskId !== taskId) continue;
    const details = event.details ?? {};
    if (event.event === "DIAGNOSTIC_CASE_RECORDED") {
      for (const hypothesis of details.hypotheses ?? []) {
        if (!hypothesis?.id) continue;
        ensure(hypothesis.id, event.seq, details.verificationCycle);
      }
    } else if (event.event === "DIAGNOSIS_RECORDED") {
      ensure(HYPOTHESIS_LEGACY_ID, event.seq, details.verificationCycle);
    } else if (event.event === "HYPOTHESIS_DISPOSITION_RECORDED") {
      const ref = details.hypothesisRef;
      if (!ref || !details.status) continue;
      const state = ensure(ref, null, null);
      if (!canTransition(state.currentStatus, details.status)) {
        invalidTransitions.push({
          sequence: event.seq,
          hypothesisRef: ref,
          from: state.currentStatus,
          to: details.status,
        });
        continue;
      }
      state.currentStatus = details.status;
      state.dispositionHistory.push({
        sequence: event.seq,
        status: details.status,
        evidenceRefs: [...(details.evidenceRefs ?? [])],
        reason: details.reason ?? null,
      });
    }
  }

  const hypotheses = [...byId.values()].sort((a, b) => a.id.localeCompare(b.id));
  return {
    hypotheses,
    openHypotheses: hypotheses.filter((hypothesis) => hypothesis.currentStatus === "OPEN").map((hypothesis) => hypothesis.id),
    invalidTransitions,
  };
}

export function buildInformationGainProjection(events, taskId) {
  return [...iterateInformationGainProjection(events, taskId)];
}

export function evaluateStructuredDiagnosticStall(gainProjection, { verificationCycle = null } = {}) {
  const candidates = verificationCycle === null || verificationCycle === undefined
    ? (gainProjection ?? [])
    : (gainProjection ?? []).filter((entry) => entry.verificationCycle === verificationCycle);

  const latest = candidates.at(-1) ?? null;
  if (!latest) {
    return { stalled: false, latestGain: null, reason: null };
  }
  if (latest.classification === "FIRST_DIAGNOSIS") {
    return { stalled: false, latestGain: latest, reason: null };
  }
  const stalled = latest.effectiveGain === false;
  return {
    stalled,
    latestGain: latest,
    reason: stalled ? "NO_DIAGNOSTIC_INFORMATION_GAIN" : null,
  };
}

function profileMetadata(bytes) {
  const text = bytes.toString("utf8");
  return {
    mode: text.match(/^profile-mode:\s*([^\s]+)\s*$/m)?.[1] ?? null,
    status: text.match(/^profile-status:\s*([^\s]+)\s*$/m)?.[1] ?? null,
  };
}

function reasonCodesFor({ state, trace, progress }) {
  const codes = [];
  codes.push(trace.integrity.valid ? "LEDGER_VALID" : "LEDGER_INCONSISTENT");
  if (state?.status === "VALID" || state?.status === "FRESH") codes.push("REPOSITORY_FRESH");
  if (["STALE", "REVALIDATION_REQUIRED"].includes(state?.status)) codes.push("REPOSITORY_STALE");
  if (trace.task.phase === "COMPLETE") codes.push("COMPLETION_VALID");
  else codes.push("COMPLETION_INCOMPLETE");
  if (progress.status === "ADVANCING") codes.push("DIAGNOSTIC_PROGRESS_ADVANCING");
  if (progress.status === "STALLED") codes.push("DIAGNOSTIC_PROGRESS_STALLED");
  return codes;
}

function structuralQualityIssues(quality, taskId) {
  if (!quality || quality.mode !== "gate") return [];
  const qualityPath = quality.current?.artifactRef ?? taskStructuralQualityDirectory(taskId);
  if (quality.baseline?.status !== "OBSERVED") {
    return [{
      code: "E_STRUCTURAL_QUALITY_BASELINE_MISSING",
      message: "Structural-quality gate evidence has no valid immutable baseline.",
      path: taskStructuralQualityDirectory(taskId),
    }];
  }
  if (!quality.current?.artifactRef) {
    return [{
      code: "E_STRUCTURAL_QUALITY_EVIDENCE_STALE",
      message: "Structural-quality gate has no evaluation for the current verification cycle.",
      path: qualityPath,
    }];
  }
  if (quality.current.status === "FAIL") {
    return [{
      code: "E_STRUCTURAL_QUALITY_REGRESSION",
      message: "Structural-quality verification detected a regression.",
      path: qualityPath,
    }];
  }
  if (quality.current.status === "BLOCKED") {
    return [{
      code: "E_STRUCTURAL_QUALITY_EVALUATION_INCOMPARABLE",
      message: "Structural-quality verification is blocked or incomparable.",
      path: qualityPath,
    }];
  }
  return [];
}

export function getInstallationAuthorityRef(check) {
  return (
    check?.details?.installationAuthorityRef
    ?? check?.details?.authorityRef
    ?? check?.installationAuthorityRef
    ?? check?.authorityRef
    ?? null
  );
}

function normalizeToolName(toolName) {
  if (typeof toolName !== "string") return "";
  if (toolName.startsWith("@")) {
    const parts = toolName.slice(1).split("@");
    return `@${parts[0]}`;
  }
  return toolName.split("@")[0];
}

export function validateAuthorityGrant({ authority, taskId, type = "SOFTWARE_INSTALLATION", tool } = {}) {
  if (!authority || typeof authority !== "object") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: "Authority grant artifact is missing or invalid",
      },
    };
  }

  if (authority.schemaVersion !== 1 || authority.protocolVersion !== 1) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant schema version (${authority.schemaVersion}) or protocol version (${authority.protocolVersion}) is invalid`,
      },
    };
  }

  if (authority.type !== type) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant type '${authority.type}' does not match expected '${type}'`,
      },
    };
  }

  if (authority.status !== "AUTHORIZED") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant is not active (status: '${authority.status}')`,
      },
    };
  }

  if (authority.source === "agent-self") {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: "Self-asserted authority grants with source 'agent-self' are not permitted",
      },
    };
  }

  if (!["operator", "host", "project-policy"].includes(authority.source)) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant source '${authority.source}' is not recognized`,
      },
    };
  }

  if (taskId && authority.taskId && authority.taskId !== taskId) {
    return {
      valid: false,
      error: {
        code: E_AUTHORITY_INVALID,
        message: `Authority grant taskId '${authority.taskId}' does not match current task '${taskId}'`,
      },
    };
  }

  if (tool && authority.scope?.tool && authority.scope.tool !== "*") {
    const requestedNorm = normalizeToolName(tool);
    const scopeNorm = normalizeToolName(authority.scope.tool);
    const exactMatch = authority.scope.tool === tool
      || tool.startsWith(`${authority.scope.tool}@`)
      || authority.scope.tool.startsWith(`${tool}@`)
      || requestedNorm === scopeNorm;

    if (!exactMatch) {
      return {
        valid: false,
        error: {
          code: E_AUTHORITY_SCOPE_MISMATCH,
          message: `Authority grant scope tool '${authority.scope.tool}' does not match requested verification tool '${tool}'`,
        },
      };
    }
  }

  return { valid: true, error: null };
}

export function validateVerificationAuthority(check, options = {}) {
  const canonicalResolution = check?.execution?.resolution ?? check?.details?.execution?.resolution;
  const command = check?.details?.command
    ?? (check?.kind === "command" && typeof check?.source === "string" && !check.source.startsWith("check:")
      ? check.source
      : null);

  if (!canonicalResolution && (!command || typeof command !== "string")) return { valid: true, error: null };

  const classification = canonicalResolution ?? classifyCommandResolution(command);
  if (!classification.mayInstall) return { valid: true, error: null };

  const authorityRef = getInstallationAuthorityRef(check);
  if (!authorityRef) {
    return {
      valid: false,
      error: {
        code: E_INSTALLATION_AUTHORITY_REQUIRED,
        message: `Verification command '${command}' uses installation-capable resolution (${classification.resolutionMode}) without recorded installation authority reference`,
      },
    };
  }

  const resolved = resolveTrustedAuthority({
    authorityRef,
    target: options.target,
    trustedAuthorityFile: options.trustedAuthorityFile,
    trustedAuthorityDir: options.trustedAuthorityDir,
    authorities: options.authorities,
    authority: options.authority,
    authorityContext: options.authorityContext,
    runtimeContext: options.runtimeContext,
  });
  if (!resolved.trusted) {
    if (resolved.error?.code === E_AUTHORITY_INVALID && resolved.sourceConfigured === false) {
      return {
        valid: false,
        error: {
          code: E_INSTALLATION_AUTHORITY_REQUIRED,
          message: "Installation-capable verification requires a host-attested authority context",
        },
      };
    }
    return { valid: false, error: resolved.error };
  }

  return validateAuthorityGrant({
    authority: resolved.authority,
    taskId: options.taskId,
    type: "SOFTWARE_INSTALLATION",
    tool: classification.tool,
  });
}

function ownershipProjection(projection) {
  return {
    taskId: projection.taskId,
    phase: projection.phase,
    claimState: projection.claimState,
    mutationAllowed: projection.mutationAllowed,
    ownershipValid: projection.ownershipValid,
    recoveryStatus: projection.recoveryStatus,
    historicalWriteClaims: [...projection.historicalWriteClaims],
    effectiveWriteClaims: [...projection.effectiveWriteClaims],
    reasonCodes: [...projection.reasonCodes],
  };
}

async function readCapturedDecisions(store, taskId, packageRoot) {
  const decisions = [];
  for (const entry of store.captureDecisionTexts(taskId)) {
    if (entry.error) throw entry.error;
    decisions.push((await parseCapturedJsonArtifact(entry.text, entry.relativePath, "semantic-decision", packageRoot)).value);
  }
  return decisions;
}

export function isLedgerEventCollection(events) {
  return Array.isArray(events) || collections.has(events);
}

export function* ledgerEntriesOfTypes(events, types) {
  if (!Array.isArray(events)) { yield* events.entriesOfTypes(types); return; }
  const selected = new Set(types);
  for (const [index, event] of events.entries()) if (selected.has(event.event)) yield [index, event];
}

export function ledgerEventAt(events, index) {
  return Array.isArray(events) ? events[index] : (Number.isSafeInteger(index) && index >= 0 ? events.at(index) : undefined);
}

export function ledgerEventAtIs(events, index, event) {
  if (Array.isArray(events)) return events[index] === event;
  return Number.isSafeInteger(index) && index >= 0 && index < events.length && events.indexOf(event) === index;
}

export function* ledgerEventsOfTypes(events, types) {
  for (const [, event] of ledgerEntriesOfTypes(events, types)) yield event;
}

export function ledgerTypeSummary(events, type) {
  let count = 0;
  let first;
  let latest;
  for (const event of ledgerEventsOfTypes(events, [type])) {
    if (!count) first = event;
    latest = event;
    count += 1;
  }
  return { count, first, latest };
}

export async function readManifest(target) {
  await assertSafePath(target, MANIFEST_PATH);
  const manifestPath = ensureWithin(target, MANIFEST_PATH);
  if (!(await fileExists(manifestPath))) return null;
  let raw;
  try {
    const bytes = await readFile(manifestPath);
    assertJsonBytes(bytes, MANIFEST_PATH);
    raw = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(raw, MANIFEST_PATH);
  } catch (error) {
    throw new Error(`Unable to parse ${MANIFEST_PATH}: ${error.message}`);
  }
  return validateManifest(raw);
}

export function sha256(bytes) {
  return createHash("sha256").update(bytes).digest("hex");
}

function validateManifest(manifest) {
  if (!manifest || typeof manifest !== "object") {
    throw new Error("Manifest must contain a JSON object");
  }
  if (manifest.schemaVersion !== MANIFEST_SCHEMA_VERSION) {
    throw new Error(`Unsupported manifest schema: ${manifest.schemaVersion}`);
  }
  if (manifest.layoutVersion !== undefined
    && ![LEGACY_LAYOUT_VERSION, LAYOUT_VERSION].includes(manifest.layoutVersion)) {
    throw new Error(`Unsupported manifest layout: ${manifest.layoutVersion}`);
  }
  if (typeof manifest.packageVersion !== "string" || !manifest.packageVersion) {
    throw new Error("Manifest packageVersion is required");
  }
  if (!manifest.files || typeof manifest.files !== "object" || Array.isArray(manifest.files)) {
    throw new Error("Manifest files must be an object");
  }

  for (const [relativePath, record] of Object.entries(manifest.files)) {
    ensureWithin("/manifest-root", relativePath);
    if (!record || typeof record.sha256 !== "string" || !/^[a-f0-9]{64}$/.test(record.sha256)) {
      throw new Error(`Invalid manifest hash for ${relativePath}`);
    }
    if (typeof record.preserve !== "boolean") {
      throw new Error(`Invalid manifest preserve flag for ${relativePath}`);
    }
    if (record.legacySha256 !== undefined
      && (typeof record.legacySha256 !== "string" || !/^[a-f0-9]{64}$/.test(record.legacySha256))) {
      throw new Error(`Invalid manifest legacy hash for ${relativePath}`);
    }
  }
  return manifest;
}

export async function writeManifest(target, manifest, { dryRun = false } = {}) {
  validateManifest(manifest);
  await assertSafePath(target, MANIFEST_PATH);
  const manifestPath = ensureWithin(target, MANIFEST_PATH);
  await writeFileAtomic(
    manifestPath,
    `${JSON.stringify(manifest, null, 2)}\n`,
    { dryRun },
  );
}

function array(value) {
  return Array.isArray(value) ? value.filter((item) => typeof item === "string") : [];
}

function contractText(contract) {
  if (!contract || typeof contract !== "object" || Array.isArray(contract)) return "";
  const values = [contract.objective, contract.summary, ...(contract.deliverables ?? []), ...(contract.successCriteria ?? []), ...(contract.risks ?? []), ...(contract.constraints ?? [])];
  return values.map((value) => value && typeof value === "object" ? value.text : value).filter((value) => typeof value === "string").join(" ").toLowerCase();
}

function deterministicFloor(input) {
  const normalized = normalizedInput(input);
  const reasons = [];
  const combined = `${contractText(normalized.contract)} ${normalized.workType} ${normalized.surfaces.join(" ")} ${normalized.risks.join(" ")}`;
  const generationRequired = normalized.generationRequired
    || normalized.behaviorChange
    || normalized.executableChange
    || GENERATION_WORK_TYPES.has(normalized.workType)
    || /\b(implement|fix|refactor|change|build|generate|write|modify|code)\b/.test(combined);
  const primary = normalized.architectureChange
    || normalized.ambiguity
    || PRIMARY_WORK_TYPES.has(normalized.workType)
    || normalized.risks.some((risk) => PRIMARY_RISKS.has(risk))
    || normalized.surfaces.some((surface) => PRIMARY_SURFACES.has(surface))
    || /\b(architecture|architectural|security boundary|migration|ambiguous|unknown requirements)\b/.test(combined);

  if (!generationRequired) {
    reasons.push("NO_GENERATION_REQUIRED");
    return { floor: "NONE", reasons };
  }
  reasons.push("GENERATION_REQUIRED");
  if (primary) {
    reasons.push("PRIMARY_COMPLEXITY_OR_RISK");
    return { floor: "PRIMARY", reasons };
  }
  reasons.push("STANDARD_GENERATION_FLOOR");
  return { floor: "STANDARD", reasons };
}

function normalizeRecommendation(recommendation) {
  if (recommendation === null || recommendation === undefined) return null;
  if (typeof recommendation === "string") {
    return MODEL_ROUTE_TIERS.includes(recommendation) ? { tier: recommendation, confidence: null, requiresEscalation: false } : null;
  }
  if (!recommendation || typeof recommendation !== "object" || Array.isArray(recommendation)) return null;
  const tier = typeof recommendation.tier === "string" && MODEL_ROUTE_TIERS.includes(recommendation.tier) ? recommendation.tier : null;
  if (!tier) return null;
  return {
    tier,
    confidence: typeof recommendation.confidence === "number" && Number.isFinite(recommendation.confidence) ? recommendation.confidence : null,
    requiresEscalation: recommendation.requiresEscalation === true,
  };
}

function normalizedInput(input = {}) {
  return {
    workType: text(input.workType),
    surfaces: array(input.surfaces).map(text),
    risks: array(input.risks).map(text),
    platforms: array(input.platforms).map(text),
    behaviorChange: input.behaviorChange === true,
    executableChange: input.executableChange === true,
    generationRequired: input.generationRequired === true,
    architectureChange: input.architectureChange === true,
    ambiguity: input.ambiguity === true,
    contract: input.contract,
  };
}

export function resolveModelRoute({ input = {}, semanticRecommendation = null } = {}) {
  const deterministic = deterministicFloor(input);
  const recommendation = normalizeRecommendation(semanticRecommendation);
  let resolved = deterministic.floor;
  const reasons = [...deterministic.reasons];
  if (recommendation?.requiresEscalation) {
    if (MODEL_ROUTE_RANK[resolved] < MODEL_ROUTE_RANK.PRIMARY) resolved = "PRIMARY";
    reasons.push("JEV_LOW_CONFIDENCE_ESCALATION");
  } else if (recommendation && MODEL_ROUTE_RANK[recommendation.tier] > MODEL_ROUTE_RANK[resolved]) {
    resolved = recommendation.tier;
    reasons.push("JEV_ESCALATION_ONLY");
  }
  return {
    floor: deterministic.floor,
    resolved,
    reasons: [...new Set(reasons)],
    semanticRecommendation: recommendation,
    generationRequired: deterministic.floor !== "NONE",
  };
}

function text(value) {
  return typeof value === "string" ? value.toLowerCase() : "";
}

export function projectModelRoute({ input = {}, semanticRecommendation = null } = {}) {
  const route = resolveModelRoute({ input, semanticRecommendation });
  if (!MODEL_ROUTE_TIERS.includes(route.floor) || !MODEL_ROUTE_TIERS.includes(route.resolved)
    || MODEL_ROUTE_RANK[route.resolved] < MODEL_ROUTE_RANK[route.floor]) {
    const error = new Error("Model route violates its deterministic safety floor.");
    error.code = "E_MODEL_ROUTE_SAFETY_FLOOR_INVALID";
    throw error;
  }
  return {
    schemaVersion: 1,
    policyVersion: MODEL_ROUTE_POLICY_VERSION,
    engine: "typesafe-jev",
    model: MODEL_ROUTE_JEV_MODEL,
    floor: route.floor,
    resolved: route.resolved,
    reasons: route.reasons,
    generationRequired: route.generationRequired,
    semanticRecommendation: route.semanticRecommendation,
    authority: MODEL_ROUTE_PROJECTION_AUTHORITY,
    evidenceAuthority: MODEL_ROUTE_PROJECTION_EVIDENCE_AUTHORITY,
    lifecycleAuthority: false,
    completionAuthority: false,
    ownershipAuthority: false,
    installationAuthority: false,
  };
}

export function inspectNativeAdapter(relativePath, bytes) {
  const text = Buffer.from(bytes).toString("utf8");
  const expected = nativeShimReferences(relativePath);
  const legacyReferences = text.match(LEGACY_REFERENCE_PATTERN) ?? [];
  const missingReferences = expected.filter((reference) => !text.includes(reference));
  const resolvedReferences = expected.map((reference) => ({
    reference,
    path: resolveNativeReference(relativePath, reference),
  }));

  return {
    text,
    expected,
    legacyReferences,
    missingReferences,
    resolvedReferences,
    hasForgeLoopMarker: /forgeloop/i.test(text),
    hasProtocolMarker: text.includes("FORGELOOP_PROJECT_PROTOCOL=REQUIRED"),
  };
}

export function nativeShimPrefix(relativePath) {
  if (relativePath.startsWith(".cursor/")) return "../../.forgeloop/kit";
  if (relativePath.startsWith(".github/")) return "../.forgeloop/kit";
  return ".forgeloop/kit";
}

export function nativeShimReferences(relativePath) {
  const prefix = nativeShimPrefix(relativePath);
  return [
    `${prefix}/LOOP_ENGINEERING.md`,
    `${prefix}/PROTOCOL_INTEGRATION.md`,
  ];
}

export async function validateNativeAdapterTargets({ target, relativePath, bytes }) {
  const inspection = inspectNativeAdapter(relativePath, bytes);
  const invalidReferences = inspection.resolvedReferences.filter(({ path: resolvedPath }) => !isKitPath(resolvedPath));
  const missingTargets = [];

  for (const { path: resolvedPath } of inspection.resolvedReferences) {
    if (!isKitPath(resolvedPath)) continue;
    try {
      await assertSafePath(target, resolvedPath);
      if (!(await fileExists(ensureWithin(target, resolvedPath)))) missingTargets.push(resolvedPath);
    } catch (error) {
      invalidReferences.push({ path: resolvedPath, error: error.message });
    }
  }

  return {
    ...inspection,
    invalidReferences,
    missingTargets,
    stale: inspection.legacyReferences.length > 0
      || inspection.missingReferences.length > 0
      || invalidReferences.length > 0,
  };
}

export function artifactError(code, message, artifacts = []) {
  return { code, message, artifacts };
}

export function checkListReasons(state) {
  try {
    assertCheckList(state.checks, "work-state.checks");
    return [];
  } catch (error) {
    return [artifactError(error.code ?? "E_CHECK_INVALID", error.message, [ARTIFACT_PATHS.state])];
  }
}

export function freshnessReasons(state, classification) {
  const requiredArtifactPaths = state.requiredArtifacts?.map((artifact) => artifact.path) ?? [];
  const reasons = [artifactError(
    "E_STATE_REVALIDATION_REQUIRED",
    `Work-state checkpoint requires revalidation: ${classification.reasons.join(", ")}`,
    [ARTIFACT_PATHS.state],
  )];
  for (const reason of classification.reasons) {
    const contractRelated = ["CONTRACT_CHANGED", "CONTRACT_INVALID", "CONTRACT_NOT_VERIFIED"].includes(reason);
    const artifactRelated = reason.startsWith("REQUIRED_ARTIFACT");
    reasons.push(artifactError(
      contractRelated ? "E_CONTRACT_STALE" : artifactRelated ? "E_REQUIRED_ARTIFACT_STALE" : "E_REPOSITORY_CHANGED",
      `Work-state freshness check failed: ${reason}`,
      uniqueSorted([
        ARTIFACT_PATHS.state,
        ...(contractRelated ? [ARTIFACT_PATHS.contract] : []),
        ...(artifactRelated ? requiredArtifactPaths : []),
      ]),
    ));
  }
  return reasons;
}

export async function loadArtifact(loader, fallback) {
  try {
    return { value: await loader(), error: null, missingArtifacts: [] };
  } catch (error) {
    return {
      value: null,
      error,
      missingArtifacts: error?.code === "ARTIFACT_MISSING"
        ? (error.artifacts?.length ? error.artifacts : [fallback])
        : [],
    };
  }
}

