export async function resolveNextActionPhase({
  target,
  packageRoot,
  explicitTaskId,
  normalized,
  state,
  context,
  stateRel,
  preflightRel,
  contractRel,
  routeRel,
  receiptRel,
  eventsRel,
  authorityContext,
  runtimeContext,
  helpers,
} = {}) {
  const { policyRecoveryAction } = helpers;
  if (explicitTaskId) {
    const taskConflictGuidance = await explicitTaskConflictGuidance({
      target, packageRoot, explicitTaskId, context, eventsRel, stateRel, state,
    });
    if (taskConflictGuidance) return taskConflictGuidance;
  }
  const actionGuidance = await resolvePendingActionGuidance({ target, packageRoot, state, context, eventsRel, authorityContext, runtimeContext, helpers });
  if (actionGuidance) return actionGuidance;
  if (state.phase === "RECEIVED") {
    return decision(
      context,
      NEXT_ACTIONS.DISCOVER,
      artifactError("PHASE_RECEIVED", "Discovery has not started"),
      [stateRel],
    );
  }
  if (state.phase === "DISCOVERING") {
    return decision(
      context,
      NEXT_ACTIONS.CREATE_CONTRACT,
      artifactError("PHASE_DISCOVERING", "Create and validate the task contract"),
      [stateRel],
    );
  }
  const contractResult = await loadArtifact(
    () => readContract(target, packageRoot, { taskId: explicitTaskId }),
    contractRel,
  );
  const contractArtifacts = [stateRel, contractRel];

  if (contractResult.error) {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: [artifactError(
        contractResult.error.code === "ARTIFACT_MISSING" ? "E_CONTRACT_MISSING" : "E_CONTRACT_INVALID",
        contractResult.error.message,
        contractResult.error.artifacts ?? [],
      )],
      requiredArtifacts: contractArtifacts,
      missingArtifacts: contractResult.missingArtifacts,
    });
  }

  const contract = contractResult.value;
  const identityErrors = completionIdentityErrors({ contract: contract.value, state });
  if (identityErrors.length > 0) {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: identityErrors,
      requiredArtifacts: contractArtifacts,
    });
  }
  const freshness = await classifyLoadedWorkState({
    target,
    state,
    contractFile: contractRel,
  });
  if (freshness.status === "REVALIDATION_REQUIRED") {
    const refreshGuidance = await preExecutionRefreshGuidance({ target, packageRoot, state, contract, freshness });
    return result({
      ...context,
      ...refreshGuidance,
      nextAction: refreshGuidance.nextAction,
      reasons: freshnessReasons(state, freshness),
      requiredArtifacts: uniqueSorted([
        stateRel,
        contractRel,
        ...(state.requiredArtifacts?.map((artifact) => artifact.path) ?? []),
      ]),
    });
  }
  if (state.phase === "CONTRACT_READY") {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.ROUTE,
      reasons: [artifactError("PHASE_CONTRACT_READY", "Persist deterministic routing for the validated contract")],
      commands: [`forgeloop route --task ${explicitTaskId} --work <type> --json`],
      commandSpecs: [routeCommandSpec(explicitTaskId)],
      requiredArtifacts: contractArtifacts,
      missingArtifacts: [routeRel],
    });
  }
  const routeResult = await loadArtifact(
    () => readPersistedRoute(target, packageRoot, { taskId: explicitTaskId }),
    routeRel,
  );
  const requiredArtifacts = [...contractArtifacts, routeRel];
  const missingArtifacts = [...routeResult.missingArtifacts];

  if (routeResult.error) {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: [artifactError(
        routeResult.error.code === "ARTIFACT_MISSING" ? "E_ROUTE_MISSING" : "E_ROUTE_INVALID",
        routeResult.error.message,
        routeResult.error.artifacts ?? [],
      )],
      requiredArtifacts,
      missingArtifacts,
    });
  }

  const route = routeResult.value;
  const stale = staleReasons(state, contract, route);
  if (stale.length > 0) {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_STALE_ROUTE,
      reasons: stale,
      commands: [`forgeloop route --task ${explicitTaskId} --work <type> --json`],
      commandSpecs: [routeCommandSpec(explicitTaskId)],
      requiredArtifacts,
    });
  }

  const phaseNeedsChronology = PHASES_REQUIRING_EXECUTION_CHRONOLOGY.has(state.phase);
  let executionPrerequisites = null;
  if (phaseNeedsChronology) {
    try {
      executionPrerequisites = await evaluateStartExecutionPrerequisites({ target, state, packageRoot, taskId: explicitTaskId, runtimeContext });
    } catch (error) {
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
        reasons: [artifactError(
          error?.code ?? "E_PHASE_CHRONOLOGY_INVALID",
          `Unable to evaluate post-execution prerequisites: ${error?.message ?? String(error)}`,
          Array.isArray(error?.artifacts) ? error.artifacts : [eventsRel],
        )],
        requiredArtifacts: [
          stateRel,
          contractRel,
          routeRel,
          preflightRel,
          eventsRel,
        ],
      });
    }
    const staleGateErrors = PHASES_ALLOWING_GATE_REVALIDATION.has(state.phase)
      ? (executionPrerequisites.preflight?.errors ?? []).filter((error) => error.code === "E_GATE_STALE")
      : [];
    if (staleGateErrors.length > 0) {
      const gates = [...new Set(staleGateErrors.map((error) => error.gate).filter(Boolean))].sort();
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.REVALIDATE_GATES,
        reasons: staleGateErrors,
        commands: gates.map((gate) => `forgeloop gate-revalidate --task ${explicitTaskId} --gate ${gate} --acknowledge-stale --json`),
        commandSpecs: gates.map((gate) => gateRevalidationCommandSpec(explicitTaskId, gate)),
        requiredArtifacts: executionPrerequisites.requiredArtifacts,
      });
    }
    if (executionPrerequisites.errors.length > 0) {
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
        reasons: executionPrerequisites.errors,
        requiredArtifacts: executionPrerequisites.requiredArtifacts,
      });
    }
  }

  const preflight = executionPrerequisites?.preflight ?? await evaluatePreflight({ target, packageRoot, taskId: explicitTaskId });
  const preflightArtifact = phaseNeedsChronology
    ? null
    : await loadArtifact(
      () => readJsonArtifact(target, preflightRel, "preflight", packageRoot),
      preflightRel,
    );
  const missingGates = preflight.requiredGates.filter((gate) => !preflight.satisfiedGates.includes(gate));
  const preflightArtifacts = [...requiredArtifacts, preflightRel];
  const persistedPreflightErrors = phaseNeedsChronology
    ? []
    : validatePersistedPreflight(preflightArtifact.value?.value, preflight, preflightArtifact.error);

  if (["ROUTED", "DESIGNING", "PLANNED"].includes(state.phase) && missingGates.length > 0) {
    const missingGatePaths = missingGates.map((gate) => taskGatePath(state.taskId, gate));
    const gateRecordSpec = {
      commandId: "gate-record",
      executable: "forgeloop",
      subcommand: "gate-record",
      argv: ["gate-record", `--task=${state.taskId}`, `--gate=${missingGates[0]}`, "--status=satisfied", "--json"],
      requiredInputs: [
        { name: "artifact", option: "--artifact=<project-relative-path>", repeatable: true },
        { name: "decision", option: "--decision=<text>", repeatable: true },
      ],
    };
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.SATISFY_GATES,
      reasons: missingGates.map((gate, index) => artifactError(
        "E_GATE_UNVERIFIED",
        `Required gate is missing or unverified: ${gate}`,
        [missingGatePaths[index]],
      )),
      requiredArtifacts: [...preflightArtifacts, ...missingGatePaths],
      missingArtifacts: missingGatePaths,
      commandSpecs: [gateRecordSpec],
    });
  }
  if (state.phase === "ROUTED") {
    if (persistedPreflightErrors.length > 0) {
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.RUN_PREFLIGHT,
        reasons: persistedPreflightErrors,
        commands: [commandFor(NEXT_ACTIONS.RUN_PREFLIGHT)],
        requiredArtifacts: preflightArtifacts,
        missingArtifacts: preflightArtifact.missingArtifacts,
      });
    }
    return decision(context, NEXT_ACTIONS.PLAN, artifactError("PHASE_ROUTED", "Routing and required gates are ready for planning"));
  }
  if (state.phase === "DESIGNING") {
    return decision(context, NEXT_ACTIONS.PLAN, artifactError("PHASE_DESIGNING", "Required gates are ready for planning"));
  }
  if (state.phase === "PLANNED") {
    return resolvePlannedPhase({ target, packageRoot, explicitTaskId, state, runtimeContext, context, preflightArtifact });
  }
  if (state.phase === "EXECUTING") {
    const continuityAction = await evaluateContinuityNextAction({ target, packageRoot, context });
    if (continuityAction) return continuityAction;
    return decision(context, NEXT_ACTIONS.ENTER_VERIFYING, artifactError("PHASE_EXECUTING", "Execution is complete enough to enter verification"));
  }
  if (state.phase === "VERIFYING") {
    return resolveVerifyingPhase({ target, packageRoot, explicitTaskId, state, runtimeContext, context, requiredArtifacts, contract, route, preflight, authorityContext, stateRel, receiptRel });
  }
  if (state.phase === "DIAGNOSING") {
    return resolveDiagnosingPhase({ target, packageRoot, normalized, state, context, eventsRel, requiredArtifacts, stateRel });
  }
  if (state.phase === "CORRECTING") {
    return resolveCorrectingPhase({ target, packageRoot, normalized, state, context, requiredArtifacts });
  }
  if (state.phase === "REVIEWING") {
    return resolveReviewingPhase({ state, context, requiredArtifacts, target, packageRoot, contract, route, preflight, authorityContext, runtimeContext, explicitTaskId, eventsRel, receiptRel, stateRel, policyRecoveryAction });
  }
  if (state.phase === "COMPLETE") {
    const completion = await evaluateCompletion({ target, packageRoot, taskId: explicitTaskId, authorityContext, runtimeContext });
    if (completion.status === "VALID") {
      return decision(context, NEXT_ACTIONS.NONE, artifactError("PHASE_COMPLETE", "Completion is validator-backed and terminal"));
    }
    const policyAction = policyRecoveryAction(completion.errors);
    return result({
      ...context,
      nextAction: policyAction ?? NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: completion.errors,
      requiredArtifacts: [...requiredArtifacts, receiptRel, eventsRel],
    });
  }
  if (state.phase === "BLOCKED") {
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
      reasons: state.blockers.map((blocker) => artifactError(
        "WORK_STATE_BLOCKED",
        blocker.reason ?? "Work state has a recorded blocker",
        [stateRel],
      )),
      requiredArtifacts,
    });
  }

  return decision(
    context,
    NEXT_ACTIONS.RESOLVE_BLOCKER,
    artifactError("E_PHASE_UNSUPPORTED", `Unsupported persisted phase: ${state.phase}`, [ARTIFACT_PATHS.state]),
    requiredArtifacts,
  );
}

export function structuralQualityOptionalActions(quality, taskId) {
  if (quality?.mode !== "observe") return [];
  if (quality.baseline?.status !== "OBSERVED") {
    return [{
      action: NEXT_ACTIONS.CAPTURE_STRUCTURAL_QUALITY_BASELINE,
      command: `forgeloop quality-baseline --task ${taskId} --json`,
    }];
  }
  if (quality.freshness === "STALE" || quality.current?.verificationCycle === null
    || quality.current?.verificationCycle === undefined) {
    return [{
      action: NEXT_ACTIONS.VERIFY_STRUCTURAL_QUALITY,
      command: `forgeloop quality-verify --task ${taskId} --json`,
    }];
  }
  return [];
}

export async function resolveCorrectingPhase({ target, packageRoot, normalized, state, context, requiredArtifacts }) {
    const ledgerForCorrection = await validateEventLedger(target, packageRoot, { taskId: normalized.taskId ?? null });
    const correctionCycle = state.verificationCycle ?? 1;
    const hasStructuredCase = ledgerForCorrection.events.some(
      (event) => event.event === "DIAGNOSTIC_CASE_RECORDED"
        && event.taskId === state.taskId
        && event.details?.verificationCycle === correctionCycle,
    );
    const hasIntervention = ledgerForCorrection.events.some(
      (event) => event.event === "INTERVENTION_RECORDED"
        && event.taskId === state.taskId
        && event.details?.verificationCycle === correctionCycle,
    );
    if (hasStructuredCase && !hasIntervention) {
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.ENTER_VERIFYING,
        reasons: [
          artifactError("PHASE_CORRECTING", "A structured diagnostic case is awaiting a recorded intervention"),
        ],
        diagnosticGuidance: {
          action: NEXT_ACTIONS.RECORD_INTERVENTION,
          signals: ["INTERVENTION_NOT_BOUND_TO_HYPOTHESIS"],
          errorCodes: [],
          commandSpecs: [recordInterventionCommandSpec(normalized.taskId)],
        },
        requiredArtifacts,
      });
    }
    return decision(context, NEXT_ACTIONS.ENTER_VERIFYING, artifactError("PHASE_CORRECTING", "Correction is ready for verification"));
  }

export async function resolveDiagnosingPhase({ target, packageRoot, normalized, state, context, eventsRel, requiredArtifacts, stateRel }) {
    const ledger = await validateEventLedger(target, packageRoot, { taskId: normalized.taskId ?? null });
    const cycle = state.verificationCycle ?? 1;
    const diagEvent = resolveCurrentCycleDiagnostic(ledger.events, state.taskId, cycle);
    if (!diagEvent) {
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.RECORD_DIAGNOSIS,
        reasons: [
          artifactError(
            "E_DIAGNOSIS_REQUIRED",
            "Current correction cycle has no append-only diagnosis record.",
            [eventsRel],
          ),
        ],
        commandSpecs: [recordDiagnosisCommandSpec()],
        requiredArtifacts: [...requiredArtifacts, eventsRel],
      });
    }
    const progress = evaluateProgress({ state, events: ledger.events });
    if (progress.status === PROGRESS_STATUS.STALLED) {
      let oscillating = false;
      try {
        const reflection = await buildTaskReflection({ target, packageRoot, taskId: normalized.taskId ?? null });
        oscillating = reflection.oscillation.detected;
      } catch {
        // Reflection is advisory guidance; stall handling must not depend on it.
      }
      return result({
        ...context,
        nextAction: NEXT_ACTIONS.CHANGE_STRATEGY,
        reasons: [
          artifactError(
            "E_PROGRESS_STALLED",
            "The current correction strategy has no new diagnostic information.",
            [stateRel, eventsRel],
          ),
        ],
        progress,
        diagnosticGuidance: {
          action: oscillating ? NEXT_ACTIONS.INTRODUCE_NEW_OBSERVATION : NEXT_ACTIONS.REQUIRE_NEW_DIAGNOSTIC_INFORMATION,
          signals: oscillating ? ["OSCILLATING_STRATEGY"] : ["NO_INFORMATION_GAIN", ...progress.signals.map((signal) => signal.code)],
          errorCodes: oscillating ? ["E_STRATEGY_OSCILLATION", "E_PROGRESS_STALLED"] : ["E_PROGRESS_STALLED"],
        },
        requiredArtifacts,
      });
    }
    return result({
      ...context,
      nextAction: NEXT_ACTIONS.CORRECT,
      commands: [commandFor(NEXT_ACTIONS.CORRECT)],
      reasons: [
        artifactError("PHASE_DIAGNOSING", "The persisted diagnosis hypothesis permits correction"),
      ],
      ...(progress.status === PROGRESS_STATUS.WATCH ? { progress } : {}),
      requiredArtifacts,
    });
  }

export async function preExecutionRefreshGuidance({ target, packageRoot, state, contract, freshness }) {
  if (!["ROUTED", "DESIGNING", "PLANNED"].includes(state.phase)) return { nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER };
  const ledger = await validateEventLedger(target, packageRoot, { taskId: state.taskId });
  if (!ledger.valid || ledger.events.some((entry) => entry.event === "EXECUTION_STARTED")) {
    return { nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER };
  }
  if (CHECKPOINT_REVALIDATION_PHASES.includes(state.phase)
    && freshness?.status === "REVALIDATION_REQUIRED"
    && [...new Set(freshness.reasons ?? [])].sort().join(",") === "REPOSITORY_CHANGED"
    && state.contractFingerprint === contract.fingerprint) {
    try {
      const route = await readPersistedRoute(target, packageRoot, { taskId: state.taskId });
      const ownership = await resolveTaskClaimState(target, { taskId: state.taskId, packageRoot });
      const coherenceErrors = validateStateLedgerCoherence(state, ledger.events);
      const repositoryAvailable = typeof freshness.repository?.head === "string" && freshness.repository.head.length > 0;
      const routeIdentityValid = route.value?.contractFingerprint === contract.fingerprint
        && state.routeFingerprint === route.fingerprint
        && sameCanonicalGuideList(state.selectedGuides, route.value.guides);
      if (ownership.ownershipValid && ownership.mutationAllowed && repositoryAvailable
        && coherenceErrors.length === 0 && routeIdentityValid) {
        return {
          nextAction: NEXT_ACTIONS.REVALIDATE_CHECKPOINT,
          commands: [`forgeloop checkpoint-revalidate --task ${state.taskId} --json`],
          commandSpecs: [directCommandSpec("checkpoint-revalidate", state.taskId)],
        };
      }
    } catch {
      // Unsupported or ambiguous identity stays on the fail-closed blocker.
    }
  }
  const lastPreflight = ledger.events.filter((entry) => ["PREFLIGHT_READY", "PREFLIGHT_BLOCKED"].includes(entry.event)).at(-1);
  if (lastPreflight?.event !== "PREFLIGHT_BLOCKED") return { nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER };
  let route;
  try { route = await readPersistedRoute(target, packageRoot, { taskId: state.taskId }); }
  catch { return { nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER }; }
  if (route.value.contractFingerprint !== contract.fingerprint) return { nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER };
  return {
    nextAction: NEXT_ACTIONS.RESOLVE_BLOCKER,
    commands: [`forgeloop clear-state --task ${state.taskId}`, `forgeloop preflight --task ${state.taskId}`],
    commandSpecs: [directCommandSpec("clear-state", state.taskId), directCommandSpec("preflight", state.taskId)],
  };
}

function capabilityDecisionMetadata(action, capability, approvalId = null) {
  return {
    capability: action.capability,
    decision: capability.decision,
    reasonCode: capability.reasonCode ?? null,
    policyFingerprint: capability.policyFingerprint ?? null,
    ...(capability.authority?.authorityRef ? { authorityRef: capability.authority.authorityRef } : {}),
    ...(capability.approval?.approvalId
      ? { approvalId: capability.approval.approvalId }
      : approvalId ? { approvalId } : {}),
  };
}

export function policyRecoveryAction(errors = []) {
  if (errors.some((e) => [
    "E_POLICY_WEAKENING",
    "E_POLICY_LOCK_MISMATCH",
    "E_ACTION_POLICY_DRIFT",
  ].includes(e.code))) {
    return NEXT_ACTIONS.RESTORE_POLICY;
  }
  if (errors.some((e) => e.code === "E_CHECK_MUTATION_EXECUTION_ERROR" || e.code === "E_CHECK_MUTATION_NOT_DETECTED")) {
    return NEXT_ACTIONS.REPAIR_CHECKER;
  }
  if (errors.some((e) => e.code === "E_POLICY_INVALID" || e.code === "E_POLICY_EVALUATION_FAILED")) {
    return NEXT_ACTIONS.REPAIR_POLICY;
  }
  if (errors.some((e) => e.code === "E_POLICY_DRIFT_UNKNOWN")) {
    return NEXT_ACTIONS.REVERIFY_AFTER_POLICY_CHANGE;
  }
  if (errors.some((e) => e.code === "E_BASELINE_EXPANSION")) {
    return NEXT_ACTIONS.RESTORE_BASELINE;
  }
  if (errors.some((e) => e.code === "E_BASELINE_RECORD_DURING_ACTIVE_TASK")) {
    return NEXT_ACTIONS.CONTINUE_WITH_EXISTING_BASELINE;
  }
  if (errors.some((e) => e.code === "E_CHECK_INERT")) {
    return NEXT_ACTIONS.RESOLVE_INERT_CHECK;
  }
  return null;
}

export function getNpmLifecycleCandidates({ scriptName, scripts = {} } = {}) {
  if (scriptName === "restart") {
    if (typeof scripts?.restart === "string" && scripts.restart.trim() !== "") {
      return ["prerestart", "restart", "postrestart"];
    }
    return ["prerestart", "prestop", "stop", "poststop", "prestart", "start", "poststart", "postrestart"];
  }
  return [`pre${scriptName}`, scriptName, `post${scriptName}`];
}

export function getNpmScriptName(argv) {
  const npm = parseNpmInvocation(argv);
  if (npm.ambiguous || !npm.subcommand) return null;

  const sub = npm.subcommand;
  const args = npm.args;
  if (["test", "t", "tst"].includes(sub)) return "test";
  if (["start", "stop", "restart"].includes(sub)) return sub;
  if (["run", "run-script", "rum", "urn"].includes(sub)) {
    let afterDoubleDash = false;
    for (let idx = 0; idx < args.length; idx++) {
      const arg = args[idx];
      if (arg === "--") {
        afterDoubleDash = true;
        if (args[idx + 1] && !args[idx + 1].startsWith("-")) return args[idx + 1];
        continue;
      }
      if (!afterDoubleDash && !arg.startsWith("-")) {
        if (idx > 0 && (args[idx - 1] === "-w" || args[idx - 1] === "--workspace" || NPM_OPTIONS_WITH_VALUE.has(args[idx - 1]))) continue;
        return arg;
      }
    }
  }
  return null;
}

export function parseNpmInvocation(argv) {
  const tokens = unwrapCommandArgv(Array.isArray(argv) ? argv : tokenizeCommand(argv));
  if (!tokens || tokens.length === 0) {
    return {
      subcommand: null,
      subcommandIndex: -1,
      args: [],
      leadingOptions: [],
      workspace: null,
      workspaces: false,
      ambiguous: true,
    };
  }
  if (normalizeExecutableName(tokens[0]) !== "npm") {
    return {
      subcommand: null,
      subcommandIndex: -1,
      args: [],
      leadingOptions: [],
      workspace: null,
      workspaces: false,
      ambiguous: true,
    };
  }
  return parseNpmInvocationArgs(tokens.slice(1));
}

export function parseNpmInvocationArgs(rest) {
  if (!Array.isArray(rest)) {
    return {
      subcommand: null,
      subcommandIndex: -1,
      args: [],
      leadingOptions: [],
      workspace: null,
      workspaces: false,
      ambiguous: true,
    };
  }

  const leadingOptions = [];
  let workspace = null;
  let workspaces = false;

  let i = 0;
  while (i < rest.length) {
    const arg = rest[i];
    if (arg === "--" || !arg.startsWith("-")) break;

    if (arg === "--workspaces" || arg === "--ws") {
      workspaces = true;
      leadingOptions.push(arg);
      i += 1;
      continue;
    }

    if (arg.startsWith("--workspace=")) {
      workspace = arg.slice("--workspace=".length) || null;
      leadingOptions.push(arg);
      i += 1;
      continue;
    }

    if (arg.startsWith("-w=")) {
      workspace = arg.slice(3) || null;
      leadingOptions.push(arg);
      i += 1;
      continue;
    }

    if (arg === "--workspace" || arg === "-w") {
      leadingOptions.push(arg);
      const value = rest[i + 1] ?? null;
      if (value !== null && !value.startsWith("-")) {
        workspace = value;
        leadingOptions.push(value);
        i += 2;
      } else {
        workspace = value;
        i += 1;
      }
      continue;
    }

    if (NPM_OPTIONS_WITH_VALUE.has(arg)) {
      leadingOptions.push(arg);
      const value = rest[i + 1] ?? null;
      if (value !== null && !value.startsWith("-")) {
        leadingOptions.push(value);
        i += 2;
      } else {
        i += 1;
      }
      continue;
    }

    if (/^--[^=]+=/.test(arg) || NPM_KNOWN_BOOLEAN_OPTIONS.has(arg)) {
      leadingOptions.push(arg);
      i += 1;
      continue;
    }

    if (/^--/.test(arg)) {
      const next = rest[i + 1];
      if (next && !next.startsWith("-")) {
        return {
          subcommand: null,
          subcommandIndex: -1,
          args: [],
          leadingOptions,
          workspace,
          workspaces,
          ambiguous: true,
          reason: "NPM_OPTION_VALUE_AMBIGUOUS",
        };
      }
      leadingOptions.push(arg);
      i += 1;
      continue;
    }

    leadingOptions.push(arg);
    i += 1;
  }

  const subcommand = rest[i] ? rest[i].toLowerCase() : null;
  const trailingArgs = subcommand ? rest.slice(i + 1) : [];

  for (let j = 0; j < trailingArgs.length; j++) {
    const arg = trailingArgs[j];
    if (arg === "--") break;
    if (arg === "--workspaces" || arg === "--ws") {
      workspaces = true;
    } else if (arg.startsWith("--workspace=")) {
      workspace = arg.slice("--workspace=".length) || null;
    } else if (arg.startsWith("-w=")) {
      workspace = arg.slice(3) || null;
    } else if (arg === "--workspace" || arg === "-w") {
      const value = trailingArgs[j + 1];
      if (value && !value.startsWith("-")) {
        workspace = value;
        j += 1;
      }
    }
  }

  const ambiguous = subcommand === null;
  return {
    subcommand,
    subcommandIndex: subcommand ? i : -1,
    args: trailingArgs,
    leadingOptions,
    workspace,
    workspaces,
    ambiguous,
    ...(ambiguous ? { reason: "NPM_SUBCOMMAND_AMBIGUOUS" } : {}),
  };
}

export function assertDiagnosingToCorrectingTransition({ state, events, resolveDiagnosis }) {
  const cycle = state?.verificationCycle ?? 1;
  const diagEvent = resolveDiagnosis(events, state?.taskId, cycle);
  if (!diagEvent) {
    throw phaseError(
      "E_DIAGNOSIS_REQUIRED",
      "DIAGNOSING -> CORRECTING requires an append-only diagnosis record for the active verification cycle",
      [],
    );
  }
  const structured = diagEvent.sourceModel === "STRUCTURED_DIAGNOSTIC_CASE_V1";
  const gainClassification = structured ? null : diagEvent.details?.informationGain;
  if (!diagEvent.details || (structured ? false : gainClassification === "NONE")) {
    throw phaseError(
      "E_DIAGNOSIS_NO_NEW_INFORMATION",
      "The proposed retry repeats the previous hypothesis with the same evidence without new information",
      [],
    );
  }
  return diagEvent;
}

function assertRepairedCheckpointIdentity({ contract, route, state, events, contractRel, routeRel, stateRel }) {
  const repairMarker = events.find((event) => event.event === CONTRACT_BOOTSTRAP_REPAIR_EVENT);
  if (!repairMarker || state.phase === "ROUTED") return false;
  const checkpoint = resolveCanonicalPostRepairCheckpointBinding(events, repairMarker);
  if (!checkpoint) {
    throw phaseError(
      "E_PHASE_CHRONOLOGY_INVALID",
      "Repaired late-phase state requires a canonical route checkpoint binding",
      [contractRel, routeRel],
    );
  }
  const identityErrors = [
    ...stateIdentityErrors({ contract, state }),
    ...stateIdentityErrors({ contract, route }),
  ];
  if (state.routeFingerprint !== checkpoint.routeFingerprint
    || !sameCanonicalGuideList(state.selectedGuides, checkpoint.selectedGuides)) {
    identityErrors.push({
      code: "E_ROUTE_GUIDE_MISMATCH",
      message: "Work state does not match the immutable route checkpoint identity",
      artifacts: [routeRel, stateRel],
    });
  }
  if (identityErrors.length > 0) {
    const first = identityErrors[0];
    throw phaseError(first.code, first.message, first.artifacts);
  }
  return true;
}

async function assertRequiredPhaseArtifact(read, toPhase, relativePath) {
  try { await read(); }
  catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    throw phaseError("E_PHASE_PREREQUISITE_MISSING", `Phase ${toPhase} requires ${relativePath}: ${error.message}`, [relativePath]);
  }
}

function isRevisionPlanRepeat(events, eventType) {
  return eventType === "PLAN_RECORDED"
    && isRevisionEpochPlanRepeat(events, events.length, { event: eventType });
}

function phaseError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function preparePhaseReceipt({ target, packageRoot, taskId, state, next, receiptRel, contractPath = null, routePath = null, statePath = null, authorityContext, runtimeContext, readers = null }) {
  let nextReceipt = null;
  try {
    const receipt = await (readers?.readReceipt ?? readJsonArtifact)(target, receiptRel, "execution-receipt", packageRoot);
    const contract = await (readers?.readContract ?? readContract)(target, packageRoot, { taskId, contractPath });
    const route = await (readers?.readRoute ?? readPersistedRoute)(target, packageRoot, { taskId, routePath });
    const preflight = await evaluatePreflight({ target, packageRoot, taskId, contractPath, routePath, statePath, readers });
    const requiredEvidence = await requiredEvidenceForTarget({
      target,
      contract,
      route,
      packageRoot,
      additionalEvidence: preflight.policy?.requiredEvidence ?? [],
    });
    await validateReceipt(receipt.value, packageRoot, {
      target,
      taskId: contract?.value?.taskId,
      authorityContext,
      runtimeContext,
    });
    assertCompletionRelationships({
      contract,
      route,
      state,
      receipt: receipt.value,
      requiredEvidence,
      requireRequiredChecks: false,
      requireReceiptStateFingerprint: false,
      target,
      taskId: contract?.value?.taskId,
      authorityContext,
      runtimeContext,
    });
    nextReceipt = await createReceipt({
      ...receipt.value,
      stateFingerprint: canonicalFingerprint(next),
      verificationCycle: next.verificationCycle ?? receipt.value.verificationCycle ?? 1,
    }, packageRoot, {
      target,
      taskId: contract?.value?.taskId,
      authorityContext,
      runtimeContext,
    });
    assertCompletionRelationships({
      contract,
      route,
      state: next,
      receipt: nextReceipt,
      requiredEvidence,
      requireRequiredChecks: false,
      target,
      taskId: contract?.value?.taskId,
      authorityContext,
      runtimeContext,
    });
  } catch (error) {
    if (error.code !== "ARTIFACT_MISSING") throw error;
  }
  return nextReceipt;
}

async function readPhaseIdentityArtifacts(target, state, toPhase, packageRoot, options, paths) {
  const scopedTaskId = options.taskId ?? null;
  const requireContract = LATE_PHASES.has(state.phase)
    || ["CONTRACT_READY", "ROUTED", "EXECUTING"].includes(toPhase);
  const requireRoute = state.phase === "ROUTED"
    || LATE_PHASES.has(state.phase)
    || ["ROUTED", "EXECUTING"].includes(toPhase);
  let contract = null;
  let route = null;
  try {
    contract = await readContract(target, packageRoot, { taskId: scopedTaskId, contractPath: options.contractPath });
  } catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    if (error.code === "ARTIFACT_MISSING" && !requireContract) {
      contract = null;
    } else {
      throw phaseError(
        requireContract ? "E_PHASE_PREREQUISITE_MISSING" : error.code ?? "E_CONTRACT_INVALID",
        `${requireContract ? `Phase ${toPhase} requires current contract` : "Unable to validate current contract"}: ${error.message}`,
        [paths.contractRel],
      );
    }
  }
  try {
    route = await readPersistedRoute(target, packageRoot, { taskId: scopedTaskId, routePath: options.routePath });
  } catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    if (error.code === "ARTIFACT_MISSING" && !requireRoute) {
      route = null;
    } else {
      throw phaseError(
        requireRoute ? "E_PHASE_PREREQUISITE_MISSING" : error.code ?? "E_ROUTE_INVALID",
        `${requireRoute ? `Phase ${toPhase} requires persisted route` : "Unable to validate persisted route"}: ${error.message}`,
        [paths.routeRel],
      );
    }
  }
  return { contract, route };
}

function reconcileImplementationStep(state, toPhase) {
  if (state.phase !== "EXECUTING" || toPhase !== "VERIFYING") return state;
  if (!state.pendingSteps.includes("implementation")) return state;
  return {
    ...state,
    completedSteps: state.completedSteps.includes("implementation")
      ? [...state.completedSteps]
      : [...state.completedSteps, "implementation"],
    pendingSteps: state.pendingSteps.filter((step) => step !== "implementation"),
  };
}

export function getPolicyAdapter(adapterId) {
  return BUILTIN_ADAPTERS[adapterId] ?? null;
}

export function computeViolationFingerprint(violation) {
  if (violation.fingerprint) {
    return violation.fingerprint.startsWith("sha256:") ? violation.fingerprint : `sha256:${violation.fingerprint}`;
  }
  const raw = `${violation.ruleId}:${violation.file || ""}:${violation.line || ""}:${violation.snippet || violation.message || ""}`;
  return `sha256:${sha256(raw)}`;
}

export function evaluateBaselineViolations(baseline, currentViolations, { now = new Date().toISOString() } = {}) {
  if (!baseline || !baseline.entries) {
    return {
      newViolations: currentViolations,
      baselinedViolations: [],
      resolvedViolations: [],
      ratchetedBaseline: null,
      warnings: [],
    };
  }

  const baselineMap = new Map();
  for (const entry of baseline.entries) {
    baselineMap.set(entry.ruleId, new Set(entry.fingerprints));
  }

  const newViolations = [];
  const baselinedViolations = [];
  const matchedFingerprintsPerRule = new Map();

  for (const v of currentViolations) {
    const fp = computeViolationFingerprint(v);
    const existing = baselineMap.get(v.ruleId);
    if (existing && existing.has(fp)) {
      baselinedViolations.push(v);
      if (!matchedFingerprintsPerRule.has(v.ruleId)) {
        matchedFingerprintsPerRule.set(v.ruleId, new Set());
      }
      matchedFingerprintsPerRule.get(v.ruleId).add(fp);
    } else {
      newViolations.push(v);
    }
  }

  // Determine resolved debt and ratcheted baseline
  const resolvedViolations = [];
  const ratchetedEntries = [];
  const warnings = [];

  for (const entry of baseline.entries) {
    const matched = matchedFingerprintsPerRule.get(entry.ruleId) ?? new Set();
    const remaining = entry.fingerprints.filter((fp) => matched.has(fp));
    const resolved = entry.fingerprints.filter((fp) => !matched.has(fp));

    for (const r of resolved) {
      resolvedViolations.push({ ruleId: entry.ruleId, fingerprint: r });
    }

    if (entry.reviewBy && entry.reviewBy <= now.slice(0, 10)) {
      warnings.push({
        code: "BASELINE_REVIEW_DUE",
        ruleId: entry.ruleId,
        reviewBy: entry.reviewBy,
        message: `Baseline review date ${entry.reviewBy} for rule ${entry.ruleId} has expired.`,
      });
    }

    if (remaining.length > 0) {
      ratchetedEntries.push({
        ruleId: entry.ruleId,
        fingerprints: remaining.sort(),
        ...(entry.reviewBy ? { reviewBy: entry.reviewBy } : {}),
      });
    }
  }

  const ratchetedBaseline = {
    schemaVersion: baseline.schemaVersion ?? 1,
    createdAt: baseline.createdAt,
    entries: ratchetedEntries.sort((a, b) => a.ruleId.localeCompare(b.ruleId)),
  };

  return {
    newViolations,
    baselinedViolations,
    resolvedViolations,
    ratchetedBaseline,
    warnings,
  };
}

export async function readBaseline(target, packageRoot) {
  const relPath = PROJECT_ARTIFACT_PATHS.policyBaseline;
  const fullPath = `${target}/${relPath}`;
  if (!(await fileExists(fullPath))) {
    return null;
  }
  const raw = await readFile(fullPath, "utf8");
  assertJsonLimits(raw, relPath);
  const parsed = JSON.parse(raw);
  const schema = await readSchema("policy-baseline", packageRoot);
  assertSchema(parsed, schema, "policy-baseline");
  return parsed;
}

export function diffPolicies(beforePolicy = {}, afterPolicy = {}) {
  const changes = [];
  const beforeRules = new Map((beforePolicy?.rules ?? []).map((r) => [r.id, r]));
  const afterRules = new Map((afterPolicy?.rules ?? []).map((r) => [r.id, r]));

  // Check removed rules
  for (const [id, beforeRule] of beforeRules.entries()) {
    if (!afterRules.has(id)) {
      const isWeakening = beforeRule.blocking || beforeRule.severity === "HIGH";
      changes.push({
        path: `rules.${id}`,
        type: isWeakening ? "WEAKEN" : "NEUTRAL",
        before: beforeRule,
        after: null,
        description: `Rule ${id} was removed`,
      });
    }
  }

  // Check added rules
  for (const [id, afterRule] of afterRules.entries()) {
    if (!beforeRules.has(id)) {
      const isTightening = afterRule.blocking || afterRule.severity === "HIGH";
      changes.push({
        path: `rules.${id}`,
        type: isTightening ? "TIGHTEN" : "NEUTRAL",
        before: null,
        after: afterRule,
        description: `Rule ${id} was added`,
      });
    }
  }

  // Check modified rules
  for (const [id, beforeRule] of beforeRules.entries()) {
    const afterRule = afterRules.get(id);
    if (!afterRule) continue;

    // Check blocking change
    if (beforeRule.blocking !== afterRule.blocking) {
      const isWeakening = beforeRule.blocking && !afterRule.blocking;
      changes.push({
        path: `rules.${id}.blocking`,
        type: isWeakening ? "WEAKEN" : "TIGHTEN",
        before: beforeRule.blocking,
        after: afterRule.blocking,
        description: isWeakening ? `Rule ${id} was changed from blocking to advisory` : `Rule ${id} was changed to blocking`,
      });
    }

    // Check threshold change
    const beforeThreshold = beforeRule.check?.threshold ?? beforeRule.parameters?.threshold;
    const afterThreshold = afterRule.check?.threshold ?? afterRule.parameters?.threshold;
    if (beforeThreshold !== undefined && afterThreshold !== undefined && beforeThreshold !== afterThreshold) {
      const isWeakening = afterThreshold > beforeThreshold;
      changes.push({
        path: `rules.${id}.threshold`,
        type: isWeakening ? "WEAKEN" : "TIGHTEN",
        before: beforeThreshold,
        after: afterThreshold,
        description: `Threshold for ${id} changed from ${beforeThreshold} to ${afterThreshold}`,
      });
    }
  }

  // Check baseline changes
  if (beforePolicy && beforePolicy.baseline === undefined && beforePolicy.baselineDigest) {
    // Legacy snapshot lacking semantic baseline state
    if (afterPolicy?.baselineDigest && beforePolicy.baselineDigest !== afterPolicy.baselineDigest) {
      changes.push({
        path: "baseline",
        type: "UNKNOWN",
        before: beforePolicy.baselineDigest,
        after: afterPolicy.baselineDigest,
        description: "Baseline digest changed but semantic baseline snapshot is unavailable",
      });
    }
  } else if (beforePolicy?.baseline || afterPolicy?.baseline) {
    const beforeEntries = beforePolicy?.baseline?.entries ?? [];
    const afterEntries = afterPolicy?.baseline?.entries ?? [];
    const beforeBaseline = new Map(beforeEntries.map((e) => [e.ruleId, new Set(e.fingerprints ?? [])]));
    const afterBaseline = new Map(afterEntries.map((e) => [e.ruleId, new Set(e.fingerprints ?? [])]));

    const allRuleIds = new Set([...beforeBaseline.keys(), ...afterBaseline.keys()]);
    for (const ruleId of allRuleIds) {
      const beforeFpSet = beforeBaseline.get(ruleId) ?? new Set();
      const afterFpSet = afterBaseline.get(ruleId) ?? new Set();

      const addedFps = [...afterFpSet].filter((fp) => !beforeFpSet.has(fp));
      const removedFps = [...beforeFpSet].filter((fp) => !afterFpSet.has(fp));

      if (addedFps.length > 0) {
        changes.push({
          path: `baseline.${ruleId}`,
          type: "WEAKEN",
          before: beforeFpSet.size,
          after: afterFpSet.size,
          description: `Added ${addedFps.length} new violations to baseline for rule ${ruleId}`,
        });
      }
      if (removedFps.length > 0) {
        changes.push({
          path: `baseline.${ruleId}`,
          type: "TIGHTEN",
          before: beforeFpSet.size,
          after: afterFpSet.size,
          description: `Resolved and removed ${removedFps.length} baseline violations for rule ${ruleId}`,
        });
      }
    }
  }

  let classification = POLICY_DIFF_CLASSIFICATIONS.NEUTRAL;
  if (changes.some((c) => c.type === "WEAKEN")) {
    classification = POLICY_DIFF_CLASSIFICATIONS.WEAKEN;
  } else if (changes.some((c) => c.type === "UNKNOWN")) {
    classification = POLICY_DIFF_CLASSIFICATIONS.UNKNOWN;
  } else if (changes.some((c) => c.type === "TIGHTEN")) {
    classification = POLICY_DIFF_CLASSIFICATIONS.TIGHTEN;
  }

  return {
    classification,
    changes,
  };
}

const checkDirs = async (parent) => {
  try {
    const subEntries = await readdir(parent, { withFileTypes: true });
    for (const ent of subEntries) {
      if (ent.isDirectory()) {
        const name = ent.name.toLowerCase();
        if (name === "domain") hasDomain = true;
        if (name === "infrastructure" || name === "infra") hasInfra = true;
        if (name === "application" || name === "app") hasApp = true;
      }
    }
  } catch {
    // ignore
  }
};

export async function discoverPolicy({ target = process.cwd() } = {}) {
  const languages = [];
  const entries = await (async () => {
    try {
      return await readdir(target);
    } catch {
      return [];
    }
  })();

  const entrySet = new Set(entries);

  // 1. Detect Languages & Manifests
  let packageJson = null;
  if (entrySet.has("package.json")) {
    try {
      const raw = await readFile(path.join(target, "package.json"), "utf8");
      packageJson = JSON.parse(raw);
      if (entrySet.has("tsconfig.json")) {
        languages.push("typescript");
      } else {
        languages.push("javascript");
      }
    } catch {
      // ignore parse error
    }
  }

  if (entrySet.has("pyproject.toml") || entrySet.has("requirements.txt") || entrySet.has("setup.py") || entrySet.has("Pipfile")) {
    languages.push("python");
  }
  if (entrySet.has("Cargo.toml")) {
    languages.push("rust");
  }
  if (entrySet.has("go.mod")) {
    languages.push("go");
  }
  if (entrySet.has("pom.xml") || entrySet.has("build.gradle") || entrySet.has("build.gradle.kts")) {
    languages.push("java");
  }

  // 2. Detect Testing
  let testing = {
    detected: false,
    confidence: CONFIDENCE_LEVELS.UNKNOWN,
  };

  if (packageJson?.scripts?.test) {
    testing = {
      detected: true,
      command: ["npm", "test"],
      framework: packageJson.devDependencies?.jest ? "jest"
        : packageJson.devDependencies?.vitest ? "vitest"
        : packageJson.devDependencies?.mocha ? "mocha"
        : "npm-test",
      confidence: CONFIDENCE_LEVELS.HIGH,
    };
  } else if (entrySet.has("Cargo.toml")) {
    testing = {
      detected: true,
      command: ["cargo", "test"],
      framework: "cargo",
      confidence: CONFIDENCE_LEVELS.HIGH,
    };
  } else if (entrySet.has("go.mod")) {
    testing = {
      detected: true,
      command: ["go", "test", "./..."],
      framework: "go",
      confidence: CONFIDENCE_LEVELS.HIGH,
    };
  } else if (entrySet.has("pytest.ini") || entrySet.has("tests") || entrySet.has("test")) {
    testing = {
      detected: true,
      command: ["pytest"],
      framework: "pytest",
      confidence: CONFIDENCE_LEVELS.MEDIUM,
    };
  }

  // 3. Detect Linting
  let linting = {
    detected: false,
    confidence: CONFIDENCE_LEVELS.UNKNOWN,
  };

  if (packageJson?.scripts?.lint) {
    linting = {
      detected: true,
      command: ["npm", "run", "lint"],
      tool: "eslint",
      confidence: CONFIDENCE_LEVELS.HIGH,
    };
  } else if (entrySet.has(".eslintrc") || entrySet.has(".eslintrc.json") || entrySet.has(".eslintrc.js") || entrySet.has("eslint.config.js") || entrySet.has("eslint.config.mjs")) {
    linting = {
      detected: true,
      command: ["npx", "eslint", "."],
      tool: "eslint",
      confidence: CONFIDENCE_LEVELS.MEDIUM,
    };
  }

  // 4. Detect Architecture
  let architecture = {
    value: null,
    confidence: CONFIDENCE_LEVELS.UNKNOWN,
    enforcement: ENFORCEMENT_MODES.NONE,
  };

  let hasDomain = false;
  let hasInfra = false;
  let hasApp = false;

  const checkDirs = async (parent) => {
    try {
      const subEntries = await readdir(parent, { withFileTypes: true });
      for (const ent of subEntries) {
        if (ent.isDirectory()) {
          const name = ent.name.toLowerCase();
          if (name === "domain") hasDomain = true;
          if (name === "infrastructure" || name === "infra") hasInfra = true;
          if (name === "application" || name === "app") hasApp = true;
        }
      }
    } catch {
      // ignore
    }
  };

  await checkDirs(target);
  if (entrySet.has("src")) {
    await checkDirs(path.join(target, "src"));
  }

  if (hasDomain && (hasInfra || hasApp)) {
    architecture = {
      value: "layered",
      confidence: CONFIDENCE_LEVELS.HIGH,
      enforcement: ENFORCEMENT_MODES.ADVISORY,
    };
  } else if (entrySet.has("src") || entrySet.has("lib") || entrySet.has("utils") || entrySet.has("services")) {
    architecture = {
      value: null,
      confidence: CONFIDENCE_LEVELS.LOW,
      enforcement: ENFORCEMENT_MODES.NONE,
    };
  }

  // 5. Generate Discovered Rules
  const discoveredRules = [];

  if (testing.detected && testing.confidence === CONFIDENCE_LEVELS.HIGH) {
    discoveredRules.push({
      id: "TEST.REQUIRED",
      severity: "MEDIUM",
      source: "discovered",
      blocking: false,
      why: "Automated test suite was detected in repository manifests.",
      fix: "Run test suite to verify changes.",
      confidence: testing.confidence,
      check: {
        type: "adapter",
        adapter: "test-runner",
        command: testing.command,
      },
    });
  }

  if (architecture.value === "layered" && architecture.confidence === CONFIDENCE_LEVELS.HIGH) {
    discoveredRules.push({
      id: "ARCH.NO_DIRECT_DATABASE_ACCESS",
      severity: "MEDIUM",
      source: "discovered",
      blocking: false,
      why: "Clean architecture requires domain layer isolation from infrastructure.",
      fix: "Depend on domain abstractions or repository interfaces.",
      confidence: architecture.confidence,
      check: {
        type: "adapter",
        adapter: "architecture-layers",
      },
    });
  }

  return {
    schemaVersion: 1,
    languages: [...new Set(languages)].sort(),
    testing,
    linting,
    architecture,
    discoveredRules,
  };
}

export function canonicalizeBaseline(baseline) {
  if (!baseline || !Array.isArray(baseline.entries)) {
    return { schemaVersion: 1, entries: [] };
  }
  const entries = baseline.entries.map((entry) => {
    const fps = entry.fingerprints ?? [];
    if (new Set(fps).size !== fps.length) {
      throw new Error(`Duplicate fingerprint detected for rule ${entry.ruleId}`);
    }
    return {
      ruleId: entry.ruleId,
      fingerprints: [...fps].sort(),
      ...(entry.reviewBy ? { reviewBy: entry.reviewBy } : {}),
    };
  });
  return {
    schemaVersion: baseline.schemaVersion ?? 1,
    entries: entries.sort((a, b) => a.ruleId.localeCompare(b.ruleId)),
  };
}

export function canonicalizeRules(rules) {
  const seenIds = new Set();
  const sorted = [...(rules ?? [])].sort((a, b) => a.id.localeCompare(b.id));
  for (const r of sorted) {
    if (seenIds.has(r.id)) {
      throw new Error(`Duplicate rule ID detected: ${r.id}`);
    }
    seenIds.add(r.id);
  }
  return sorted;
}

export async function computePersistedPolicyLockData(target, packageRoot, rules, baseline) {
  const identity = await readCapabilityPolicyIdentityForLock(target, packageRoot);
  return computePolicyLockData(rules, baseline, identity.policy);
}

export function computePolicyLockData(rules, baseline, capabilityPolicy = null) {
  const canonicalRules = canonicalizeRules(rules);
  const canonicalBase = canonicalizeBaseline(baseline);
  const rulesDigest = sha256(canonicalFingerprint(canonicalRules));
  const baselineDigest = sha256(canonicalFingerprint(canonicalBase));
  // The capability policy participates in the lock only when the artifact
  // exists, keeping historical locks stable for projects that never adopt
  // durable actions.
  const capabilityPolicyDigest =
    capabilityPolicy && typeof capabilityPolicy === "object"
      ? sha256(canonicalFingerprint(capabilityPolicy))
      : null;
  const fullDigest =
    capabilityPolicyDigest === null
      ? sha256(`${rulesDigest}:${baselineDigest}`)
      : sha256(`${rulesDigest}:${baselineDigest}:${capabilityPolicyDigest}`);

  return {
    schemaVersion: 1,
    algorithm: "sha256",
    digest: `sha256:${fullDigest}`,
    rulesDigest: `sha256:${rulesDigest}`,
    baselineDigest: `sha256:${baselineDigest}`,
    ...(capabilityPolicyDigest === null
      ? {}
      : { capabilityPolicyDigest: `sha256:${capabilityPolicyDigest}` }),
    capturedAt: new Date().toISOString(),
  };
}

export async function detectPolicyCapability(target, packageRoot) {
  const rulesRel = PROJECT_ARTIFACT_PATHS.policyRules;
  const baselineRel = PROJECT_ARTIFACT_PATHS.policyBaseline;
  const discoveryRel = PROJECT_ARTIFACT_PATHS.policyDiscovery;
  const lockRel = PROJECT_ARTIFACT_PATHS.policyLock;
  const capabilityRel = PROJECT_ARTIFACT_PATHS.capabilityPolicy;

  const hasRules = await fileExists(path.join(target, rulesRel));
  const hasBaseline = await fileExists(path.join(target, baselineRel));
  const hasDiscovery = await fileExists(path.join(target, discoveryRel));
  const hasLock = await fileExists(path.join(target, lockRel));
  const hasCapabilityPolicy = await fileExists(path.join(target, capabilityRel));

  if (!hasRules && !hasBaseline && !hasDiscovery && !hasLock && !hasCapabilityPolicy) {
    return "NOT_PRESENT";
  }

  try {
    if (hasRules) await readProjectRules(target, packageRoot);
    if (hasBaseline) await readBaseline(target, packageRoot);
    if (hasDiscovery) await readDiscoveryReport(target, packageRoot);
    if (hasLock) await readPolicyLock(target, packageRoot);
    // A capability policy is policy configuration: its presence makes the
    // executable-policy subsystem applicable and it must fail closed when
    // malformed.
    if (hasCapabilityPolicy) {
      const { loadCapabilityPolicy } = await import("./capability-policy.js");
      await loadCapabilityPolicy(target, packageRoot);
    }
    return "AVAILABLE";
  } catch {
    return "INVALID";
  }
}

export async function evaluateTargetPolicy({
  target = process.cwd(),
  packageRoot,
  taskId = null,
  files = null,
  overrideAdapters = null,
  now = new Date().toISOString(),
} = {}) {
  const capability = await detectPolicyCapability(target, packageRoot);
  if (capability === "NOT_PRESENT") {
    return {
      status: "VALID",
      capability: "NOT_PRESENT",
      rules: [],
      provenRules: 0,
      inertRules: 0,
      unsupportedRules: 0,
      baselineViolations: 0,
      newViolations: [],
      resolvedViolations: [],
      ratchetedBaseline: null,
      lock: { status: "NOT_APPLICABLE" },
      drift: { detected: false },
      errors: [],
      warnings: [],
    };
  }

  if (capability === "INVALID") {
    return {
      status: "INVALID",
      capability: "INVALID",
      rules: [],
      provenRules: 0,
      inertRules: 0,
      unsupportedRules: 0,
      baselineViolations: 0,
      newViolations: [],
      resolvedViolations: [],
      ratchetedBaseline: null,
      lock: { status: "INVALID" },
      drift: { detected: false },
      errors: [
        {
          code: "E_POLICY_INVALID",
          why: "Policy configuration or baseline artifacts are malformed or fail schema validation.",
          fix: "Validate and repair rules.json, baseline.json, or discovery.json against schemas.",
        },
      ],
      warnings: [],
    };
  }

  const rules = await loadEffectiveRules(target, packageRoot);
  const baseline = await readBaseline(target, packageRoot);
  const errors = [];
  const warnings = [];
  const evaluatedRules = [];
  const rawViolations = [];

  // Active lock verification
  const lockVerification = await verifyPolicyLock(target, packageRoot);
  if (lockVerification.status === "MISMATCH") {
    const expStr = typeof lockVerification.expected === "object" ? lockVerification.expected.digest : lockVerification.expected;
    const obsStr = typeof lockVerification.observed === "object" ? lockVerification.observed.digest : lockVerification.observed;
    errors.push({
      code: "POLICY_LOCK_MISMATCH",
      why: `Persisted policy lock does not match current effective policy: expected ${expStr}, observed ${obsStr}`,
      fix: "Re-evaluate effective rules and update policy.lock or restore modified rules.",
    });
  }

  for (const rule of rules) {
    const adapterId = rule.check?.adapter ?? (typeof rule.check === "string" ? rule.check : null);
    const adapter = overrideAdapters?.[adapterId] ?? getPolicyAdapter(adapterId);

    if (!adapter) {
      evaluatedRules.push({
        ruleId: rule.id,
        rule,
        status: "UNSUPPORTED",
        why: `No policy adapter found for ${adapterId}`,
        fix: "Configure an existing adapter or remove the rule.",
      });
      continue;
    }

    let checkResult;
    try {
      checkResult = await adapter.check({ target, rule, files });
    } catch (error) {
      errors.push({
        code: "POLICY_EVALUATION_FAILED",
        ruleId: rule.id,
        why: `Policy evaluation threw an unexpected error for rule ${rule.id}: ${error.message}`,
        fix: "Inspect adapter check logic and target files for unhandled exceptions.",
      });
      checkResult = { passed: false, isInert: false, violations: [], error: error.message };
    }

    // Handle inert checks
    if (checkResult.isInert) {
      if (rule.source === "discovered") {
        // Gracefully downgrade discovered rules
        evaluatedRules.push({
          ruleId: rule.id,
          rule,
          status: "UNSUPPORTED",
          isInert: true,
          why: "Discovered rule is currently inert (no applicable files in repository).",
          fix: "Rule will automatically activate when matching files are present.",
        });
        continue;
      } else if (rule.source === "project" && rule.blocking) {
        errors.push({
          code: "CHECK_INERT",
          ruleId: rule.id,
          why: `Configured blocking check ${rule.id} has no effective target scope.`,
          fix: "Provide an applicable target scope or mark rule non-blocking.",
        });
        evaluatedRules.push({
          ruleId: rule.id,
          rule,
          status: "INERT",
          isInert: true,
          errorCode: "CHECK_INERT",
          why: `Configured blocking check ${rule.id} has no effective target scope.`,
          fix: "Provide an applicable target scope or mark rule non-blocking.",
        });
        continue;
      } else {
        evaluatedRules.push({
          ruleId: rule.id,
          rule,
          status: "INERT",
          isInert: true,
          why: "Check is enabled but has no effective target.",
          fix: "Configure an applicable scope or mark the rule as unsupported.",
        });
        continue;
      }
    }

    // Verify mutation for blocking rules
    let mutationProof = null;
    if (rule.blocking) {
      mutationProof = await verifyRuleMutation({ target, rule, adapter });
      if (mutationProof.status !== "PROVEN") {
        if (mutationProof.errorCode === "CHECK_MUTATION_EXECUTION_ERROR") {
          errors.push({
            code: "CHECK_MUTATION_EXECUTION_ERROR",
            ruleId: rule.id,
            why: mutationProof.why,
            fix: mutationProof.fix,
          });
        } else {
          errors.push({
            code: "CHECK_MUTATION_NOT_DETECTED",
            ruleId: rule.id,
            why: mutationProof.why,
            fix: mutationProof.fix,
          });
        }
      }
    }

    if (checkResult.violations && checkResult.violations.length > 0) {
      rawViolations.push(...checkResult.violations);
    }

    evaluatedRules.push({
      ruleId: rule.id,
      rule,
      status: rule.blocking
        ? mutationProof?.status === "PROVEN" ? "PROVEN" : "UNPROVEN"
        : "ACTIVE",
      mutationProof,
      violations: checkResult.violations ?? [],
    });
  }

  // Baseline evaluation
  const baselineEval = evaluateBaselineViolations(baseline, rawViolations, { now });
  warnings.push(...baselineEval.warnings);

  for (const newViolation of baselineEval.newViolations) {
    const matchingRule = rules.find((r) => r.id === newViolation.ruleId);
    if (matchingRule?.blocking) {
      errors.push({
        code: "NEW_VIOLATION",
        ruleId: newViolation.ruleId,
        file: newViolation.file,
        line: newViolation.line,
        fingerprint: newViolation.fingerprint,
        why: `New policy violation detected not present in baseline: ${newViolation.message}`,
        fix: matchingRule.fix || "Resolve the violation before completing the task.",
      });
    } else {
      warnings.push({
        code: "NEW_ADVISORY_VIOLATION",
        ruleId: newViolation.ruleId,
        file: newViolation.file,
        message: newViolation.message,
      });
    }
  }

  // Drift evaluation against task policy snapshot
  let drift = null;
  if (taskId) {
    const taskSnapshot = await readTaskPolicySnapshot(target, taskId, packageRoot);
    if (taskSnapshot) {
      const currentLock = await computePersistedPolicyLockData(target, packageRoot, rules, baseline);
      if (taskSnapshot.policyDigest !== currentLock.digest) {
        const policyDiff = diffPolicies(
          { rules: taskSnapshot.rules, baseline: taskSnapshot.baseline, baselineDigest: taskSnapshot.baselineDigest },
          { rules, baseline, baselineDigest: currentLock.baselineDigest },
        );
        drift = {
          detected: true,
          classification: policyDiff.classification,
          snapshotDigest: taskSnapshot.policyDigest,
          currentDigest: currentLock.digest,
          changes: policyDiff.changes,
        };

        if (policyDiff.classification === "WEAKEN") {
          errors.push({
            code: "POLICY_WEAKENING",
            why: "Policy weakening detected relative to task activation snapshot.",
            fix: "Restore the original policy rules or obtain explicit project authority.",
          });
        } else if (policyDiff.classification === "UNKNOWN") {
          errors.push({
            code: "POLICY_DRIFT_UNKNOWN",
            why: "Policy drift detected against task snapshot but baseline state cannot be semantically compared.",
            fix: "Re-verify the task under the current policy state.",
          });
        } else if (policyDiff.classification === "TIGHTEN") {
          warnings.push({
            code: "POLICY_TIGHTENING",
            why: "Policy tightened after task activation. Re-verification required.",
            fix: "Re-run verification checks under the tightened policy.",
          });
        }
      }
    }
  }

  const currentLock = await computePersistedPolicyLockData(target, packageRoot, rules, baseline);

  return {
    status: errors.length === 0 ? "VALID" : "INVALID",
    rules: evaluatedRules,
    provenRules: evaluatedRules.filter((r) => r.status === "PROVEN").length,
    inertRules: evaluatedRules.filter((r) => r.status === "INERT").length,
    unsupportedRules: evaluatedRules.filter((r) => r.status === "UNSUPPORTED").length,
    baselineViolations: baselineEval.baselinedViolations.length,
    newViolations: baselineEval.newViolations,
    resolvedViolations: baselineEval.resolvedViolations,
    ratchetedBaseline: baselineEval.ratchetedBaseline,
    lock: currentLock,
    drift: drift ?? { detected: false },
    errors,
    warnings,
  };
}

export async function loadEffectiveRules(target, packageRoot) {
  const ruleMap = new Map();

  // 1. Built-in rules
  for (const rule of BUILTIN_POLICY_RULES) {
    ruleMap.set(rule.id, { ...rule });
  }

  // 2. Discovered rules
  let discovery = await readDiscoveryReport(target, packageRoot);
  if (!discovery) {
    discovery = await discoverPolicy({ target });
  }
  for (const rule of discovery.discoveredRules ?? []) {
    ruleMap.set(rule.id, { ...rule });
  }

  // 3. Project rules (highest precedence)
  const projectRules = await readProjectRules(target, packageRoot);
  if (projectRules) {
    for (const rule of projectRules) {
      ruleMap.set(rule.id, { ...rule, source: "project" });
    }
  }

  return [...ruleMap.values()].sort((a, b) => a.id.localeCompare(b.id));
}

export async function loadPolicyIdentity(target, packageRoot, taskId) {
  const { E_ACTION_POLICY_DRIFT, E_ACTION_POLICY_LOCK_REQUIRED } = await import("./error-codes.js");
  const capability = await readCapabilityPolicyIdentityForLock(target, packageRoot);
  const lock = await verifyPolicyLock(target, packageRoot);
  const snapshot = taskId ? await readTaskPolicySnapshot(target, taskId, packageRoot) : null;

  if (capability.policy && lock.status !== "VALID") {
    return {
      status: lock.status === "MISMATCH" ? "DRIFT" : "INVALID",
      code: lock.status === "MISMATCH" ? E_ACTION_POLICY_DRIFT : E_ACTION_POLICY_LOCK_REQUIRED,
      ...(lock.status === "MISMATCH" ? { mismatches: lock.mismatches } : {}),
    };
  }

  // A modern task snapshot must bind the current capability policy before any
  // side-effecting action may be authorized.
  if (
    capability.digest
    && snapshot
    && snapshot.capabilityPolicyDigest !== capability.digest
  ) {
    return {
      status: "DRIFT",
      code: E_ACTION_POLICY_DRIFT,
    };
  }

  // A modern capability policy without a task snapshot has no epoch to bind:
  // authorization cannot proceed for a task-scoped action.
  if (capability.digest && taskId && !snapshot) {
    return {
      status: "INVALID",
      code: E_ACTION_POLICY_LOCK_REQUIRED,
    };
  }

  return {
    status: "VALID",
    lockDigest: lock.digest ?? null,
    taskPolicyDigest: snapshot?.policyDigest ?? null,
    capabilityPolicyFingerprint: capability.fingerprint,
    capabilityPolicyDigest: capability.digest,
  };
}

export async function readCapabilityPolicyIdentityForLock(target, packageRoot) {
