}

export function evaluateProgress({ state, events = [] } = {}) {
  const signals = [];
  let status = PROGRESS_STATUS.ADVANCING;

  if (!state) {
    return { status, signals };
  }

  const taskEvents = progressTaskEvents(events, state.taskId);
  const latestLegacy = latestDiagnosisForTask(taskEvents, state.taskId);
  const resolvedDiagnostic = resolveCurrentCycleDiagnostic(taskEvents, state.taskId, state.verificationCycle ?? null);
  const latestDiag = resolvedDiagnostic?.details ?? latestLegacy?.details ?? null;

  let latestGainClassification = latestDiag?.informationGain ?? null;
  let structuredStall = null;
  if (resolvedDiagnostic?.sourceModel === "STRUCTURED_DIAGNOSTIC_CASE_V1") {
    if (!Array.isArray(latestDiag.evidenceRefs)) {
      latestDiag.evidenceRefs = [...new Set(
        (latestDiag.hypotheses ?? []).flatMap((hypothesis) => hypothesis.evidenceRefs ?? []),
      )];
    }
    // Canonical structured-stall truth; compatibility classification is presentation only.
    structuredStall = summarizeInformationGain(
      taskEvents, state.taskId,
      { verificationCycle: state.verificationCycle ?? null },
    );
    latestDiag.effectiveInformationGain = !(structuredStall.stalled);
    latestGainClassification = structuredStall.latestGain?.classification ?? null;
  }

  // Build checksById index for resolving requirement from check IDs
  const checksById = new Map();
  for (const check of state.checks ?? []) {
    if (check.id) checksById.set(check.id, check);
    if (check.checkId) checksById.set(check.checkId, check);
  }
  for (const event of progressVerificationEvents(taskEvents, state.taskId)) {
    if (event.event === "VERIFICATION_RECORDED" && event.details) {
      if (event.details.id) checksById.set(event.details.id, event.details);
      if (event.details.checkId) checksById.set(event.details.checkId, event.details);
    }
  }

  // 1. Check if latest diagnosis has NO information gain (global stall)
  const legacyStalled = resolvedDiagnostic?.sourceModel !== "STRUCTURED_DIAGNOSTIC_CASE_V1"
    && Boolean(latestDiag) && latestGainClassification === "NONE";
  // Single normalized diagnostic-stall truth: structured diagnostics defer to
  // the canonical structured stall evaluator; legacy diagnoses keep their
  // compatibility rule (informationGain NONE).
  const diagnosticStalled =
    resolvedDiagnostic?.sourceModel === "STRUCTURED_DIAGNOSTIC_CASE_V1"
      ? Boolean(structuredStall?.stalled)
      : Boolean(legacyStalled);
  if (diagnosticStalled) {
    status = PROGRESS_STATUS.STALLED;
    signals.push({
      code: PROGRESS_SIGNAL.NO_DIAGNOSTIC_INFORMATION_GAIN,
      severity: "BLOCKING_FOR_RETRY",
      message: resolvedDiagnostic?.sourceModel === "STRUCTURED_DIAGNOSTIC_CASE_V1"
        ? "Latest diagnostic state introduces no effective new information relative to the prior comparable diagnostic state."
        : "Latest diagnosis repeats the prior hypothesis with the same evidence.",
      verificationCycles: [latestDiag.verificationCycle],
      ...(structuredStall?.latestGain
        ? { classification: structuredStall.latestGain.classification, effectiveGain: false }
        : {}),
    });
  }

  // 2. Track failed requirements across distinct verification cycles
  const reqCycles = new Map();
  const checks = state.checks ?? [];
  for (const check of checks) {
    if (check.status === "failed" || check.status === "blocked") {
      const cycle = check.details?.verificationCycle ?? state.verificationCycle ?? 1;
      const req = check.requirement ?? "default";
      if (!reqCycles.has(req)) reqCycles.set(req, new Set());
      reqCycles.get(req).add(cycle);
    }
  }

  // Also extract from VERIFICATION_RECORDED events
  for (const event of progressVerificationEvents(taskEvents, state.taskId)) {
    if (event.event === "VERIFICATION_RECORDED") {
      const details = event.details ?? {};
      if (details.status === "failed" || details.status === "blocked") {
        const cycle = details.verificationCycle ?? 1;
        const req = details.requirement ?? "default";
        if (!reqCycles.has(req)) reqCycles.set(req, new Set());
        reqCycles.get(req).add(cycle);
      }
    }
  }

  const latestDiagReqs = diagnosisRequirements(latestDiag, checksById);

  for (const [req, cyclesSet] of [...reqCycles.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    if (cyclesSet.size >= 3) {
      const sortedCycles = [...cyclesSet].sort((a, b) => a - b);
      const isLatestStalledForThisReq = diagnosticStalled && latestDiagReqs.includes(req);
      if (isLatestStalledForThisReq) {
        if (!signals.some((s) => s.code === PROGRESS_SIGNAL.REPEATED_FAILURE_WITH_SAME_DIAGNOSIS && s.requirement === req)) {
          signals.push({
            code: PROGRESS_SIGNAL.REPEATED_FAILURE_WITH_SAME_DIAGNOSIS,
            severity: "BLOCKING_FOR_RETRY",
            message: `Requirement "${req}" failed in ${cyclesSet.size} cycles and the latest diagnoses contain no new information.`,
            verificationCycles: sortedCycles,
            requirement: req,
          });
        }
        status = PROGRESS_STATUS.STALLED;
      } else {
        if (!signals.some((s) => s.code === PROGRESS_SIGNAL.REPEATED_FAILED_REQUIREMENT && s.requirement === req)) {
          signals.push({
            code: PROGRESS_SIGNAL.REPEATED_FAILED_REQUIREMENT,
            severity: "ADVISORY",
            message: `Requirement "${req}" failed across ${cyclesSet.size} distinct verification cycles.`,
            verificationCycles: sortedCycles,
            requirement: req,
          });
        }
        if (status !== PROGRESS_STATUS.STALLED) {
          status = PROGRESS_STATUS.WATCH;
        }
      }
    }
  }

  // 3. High cycle count
  const currentCycle = state.verificationCycle ?? 1;
  if (currentCycle >= 4) {
    signals.push({
      code: PROGRESS_SIGNAL.HIGH_CORRECTION_CYCLE_COUNT,
      severity: "ADVISORY",
      message: `Task has reached verification cycle ${currentCycle}.`,
      verificationCycles: Array.from({ length: currentCycle }, (_, i) => i + 1),
    });
    if (status !== PROGRESS_STATUS.STALLED) {
      status = PROGRESS_STATUS.WATCH;
    }
  }

  // Sort signals deterministically
  signals.sort((left, right) =>
    left.code.localeCompare(right.code) || (left.requirement || "").localeCompare(right.requirement || "")
  );

  return {
    status,
    signals,
  };
}

function publicSchemaVersions() {
  return Object.fromEntries(
    [...new Set(Object.values(ARTIFACT_REGISTRY)
      .filter((artifact) => artifact.isPublic && artifact.isPersisted)
      .map((artifact) => artifact.schema)
      .filter(Boolean))]
      .sort()
      .map((schema) => [schema, [SCHEMA_COMPATIBILITY_POLICY.schemaVersion]]),
  );
}

export function assertFailureClass(value) {
  if (!FAILURE_CLASSES.includes(value)) {
    throw new Error(`Unknown failure class: ${value}`);
  }
  return value;
}

export function assertWorkPhase(value) {
  if (!WORK_PHASES.includes(value)) {
    throw new Error(`Unknown work phase: ${value}`);
  }
  return value;
}

export function isValidTransition(from, to) {
  if (!WORK_PHASES.includes(from) || !WORK_PHASES.includes(to)) return false;
  if (to === "BLOCKED" && from !== "COMPLETE" && from !== "BLOCKED") return true;
  return WORK_TRANSITIONS[from].includes(to);
}

function assertKnownGuides(guides) {
  const unknown = guides.filter((guide) => !GUIDE_IDS.includes(guide));
  if (unknown.length > 0) throw new Error(`Receipt contains unknown guide: ${unknown[0]}`);
  if (new Set(guides).size !== guides.length) throw new Error("Receipt selectedGuides must not contain duplicates");
}

export function assertReceiptSemantics(receipt, options = {}) {
  const evidence = receipt.evidence ?? [];
  if (receipt.verificationCycle !== undefined
    && (!Number.isInteger(receipt.verificationCycle) || receipt.verificationCycle < 1)) {
    throw new Error("receipt.verificationCycle must be a positive integer");
  }
  assertEvidenceList(evidence, "receipt.evidence");

  for (const [index, check] of receipt.checks.entries()) {
    if (check?.schemaVersion !== undefined || check?.id !== undefined || check?.evidenceKind !== undefined) {
      assertCheck(check, `receipt.checks[${index}]`, options);
      continue;
    }
    if (check?.status === "passed") {
      const hasCommandOrResult = [check.command, check.result, check.name]
        .some((value) => typeof value === "string" && value.trim().length > 0);
      if (!hasCommandOrResult) {
        throw new Error(`receipt.checks[${index}] passed check requires a command or result`);
      }
    }
  }

  if (receipt.evidenceCoverage !== undefined) {
    assertCoverageList(receipt.evidenceCoverage, "receipt.evidenceCoverage");
  }

  if (receipt.status === "complete") {
    const verificationEvidence = evidence.filter((item) => ["OBSERVED", "INFERRED"].includes(item.kind));
    if (verificationEvidence.length === 0) {
      throw new Error("COMPLETE receipt requires verification evidence");
    }
  }

  const publicationEvidence = [
    [receipt.publication.committed, ["commit", "committed"], "committed", "commit"],
    [receipt.publication.pushed, ["git push", "pushed"], "pushed", "push"],
    [receipt.publication.deployed, ["deploy", "deployed", "deployment"], "deployed", "deployment"],
  ];
  for (const [claimed, terms, field, label] of publicationEvidence) {
    if (claimed && !evidenceMatches(evidence, terms)) {
      const error = new Error(`publication.${field} requires ${label} evidence`);
      error.code = "E_PUBLICATION_CLAIM_UNVERIFIED";
      throw error;
    }
  }

  if (["committed", "pushed", "published", "deployed"].includes(receipt.publicationStatus)) {
    const requiredTerms = receipt.publicationStatus === "committed"
      ? ["commit", "committed"]
      : receipt.publicationStatus === "pushed"
        ? ["git push", "pushed"]
        : receipt.publicationStatus === "deployed"
          ? ["deploy", "deployed", "deployment"]
          : ["publish", "published", "release"];
    if (!evidenceMatches(evidence, requiredTerms)) {
      const error = new Error(`publicationStatus ${receipt.publicationStatus} requires publication evidence`);
      error.code = "E_PUBLICATION_CLAIM_UNVERIFIED";
      throw error;
    }
  }
  if (receipt.productionReadiness === "ready" && !evidenceMatches(evidence, ["production readiness", "production validation", "deployment"])) {
    const error = new Error("productionReadiness ready requires production evidence");
    error.code = "E_PRODUCTION_READINESS_UNVERIFIED";
    throw error;
  }

  if (receipt.review.independent === true) {
    const implementer = receipt.review.implementerId;
    const reviewer = receipt.review.reviewerId;
    if (typeof implementer !== "string" || typeof reviewer !== "string" || implementer === reviewer) {
      throw new Error("independent review requires distinct implementer and reviewer identities");
    }
  }
  return receipt;
}

export function assertSecretFree(value) {
  assertJsonLimits(value, "secret-free artifact");
  const violations = [];
  findSecretLikeValues(value, "$", violations);
  if (violations.length > 0) throw new Error(violations.join("; "));
}

export async function validateReceipt(receipt, packageRoot, options = {}) {
  assertSecretFree(receipt);
  const schema = await readSchema("execution-receipt", packageRoot);
  assertSchema(receipt, schema, "execution receipt");
  assertKnownGuides(receipt.selectedGuides);
  return assertReceiptSemantics(receipt, options);
}

function assertRepositoryOnlyFreshness(freshness, stateRel, contractRel) {
  if (freshness.status !== "REVALIDATION_REQUIRED") {
    throw reconcileError(
      "E_RECONCILE_NOT_STALE",
      `work-state checkpoint is ${freshness.status === "FRESH" ? "fresh" : "not revalidation-required"}; no reconciliation required`,
      [stateRel, contractRel],
    );
  }
  if (freshness.reasons.length === 1 && freshness.reasons[0] === "REPOSITORY_CHANGED") return;
  throw reconcileError(
    "E_RECONCILE_UNSUPPORTED_DRIFT",
    `reconcile-closure only reconciles repository fingerprint drift; unresolved drift: ${freshness.reasons.join(", ")}`,
    [stateRel, contractRel],
  );
}

function reconcileError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

async function validateReconciliationCheckpoint({
  target,
  packageRoot,
  taskId,
  state,
  stateRel,
  contractRel,
  eventsRel,
  receiptRel,
  authorityContext,
  runtimeContext,
}) {
  const freshness = await classifyLoadedWorkState({ target, state, contractFile: contractRel });
  if (freshness.status !== "REVALIDATION_REQUIRED") {
    await assertFreshReviewingRecoveryIsAuthorized({
      target,
      packageRoot,
      taskId,
      state,
      eventsRel,
      receiptRel,
    });
  }
  assertRepositoryOnlyFreshness(freshness, stateRel, contractRel);

  const ledger = await validateEventLedger(target, packageRoot, { taskId });
  if (!ledger.valid) {
    const first = ledger.errors[0];
    throw reconcileError(
      "E_RECONCILE_LEDGER_INVALID",
      `append-only event ledger must be valid before reconciliation: ${first?.message ?? "invalid ledger"}`,
      [eventsRel],
    );
  }

  if (state.phase === "CORRECTING") {
    // Recovery retains this phase; it cannot manufacture diagnosis or authorize
    // a retry that the ordinary correction transition would refuse.
    assertDiagnosingToCorrectingTransition({
      state, events: ledger.events, resolveDiagnosis: resolveCurrentCycleDiagnostic,
    });
  }

  const ownership = await resolveTaskClaimState(target, { taskId, packageRoot });
  if (!ownership.ownershipValid || !ownership.mutationAllowed || ownership.claimState !== "ACTIVE") {
    const first = ownership.ownershipErrors?.[0] ?? ownership.errors?.[0] ?? {};
    throw reconcileError(
      first.code ?? "E_TASK_CLAIM_OWNERSHIP_INCONSISTENT",
      `reconcile-closure requires active, valid task claim ownership: ${first.message ?? ownership.claimState}`,
      [stateRel, eventsRel],
    );
  }

  if (state.phase !== "REVIEWING" || !Object.prototype.hasOwnProperty.call(state, "lastCompletionAttempt")) {
    return state;
  }

  const recovery = await authorizeCompletionRecoveryOrRebind({
    target,
    packageRoot,
    taskId,
    authorityContext,
    runtimeContext,
  });
  if (!recovery.recoveryAuth.authorized) {
    const first = recovery.recoveryAuth.errors?.[0] ?? {};
    throw reconcileError(
      first.code ?? "E_COMPLETION_RECOVERY_UNAUTHORIZED",
      `REVIEWING reconciliation requires authorized completion recovery: ${first.message ?? "unauthorized"}`,
      [stateRel, receiptRel],
    );
  }
  return recovery.rebound ? recovery.state : state;
}

export function detectOscillation(strategies) {
  return detectOscillationImpl(strategies);
}

export function evaluateInterventionEffectiveness(trace, surfacesByCycle) {
  return evaluateInterventionEffectivenessImpl(trace, surfacesByCycle);
}

function signatureSetsByCycle(trace) {
  const byCycle = new Map();
  for (const entry of trace.failureSignatures) {
    for (const cycle of entry.cycles ?? []) {
      if (!byCycle.has(cycle)) byCycle.set(cycle, new Set());
      byCycle.get(cycle).add(entry.signature);
    }
  }
  return byCycle;
}

export function summarizeHypotheses(trace) {
  const summary = { created: 0, supported: 0, weakened: 0, falsified: 0, superseded: 0, unresolved: 0, open: 0 };

  const pseudoEvents = [
    ...trace.diagnostics.cases.map((diagnosticCase) => ({
      seq: diagnosticCase.sequence,
      event: "DIAGNOSTIC_CASE_RECORDED",
      details: diagnosticCase,
    })),
    ...trace.diagnostics.legacyDiagnoses.map((legacy) => ({
      seq: legacy.sequence,
      event: "DIAGNOSIS_RECORDED",
      details: legacy,
    })),
    ...trace.diagnostics.dispositions.map((disposition) => ({
      seq: disposition.sequence,
      event: "HYPOTHESIS_DISPOSITION_RECORDED",
      details: disposition,
    })),
  ];
  const projection = projectHypothesisStates(pseudoEvents);

  for (const hypothesis of projection.hypotheses) {
    if (hypothesis.id === "h-legacy" && hypothesis.sourceEventSeq !== null) {
      summary.created += 1;
    } else if (hypothesis.id !== "h-legacy") {
      summary.created += 1;
    }
    const status = hypothesis.currentStatus.toLowerCase();
    if (summary[status] !== undefined) summary[status] += 1;
  }
  summary.open = projection.openHypotheses.length;
  return summary;
}

function assertRepositoryPath(relativePath) {
  if (typeof relativePath !== "string" || relativePath.length === 0
    || relativePath.startsWith("/") || /^[A-Za-z]:[\\/]/u.test(relativePath)
    || /[\u0000-\u001f\u007f]/u.test(relativePath) || relativePath.includes("\\")) {
    throw repositoryError("E_REVISION_CONTENT_UNAVAILABLE", "Repository path must be a non-empty relative path");
  }
  const normalized = path.posix.normalize(relativePath);
  if (normalized === "." || normalized === ".." || normalized.startsWith("../") || normalized !== relativePath) {
    throw repositoryError("E_REVISION_CONTENT_UNAVAILABLE", `Repository path escapes the target: ${relativePath}`);
  }
  return normalized;
}

function assertRevision(value, label = "revision") {
  if (typeof value !== "string" || !value.trim() || value.startsWith("-") || value.includes("\0") || /\s/u.test(value)) {
    throw repositoryError("E_REVISION_NOT_FOUND", `${label} must be a non-empty opaque revision identifier`);
  }
  return value;
}

export async function currentChangedPaths(target, { paths = null } = {}) {
  try {
    const entries = await repositoryStatusEntries(target, { paths });
    return [...new Set(entries
      .flatMap((entry) => [entry.path, entry.sourcePath].filter(Boolean))
      .filter((relativePath) => !relativePath.startsWith(".forgeloop/")))].sort((a, b) => a.localeCompare(b));
  } catch {
    return null;
  }
}

export async function currentRepositoryFingerprint(target) {
  try {
    const [{ stdout: branchOutput }, { stdout: headOutput }] = await Promise.all([
      execFileAsync("git", ["-C", target, "branch", "--show-current"], { windowsHide: true }),
      execFileAsync("git", ["-C", target, "rev-parse", "HEAD"], { windowsHide: true }),
    ]);
    return {
      branch: branchOutput.trim() || null,
      head: headOutput.trim() || null,
    };
  } catch {
    return { branch: null, head: null };
  }
}

function parseStatusZ(output) {
  const tokens = text(output).split("\0").filter(Boolean);
  const entries = [];
  for (let index = 0; index < tokens.length; index += 1) {
    const item = tokens[index];
    const status = item.slice(0, 2);
    const firstPath = item.slice(3).replace(/^\t/u, "");
    if (status.includes("R") || status.includes("C")) {
      const sourcePath = assertRepositoryPath(tokens[index + 1] ?? "");
      const filePath = assertRepositoryPath(firstPath);
      entries.push({ path: filePath, sourcePath, status, score: null });
      index += 1;
    } else {
      entries.push({ path: assertRepositoryPath(firstPath), sourcePath: null, status, score: null });
    }
  }
  return entries.sort((left, right) => left.path.localeCompare(right.path));
}

function repositoryError(code, message, cause = null) {
  const error = new Error(message);
  error.code = code;
  if (cause) error.cause = cause;
  return error;
}

export async function repositoryHead(target, { revision = "HEAD" } = {}) {
  const output = await runGit(target, ["rev-parse", "--verify", assertRevision(revision)]);
  return text(output).trim();
}

export async function repositoryObjectFormat(target) {
  const output = await runGit(target, ["rev-parse", "--show-object-format"]);
  return text(output).trim() || "sha1";
}

export async function repositoryStatusEntries(target, { paths = null } = {}) {
  const args = ["status", "--porcelain=v1", "-z", "--untracked-files=all"];
  if (Array.isArray(paths) && paths.length > 0) args.push("--", ...paths.map(assertRepositoryPath));
  return parseStatusZ(await runGit(target, args));
}

export async function repositoryWorktreeMetadata(target) {
  const [commonDirectory, gitDirectory, topLevel] = await Promise.all([
    runGit(target, ["rev-parse", "--git-common-dir"]),
    runGit(target, ["rev-parse", "--git-dir"]),
    runGit(target, ["rev-parse", "--show-toplevel"]),
  ]);
  return {
    commonDirectory: text(commonDirectory).trim(),
    gitDirectory: text(gitDirectory).trim(),
    topLevel: text(topLevel).trim(),
    objectFormat: await repositoryObjectFormat(target),
  };
}

async function runGit(target, args, { binary = false } = {}) {
  try {
    const result = await execFileAsync("git", ["-C", target, ...args], {
      ...GIT_EXECUTION_OPTIONS,
      ...(binary ? { encoding: "buffer" } : {}),
    });
    return result.stdout;
  } catch (error) {
    throw repositoryError(
      "E_REPOSITORY_GIT_COMMAND_FAILED",
      `Git command failed (${args.join(" ")}): ${String(error.stderr ?? error.message).trim()}`,
      error,
    );
  }
}

function text(value) {
  return Buffer.isBuffer(value) ? value.toString("utf8") : String(value ?? "");
}

function normalizePaths(paths, label) {
  try {
    return normalizeWriteClaims(paths ?? []);
  } catch (error) {
    throw responsibilityError("E_RESPONSIBILITY_INVALID", `${label}: ${error.message}`);
  }
}

export async function resolveResponsibilityStatus(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  const read = () => resolveLoadedResponsibilityStatus(target, { taskId, packageRoot });
  return withNativeReadScope(target, () => {
    if (getOperationalStore(target)) return withEventLedgerAudit(target, packageRoot, { taskId }, read);
    return read();
  });
}

function responsibilityError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "ResponsibilityError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export async function validateResponsibilityContract(value, packageRoot = getPackageRoot()) {
  try {
    assertSchema(value, await readSchema("responsibility", packageRoot), "responsibility contract");
  } catch (error) {
    throw responsibilityError("E_RESPONSIBILITY_INVALID", error.message);
  }
  try {
    const allowedPaths = normalizePaths(value.allowedPaths, "allowedPaths");
    const readOnlyPaths = normalizePaths(value.readOnlyPaths, "readOnlyPaths");
    const requiredCheckIds = [...new Set(value.requiredCheckIds)].sort();
    if (requiredCheckIds.length !== value.requiredCheckIds.length) {
      throw responsibilityError("E_RESPONSIBILITY_INVALID", "requiredCheckIds must not contain duplicates");
    }
    if (allowedPaths.some((item) => item === ".forgeloop" || item.startsWith(".forgeloop/"))) {
      throw responsibilityError("E_RESPONSIBILITY_INVALID", "allowedPaths cannot include ForgeLoop protocol metadata");
    }
    if (readOnlyPaths.some((item) => item === ".forgeloop" || item.startsWith(".forgeloop/"))) {
      throw responsibilityError("E_RESPONSIBILITY_INVALID", "readOnlyPaths cannot include ForgeLoop protocol metadata");
    }
    const normalized = {
      ...value,
      allowedPaths,
      readOnlyPaths,
      requiredCheckIds,
      frozenInputs: {
        contract: value.frozenInputs?.contract === true,
        route: value.frozenInputs?.route === true,
        claims: value.frozenInputs?.claims === true,
      },
      baseline: {
        contractFingerprint: value.baseline.contractFingerprint,
        routeFingerprint: value.baseline.routeFingerprint ?? null,
        claimsFingerprint: value.baseline.claimsFingerprint,
      },
    };
    assertSecretFree(normalized);
    return normalized;
  } catch (error) {
    if (error.code === "E_RESPONSIBILITY_INVALID") throw error;
    throw responsibilityError("E_RESPONSIBILITY_INVALID", error.message);
  }
}

const withoutTimestamp = (value) => {
  const copy = structuredClone(value);
  delete copy.lastUpdated;
  return copy;
};

export function buildResumableWorkStateFields({ events, resumedPhase }) {
  const steps = resumeStepsForPhase(resumedPhase);
  return {
    phase: resumedPhase,
    completedSteps: [...steps.completedSteps],
    pendingSteps: [...steps.pendingSteps],
    ...(events && events.length > 0 && cycleEvents(events) !== undefined
      ? { verificationCycle: cycleEvents(events) }
      : {}),
  };
}

export async function deriveResumePhaseFromLedger(target, packageRoot, taskId) {
  let ledger;
  try {
    ledger = await validateEventLedger(target, packageRoot, { taskId });
  } catch {
    return null;
  }
  if (!ledger?.valid) return null;
  const scoped = (ledger.events ?? []).filter((event) => !taskId || event.taskId === taskId);
  if (scoped.some((event) => event.event === "COMPLETION_VALIDATED")) return null;
  const positions = RESUME_PHASE_BY_MILESTONE;
  let derived = null;
  for (const event of scoped) {
    const phase = positions[event.event];
    if (phase) derived = phase;
  }
  return derived;
}

function routeSyncError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function sameStringList(left, right) {
  const a = [...(left ?? [])].sort();
  const b = [...(right ?? [])].sort();
  return a.length === b.length && a.every((value, index) => value === b[index]);
}

export function assertRevisionProvider(provider) {
  const required = [
    "detect",
    "getCurrentRevision",
    "getChangedEntries",
    "readContent",
    "getContentIdentity",
    "getRepositoryIdentity",
  ];
  if (!provider || typeof provider !== "object"
    || required.some((method) => typeof provider[method] !== "function")) {
    const error = new Error(`Revision provider must implement ${required.join(", ")}`);
    error.code = "E_REVISION_PROVIDER_INVALID";
    throw error;
  }
  return provider;
}

export async function resolveRevisionProvider({ target, providerName = null, registry } = {}) {
  const providers = registry ?? {};
  if (providerName) {
    const factory = providers[providerName];
    if (typeof factory !== "function") {
      const error = new Error(`Revision provider is unavailable: ${providerName}`);
      error.code = "E_REVISION_PROVIDER_UNAVAILABLE";
      throw error;
    }
    return assertRevisionProvider(await factory({ target }));
  }

  const available = [];
  for (const [name, factory] of Object.entries(providers)) {
    try {
      const provider = assertRevisionProvider(await factory({ target }));
      if (await provider.detect(target)) available.push({ name, provider });
    } catch {
      // Auto-detection ignores providers that cannot inspect this target.
    }
  }
  if (available.length === 1) return available[0].provider;
  if (available.length === 0) {
    const error = new Error("No revision provider can resolve the target repository");
    error.code = "E_REVISION_PROVIDER_UNAVAILABLE";
    throw error;
  }
  const error = new Error(`Multiple revision providers match the target: ${available.map(({ name }) => name).join(", ")}`);
  error.code = "E_REVISION_PROVIDER_AMBIGUOUS";
  throw error;
}

export function assertRouteInvariants(result) {
  const invariantError = (code, message) => {
    const error = new RouteInputError(message);
    error.code = code;
    return error;
  };
  if (!result || typeof result !== "object" || Array.isArray(result)) {
    throw invariantError("E_ROUTE_INVALID", "Route result must be an object");
  }
  if (!Array.isArray(result.guides) || new Set(result.guides).size !== result.guides.length) {
    throw invariantError("E_ROUTE_INVALID", "Route result contains duplicate guides");
  }
  if (result.contractFingerprint !== undefined && !/^[a-f0-9]{64}$/.test(result.contractFingerprint)) {
    throw invariantError("E_ROUTE_INVALID", "Route contractFingerprint must be a lowercase SHA-256 fingerprint");
  }
  if (result.executionProfile !== undefined) {
    try {
      assertExecutionProfile(result.executionProfile);
    } catch (error) {
      throw invariantError(error.code ?? "E_EXECUTION_PROFILE_INCONSISTENT", error.message);
    }
  }
  for (const guide of result.guides) {
    if (!GUIDE_IDS.includes(guide)) throw invariantError("E_ROUTE_INVALID", `Route result contains unknown guide: ${guide}`);
    if (!Array.isArray(result.reasons?.[guide]) || result.reasons[guide].length === 0) {
      throw invariantError("E_ROUTE_REASON_MISSING", `Selected guide has no reason: ${guide}`);
    }
  }
  for (const [guide, reasons] of Object.entries(result.excluded ?? {})) {
    if (!GUIDE_IDS.includes(guide)) {
      throw invariantError("E_ROUTE_INVALID", `Route result contains unknown excluded guide: ${guide}`);
    }
    if (result.guides.includes(guide)) {
      throw invariantError("E_ROUTE_INVALID", `Guide cannot be selected and excluded: ${guide}`);
    }
    if (!Array.isArray(reasons) || reasons.length === 0) {
      throw invariantError("E_ROUTE_REASON_MISSING", `Excluded guide has no exclusion reason: ${guide}`);
    }
  }
  if (result.primary !== null && !result.guides.includes(result.primary)) {
    throw invariantError("E_ROUTE_INVALID", "Primary guide must be null or selected");
  }
  return result;
}

function configuredValue(value) {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : undefined;
}

function contextInput(input = {}) {
  const source = input && typeof input === "object" && !Array.isArray(input) ? input : {};
  const provider = providerValue(source.trustedAuthorityProvider);
  const explicit = source.authorityContext && typeof source.authorityContext === "object"
    ? source.authorityContext
    : {};
  const { authorityContext: _authorityContext, trustedAuthorityProvider: _trustedAuthorityProvider, ...direct } = source;
  return { ...direct, ...provider, ...explicit };
}

export function createAuthorityContext(input = {}) {
  const values = contextInput(input);
  const trustMode = values.trustMode ?? values.authorityTrustMode ?? "NONE";
  if (!AUTHORITY_TRUST_MODES.includes(trustMode)) {
    const error = new Error(`Unsupported authority trust mode: ${trustMode}`);
    error.code = "E_AUTHORITY_INVALID";
    throw error;
  }

  const context = { trustMode };
  for (const field of AUTHORITY_CONTEXT_FIELDS) {
    if (field === "trustedAuthorityFile" || field === "trustedAuthorityDir") {
      const value = configuredValue(values[field]);
      if (value !== undefined) context[field] = value;
    } else if (values[field] !== undefined) {
      context[field] = values[field];
    }
  }
  return Object.freeze(context);
}

export function hasAuthorityContext(options = {}) {
  if (!options || typeof options !== "object") return false;
  return Boolean(
    options.authorityContext
    || options.runtimeContext?.authorityContext
    || (options.runtimeContext && typeof options.runtimeContext === "object" && options.runtimeContext.trustMode),
  );
}

function providerValue(provider) {
  if (typeof provider === "function") return provider();
  return provider && typeof provider === "object" && !Array.isArray(provider) ? provider : {};
}

export function resolveAuthorityContext(options = {}) {
  const source = options && typeof options === "object" && !Array.isArray(options) ? options : {};
  if (source.authorityContext !== undefined) {
    return createAuthorityContext(source.authorityContext);
  }
  if (source.runtimeContext?.authorityContext !== undefined) {
    return createAuthorityContext(source.runtimeContext.authorityContext);
  }
  if (source.runtimeContext && typeof source.runtimeContext === "object" && source.runtimeContext.trustMode) {
    return createAuthorityContext(source.runtimeContext);
  }

  const hasDirectAuthority = AUTHORITY_CONTEXT_FIELDS.some((field) => source[field] !== undefined);
  // Direct resolver options are legacy source selectors, not a host attestation
  // channel. They remain NONE unless wrapped in an explicit runtime context.
  return hasDirectAuthority ? createAuthorityContext({ ...source, trustMode: "NONE" }) : createAuthorityContext();
}

export function runSemanticPlan({ kind, input = {}, semanticRecommendation = null } = {}) {
  const projector = PROJECTORS[kind];
  if (!projector) throw decisionError(DECISION_ERROR_CODES.QUESTION_SET_UNKNOWN, `Unknown semantic plan kind: ${kind}`);
  return projector({ input, semanticRecommendation });
}

export function assertDecisionCriterionDetails(details) {
  if (!details || typeof details !== "object" || Array.isArray(details)) {
    const error = new Error("Decision criterion details must be an object");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  if (typeof details.decision !== "string" || !details.decision.trim()) {
    const error = new Error("Decision criterion decision must be a non-empty string");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  const expectedId = decisionId(details.decision);
  if (details.decisionId !== expectedId) {
    const error = new Error(`Decision criterion decisionId "${details.decisionId}" does not match computed "${expectedId}"`);
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  if (typeof details.settledBy !== "string" || !details.settledBy.trim()) {
    const error = new Error("Decision criterion settledBy must be a non-empty string");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  if (typeof details.contractFingerprint !== "string" || !/^[a-f0-9]{64}$/.test(details.contractFingerprint)) {
    const error = new Error("Decision criterion contractFingerprint must be a 64-char hex string");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  return details;
}

export function criterionForDecision(events, taskId, decisionText, contractFingerprint) {
  const decId = decisionId(decisionText);
  const taskEvents = decisionCriterionEvents(events, taskId);
  for (let i = taskEvents.length - 1; i >= 0; i--) {
    const details = taskEvents[i].details;
    if (details?.decisionId === decId && (!contractFingerprint || details?.contractFingerprint === contractFingerprint)) {
      return details;
    }
  }
  return null;
}

export function decisionId(decisionText) {
  const normalized = normalizeDecisionText(decisionText);
  const hash = createHash("sha256").update(normalized).digest("hex").slice(0, 16);
  return `decision-${hash}`;
}

export function normalizeDecisionCriterionInput(input) {
  if (!input || typeof input !== "object") {
    const error = new Error("Decision criterion input must be an object");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  if (typeof input.decision !== "string" || !input.decision.trim()) {
    const error = new Error("decision must be a non-empty string");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  if (typeof input.settledBy !== "string" || !input.settledBy.trim()) {
    const error = new Error("settledBy must be a non-empty string");
    error.code = "E_DECISION_CRITERION_INVALID";
    throw error;
  }
  return {
    decision: input.decision.trim(),
    settledBy: input.settledBy.trim(),
  };
}

export function assertContractPresetRefs(refs = []) {
  for (const ref of refs) {
    if (typeof ref === "string" && ref.startsWith(CONTRACT_PRESET_PREFIX) && !isBuiltinContractPresetRef(ref)) {
      const error = new Error(`Unknown built-in contract preset source: ${ref}`);
      error.code = "E_PROFILE_SOURCE_UNKNOWN";
      throw error;
    }
  }
  return true;
}

export function assertContractSourceProvenance(registry, refs = []) {
  assertContractPresetRefs(refs);
  const externalRefs = externalContractSourceRefs(refs);
  if (externalRefs.length === 0) return true;
  if (!registry) {
    const error = new Error("External contract source references require a source registry");
    error.code = "E_PROFILE_SOURCE_MISSING";
    throw error;
  }
  return assertSourceProvenance(registry, externalRefs);
}

export function assertSourceProvenance(registry, refs = [], { expectedKind } = {}) {
  assertSourceRegistry(registry);
  assertSourceRefs(registry, refs);
  const expectedKinds = expectedKind === undefined
    ? null
    : new Set(Array.isArray(expectedKind) ? expectedKind : [expectedKind]);
  if (expectedKinds) {
    for (const ref of refs) {
      const source = registry.sources[ref];
      if (!expectedKinds.has(source.kind)) {
        const error = new Error(`Source ${ref} has kind ${source.kind}, expected ${[...expectedKinds].join(", ")}`);
        error.code = "E_PROFILE_SOURCE_MISCLASSIFIED";
        throw error;
      }
    }
  }
  return true;
}

export function externalContractSourceRefs(refs = []) {
  return refs.filter((ref) => !isBuiltinContractPresetRef(ref));
}

export function computeStrategyFingerprints(trace) {
  const byCycle = new Map();
  const add = (cycle, component, fingerprint) => {
    if (!byCycle.has(cycle)) byCycle.set(cycle, { hypotheses: new Set(), contributors: new Set(), interventions: new Set() });
    byCycle.get(cycle)[component].add(fingerprint);
  };
  for (const diagnosticCase of trace.diagnostics.cases) {
    for (const hypothesis of diagnosticCase.hypotheses ?? []) {
      add(diagnosticCase.verificationCycle, "hypotheses", `${hypothesis.statement}`.trim().toLowerCase());
    }
    for (const contributor of diagnosticCase.contributors ?? []) {
      add(diagnosticCase.verificationCycle, "contributors", `${contributor.statement}`.trim().toLowerCase());
    }
  }
  for (const legacy of trace.diagnostics.legacyDiagnoses) {
    add(legacy.verificationCycle, "hypotheses", `${legacy.hypothesis}`.trim().toLowerCase());
  }
  for (const intervention of trace.diagnostics.interventions) {
    add(intervention.verificationCycle, "interventions", intervention.interventionSemanticFingerprint ?? `${intervention.intervention?.statement ?? ""}`.trim().toLowerCase());
  }

  return [...byCycle.entries()]
    .sort(([a], [b]) => a - b)
    .map(([cycle, components]) => ({
      verificationCycle: cycle,
      strategyFingerprint: JSON.stringify([
        [...components.hypotheses].sort(),
        [...components.contributors].sort(),
        [...components.interventions].sort(),
      ]),
      components: {
        hypotheses: [...components.hypotheses].sort(),
        contributors: [...components.contributors].sort(),
        interventions: [...components.interventions].sort(),
      },
    }));
}

export function assertStructuralQualityBindings(value, expected = {}) {
  const errors = validateStructuralQualityBindings(value, expected);
  if (errors.length > 0) {
    const artifactRef = expected.artifactRef ?? null;
    throw qualityArtifactError(
      errors[0].code,
      errors[0].message,
      artifactRef ? [structuralQualityArtifactRef(expected.taskId ?? value.taskId, artifactRef)] : [],
    );
  }
  return value;
}

function normalizeAttempt(value) {
  if (!Number.isInteger(value) || value < 1) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "structural-quality attempt must be a positive integer");
  }
  return value;
}

function normalizeCycle(value, label) {
  if (!Number.isInteger(value) || value < 1) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} must be a positive integer`);
  }
  return value;
}

function qualityArtifactError(code, message, artifacts = []) {
  return structuralQualityError(code, message, artifacts);
}

function readFailure(error, relativePath, missingCode) {
  if (error?.code === "ARTIFACT_MISSING") {
    return qualityArtifactError(missingCode, `Structural-quality artifact is missing: ${relativePath}`, [relativePath]);
  }
  if (error?.code?.startsWith("E_STRUCTURAL_QUALITY")) return error;
  return qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `Structural-quality artifact is invalid: ${error.message}`, [relativePath]);
}

export function structuralQualityArtifactRef(taskId, relativePath) {
  const expectedRoot = taskStructuralQualityDirectory(taskId).replaceAll("\\", "/");
  const portable = String(relativePath).replaceAll("\\", "/");
  if (portable.startsWith("/")
    || portable.split("/").some((part) => part === "..")
    || (portable !== expectedRoot && !portable.startsWith(`${expectedRoot}/`))) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `Artifact reference escapes the structural-quality directory: ${relativePath}`, [portable]);
  }
  return portable;
}

export function validateStructuralQualityArtifact(value, label = "structural-quality artifact") {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} must be an object`);
  }
  if (value.role === "BASELINE") {
    if (value.verificationCycle !== null) throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} baseline verificationCycle must be null`);
    if (value.status !== "PASS") throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} baseline status must be PASS`);
    if (value.bindings?.baselineFingerprint !== undefined && value.bindings.baselineFingerprint !== null) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, `${label} baselineFingerprint must be null`);
    }
  } else if (value.role === "EVALUATION") {
    if (!Number.isInteger(value.verificationCycle) || value.verificationCycle < 1) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} evaluation verificationCycle must be positive`);
    }
    if (!Number.isInteger(value.attempt) || value.attempt < 1) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} evaluation attempt must be positive`);
    }
    if (!Array.isArray(value.reasonCodes) || (value.status !== "PASS" && value.reasonCodes.length === 0)) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} non-PASS evaluations require a reason code`);
    }
    if (!value.comparison || typeof value.comparison !== "object") {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} evaluation comparison is required`);
    }
    const comparisonStatus = value.comparison.status;
    if (value.status === "PASS" && comparisonStatus !== "PASS") {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} PASS status requires a PASS comparison`);
    }
    if (value.status === "FAIL" && comparisonStatus !== "FAIL") {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} FAIL status requires a FAIL comparison`);
    }
    if (["BLOCKED", "NOT_OBSERVED"].includes(value.status) && comparisonStatus === "PASS") {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} unavailable evaluation cannot contain a PASS comparison`);
    }
  } else {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} role must be BASELINE or EVALUATION`);
  }
  const observed = value.role === "BASELINE" || ["PASS", "FAIL"].includes(value.status);
  const sourceFingerprint = value.bindings?.sourceMaterialFingerprint;
  if (observed) {
    if (typeof sourceFingerprint !== "string" || !/^[a-f0-9]{64}$/u.test(sourceFingerprint)) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} observed evidence requires sourceMaterialFingerprint`);
    }
    if (!value.sourceObservation || value.sourceObservation.stable !== true) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} observed evidence requires a stable sourceObservation`);
    }
  }
  if (!value.detection || typeof value.detection !== "object" || Array.isArray(value.detection)) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} detection metadata is required`);
  }
  if (value.provider?.id !== value.detection?.providerId) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, `${label} provider and detection IDs differ`);
  }
  if (value.sourceObservation !== undefined && value.sourceObservation !== null) {
    if (typeof value.sourceObservation !== "object" || Array.isArray(value.sourceObservation)) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} sourceObservation must be an object`);
    }
    if (typeof value.sourceObservation.beforeFingerprint !== "string"
      || typeof value.sourceObservation.afterFingerprint !== "string"
      || typeof value.sourceObservation.stable !== "boolean") {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} sourceObservation requires beforeFingerprint, afterFingerprint, and stable`);
    }
    if (value.sourceObservation.stable === true
      && (value.sourceObservation.beforeFingerprint !== value.sourceObservation.afterFingerprint
        || (typeof sourceFingerprint === "string" && value.sourceObservation.beforeFingerprint !== sourceFingerprint))) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} stable sourceObservation does not match its source binding`);
    }
    if (!value.sourceObservation.stable && ["PASS", "FAIL"].includes(value.status)) {
      throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} unstable sourceObservation cannot produce observed evidence`);
    }
  }
  normalizeStructuralQualityDetection(value.detection, {
    providerId: value.provider?.id,
    version: value.provider?.version,
    transport: value.provider?.transport,
    measurementModel: value.provider?.measurementModel,
    compatibilityKey: value.provider?.compatibilityKey,
  });
  if (value.snapshot !== undefined) normalizeStructuralQualitySnapshot(value.snapshot);
  if (["PASS", "FAIL"].includes(value.status) && value.snapshot === undefined) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `${label} observed status requires a normalized snapshot`);
  }
  return value;
}

export function validateStructuralQualityBindings(value, expected = {}) {
  const errors = [];
  const bindings = value?.bindings ?? {};
  const fields = ["contractFingerprint", "routeFingerprint", "policyFingerprint", "scopeFingerprint"];
  for (const field of fields) {
    if (expected[field] !== undefined && bindings[field] !== expected[field]) {
      errors.push({
        code: E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH,
        message: `Structural-quality ${field} does not match the active task binding`,
      });
    }
  }
  if (expected.providerId !== undefined && value.provider?.id !== expected.providerId) {
    errors.push({ code: E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, message: "Structural-quality provider ID does not match the active policy" });
  }
  if (expected.providerVersion !== undefined && expected.providerVersion !== null && value.provider?.version !== expected.providerVersion) {
    errors.push({ code: E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, message: "Structural-quality provider version does not match the baseline" });
  }
  if (expected.baselineFingerprint !== undefined && bindings.baselineFingerprint !== expected.baselineFingerprint) {
    errors.push({ code: E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, message: "Structural-quality evaluation does not bind the active baseline" });
  }
  if (expected.verificationCycle !== undefined && value.verificationCycle !== expected.verificationCycle) {
    errors.push({ code: E_STRUCTURAL_QUALITY_EVIDENCE_STALE, message: "Structural-quality evidence belongs to a different verification cycle" });
  }
  return errors;
}

export function structuralQualityError(code, message, artifacts = []) {
  const error = new Error(message);
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

export function compareStructuralQuality({ baseline, current, policy } = {}) {
  const normalizedPolicy = normalizeStructuralQualityConfig(policy ?? { mode: "gate", provider: "sentrux" });
  const baselineSnapshot = snapshotOf(baseline);
  const currentSnapshot = snapshotOf(current);
  const incompatibilities = assertComparableInputs(baseline, current);
  const rootCauseDeltas = Object.fromEntries(STRUCTURAL_QUALITY_ROOT_CAUSES.map((cause) => [
    cause,
    Number.isInteger(currentSnapshot?.rootCauses?.[cause]?.score) && Number.isInteger(baselineSnapshot?.rootCauses?.[cause]?.score)
      ? currentSnapshot.rootCauses[cause].score - baselineSnapshot.rootCauses[cause].score
      : null,
  ]));
  const qualityDelta = Number.isInteger(currentSnapshot?.qualitySignal) && Number.isInteger(baselineSnapshot?.qualitySignal)
    ? currentSnapshot.qualitySignal - baselineSnapshot.qualitySignal
    : null;
  const failedConditions = [];
  const reasonCodes = [...incompatibilities];
  if (incompatibilities.length === 0) {
    if (qualityDelta === null || qualityDelta < -normalizedPolicy.maxRegressionPoints) {
      failedConditions.push("qualitySignal");
    }
    for (const cause of STRUCTURAL_QUALITY_ROOT_CAUSES) {
      const budget = normalizedPolicy.dimensionBudgets[cause];
      if (budget !== null && budget !== undefined) {
        const delta = rootCauseDeltas[cause];
        if (delta === null || delta < -budget) failedConditions.push(cause);
      }
      const minimum = normalizedPolicy.minimums[cause];
      if (minimum > 0 && (!Number.isInteger(currentSnapshot?.rootCauses?.[cause]?.score)
        || currentSnapshot.rootCauses[cause].score < minimum)) failedConditions.push(`${cause}:minimum`);
    }
    if (normalizedPolicy.minQualitySignal !== null
      && (!Number.isInteger(currentSnapshot?.qualitySignal) || currentSnapshot.qualitySignal < normalizedPolicy.minQualitySignal)) {
      failedConditions.push("qualitySignal:minimum");
    }
    if (normalizedPolicy.forbidNewCycles
      && Number.isFinite(baselineSnapshot?.rootCauses?.acyclicity?.raw)
      && Number.isFinite(currentSnapshot?.rootCauses?.acyclicity?.raw)
      && currentSnapshot.rootCauses.acyclicity.raw > baselineSnapshot.rootCauses.acyclicity.raw) {
      failedConditions.push("acyclicity:new-cycles");
    }
    if (failedConditions.length > 0) reasonCodes.push("E_STRUCTURAL_QUALITY_REGRESSION");
  } else {
    if (incompatibilities.includes("MEASUREMENT_MODEL_MISMATCH")) {
      reasonCodes.push("E_STRUCTURAL_QUALITY_MEASUREMENT_MODEL_MISMATCH");
    }
    reasonCodes.push("E_STRUCTURAL_QUALITY_EVALUATION_INCOMPARABLE");
  }
  const sortedReasons = [...new Set(reasonCodes)].sort();
  return {
    comparable: incompatibilities.length === 0,
    qualityDelta,
    rootCauseDeltas,
    failedConditions: [...new Set(failedConditions)].sort(),
    status: incompatibilities.length > 0 ? "NOT_OBSERVED" : failedConditions.length > 0 ? "FAIL" : "PASS",
    reasonCodes: sortedReasons,
  };
}

function integer(value, label, { min = 0, max = 10_000 } = {}) {
  if (!Number.isInteger(value) || value < min || value > max) {
    throw structuralQualityError(
      E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID,
      `${label} must be an integer between ${min} and ${max}`,
    );
  }
  return value;
}

function normalizeBudgets(value, label) {
  const source = value === undefined ? {} : plainObject(value, label);
  const unknown = Object.keys(source).find((key) => !STRUCTURAL_QUALITY_ROOT_CAUSES.includes(key));
  if (unknown) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `${label} contains unknown root cause: ${unknown}`);
  }
  return Object.fromEntries(STRUCTURAL_QUALITY_ROOT_CAUSES.map((cause) => {
    const raw = source[cause];
    if (raw === null || raw === undefined) {
      return [cause, STRUCTURAL_QUALITY_DEFAULT_DIMENSION_BUDGETS[cause] ?? null];
    }
    return [cause, integer(raw, `${label}.${cause}`)];
  }));
}

function normalizeMinimums(value) {
  const source = value === undefined ? {} : plainObject(value, "structuralQuality.minimums");
  const unknown = Object.keys(source).find((key) => !STRUCTURAL_QUALITY_ROOT_CAUSES.includes(key));
  if (unknown) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `structuralQuality.minimums contains unknown root cause: ${unknown}`);
  }
  return Object.fromEntries(Object.entries(source).map(([cause, minimum]) => [
    cause,
    integer(minimum, `structuralQuality.minimums.${cause}`),
  ]));
}

function normalizeOptimization(value) {
  const source = value === undefined ? {} : plainObject(value, "structuralQuality.optimization");
  const unknown = Object.keys(source).find((key) => !["mode", "maxExtraEvaluations", "minGainPoints"].includes(key));
  if (unknown) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `structuralQuality.optimization contains unknown property: ${unknown}`);
  }
  const mode = source.mode ?? STRUCTURAL_QUALITY_DEFAULT_OPTIMIZATION.mode;
  if (!["off", "bounded"].includes(mode)) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, "structuralQuality.optimization.mode must be off or bounded");
  }
  const maxExtraEvaluations = source.maxExtraEvaluations ?? STRUCTURAL_QUALITY_DEFAULT_OPTIMIZATION.maxExtraEvaluations;
  integer(maxExtraEvaluations, "structuralQuality.optimization.maxExtraEvaluations", { min: 0, max: 2 });
  const minGainPoints = source.minGainPoints ?? STRUCTURAL_QUALITY_DEFAULT_OPTIMIZATION.minGainPoints;
  integer(minGainPoints, "structuralQuality.optimization.minGainPoints", { min: 1, max: 10_000 });
  return { mode, maxExtraEvaluations, minGainPoints };
}

export function normalizeStructuralQualityConfig(input) {
  if (input === undefined || input === null) return undefined;
  const source = plainObject(input, "structuralQuality");
  const unknown = Object.keys(source).find((key) => !POLICY_KEYS.has(key));
  if (unknown) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `structuralQuality contains unknown property: ${unknown}`);
  }
  const mode = source.mode ?? "observe";
  if (!STRUCTURAL_QUALITY_MODES.includes(mode)) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `Unknown structural quality mode: ${mode}`);
  }
  const provider = source.provider ?? "sentrux";
  if (typeof provider !== "string" || !STRUCTURAL_QUALITY_PROVIDER_ID_PATTERN.test(provider)) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, "structuralQuality.provider must be a lower-case provider ID");
  }
  const maxRegressionPoints = source.maxRegressionPoints ?? 0;
  integer(maxRegressionPoints, "structuralQuality.maxRegressionPoints");
  const minQualitySignal = source.minQualitySignal === null || source.minQualitySignal === undefined
    ? null
    : integer(source.minQualitySignal, "structuralQuality.minQualitySignal");
  if (source.forbidNewCycles !== undefined && typeof source.forbidNewCycles !== "boolean") {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, "structuralQuality.forbidNewCycles must be boolean");
  }
  const policy = {
    mode,
    provider,
    maxRegressionPoints,
    dimensionBudgets: normalizeBudgets(source.dimensionBudgets, "structuralQuality.dimensionBudgets"),
    forbidNewCycles: source.forbidNewCycles ?? true,
    minQualitySignal,
    minimums: normalizeMinimums(source.minimums),
    optimization: normalizeOptimization(source.optimization),
  };
  return Object.freeze({
    ...policy,
    dimensionBudgets: Object.freeze(policy.dimensionBudgets),
    minimums: Object.freeze(policy.minimums),
    optimization: Object.freeze(policy.optimization),
  });
}

function plainObject(value, label) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw structuralQualityError(E_STRUCTURAL_QUALITY_CONFIGURATION_INVALID, `${label} must be an object`);
  }
  return value;
}

export function structuralQualityPolicyFingerprint(policy) {
  return canonicalFingerprint(normalizeStructuralQualityConfig(policy));
}

function boundedDiagnosticValue(value, projectPath, label, depth = 0) {
  if (depth > 8) throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} is too deeply nested`);
  if (typeof value === "string") {
    if (value.length > STRUCTURAL_QUALITY_MAX_DIAGNOSTIC_STRING) {
      throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} exceeds the diagnostic string limit`);
    }
    return relativePortablePath(value, projectPath, label);
  }
  if (typeof value === "number" || typeof value === "boolean" || value === null) return value;
  if (Array.isArray(value)) {
    if (value.length > STRUCTURAL_QUALITY_MAX_DIAGNOSTICS) {
      throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} exceeds the diagnostic count limit`);
    }
    return value.map((item, index) => boundedDiagnosticValue(item, projectPath, `${label}[${index}]`, depth + 1));
  }
  if (!isRecord(value)) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} contains an unsupported value`);
  }
  const output = {};
  for (const [key, item] of Object.entries(value)) {
    if (SECRET_KEY.test(key)) {
      throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} contains a secret-like field`);
    }
    output[key] = boundedDiagnosticValue(item, projectPath, `${label}.${key}`, depth + 1);
  }
  return output;
}

function canonicalBottleneck(rootCauses) {
  return STRUCTURAL_QUALITY_ROOT_CAUSES.reduce((best, cause) => (
    best === null || rootCauses[cause].score < rootCauses[best].score ? cause : best
  ), null);
}

export function createStructuralQualityProviderRegistry({ providers = {}, builtIns = {} } = {}) {
  if (!isRecord(providers) || !isRecord(builtIns)) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "Structural-quality provider registry entries must be objects");
  }
  const custom = new Map();
  for (const [id, provider] of Object.entries(providers)) {
    if (!STRUCTURAL_QUALITY_PROVIDER_ID_PATTERN.test(id) || id === "sentrux") {
      throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `Invalid or reserved provider ID: ${id}`);
    }
    custom.set(id, provider);
  }
  const builtInEntries = new Map(Object.entries(builtIns));
  return Object.freeze({
    async resolve(name, input) {
      const providerOrFactory = custom.get(name) ?? builtInEntries.get(name);
      if (!providerOrFactory) {
        throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_UNAVAILABLE, `Structural-quality provider is unavailable: ${name}`);
      }
      const providerInput = freezeProviderInput(input);
      const provider = typeof providerOrFactory === "function"
        ? await providerOrFactory(providerInput)
        : providerOrFactory;
      const asserted = assertStructuralQualityProvider(provider);
      if (asserted.id !== name) {
        throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `Structural-quality provider identity ${asserted.id} does not match registry key ${name}`);
      }
      return asserted;
    },
  });
}

function freezeProviderInput(input = {}) {
  const source = isRecord(input) ? input : {};
  const projectPath = requiredString(source.projectPath ?? source.target, "provider input.projectPath");
  const taskId = requiredString(source.taskId, "provider input.taskId");
  const timeoutMs = source.timeoutMs ?? 120_000;
  const maxOutputBytes = source.maxOutputBytes ?? 2 * 1024 * 1024;
  if (!Number.isInteger(timeoutMs) || timeoutMs < 0) throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "provider input.timeoutMs must be a non-negative integer");
  if (!Number.isInteger(maxOutputBytes) || maxOutputBytes < 1) throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "provider input.maxOutputBytes must be a positive integer");
  return Object.freeze({ projectPath, taskId, timeoutMs, maxOutputBytes });
}

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function nonNegativeIntegerOrNull(value, label) {
  if (value === undefined || value === null) return null;
  if (!Number.isInteger(value) || value < 0) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} must be a non-negative integer or null`);
  }
  return value;
}

function normalizeStatistics(raw) {
  const statistics = raw?.statistics ?? {};
  const source = raw?.scan ?? raw;
  return {
    files: nonNegativeIntegerOrNull(statistics.files ?? source.files ?? source.fileCount ?? source.file_count, "snapshot.statistics.files"),
    lines: nonNegativeIntegerOrNull(statistics.lines ?? source.lines ?? source.lineCount ?? source.line_count, "snapshot.statistics.lines"),
    importEdges: nonNegativeIntegerOrNull(statistics.importEdges ?? statistics.import_edges ?? source.importEdges ?? source.import_edges ?? source.importEdgeCount, "snapshot.statistics.importEdges"),
    crossModuleEdges: nonNegativeIntegerOrNull(statistics.crossModuleEdges ?? statistics.cross_module_edges ?? source.crossModuleEdges ?? source.cross_module_edges, "snapshot.statistics.crossModuleEdges"),
  };
}

export function normalizeStructuralQualityDetection(raw = {}, defaults = {}) {
  const source = isRecord(raw) ? raw : {};
  const providerId = source.providerId ?? source.provider_id ?? defaults.providerId ?? defaults.id;
  requiredString(providerId, "detection.providerId");
  if (!STRUCTURAL_QUALITY_PROVIDER_ID_PATTERN.test(providerId)) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "detection.providerId must be a lower-case provider ID");
  }
  const providerVersion = source.providerVersion ?? source.provider_version ?? source.version ?? defaults.providerVersion ?? defaults.version ?? null;
  if (providerVersion !== null && typeof providerVersion !== "string") {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "detection.providerVersion must be a string or null");
  }
  const transport = source.transport ?? defaults.transport ?? DETECTION_TRANSPORT;
  requiredString(transport, "detection.transport");
  const measurementModel = source.measurementModel ?? source.measurement_model ?? defaults.measurementModel ?? defaults.measurement_model ?? "structural-root-causes-v1";
  requiredString(measurementModel, "detection.measurementModel");
  const compatibilityKey = source.compatibilityKey ?? source.compatibility_key ?? defaults.compatibilityKey ?? defaults.compatibility_key ?? null;
  if (compatibilityKey !== null && typeof compatibilityKey !== "string") {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "detection.compatibilityKey must be a string or null");
  }
  const reasonCode = source.reasonCode ?? source.reason_code ?? null;
  if (reasonCode !== null && typeof reasonCode !== "string") {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "detection.reasonCode must be a string or null");
  }
  return {
    available: source.available === true,
    providerId,
    providerVersion,
    transport,
    measurementModel,
    compatibilityKey,
    reasonCode,
  };
}

export function normalizeStructuralQualitySnapshot(raw, { projectPath = null } = {}) {
  const source = raw?.snapshot && isRecord(raw.snapshot) ? raw.snapshot : raw;
  if (!isRecord(source)) throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, "provider scan result must be an object");
  const qualitySignal = source.qualitySignal ?? source.quality_signal ?? source.signal;
  const rootCauses = Object.fromEntries(STRUCTURAL_QUALITY_ROOT_CAUSES.map((cause) => {
    const input = rootCauseInput(source, cause);
    return [cause, {
      score: score(input.score, `snapshot.rootCauses.${cause}.score`),
      raw: rawScore(input.raw, `snapshot.rootCauses.${cause}.raw`),
    }];
  }));
  const snapshot = {
    qualitySignal: score(qualitySignal, "snapshot.qualitySignal"),
    bottleneck: canonicalBottleneck(rootCauses),
    rootCauses,
    statistics: normalizeStatistics(source),
    diagnostics: source.diagnostics === undefined || source.diagnostics === null
      ? null
      : boundedDiagnosticValue(source.diagnostics, projectPath, "snapshot.diagnostics"),
  };
  if (source.bottleneck !== undefined && source.bottleneck !== snapshot.bottleneck) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `snapshot.bottleneck must be the canonical lowest-score root cause (${snapshot.bottleneck})`);
  }
  return snapshot;
}

function providerError(code, message, artifacts = []) {
  return structuralQualityError(code, message, artifacts);
}

export function providerInputFor({ projectPath, taskId, timeoutMs, maxOutputBytes } = {}) {
  return freezeProviderInput({ projectPath, taskId, timeoutMs, maxOutputBytes });
}

function relativePortablePath(value, projectPath, label) {
  if (typeof value !== "string") return value;
  const trimmed = value.trim();
  if (!trimmed) return trimmed;
  if (!path.isAbsolute(trimmed)) return trimmed.replaceAll("\\", "/");
  if (!projectPath) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} must not contain an absolute path`);
  }
  const relative = path.relative(path.resolve(projectPath), path.resolve(trimmed));
  if (!relative || (!relative.startsWith("..") && !path.isAbsolute(relative))) {
    return relative.replaceAll("\\", "/") || ".";
  }
  throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} contains a path outside the project target`);
}

function requiredString(value, label, { allowEmpty = false } = {}) {
  if (typeof value !== "string" || (!allowEmpty && value.trim() === "")) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} must be a non-empty string`);
  }
  return value;
}

export async function resolveStructuralQualityProvider({ providerName = "sentrux", target, taskId, timeoutMs, maxOutputBytes, runtimeContext } = {}) {
  if (typeof providerName !== "string" || !STRUCTURAL_QUALITY_PROVIDER_ID_PATTERN.test(providerName)) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `Invalid structural-quality provider ID: ${providerName}`);
  }
  const configured = runtimeContext?.structuralQualityProviders;
  const custom = configured instanceof Map ? Object.fromEntries(configured.entries()) : configured ?? {};
  if (providerName !== "sentrux" && !Object.prototype.hasOwnProperty.call(custom, providerName)) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_UNAVAILABLE, `Structural-quality provider is unavailable: ${providerName}`);
  }
  const builtIns = {
    sentrux: async (input) => {
      const { createSentruxStructuralQualityProvider } = await import("./sentrux-mcp.js");
      return createSentruxStructuralQualityProvider(input);
    },
  };
  return createStructuralQualityProviderRegistry({ providers: custom, builtIns }).resolve(providerName, {
    projectPath: target,
    taskId,
    timeoutMs,
    maxOutputBytes,
  });
}

function score(value, label) {
  if (!Number.isInteger(value) || value < 0 || value > 10_000) {
    throw providerError(E_STRUCTURAL_QUALITY_PROVIDER_INVALID, `${label} must be an integer between 0 and 10000`);
  }
  return value;
}

export function structuralQualityProviderCompatibility({ id, version, measurementModel, compatibilityKey } = {}) {
  if (id !== "sentrux") return { supported: true, measurementModel, compatibilityKey };
  if (!STRUCTURAL_QUALITY_SENTRUX_VERIFIED_VERSIONS.includes(version)) {
    return {
      supported: false,
      reasonCode: E_STRUCTURAL_QUALITY_PROVIDER_VERSION_UNSUPPORTED,
    };
  }
  return {
    supported: true,
    measurementModel: "structural-root-causes-v1",
    compatibilityKey: "sentrux-structural-root-causes-v1",
  };
}

function baseBindings(inputs, policyFingerprint, baselineFingerprint = null, sourceMaterialFingerprint = null) {
  return {
    contractFingerprint: inputs.contract.fingerprint,
    routeFingerprint: inputs.route.fingerprint,
    policyFingerprint,
    scopeFingerprint: inputs.scopeFingerprint,
    baselineFingerprint,
    sourceMaterialFingerprint,
    stateRevision: inputs.state.revision ?? 0,
  };
}

function checkProjection(policy, evaluation) {
  if (evaluation.status === "PASS") return { status: "passed", evidenceKind: "OBSERVED" };
  if (evaluation.status === "FAIL") return { status: "failed", evidenceKind: "OBSERVED" };
  if (policy.mode === "gate" && evaluation.status === "BLOCKED") return { status: "blocked", evidenceKind: "BLOCKED" };
  return { status: "not-run", evidenceKind: "NOT_VERIFIED" };
}

function configuredPolicy(config) {
  if (!config?.structuralQuality) return null;
  return normalizeStructuralQualityConfig(config.structuralQuality);
}

function emptyProjection(policy, reasonCodes = []) {
  return {
    mode: policy?.mode ?? "off",
    provider: policy?.mode && policy.mode !== "off" ? policy.provider : null,
    baseline: { status: policy ? "MISSING" : "NOT_REQUESTED", qualitySignal: null, artifactRef: null, fingerprint: null },
    current: { status: "NOT_OBSERVED", verificationCycle: null, attempt: null, qualitySignal: null, delta: null, bottleneck: null, artifactRef: null },
    comparable: null,
    completionRequired: policy?.mode === "gate",
    reasonCodes: [...new Set(reasonCodes)].sort(),
    next: policy?.mode === "gate" ? "CAPTURE_STRUCTURAL_QUALITY_BASELINE" : null,
    optimization: policy ? optimizationProjection(policy, [], null) : null,
  };
}

async function invokeProvider({ target, taskId, policy, provider: suppliedProvider = null, runtimeContext, timeoutMs, maxOutputBytes }) {
  const provider = suppliedProvider ?? await resolveStructuralQualityProvider({
    providerName: policy.provider,
    target,
    taskId,
    timeoutMs,
    maxOutputBytes,
    runtimeContext,
  });
  const input = providerInputFor({
    projectPath: target,
    taskId,
    timeoutMs: timeoutMs ?? STRUCTURAL_QUALITY_DEFAULT_TIMEOUT_MS,
    maxOutputBytes: maxOutputBytes ?? 2 * 1024 * 1024,
  });
  if (typeof provider.observe === "function") {
    const result = await provider.observe(input);
    return normalizeScanResult(result, provider, result.detection, target);
  }
  let detection;
  try {
    detection = providerDetection(await provider.detect(input), provider.id);
  } catch (error) {
    detection = providerDetection({
      available: false,
      providerId: provider.id,
      providerVersion: null,
      transport: "runtime",
      measurementModel: STRUCTURAL_QUALITY_MEASUREMENT_MODEL,
      compatibilityKey: null,
      reasonCode: error.code ?? E_STRUCTURAL_QUALITY_PROVIDER_UNAVAILABLE,
    }, provider.id);
  }
  if (!detection.available) {
    throw qualityError(detection.reasonCode ?? E_STRUCTURAL_QUALITY_PROVIDER_UNAVAILABLE, `Structural-quality provider ${provider.id} is unavailable`);
  }
  const result = await provider.scan(input);
  return normalizeScanResult(result, provider, detection, target);
}

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

async function loadOptionalConfig(target, packageRoot) {
  try {
    return await readConfig(target, packageRoot);
  } catch (error) {
    if (error.code === "ARTIFACT_MISSING") return null;
    throw error;
  }
}

function nonPassEvaluation({ taskId, inputs, cycle, attempt, policy, reasonCode, reasonCodes = [], providerId = policy.provider, providerVersion = null, detection = null, baseline = null, sourceObservation = null, sourceMaterialFingerprint = null }) {
  const status = policy.mode === "gate" ? "BLOCKED" : "NOT_OBSERVED";
  const detectionValue = detection ?? {
    available: false,
    providerId,
    providerVersion,
    transport: "runtime",
    measurementModel: STRUCTURAL_QUALITY_MEASUREMENT_MODEL,
    compatibilityKey: null,
    reasonCode,
  };
  const policyFingerprint = structuralQualityPolicyFingerprint(policy);
  return {
    schemaVersion: 1,
    protocolVersion: 1,
    role: "EVALUATION",
    taskId,
    capturedAt: new Date().toISOString(),
    verificationCycle: cycle,
    attempt,
    status,
    reasonCodes: [...new Set([reasonCode, ...reasonCodes])],
    errorCode: reasonCode,
    bindings: baseBindings(inputs, policyFingerprint, baseline?.fingerprint ?? null, sourceMaterialFingerprint),
    ...(sourceObservation ? { sourceObservation } : {}),
    provider: {
      id: providerId,
      version: providerVersion,
      transport: detectionValue.transport,
      executionMode: "runtime-context",
      measurementModel: detectionValue.measurementModel ?? STRUCTURAL_QUALITY_MEASUREMENT_MODEL,
      compatibilityKey: detectionValue.compatibilityKey ?? null,
    },
    detection: detectionValue,
    scope: inputs.scope,
    ...(baseline?.value?.snapshot ? { baselineSignal: baseline.value.snapshot.qualitySignal } : {}),
    comparison: {
      comparable: false,
      qualityDelta: null,
      rootCauseDeltas: Object.fromEntries(["modularity", "acyclicity", "depth", "equality", "redundancy"].map((key) => [key, null])),
      failedConditions: [],
      status: "NOT_OBSERVED",
      reasonCodes: [...new Set([reasonCode, ...reasonCodes])],
    },
  };
}

function normalizeScanResult(result, provider, detection, projectPath) {
  const source = isRecord(result) ? result : { snapshot: result };
  const snapshot = normalizeStructuralQualitySnapshot(source.snapshot ?? source, { projectPath });
  const metadata = providerMetadata(source.provider, detection);
  if (metadata.id !== provider.id) {
    throw qualityError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, "Structural-quality scan returned a different provider identity");
  }
  return {
    snapshot,
    provider: metadata,
    detection: providerDetection(source.detection ?? detection, provider.id),
    providerScopeBinding: source.providerScopeBinding ?? null,
  };
}

async function persistEvaluationAndCheck({ target, packageRoot, taskId, inputs, persisted, authorityContext, runtimeContext }) {
  const { prepareCompletion, recordCheck } = await import("../completion-artifacts.js");
  const staleRecoveryResult = (freshness, effectiveTaskId = taskId) => ({
    status: inputs.policy.mode === "gate" ? "BLOCKED" : "NOT_OBSERVED",
    mode: inputs.policy.mode,
    evaluation: persisted,
    check: null,
    receipt: null,
    attempts: persisted.attempt,
    reasonCodes: freshness.reasonCodes,
    errorCode: E_STRUCTURAL_QUALITY_EVIDENCE_STALE,
    taskId: effectiveTaskId,
  });
  if (["PASS", "FAIL"].includes(persisted.status)) {
    const initialFreshness = await validateStructuralQualityEvaluationFreshness({
      target,
      packageRoot,
      taskId,
      artifact: persisted,
      inputs,
      runtimeContext,
    });
    if (!initialFreshness.valid) return staleRecoveryResult(initialFreshness);
  }
  const record = (context, evaluation) => recordCheck({
    target,
    packageRoot,
    id: STRUCTURAL_QUALITY_CHECK_ID,
    kind: "structural-quality",
    requirement: STRUCTURAL_QUALITY_REQUIREMENT,
    status: checkProjection(inputs.policy, evaluation).status,
    evidenceKind: checkProjection(inputs.policy, evaluation).evidenceKind,
    result: `structural quality ${evaluation.status}`,
    details: evaluationDetails(evaluation),
    authorityContext,
    runtimeContext,
    taskId: context?.taskId ?? taskId,
  });
  const recorded = await withQualityMutation(target, { taskId, packageRoot }, "quality-verify-check", async (context) => {
    const effectiveTaskId = context?.taskId ?? taskId;
    const evaluations = await listStructuralQualityEvaluations(target, effectiveTaskId, packageRoot);
    const latest = evaluations
      .filter((item) => item.value.verificationCycle === persisted.verificationCycle)
      .at(-1);
    const evaluation = latest && latest.value.attempt > persisted.attempt
      ? { ...latest.value, artifactRef: latest.path, artifactFingerprint: latest.fingerprint }
      : persisted;
    if (["PASS", "FAIL"].includes(evaluation.status)) {
      const freshness = await validateStructuralQualityEvaluationFreshness({
        target,
        packageRoot,
        taskId: effectiveTaskId,
        artifact: evaluation,
        inputs: await resolveStructuralQualityContext({ target, packageRoot, taskId: effectiveTaskId, runtimeContext }),
        runtimeContext,
      });
      if (!freshness.valid) return staleRecoveryResult(freshness, effectiveTaskId);
    }
    const publish = () => record(context, evaluation);
    try {
      return await publish();
    } catch (error) {
      if (error.code !== "E_RECEIPT_MISSING") throw error;
      await prepareCompletion({
        target,
        packageRoot,
        authorityContext,
        runtimeContext,
        taskId: effectiveTaskId,
      });
      return publish();
    }
  });
  return { evaluation: persisted, check: recorded.check, receipt: recorded };
}

export async function projectStructuralQualityStatus(options = {}) {
  return withProjectReadSnapshot(options.target, () => projectStructuralQualityStatusObservation(options));
}

function projectionFromArtifacts(policy, baseline, current, state, evaluations = [], optimizationScope = null, freshness = null, baselineFreshness = null) {
  if (!policy || policy.mode === "off") return emptyProjection(null);
  const projection = emptyProjection(policy);
  projection.persistedStatus = current?.value?.status ?? null;
  projection.freshness = current ? (freshness?.valid === false ? "STALE" : "CURRENT") : "MISSING";
  projection.baselineFreshness = baseline ? (baselineFreshness?.valid === false ? "STALE" : "CURRENT") : "MISSING";
  if (baseline) {
    projection.baseline = {
      status: baseline.value.status === "PASS" ? "OBSERVED" : baseline.value.status,
      qualitySignal: baseline.value.snapshot?.qualitySignal ?? null,
      artifactRef: baseline.path,
      fingerprint: baseline.fingerprint,
    };
  }
  if (current) {
    const currentStatus = freshness?.valid === false ? statusForComparison(policy, { status: "BLOCKED" }) : current.value.status;
    projection.current = {
      status: currentStatus,
      verificationCycle: current.value.verificationCycle,
      attempt: current.value.attempt,
      qualitySignal: current.value.snapshot?.qualitySignal ?? null,
      delta: current.value.comparison?.qualityDelta ?? null,
      bottleneck: current.value.snapshot?.bottleneck ?? null,
      artifactRef: current.path,
    };
    projection.comparable = current.value.comparison?.comparable ?? null;
    projection.reasonCodes = [...new Set([...(current.value.reasonCodes ?? []), ...(freshness?.reasonCodes ?? [])])].sort();
  } else if (!baseline) {
    projection.reasonCodes = [E_STRUCTURAL_QUALITY_BASELINE_MISSING];
  }
  projection.optimization = optimizationProjection(policy, evaluations, current, optimizationScope ?? undefined);
  if (freshness?.valid === false) {
    projection.next = policy.mode === "gate" ? "VERIFY_STRUCTURAL_QUALITY" : "OPTIONAL_VERIFY_STRUCTURAL_QUALITY";
  } else if (baselineFreshness?.valid === false) {
    projection.next = policy.mode === "gate" ? "RESOLVE_STRUCTURAL_QUALITY_BLOCKER" : null;
  } else if (!baseline) {
    projection.next = policy.mode === "gate"
      ? "CAPTURE_STRUCTURAL_QUALITY_BASELINE"
      : (policy.mode === "observe" ? "OPTIONAL_CAPTURE_STRUCTURAL_QUALITY_BASELINE" : null);
  } else if (!current || current.value.verificationCycle !== (state?.verificationCycle ?? 1)) {
    projection.next = policy.mode === "gate"
      ? "VERIFY_STRUCTURAL_QUALITY"
      : (policy.mode === "observe" ? "OPTIONAL_VERIFY_STRUCTURAL_QUALITY" : null);
  } else if (current.value.status === "FAIL") {
    projection.next = "DIAGNOSE_STRUCTURAL_QUALITY_REGRESSION";
  } else if (current.value.status === "BLOCKED") {
    projection.next = "RESOLVE_STRUCTURAL_QUALITY_BLOCKER";
  } else {
    projection.next = null;
  }
  return projection;
}

function providerCompatibilityErrors(baselineProvider, currentProvider) {
  const errors = [];
  for (const provider of [baselineProvider, currentProvider]) {
    if (provider?.id !== "sentrux" || provider.version === undefined || provider.version === null) continue;
    if (!structuralQualityProviderCompatibility(provider).supported) {
      errors.push(qualityError("E_STRUCTURAL_QUALITY_PROVIDER_VERSION_UNSUPPORTED", "Structural-quality provider version is not in the verified compatibility table"));
    }
  }
  if (!baselineProvider || !currentProvider) return errors;
  if (baselineProvider.measurementModel && currentProvider.measurementModel
    && baselineProvider.measurementModel !== currentProvider.measurementModel) {
    errors.push(qualityError(E_STRUCTURAL_QUALITY_MEASUREMENT_MODEL_MISMATCH, "Structural-quality measurement model differs from the captured baseline"));
  }
  if (baselineProvider.compatibilityKey && currentProvider.compatibilityKey
    && baselineProvider.compatibilityKey !== currentProvider.compatibilityKey) {
    errors.push(qualityError(E_STRUCTURAL_QUALITY_EVALUATION_INCOMPARABLE, "Structural-quality compatibility key differs from the captured baseline"));
  }
  if (baselineProvider.version !== currentProvider.version) {
    const sameCompatibility = baselineProvider.compatibilityKey
      && currentProvider.compatibilityKey
      && baselineProvider.compatibilityKey === currentProvider.compatibilityKey;
    if (!sameCompatibility) {
      errors.push(qualityError(E_STRUCTURAL_QUALITY_EVALUATION_INCOMPARABLE, "Structural-quality provider version differs from the captured baseline"));
    }
  }
  return errors;
}

function providerDetection(value, providerId) {
  return normalizeStructuralQualityDetection(value, { providerId, id: providerId, transport: "runtime" });
}

function providerMetadata(provider, detection) {
  const metadata = provider?.metadata ?? provider;
  const id = metadata?.id ?? detection.providerId;
  const version = metadata?.version ?? detection.providerVersion ?? null;
  return {
    id,
    version,
    transport: metadata?.transport ?? detection.transport ?? "runtime",
    executionMode: metadata?.executionMode ?? "runtime-context",
    measurementModel: metadata?.measurementModel ?? detection.measurementModel ?? STRUCTURAL_QUALITY_MEASUREMENT_MODEL,
    compatibilityKey: metadata?.compatibilityKey ?? detection.compatibilityKey ?? null,
  };
}

function qualityError(code, message, artifacts = []) {
  return structuralQualityError(code, message, artifacts);
}

async function resolveProviderForContext({ target, taskId, policy, runtimeContext, timeoutMs, maxOutputBytes } = {}) {
  if (!policy || policy.mode === "off") return null;
  try {
    return await resolveStructuralQualityProvider({
      providerName: policy.provider,
      target,
      taskId,
      timeoutMs,
      maxOutputBytes,
      runtimeContext,
    });
  } catch (error) {
    if (error.code === E_STRUCTURAL_QUALITY_PROVIDER_UNAVAILABLE) return null;
    throw error;
  }
}

export async function resolveStructuralQualityContext(options = {}) {
  return withProjectReadSnapshot(options.target, () => resolveStructuralQualityContextObservation(options));
}

async function scopeIdentity(target, provider = null, providerId = null) {
  let providerConfigFingerprint = null;
  let architectureRulesFingerprint = null;
  const effectiveProviderId = provider?.id ?? providerId;
  if (provider && typeof provider.scopeBinding === "function") {
    const binding = await provider.scopeBinding({ projectPath: target });
    providerConfigFingerprint = binding?.providerConfigFingerprint ?? null;
    architectureRulesFingerprint = binding?.architectureRulesFingerprint ?? null;
  }
  const scope = {
    kind: "PROJECT",
    projectRoot: ".",
    providerConfigFingerprint,
    ...(architectureRulesFingerprint !== null ? { architectureRulesFingerprint } : {}),
  };
  return {
    scope,
    // Architecture rules are a separate policy sensor. They are retained for
    // provenance, but must not make identical Structural Quality measurements
    // incomparable when a project rule changes.
    scopeFingerprint: canonicalFingerprint({
      providerId: effectiveProviderId,
      kind: scope.kind,
      projectRoot: scope.projectRoot,
      providerConfigFingerprint: scope.providerConfigFingerprint,
    }),
  };
}

function statusForComparison(policy, comparison) {
  if (comparison.status === "PASS") return "PASS";
  if (comparison.status === "FAIL") return "FAIL";
  return policy.mode === "gate" ? "BLOCKED" : "NOT_OBSERVED";
}

async function taskInputs(target, packageRoot, taskId, options = {}) {
  return resolveStructuralQualityContext({ target, packageRoot, taskId, ...options });
}

function validateBindingErrors(value, expected) {
  const errors = [];
  const bindings = value.bindings ?? {};
  if (expected.taskId !== undefined && value.taskId !== expected.taskId) {
    errors.push(qualityError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, "Structural-quality task ID does not match the active task"));
  }
  for (const key of ["contractFingerprint", "routeFingerprint", "policyFingerprint", "scopeFingerprint"]) {
    if (expected[key] !== undefined && bindings[key] !== expected[key]) errors.push(qualityError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, `Structural-quality ${key} is stale`));
  }
  if (expected.providerId && value.provider?.id !== expected.providerId) errors.push(qualityError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, "Structural-quality provider binding is stale"));
  if (expected.baselineFingerprint !== undefined && value.role === "EVALUATION" && bindings.baselineFingerprint !== expected.baselineFingerprint) errors.push(qualityError(E_STRUCTURAL_QUALITY_BASELINE_BINDING_MISMATCH, "Structural-quality baseline binding is stale"));
  if (expected.verificationCycle !== undefined && value.role === "EVALUATION" && value.verificationCycle !== expected.verificationCycle) errors.push(qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "Structural-quality evaluation is from a stale verification cycle"));
  return errors;
}

export async function validateStructuralQualityEvaluationFreshness({
  target,
  packageRoot = getPackageRoot(),
  taskId,
  artifact,
  inputs = null,
  runtimeContext,
  check = null,
} = {}) {
  const value = artifact?.value ?? artifact;
  const errors = [];
  if (!value || typeof value !== "object") {
    return { valid: false, errors: [qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "Structural-quality evidence is missing")], reasonCodes: [E_STRUCTURAL_QUALITY_EVIDENCE_STALE] };
  }
  try {
    validateStructuralQualityArtifact(value, artifact?.path ?? "structural-quality artifact");
  } catch (error) {
    errors.push(error.code ? error : qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, error.message));
  }

  let active = inputs;
  if (!active) {
    try {
      active = await resolveStructuralQualityContext({ target, packageRoot, taskId, runtimeContext });
    } catch (error) {
      errors.push(error.code ? error : qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, error.message));
    }
  }
  if (active) {
    errors.push(...validateBindingErrors(value, {
      taskId,
      contractFingerprint: active.contract.fingerprint,
      routeFingerprint: active.route.fingerprint,
      policyFingerprint: active.policy ? structuralQualityPolicyFingerprint(active.policy) : undefined,
      scopeFingerprint: active.scopeFingerprint,
      providerId: active.policy?.provider,
      verificationCycle: value.role === "EVALUATION" ? active.state.verificationCycle : undefined,
    }));
  }

  let baseline = null;
  if (value.role === "EVALUATION") {
    try {
      baseline = await readStructuralQualityBaseline(target, taskId, packageRoot);
      if (!baseline) errors.push(qualityError(E_STRUCTURAL_QUALITY_BASELINE_MISSING, "Structural-quality evaluation has no captured baseline"));
    } catch (error) {
      errors.push(error.code ? error : qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, error.message));
    }
    if (baseline) {
      try {
        validateStructuralQualityArtifact(baseline.value, baseline.path);
      } catch (error) {
        errors.push(error.code ? error : qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, error.message));
      }
      if (active) {
        errors.push(...validateBindingErrors(baseline.value, {
          taskId,
          contractFingerprint: active.contract.fingerprint,
          routeFingerprint: active.route.fingerprint,
          policyFingerprint: active.policy ? structuralQualityPolicyFingerprint(active.policy) : undefined,
          scopeFingerprint: active.scopeFingerprint,
          providerId: active.policy?.provider,
        }));
      }
      errors.push(...validateBindingErrors(value, { baselineFingerprint: baseline.fingerprint }));
      errors.push(...providerCompatibilityErrors(baseline.value.provider, value.provider));
    }
  } else {
    errors.push(...providerCompatibilityErrors(value.provider, value.provider));
  }

  if (["BASELINE", "EVALUATION"].includes(value.role) && value.bindings?.sourceMaterialFingerprint) {
    try {
      const currentSourceFingerprint = await computeMaterialSourceFingerprint(target);
      if (currentSourceFingerprint !== value.bindings.sourceMaterialFingerprint) {
        errors.push(qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `Structural-quality ${value.role.toLowerCase()} source material has changed since capture`));
      }
    } catch (error) {
      errors.push(error.code ? error : qualityError(E_STRUCTURAL_QUALITY_SOURCE_FINGERPRINT_UNAVAILABLE, error.message));
    }
  }
  if (check) {
    if (!active?.policy) errors.push(qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "Structural-quality policy is unavailable"));
    else if (check.status !== checkProjection(active.policy, value).status) {
      errors.push(qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "Structural-quality check status does not match its persisted evaluation"));
    }
    if (artifact?.fingerprint && check.details?.artifactFingerprint !== artifact.fingerprint) {
      errors.push(qualityError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, "Structural-quality check fingerprint does not match its artifact"));
    }
  }
  return {
    valid: errors.length === 0,
    errors,
    reasonCodes: [...new Set(errors.map((error) => error.code ?? E_STRUCTURAL_QUALITY_EVIDENCE_STALE))].sort(),
  };
}

export async function computeMaterialSourceFingerprint(target) {
  try {
    const head = await repositoryHead(target);
    const statusEntries = await repositoryStatusEntries(target);
    const filtered = statusEntries
      .filter((entry) => !entry.path.startsWith(".forgeloop/")
        && !entry.path.startsWith(".git/")
        && !entry.path.startsWith(".sentrux/"));
    const enriched = [];
    for (const entry of filtered) {
      let digest = "DELETED";
      let exists = false;
      try {
        await lstat(ensureWithin(target, entry.path));
        exists = true;
      } catch (error) {
        if (error.code !== "ENOENT") throw fingerprintError(`Unable to inspect structural-quality source material: ${entry.path}`, error);
      }
      if (exists) {
        digest = await readMaterialFile(target, entry.path);
      }
      enriched.push({
        path: entry.path,
        sourcePath: entry.sourcePath ?? null,
        status: entry.status,
        digest,
      });
    }
    enriched.sort((left, right) => left.path.localeCompare(right.path));
    return canonicalFingerprint({
      kind: "GIT_WORKTREE",
      head,
      statusEntries: enriched,
    });
  } catch (error) {
    if (error?.code === E_STRUCTURAL_QUALITY_SOURCE_FINGERPRINT_UNAVAILABLE) throw error;
    const files = await crawlDirectory(target);
    return canonicalFingerprint({
      kind: "DIRECTORY",
      files,
    });
  }
}

async function crawlDirectory(root, current = "") {
  const dirPath = current ? path.join(root, current) : root;
  let entries;
  try {
    entries = await readdir(dirPath, { withFileTypes: true });
  } catch (error) {
    throw fingerprintError(`Unable to enumerate structural-quality source material: ${current || "."}`, error);
  }
  const files = [];
  for (const entry of entries) {
    const rel = current ? path.join(current, entry.name).replaceAll("\\", "/") : entry.name;
    if (entry.isSymbolicLink()) {
      throw fingerprintError(`Structural-quality source material uses an unsafe symlink: ${rel}`);
    }
    if (entry.isDirectory()) {
      if (IGNORED_DIRECTORIES.has(entry.name) || rel.startsWith(".forgeloop/")) continue;
      files.push(...(await crawlDirectory(root, rel)));
    } else if (entry.isFile()) {
      if (rel.startsWith(".forgeloop/")) continue;
      files.push({ path: rel, sha256: await readMaterialFile(root, rel) });
    } else {
      throw fingerprintError(`Unsupported structural-quality source material: ${rel}`);
    }
  }
  return files.sort((left, right) => left.path.localeCompare(right.path));
}

function fingerprintError(message, cause = null) {
  const error = new Error(message);
  error.code = E_STRUCTURAL_QUALITY_SOURCE_FINGERPRINT_UNAVAILABLE;
  if (cause) error.cause = cause;
  return error;
}

async function readMaterialFile(root, relativePath) {
  const fullPath = ensureWithin(root, relativePath);
  let info;
  try {
    info = await lstat(fullPath);
  } catch (error) {
    throw fingerprintError(`Unable to inspect structural-quality source material: ${relativePath}`, error);
  }
  if (info.isSymbolicLink()) {
    throw fingerprintError(`Structural-quality source material uses an unsafe symlink: ${relativePath}`);
  }
  if (!info.isFile()) {
    throw fingerprintError(`Structural-quality source material is not a regular file: ${relativePath}`);
  }
  try {
    return sha256(await readBytes(fullPath));
  } catch (error) {
    throw fingerprintError(`Unable to read structural-quality source material: ${relativePath}`, error);
  }
}

export function isKitPath(relativePath) {
  return relativePath === FORGELOOP_KIT_DIR || relativePath.startsWith(`${FORGELOOP_KIT_DIR}/`);
}

export async function assertTaskMutationAllowed(target, options = {}) {
  const result = await resolveTaskClaimState(target, options);
  if (result.mutationAllowed) return result;

  const inconsistent = result.claimState === "INCONSISTENT";
  const error = new Error(inconsistent
    ? `Task ${result.taskId} claim ownership is inconsistent; ordinary mutation is blocked`
    : result.claimState === "RELEASED_BY_COMPLETION"
      ? `Task ${result.taskId} is COMPLETE and cannot be mutated`
      : `Task ${result.taskId} is RECOVERED and its write claims are released; run task-resume before ordinary mutation`);
  error.code = inconsistent
    ? E_TASK_CLAIM_OWNERSHIP_INCONSISTENT
    : result.claimState === "RELEASED_BY_COMPLETION"
      ? E_TASK_COMPLETE
      : E_TASK_RECOVERED;
  error.taskId = result.taskId;
  error.claimState = result.claimState;
  error.reasonCodes = result.reasonCodes;
  error.errors = result.errors;
  error.recovery = result.recovery;
  throw error;
}

export function buildTaskClaimEvidence({ taskId, descriptor, state, recovery, ledger, repairArtifacts = null, initialErrors = [] }) {
  const errors = [...initialErrors];
  if (!ledger.valid) {
    for (const error of ledger.errors) {
      errors.push(ownershipError(`Task event ledger is invalid: ${error.message}`, error));
    }
  }
  if (ledger.events.some((event) => event.taskId !== taskId)) {
    errors.push(ownershipError(`Task event ledger contains an event for a different task`));
  }
  if (state) {
    for (const error of validateStateLedgerCoherence(state, ledger.events)) {
      if (![
        "E_CHECKPOINT_REVALIDATION_UNSAFE",
        "E_CONTRACT_REVISION_UNSAFE",
      ].includes(error.code)) continue;
      errors.push(ownershipError(`Task state and event ledger are incoherent: ${error.message}`, error));
    }
  }

  const repairConsistencyErrors = validateContractBootstrapRepairConsistency(taskId, ledger.events, state, repairArtifacts);
  errors.push(...repairConsistencyErrors);

  const descriptorClaims = [];
  appendClaims(descriptorClaims, descriptor?.writeClaims, errors, "descriptor");
  const normalizedDescriptorClaims = normalizeWriteClaims(descriptorClaims);

  const historicalClaims = new Set(normalizedDescriptorClaims);
  const observeRecovery = cycle => appendClaims(historicalClaims, cycle.event?.details?.releasedClaims, errors, "recovery ledger");
  const history = Array.isArray(ledger.events)
    ? classifyRecoveryHistory(ledger.events)
    : summarizeRecoveryHistory(ledger.events, observeRecovery);
  if (Array.isArray(ledger.events)) for (const cycle of history.recoveries) observeRecovery(cycle);
  appendClaims(historicalClaims, recovery?.releasedClaims, errors, "recovery artifact");

  return {
    taskId,
    phase: state?.phase ?? null,
    descriptor,
    state,
    recovery,
    ledger,
    history,
    normalizedDescriptorClaims,
    historicalWriteClaims: normalizeWriteClaims([...historicalClaims]),
    errors,
  };
}

export function classifyTaskClaimState(evidence) {
  const {
    taskId,
    phase,
    recovery,
    ledger,
    history,
    normalizedDescriptorClaims,
    historicalWriteClaims,
  } = evidence;

  // Classification is side-effect free: never mutate the supplied evidence.
  const errors = [...(evidence.errors ?? [])];
  errors.push(...validateTaskRecoveryConsistency({
    taskId,
    recovery,
    events: ledger.events,
    historicalWriteClaims: normalizedDescriptorClaims,
    recoveryHistory: history,
  }));

  if (errors.length > 0) {
    return inconsistentResult({ taskId, phase, historicalWriteClaims, recovery, errors });
  }

  if (phase === "COMPLETE") {
    const proof = validateCompletionOwnershipProof({ taskId, state: evidence.state, ledger });
    if (!proof.valid) {
      return inconsistentResult({
        taskId,
        phase,
        historicalWriteClaims,
        recovery,
        errors: [
          ownershipError(
            "COMPLETE work-state lacks canonical lifecycle/ledger completion proof; claims stay reserved",
            { code: E_COMPLETION_OWNERSHIP_UNPROVEN },
          ),
          ...proof.errors.map((error) => ownershipError(error.message, { code: error.code })),
        ],
      });
    }
    return {
      taskId,
      phase,
      historicalWriteClaims,
      effectiveWriteClaims: [],
      writeClaims: [],
      claimState: "RELEASED_BY_COMPLETION",
      mutationAllowed: false,
      recovery: null,
      recoveryStatus: "NOT_APPLICABLE",
      valid: true,
      ownershipValid: true,
      reasonCodes: [],
      errors: [],
      ownershipErrors: [],
    };
  }

  if (history.activeRecovery) {
    // The consistency validator above guarantees that the active ledger cycle
    // and recovery artifact identify the same recovery before this branch.
    return {
      taskId,
      phase,
      historicalWriteClaims,
      effectiveWriteClaims: [],
      writeClaims: [],
      claimState: "RELEASED_BY_RECOVERY",
      mutationAllowed: false,
      recovery,
      recoveryStatus: "ACTIVE",
      valid: true,
      ownershipValid: true,
      reasonCodes: [],
      errors: [],
      ownershipErrors: [],
    };
  }

  return {
    taskId,
    phase,
    historicalWriteClaims,
    effectiveWriteClaims: normalizedDescriptorClaims,
    writeClaims: normalizedDescriptorClaims,
    claimState: "ACTIVE",
    mutationAllowed: true,
    recovery: null,
    recoveryStatus: (history.completedRecoveryCount ?? history.completedRecoveries.length) > 0 ? "COMPLETED" : "ABSENT",
    valid: true,
    ownershipValid: true,
    reasonCodes: [],
    errors: [],
    ownershipErrors: [],
  };
}

async function collectContractBootstrapRepairConsistency(target, packageRoot, taskId, events, state) {
  const anchor = resolveEffectiveContractBootstrapRepairAnchor(events);
  if (!anchor) return null;
  const details = anchor.details;
  const artifacts = { contract: null, route: null, contractError: null, routeError: null };

  // Contract binding: the current contract must exist, validate, and bind to
  // the marker and work state.
  try {
    const contract = await readContract(target, packageRoot, { taskId });
    artifacts.contract = contract;
    if (contract.fingerprint !== details.contractFingerprint) {
      artifacts.contractError = `contract fingerprint ${contract.fingerprint} does not match marker contract fingerprint ${details.contractFingerprint}`;
    } else if (state && state.contractFingerprint !== details.contractFingerprint) {
      artifacts.contractError = "work-state contract fingerprint does not match marker contract fingerprint";
    }
  } catch (error) {
    if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
    artifacts.contractError = error.code === "ARTIFACT_MISSING"
      ? "contract artifact is missing after a recorded repair"
      : `contract artifact is invalid after a recorded repair: ${error.message}`;
  }

  // Route binding is anchored exactly at repair time, then follows the
  // current state/route identity after the checkpoint advances.
  const routeRequired = state && (REPAIR_ROUTE_PHASES.has(state.phase)
    || state.routeFingerprint !== undefined);
  if (routeRequired || details.routeFingerprint !== null) {
    try {
      const route = await readPersistedRoute(target, packageRoot, { taskId });
      artifacts.route = route;
      if (route.value?.contractFingerprint !== undefined
        && route.value.contractFingerprint !== details.contractFingerprint) {
        artifacts.routeError = "route artifact contract binding does not match repair anchor contract fingerprint";
      }
    } catch (error) {
      if (error.code === "E_STATE_REVISION_CONFLICT") throw error;
      artifacts.routeError = error.code === "ARTIFACT_MISSING"
        ? "route artifact is missing after a routed repair"
        : `route artifact is invalid after a routed repair: ${error.message}`;
    }
  }

  return artifacts;
}

export async function collectTaskClaimEvidence(target, options = {}) {
  return collectClaimEvidence(target, options);
}

function ownershipError(message, cause = null) {
  return {
    code: E_TASK_RECOVERY_INCONSISTENT,
    message,
    ...(cause?.code ? { causeCode: cause.code } : {}),
  };
}

export async function resolveTaskClaimState(target, options = {}) {
  return withTaskClaimEvidence(target, options, classifyTaskClaimState);
}

export async function withResolvedTask(
  target,
  options = {},
  callback,
  { explicitRequired = false } = {},
) {
  const taskOption = options.taskId ?? options.task ?? null;
  const taskContext = await resolveTaskContext(target, {
    taskId: taskOption,
    explicitRequired,
    packageRoot: options.packageRoot,
    selectionMode: TASK_SELECTION_MODES.READ,
  });

  return callback(taskContext);
}

export function candidateTasksForSelection(tasks, selectionMode = TASK_SELECTION_MODES.MUTATION) {
  if (selectionMode === TASK_SELECTION_MODES.READ) {
    return tasks.filter((task) => task.healthy !== false);
  }
  return tasks.filter(isOperationallyActiveTask);
}

export function createTaskDescriptor({
  taskId,
  writeClaims = [],
  createdAt = new Date().toISOString(),
  updatedAt = createdAt,
} = {}) {
  assertTaskId(taskId);
  const taskKey = taskStorageKey(taskId);
  const normalizedClaims = normalizeWriteClaims(writeClaims);

  const descriptor = {
    schemaVersion: TASK_DESCRIPTOR_SCHEMA_VERSION,
    protocolVersion: PROTOCOL_VERSION,
    taskId,
    taskKey,
    createdAt,
    updatedAt,
    writeClaims: normalizedClaims,
  };

  assertTaskDescriptorIdentity(descriptor, taskId, taskKey);
  return descriptor;
}

export async function validateTaskDescriptor(descriptor, packageRoot = getPackageRoot()) {
  assertTaskDescriptorIdentity(descriptor);
  const schema = await readSchema("task-descriptor", packageRoot);
  assertSchema(descriptor, schema, "task descriptor");
  return descriptor;
}

export async function discoverTasks(target, packageRoot = getPackageRoot(), { taskKeys = null } = {}) {
  return discoverTasksInScope(target, packageRoot, taskKeys, DISCOVERY_PROJECTIONS.FULL);
}

export async function findTaskById(target, taskId, packageRoot = getPackageRoot()) {
  return withNativeReadScope(target, async () => {
    const taskKey = taskStorageKey(taskId);
    const store = getOperationalStore(target);
    if (store && !store.taskRow(taskKey)) return null;
    const tasks = await discoverTasks(target, packageRoot, store ? { taskKeys: [taskKey] } : {});
    return tasks.find((t) => t.healthy !== false && (t.taskId === taskId || t.taskKey === taskKey)) ?? null;
  });
}

export function classifyLockStaleness(lock, now = Date.now()) {
  if (!lock) return { status: "NONE", stale: false };
  if (lock.corrupted) return { status: "CORRUPT", stale: false };
  if (!isValidTaskLockIdentity(lock)) return { status: "UNKNOWN", stale: false };
  return classifyLeaseWindow(lock, now);
}

export function currentProcessStartToken(now = Date.now(), uptimeSeconds = process.uptime()) {
  return `${process.pid}:${Math.max(0, Math.floor(now - (uptimeSeconds * 1000)))}`;
}

const checkIdentity = (obj, relPath) => {
  if (obj && obj.taskId && obj.taskId !== taskId) {
    const error = new Error(`Task identity mismatch in ${relPath}: expected ${taskId}, got ${obj.taskId}`);
    error.code = E_TASK_MIGRATION_IDENTITY_MISMATCH;
    throw error;
  }
};

const processDir = async (dirKey, dirRelPath, schemaName) => {
  if (!dirRelPath) return;
  const absPath = ensureWithin(target, dirRelPath);
  if (!(await fileExists(absPath))) return;

  const entries = await readdir(absPath, { withFileTypes: true });
  const fileHashes = [];

  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      const error = new Error(`Symlinks not allowed in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }
    if (!entry.isFile()) {
      const error = new Error(`Unexpected non-file entry in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }
    if (!entry.name.endsWith(".json")) {
      const error = new Error(`Unexpected non-json file in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }

    const fileRelPath = path.posix.join(dirRelPath, entry.name);
    const fileAbsPath = path.join(absPath, entry.name);

    try {
      const { value } = await readPortableJsonArtifact(target, fileRelPath, schemaName, packageRoot);
      checkIdentity(value, fileRelPath);
      const hash = await fingerprintFile(fileAbsPath);
      fileHashes.push({ relPath: entry.name, hash });
    } catch (err) {
      if (err.code === E_TASK_MIGRATION_IDENTITY_MISMATCH) throw err;
      const error = new Error(`Validation failed for ${fileRelPath}: ${err.message}`);
      error.code = E_TASK_MIGRATION_INVALID;
      error.cause = err;
      throw error;
    }
  }

  if (fileHashes.length > 0) {
    fileHashes.sort((a, b) => a.relPath.localeCompare(b.relPath));
    let hashStr = "";
    for (const item of fileHashes) {
      hashStr += `${item.relPath}\0${item.hash}\n`;
    }
    directoryFingerprints[dirKey] = createHash("sha256").update(hashStr).digest("hex");
  } else {
    directoryFingerprints[dirKey] = createHash("sha256").update("").digest("hex");
  }
};

async function fingerprintFile(absolutePath) {
  const bytes = await readFile(absolutePath);
  return createHash("sha256").update(bytes).digest("hex");
}

export async function validateMigrationSnapshot(target, { taskId, packageRoot, paths }) {
  const artifactFingerprints = {};
  const directoryFingerprints = {};
  let eventCount = 0;

  const checkIdentity = (obj, relPath) => {
    if (obj && obj.taskId && obj.taskId !== taskId) {
      const error = new Error(`Task identity mismatch in ${relPath}: expected ${taskId}, got ${obj.taskId}`);
      error.code = E_TASK_MIGRATION_IDENTITY_MISMATCH;
      throw error;
    }
  };

  const jsonMap = {
    contract: "current-contract",
    route: "routing-result",
    preflight: "preflight",
    state: "work-state",
    continuity: "continuity",
    receipt: "execution-receipt",
  };

  for (const [key, schemaName] of Object.entries(jsonMap)) {
    const relPath = paths[key];
    if (relPath) {
      const absPath = ensureWithin(target, relPath);
      if (await fileExists(absPath)) {
        try {
          const { value } = await readPortableJsonArtifact(target, relPath, schemaName, packageRoot);
          checkIdentity(value, relPath);
          artifactFingerprints[key] = await fingerprintFile(absPath);
        } catch (err) {
          if (err.code === E_TASK_MIGRATION_IDENTITY_MISMATCH) throw err;
          const error = new Error(`Validation failed for ${relPath}: ${err.message}`);
          error.code = E_TASK_MIGRATION_INVALID;
          error.cause = err;
          throw error;
        }
      }
    }
  }

  if (paths.events) {
    const absPath = ensureWithin(target, paths.events);
    if (await fileExists(absPath)) {
      const ledger = await validatePortableEventLedger(target, packageRoot, { eventsPath: paths.events });
      if (!ledger.valid) {
        const error = new Error(`Event ledger validation failed for ${paths.events}: ${ledger.errors?.[0]?.message ?? "invalid ledger"}`);
        error.code = E_TASK_MIGRATION_INVALID;
        error.cause = ledger.errors?.[0];
        throw error;
      }
      for (const event of ledger.events) {
        checkIdentity(event, paths.events);
      }
      artifactFingerprints.events = await fingerprintFile(absPath);
      eventCount = ledger.events.length;
    }
  }

  const processDir = async (dirKey, dirRelPath, schemaName) => {
    if (!dirRelPath) return;
    const absPath = ensureWithin(target, dirRelPath);
    if (!(await fileExists(absPath))) return;

    const entries = await readdir(absPath, { withFileTypes: true });
    const fileHashes = [];

    for (const entry of entries) {
      if (entry.isSymbolicLink()) {
        const error = new Error(`Symlinks not allowed in ${dirRelPath}: ${entry.name}`);
        error.code = E_TASK_MIGRATION_INVALID;
        throw error;
      }
      if (!entry.isFile()) {
        const error = new Error(`Unexpected non-file entry in ${dirRelPath}: ${entry.name}`);
        error.code = E_TASK_MIGRATION_INVALID;
        throw error;
      }
      if (!entry.name.endsWith(".json")) {
        const error = new Error(`Unexpected non-json file in ${dirRelPath}: ${entry.name}`);
        error.code = E_TASK_MIGRATION_INVALID;
        throw error;
      }

      const fileRelPath = path.posix.join(dirRelPath, entry.name);
      const fileAbsPath = path.join(absPath, entry.name);

      try {
        const { value } = await readPortableJsonArtifact(target, fileRelPath, schemaName, packageRoot);
        checkIdentity(value, fileRelPath);
        const hash = await fingerprintFile(fileAbsPath);
        fileHashes.push({ relPath: entry.name, hash });
      } catch (err) {
        if (err.code === E_TASK_MIGRATION_IDENTITY_MISMATCH) throw err;
        const error = new Error(`Validation failed for ${fileRelPath}: ${err.message}`);
        error.code = E_TASK_MIGRATION_INVALID;
        error.cause = err;
        throw error;
      }
    }

    if (fileHashes.length > 0) {
      fileHashes.sort((a, b) => a.relPath.localeCompare(b.relPath));
      let hashStr = "";
      for (const item of fileHashes) {
        hashStr += `${item.relPath}\0${item.hash}\n`;
      }
      directoryFingerprints[dirKey] = createHash("sha256").update(hashStr).digest("hex");
    } else {
      directoryFingerprints[dirKey] = createHash("sha256").update("").digest("hex");
    }
  };

  await processDir("gates", paths.gates, "gate");
  await processDir("executions", paths.executions, "execution");

  return {
    taskId,
    artifactFingerprints,
    directoryFingerprints,
    eventCount,
  };
}

export async function detectLegacySingletonLayout(target) {
  const legacyFiles = [];
  for (const [key, relPath] of Object.entries(LEGACY_TASK_ARTIFACT_PATHS)) {
    const fullPath = ensureWithin(target, relPath);
    if (await fileExists(fullPath)) {
      legacyFiles.push({ key, path: relPath });
    }
  }
  return {
    hasLegacy: legacyFiles.length > 0,
    legacyFiles,
  };
}

export function assertTaskRecoveryAuthority(recovery) {
  const authority = recovery?.authority;
  const validCaller = authority?.kind === "CALLER_ACKNOWLEDGED" && authority.grantRef === undefined;
  const validHost = authority?.kind === "HOST_ATTESTED"
    && typeof authority.grantRef === "string"
    && authority.grantRef.trim() !== "";
  if (validCaller || validHost) return recovery;
  const error = new Error(
    "Recovery authority must be caller acknowledgement or host attestation with a trusted grant reference",
  );
  error.code = E_TASK_RECOVERY_AUTHORITY_INVALID;
  throw error;
}

export function assertClaimsCoverChangedPaths(claims, changedPaths) {
  const normalizedClaims = normalizeWriteClaims(claims);
  if (normalizedClaims.length === 0) return;

  // Root claim covers everything
  if (normalizedClaims.includes(".")) return;

  const outOfScope = [];
  for (const changedPath of changedPaths ?? []) {
    const normPath = changedPath.replaceAll("\\", "/").replace(/^\.\//, "").toLowerCase();
    const covered = normalizedClaims.some((claim) => {
      const normClaim = claim.toLowerCase();
      return normPath === normClaim || normPath.startsWith(`${normClaim}/`);
    });
    if (!covered) {
      outOfScope.push(changedPath);
    }
  }

  if (outOfScope.length > 0) {
    const error = new Error(
      `Observed repository changes exceed task write claims: ${outOfScope.slice(0, 5).join(", ")}${outOfScope.length > 5 ? "..." : ""}`,
    );
    error.code = E_TASK_CHANGE_OUTSIDE_SCOPE;
    error.outOfScopePaths = outOfScope;
    throw error;
  }
}

export function assertNoScopeConflicts(newClaims, existingTasks = [], currentTaskId = null) {
  const normalizedNew = normalizeWriteClaims(newClaims);
  if (normalizedNew.length > 0) {
    const ownershipBlockers = existingTasks.filter((task) => {
      if (task.taskId === currentTaskId) return false;
      if (task.healthy === false) return true;
      if (task.claimState !== "INCONSISTENT" && task.ownershipValid !== false) return false;
      const retainedClaims = normalizeWriteClaims(
        task.effectiveWriteClaims ?? task.writeClaims ?? task.descriptor?.writeClaims ?? [],
      );
      return retainedClaims.length === 0
        || normalizedNew.some((claim) => retainedClaims.some((retained) => claimsOverlap(claim, retained)));
    });
    if (ownershipBlockers.length > 0) {
      const error = new Error(
        `Cannot acquire write claims while task ownership is inconsistent: ${ownershipBlockers
          .map((task) => task.taskId ?? task.taskKey)
          .join(", ")}`,
      );
      error.code = E_TASK_CLAIM_OWNERSHIP_INCONSISTENT;
      error.tasks = ownershipBlockers.map((task) => ({
        taskId: task.taskId ?? null,
        taskKey: task.taskKey ?? null,
        claimState: task.claimState ?? "INCONSISTENT",
        reasonCodes: task.reasonCodes ?? [task.error?.code].filter(Boolean),
      }));
      throw error;
    }
  }

  const conflicts = checkScopeConflicts(newClaims, existingTasks, currentTaskId);
  if (conflicts.length > 0) {
    const first = conflicts[0];
    const error = new Error(
      `Task write claim "${first.requestedClaim}" conflicts with active task "${first.taskId}" (claim "${first.conflictingClaim}", phase: ${first.phase ?? "PLANNED"})`,
    );
    error.code = E_TASK_SCOPE_CONFLICT;
    error.conflicts = conflicts;
    throw error;
  }
}

export async function assertScopeClean(target, claims) {
  const normalized = normalizeWriteClaims(claims);
  if (normalized.length === 0) return;

  const changed = await currentChangedPaths(target, { paths: normalized });
  if (changed !== null && changed.length > 0) {
    const error = new Error(
      `Claimed scope contains pre-existing uncommitted changes: ${changed.slice(0, 5).join(", ")}${changed.length > 5 ? "..." : ""}`,
    );
    error.code = E_TASK_SCOPE_DIRTY;
    error.changedPaths = changed;
    throw error;
  }
}

export function claimsOverlap(claimA, claimB) {
  const normA = normalizeWriteClaim(claimA).toLowerCase();
  const normB = normalizeWriteClaim(claimB).toLowerCase();

  if (normA === "." || normB === ".") {
    return true;
  }

  if (normA === normB) {
    return true;
  }

  if (normA.startsWith(`${normB}/`)) {
    return true;
  }

  if (normB.startsWith(`${normA}/`)) {
    return true;
  }

  return false;
}

export function normalizeWriteClaims(claims) {
  if (claims === undefined || claims === null) {
    return [];
  }
  if (!Array.isArray(claims)) {
    const error = new Error("writeClaims must be an array of string prefixes");
    error.code = E_TASK_DESCRIPTOR_INVALID;
    throw error;
  }

  const normalized = claims.map((c) => normalizeWriteClaim(c));
  const unique = [...new Set(normalized)];
  return unique.sort((a, b) => a.localeCompare(b));
}

export function getPackageRoot() {
  return PACKAGE_ROOT;
}

export async function readTemplateEntries(packageRoot = PACKAGE_ROOT) {
  return Promise.all(
    TEMPLATE_PATHS.map(async (relativePath) => {
      const sourcePath = relativePath;
      const inlineContent = INLINE_TEMPLATE_CONTENT[relativePath];
      return {
        relativePath: targetPathForSource(relativePath),
        sourcePath,
        legacyRelativePath: legacyPathForSource(sourcePath),
        bytes: Buffer.from(
          inlineContent !== undefined
            ? inlineContent
            : isNativeAdapterPath(relativePath)
              ? nativeShim(relativePath)
              : await readFile(path.join(packageRoot, sourcePath)),
        ),
      };
    }),
  );
}

function collectUnits(source) {
  const units = [];
  const matcher = /\b(test|it)\s*\(\s*(["'`])([^"'`]+)\2/g;
  let match;
  while ((match = matcher.exec(source))) units.push({ name: match[3].trim(), line: source.slice(0, match.index).split("\n").length });
  return units;
}

async function filesUnder(root, relative = "") {
  const current = path.join(root, relative);
  let entries = [];
  try { entries = await readdir(current, { withFileTypes: true }); } catch { return []; }
  const result = [];
  for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
    const child = path.join(relative, entry.name);
    if (entry.isDirectory()) result.push(...await filesUnder(root, child));
    else if (entry.isFile() && TEST_FILE_PATTERN.test(entry.name)) result.push(child);
  }
  return result;
}

function frameworkFor(source) {
  if (/node:test/.test(source)) return "node:test";
  if (/vitest/.test(source)) return "vitest";
  if (/jest/.test(source)) return "jest";
  if (/pytest|unittest/.test(source)) return "python";
  return "unknown";
}

export async function inventoryTests(projectRoot = process.cwd()) {
  const files = [];
  for (const directory of TEST_DIRECTORIES) files.push(...await filesUnder(projectRoot, directory));
  const tests = [];
  for (const relativeFile of [...new Set(files)].sort()) {
    const source = await readFile(path.join(projectRoot, relativeFile), "utf8");
    const framework = frameworkFor(source);
    for (const unit of collectUnits(source)) {
      const file = relativeFile.replaceAll(path.sep, "/");
      tests.push({
        testId: stableId(framework, file, "", unit.name), file, framework, suite: "", name: unit.name,
        line: unit.line, sourceSummary: `${file}:${unit.line} ${unit.name}`.slice(0, 500),
        targets: [file], runtimeMs: null, uniqueBranches: null, signals: signals(file, unit.name),
      });
    }
  }
  tests.sort((a, b) => a.testId.localeCompare(b.testId));
  return { schemaVersion: 1, source: "DETERMINISTIC", tests };
}

function signals(file, name) {
  const text = `${file} ${name}`.toLowerCase();
  return {
    requiredBehavior: /contract|acceptance|required|lifecycle|protocol/.test(text),
    security: /security|auth|secret|permission|credential|csp|injection/.test(text),
    publicApi: /api|compat|public|cli|protocol/.test(text),
    criticalPath: /critical|transaction|lock|concurr|race|recovery/.test(text),
    integration: /integration|e2e|browser|provider|package|release/.test(text),
    migration: /migration|schema|upgrade|downgrade/.test(text),
    release: /package|release|publish|smoke/.test(text),
    platformSpecific: /windows|win32|macos|darwin|linux|platform|native/.test(text),
  };
}

function stableId(framework, file, suite, name) {
  return `test-${createHash("sha256").update(JSON.stringify({ framework, file, suite, name })).digest("hex").slice(0, 24)}`;
}

export function batchTests(tests = [], size = TEST_UTILITY_BATCH_SIZE) {
  const batches = [];
  for (let index = 0; index < tests.length; index += size) batches.push(tests.slice(index, index + size));
  return batches;
}

export function buildTestSemanticState(tests = []) {
  return {
    tests: tests.map(({ testId, file, framework, suite, name, line, sourceSummary, targets, runtimeMs, uniqueBranches, signals }) => ({
      testId, file, framework, suite, name, line, sourceSummary, targets, runtimeMs, uniqueBranches, signals,
    })),
  };
}

export function eventCategory(eventType) {
  return EVENT_CATEGORY_MAP[eventType] ?? "integrity";
}

function eventSummary(event) {
  const d = event.details ?? {};
  const staticSummary = STATIC_EVENT_SUMMARIES[event.event];
  if (staticSummary) return staticSummary;
  switch (event.event) {
    case "TASK_RECEIVED":
      return `Task received${d.taskId ? ` (${d.taskId})` : ""}`;
    case "CONTRACT_VALIDATED":
      return "Contract validated";
    case "ROUTE_VALIDATED":
      return `Route selected${Array.isArray(d.selectedGuides) ? `: ${d.selectedGuides.join(", ")}` : ""}`;
    case "PREFLIGHT_READY":
      return "Preflight READY";
    case "PREFLIGHT_BLOCKED":
      return "Preflight BLOCKED";
    case "EXECUTION_STARTED":
      return "Execution started";
    case "VERIFICATION_RECORDED": {
      const id = d.id ?? d.checkId ?? d.requirement ?? "check";
      return `${id} ${String(d.status ?? "recorded").toUpperCase()}${d.exitCode !== undefined ? ` (exit ${d.exitCode})` : ""}`;
    }
    case "TERMINAL_RESULT_RECORDED":
      return `Terminal result ${d.type ?? ""} ${d.status ?? ""}`.trim();
    case "REVIEW_STARTED":
      return `Review started${Number.isInteger(d.verificationCycle) ? ` for cycle ${d.verificationCycle}` : ""}`;
    case "DIAGNOSIS_RECORDED":
      return `Diagnosis recorded (${d.informationGain ?? "gain unknown"})`;
    case "DIAGNOSTIC_CASE_RECORDED":
      return `Diagnostic case recorded (cycle ${d.verificationCycle}, revision ${d.diagnosticRevision})`;
    case "INTERVENTION_RECORDED":
      return `Intervention recorded (${d.intervention?.id ?? "unknown"})`;
    case "HYPOTHESIS_DISPOSITION_RECORDED":
      return `Hypothesis ${d.hypothesisRef ?? "unknown"} ${d.status ?? "dispositioned"}`;
    case "DECISION_CRITERION_RECORDED":
      return "Decision criterion recorded";
    case "GATE_SATISFIED":
      return `Gate satisfied: ${d.gate ?? "unknown"}`;
    case "CHECKPOINT_RECONCILED":
      return "Checkpoint reconciled";
    case "CONTINUITY_RECORDED":
      return "Continuity checkpoint recorded";
    case "TASK_RECOVERY_RECORDED":
      return `Task recovery recorded (${d.classification ?? "unknown"})`;
    case "COMPLETION_VALIDATED":
      return "Completion validated";
    case "COMPLETION_REJECTED":
      return "Completion rejected";
    case "TRANSACTION_COMMITTED":
      return "Transaction committed";
    case "ACTION_PROPOSED":
      return `Action proposed (${d.actionId ?? "unknown"})`;
    case "ACTION_AUTHORIZED":
      return `Action authorized (${d.actionId ?? "unknown"})`;
    case "ACTION_STARTED":
      return `Action started (${d.actionId ?? "unknown"})`;
    case "ACTION_COMMIT_RECORDED":
      return `Action commit recorded (${d.actionId ?? "unknown"})`;
    case "ACTION_VERIFIED":
      return `Action verified (${d.actionId ?? "unknown"})`;
    case "ACTION_FAILED":
      return `Action failed (${d.actionId ?? "unknown"})`;
    case "ACTION_COMMIT_UNKNOWN":
      return `Action commit unknown (${d.actionId ?? "unknown"})`;
    case "ACTION_RECONCILED":
      return `Action reconciled (${d.actionId ?? "unknown"})`;
    case "ACTION_CANCELLED":
      return `Action cancelled (${d.actionId ?? "unknown"})`;
    default:
      return event.event;
  }
}

function historyQualityFromSummary(snapshot, eventCount, hasLegacyTimestamp) {
  const reasons = [];
  const hasLedger = eventCount > 0;
  if (!hasLedger) reasons.push("LEDGER_ABSENT");
  if (hasLegacyTimestamp) {
    reasons.push("LEGACY_PHASE_TIMESTAMPS_UNAVAILABLE");
  }
  if (snapshot.state && Number.isInteger(snapshot.state.verificationCycle) && snapshot.state.verificationCycle > 1
    && !snapshot.events.some((event) => event.event === "DIAGNOSIS_RECORDED" || event.event === "DIAGNOSTIC_CASE_RECORDED")) {
    reasons.push("STRUCTURED_DIAGNOSTICS_UNAVAILABLE");
  }
  const level = reasons.length === 0 ? "COMPLETE" : (hasLedger ? "PARTIAL" : "MINIMAL");
  return { level, reasons };
}

function legacyDiagnoses(events, taskId) {
  return [...ledgerEventsOfTypes(events, ["DIAGNOSIS_RECORDED"])]
    .filter(event => !taskId || event.taskId === taskId).map((event) => ({
    sequence: event.seq,
    at: event.at,
    sourceModel: "LEGACY_DIAGNOSIS_V1",
    ...event.details,
  }));
}

function orderedSequences(events) {
  let previous = -Infinity;
  return events.every(event => {
    if (!Number.isFinite(event.seq) || event.seq <= previous) return false;
    previous = event.seq;
    return true;
  });
}

function phaseStep(event, currentPhase) {
  const milestone = PHASE_MILESTONES[event.event];
  if (milestone) return { phase: milestone.phase, quality: milestone.quality };
  const derive = PHASE_DERIVATIONS[event.event];
  const derived = derive ? derive(event.details ?? {}) : null;
  return { phase: derived ?? currentPhase, quality: derived || currentPhase ? "derived" : "unknown" };
}

function* phasedEvents(events) {
  let currentPhase = null;
  if (orderedSequences(events)) {
    for (const event of events) {
      const step = phaseStep(event, currentPhase);
      currentPhase = step.phase;
      yield { event, ...step };
    }
    return;
  }
  // Legacy duplicate sequence keys retain the original last-write projection.
  const phases = new Map();
  for (const event of events) {
    const step = phaseStep(event, currentPhase);
    currentPhase = step.phase;
    phases.set(event.seq, step);
  }
  for (const event of events) yield { event, ...phases.get(event.seq) };
}

function projectChecks(snapshot) {
  const state = snapshot.state;
  const attemptsByCheck = new Map();
  const pushAttempt = (key, attempt) => {
    if (!attemptsByCheck.has(key)) attemptsByCheck.set(key, []);
    attemptsByCheck.get(key).push(attempt);
  };

  // Ledger chronology is the primary source of historical attempts.
  const ledgerIdentityKeys = new Set();
  for (const event of snapshot.events) {
    if (event.event !== "VERIFICATION_RECORDED") continue;
    const d = event.details ?? {};
    const key = d.id ?? d.checkId ?? d.requirement ?? null;
    if (!key) continue;
    ledgerIdentityKeys.add(`${key}@@${d.verificationCycle ?? "*"}`);
    pushAttempt(key, {
      sequence: event.seq,
      at: event.at,
      status: d.status ?? null,
      exitCode: d.exitCode ?? null,
      requirement: d.requirement ?? null,
      verificationCycle: d.verificationCycle ?? null,
      provenance: d.provenance ?? null,
      executionMode: d.provenance === "FORGELOOP_EXECUTED"
        ? "executed"
        : (d.provenance === "ACTOR_REPORTED" || d.provenance === "MANUAL_OBSERVATION" ? "observed" : (d.executionId ? "executed" : "unknown")),
      failureToken: d.failureToken ?? d.details?.failureToken ?? null,
      source: "ledger",
    });
  }

  // State checks only enrich or fill legacy gaps; never duplicate ledger attempts.
  for (const check of state?.checks ?? []) {
    const key = check.id ?? check.checkId ?? null;
    if (!key) continue;
    const identityKey = `${key}@@${check.details?.verificationCycle ?? "*"}`;
    if (ledgerIdentityKeys.has(identityKey) || ledgerIdentityKeys.has(`${key}@@*`)) continue;
    pushAttempt(key, {
      sequence: null,
      at: check.at ?? check.lastUpdatedAt ?? null,
      status: check.status,
      exitCode: check.exitCode ?? null,
      requirement: check.requirement ?? null,
      verificationCycle: check.details?.verificationCycle ?? null,
      provenance: check.provenance ?? null,
      executionMode: check.provenance === "ACTOR_REPORTED" || check.provenance === "MANUAL_OBSERVATION" ? "observed" : "executed",
      failureToken: check.details?.failureToken ?? null,
      source: "state-fallback",
    });
  }

  const checks = [];
  const MAX = Number.MAX_SAFE_INTEGER;
  for (const [id, attempts] of [...attemptsByCheck.entries()].sort(([a], [b]) => a.localeCompare(b))) {
    attempts.sort((a, b) =>
      ((a.verificationCycle ?? MAX) - (b.verificationCycle ?? MAX))
      || ((a.sequence ?? MAX) - (b.sequence ?? MAX)));
    checks.push({
      id,
      requirement: attempts.findLast((a) => a.requirement)?.requirement ?? null,
      attemptCount: attempts.length,
      failedAttempts: attempts.filter((a) => a.status === "failed" || a.status === "blocked").length,
      currentResult: attempts.at(-1)?.status ?? null,
      attempts,
    });
  }
  return checks;
}

function structuredDiagnostics(events) {
  const cases = [];
  const interventions = [];
  const dispositions = [];
  const invalidRevisions = [];
  const lastCaseByCycle = new Map();
  for (const event of events) {
    try {
      if (event.event === "DIAGNOSTIC_CASE_RECORDED") {
        assertDiagnosticCaseDetails(event.details);
        const cycle = event.details?.verificationCycle;
        const previous = lastCaseByCycle.get(cycle);
        if (Number.isInteger(event.details?.diagnosticRevision) && event.details.diagnosticRevision > 1 && previous) {
          if (event.details.previousDiagnosticFingerprint !== previous.diagnosticFingerprint) {
            invalidRevisions.push({
              sequence: event.seq,
              verificationCycle: cycle,
              code: "E_DIAGNOSTIC_CASE_INVALID",
              message: "Revision chain broken: previousDiagnosticFingerprint does not match the prior case fingerprint.",
            });
            continue;
          }
        }
        lastCaseByCycle.set(cycle, event.details);
        cases.push({ sequence: event.seq, at: event.at, ...event.details });
      } else if (event.event === "INTERVENTION_RECORDED") {
        assertInterventionDetails(event.details);
        interventions.push({ sequence: event.seq, at: event.at, ...event.details });
      } else if (event.event === "HYPOTHESIS_DISPOSITION_RECORDED") {
        assertHypothesisDispositionDetails(event.details);
        dispositions.push({ sequence: event.seq, at: event.at, ...event.details });
      }
    } catch {
      // Invalid diagnostic details surface through ledger integrity errors;
      // projections must not crash on them.
    }
  }
  return { cases, interventions, dispositions, invalidRevisions };
}

export function timestampQuality(event) {
  if (typeof event?.at === "string" && !Number.isNaN(Date.parse(event.at))) return "authoritative";
  return "unknown";
}

export async function buildTrajectoryMetrics(options) {
  const { target, packageRoot, taskId } = options;
  return withNativeReadScope(target, () => {
    if (getOperationalStore(target)) {
      return withEventLedgerAudit(target, packageRoot, { taskId }, () => projectTrajectoryMetrics(options));
    }
    return projectTrajectoryMetrics(options);
  });
}

function authorityFileName(authorityRef) {
  if (typeof authorityRef !== "string" || authorityRef.trim() === "") return null;
  const ref = authorityRef.trim();
  if (ref === "." || ref === ".." || ref.includes("/") || ref.includes("\\")) return null;
  return ref.endsWith(".json") ? ref : `${ref}.json`;
}

function authoritySourceOptions(options = {}) {
  const context = resolveAuthorityContext(options);
  const contextProvided = hasAuthorityContext(options);
  const directFile = configuredValue(options.trustedAuthorityFile);
  const directDir = configuredValue(options.trustedAuthorityDir);
  const contextFile = configuredValue(context.trustedAuthorityFile);
  const contextDir = configuredValue(context.trustedAuthorityDir);
  const file = contextFile ?? (contextProvided ? null : directFile);
  const dir = contextDir ?? (contextProvided ? null : directDir);
  const authorities = context.authorities ?? (contextProvided ? undefined : options.authorities);
  const authority = context.authority ?? (contextProvided ? undefined : options.authority);

  if (contextProvided
    && context.trustMode !== "HOST_ATTESTED"
    && !file
    && !dir
    && authorities === undefined
    && authority === undefined) {
    const envFile = configuredValue(process.env[AUTHORITY_FILE_ENV]);
    const envDir = configuredValue(process.env[AUTHORITY_DIR_ENV]);
    return {
      context,
      file: envFile,
      dir: envDir,
      authorities: undefined,
      authority: undefined,
      sourceConfigured: Boolean(envFile || envDir),
      sourceType: envFile ? "external-file" : envDir ? "external-dir" : null,
    };
  }

  if (context.trustMode === "HOST_ATTESTED" || contextProvided || file || dir || authorities !== undefined || authority !== undefined) {
    return {
      context,
      file,
      dir,
      authorities,
      authority,
      sourceConfigured: Boolean(file || dir || authorities !== undefined || authority !== undefined),
      sourceType: file ? "external-file" : dir ? "external-dir" : authorities !== undefined || authority !== undefined ? "in-memory" : null,
    };
  }

  const envFile = configuredValue(process.env[AUTHORITY_FILE_ENV]);
  const envDir = configuredValue(process.env[AUTHORITY_DIR_ENV]);
  return {
    context,
    file: envFile,
    dir: envDir,
    authorities: undefined,
    authority: undefined,
    sourceConfigured: Boolean(envFile || envDir),
    sourceType: envFile ? "external-file" : envDir ? "external-dir" : null,
  };
}

function configuredValue(value) {
  return typeof value === "string" && value.trim() !== "" ? value.trim() : null;
}

function findAuthority(value, authorityRef) {
  if (value && typeof value === "object" && !Array.isArray(value)) {
    const keyedAuthority = value[authorityRef];
    if (keyedAuthority && typeof keyedAuthority === "object") return keyedAuthority;
  }
  const envelope = value && typeof value === "object" && !Array.isArray(value)
    && Array.isArray(value.authorities)
    ? value
    : null;
  const grants = grantsFromValue(value);
  if (!grants) return null;
  const authority = grants.find((item) => item?.authorityId === authorityRef || item?.id === authorityRef) ?? null;
  if (!authority || !envelope) return authority;
  return {
    ...authority,
    schemaVersion: envelope.schemaVersion,
    protocolVersion: envelope.protocolVersion,
  };
}

function findInMemoryAuthority(authorities, authority, authorityRef) {
  if (authority !== undefined) {
    return authority?.authorityId === authorityRef || authority?.id === authorityRef ? authority : null;
  }
  if (authorities !== undefined) {
    return findAuthority(authorities, authorityRef);
  }
  return undefined;
}

function grantsFromValue(value) {
  if (Array.isArray(value)) return value;
  if (value && typeof value === "object" && Array.isArray(value.authorities)) {
    if (value.schemaVersion !== 1 || value.protocolVersion !== 1) return null;
    return value.authorities;
  }
  return value && typeof value === "object" ? [value] : null;
}

function invalid(message, details = {}) {
  return {
    trusted: false,
    error: { code: E_AUTHORITY_INVALID, message },
    ...details,
  };
}

function isInsideTarget(target, candidate) {
  if (!target) return false;
  // Check both lexical paths and their real paths. The lexical check rejects
  // actor-created symlinks inside the target that point at an external file.
  return isWithin(path.resolve(target), path.resolve(candidate))
    || isWithin(resolvedPath(target), resolvedPath(candidate));
}

function isWithin(parent, candidate) {
  const relative = path.relative(parent, candidate);
  return relative === ""
    || (!relative.startsWith(`..${path.sep}`) && relative !== ".." && !path.isAbsolute(relative));
}

function projectLocalAuthorityExists(authorityRef, target) {
  const fileName = authorityFileName(authorityRef);
  if (!fileName || !target) return false;
  const localPath = path.join(target, ".forgeloop", "authorities", fileName);
  try {
    accessSync(localPath, fsConstants.F_OK);
    return true;
  } catch (error) {
    if (error.code === "ENOENT") return false;
    return true;
  }
}

function readExternalJson(candidate, target, kind) {
  if (isInsideTarget(target, candidate)) {
    return untrusted(`Configured trusted authority ${kind} must be outside the actor-writable target`);
  }

  try {
    accessSync(candidate, fsConstants.R_OK);
    const info = lstatSync(candidate);
    if (kind === "file" && !info.isFile()) {
      return invalid("Configured trusted authority file is not a regular file");
    }
    if (kind === "directory" && !info.isDirectory()) {
      return invalid("Configured trusted authority directory is not a directory");
    }
    const bytes = readFileSync(candidate);
    assertJsonBytes(bytes, `trusted authority ${kind}`);
    const value = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(value, `trusted authority ${kind}`);
    return { value };
  } catch {
    return invalid(`Configured trusted authority ${kind} could not be read or parsed`);
  }
}

function resolveFromExternalDirectory(authorityRef, target, dir) {
  const fileName = authorityFileName(authorityRef);
  if (!fileName) return invalid("Installation authority reference must be a simple authority ID");
  if (isInsideTarget(target, dir)) {
    return untrusted("Configured trusted authority directory must be outside the actor-writable target");
  }
  try {
    accessSync(dir, fsConstants.R_OK);
    if (!lstatSync(dir).isDirectory()) {
      return invalid("Configured trusted authority directory is not a directory");
    }
  } catch {
    return invalid("Configured trusted authority directory could not be read");
  }
  const authorityPath = path.join(dir, fileName);
  const read = readExternalJson(authorityPath, target, "file");
  if (read.error) return read;
  const authority = findAuthority(read.value, authorityRef);
  return authority
    ? { trusted: true, authority, sourceType: "external-dir" }
    : invalid(`Referenced installation authority '${authorityRef}' does not match the trusted authority file`);
}

function resolveFromExternalFile(authorityRef, target, file) {
  const read = readExternalJson(file, target, "file");
  if (read.error) return read;
  const authority = findAuthority(read.value, authorityRef);
  return authority
    ? { trusted: true, authority, sourceType: "external-file" }
    : invalid(`Referenced installation authority '${authorityRef}' was not found in the trusted authority file`);
}

export function resolveTrustedAuthority({
  authorityRef,
  target,
  trustedAuthorityFile,
  trustedAuthorityDir,
  authorities,
  authority,
  authorityContext,
  runtimeContext,
} = {}) {
  const fileName = authorityFileName(authorityRef);
  if (!fileName) return invalid("Installation authority reference must be a simple authority ID");

  const sources = authoritySourceOptions({
    trustedAuthorityFile,
    trustedAuthorityDir,
    authorities,
    authority,
    authorityContext,
    runtimeContext,
  });
  if (sources.sourceConfigured && sources.context.trustMode !== "HOST_ATTESTED") {
    return untrusted("Standalone configuration selects an authority source but does not attest host authority");
  }
  if ((sources.file || sources.dir) && !target) {
    return untrusted("A target path is required to validate trusted authority provenance");
  }
  if (sources.file) return resolveFromExternalFile(authorityRef, target, sources.file);
  if (sources.dir) return resolveFromExternalDirectory(authorityRef, target, sources.dir);

  // In-memory authorities are a host-injected policy interface. They never
  // originate from project-local files and are intentionally resolved only
  // after the explicit external sources above.
  const inMemory = findInMemoryAuthority(sources.authorities, sources.authority, authorityRef);
  if (inMemory !== undefined) {
    return inMemory
      ? { trusted: true, authority: inMemory, sourceType: "in-memory" }
      : invalid(`Referenced installation authority '${authorityRef}' could not be resolved`);
  }

  if (projectLocalAuthorityExists(authorityRef, target)) {
    return untrusted("Project-local authority artifacts are references only and are not trusted authority sources");
  }
  return invalid(`Referenced installation authority '${authorityRef}' could not be resolved`, {
    sourceConfigured: sources.sourceConfigured,
  });
}

function resolvedPath(candidate) {
  const absolute = path.resolve(candidate);
  const missingSegments = [];
  let current = absolute;
  while (true) {
    try {
      const existing = realpathSync(current);
      return path.resolve(existing, ...missingSegments);
    } catch (error) {
      if (error.code !== "ENOENT") throw error;
      const parent = path.dirname(current);
      if (parent === current) return absolute;
      missingSegments.unshift(path.basename(current));
      current = parent;
    }
  }
}

export function trustedAuthorityConfiguration(options = {}) {
  const { context, sourceConfigured, sourceType, file, dir } = authoritySourceOptions(options);
  const sourceInsideTarget = options.target && (file || dir)
    ? isInsideTarget(options.target, file ?? dir)
    : false;
  return {
    sourceConfigured,
    sourceType,
    trustMode: context.trustMode,
    trusted: context.trustMode === "HOST_ATTESTED" && sourceConfigured && !sourceInsideTarget,
  };
}

function untrusted(message) {
  return {
    trusted: false,
    error: { code: E_AUTHORITY_UNTRUSTED_SOURCE, message },
  };
}

export function createUsageArtifact({ taskId, usage = {}, recordedAt = new Date().toISOString() } = {}) {
  if (typeof taskId !== "string" || !taskId) throw usageError("E_USAGE_INVALID", "taskId is required for usage telemetry");
  if (typeof recordedAt !== "string" || !recordedAt.trim() || Number.isNaN(Date.parse(recordedAt))) {
    throw usageError("E_USAGE_INVALID", "recordedAt must be a valid timestamp");
  }
  return {
    schemaVersion: 1,
    protocolVersion: 1,
    taskId,
    recordedAt,
    usage: normalizeUsage(usage),
  };
}

export function unknownUsage() {
  return {
    inputTokens: null,
    outputTokens: null,
    cacheReadTokens: null,
    cacheWriteTokens: null,
    totalTokens: null,
    costUsd: null,
    model: null,
    provider: null,
    source: "UNKNOWN",
  };
}

function assertIsolationMetadataConsistency(isolation) {
  if (isolation.mode === "NATIVE_PROJECT") {
    if (
      isolation.isolated !== false
      || isolation.liveProjectWritable !== true
    ) {
      throw executionError(
        E_VERIFICATION_EXECUTION_INVALID,
        "NATIVE_PROJECT must report isolated=false and liveProjectWritable=true",
      );
    }
    return;
  }

  if (
    isolation.isolated !== true
    || isolation.liveProjectWritable !== false
  ) {
    throw executionError(
      E_VERIFICATION_EXECUTION_INVALID,
      `${isolation.mode} must report isolated=true and liveProjectWritable=false`,
    );
  }

  if (
    isolation.mode === "SYSTEM_ISOLATED"
    && isolation.networkPolicy !== "DENIED"
  ) {
    throw executionError(
      E_VERIFICATION_EXECUTION_INVALID,
      "SYSTEM_ISOLATED must report networkPolicy=DENIED",
    );
  }
}

export function assertVerificationIsolation(result, policy) {
  const requiredIsolation = normalizeVerificationExecutionPolicy(policy).requiredIsolation;
  if (!satisfiesIsolationPolicy(result.isolation, requiredIsolation)) {
    throw executionError(
      E_VERIFICATION_ISOLATION_UNAVAILABLE,
      `Verification execution did not satisfy the required ${requiredIsolation} isolation boundary`,
    );
  }
  return result;
}

export async function executeVerificationProcess({
  argv,
  protocolProjectRoot,
  taskId,
  checkId,
  requirement,
  resolution,
  timeoutMs,
  runtimeContext,
  nativeExecute,
}) {
  const policy = normalizeVerificationExecutionPolicy(runtimeContext?.verificationExecutionPolicy);
  const adapter = readAdapter(runtimeContext);
  let rawResult;
  if (adapter) {
    try {
      rawResult = await adapter.execute(Object.freeze({
        argv: [...argv],
        protocolProjectRoot,
        taskId,
        checkId,
        requirement,
        timeoutMs,
        resolution,
      }));
    } catch (error) {
      if (error?.code === E_VERIFICATION_ISOLATION_UNAVAILABLE) throw error;
      throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution adapter failed");
    }
  } else {
    if (policy.requiredIsolation !== "NONE") {
      throw executionError(
        E_VERIFICATION_ISOLATION_UNAVAILABLE,
        `Verification execution requires ${policy.requiredIsolation}, but no trusted adapter was supplied`,
      );
    }
    const nativeResult = await nativeExecute(argv, protocolProjectRoot, { timeoutMs });
    rawResult = {
      ...nativeResult,
      cwd: protocolProjectRoot,
      isolation: {
        mode: "NATIVE_PROJECT",
        isolated: false,
        liveProjectWritable: true,
        networkPolicy: "INHERITED",
        environmentPolicy: "INHERITED",
      },
    };
  }

  const normalized = normalizeVerificationExecutionResult(rawResult, { defaultCwd: protocolProjectRoot });
  if (
    policy.requiredIsolation !== "NONE"
    && normalized.isolation.mode !== "NATIVE_PROJECT"
    && normalized.cwd === protocolProjectRoot
  ) {
    throw executionError(
      E_VERIFICATION_EXECUTION_INVALID,
      "Isolated verification execution must use a cwd separate from the protocol project root",
    );
  }
  return assertVerificationIsolation(normalized, policy);
}

function executionError(code, message) {
  const error = new Error(message);
  error.code = code;
  return error;
}

function isRecord(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

export function isVerificationExecutionAdapter(value) {
  return isRecord(value) && typeof value.execute === "function";
}

function nonNegativeInteger(value, field, fallback) {
  const resolved = value === undefined ? fallback : value;
  if (!Number.isInteger(resolved) || resolved < 0) {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, `Verification execution ${field} must be a non-negative integer`);
  }
  return resolved;
}

function normalizeIsolation(value) {
  if (!isRecord(value)) {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution isolation metadata is missing");
  }
  const mode = value.mode;
  if (!VERIFICATION_ISOLATION_MODES.includes(mode)) {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution isolation mode is unsupported");
  }
  if (typeof value.isolated !== "boolean" || typeof value.liveProjectWritable !== "boolean") {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution isolation booleans are invalid");
  }
  const isolation = {
    mode,
    isolated: value.isolated,
    liveProjectWritable: value.liveProjectWritable,
    networkPolicy: requiredString(value.networkPolicy, "networkPolicy"),
    environmentPolicy: requiredString(value.environmentPolicy, "environmentPolicy"),
  };
  assertIsolationMetadataConsistency(isolation);
  return isolation;
}

export function normalizeVerificationExecutionPolicy(policy = {}) {
  if (policy === undefined || policy === null) return Object.freeze({ requiredIsolation: "NONE" });
  if (!isRecord(policy)) {
    throw executionError(E_VERIFICATION_ISOLATION_UNAVAILABLE, "Verification execution isolation policy is invalid");
  }
  const requiredIsolation = policy.requiredIsolation ?? "NONE";
  if (!VERIFICATION_EXECUTION_POLICY_MODES.includes(requiredIsolation)) {
    throw executionError(E_VERIFICATION_ISOLATION_UNAVAILABLE, "Verification execution isolation policy is unsupported");
  }
  return Object.freeze({ requiredIsolation });
}

export function normalizeVerificationExecutionResult(value, { defaultCwd = null } = {}) {
  if (!isRecord(value)) {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution adapter returned an invalid result");
  }
  const cwd = value.cwd ?? defaultCwd;
  requiredString(cwd, "cwd");
  if (value.exitCode !== null && !Number.isInteger(value.exitCode)) {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution exitCode must be an integer or null");
  }
  const signal = nullableString(value.signal ?? null, "signal");
  if (typeof value.timedOut !== "boolean") {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution timedOut must be boolean");
  }
  if (typeof value.outputTruncated !== "boolean") {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, "Verification execution outputTruncated must be boolean");
  }
  const stdout = outputBytes(value.stdout, "stdout");
  const stderr = outputBytes(value.stderr, "stderr");
  return {
    exitCode: value.exitCode,
    signal,
    timedOut: value.timedOut,
    stdout,
    stderr,
    stdoutBytes: nonNegativeInteger(value.stdoutBytes, "stdoutBytes", stdout.length),
    stderrBytes: nonNegativeInteger(value.stderrBytes, "stderrBytes", stderr.length),
    outputTruncated: value.outputTruncated,
    spawnError: Boolean(value.spawnError),
    cwd,
    isolation: normalizeIsolation(value.isolation),
  };
}

function nullableString(value, field) {
  if (value !== null && typeof value !== "string") {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, `Verification execution ${field} must be a string or null`);
  }
  return value;
}

function outputBytes(value, field) {
  if (value === undefined || value === null) return Buffer.alloc(0);
  if (typeof value === "string") return Buffer.from(value, "utf8");
  if (Buffer.isBuffer(value) || value instanceof Uint8Array) return Buffer.from(value);
  throw executionError(E_VERIFICATION_EXECUTION_INVALID, `Verification execution ${field} must be text or bytes`);
}

function readAdapter(runtimeContext) {
  const value = isRecord(runtimeContext) ? runtimeContext.verificationExecutionAdapter : undefined;
  if (value === undefined || value === null) return null;
  if (!isVerificationExecutionAdapter(value)) {
    throw executionError(E_VERIFICATION_ISOLATION_UNAVAILABLE, "Verification execution adapter is unavailable or invalid");
  }
  return value;
}

function requiredString(value, field) {
  if (typeof value !== "string" || value.trim() === "") {
    throw executionError(E_VERIFICATION_EXECUTION_INVALID, `Verification execution ${field} must be a non-empty string`);
  }
  return value;
}

function satisfiesIsolationPolicy(isolation, requiredIsolation) {
  if (requiredIsolation === "NONE") return true;
  if (ISOLATION_RANK[isolation.mode] < ISOLATION_RANK[requiredIsolation]) return false;
  if (requiredIsolation === "NATIVE_PROJECT") return true;
  return isolation.isolated === true
    && isolation.liveProjectWritable === false
    && (requiredIsolation !== "SYSTEM_ISOLATED" || isolation.networkPolicy === "DENIED");
}

export function normalizeVerificationConfiguration(value, label = "verification") {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw capabilityError(`${label} must be an object`);
  }
  const unexpected = Object.keys(value).find((key) => key !== "checkers");
  if (unexpected) throw capabilityError(`${label} contains unknown property: ${unexpected}`);
  return {
    checkers: normalizeScopedCheckerDescriptors(value.checkers ?? [], `${label}.checkers`),
  };
}

export function scopedCheckerCapabilitiesFingerprint(checkers = []) {
  return canonicalFingerprint({
    schemaVersion: 1,
    scopeMode: SCOPED_CHECKER_SCOPE_MODE,
    checkers: normalizeScopedCheckerDescriptors(checkers),
  });
}

async function currentChangedPathsFromRevisionProvider(target) {
  try {
    const provider = await resolveRevisionProvider({ target, registry: REVISION_PROVIDERS });
    const entries = await provider.getChangedEntries({ target, headRevision: "WORKTREE" });
    return [...new Set(entries
      .flatMap((entry) => [entry.path, entry.sourcePath].filter(Boolean)))].sort((left, right) => left.localeCompare(right));
  } catch {
    return null;
  }
}

export async function readVerificationScope(target, { taskId, packageRoot = getPackageRoot(), scopePath = null } = {}) {
  return withNativeReadScope(target, async () => {
    const relativePath = scopePath ?? taskVerificationScopePath(taskId);
    if (!(operationalArtifactExists(target, relativePath) ?? await fileExists(ensureWithin(target, relativePath)))) {
      throw scopeError("E_VERIFICATION_SCOPE_INVALID", `Verification scope is missing: ${relativePath}`, [relativePath]);
    }
    try {
      const artifact = await readJsonArtifact(target, relativePath, "verification-scope", packageRoot);
      return { ...artifact, value: await validateVerificationScope(artifact.value, packageRoot) };
    } catch (error) {
      if (error.code === "E_VERIFICATION_SCOPE_INVALID") throw error;
      throw scopeError("E_VERIFICATION_SCOPE_INVALID", error.message, [relativePath]);
    }
  });
}

function scopeError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "VerificationScopeError";
  error.code = code;
  error.artifacts = artifacts;
  return error;
}

function sortedPaths(paths, label = "paths") {
  if (!Array.isArray(paths)) throw scopeError("E_VERIFICATION_SCOPE_INVALID", `${label} must be an array`);
  return [...new Set(paths.map((value, index) => normalizeScopePath(value, `${label}[${index}]`)))].sort();
}

export async function validateVerificationScope(scope, packageRoot = getPackageRoot()) {
  try {
    assertSchema(scope, await readSchema("verification-scope", packageRoot), "verification scope");
  } catch (error) {
    throw scopeError("E_VERIFICATION_SCOPE_INVALID", error.message);
  }
  if (scope.taskId.length === 0 || scope.requestedMode === "IMPACTED" || scope.resolvedMode === "IMPACTED") {
    throw scopeError("E_VERIFICATION_SCOPE_INVALID", "IMPACTED is reserved for an explicit future mapping capability");
  }
  const canonical = {
    ...scope,
    changedPaths: sortedPaths(scope.changedPaths),
    claimedPaths: sortedPaths(scope.claimedPaths),
    selectedPaths: sortedPaths(scope.selectedPaths),
    reasons: [...scope.reasons],
  };
  return canonical;
}

function assertFingerprint(value, label) {
  if (typeof value !== "string" || !/^[a-f0-9]{64}$/.test(value)) {
    throw new WorkStateError(`${label} must be a lowercase SHA-256 fingerprint`);
  }
}

function assertStringArray(value, label) {
  if (!Array.isArray(value) || value.some((item) => typeof item !== "string" || !item)) {
    throw new WorkStateError(`${label} must be an array of non-empty strings`);
  }
}

export function assertWorkStateSemantics(state) {
  if (!state || typeof state !== "object" || Array.isArray(state)) {
    throw new WorkStateError("Work state must be a JSON object");
  }
  if (state.schemaVersion !== 1 || state.protocolVersion !== PROTOCOL_VERSION) {
    throw new WorkStateError("Unsupported work-state protocol version");
  }
  if (typeof state.taskId !== "string" || !state.taskId) {
    throw new WorkStateError("Work state taskId is required");
  }
  assertFingerprint(state.contractFingerprint, "contractFingerprint");
  if (state.routeFingerprint !== undefined) assertFingerprint(state.routeFingerprint, "routeFingerprint");
  if (!state.repositoryFingerprint || typeof state.repositoryFingerprint !== "object" || Array.isArray(state.repositoryFingerprint)) {
    throw new WorkStateError("repositoryFingerprint is required");
  }
  for (const key of ["branch", "head"]) {
    if (state.repositoryFingerprint[key] !== null && typeof state.repositoryFingerprint[key] !== "string") {
      throw new WorkStateError(`repositoryFingerprint.${key} must be a string or null`);
    }
  }
  assertWorkPhase(state.phase);
  assertStringArray(state.selectedGuides, "selectedGuides");
  if (state.selectedGuides.some((guide) => !GUIDE_IDS.includes(guide))) {
    throw new WorkStateError("Work state contains an unknown guide");
  }
  if (new Set(state.selectedGuides).size !== state.selectedGuides.length) {
    throw new WorkStateError("selectedGuides must not contain duplicates");
  }
  for (const key of ["requiredGates", "satisfiedGates"]) {
    if (state[key] !== undefined) {
      assertStringArray(state[key], key);
      if (new Set(state[key]).size !== state[key].length) {
        throw new WorkStateError(`${key} must not contain duplicates`);
      }
    }
  }
  if (state.satisfiedGates?.some((gate) => !state.requiredGates?.includes(gate))) {
    throw new WorkStateError("satisfiedGates must be a subset of requiredGates");
  }
  if (state.complianceMode !== undefined && !["advisory", "standard", "strict"].includes(state.complianceMode)) {
    throw new WorkStateError(`Unknown compliance mode: ${state.complianceMode}`);
  }
  if (state.publicationStatus !== undefined
    && !["not-published", "local-only", "committed", "pushed", "published", "deployed"].includes(state.publicationStatus)) {
    throw new WorkStateError(`Unknown publication status: ${state.publicationStatus}`);
  }
  if (state.evidenceCoverage !== undefined && !Array.isArray(state.evidenceCoverage)) {
    throw new WorkStateError("evidenceCoverage must be an array");
  }
  if (state.evidenceCoverage !== undefined) {
    try {
      assertCoverageList(state.evidenceCoverage);
    } catch (error) {
      throw new WorkStateError(error.message);
    }
  }
  assertStringArray(state.completedSteps, "completedSteps");
  assertStringArray(state.pendingSteps, "pendingSteps");
  normalizeRequiredArtifacts(state.requiredArtifacts);
  for (const key of ["checks", "failures", "blockers", "verificationEvidence"]) {
    if (!Array.isArray(state[key])) throw new WorkStateError(`${key} must be an array`);
  }
  if (state.phase === "COMPLETE" && state.verificationEvidence.length === 0) {
    throw new WorkStateError("COMPLETE requires verification evidence");
  }
  if (state.phase === "COMPLETE" && state.evidenceCoverage?.some((item) => item.status !== "COVERED")) {
    throw new WorkStateError("COMPLETE requires covered evidence for every recorded criterion");
  }
  if (state.phase === "BLOCKED" && state.blockers.length === 0) {
    throw new WorkStateError("BLOCKED requires a blocker");
  }
  if (state.phase === "CORRECTING" && (typeof state.diagnosedHypothesis !== "string" || !state.diagnosedHypothesis)) {
    throw new WorkStateError("CORRECTING requires a diagnosed hypothesis");
  }
  if (state.previousPhase !== undefined) {
    if (!isValidTransition(state.previousPhase, state.phase)) {
      throw new WorkStateError(`Invalid work-state transition: ${state.previousPhase} -> ${state.phase}`);
    }
  }
  if (state.verificationCycle !== undefined && (!Number.isInteger(state.verificationCycle) || state.verificationCycle < 1)) {
    throw new WorkStateError("verificationCycle must be a positive integer");
  }
  if (state.revision !== undefined && (!Number.isInteger(state.revision) || state.revision < 0)) {
    throw new WorkStateError("revision must be a non-negative integer");
  }
  if (state.lastCompletionAttempt !== undefined) {
    if (!state.lastCompletionAttempt || typeof state.lastCompletionAttempt !== "object" || Array.isArray(state.lastCompletionAttempt)) {
      throw new WorkStateError("lastCompletionAttempt must be an object");
    }
    if (state.lastCompletionAttempt.status !== "REJECTED") {
      throw new WorkStateError("lastCompletionAttempt.status must be REJECTED");
    }
    if (!Array.isArray(state.lastCompletionAttempt.reasonCodes)
      || state.lastCompletionAttempt.reasonCodes.some((code) => typeof code !== "string" || !code.trim())) {
      throw new WorkStateError("lastCompletionAttempt.reasonCodes must be an array of non-empty strings");
    }
    if (!Array.isArray(state.lastCompletionAttempt.missingRequirementIds)
      || state.lastCompletionAttempt.missingRequirementIds.some((id) => typeof id !== "string" || !id.trim())) {
      throw new WorkStateError("lastCompletionAttempt.missingRequirementIds must be an array of non-empty strings");
    }
    if (!Number.isInteger(state.lastCompletionAttempt.verificationCycle) || state.lastCompletionAttempt.verificationCycle < 1) {
      throw new WorkStateError("lastCompletionAttempt.verificationCycle must be a positive integer");
    }
    if (typeof state.lastCompletionAttempt.timestamp !== "string" || !state.lastCompletionAttempt.timestamp.trim()) {
      throw new WorkStateError("lastCompletionAttempt.timestamp must be a non-empty string");
    }
  }
  for (const failure of state.failures) {
    if (failure?.failureClass !== undefined) assertFailureClass(failure.failureClass);
  }
  assertSecretFree(state);
  return state;
}

export async function classifyLoadedWorkState({ target, state, contractFile = null, maxAgeMs } = {}) {
  const repository = await currentRepositoryFingerprint(target);

  let contract = null;
  let contractError = null;
  if (contractFile) {
    try {
      contract = await readContractFingerprint(target, contractFile);
    } catch (error) {
      if (error?.code === "E_STATE_REVISION_CONFLICT") throw error;
      contractError = error.message;
    }
  }

  let currentArtifacts;
  let artifactError = null;
  if ((state.requiredArtifacts ?? []).length > 0) {
    try {
      currentArtifacts = await readRequiredArtifactFingerprints(target, state.requiredArtifacts);
    } catch (error) {
      if (error?.code === "E_STATE_REVISION_CONFLICT") throw error;
      artifactError = error.message;
    }
  } else {
    currentArtifacts = [];
  }

  const classification = classifyWorkState(state, {
    repositoryFingerprint: repository,
    contractFingerprint: contract?.fingerprint,
    requiredArtifacts: currentArtifacts,
    maxAgeMs,
  });
  if (contractError) {
    classification.contractComparison = "INVALID";
    classification.reasons = classification.reasons.filter((reason) => reason !== "CONTRACT_NOT_VERIFIED");
    classification.reasons.push("CONTRACT_INVALID");
  }
  if (artifactError) {
    classification.artifactComparison = "NOT_VERIFIED";
    classification.reasons.push("REQUIRED_ARTIFACTS_NOT_VERIFIED");
  }
  classification.reasons = [...new Set(classification.reasons)];
  return {
    ...classification,
    repository,
    error: contractError ?? artifactError,
    contract: {
      path: contractFile,
      status: contractError ? "INVALID" : contract ? "OBSERVED" : "NOT_VERIFIED",
    },
    evidence: [
      createEvidence({
        kind: classification.repositoryComparison === "NOT_VERIFIED" ? "NOT_VERIFIED" : "OBSERVED",
        source: "repository fingerprint",
        result: classification.repositoryComparison,
      }),
      createEvidence({
        kind: classification.contractComparison === "NOT_VERIFIED" ? "NOT_VERIFIED" : "OBSERVED",
        source: contractFile ?? "current contract",
        result: classification.contractComparison,
      }),
      ...(classification.artifactComparison !== "NOT_APPLICABLE"
        ? [createEvidence({
          kind: classification.artifactComparison === "NOT_VERIFIED" ? "NOT_VERIFIED" : "OBSERVED",
          source: "required artifacts",
          result: classification.artifactComparison,
        })]
        : []),
    ],
  };
}

export function classifyWorkState(state, currentInput = {}) {
  if (!state) return { status: "ABSENT", reasons: ["NO_CHECKPOINT"] };
  const current = normalizeClassificationInput(currentInput);
  const reasons = [];
  const warnings = [];
  const saved = state.repositoryFingerprint;
  const repositoryFingerprint = current.repositoryFingerprint ?? { branch: null, head: null };
  const repositoryUnavailable = saved.branch === null
    && saved.head === null
    && repositoryFingerprint.branch === null
    && repositoryFingerprint.head === null;
  const repositoryComparison = repositoryUnavailable
    ? "NOT_VERIFIED"
    : saved.branch !== repositoryFingerprint.branch || saved.head !== repositoryFingerprint.head
      ? "MISMATCH"
      : "MATCH";
  if (repositoryComparison === "MISMATCH") {
    reasons.push("REPOSITORY_CHANGED");
  }

  let contractComparison = "NOT_VERIFIED";
  if (typeof current.contractFingerprint === "string") {
    contractComparison = state.contractFingerprint === current.contractFingerprint ? "MATCH" : "MISMATCH";
    if (contractComparison === "MISMATCH") reasons.push("CONTRACT_CHANGED");
  } else {
    reasons.push("CONTRACT_NOT_VERIFIED");
  }

  const savedArtifacts = normalizeRequiredArtifacts(state.requiredArtifacts);
  let artifactComparison = "NOT_APPLICABLE";
  if (savedArtifacts.length > 0) {
    if (!Array.isArray(current.requiredArtifacts)) {
      artifactComparison = "NOT_VERIFIED";
      reasons.push("REQUIRED_ARTIFACTS_NOT_VERIFIED");
    } else {
      const currentArtifacts = new Map(current.requiredArtifacts.map((artifact) => [artifact.path, artifact]));
      const missing = savedArtifacts.some((artifact) => !currentArtifacts.has(artifact.path)
        || currentArtifacts.get(artifact.path)?.sha256 === null
        || currentArtifacts.get(artifact.path)?.status === "missing");
      const changed = savedArtifacts.some((artifact) => currentArtifacts.get(artifact.path)?.sha256 !== artifact.sha256);
      if (missing) {
        artifactComparison = "MISSING";
        reasons.push("REQUIRED_ARTIFACT_MISSING");
      } else if (changed) {
        artifactComparison = "MISMATCH";
        reasons.push("REQUIRED_ARTIFACT_CHANGED");
      } else {
        artifactComparison = "MATCH";
      }
    }
  }

  const now = current.now ?? Date.now();
  const updatedAt = Date.parse(state.lastUpdated);
  let stateAgeMs = null;
  if (Number.isFinite(updatedAt) && Number.isFinite(now) && now >= updatedAt) {
    stateAgeMs = now - updatedAt;
    if (Number.isFinite(current.maxAgeMs) && current.maxAgeMs >= 0 && stateAgeMs > current.maxAgeMs) {
      warnings.push("CHECKPOINT_OLD");
    }
  }
  return {
    status: reasons.length > 0 ? "REVALIDATION_REQUIRED" : "FRESH",
    reasons,
    warnings,
    repositoryComparison,
    contractComparison,
    artifactComparison,
    stateAgeMs,
    state,
  };
}

export function createWorkState(input) {
  assertSecretFree(input);
  const state = {
    schemaVersion: 1,
    protocolVersion: PROTOCOL_VERSION,
    taskId: input.taskId,
    contractFingerprint: input.contractFingerprint,
    ...(input.routeFingerprint !== undefined ? { routeFingerprint: input.routeFingerprint } : {}),
    repositoryFingerprint: input.repositoryFingerprint ?? { branch: null, head: null },
    phase: input.phase,
    selectedGuides: [...(input.selectedGuides ?? [])],
    ...(input.requiredGates !== undefined ? { requiredGates: [...input.requiredGates] } : {}),
    ...(input.satisfiedGates !== undefined ? { satisfiedGates: [...input.satisfiedGates] } : {}),
    ...(input.complianceMode !== undefined ? { complianceMode: input.complianceMode } : {}),
    ...(input.evidenceCoverage !== undefined ? { evidenceCoverage: [...input.evidenceCoverage] } : {}),
    ...(input.publicationStatus !== undefined ? { publicationStatus: input.publicationStatus } : {}),
    completedSteps: [...(input.completedSteps ?? [])],
    pendingSteps: [...(input.pendingSteps ?? [])],
    requiredArtifacts: normalizeRequiredArtifacts(input.requiredArtifacts),
    checks: [...(input.checks ?? [])],
    failures: [...(input.failures ?? [])],
    blockers: [...(input.blockers ?? [])],
    verificationEvidence: [...(input.verificationEvidence ?? [])],
    lastUpdated: input.lastUpdated ?? new Date().toISOString(),
    revision: input.revision ?? 0,
  };
  if (input.verificationCycle !== undefined) state.verificationCycle = input.verificationCycle;
  if (input.lastCompletionAttempt !== undefined) state.lastCompletionAttempt = structuredClone(input.lastCompletionAttempt);
  if (input.previousPhase !== undefined) state.previousPhase = input.previousPhase;
  if (input.diagnosedHypothesis !== undefined) state.diagnosedHypothesis = input.diagnosedHypothesis;
  return assertWorkStateSemantics(state);
}

function normalizeClassificationInput(currentInput = {}) {
  if (!currentInput || typeof currentInput !== "object" || Array.isArray(currentInput)) {
    return { repositoryFingerprint: { branch: null, head: null } };
  }
  const isOptions = Object.prototype.hasOwnProperty.call(currentInput, "repositoryFingerprint")
    || Object.prototype.hasOwnProperty.call(currentInput, "contractFingerprint")
    || Object.prototype.hasOwnProperty.call(currentInput, "requiredArtifacts")
    || Object.prototype.hasOwnProperty.call(currentInput, "maxAgeMs")
    || Object.prototype.hasOwnProperty.call(currentInput, "now");
  if (isOptions) {
    return {
      repositoryFingerprint: currentInput.repositoryFingerprint ?? { branch: null, head: null },
      contractFingerprint: currentInput.contractFingerprint,
      requiredArtifacts: currentInput.requiredArtifacts,
      maxAgeMs: currentInput.maxAgeMs,
      now: currentInput.now,
    };
  }
  return { repositoryFingerprint: currentInput };
}

function normalizeRequiredArtifacts(value) {
  if (value === undefined) return [];
  if (!Array.isArray(value)) throw new WorkStateError("requiredArtifacts must be an array");
  const artifacts = value.map((artifact) => {
    if (!artifact || typeof artifact !== "object" || Array.isArray(artifact)) {
      throw new WorkStateError("requiredArtifacts entries must be objects");
    }
    const normalized = {
      path: normalizeArtifactPath(artifact.path),
      sha256: artifact.sha256,
    };
    assertFingerprint(normalized.sha256, `requiredArtifacts.${normalized.path}.sha256`);
    return normalized;
  });
  if (new Set(artifacts.map((artifact) => artifact.path)).size !== artifacts.length) {
    throw new WorkStateError("requiredArtifacts must not contain duplicate paths");
  }
  return artifacts.sort((left, right) => left.path.localeCompare(right.path));
}

export async function readContractFingerprint(target, contractFile) {
  return withNativeReadScope(target, async () => {
    const operational = readOperationalText(target, contractFile);
    if (operational.selected) {
      if (operational.text === null) throw new WorkStateError(`Unable to parse contract ${contractFile}: artifact missing`);
      assertJsonBytes(operational.text, contractFile);
      return { path: contractFile, fingerprint: contractFingerprint(JSON.parse(operational.text)) };
    }
    await assertSafePath(target, contractFile);
    const contractPath = ensureWithin(target, contractFile);
    let contract;
    try {
      const bytes = await readBytes(contractPath);
      assertJsonBytes(bytes, contractFile);
      contract = JSON.parse(bytes.toString("utf8"));
    } catch (error) {
      throw new WorkStateError(`Unable to parse contract ${contractFile}: ${error.message}`);
    }
    return { path: contractFile, fingerprint: contractFingerprint(contract) };
  });
}

async function validateStoredState(state, packageRoot = getPackageRoot()) {
  const schema = await readSchema("work-state", packageRoot);
  assertSchema(state, schema, "work state");
  return assertWorkStateSemantics(state);
}

async function absoluteGitPath(target, value) {
  const candidate = path.isAbsolute(value) ? value : path.resolve(target, value);
  try {
    return normalizeIdentityPath(await realpath(candidate));
  } catch {
    return normalizeIdentityPath(candidate);
  }
}

export async function assertWorkspaceBinding(target, { taskId, packageRoot = getPackageRoot(), operation = "mutation" } = {}) {
  const result = await resolveWorkspaceBindingStatus(target, { taskId, packageRoot });
  if (result.status === "UNBOUND" || result.status === "MATCH") return result;
  const code = result.status === "MISMATCH"
    ? "E_WORKSPACE_BINDING_MISMATCH"
    : result.status === "UNAVAILABLE"
      ? "E_WORKSPACE_IDENTITY_UNAVAILABLE"
      : "E_WORKSPACE_BINDING_INVALID";
  const message = result.status === "MISMATCH"
    ? `Workspace binding does not match the current Git worktree before ${operation}`
    : result.status === "UNAVAILABLE"
      ? `Current Git worktree identity is unavailable before ${operation}`
      : `Workspace binding is invalid before ${operation}`;
  throw bindingError(code, message, [result.path]);
}

function bindingError(code, message, artifacts = []) {
  const error = new Error(message);
  error.name = "WorkspaceBindingError";
  error.code = code;
  if (artifacts.length > 0) error.artifacts = artifacts;
  return error;
}

export async function captureWorkspaceIdentity(target) {
  let metadata;
  try {
    metadata = await repositoryWorktreeMetadata(target);
  } catch (error) {
    throw bindingError(
      "E_WORKSPACE_IDENTITY_UNAVAILABLE",
      "The current directory is not a Git worktree whose identity ForgeLoop can prove",
      error?.artifacts ?? [],
    );
  }

  const commonDirectory = await absoluteGitPath(target, metadata.commonDirectory);
  const gitDirectory = await absoluteGitPath(target, metadata.gitDirectory);
  const topLevel = await absoluteGitPath(target, metadata.topLevel);
  const repositoryIdentity = canonicalFingerprint({
    commonDirectory,
    objectFormat: metadata.objectFormat,
  });
  const workspaceIdentity = canonicalFingerprint({
    commonDirectory,
    gitDirectory,
    topLevel,
    objectFormat: metadata.objectFormat,
  });
  const repositoryFingerprint = await currentRepositoryFingerprint(target);
  return {
    repositoryIdentity,
    workspaceIdentity,
    branchAtBind: repositoryFingerprint.branch,
    headAtBind: repositoryFingerprint.head,
    metadata: { objectFormat: metadata.objectFormat },
  };
}

function normalizeIdentityPath(value) {
  const normalized = path.normalize(value).replaceAll("\\", "/");
  return process.platform === "win32" ? normalized.toLowerCase() : normalized;
}

export async function resolveWorkspaceBindingStatus(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  const relativePath = taskWorkspaceBindingPath(taskId);
  let artifact;
  try {
    artifact = await readWorkspaceBinding(target, { taskId, packageRoot });
  } catch (error) {
    return {
      status: "INVALID",
      taskId,
      path: relativePath,
      binding: null,
      current: null,
      error: { code: error.code ?? "E_WORKSPACE_BINDING_INVALID", message: error.message },
    };
  }
  if (!artifact) return { status: "UNBOUND", taskId, path: relativePath, binding: null, current: null };

  let current;
  try {
    current = await captureWorkspaceIdentity(target);
  } catch (error) {
    return {
      status: "UNAVAILABLE",
      taskId,
      path: relativePath,
      binding: artifact.value,
      bindingFingerprint: artifact.fingerprint,
      current: null,
      error: { code: error.code ?? "E_WORKSPACE_IDENTITY_UNAVAILABLE", message: error.message },
    };
  }
  const matches = artifact.value.repositoryIdentity === current.repositoryIdentity
    && artifact.value.workspaceIdentity === current.workspaceIdentity;
  return {
    status: matches ? "MATCH" : "MISMATCH",
    taskId,
    path: relativePath,
    binding: artifact.value,
    bindingFingerprint: artifact.fingerprint,
    current,
  };
}

export async function validateWorkspaceBinding(binding, packageRoot = getPackageRoot()) {
  try {
    const schema = await readSchema("workspace-binding", packageRoot);
    assertSchema(binding, schema, "workspace binding");
  } catch (error) {
    throw bindingError("E_WORKSPACE_BINDING_INVALID", error.message);
  }
  if (!SHA256.test(binding.repositoryIdentity) || !SHA256.test(binding.workspaceIdentity)) {
    throw bindingError("E_WORKSPACE_BINDING_INVALID", "Workspace binding identities must be lowercase SHA-256 values");
  }
  assertSecretFree(binding);
  return binding;
}

export async function getPersistentTransportStatus(options = {}) {
  return getLifecycleStatus(options);
}

export function getPersistentTransportRoot({ homeDirectory = os.homedir() } = {}) {
  return path.join(homeDirectory, ".forgeloop", "persistent-search");
}

export async function getPersistentTransportStatus(options = {}) {
  const inspection = await inspectPersistentTransport(options);
  return {
    schemaVersion: 1,
    status: inspection.status,
    running: inspection.running,
    owned: inspection.owned,
    protocolVersion: inspection.state?.protocolVersion ?? null,
    forgeLoopVersion: inspection.state?.forgeLoopVersion ?? null,
  };
}

export async function inspectPersistentTransport({ homeDirectory = os.homedir(), processApi = process, processInspector = {} } = {}) {
  const paths = getPersistentTransportPaths({ homeDirectory });
  const { state, invalid } = await readPersistentTransportState(paths.statePath);
  if (invalid) return { status: "STALE", running: false, owned: false, paths, state: null, reason: "STATE_INVALID" };
  if (!state) return { status: "NOT_RUNNING", running: false, owned: false, paths, state: null };
  const ownership = await inspectPersistentTransportOwnership(state, { processApi, processInspector, expectedEndpoint: paths.endpoint });
  if (!ownership.running && ownership.reason === "PROCESS_EXITED") return { status: "STALE", running: false, owned: true, paths, state, reason: ownership.reason };
  if (!ownership.owned) return { status: "OWNERSHIP_UNVERIFIED", running: false, owned: false, paths, state, reason: ownership.reason };
  const packageVersion = await readPackageVersion();
  if (state.protocolVersion !== PERSISTENT_TRANSPORT_PROTOCOL_VERSION || (packageVersion && state.forgeLoopVersion !== packageVersion)) {
    return { status: "INCOMPATIBLE", running: true, owned: true, paths, state, reason: "VERSION_MISMATCH", packageVersion, ownershipMode: ownership.ownershipMode };
  }
  return { status: "READY", running: true, owned: true, paths, state, packageVersion, ownershipMode: ownership.ownershipMode };
}

async function readPackageVersion() {
  const packageJson = await readFile(path.join(getPackageRoot(), "package.json"), "utf8");
  return JSON.parse(packageJson).version ?? null;
}

function comparable(value) {
  if (process.platform !== "win32") return value;
  return value.toLowerCase().replaceAll("\\", "/");
}

async function endpointMatchesState(state, expectedEndpoint) {
  if (typeof expectedEndpoint === "string" && comparable(state.endpoint) !== comparable(expectedEndpoint)) return false;
  try {
    await endpointRequest(state);
    return true;
  } catch {
    return false;
  }
}

function endpointRequest(state, method = null, params = {}, timeoutMs = ENDPOINT_PROBE_TIMEOUT_MS) {
  return new Promise((resolve, reject) => {
    if (typeof state.endpoint !== "string" || state.endpoint.length === 0) {
      reject(persistentTransportError(PERSISTENT_TRANSPORT_ERROR_CODES.OWNERSHIP_UNVERIFIED, "Persistent search host endpoint is invalid"));
      return;
    }
    const socket = net.createConnection(state.endpoint);
    const decoder = new FrameDecoder({ maxFrameBytes: PERSISTENT_TRANSPORT_DEFAULTS.maxResponseFrameBytes });
    const handshakeRequest = createRequest("handshake", { scopeId: state.scopeId });
    let activeRequest = handshakeRequest;
    let handshakeResult = null;
    let settled = false;
    const timer = setTimeout(() => finish(reject, persistentTransportError(PERSISTENT_TRANSPORT_ERROR_CODES.TIMEOUT, "Timed out verifying the persistent search host endpoint")), timeoutMs);
    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      socket.off("data", onData);
      socket.off("error", onError);
      socket.off("end", onEnd);
      socket.destroy();
      fn(value);
    };
    const send = (request) => {
      activeRequest = request;
      try {
        socket.write(encodeFrame(request, { maxFrameBytes: PERSISTENT_TRANSPORT_DEFAULTS.maxRequestFrameBytes }));
      } catch (error) {
        finish(reject, error);
      }
    };
    const onData = (chunk) => {
      try {
        for (const frame of decoder.push(chunk)) {
          const response = validateResponse(parseFrame(frame), activeRequest.id);
          if (!response.ok) {
            finish(reject, persistentTransportError(response.error.code, response.error.message));
            return;
          }
          if (activeRequest === handshakeRequest) {
            handshakeResult = response.result;
            if (!handshakeResult || handshakeResult.pid !== state.pid
              || handshakeResult.nonce !== state.nonce
              || handshakeResult.scopeId !== state.scopeId
              || handshakeResult.protocolVersion !== state.protocolVersion
              || handshakeResult.forgeLoopVersion !== state.forgeLoopVersion) {
              finish(reject, persistentTransportError(PERSISTENT_TRANSPORT_ERROR_CODES.OWNERSHIP_UNVERIFIED, "Persistent search host endpoint identity does not match its state"));
              return;
            }
            if (method === null) {
              finish(resolve, response);
              return;
            }
            send(createRequest(method, params));
            continue;
          }
          finish(resolve, response);
          return;
        }
      } catch (error) {
        finish(reject, error);
      }
    };
    const onError = (cause) => finish(reject, persistentTransportError(PERSISTENT_TRANSPORT_ERROR_CODES.UNAVAILABLE, `Persistent search host endpoint failed: ${cause.code ?? cause.message}`));
    const onEnd = () => finish(reject, persistentTransportError(PERSISTENT_TRANSPORT_ERROR_CODES.UNAVAILABLE, "Persistent search host endpoint closed the connection"));
    socket.on("data", onData);
    socket.once("error", onError);
    socket.once("end", onEnd);
    socket.once("connect", () => {
      socket.setNoDelay?.(true);
      send(handshakeRequest);
    });
  });
}

function inspectCommandLineIdentity(state, commandLine) {
  const command = comparable(commandLine);
  const entrypoint = comparable(state.entrypoint);
  const scopeMarker = comparable(state.scopeId);
  const owned = command.includes(entrypoint) && command.includes("--persistent-transport-server") && command.includes(scopeMarker);
  return ownershipResult(state, owned, owned ? "PROCESS_COMMAND_LINE" : null);
}

async function inspectEndpointIdentity(state, expectedEndpoint) {
  const owned = await endpointMatchesState(state, expectedEndpoint);
  return ownershipResult(state, owned, owned ? "ENDPOINT_HANDSHAKE" : null);
}

export async function inspectPersistentTransportOwnership(state, {
  processApi = process,
  processInspector = {},
  expectedEndpoint = null,
} = {}) {
  if (!validPersistentTransportState(state)) {
    return { owned: false, running: false, reason: "STATE_INVALID" };
  }
  if (typeof expectedEndpoint === "string" && comparable(state.endpoint) !== comparable(expectedEndpoint)) {
    return { owned: false, running: false, reason: "STATE_ENDPOINT_MISMATCH" };
  }
  const alive = (processInspector.isAlive ?? ((pid) => processIsAlive(pid, processApi)))(state.pid);
  if (!alive) return { owned: true, running: false, reason: "PROCESS_EXITED", pid: state.pid };
  if (process.platform === "win32" && processInspector.commandLine === undefined) {
    return inspectEndpointIdentity(state, expectedEndpoint);
  }
  const commandLine = processInspector.commandLine === undefined
    ? await processCommandLine(state.pid, { platform: process.platform })
    : await processInspector.commandLine(state.pid);
  if (typeof commandLine !== "string" || commandLine.length === 0) {
    return inspectEndpointIdentity(state, expectedEndpoint);
  }
  return inspectCommandLineIdentity(state, commandLine);
}

function ownershipResult(state, owned, ownershipMode = null) {
  return {
    owned,
    running: owned,
    pid: state.pid,
    ownershipMode,
    reason: owned ? null : "PROCESS_IDENTITY_UNVERIFIED",
    commandLine: null,
  };
}

function validPersistentTransportState(state) {
  if (!state || state.schemaVersion !== 1) return false;
  if (!Number.isInteger(state.pid) || state.pid <= 0) return false;
  if (typeof state.nonce !== "string" || typeof state.scopeId !== "string") return false;
  if (typeof state.entrypoint !== "string") return false;
  return typeof state.endpoint === "string" && state.endpoint.length > 0;
}

export function getPersistentTransportPaths({ homeDirectory = os.homedir(), platform = process.platform } = {}) {
  const root = getPersistentTransportRoot({ homeDirectory });
  const scopeId = getPersistentTransportScopeId({ homeDirectory });
  return {
    root,
    scopeId,
    statePath: path.join(root, "state.json"),
    lockPath: path.join(root, "startup.lock"),
    endpoint: platform === "win32"
      ? `\\\\.\\pipe\\forgeloop-persistent-search-${scopeHash(homeDirectory)}`
      // macOS limits Unix-domain socket paths to a small fixed length. Keep
      // the user-scoped endpoint in the local temporary namespace while the
      // authoritative ownership state remains under the user's ForgeLoop
      // directory.
      : path.join(os.tmpdir(), `forgeloop-persistent-search-${scopeHash(homeDirectory)}.sock`),
  };
}

export function getPersistentTransportScopeId({ homeDirectory = os.homedir() } = {}) {
  return `user-${scopeHash(homeDirectory)}`;
}

function scopeHash(homeDirectory) {
  return createHash("sha256").update(String(homeDirectory)).digest("hex").slice(0, 20);
}

export async function readPersistentTransportState(statePath) {
  try {
    const info = await lstat(statePath);
    if (!info.isFile() || info.isSymbolicLink()) return { state: null, invalid: true };
    const state = JSON.parse(await readFile(statePath, "utf8"));
    if (!state || typeof state !== "object" || state.schemaVersion !== PERSISTENT_TRANSPORT_SCHEMA_VERSION) return { state: null, invalid: true };
    return { state, invalid: false };
  } catch (error) {
    if (error.code === "ENOENT") return { state: null, invalid: false };
    if (error instanceof SyntaxError) return { state: null, invalid: true };
    throw error;
  }
}

export function appendSearchFilters(args, { globs = [], types = [] } = {}) {
  for (const glob of globs) args.push("--glob", glob);
  for (const type of types) args.push("--type", type);
  return args;
}

export function getCanonicalRepositoryIndexArgs({ mode, indexPath, config = {} } = {}) {
  if (!["index", "serve", "search", "status"].includes(mode)) {
    throw new Error(`Unknown Repository Index command mode: ${mode}`);
  }
  if (typeof indexPath !== "string" || indexPath.trim() === "") {
    throw new Error("Repository Index indexPath is required");
  }

  const effective = {
    ...REPOSITORY_INDEX_DEFAULTS,
    ...config,
  };
  const args = [];
  pushPair(args, "--index-path", indexPath);
  pushPair(args, "--max-filesize", effective.maxFileSize);
  if (["index", "serve"].includes(mode)) {
    args.push("--exclude", ".forgeloop/repository-index");
  }
  args.push("--no-require-git");

  if (mode === "index") {
    args.push("--index-strategy", "external");
  }
  if (mode === "serve") {
    pushPair(args, "--max-cpu", effective.maxCpuPercent);
    pushPair(args, "--watcher-queue-cap", effective.watcherQueueCap);
    pushPair(args, "--auto-save-mutations", effective.autoSaveMutations);
  }
  return Object.freeze(args);
}

export function getCanonicalRepositorySearchArgs({ indexPath, pattern, options = {}, config = {} } = {}) {
  const args = ["--regexp", pattern];
  if (options.fixedStrings) args.push("--fixed-strings");
  if (options.ignoreCase) args.push("--ignore-case");
  if (options.smartCase) args.push("--smart-case");
  if (options.wordRegexp) args.push("--word-regexp");
  if (options.context !== undefined && options.context !== null) pushPair(args, "--context", options.context);
  if (options.beforeContext !== undefined && options.beforeContext !== null) pushPair(args, "--before-context", options.beforeContext);
  if (options.afterContext !== undefined && options.afterContext !== null) pushPair(args, "--after-context", options.afterContext);
  if (options.maxCount !== undefined && options.maxCount !== null) pushPair(args, "--max-count", options.maxCount);
  if (options.filesWithMatches) args.push("--files-with-matches");
  if (options.stats) args.push("--stats");
  args.push("--json");
  args.push(...getCanonicalRepositoryIndexArgs({ mode: "search", indexPath, config }));
  return Object.freeze(args);
}

function pushPair(args, flag, value) {
  args.push(flag, String(value));
}

function absolutePath(value, label) {
  if (typeof value !== "string" || !path.isAbsolute(value)) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `${label} must be an absolute path`);
  }
  return path.normalize(value);
}

async function ensureRegularFile(filePath, code, label) {
  let info;
  try {
    info = await lstat(filePath);
  } catch (cause) {
    if (cause.code === "ENOENT") throw repositoryIndexError(code, `${label} is missing: ${filePath}`, { cause, path: filePath });
    throw repositoryIndexError(code, `${label} cannot be inspected: ${filePath}: ${cause.message}`, { cause, path: filePath });
  }
  if (info.isSymbolicLink() || !info.isFile()) {
    throw repositoryIndexError(code, `${label} must be a regular file: ${filePath}`, { path: filePath });
  }
  return info;
}

function parseVersion(output) {
  return output.match(VERSION_PATTERN)?.[1] ?? null;
}

export async function sha256File(filePath) {
  return new Promise((resolve, reject) => {
    const hash = createHash("sha256");
    const stream = createReadStream(filePath);
    stream.on("data", (chunk) => hash.update(chunk));
    stream.on("error", reject);
    stream.on("end", () => resolve(hash.digest("hex")));
  });
}

export async function verifyBinaryChecksum(binaryPath, expectedSha256) {
  const actual = await sha256File(binaryPath);
  if (actual !== expectedSha256) {
    throw repositoryIndexError(
      REPOSITORY_INDEX_ERROR_CODES.ENGINE_BINARY_CHECKSUM_MISMATCH,
      `tgrep binary checksum mismatch: expected ${expectedSha256}, got ${actual}`,
      { expectedSha256, actualSha256: actual, binaryPath },
    );
  }
  return actual;
}

async function verifyExecutable(filePath, { platform = process.platform } = {}) {
  await ensureRegularFile(filePath, REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, "Managed tgrep binary");
  if (platform !== "win32") {
    try {
      await access(filePath, fsConstants.X_OK);
    } catch (cause) {
      throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `Managed tgrep binary is not executable: ${filePath}`, { cause, path: filePath });
    }
  }
}

export async function verifyManagedTgrep({ packageRoot, repoRoot = process.cwd(), platform, arch, env = process.env, binaryPath: explicitBinaryPath, homeDirectory = os.homedir(), spawnImpl } = {}) {
  const manifest = await loadTgrepManifest(packageRoot);
  const selectedPlatform = platform && arch
    ? getRepositoryIndexPlatform({ platform, arch })
    : getRepositoryIndexPlatform();
  const override = explicitBinaryPath ?? env?.[REPOSITORY_INDEX_ENV_BINARY];
  if (override) {
    const overridePath = absolutePath(override, REPOSITORY_INDEX_ENV_BINARY);
    await ensureRegularFile(overridePath, REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, "Explicit tgrep override");
    if (selectedPlatform.platform !== "win32") {
      try { await access(overridePath, fsConstants.X_OK); } catch (cause) {
        throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `Explicit tgrep override is not executable: ${overridePath}`, { cause, path: overridePath });
      }
    }
    const version = await verifyTgrepVersion({ binaryPath: overridePath, expectedVersion: manifest.version, repoRoot, spawnImpl });
    return Object.freeze({
      engine: manifest.engine,
      engineVersion: version,
      platform: selectedPlatform,
      binaryPath: overridePath,
      managed: false,
      overridden: true,
      canonical: false,
      asset: null,
    });
  }

  const binaryPath = getManagedTgrepBinaryPath(manifest.version, selectedPlatform.key, {
    homeDirectory,
    windows: selectedPlatform.platform === "win32",
  });
  const asset = manifest.assets[selectedPlatform.key];
  await verifyExecutable(binaryPath, { platform: selectedPlatform.platform });
  await verifyBinaryChecksum(binaryPath, asset.binarySha256);
  const version = await verifyTgrepVersion({ binaryPath, expectedVersion: manifest.version, repoRoot, spawnImpl });
  return Object.freeze({
    engine: manifest.engine,
    engineVersion: version,
    platform: selectedPlatform,
    binaryPath,
    managed: true,
    overridden: false,
    canonical: true,
    asset,
  });
}

export async function verifyTgrepVersion({ binaryPath, expectedVersion, repoRoot = process.cwd(), spawnImpl, timeoutMs = 15_000 } = {}) {
  const result = await runTgrep({
    binary: createTgrepBinaryHandle(binaryPath),
    repoRoot,
    args: ["--version"],
    spawnImpl,
    timeoutMs,
    maxOutputBytes: 64 * 1024,
  });
  if (result.timedOut || result.exitCode !== 0) {
    throw repositoryIndexError(
      REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED,
      `Unable to verify tgrep version at ${binaryPath}`,
      { result: { exitCode: result.exitCode, stderr: result.stderr.slice(0, 2000), timedOut: result.timedOut } },
    );
  }
  const actualVersion = parseVersion(`${result.stdout}\n${result.stderr}`);
  if (actualVersion !== expectedVersion) {
    throw repositoryIndexError(
      REPOSITORY_INDEX_ERROR_CODES.ENGINE_VERSION_MISMATCH,
      `Managed tgrep version is ${actualVersion ?? "unknown"}; expected ${expectedVersion}`,
      { actualVersion, expectedVersion, binaryPath },
    );
  }
  return actualVersion;
}

export function repositoryIndexError(code, message, details = {}) {
  const error = new Error(message);
  error.code = code;
  for (const [key, value] of Object.entries(details)) {
    if (value !== undefined) error[key] = value;
  }
  return error;
}

export async function isRepositoryCandidate(repositoryRoot) {
  try {
    const info = await lstat(path.join(repositoryRoot, ".git"));
    return info.isDirectory() || info.isFile();
  } catch (error) {
    if (error.code === "ENOENT") return false;
    throw error;
  }
}

function assertManifest(value, source = "tgrep manifest") {
  assertManifestObject(value, source);
  assertManifestIdentity(value, source);
  assertManifestRelease(value, source);
  assertManifestAssets(value, source);
  return Object.freeze({
    ...value,
    assets: Object.freeze(Object.fromEntries(Object.entries(value.assets).map(([key, asset]) => [key, Object.freeze({ ...asset })]))),
  });
}

function assertManifestAsset(asset, platformKey, source) {
  if (!asset || typeof asset !== "object") manifestError(source, `is missing ${platformKey}`);
  if (typeof asset.assetName !== "string" || asset.assetName.trim() === "") {
    manifestError(source, `${platformKey} assetName is required`);
  }
  const assetName = asset.assetName.replaceAll("\\", "/");
  if (path.posix.isAbsolute(assetName) || path.win32.isAbsolute(assetName)
    || path.posix.basename(assetName) !== assetName || path.posix.normalize(assetName) !== assetName
    || !/^[A-Za-z0-9._-]+$/u.test(assetName)) {
    manifestError(source, `${platformKey} assetName must be a single safe filename`);
  }
  if (!ARCHIVES.has(asset.archive)) manifestError(source, `${platformKey} archive is unsupported`);
  if (typeof asset.binaryName !== "string" || asset.binaryName.trim() === "") {
    manifestError(source, `${platformKey} binaryName is required`);
  }
  const expectedBinaryName = platformKey === "windows-x64" ? "tgrep.exe" : "tgrep";
  if (asset.binaryName !== expectedBinaryName) {
    manifestError(source, `${platformKey} binaryName must be ${expectedBinaryName}`);
  }
  if (!SHA256.test(asset.sha256) || /^0+$/.test(asset.sha256) || /replace|todo|placeholder/i.test(asset.sha256)) {
    manifestError(source, `${platformKey} checksum is not a verified SHA-256`, REPOSITORY_INDEX_ERROR_CODES.ENGINE_CHECKSUM_MISMATCH);
  }
  if (!SHA256.test(asset.binarySha256) || /^0+$/.test(asset.binarySha256) || /replace|todo|placeholder/i.test(asset.binarySha256)) {
    manifestError(source, `${platformKey} binarySha256 is not a verified SHA-256`, REPOSITORY_INDEX_ERROR_CODES.ENGINE_BINARY_CHECKSUM_MISMATCH);
  }
}

function assertManifestAssets(value, source) {
  if (!value.assets || typeof value.assets !== "object" || Array.isArray(value.assets)) {
    manifestError(source, "assets are required");
  }
  for (const key of REPOSITORY_INDEX_SUPPORTED_PLATFORMS) {
    assertManifestAsset(value.assets[key], key, source);
  }
  const unsupportedKeys = Object.keys(value.assets).filter((key) => !REPOSITORY_INDEX_SUPPORTED_PLATFORMS.includes(key));
  if (unsupportedKeys.length > 0) {
    manifestError(source, `contains unsupported platforms: ${unsupportedKeys.join(", ")}`);
  }
}

function assertManifestIdentity(value, source) {
  if (value.engine !== REPOSITORY_INDEX_ENGINE) {
    manifestError(source, `engine must be ${REPOSITORY_INDEX_ENGINE}`);
  }
  if (typeof value.repository !== "string" || value.repository !== "microsoft/tgrep") {
    manifestError(source, "repository must be microsoft/tgrep");
  }
  if (typeof value.version !== "string" || !SEMVER.test(value.version)) {
    manifestError(source, "version is invalid");
  }
}

function assertManifestObject(value, source) {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    manifestError(source, "must be a JSON object");
  }
  if (value.schemaVersion !== 1) {
    manifestError(source, "schemaVersion must be 1");
  }
}

function assertManifestRelease(value, source) {
  if (typeof value.releaseBaseUrl !== "string"
    || value.releaseBaseUrl !== `https://github.com/microsoft/tgrep/releases/download/v${value.version}`) {
    manifestError(source, "releaseBaseUrl must be the pinned Microsoft tgrep release URL");
  }
}

export async function loadTgrepManifest(packageRoot = getPackageRoot()) {
  if (typeof packageRoot !== "string" || packageRoot.trim() === "") {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, "ForgeLoop package root is required to load the tgrep manifest");
  }
  const manifestPath = path.join(packageRoot, "src", "repository-index", "tgrep-manifest.json");
  let value;
  try {
    value = JSON.parse(await readFile(manifestPath, "utf8"));
  } catch (cause) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `Unable to read ${manifestPath}: ${cause.message}`, { cause, manifestPath });
  }
  return assertManifest(value, manifestPath);
}

function manifestError(source, message, code = REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING) {
  throw repositoryIndexError(code, `${source} ${message}`);
}

export function buildRepositorySearchMetrics({ durationMs, nativeDurationMs, result, engine, engineVersion, serverUsed }) {
  return {
    queryDurationMs: durationMs,
    nativeDurationMs,
    matchCount: result.matches.length,
    matchedFileCount: result.files.length,
    engine,
    engineVersion,
    serverUsed,
    exitCode: result.exitCode,
    ignoredNativeEvents: result.ignoredEvents,
    ...(result.stats.bytesSearched !== undefined ? { bytesSearched: result.stats.bytesSearched } : {}),
    ...(result.stats.matchedLines !== undefined ? { matchedLines: result.stats.matchedLines } : {}),
  };
}

function addStats(target, data) {
  const stats = data?.stats && typeof data.stats === "object" ? data.stats : data;
  if (!stats || typeof stats !== "object") return;
  const values = {
    bytesSearched: stats.bytes_searched,
    bytesPrinted: stats.bytes_printed,
    matchedLines: stats.matched_lines,
    matches: stats.matches,
    searches: stats.searches,
    searchesWithMatch: stats.searches_with_match,
    elapsedNanos: stats.elapsed?.nanos,
  };
  for (const [key, value] of Object.entries(values)) {
    if (Number.isSafeInteger(value) && value >= 0) target[key] = value;
  }
}

function extractData(event) {
  return event && typeof event === "object" && event.data && typeof event.data === "object"
    ? event.data
    : event;
}

function finiteInteger(value, label, { min = 0, optional = false } = {}) {
  if (value === undefined || value === null) {
    if (optional) return null;
    throw invalid(`tgrep JSON field ${label} is required`);
  }
  if (!Number.isSafeInteger(value) || value < min) throw invalid(`tgrep JSON field ${label} is invalid`);
  return value;
}

function invalid(message, details = {}) {
  return repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.OUTPUT_INVALID, message, details);
}

function lineText(data) {
  if (typeof data.text === "string") return data.text;
  if (data.lines && typeof data.lines.text === "string") return data.lines.text;
  return "";
}

function looksLikeStatsLine(line) {
  return /^(?:Query plan:|Search completed in |Walking |Found \d+ text files|Extracting trigrams|Writing index|Index built successfully|Indexed in )/i.test(line.trim());
}

async function normalizeMatch(event, repositoryRoot, options) {
  const data = extractData(event);
  const relativePath = await normalizePath(pathText(data), repositoryRoot, options);
  const lineNumber = finiteInteger(data.line_number ?? data.lineNumber, "line_number", { min: 1 });
  const absoluteOffset = finiteInteger(data.absolute_offset ?? data.absoluteOffset, "absolute_offset", { optional: true });
  return {
    path: relativePath,
    line: lineNumber,
    column: finiteInteger(data.column, "column", { min: 1, optional: true }),
    offset: absoluteOffset,
    text: lineText(data),
    submatches: normalizeSubmatches(data),
  };
}

async function normalizePath(value, repositoryRoot, { pathStyle = null } = {}) {
  if (typeof value !== "string" || value.length === 0) throw invalid("tgrep JSON match path is missing");
  const windows = usesWindowsPath(value, repositoryRoot, pathStyle);
  const pathApi = windows ? path.win32 : path;
  const normalizedRoot = pathApi.normalize(repositoryRoot);
  const normalizedValue = value.replaceAll("/", pathApi.sep);
  const candidate = pathApi.isAbsolute(normalizedValue)
    ? pathApi.normalize(normalizedValue)
    : pathApi.resolve(normalizedRoot, normalizedValue);
  const comparisonRoot = windows ? normalizedRoot.toLowerCase() : normalizedRoot;
  const comparisonCandidate = windows ? candidate.toLowerCase() : candidate;
  const relative = pathApi.relative(comparisonRoot, comparisonCandidate);
  if (relative === ".." || relative.startsWith(`..${pathApi.sep}`) || pathApi.isAbsolute(relative)) {
    throw invalid(`tgrep JSON path escapes the repository root: ${value}`);
  }
  return relative ? relative.split(pathApi.sep).join("/") : ".";
}

function normalizeSubmatches(data) {
  if (data.submatches === undefined) return [];
  if (!Array.isArray(data.submatches)) throw invalid("tgrep JSON submatches must be an array");
  return data.submatches.map((submatch, index) => {
    if (!submatch || typeof submatch !== "object") throw invalid(`tgrep JSON submatch ${index} is invalid`);
    const start = finiteInteger(submatch.start, `submatches[${index}].start`);
    const end = finiteInteger(submatch.end, `submatches[${index}].end`);
    if (end < start) throw invalid(`tgrep JSON submatch ${index} has a reversed range`);
    const match = typeof submatch.match === "string" ? submatch.match : submatch.match?.text;
    return { start, end, match: typeof match === "string" ? match : null };
  });
}

export async function normalizeTgrepJson(stdout, {
  repositoryRoot,
  filesWithMatches = false,
  realpathImpl = realpath,
  pathStyle = null,
} = {}) {
  if (typeof stdout !== "string" || typeof repositoryRoot !== "string") throw invalid("tgrep JSON output requires text and repositoryRoot");
  const canonicalRoot = await realpathImpl(repositoryRoot);
  const pathOptions = { pathStyle };
  const lines = stdout.split(/\r?\n/).filter((line) => line.trim());
  if (filesWithMatches) {
    return {
      matches: [],
      contexts: [],
      files: await parseFileLines(lines, canonicalRoot, pathOptions),
      stats: {},
      events: { begin: 0, match: 0, context: 0, end: 0, summary: 0 },
      ignoredEvents: 0,
    };
  }

  const matches = [];
  const contexts = [];
  const stats = {};
  const files = new Set();
  const events = { begin: 0, match: 0, context: 0, end: 0, summary: 0 };
  let ignoredEvents = 0;
  for (const line of lines) {
    let event;
    try { event = JSON.parse(line); } catch {
      if (looksLikeStatsLine(line)) continue;
      throw invalid("tgrep emitted a non-JSON line in JSON search mode", { line: line.slice(0, 500) });
    }
    if (!event || typeof event !== "object" || typeof event.type !== "string") {
      throw invalid("tgrep emitted a JSON value without an event type");
    }
    if (!Object.hasOwn(events, event.type)) {
      ignoredEvents += 1;
      continue;
    }
    events[event.type] += 1;
    if (event.type === "match" || event.type === "context") {
      const normalized = await normalizeMatch(event, canonicalRoot, pathOptions);
      files.add(normalized.path);
      (event.type === "match" ? matches : contexts).push(normalized);
    } else if (event.type === "end" || event.type === "summary") {
      addStats(stats, extractData(event));
    }
  }
  return { matches, contexts, files: [...files].sort(), stats, events, ignoredEvents };
}

async function parseFileLines(lines, repositoryRoot, options) {
  const files = [];
  for (const line of lines) {
    if (!line.trim()) continue;
    if (looksLikeStatsLine(line)) continue;
    let value;
    try { value = JSON.parse(line); } catch {
      files.push(await normalizePath(line.trim(), repositoryRoot, options));
      continue;
    }
    const text = pathText(extractData(value));
    if (value.type === "match" || value.type === "context") {
      files.push(await normalizePath(text, repositoryRoot, options));
    } else if (text) {
      files.push(await normalizePath(text, repositoryRoot));
    }
  }
  return [...new Set(files)].sort();
}

function pathText(data) {
  if (typeof data.path === "string") return data.path;
  if (data.path && typeof data.path.text === "string") return data.path.text;
  return null;
}

function usesWindowsPath(value, repositoryRoot, pathStyle) {
  return pathStyle === "win32"
    || /^[A-Za-z]:[\\/]/u.test(value)
    || /^\\\\/u.test(value)
    || /^[A-Za-z]:[\\/]/u.test(repositoryRoot)
    || /^\\\\/u.test(repositoryRoot);
}

export function getEngineHome({ homeDirectory = os.homedir() } = {}) {
  return path.join(homeDirectory, ".forgeloop", "engines", "tgrep");
}

export function getManagedTgrepBinaryPath(version, platformKey, { windows = platformKey.startsWith("windows-") || process.platform === "win32", ...options } = {}) {
  return path.join(getManagedTgrepDirectory(version, platformKey, options), windows ? "tgrep.exe" : "tgrep");
}

export function getManagedTgrepDirectory(version, platformKey, options = {}) {
  return path.join(getTgrepVersionDirectory(version, options), platformKey);
}

export function getRepositoryIndexRoot(repoRoot) {
  return path.join(repoRoot, REPOSITORY_INDEX_RELATIVE_PATH);
}

export function getRepositoryIndexStatePath(repoRoot) {
  return path.join(getRepositoryIndexRoot(repoRoot), REPOSITORY_INDEX_STATE_FILE);
}

export function getTgrepIndexPath(repoRoot) {
  return path.join(getRepositoryIndexRoot(repoRoot), "tgrep");
}

export function getTgrepVersionDirectory(version, options = {}) {
  return path.join(getEngineHome(options), version);
}

export function getRepositoryIndexPlatform({ platform = process.platform, arch = process.arch } = {}) {
  const key = SUPPORTED.get(`${platform}:${arch}`);
  if (!key) {
    throw repositoryIndexError(
      REPOSITORY_INDEX_ERROR_CODES.PLATFORM_UNSUPPORTED,
      `Repository Index does not support platform ${platform}/${arch}`,
      { platform, arch },
    );
  }
  return Object.freeze({ platform, arch, key });
}

function assertArgs(args) {
  if (!Array.isArray(args) || args.some((arg) => typeof arg !== "string" || arg.length === 0)) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "tgrep arguments must be a non-empty string array");
  }
}

function assertExecutablePath(binaryPath) {
  if (typeof binaryPath !== "string" || binaryPath.trim() === "") {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "A verified managed tgrep binary path is required");
  }
  if (!path.isAbsolute(binaryPath) || !binaryPath.match(/^[\w./\\: @%+=~-]+$/u)) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "The managed tgrep binary path contains unsafe command characters");
  }
  return binaryPath;
}

export function createTgrepBinaryHandle(binaryPath) {
  const handle = Object.freeze({});
  trustedBinaryPaths.set(handle, assertExecutablePath(binaryPath));
  return handle;
}

function resolveTgrepBinaryHandle(handle) {
  const binaryPath = trustedBinaryPaths.get(handle);
  if (!binaryPath) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "A validated managed tgrep binary handle is required");
  }
  return binaryPath;
}

export async function runTgrep({ binary, repoRoot, args, stdin = null, timeoutMs = REPOSITORY_INDEX_DEFAULTS.commandTimeoutMs, env = {}, spawnImpl = spawn, maxOutputBytes = REPOSITORY_INDEX_DEFAULTS.maxProcessOutputBytes } = {}) {
  const binaryPath = resolveTgrepBinaryHandle(binary);
  if (typeof repoRoot !== "string" || repoRoot.trim() === "") {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "A repository root is required to execute tgrep");
  }
  assertArgs(args);
  if (!Number.isInteger(timeoutMs) || timeoutMs <= 0) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, "tgrep timeoutMs must be a positive integer");
  }
  const effectiveTimeoutMs = Math.min(timeoutMs, MAX_COMMAND_TIMEOUT_MS);

  const startedAt = Date.now();
  return new Promise((resolve, reject) => {
    let child;
    try {
      child = spawnImpl(binaryPath, args, {
        cwd: repoRoot,
        env: { ...process.env, ...env },
        shell: false,
        windowsHide: true,
      });
    } catch (cause) {
      reject(repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, `Unable to launch managed tgrep: ${cause.message}`, { cause }));
      return;
    }

    let stdout = "";
    let stderr = "";
    let settled = false;
    let timedOut = false;
    const timeoutDeadline = startedAt + effectiveTimeoutMs;
    const timer = setInterval(() => {
      if (Date.now() < timeoutDeadline) return;
      timedOut = true;
      clearInterval(timer);
      try { child.kill("SIGTERM"); } catch { /* process may already be gone */ }
    }, PROCESS_TIMER_INTERVAL_MS);
    timer.unref?.();

    const finish = (fn, value) => {
      if (settled) return;
      settled = true;
      clearInterval(timer);
      fn(value);
    };
    const append = (current, chunk) => {
      const next = `${current}${chunk.toString("utf8")}`;
      if (Buffer.byteLength(next, "utf8") > maxOutputBytes) {
        try { child.kill("SIGTERM"); } catch { /* process may already be gone */ }
        finish(reject, repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_OUTPUT_LIMIT, `tgrep output exceeded ${maxOutputBytes} bytes`));
        return current;
      }
      return next;
    };
    child.stdout?.on("data", (chunk) => { stdout = append(stdout, chunk); });
    child.stderr?.on("data", (chunk) => { stderr = append(stderr, chunk); });
    child.once("error", (cause) => finish(reject, repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED, `Managed tgrep failed to start: ${cause.message}`, { cause })));
    child.once("close", (exitCode, signal) => {
      if (settled) return;
      const result = {
        exitCode: Number.isInteger(exitCode) ? exitCode : null,
        signal: signal ?? null,
        stdout,
        stderr,
        durationMs: Date.now() - startedAt,
        timedOut,
      };
      finish(resolve, result);
    });
    if (stdin !== null && stdin !== undefined) {
      child.stdin?.end(stdin);
    } else {
      child.stdin?.end();
    }
  });
}

export function getRepositoryIndexReadiness(canonicalRoot, platform = process.platform) {
  return readinessByRepository.get(normalize(canonicalRoot, platform)) ?? null;
}

export function invalidateRepositoryIndexReadiness(canonicalRoot, platform = process.platform) {
  if (typeof canonicalRoot !== "string") return;
  readinessByRepository.delete(normalize(canonicalRoot, platform));
}

export function isRepositoryIndexReadinessUsable(readiness, expected = {}, { isAlive = processIsAlive } = {}) {
  if (!readiness || readiness.serverRunning !== true || typeof readiness.canonicalRoot !== "string") return false;
  const platform = expected.platform ?? readiness.platform ?? process.platform;
  if (expected.canonicalRoot && normalize(readiness.canonicalRoot, platform) !== normalize(expected.canonicalRoot, platform)) return false;
  if (expected.indexPath && normalize(readiness.indexPath, platform) !== normalize(expected.indexPath, platform)) return false;
  if (expected.binaryPath && normalize(readiness.binaryPath, platform) !== normalize(expected.binaryPath, platform)) return false;
  if (expected.engineVersion && readiness.engineVersion !== expected.engineVersion) return false;
  if (!Number.isInteger(readiness.pid) || !isAlive(readiness.pid)) return false;
  return true;
}

export function markRepositoryIndexSearchSucceeded(canonicalRoot, platform = process.platform) {
  const current = getRepositoryIndexReadiness(canonicalRoot, platform);
  if (!current) return null;
  const next = Object.freeze({ ...current, lastSuccessfulSearchAt: new Date().toISOString() });
  readinessByRepository.set(normalize(canonicalRoot, platform), next);
  return next;
}

function normalize(value, platform = process.platform) {
  if (typeof value !== "string" || value.length === 0) return value;
  const pathApi = platform === "win32" ? path.win32 : path;
  const normalized = pathApi.normalize(value);
  return platform === "win32" ? normalized.toLowerCase() : normalized;
}

export function rememberRepositoryIndexReadiness({ canonicalRoot, status, platform } = {}) {
  if (typeof canonicalRoot !== "string" || !status?.indexPath || !status?.binaryPath || status.server?.running !== true) return null;
  const selectedPlatform = platform ?? status.platform?.platform ?? process.platform;
  const readiness = Object.freeze({
    canonicalRoot,
    indexPath: status.indexPath,
    binaryPath: status.binaryPath,
    engineVersion: status.engineVersion ?? null,
    serverRunning: true,
    pid: Number.isInteger(status.server?.pid) ? status.server.pid : null,
    platform: selectedPlatform,
    status,
    lastSuccessfulSearchAt: null,
  });
  readinessByRepository.set(normalize(canonicalRoot, selectedPlatform), readiness);
  return readiness;
}

function assertSearchInvocation(repositoryRoot, request) {
  if (typeof repositoryRoot !== "string" || repositoryRoot.length === 0) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.REQUEST_INVALID, "Search repoRoot is required");
  }
  if (!request || typeof request !== "object" || Array.isArray(request)) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.REQUEST_INVALID, "Search request must be an object");
  }
}

function buildSearchArgs({ indexPath, canonicalRoot, request }) {
  const args = [...getCanonicalRepositorySearchArgs({
    indexPath,
    pattern: request.pattern,
    options: request,
    config: request.config,
  })];
  appendSearchFilters(args, { globs: request.globs, types: request.types });
  args.push(canonicalRoot);
  return args;
}

function collectErrorPaths(error) {
  const paths = [];
  const seen = new Set();
  for (let current = error; current && !seen.has(current); current = current.cause) {
    seen.add(current);
    for (const key of ["path", "binaryPath", "repositoryRoot", "indexPath", "statePath", "archivePath", "manifestPath", "source"]) {
      if (typeof current[key] === "string") paths.push(current[key]);
    }
    const status = current.status;
    if (status && typeof status === "object") {
      for (const value of [status.binaryPath, status.repositoryRoot, status.indexPath, status.statePath, status.index?.rootPath]) {
        if (typeof value === "string") paths.push(value);
      }
    }
  }
  return [...new Set(paths)].sort((left, right) => right.length - left.length);
}

async function expectedReadiness(canonicalRoot, request) {
  const manifest = await loadTgrepManifest(request.packageRoot);
  const selectedPlatform = getRepositoryIndexPlatform({ platform: request.platform, arch: request.arch });
  const override = request.binaryPath
    ?? (request.env === undefined ? process.env[REPOSITORY_INDEX_ENV_BINARY] : request.env?.[REPOSITORY_INDEX_ENV_BINARY]);
  const binaryPath = override ?? getManagedTgrepBinaryPath(manifest.version, selectedPlatform.key, {
    homeDirectory: request.homeDirectory,
    windows: selectedPlatform.platform === "win32",
  });
  return {
    canonicalRoot,
    indexPath: getTgrepIndexPath(canonicalRoot),
    binaryPath,
    engineVersion: manifest.version,
    platform: selectedPlatform.platform,
  };
}

function isRecoverableSearchFailure(error) {
  if (error?.code === REPOSITORY_INDEX_ERROR_CODES.ENGINE_EXECUTION_FAILED) return true;
  if (error?.code !== REPOSITORY_INDEX_ERROR_CODES.SEARCH_FAILED) return false;
  return /server|index|connect|connection|not running|metadata|broken pipe|no such file|unavailable/i.test(error.stderr ?? "");
}

function normalizeSearchInvocation(repositoryRoot, request) {
  if (repositoryRoot && typeof repositoryRoot === "object" && request && Object.keys(request).length === 0) {
    const normalizedRequest = { ...repositoryRoot };
    return {
      repositoryRoot: normalizedRequest.repoRoot ?? normalizedRequest.repositoryRoot ?? normalizedRequest.projectPath,
      request: normalizedRequest,
    };
  }
  return { repositoryRoot, request };
}

async function prepareSearch(repositoryRoot, request) {
  const canonicalRoot = await realpath(repositoryRoot);
  const setupImpl = request.setupRepositoryIndexImpl ?? setupRepositoryIndex;
  const cached = getRepositoryIndexReadiness(canonicalRoot, request.platform ?? process.platform);
  if (cached) {
    const expected = await expectedReadiness(canonicalRoot, request);
    if (isRepositoryIndexReadinessUsable(cached, expected, { isAlive: request.processIsAliveImpl })) {
      return {
        status: cached.status,
        canonicalRoot,
        indexPath: cached.indexPath,
        binaryPath: cached.binaryPath,
        cacheHit: true,
      };
    }
    invalidateRepositoryIndexReadiness(canonicalRoot, request.platform ?? process.platform);
  }

  const setup = await setupImpl(repositoryRoot, request);
  const status = setup.status?.repositoryRoot
    ? setup.status
    : await (request.getRepositoryIndexStatusImpl ?? getRepositoryIndexStatus)(canonicalRoot, { ...request, includeLocalPaths: true });
  if (status.health !== "READY") {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY, "Repository Index is not ready for search", { status });
  }
  const indexPath = status.indexPath;
  const binaryPath = status.binaryPath ?? request.binaryPath;
  if (!indexPath || !binaryPath) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY, "Repository Index readiness did not provide executable paths", { status });
  }
  rememberRepositoryIndexReadiness({ canonicalRoot, status, platform: request.platform });
  return { status, canonicalRoot, indexPath, binaryPath, cacheHit: false };
}

async function runSearch({ binaryPath, status, canonicalRoot, request, args }) {
  const startedAt = Date.now();
  const result = await (request.runTgrepImpl ?? runTgrep)({
    binary: createTgrepBinaryHandle(binaryPath),
    repoRoot: canonicalRoot,
    args,
    env: request.env,
    spawnImpl: request.spawnImpl,
    timeoutMs: request.commandTimeoutMs ?? REPOSITORY_INDEX_DEFAULTS.commandTimeoutMs,
    maxOutputBytes: request.maxProcessOutputBytes ?? REPOSITORY_INDEX_DEFAULTS.maxProcessOutputBytes,
  });
  if (result.timedOut || ![0, 1].includes(result.exitCode)) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.SEARCH_FAILED, `tgrep search failed with exit code ${result.exitCode ?? "unknown"}`, {
      exitCode: result.exitCode,
      stderr: result.stderr.slice(0, 4000),
    });
  }
  const normalized = await normalizeTgrepJson(result.stdout, {
    repositoryRoot: canonicalRoot,
    filesWithMatches: request.filesWithMatches === true,
  });
  return { result, normalized, startedAt, status };
}

function sanitizeSearchError(error, request, repositoryRoot) {
  const localPaths = [...new Set([
    repositoryRoot,
    request.binaryPath,
    request.homeDirectory,
    request.assetPath,
    process.cwd(),
    ...collectErrorPaths(error),
  ].filter((value) => typeof value === "string" && value.length > 0))].sort((left, right) => right.length - left.length);
  const redact = (value) => localPaths.reduce((result, localPath) => result.replaceAll(localPath, "<local-path>"), String(value ?? ""));
  if (localPaths.length === 0) return error;
  const sanitized = repositoryIndexError(error.code ?? REPOSITORY_INDEX_ERROR_CODES.SEARCH_FAILED, redact(error.message));
  for (const key of ["exitCode", "signal", "timedOut", "stderr", "stdout", "expectedVersion", "actualVersion"]) {
    if (error[key] !== undefined) sanitized[key] = typeof error[key] === "string" ? redact(error[key]) : error[key];
  }
  return sanitized;
}

export async function searchRepository(repositoryRoot, request = {}) {
  ({ repositoryRoot, request } = normalizeSearchInvocation(repositoryRoot, request));
  assertSearchInvocation(repositoryRoot, request);
  validateSearchRequest(request);
  let prepared;
  try {
    prepared = await prepareSearch(repositoryRoot, request);
  } catch (error) {
    throw sanitizeSearchError(error, request, repositoryRoot);
  }
  let args = buildSearchArgs({ indexPath: prepared.indexPath, canonicalRoot: prepared.canonicalRoot, request });
  try {
    const execution = await runSearch({ binaryPath: prepared.binaryPath, status: prepared.status, canonicalRoot: prepared.canonicalRoot, request, args });
    markRepositoryIndexSearchSucceeded(prepared.canonicalRoot, request.platform ?? process.platform);
    return buildSearchResult({ request, ...execution });
  } catch (error) {
    if (!isRecoverableSearchFailure(error)) throw sanitizeSearchError(error, request, prepared.canonicalRoot);
    invalidateRepositoryIndexReadiness(prepared.canonicalRoot, request.platform ?? process.platform);
    try {
      prepared = await prepareSearch(prepared.canonicalRoot, request);
    } catch (recoveryError) {
      throw sanitizeSearchError(recoveryError, request, prepared.canonicalRoot);
    }
    args = buildSearchArgs({ indexPath: prepared.indexPath, canonicalRoot: prepared.canonicalRoot, request });
    try {
      const execution = await runSearch({ binaryPath: prepared.binaryPath, status: prepared.status, canonicalRoot: prepared.canonicalRoot, request, args });
      markRepositoryIndexSearchSucceeded(prepared.canonicalRoot, request.platform ?? process.platform);
      return buildSearchResult({ request, ...execution });
    } catch (retryError) {
      throw sanitizeSearchError(retryError, request, prepared.canonicalRoot);
    }
  }
}

function validateSearchRequest({ pattern, globs = [], types = [], context, beforeContext, afterContext, maxCount } = {}) {
  if (typeof pattern !== "string" || pattern.length === 0 || pattern.length > MAX_PATTERN_CHARS) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.REQUEST_INVALID, `Search pattern must contain 1-${MAX_PATTERN_CHARS} characters`);
  }
  for (const [label, values] of [["globs", globs], ["types", types]]) {
    if (!Array.isArray(values) || values.length > MAX_FILTERS || values.some((value) => typeof value !== "string" || value.length === 0 || value.length > 256)) {
      throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.REQUEST_INVALID, `Search ${label} must contain at most ${MAX_FILTERS} bounded strings`);
    }
  }
  for (const [label, value] of [["context", context], ["beforeContext", beforeContext], ["afterContext", afterContext], ["maxCount", maxCount]]) {
    if (value !== undefined && value !== null && (!Number.isSafeInteger(value) || value < 0 || (label === "maxCount" && value === 0))) {
      throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.REQUEST_INVALID, `Search ${label} must be a valid positive or non-negative integer`);
    }
  }
}

function execFileAsync(execFileImpl, file, args) {
  return new Promise((resolve) => {
    execFileImpl(file, args, { shell: false, timeout: 5_000, maxBuffer: 128 * 1024 }, (error, stdout, stderr) => {
      resolve({ error, stdout: stdout ?? "", stderr: stderr ?? "" });
    });
  });
}

export async function getRepositoryIndexStatus(repositoryRoot, {
  packageRoot = getPackageRoot(),
  env = process.env,
  binaryPath,
  platform,
  arch,
  homeDirectory,
  config = {},
  spawnImpl,
  processInspector = {},
  skipNativeStatus = false,
  includeLocalPaths = false,
} = {}) {
  const canonicalRoot = await realpath(repositoryRoot);
  const indexPath = getTgrepIndexPath(canonicalRoot);
  const statePath = getRepositoryIndexStatePath(canonicalRoot);
  const status = baseStatus({ repositoryRoot: canonicalRoot, indexPath, statePath });

  const engine = await verifyEngineForStatus(status, {
    packageRoot,
    repoRoot: canonicalRoot,
    env,
    binaryPath,
    platform,
    arch,
    homeDirectory,
    spawnImpl,
  });
  if (!engine) return statusOutput(status, includeLocalPaths);

  const metadata = await readStatusMetadata(indexPath, statePath);
  if (metadata.error) return statusOutput(healthResult(status, "SERVER_UNHEALTHY", metadata.error), includeLocalPaths);
  const { meta, state, serve } = metadata;
  if (!meta) return statusOutput(healthResult(status, "NOT_INITIALIZED", { code: REPOSITORY_INDEX_ERROR_CODES.NOT_INITIALIZED, message: "Repository Index has not been built" }), includeLocalPaths);
  if (!await projectIndexMetadata(status, meta, canonicalRoot, config)) return statusOutput(status, includeLocalPaths);

  if (!skipNativeStatus) {
    const native = await readNativeStatus({ engine, canonicalRoot, indexPath, config, spawnImpl });
    if (nativeStatusFailed(native)) {
      return statusOutput(healthResult(status, "SERVER_UNHEALTHY", {
        code: native.error?.code ?? REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY,
        message: native.error?.message ?? "tgrep status failed",
      }), includeLocalPaths);
    }
    status.native = parseStatusText(`${native.stdout}\n${native.stderr}`);
  }

  const ownership = await inspectRepositoryIndexServer({
    state,
    serve,
    repositoryRoot: canonicalRoot,
    indexPath,
    processInspector,
  });
  return statusOutput(projectServerStatus(status, ownership, serve, state), includeLocalPaths);
}

function healthResult(status, health, diagnostic) {
  status.health = REPOSITORY_INDEX_HEALTH.includes(health) ? health : "ERROR";
  if (diagnostic) status.diagnostics.push(diagnostic);
  return status;
}

export async function inspectRepositoryIndexServer({ state, serve, repositoryRoot, indexPath, processInspector = {} } = {}) {
  const platform = processInspector.platform ?? process.platform;
  if (!state || state.startedByForgeLoop !== true) {
    return { owned: false, running: false, reason: "MISSING_FORGELOOP_OWNERSHIP" };
  }
  if (!stateMatchesIndexPaths(state, repositoryRoot, indexPath, platform)) {
    return { owned: false, running: false, reason: "STATE_PATH_MISMATCH" };
  }
  if (!serve || serve.pid !== state.observedPid || !Number.isInteger(serve.pid) || serve.pid <= 0) {
    return { owned: false, running: false, reason: "SERVE_METADATA_MISMATCH" };
  }
  const alive = (processInspector.isAlive ?? processIsAlive)(serve.pid);
  if (!alive) return { owned: true, running: false, pid: serve.pid, port: serve.port ?? null, reason: "PROCESS_EXITED" };
  const commandLine = await readProcessCommandLineForInspection(serve.pid, processInspector, platform);
  const identityReason = processIdentityReason({ commandLine, repositoryRoot, indexPath, binaryPath: state.binaryPath, platform });
  if (identityReason) return { owned: false, running: false, pid: serve.pid, port: serve.port ?? null, reason: identityReason, commandLine: null };
  return { owned: true, running: true, pid: serve.pid, port: serve.port ?? null, commandLine: null };
}

function nativeStatusFailed(native) {
  return native.error || (native.exitCode !== 0 && !native.stdout && !native.stderr);
}

function parseStatusText(text) {
  const files = Number(text.match(/^\s*Files:\s*(\d+)/mi)?.[1]);
  const trigrams = Number(text.match(/^\s*Trigrams:\s*(\d+)/mi)?.[1]);
  const serverNotRunning = /Server:\s*not running/i.test(text);
  const serverRunning = /Server:\s*running/i.test(text);
  const indexing = text.match(/^\s*(?:Indexing|Status):\s*(.+)$/mi)?.[1]?.trim() ?? null;
  return {
    files: Number.isFinite(files) ? files : null,
    trigrams: Number.isFinite(trigrams) ? trigrams : null,
    serverNotRunning,
    serverRunning,
    indexing,
  };
}

export async function processCommandLine(pid, { platform = process.platform, execFileImpl = nodeExecFile } = {}) {
  if (!Number.isInteger(pid) || pid <= 0) return null;
  if (platform === "win32") {
    // PowerShell is part of supported Windows hosts. Encode the command as
    // UTF-16LE instead of relying on Windows argument re-quoting for the
    // nested CIM filter. The interpolated value is already an integer, so
    // this remains an exact non-shell process query rather than a
    // user-controlled command string.
    const command = [
      "$ErrorActionPreference = 'Stop'",
      "$OutputEncoding = [System.Text.Encoding]::UTF8",
      "[Console]::OutputEncoding = [System.Text.Encoding]::UTF8",
      `(Get-CimInstance -ClassName Win32_Process -Filter 'ProcessId = ${pid}').CommandLine`,
    ].join("; ");
    const encodedCommand = Buffer.from(command, "utf16le").toString("base64");
    const result = await execFileAsync(execFileImpl, "powershell.exe", [
      "-NoProfile",
      "-NonInteractive",
      "-EncodedCommand",
      encodedCommand,
    ]);
    if (result.error) return null;
    const commandLine = result.stdout.replaceAll("\0", "").trim();
    return commandLine || null;
  }
  const result = await execFileAsync(execFileImpl, "ps", ["-p", String(pid), "-o", "command="]);
  if (result.error) return null;
  const command = result.stdout.trim();
  return command || null;
}

function processIdentityReason({ commandLine, repositoryRoot, indexPath, binaryPath, platform }) {
  const comparableCommandLine = platform === "win32" && typeof commandLine === "string"
    ? commandLine.toLowerCase()
    : commandLine;
  const comparableRoot = platform === "win32" ? repositoryRoot.toLowerCase() : repositoryRoot;
  const comparableIndexPath = platform === "win32" ? indexPath.toLowerCase() : indexPath;
  if (typeof commandLine !== "string" || !comparableCommandLine.includes("serve")
    || !comparableCommandLine.includes(comparableRoot) || !comparableCommandLine.includes(comparableIndexPath)) {
    return "PROCESS_IDENTITY_UNVERIFIED";
  }
  const comparableBinaryPath = platform === "win32" && binaryPath
    ? binaryPath.toLowerCase()
    : binaryPath;
  if (binaryPath && !comparableCommandLine.includes(comparableBinaryPath)) return "PROCESS_BINARY_MISMATCH";
  return null;
}

async function projectIndexMetadata(status, meta, canonicalRoot, config) {
  const metaRoot = typeof meta.root_path === "string" ? await realpath(meta.root_path).catch(() => meta.root_path) : null;
  status.index = {
    present: true,
    complete: meta.complete === true,
    files: Number.isInteger(meta.num_files) ? meta.num_files : null,
    trigrams: Number.isInteger(meta.num_trigrams) ? meta.num_trigrams : null,
    createdAt: Number.isFinite(meta.created_at) ? meta.created_at : null,
    updatedAt: Number.isFinite(meta.updated_at) ? meta.updated_at : null,
    rootPath: metaRoot,
  };
  status.policy = {
    maxFileSize: config.maxFileSize ?? REPOSITORY_INDEX_DEFAULTS.maxFileSize,
    maxCpuPercent: config.maxCpuPercent ?? REPOSITORY_INDEX_DEFAULTS.maxCpuPercent,
    watcherQueueCap: config.watcherQueueCap ?? REPOSITORY_INDEX_DEFAULTS.watcherQueueCap,
    autoSaveMutations: config.autoSaveMutations ?? REPOSITORY_INDEX_DEFAULTS.autoSaveMutations,
  };
  if (!samePath(metaRoot, canonicalRoot)) {
    healthResult(status, "SERVER_UNHEALTHY", { code: REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY, message: "Index metadata points at a different repository root" });
    return false;
  }
  if (meta.complete !== true) {
    status.server.indexing = "in-progress";
    healthResult(status, "INDEXING", { code: REPOSITORY_INDEX_ERROR_CODES.INDEXING, message: "Repository Index build is incomplete" });
    return false;
  }
  return true;
}

function projectServerStatus(status, ownership, serve, state) {
  status.server = {
    running: ownership.running === true,
    owned: ownership.owned === true,
    pid: ownership.pid ?? null,
    port: ownership.port ?? null,
    watcher: ownership.running ? "active" : "inactive",
    indexing: "complete",
    files: status.index.files,
  };
  if (ownership.running) return healthResult(status, "READY");
  if (serve || state) {
    return healthResult(status, ownership.owned ? "SERVER_DOWN" : "SERVER_UNHEALTHY", {
      code: REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY,
      message: ownership.owned ? "ForgeLoop Repository Index server is not running" : "A tgrep server exists without verifiable ForgeLoop ownership",
    });
  }
  return healthResult(status, "SERVER_DOWN", { code: REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY, message: "Repository Index server is not running" });
}

async function readJsonIfPresent(filePath) {
  try {
    const info = await lstat(filePath);
    if (info.isSymbolicLink() || !info.isFile()) return { error: "NOT_REGULAR_FILE" };
    const raw = await readFile(filePath, "utf8");
    return { value: JSON.parse(raw) };
  } catch (error) {
    if (error.code === "ENOENT") return { value: null };
    return { error: error.message };
  }
}

async function readNativeStatus({ engine, canonicalRoot, indexPath, config, spawnImpl }) {
  return runTgrep({
    binary: createTgrepBinaryHandle(engine.binaryPath),
    repoRoot: canonicalRoot,
    args: ["status", ...getCanonicalRepositoryIndexArgs({ mode: "status", indexPath, config }), canonicalRoot],
    spawnImpl,
    timeoutMs: 15_000,
    maxOutputBytes: 256 * 1024,
  }).catch((error) => ({ error }));
}

async function readProcessCommandLineForInspection(pid, processInspector, platform) {
  return processInspector.commandLine === undefined
    ? processCommandLine(pid, { ...processInspector, platform })
    : processInspector.commandLine(pid);
}

async function readStatusMetadata(indexPath, statePath) {
  const [metaFile, stateFile, serveFile] = await Promise.all([
    readJsonIfPresent(path.join(indexPath, "meta.json")),
    readJsonIfPresent(statePath),
    readJsonIfPresent(path.join(indexPath, "serve.json")),
  ]);
  if (metaFile.error || stateFile.error || serveFile.error) {
    return { error: { code: REPOSITORY_INDEX_ERROR_CODES.SERVER_UNHEALTHY, message: "Repository Index metadata is not readable as regular JSON files" } };
  }
  return { meta: metaFile.value, state: stateFile.value, serve: serveFile.value };
}

function samePath(left, right, platform = process.platform) {
  const pathApi = platform === "win32" ? path.win32 : path;
  const normalize = (value) => pathApi.normalize(value);
  const comparable = (value) => platform === "win32" ? value.toLowerCase() : value;
  return typeof left === "string" && typeof right === "string"
    && comparable(normalize(left)) === comparable(normalize(right));
}

export function sanitizeRepositoryIndexStatus(status) {
  if (!status || typeof status !== "object") return status;
  const {
    binaryPath: _binaryPath,
    repositoryRoot: _repositoryRoot,
    indexPath: _indexPath,
    statePath: _statePath,
    index = {},
    diagnostics = [],
    ...publicStatus
  } = status;
  const localPaths = [
    status.binaryPath,
    status.repositoryRoot,
    status.indexPath,
    status.statePath,
    index.rootPath,
    ...diagnostics.map((diagnostic) => diagnostic.path),
  ];
  const { rootPath: _rootPath, ...publicIndex } = index;
  return {
    ...publicStatus,
    index: publicIndex,
    diagnostics: diagnostics.map(({ path: _path, ...diagnostic }) => ({
      ...diagnostic,
      message: redactLocalPaths(diagnostic.message, localPaths),
    })),
  };
}

function stateMatchesIndexPaths(state, repositoryRoot, indexPath, platform) {
  return samePath(state?.repositoryRoot, repositoryRoot, platform)
    && samePath(state?.indexPath, indexPath, platform);
}

function statusOutput(status, includeLocalPaths) {
  return includeLocalPaths ? status : sanitizeRepositoryIndexStatus(status);
}

async function verifyEngineForStatus(status, options) {
  try {
    const engine = await verifyManagedTgrep(options);
    status.engineVersion = engine.engineVersion;
    status.managedBinary = engine.managed;
    status.overridden = engine.overridden;
    status.binaryPath = engine.binaryPath;
    return engine;
  } catch (error) {
    const missing = error.code === REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING;
    healthResult(status, missing ? "ENGINE_MISSING" : "ENGINE_INVALID", {
      code: error.code ?? REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING,
      message: error.message,
      path: error.path,
    });
    return null;
  }
}

export async function discoverTaskSummaries(target, packageRoot = getPackageRoot(), { taskKeys = null } = {}) {
  return discoverTasksInScope(target, packageRoot, taskKeys, DISCOVERY_PROJECTIONS.SUMMARY);
}

async function discoverTasksInScope(target, packageRoot, taskKeys, projection) {
  return withProjectReadSnapshot(target,
    () => discoverSelectedTasks(target, packageRoot, taskKeys, projection));
}

function projectTaskSummary(task) {
  return {
    taskId: task.taskId,
    healthy: task.healthy !== false,
    phase: task.phase ?? null,
    mutationAllowed: task.mutationAllowed !== false,
  };
}

function compareDiscoveredTasks(a, b) {
  return (a.taskId ?? a.taskKey).localeCompare(b.taskId ?? b.taskKey);
}

function appendDiscoveredTask(tasks, task, projection, fallbackSortKey = null, collect = null) {
  if (collect) { collect(task, fallbackSortKey); return; }
  if (projection === DISCOVERY_PROJECTIONS.FULL) {
    tasks.push(task);
    return;
  }
  tasks.push({ sortKey: task.taskId ?? task.taskKey ?? fallbackSortKey, value: task });
}

function finishDiscoveredTasks(tasks, projection) {
  if (projection !== DISCOVERY_PROJECTIONS.FULL) {
    return tasks.sort((a, b) => a.sortKey.localeCompare(b.sortKey)).map(({ value }) => value);
  }
  return tasks.sort(compareDiscoveredTasks);
}

export async function discoverTaskListEntries(target, packageRoot = getPackageRoot(), { taskKeys = null } = {}) {
  return discoverTasksInScope(target, packageRoot, taskKeys, DISCOVERY_PROJECTIONS.TASK_LIST);
}

function projectTaskList(task) {
  if (task.healthy === false) {
    return {
      taskId: task.taskId ?? null,
      taskKey: task.taskKey,
      directory: task.directory,
      healthy: false,
      error: task.error,
    };
  }
  return {
    taskId: task.taskId,
    taskKey: task.taskKey,
    directory: task.directory,
    healthy: true,
    phase: task.phase,
    writeClaims: task.writeClaims ?? [],
    historicalWriteClaims: task.historicalWriteClaims ?? [],
    effectiveWriteClaims: task.effectiveWriteClaims ?? [],
    claimState: task.claimState,
    recovery: task.recovery,
    mutationAllowed: task.mutationAllowed,
    ownershipValid: task.ownershipValid,
    ownershipErrors: task.ownershipErrors ?? task.errors ?? [],
    reasonCodes: task.reasonCodes ?? [],
    locked: task.locked,
    hasContinuity: task.hasContinuity,
    hasReceipt: task.hasReceipt,
    createdAt: task.createdAt,
    updatedAt: task.updatedAt,
  };
}

function projectTask(task, projection) {
  if (projection === DISCOVERY_PROJECTIONS.FULL) return task;
  if (projection === DISCOVERY_PROJECTIONS.SUMMARY) return projectTaskSummary(task);
  return projectTaskList(task);
}

export async function discoverTaskListPage(target, packageRoot = getPackageRoot(), { phase, active, offset, limit }) {
  const retained = [];
  let total = 0;
  const capacity = limit === null ? Infinity : limit === 0 ? 0 : offset + limit;
  const collect = (task, fallbackSortKey) => {
    if ((phase && task.phase !== phase) || (active && (task.claimState !== "ACTIVE" || task.mutationAllowed !== true))) return;
    total += 1;
    if (capacity === 0) return;
    const entry = { sortKey: task.taskId ?? task.taskKey ?? fallbackSortKey, value: task };
    if (capacity === Infinity) { retained.push(entry); return; }
    let low = 0, high = retained.length;
    while (low < high) {
      const middle = Math.floor((low + high) / 2);
      if (retained[middle].sortKey.localeCompare(entry.sortKey) <= 0) low = middle + 1;
      else high = middle;
    }
    if (low >= capacity) return;
    retained.splice(low, 0, entry);
    if (retained.length > capacity) retained.pop();
  };
  await withProjectReadSnapshot(target,
    () => discoverSelectedTasks(target, packageRoot, null, DISCOVERY_PROJECTIONS.TASK_LIST, collect));
  if (capacity === Infinity) retained.sort((a, b) => a.sortKey.localeCompare(b.sortKey));
  return { tasks: retained.slice(offset).map(entry => entry.value), total };
}

const collect = (task, fallbackSortKey) => {
  if ((phase && task.phase !== phase) || (active && (task.claimState !== "ACTIVE" || task.mutationAllowed !== true))) return;
  total += 1;
  if (capacity === 0) return;
  const entry = { sortKey: task.taskId ?? task.taskKey ?? fallbackSortKey, value: task };
  if (capacity === Infinity) { retained.push(entry); return; }
  let low = 0, high = retained.length;
  while (low < high) {
    const middle = Math.floor((low + high) / 2);
    if (retained[middle].sortKey.localeCompare(entry.sortKey) <= 0) low = middle + 1;
    else high = middle;
  }
  if (low >= capacity) return;
  retained.splice(low, 0, entry);
  if (retained.length > capacity) retained.pop();
};

export async function listCanonicalHandoffs(target, { taskId, packageRoot = getPackageRoot() } = {}) {
  return withProjectReadSnapshot(target, async () => {
    const directory = taskHandoffDirectory(taskId);
    let names = listOperationalArtifactNames(target, taskId, "handoffs");
    if (names === null) {
      if (!(await fileExists(ensureWithin(target, directory)))) return [];
      names = (await readdir(ensureWithin(target, directory), { withFileTypes: true })).filter(entry => entry.isFile()).map(entry => entry.name);
    }
    const handoffs = [];
    for (const name of names) {
      if (!/^handoff-[A-Za-z0-9_-]+\.json$/u.test(name)) continue;
      const handoffId = name.slice(0, -5);
      const artifact = await readCanonicalHandoff(target, { taskId, handoffId, packageRoot });
      handoffs.push(artifact.value);
    }
    return handoffs.sort((left, right) => left.createdAt.localeCompare(right.createdAt) || left.handoffId.localeCompare(right.handoffId));
  });
}

