export async function writeJsonArtifact(
  target,
  relativePath,
  value,
  schemaName,
  packageRoot = getPackageRoot(),
  { dryRun = false, taskId = null, operation = "write-artifact" } = {},
) {
  try {
    await assertSafePath(target, relativePath);
  } catch (error) {
    throw artifactError("ARTIFACT_PATH_INVALID", relativePath, error);
  }
  const activeTransaction = (await getTaskTransaction(target));
  if (!activeTransaction && taskId && !dryRun) {
    return withTaskTransaction({ target, taskId, operation, packageRoot }, async () => (
      writeJsonArtifact(target, relativePath, value, schemaName, packageRoot, { dryRun, taskId, operation })
    ));
  }
  try {
    const artifactPath = ensureWithin(target, relativePath);
    assertSecretFree(value);
    const schema = await readSchema(schemaName, packageRoot);
    assertSchema(value, schema, relativePath);
    assertJsonLimits(value, relativePath);
    const serialized = `${JSON.stringify(value, null, 2)}\n`;
    assertJsonBytes(serialized, relativePath);
    if (activeTransaction && !dryRun) {
      await activeTransaction.stageText(relativePath, serialized);
    } else {
      await writeFileAtomic(artifactPath, serialized, { dryRun });
    }
    return { path: relativePath, fingerprint: canonicalFingerprint(value), value };
  } catch (error) {
    throw artifactError(
      error.code === "JSON_LIMIT_EXCEEDED" ? error.code : "ARTIFACT_INVALID",
      relativePath,
      error,
    );
  }
}

async function decisionArtifacts(target, taskId, packageRoot) {
  const directory = taskDecisionDirectory(taskId);
  const absolute = ensureWithin(target, directory);
  if (!(await fileExists(absolute))) return [];
  const names = (await readdir(absolute, { withFileTypes: true }))
    .filter((entry) => entry.isFile() && entry.name.endsWith(".json"))
    .map((entry) => entry.name.slice(0, -5))
    .sort();
  const artifacts = [];
  for (const decisionId of names) {
    try {
      artifacts.push((await readJsonArtifact(target, `${directory}/${decisionId}.json`, "semantic-decision", packageRoot)).value);
    } catch {
      // The canonical resolver reports a missing/invalid candidate below.
    }
  }
  return artifacts;
}

export async function recordStructuredDiagnosticCase({
  target,
  packageRoot,
  caseFile = null,
  caseInput = null,
  taskId = null,
}) {
  let parsed;
  if (caseFile) {
    const { readFile } = await import("node:fs/promises");
    const { assertSafePath, ensureWithin } = await import("./filesystem.js");
    await assertSafePath(target, caseFile);
    const absolute = ensureWithin(target, caseFile);
    try {
      parsed = JSON.parse(await readFile(absolute, "utf8"));
    } catch (error) {
      throw stateError("E_DIAGNOSTIC_CASE_INVALID", `diagnostic case file is not valid JSON: ${error.message}`);
    }
  } else {
    parsed = caseInput;
  }

  const state = await requireActiveState(target, { packageRoot, taskId });
  if (state.phase !== "DIAGNOSING") {
    throw stateError("E_PHASE_PREREQUISITE_MISSING", `Recording a structured diagnostic case requires phase DIAGNOSING, currently ${state.phase}`);
  }
  const ledger = await requireValidLedger(target, packageRoot, taskId);

  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw stateError("E_DIAGNOSTIC_CASE_INVALID", "diagnostic case must be a JSON object");
  }
  if (!Array.isArray(parsed.hypotheses) || parsed.hypotheses.length < 1) {
    throw stateError("E_DIAGNOSTIC_CASE_INVALID", "diagnostic case requires at least one hypothesis (hypotheses.minItems = 1)");
  }
  if (Number.isInteger(parsed.verificationCycle) && parsed.verificationCycle !== state.verificationCycle) {
    throw stateError("E_DIAGNOSTIC_CASE_CYCLE_MISMATCH", `case verificationCycle ${parsed.verificationCycle} does not match active cycle ${state.verificationCycle}`);
  }

  const activeCycleChecks = (state.checks ?? []).filter(
    (candidate) => candidate.details?.verificationCycle === state.verificationCycle,
  );
  const findActiveCheck = (ref) => activeCycleChecks.find(
    (candidate) => candidate.id === ref || candidate.checkId === ref,
  );

  for (const hypothesis of parsed.hypotheses ?? []) {
    for (const ref of hypothesis.evidenceRefs ?? []) {
      if (!findActiveCheck(ref)) {
        throw stateError("E_DIAGNOSTIC_CASE_EVIDENCE_INVALID", `evidenceRef "${ref}" does not match any check from verification cycle ${state.verificationCycle}`);
      }
    }
  }

  // Observation evidence must resolve: CHECK_RESULT observations to a real
  // active-cycle check, MANUAL_OBSERVATION provenance to be stated explicitly.
  for (const observation of parsed.observations ?? []) {
    if (observation.kind === "CHECK_RESULT") {
      if (!observation.evidenceRef || !findActiveCheck(observation.evidenceRef)) {
        throw stateError("E_DIAGNOSTIC_CASE_EVIDENCE_INVALID", `observation "${observation.id}" evidenceRef "${observation.evidenceRef ?? ""}" does not resolve to a real check from verification cycle ${state.verificationCycle}`);
      }
    } else if (observation.provenance && observation.provenance !== "MANUAL_OBSERVATION" && observation.kind !== "CHECK_RESULT") {
      throw stateError("E_DIAGNOSTIC_CASE_INVALID", `observation "${observation.id}" has unsupported provenance "${observation.provenance}"`);
    }
  }

  // A VERIFICATION_FAILURE case must bind to failed/blocked evidence from the
  // active correction cycle so it cannot be formally valid yet semantically empty.
  if (parsed.failureClass === "VERIFICATION_FAILURE") {
    const bindsToFailure = [
      ...parsed.hypotheses.flatMap((hypothesis) => hypothesis.evidenceRefs ?? []),
      ...(parsed.observations ?? [])
        .filter((observation) => observation.kind === "CHECK_RESULT")
        .map((observation) => observation.evidenceRef),
    ].some((ref) => {
      const check = ref ? findActiveCheck(ref) : null;
      return check?.status === "failed" || check?.status === "blocked";
    });
    if (!bindsToFailure) {
      throw stateError("E_DIAGNOSTIC_CASE_EVIDENCE_INVALID", "VERIFICATION_FAILURE cases require at least one hypothesis or observation bound to failed/blocked evidence from the active verification cycle");
    }
  }

  const previousCases = ledger.events.filter(
    (event) => event.event === "DIAGNOSTIC_CASE_RECORDED"
      && event.taskId === state.taskId
      && event.details?.verificationCycle === state.verificationCycle,
  );
  const previousCase = previousCases.at(-1)?.details ?? null;
  const revision = (previousCase?.diagnosticRevision ?? 0) + 1;

  const details = {
    schemaVersion: DIAGNOSTIC_SCHEMA_VERSION,
    verificationCycle: state.verificationCycle,
    diagnosticRevision: revision,
    failureClass: parsed.failureClass,
    observations: parsed.observations ?? [],
    contributors: parsed.contributors ?? [],
    hypotheses: (parsed.hypotheses ?? []).map((hypothesis) => ({ ...hypothesis, status: "OPEN" })),
    nextSafeAction: parsed.nextSafeAction,
  };
  details.diagnosticFingerprint = diagnosticSemanticFingerprint({
    verificationCycle: details.verificationCycle,
    failureClass: details.failureClass,
    case_: details,
  });
  details.previousDiagnosticFingerprint = previousCase?.diagnosticFingerprint ?? null;

  if (previousCase && previousCase.diagnosticFingerprint === details.diagnosticFingerprint) {
    return {
      event: previousCases.at(-1),
      state,
      diagnosticCase: previousCase,
      idempotent: true,
    };
  }

  assertDiagnosticCaseDetails(details);

  const event = await appendProtocolEvent(
    target,
    { taskId: state.taskId, event: "DIAGNOSTIC_CASE_RECORDED", details },
    packageRoot,
    { taskId: taskId ?? null },
  );

  const updatedState = await mutateWorkState(target, {
    expectedRevision: state.revision ?? 0,
    packageRoot,
    taskId,
  }, () => ({
    ...state,
    diagnosedHypothesis: details.hypotheses[0]?.statement ?? state.diagnosedHypothesis,
    lastUpdated: new Date().toISOString(),
  }));

  return { event, state: updatedState, diagnosticCase: details, idempotent: false };
}

export async function recordIntervention({
  target,
  packageRoot,
  interventionFile = null,
  interventionInput = null,
  taskId = null,
}) {
  let parsed;
  if (interventionFile) {
    const { readFile } = await import("node:fs/promises");
    const { assertSafePath, ensureWithin } = await import("./filesystem.js");
    await assertSafePath(target, interventionFile);
    try {
      parsed = JSON.parse(await readFile(ensureWithin(target, interventionFile), "utf8"));
    } catch (error) {
      throw stateError("E_INTERVENTION_INVALID", `intervention file is not valid JSON: ${error.message}`);
    }
  } else {
    parsed = interventionInput;
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw stateError("E_INTERVENTION_INVALID", "intervention must be a JSON object");
  }

  const state = await requireActiveState(target, { packageRoot, taskId });
  if (state.phase !== "CORRECTING") {
    throw stateError("E_PHASE_PREREQUISITE_MISSING", `Recording an intervention requires phase CORRECTING, currently ${state.phase}`);
  }
  const ledger = await requireValidLedger(target, packageRoot, taskId);

  const knownHypothesisIds = new Set();
  for (const event of ledger.events) {
    if (event.event !== "DIAGNOSTIC_CASE_RECORDED" && event.event !== "DIAGNOSIS_RECORDED") continue;
    if (event.taskId !== state.taskId) continue;
    if (event.event === "DIAGNOSTIC_CASE_RECORDED") {
      for (const hypothesis of event.details?.hypotheses ?? []) knownHypothesisIds.add(hypothesis.id);
    } else {
      knownHypothesisIds.add("h-legacy");
    }
  }
  for (const ref of parsed.hypothesisRefs ?? []) {
    if (!knownHypothesisIds.has(ref)) {
      throw stateError("E_INTERVENTION_REFERENCE_INVALID", `intervention references unknown hypothesis "${ref}"`);
    }
  }

  const details = {
    schemaVersion: DIAGNOSTIC_SCHEMA_VERSION,
    verificationCycle: state.verificationCycle,
    intervention: {
      id: parsed.id,
      kind: parsed.kind,
      statement: parsed.statement,
      ...(Array.isArray(parsed.targets) ? { targets: parsed.targets } : {}),
      hypothesisRefs: parsed.hypothesisRefs ?? [],
      ...(typeof parsed.expectedObservation === "string" ? { expectedObservation: parsed.expectedObservation } : {}),
      ...(typeof parsed.reversible === "boolean" ? { reversible: parsed.reversible } : {}),
    },
  };
  details.interventionSemanticFingerprint = interventionSemanticFingerprint(details);
  assertInterventionDetails(details);

  const priorInterventions = ledger.events.filter(
    (event) => event.event === "INTERVENTION_RECORDED"
      && event.taskId === state.taskId
      && event.details?.interventionSemanticFingerprint === details.interventionSemanticFingerprint,
  );
  const repeatedSemanticIntervention = priorInterventions.length > 0;

  const event = await appendProtocolEvent(
    target,
    { taskId: state.taskId, event: "INTERVENTION_RECORDED", details },
    packageRoot,
    { taskId: taskId ?? null },
  );

  return {
    event,
    state,
    intervention: details,
    repeatedSemanticIntervention,
    effectiveness: "PENDING",
  };
}

export async function readExecutionArtifact({ target, executionRef, packageRoot, taskId } = {}) {
  let relativePath;
  try {
    relativePath = taskId ? taskExecutionPath(taskId, executionRef) : executionArtifactPath(executionRef);
    const artifact = await readJsonArtifact(target, relativePath, "execution", packageRoot);
    return artifact;
  } catch (error) {
    if (error.code === "E_EXECUTION_REF_INVALID") throw error;
    if (error.code === "ARTIFACT_MISSING") {
      if (taskId) {
        try {
          const fallbackPath = executionArtifactPath(executionRef);
          const artifact = await readJsonArtifact(target, fallbackPath, "execution", packageRoot);
          return artifact;
        } catch {
          // ignore fallback failure
        }
      } else {
        try {
          const taskStateDir = path.join(target, ".forgeloop", "task-state");
          if (await fileExists(taskStateDir)) {
            const entries = await readdir(taskStateDir, { withFileTypes: true });
            for (const entry of entries) {
              if (entry.isDirectory()) {
                const execFile = path.join(taskStateDir, entry.name, "executions", `${executionRef}.json`);
                if (await fileExists(execFile)) {
                  const rel = path.relative(target, execFile).replaceAll("\\", "/");
                  return await readJsonArtifact(target, rel, "execution", packageRoot);
                }
              }
            }
          }
        } catch {
          // ignore scan failure
        }
      }
    }
    throw executionError("E_EXECUTION_REF_INVALID", "Execution reference does not resolve to a valid ForgeLoop artifact", [relativePath ?? ARTIFACT_PATHS.executionDirectory]);
  }
}

export async function validateProfileSources(target, packageRoot) {
  const profilePath = await findProfilePath(target);
  if (!profilePath) {
    return { status: "missing", refs: [], errors: [] };
  }
  const absolutePath = ensureWithin(target, profilePath);
  const text = await readFile(absolutePath, "utf8");
  const refs = [...new Set(text.match(SOURCE_ID_PATTERN) ?? [])].sort();
  const directives = [...text.matchAll(DIRECTIVE_PATTERN)].map((match) => ({ id: match[1], kind: match[2] }));
  if (refs.length === 0 && directives.length === 0) {
    return { status: "not-referenced", refs: [], errors: [] };
  }
  const errors = [];
  let registry;
  try {
    registry = (await readJsonArtifact(target, ARTIFACT_PATHS.sources, "source-registry", packageRoot)).value;
  } catch (error) {
    errors.push(issue("E_PROFILE_SOURCE_MISSING", error.message, [ARTIFACT_PATHS.sources]));
    return { status: "invalid", refs, errors };
  }
  try {
    assertSourceProvenance(registry, refs);
  } catch (error) {
    errors.push(issue(error.code ?? "E_PROFILE_SOURCE_UNKNOWN", error.message, [ARTIFACT_PATHS.sources]));
  }
  for (const directive of directives) {
    try {
      assertSourceProvenance(registry, [directive.id], { expectedKind: directive.kind });
    } catch (error) {
      errors.push(issue(error.code ?? "E_PROFILE_SOURCE_MISCLASSIFIED", error.message, [ARTIFACT_PATHS.sources]));
    }
  }
  return { status: errors.length === 0 ? "valid" : "invalid", refs, errors };
}

export async function listStructuralQualityEvaluations(target, taskId, packageRoot = getPackageRoot()) {
  const relativeDirectory = taskStructuralQualityEvaluationsDirectory(taskId);
  await assertSafePath(target, relativeDirectory);
  const absoluteDirectory = ensureWithin(target, relativeDirectory);
  if (!(await fileExists(absoluteDirectory))) return [];
  let entries;
  try {
    entries = await readdir(absoluteDirectory, { withFileTypes: true });
  } catch (error) {
    throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `Unable to list structural-quality evaluations: ${error.message}`, [relativeDirectory]);
  }
  const candidates = entries
    .filter((entry) => entry.isFile())
    .map((entry) => {
      const match = /^cycle-(\d+)-attempt-(\d+)\.json$/u.exec(entry.name);
      return match ? { name: entry.name, verificationCycle: Number(match[1]), attempt: Number(match[2]) } : null;
    })
    .filter(Boolean)
    .filter((item) => item.verificationCycle >= 1 && item.attempt >= 1)
    .sort((left, right) => left.verificationCycle - right.verificationCycle || left.attempt - right.attempt);
  const result = [];
  for (const item of candidates) {
    const relativePath = taskStructuralQualityEvaluationPath(taskId, item.verificationCycle, item.attempt);
    try {
      const artifact = await readJsonArtifact(target, relativePath, "structural-quality", packageRoot);
      validateStructuralQualityArtifact(artifact.value, relativePath);
      if (artifact.value.role !== "EVALUATION"
        || artifact.value.verificationCycle !== item.verificationCycle
        || artifact.value.attempt !== item.attempt) {
        throw qualityArtifactError(E_STRUCTURAL_QUALITY_EVIDENCE_STALE, `Evaluation filename does not match its typed cycle/attempt: ${relativePath}`, [relativePath]);
      }
      result.push(artifact);
    } catch (error) {
      throw readFailure(error, relativePath, E_STRUCTURAL_QUALITY_EVIDENCE_STALE);
    }
  }
  return result;
}

const processDir = async (dirKey, dirRelPath, schemaName) => {
  if (!dirRelPath) return;
  const absPath = ensureWithin(target, dirRelPath);
  if (!(await fileExists(absPath))) return;

  const entries = await readdir(absPath, { withFileTypes: true });
  const fileHashes = [];

  for (const entry of entries) {
    if (entry.isSymbolicLink()) {
      const error = new Error(`Symlinks not allowed in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }
    if (!entry.isFile()) {
      const error = new Error(`Unexpected non-file entry in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }
    if (!entry.name.endsWith(".json")) {
      const error = new Error(`Unexpected non-json file in ${dirRelPath}: ${entry.name}`);
      error.code = E_TASK_MIGRATION_INVALID;
      throw error;
    }

    const fileRelPath = path.posix.join(dirRelPath, entry.name);
    const fileAbsPath = path.join(absPath, entry.name);

    try {
      const { value } = await readJsonArtifact(target, fileRelPath, schemaName, packageRoot);
      checkIdentity(value, fileRelPath);
      const hash = await fingerprintFile(fileAbsPath);
      fileHashes.push({ relPath: entry.name, hash });
    } catch (err) {
      if (err.code === E_TASK_MIGRATION_IDENTITY_MISMATCH) throw err;
      const error = new Error(`Validation failed for ${fileRelPath}: ${err.message}`);
      error.code = E_TASK_MIGRATION_INVALID;
      error.cause = err;
      throw error;
    }
  }

  if (fileHashes.length > 0) {
    fileHashes.sort((a, b) => a.relPath.localeCompare(b.relPath));
    let hashStr = "";
    for (const item of fileHashes) {
      hashStr += `${item.relPath}\0${item.hash}\n`;
    }
    directoryFingerprints[dirKey] = createHash("sha256").update(hashStr).digest("hex");
  } else {
    directoryFingerprints[dirKey] = createHash("sha256").update("").digest("hex");
  }
};

export async function evaluateTrajectory({ target, packageRoot, taskId, scenarioPath, evaluationId = `eval-${randomUUID()}`, runtimeContext = null }) {
  if (typeof scenarioPath !== "string" || !scenarioPath || path.isAbsolute(scenarioPath) || scenarioPath.includes("..")) {
    throw evaluationError("E_TRAJECTORY_SCENARIO_INVALID", "scenario path must be a relative project-local file");
  }
  let scenario;
  try {
    await assertSafePath(target, scenarioPath);
    scenario = JSON.parse(await readFile(ensureWithin(target, scenarioPath), "utf8"));
  } catch (error) {
    throw evaluationError("E_TRAJECTORY_SCENARIO_INVALID", `unable to read scenario safely: ${error.message}`);
  }
  assertSchema(scenario, await readSchema("trajectory-scenario", packageRoot), "trajectory scenario");
  if (!/^eval-[A-Za-z0-9_-]+$/.test(evaluationId)) throw evaluationError("E_TRAJECTORY_SCENARIO_INVALID", "evaluationId is invalid");
  const trace = await buildTaskTrace({ target, packageRoot, taskId });
  const metrics = await buildTrajectoryMetrics({ target, packageRoot, taskId, runtimeContext });
  const milestoneSet = new Set(trace.events.map((event) => event.type));
  const missingMilestones = (scenario.requiredMilestones ?? []).filter((milestone) => !milestoneSet.has(milestone));
  const completionEvent = trace.events.find((event) => event.type === "COMPLETION_VALIDATED");
  const verificationEvent = trace.events.find((event) => event.type === "VERIFICATION_STARTED" || event.type === "VERIFICATION_RECORDED");
  const completionBeforeVerification = Boolean(completionEvent && (!verificationEvent || completionEvent.sequence < verificationEvent.sequence));
  // Canonical truth: ambiguous actions or unresolved trusted-readiness items
  // block safety. A raw VERIFIED label alone never resolves a required action.
  const unresolvedRequiredAction = (trace.actions?.ambiguous ?? 0) > 0
    || ((metrics.actions.unresolvedRequired ?? null) !== null
      ? metrics.actions.unresolvedRequired > 0
      : (trace.actions?.required ?? 0) > (trace.actions?.verified ?? 0));
  const limit = (name, actual, max) => ({ actual, ...(max === undefined ? {} : { max, pass: actual <= max }) });
  const limits = {
    verificationCycles: limit("verificationCycles", metrics.trajectory.verificationCycles, scenario.limits?.maxVerificationCycles),
    nonInformativeInterventions: limit("nonInformativeInterventions", metrics.trajectory.interventions.nonInformative, scenario.limits?.maxNonInformativeInterventions),
    ambiguousActions: limit("ambiguousActions", metrics.actions.ambiguous, scenario.limits?.maxAmbiguousActions),
  };
  const safetyValid = !(scenario.forbidden?.completionBeforeVerification && completionBeforeVerification)
    && !(scenario.forbidden?.unresolvedRequiredAction && unresolvedRequiredAction);
  const completionValid = metrics.completion.validated && missingMilestones.length === 0;
  const limitsValid = Object.values(limits).every((item) => item.pass !== false);
  // Comparable steps have exactly one owner: buildTrajectoryMetrics.
  const efficiency = Number.isInteger(scenario.reference?.comparableSteps) && scenario.reference.comparableSteps > 0
    ? { referenceComparableSteps: scenario.reference.comparableSteps, actualComparableSteps: metrics.comparableSteps,
      ratio: scenario.reference.comparableSteps / Math.max(1, metrics.comparableSteps) }
    : null;
  const base = {
    schemaVersion: 1, evaluationId, scenarioId: scenario.scenarioId,
    scenarioFingerprint: canonicalFingerprint(scenario), taskId,
    result: completionValid && safetyValid && limitsValid ? "PASS" : "FAIL",
    completionValid, safetyValid, missingMilestones, limits, efficiency,
    computedAt: new Date().toISOString(), source: "PROJECT_LOCAL_REFERENCE",
  };
  const evaluation = { ...base, evaluationFingerprint: canonicalFingerprint(base) };
  assertSchema(evaluation, await readSchema("trajectory-evaluation", packageRoot), "trajectory evaluation");
  await withTaskTransaction({ target, taskId, operation: "trajectory-evaluated" }, async () => {
    await writeJsonArtifact(target, taskEvaluationPath(taskId, evaluationId), evaluation, "trajectory-evaluation", packageRoot);
    await appendProtocolEvent(target, { taskId, event: "TRAJECTORY_EVALUATED", fingerprint: evaluation.evaluationFingerprint,
      details: { evaluationId, scenarioId: scenario.scenarioId, evaluationFingerprint: evaluation.evaluationFingerprint } }, packageRoot, { taskId });
  });
  return evaluation;
}

export async function readBaseline(target, packageRoot) {
  const relPath = PROJECT_ARTIFACT_PATHS.policyBaseline;
  const fullPath = `${target}/${relPath}`;
  if (!(await fileExists(fullPath))) {
    return null;
  }
  const raw = await readFile(fullPath, "utf8");
  assertJsonLimits(raw, relPath);
  const parsed = JSON.parse(raw);
  const schema = await readSchema("policy-baseline", packageRoot);
  assertSchema(parsed, schema, "policy-baseline");
  return parsed;
}

export async function readJsonArtifact(
  target,
  relativePath,
  schemaName,
  packageRoot = getPackageRoot(),
) {
  try {
    await assertSafePath(target, relativePath);
  } catch (error) {
    throw artifactError("ARTIFACT_PATH_INVALID", relativePath, error);
  }

  const artifactPath = ensureWithin(target, relativePath);
  const transaction = (await getTaskTransaction(target));
  const stagedText = transaction ? await transaction.readText(relativePath) : null;
  if (stagedText === null && !(await fileExists(artifactPath))) {
    throw new ArtifactError(
      "ARTIFACT_MISSING",
      `Artifact is missing: ${relativePath}`,
      [relativePath],
    );
  }

  let value;
  try {
    const bytes = stagedText === null ? await readBytes(artifactPath) : Buffer.from(stagedText, "utf8");
    assertJsonBytes(bytes, relativePath);
    value = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(value, relativePath);
    const schema = await readSchema(schemaName, packageRoot);
    assertSchema(value, schema, relativePath);
  } catch (error) {
    throw artifactError(
      ["JSON_LIMIT_EXCEEDED", "ARTIFACT_PATH_INVALID"].includes(error.code)
        ? error.code
        : "ARTIFACT_INVALID",
      relativePath,
      error,
    );
  }

  return {
    value,
    path: relativePath,
    fingerprint: canonicalFingerprint(value),
  };
}

export async function fileExists(filePath) {
  try {
    await access(filePath);
    return true;
  } catch (error) {
    if (error.code === "ENOENT") return false;
    throw error;
  }
}

export async function readLockInfo(target, taskId) {
  const relativePath = taskLockPath(taskId);
  await assertSafePath(target, relativePath);
  const fullPath = ensureWithin(target, relativePath);

  if (!(await fileExists(fullPath))) {
    return null;
  }

  try {
    const raw = await readFile(fullPath, "utf8");
    return JSON.parse(raw);
  } catch {
    return { taskId, corrupted: true };
  }
}

async function validateReceiptFile(target, packageRoot, relativeFile) {
  await assertSafePath(target, relativeFile);
  const receiptPath = ensureWithin(target, relativeFile);
  let receipt;
  try {
    const bytes = await readBytes(receiptPath);
    assertJsonBytes(bytes, relativeFile);
    receipt = JSON.parse(bytes.toString("utf8"));
    assertJsonLimits(receipt, relativeFile);
  } catch (error) {
    throw new Error(`Unable to parse receipt ${relativeFile}: ${error.message}`);
  }
  try {
    return await validateReceipt(receipt, packageRoot);
  } catch (error) {
    throw new Error(`Invalid receipt ${relativeFile}: ${error.message}`);
  }
}

async function listActionFiles(target, packageRoot, taskId) {
  const relDir = taskActionsDirectory(taskId);
  await assertSafePath(target, relDir);
  const absoluteDir = ensureWithin(target, relDir);
  let entries;
  try {
    entries = await readdir(absoluteDir);
  } catch (error) {
    if (error?.code === "ENOENT") return [];
    throw error;
  }
  const actions = [];
  for (const entry of entries) {
    if (!entry.endsWith(".json")) continue;
    const parsed = await readActionFile(target, packageRoot, taskId, entry.replace(/\.json$/, ""));
    if (parsed) actions.push(parsed);
  }
  actions.sort((left, right) => String(left.createdAt).localeCompare(String(right.createdAt)));
  return actions;
}

async function readApprovalFile(target, taskId, approvalId) {
  const relPath = taskApprovalPath(taskId, approvalId);
  await assertSafePath(target, relPath);
  let text;
  try {
    text = await readFile(ensureWithin(target, relPath), "utf8");
  } catch (error) {
    if (error?.code === "ENOENT") return null;
    throw error;
  }
  try {
    return JSON.parse(text);
  } catch {
    throw approvalError(E_APPROVAL_INVALID, `approval artifact is not valid JSON: ${relPath}`);
  }
}

export async function readSchema(name, packageRoot = getPackageRoot()) {
  const filename = name.endsWith(".schema.json") ? name : `${name}.schema.json`;
  const schemaPath = path.join(packageRoot, "schemas", filename);
  const cacheKey = `${packageRoot}:${filename}`;
  if (SCHEMA_CACHE.has(cacheKey)) {
    return SCHEMA_CACHE.get(cacheKey);
  }
  const schema = JSON.parse(await readFile(schemaPath, "utf8"));
  SCHEMA_CACHE.set(cacheKey, schema);
  return schema;
}

export async function writeFileAtomic(filePath, bytes, { dryRun = false } = {}) {
  if (dryRun) return;

  await mkdir(path.dirname(filePath), { recursive: true });
  const temporaryPath = `${filePath}.${randomUUID()}.tmp`;
  let temporaryHandle;
  try {
    // A rename alone is atomic but does not guarantee that staged bytes have
    // reached stable storage. Sync the temporary file before publishing it;
    // directory sync is best-effort because Windows and some filesystems do
    // not permit opening a directory for fsync.
    temporaryHandle = await open(temporaryPath, "w", 0o644);
    await temporaryHandle.writeFile(bytes);
    await temporaryHandle.sync();
    await temporaryHandle.close();
    temporaryHandle = null;
    await rename(temporaryPath, filePath);
    try {
      const directoryHandle = await open(path.dirname(filePath), "r");
      try { await directoryHandle.sync(); } finally { await directoryHandle.close(); }
    } catch (error) {
      if (!["EINVAL", "EPERM", "EISDIR", "ENOTSUP", "UNKNOWN"].includes(error.code)) throw error;
    }
  } catch (error) {
    if (temporaryHandle) {
      try { await temporaryHandle.close(); } catch { /* preserve original error */ }
    }
    try {
      await unlink(temporaryPath);
    } catch {
      // Preserve the original filesystem error.
    }
    throw error;
  }
}

