export async function readRequiredArtifactFingerprints(target, artifacts) {
  const normalized = normalizeRequiredArtifacts(artifacts);
  const current = [];
  for (const artifact of normalized) {
    await assertSafePath(target, artifact.path);
    const artifactPath = ensureWithin(target, artifact.path);
    if (!(await fileExists(artifactPath))) {
      current.push({ path: artifact.path, sha256: null, status: "missing" });
      continue;
    }
    current.push({
      path: artifact.path,
      sha256: createHash("sha256").update(await readBytes(artifactPath)).digest("hex"),
      status: "present",
    });
  }
  return current;
}

export async function readGuideMetadata(packageRoot) {
  const metadata = {};
  for (const [id, relativePath] of Object.entries(GUIDE_FILES)) {
    const text = await readFile(path.join(packageRoot, relativePath), "utf8");
    const parsed = parseFrontmatter(text, relativePath);
    metadata[id] = {
      guideId: parsed.guideId ?? id,
      lastReviewed: parsed.lastReviewed,
      version: parsed.version,
      requiresGates: [...parsed.requiresGates],
      completionEvidence: [...parsed.completionEvidence],
      path: relativePath,
    };
  }
  return metadata;
}

export async function acquireProjectClaimsLock(target, operation = "claim-reservation") {
  await assertSafePath(target, CLAIMS_LOCK_REL_PATH);
  const fullPath = ensureWithin(target, CLAIMS_LOCK_REL_PATH);

  await mkdir(path.dirname(fullPath), { recursive: true });

  const acquiredAt = new Date().toISOString();
  const lockData = {
    lockId: randomUUID(),
    scope: "claims-reservation",
    operation,
    pid: process.pid,
    hostname: os.hostname(),
    processStartToken: currentProcessStartToken(),
    ownerInstanceId: randomUUID(),
    acquiredAt,
    heartbeatAt: acquiredAt,
    leaseMs: 300000,
  };

  let fileHandle = null;
  for (let attempt = 0; attempt < 2; attempt += 1) {
    try {
      fileHandle = await open(fullPath, "wx");
      break;
    } catch (error) {
      if (error.code !== "EEXIST") throw error;
      const existing = await readProjectClaimsLockInfo(target);
      const classification = classifyProjectClaimsLock(existing);
      if (classification.status === "STALE" && attempt === 0) {
        const released = await releaseStaleProjectClaimsLockIfUnchanged(target, existing);
        if (released.released || released.reason === "LOCK_MISSING") continue;
        throw projectClaimsLockError(
          released.classification ?? { status: "UNKNOWN", stale: false },
          released.currentLock ?? existing,
          released.reason,
        );
      }
      throw projectClaimsLockError(classification, existing);
    }
  }
  if (!fileHandle) {
    throw projectClaimsLockError({ status: "UNKNOWN", stale: false }, null, "ACQUISITION_RETRY_EXHAUSTED");
  }

  try {
    await fileHandle.writeFile(`${JSON.stringify(lockData, null, 2)}\n`, "utf8");
    await fileHandle.close();
    return {
      lockData,
      release: async () => {
        try {
          const current = await readProjectClaimsLockInfo(target);
          if (current && current.lockId === lockData.lockId) {
            await unlink(fullPath);
          }
        } catch {
          // ignore
        }
      },
    };
  } catch (error) {
    try {
      await fileHandle.close();
    } catch {
      // ignore
    }
    try {
      await unlink(fullPath);
    } catch {
      // ignore
    }
    throw error;
  }
}

