async function adoptAdapters({ target, manifest, adoptPaths, findings }) {
  if (!manifest || adoptPaths.length === 0) return manifest;

  const nextManifest = structuredClone(manifest);
  let changed = false;

  for (const relativePath of adoptPaths) {
    if (!ADAPTER_PATHS.has(relativePath)) {
      findings.push(
        finding(
          "adopt-invalid-path",
          "error",
          relativePath,
          "Only supported adapter paths can be adopted.",
        ),
      );
      continue;
    }

    const destination = ensureWithin(target, relativePath);
    try {
      await assertSafePath(target, relativePath);
    } catch (error) {
      findings.push(finding("unsafe-path", "error", relativePath, error.message));
      continue;
    }
    if (!(await fileExists(destination))) {
      findings.push(finding("adopt-file-missing", "error", relativePath, "Adapter file is missing."));
      continue;
    }

    nextManifest.files[relativePath] = {
      sha256: sha256(await readBytes(destination)),
      preserve: true,
    };
    findings.push(
      finding(
        "file-adopted",
        "info",
        relativePath,
        "Existing adapter is now recorded as preserved by ForgeLoop.",
      ),
    );
    changed = true;
  }

  if (changed) await writeManifest(target, nextManifest);
  return nextManifest;
}

export async function writeManifest(target, manifest, { dryRun = false } = {}) {
  validateManifest(manifest);
  await assertSafePath(target, MANIFEST_PATH);
  const manifestPath = ensureWithin(target, MANIFEST_PATH);
  await writeFileAtomic(
    manifestPath,
    `${JSON.stringify(manifest, null, 2)}\n`,
    { dryRun },
  );
}

async function readMaterialFile(root, relativePath) {
  const fullPath = ensureWithin(root, relativePath);
  let info;
  try {
    info = await lstat(fullPath);
  } catch (error) {
    throw fingerprintError(`Unable to inspect structural-quality source material: ${relativePath}`, error);
  }
  if (info.isSymbolicLink()) {
    throw fingerprintError(`Structural-quality source material uses an unsafe symlink: ${relativePath}`);
  }
  if (!info.isFile()) {
    throw fingerprintError(`Structural-quality source material is not a regular file: ${relativePath}`);
  }
  try {
    return sha256(await readBytes(fullPath));
  } catch (error) {
    throw fingerprintError(`Unable to read structural-quality source material: ${relativePath}`, error);
  }
}

async function readMaterialFile(root, relativePath) {
