async function readPackageVersion() {
  const packageJson = await readFile(path.join(getPackageRoot(), "package.json"), "utf8");
  return JSON.parse(packageJson).version ?? null;
}

export async function loadTgrepManifest(packageRoot = getPackageRoot()) {
  if (typeof packageRoot !== "string" || packageRoot.trim() === "") {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, "ForgeLoop package root is required to load the tgrep manifest");
  }
  const manifestPath = path.join(packageRoot, "src", "repository-index", "tgrep-manifest.json");
  let value;
  try {
    value = JSON.parse(await readFile(manifestPath, "utf8"));
  } catch (cause) {
    throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `Unable to read ${manifestPath}: ${cause.message}`, { cause, manifestPath });
  }
  return assertManifest(value, manifestPath);
}

async function ensureRegularFile(filePath, code, label) {
  let info;
  try {
    info = await lstat(filePath);
  } catch (cause) {
    if (cause.code === "ENOENT") throw repositoryIndexError(code, `${label} is missing: ${filePath}`, { cause, path: filePath });
    throw repositoryIndexError(code, `${label} cannot be inspected: ${filePath}: ${cause.message}`, { cause, path: filePath });
  }
  if (info.isSymbolicLink() || !info.isFile()) {
    throw repositoryIndexError(code, `${label} must be a regular file: ${filePath}`, { path: filePath });
  }
  return info;
}

async function verifyExecutable(filePath, { platform = process.platform } = {}) {
  await ensureRegularFile(filePath, REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, "Managed tgrep binary");
  if (platform !== "win32") {
    try {
      await access(filePath, fsConstants.X_OK);
    } catch (cause) {
      throw repositoryIndexError(REPOSITORY_INDEX_ERROR_CODES.ENGINE_MISSING, `Managed tgrep binary is not executable: ${filePath}`, { cause, path: filePath });
    }
  }
}

export async function writePortableJsonArtifact(target, relativePath, value, schemaName, packageRoot = getPackageRoot(), { dryRun = false } = {}) {
  if (isOperationalArtifactPath(relativePath)) throw new ArtifactError("E_STORAGE_OPERATION_UNSUPPORTED", "Portable output cannot replace a canonical operational namespace", [relativePath]);
  assertNativeWritePath(target, relativePath);
  if (!dryRun && await getTaskTransaction(target)) throw new ArtifactError("E_STORAGE_TRANSACTION_INVALID", "Portable output requires no active operational transaction", [relativePath]);
  try {
    await assertSafePath(target, relativePath);
  } catch (error) {
    throw artifactError("ARTIFACT_PATH_INVALID", relativePath, error);
  }
  try {
    const artifactPath = ensureWithin(target, relativePath);
    assertSecretFree(value);
    const schema = await readSchema(schemaName, packageRoot);
    assertSchema(value, schema, relativePath);
    assertJsonLimits(value, relativePath);
    const serialized = `${JSON.stringify(value, null, 2)}\n`;
    assertJsonBytes(serialized, relativePath);
    await writeFileAtomic(artifactPath, serialized, { dryRun });
    return { path: relativePath, fingerprint: canonicalFingerprint(value), value };
  } catch (error) {
    throw artifactError(
      error.code === "JSON_LIMIT_EXCEEDED" ? error.code : "ARTIFACT_INVALID",
      relativePath,
      error,
    );
  }
}

export async function readPortableJsonArtifact(target, relativePath, schemaName, packageRoot = getPackageRoot()) {
  try {
    await assertSafePath(target, relativePath);
  } catch (error) {
    throw artifactError("ARTIFACT_PATH_INVALID", relativePath, error);
  }

  const artifactPath = ensureWithin(target, relativePath);
  if (!(await fileExists(artifactPath))) {
    throw new ArtifactError(
      "ARTIFACT_MISSING",
      `Artifact is missing: ${relativePath}`,
      [relativePath],
    );
  }

  try {
    const bytes = await readBytes(artifactPath);
    return await parseCapturedJsonArtifact(bytes, relativePath, schemaName, packageRoot);
  } catch (error) {
    throw artifactError(
      ["JSON_LIMIT_EXCEEDED", "ARTIFACT_PATH_INVALID"].includes(error.code)
        ? error.code
        : "ARTIFACT_INVALID",
      relativePath,
      error,
    );
  }
}

